insert into contabilidade.planocontadetalhe values (278, 2, '1.1.3.6.4.01.00.00.00.00', 'CONTRIBUIÇÕES DO RPPS A RECEBER', 'Registra os valores relativos aos créditos a receber, decorrentes das contribuições previdenciárias do RPPS.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (279, 2, '1.1.3.6.4.02.00.00.00.00', 'CRÉDITOS PREVIDENCIÁRIOS PARCELADOS', 'Registra os valores relativos aos créditos a receber, decorrentes de créditos previdenciários parcelados.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (280, 2, '1.1.3.6.4.03.01.00.00.00', 'CRÉDITOS DO RPPS JUNTO AO RPPS DE ESTADO', 'Registra os valores relativos aos créditos do RPPS a receber do RPPS de um estado decorrentes de compensação financeira entre regimes, por contagem recíproca de tempo de contribuição.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (281, 2, '1.1.3.6.4.03.02.00.00.00', 'CRÉDITOS DO RGPS JUNTO AO RPPS DE ESTADO', 'Registra os valores relativos aos créditos do RGPS a receber do RPPS de um estado decorrentes de compensação financeira entre regimes, por contagem recíproca de tempo de contribuição.', 1, true, 2, 'P');
