insert into contabilidade.planocontadetalhe values (283, 2, '1.1.3.6.4.99.02.00.00.00', 'OUTROS CRÉDITOS PREVIDENCIÁRIOS PARCELADOS', 'Registra os valores relativos a outros créditos previdenciários devidos ao RPPS pelo ente, sujeitos a pagamento parcelado.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (284, 2, '1.1.3.6.5.01.00.00.00.00', 'CONTRIBUIÇÕES DO RPPS A RECEBER', 'Registra os valores relativos aos créditos a receber, decorrentes das contribuições previdenciárias do RPPS.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (285, 2, '1.1.3.6.5.02.00.00.00.00', 'CRÉDITOS PREVIDENCIÁRIOS PARCELADOS', 'Registra os valores relativos aos créditos a receber, decorrentes de créditos previdenciários parcelados.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (286, 2, '1.1.3.6.5.03.01.00.00.00', 'CRÉDITOS DO RPPS JUNTO AO RPPS DE MUNICÍPIO', 'Registra os valores relativos aos créditos do RPPS a receber do RPPS de um município decorrentes de compensação financeira entre regimes, por contagem recíproca de tempo de contribuição.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (287, 2, '1.1.3.6.5.03.02.00.00.00', 'CRÉDITOS DO RGPS JUNTO AO RPPS DE MUNICÍPIO', 'Registra os valores relativos aos créditos do RGPS a receber do RPPS de um município decorrentes de compensação financeira entre regimes, por contagem recíproca de tempo de contribuição.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (288, 2, '1.1.3.6.5.99.01.00.00.00', 'OUTROS CRÉDITOS PREVIDENCIÁRIOS - NÃO PARCELADOS', 'Registra os valores relativos a outros créditos previdenciários devidos ao RPPS pelo ente, sujeitos a pagamento em parcela única.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (289, 2, '1.1.3.6.5.99.02.00.00.00', 'OUTROS CRÉDITOS PREVIDENCIÁRIOS PARCELADOS', 'Registra os valores relativos a outros créditos previdenciários devidos ao RPPS pelo ente, sujeitos a pagamento parcelado.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (290, 2, '1.1.3.8.1.01.00.00.00.00', 'ALUGUÉIS A RECEBER', 'Registra os valores a receber decorrentes de contratos de aluguel.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (291, 2, '1.1.3.8.1.02.00.00.00.00', 'CRÉDITOS A RECEBER DECORRENTES DE PERMISSÃO DE USO DE BENS PÚBLICOS', 'Registra os valores a receber decorrentes de permissão de uso de bens públicos.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (292, 2, '1.1.3.8.1.03.00.00.00.00', 'VALORES A RECUPERAR DECORRENTES DE INDENIZAÇÕES POR SINISTROS PAGOS', 'Registra os valores a recuperar referentes a indenizações pelo pagamento de sinistros.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (293, 2, '1.1.3.8.1.04.00.00.00.00', 'VALES, TICKETS E BILHETES', 'Registra o valor dos vales, tickets e bilhetes adquiridos para futura distribuição aos servidores.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (486, 2, '1.2.1.9.1.02.00.00.00.00', 'VPD FINANCEIRAS A APROPRIAR', 'Registra os valores pagos a título de VPD financeiras a apropriar.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (294, 2, '1.1.3.8.1.06.00.00.00.00', 'VALORES EM TRÂNSITO REALIZÁVEIS A CURTO PRAZO', 'Registra o somatório dos valores contabilizados indevidamente em conta bancária, guia de recebimento e ordens bancárias emitidas a compensar.', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (295, 2, '1.1.3.8.1.07.00.00.00.00', 'CRÉDITOS A RECEBER DECORRENTES DE INFRAÇÕES LEGAIS E CONTRATUAIS', 'Registra os recursos a receber provenientes da aplicação de autos de infração ou decorrentes de quebra de cláusulas contratuais. Os créditos decorrentes da quebra de cláusulas contratuais podem ser pagos em espécie, glosa ou através de fornecimentos.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (296, 2, '1.1.3.8.1.08.00.00.00.00', 'CRÉDITOS A RECEBER POR REEMBOLSO DE SALÁRIO FAMÍLIA PAGO', 'Registra os valores relativos ao salário-família, incluídos em folhas de pagamento, pagos aos empregados (CLT), com filhos menores, a compensar com as contribuições devidas pelo empregador a Previdência Social.', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (297, 2, '1.1.3.8.1.09.00.00.00.00', 'CRÉDITOS A RECEBER POR REEMBOLSO DE SALÁRIO MATERNIDADE PAGO', 'Registra os salários pagos as servidoras gestantes, regidas pela CLT no período que perdurar a licença maternidade, prevista em lei, a deduzir das obrigações sociais devidas pelos órgãos e entidades.', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (3303, 2, '8.1.1.1.1.01.06.00.00.00', 'HIPOTECAS EXECUTADAS', 'REGISTRA O VALOR RECEBIDO DAS GARANTIAS POR HIPOTECA NO PAÍS.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (298, 2, '1.1.3.8.1.10.00.00.00.00', 'AUXÍLIO NATALIDADE PAGO A RECUPERAR', 'Registra os valores relativos à auxilio natalidade, pagos aos empregados regidos pela CLT, quando do nascimento de filhos destes, a recuperar, por se tratar de obrigações da Previdência Social.', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (299, 2, '1.1.3.8.1.11.00.00.00.00', 'CRÉDITOS A RECEBER POR REEMBOLSO DE AUXÍLIO DOENÇA E ACIDENTES PAGOS', 'Registra os salários pagos aos servidores, regidos pela CLT, a título de auxilio doença/acidentes, previsto em lei, a serem reembolsados pelo INSS.', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (300, 2, '1.1.3.8.1.12.00.00.00.00', 'CRÉDITOS A RECEBER POR CESSÃO DE PESSOAL', 'Registra os valores de créditos a receber tais como: folha de pagamento, despesa de transporte, alimentação e outras relativas à cessão de pessoal.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (301, 2, '1.1.3.8.1.13.00.00.00.00', 'CRÉDITOS A RECEBER DECORRENTES DE CESSÃO DE ÁREAS PÚBLICAS', 'Registra os valores dos créditos a receber decorrentes da cessão de áreas públicas.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (302, 2, '1.1.3.8.1.14.00.00.00.00', 'CRÉDITOS A RECEBER DECORRENTES DE ALIENAÇÃO DE BENS MÓVEIS E IMÓVEIS', 'Registra os valores dos créditos a receber decorrentes da alienação de bens móveis ou imóveis.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (303, 2, '1.1.3.8.1.15.00.00.00.00', 'CRÉDITOS A RECEBER DECORRENTES DE PAGAMENTO DE DESPESA DE TERCEIROS', 'Registra os recursos a receber provenientes de pagamentos de despesas de terceiros decorrentes de cláusulas contratuais, tais como: água, luz, telefone, instalações, transporte e aluguéis.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (304, 2, '1.1.3.8.1.16.00.00.00.00', 'CRÉDITOS A RECEBER POR ACERTO FINANCEIRO COM SERVIDORES E EX-SERVIDORES', 'Registra os valores dos créditos a receber decorrentes de acertos financeiros com servidores e ex-servidores do órgão, conforme disposto na lei 8.112/90.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (305, 2, '1.1.3.8.1.17.00.00.00.00', 'CRÉDITOS A RECEBER DECORRENTES DE FOLHA DE PAGAMENTO', 'Registra os valores dos créditos a receber decorrentes de folha de pagamento.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (306, 2, '1.1.3.8.1.18.00.00.00.00', 'DIVIDENDOS PROPOSTOS A RECEBER', 'Registra os valores dos dividendos a que a empresa tenha direito, em função de participações em outras empresas, quando tais empresas já tenham registrado na demonstração de lucros ou prejuízos acumulados a parcela de Dividendos propostos a distribuir.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (307, 2, '1.1.3.8.1.20.00.00.00.00', 'REMUNERAÇÃO DE DEBÊNTURES A RECEBER', 'Registra os valores das remunerações de debêntures a receber.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (308, 2, '1.1.3.8.1.27.01.00.00.00', 'INSCRIÇÃO DE CERTIDÃO DE DECISÃO - TÍTULO EXECUTIVO DO TCE-RS', 'Registra os créditos de natureza não-tributária exigíveis a partir do recebimento, pela entidade, de certidão de decisão - título executivo, emitida pelo Tribunal de Contas do Estado com característica de liquidez e certeza, podendo ser, facultativamente inscrita como divida ativa não tributaria', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (309, 2, '1.1.3.8.1.28.00.00.00.00', 'CRÉDITOS A RECEBER DE ENTIDADES FEDERAIS', 'Registra os valores a receber a curto prazo, decorrentes de direitos junto a entidades federais.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (310, 2, '1.1.3.8.1.29.00.00.00.00', 'CRÉDITOS A RECEBER DE ENTIDADES ESTADUAIS, DISTRITAIS E MUNICIPAIS', 'Registra os valores a receber a curto prazo, decorrentes de direitos junto a estados, DF e municÍpios.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (311, 2, '1.1.3.8.1.31.00.00.00.00', 'CRÉDITOS A RECEBER DE PARCELAMENTOS', 'Registra o crédito de origem fiscal ou não, se autorizado o parcelamento, excluídos os créditos tributários e previdenciários.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (312, 2, '1.1.3.8.1.99.00.00.00.00', 'OUTROS CRÉDITOS A RECEBER E VALORES DE  CURTO PRAZO', 'Registra os valores de outros créditos a receber, para os quais não tenham contas especificas neste subgrupo de contas.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (313, 2, '1.1.4.1.1.01.00.00.00.00', 'TÍTULOS PÚBLICOS', 'Registra os valores relativos aos titulos públicos, emitidos e em circulacao, de posse da entidade pública.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (314, 2, '1.1.4.1.1.02.00.00.00.00', 'AÇÕES', 'Registra os valores das ações representativas das participações dos orgaos e entidades no capital das sociedades por ações havidas por aquisições, subscrições, bonificações e doações.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (315, 2, '1.1.4.1.1.03.00.00.00.00', 'DERIVATIVOS', 'Registra os créditos relativos a operações com derivativos.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (316, 2, '1.1.4.1.1.09.01.00.00.00', 'TÍTULOS DE RESPONSABILIDADE DO TESOURO', 'Registra os investimentos realizados pelo RPPS em títulos de emissão do Tesouro Nacional, efetuados em conformidade com as Resoluções CMN nº 3.922/2010 e nº 4.392/2014.', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (317, 2, '1.1.4.1.1.09.02.00.00.00', 'TÍTULOS DE RESPONSABILIDADE DO BANCO CENTRAL', 'Registra saldos remanescentes dos investimentos realizados pelo RPPS, em títulos de emissão do Banco Central do Brasil, considerando que este não emite mais títulos da Dívida Pública, conforme art. 34 da Lei Complementar nº 101/2000.', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (318, 2, '1.1.4.1.1.09.03.00.00.00', 'DEPÓSITOS DE POUPANÇA', 'Registra os investimentos realizados pelo RPPS em poupança e seus rendimentos (juros e atualização monetária) posteriores, em conformidade com as Resoluções CMN nº 3.922/2010 e nº 4.392/2014.', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (319, 2, '1.1.4.1.1.09.04.00.00.00', 'FUNDOS DE INVESTIMENTO EM RENDA FIXA OU REFERENCIADOS', 'Registra os investimentos realizados pelos RPPS em fundos de investimentos em renda fixa, efetuados em conformidade com a Resolução CMN nº 3.922/2010 (alterada pela Resolução CMN nº 4.392/2014), art. 7º, inciso IV.', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (320, 2, '1.1.4.1.1.09.05.00.00.00', 'FUNDOS DE INVESTIMENTO EM RENDA FIXA - CRÉDITO PRIVADO', 'Registra os investimentos realizados pelos RPPS em fundos de investimentos em renda fixa - crédito privado, efetuados em conformidade com as Resoluções CMN nº 3.922/2010 e nº 4.392/2014.', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (321, 2, '1.1.4.1.1.09.06.00.00.00', 'FUNDOS DE INVESTIMENTOS EM RENDA FIXA OU REFERENCIADOS - IMA/IDkA', 'Registra os investimentos realizados pelo RPPS em fundos de investimentos ou como referenciados em indicadores de desempenho de renda fixa, constituídos sob a forma de condomínio aberto e cuja política de investimento assuma o compromisso de buscar o retorno de um dos subíndices do Índice de Mercado Anbima (IMA) ou do Índice de Duração Constante Anbima (IDkA), efetuados em conformidade com as Resoluções CMN nº 3.922/2010 e nº 4.392/2014.', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (322, 2, '1.1.4.1.1.09.07.00.00.00', 'FUNDOS DE INVESTIMENTOS EM DIREITOS CREDITÓRIOS ', 'Registra os investimentos realizados pelo RPPS em fundos de investimentos em direito creditório, efetuados em conformidade com as Resoluções CMN nº 3.922/2010 e nº 4.392/2014.', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (323, 2, '1.1.4.1.1.09.08.00.00.00', 'FUNDOS DE INVESTIMENTOS EM TÍTULOS DO TESOURO', 'Registra os investimentos realizados pelo RPPS, em fundos de investimentos em títulos do tesouro, efetuados em conformidade com as Resoluções CMN nº 3.922/2010 e nº 4.392/2014.', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (324, 2, '1.1.4.1.1.09.09.00.00.00', 'OPERAÇÕES COMPROMISSADAS', 'Registra os investimentos realizados pelo RPPS, em operações compromissadas, efetuados em conformidade com as Resoluções CMN nº 3.922/2010 e nº 4.392/2014.', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (325, 2, '1.1.4.1.1.09.10.00.00.00', 'LETRAS IMOBILIÁRIAS GARANTIDAS', 'Registra os investimentos realizados pelo RPPS, em letras imobiliárias garantidas, efetuados em conformidade com a Resolução CMN nº 3.922/2010 (alterada pela Resolução CMN nº 4.392/2014), art 7º, inciso V, alínea "b".', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (326, 2, '1.1.4.1.1.10.01.00.00.00', 'FUNDOS DE INVESTIMENTOS REFERENCIADOS', 'Registra os investimentos realizados pelo RPPS em fundos de investimentos referenciados, renda variável, efetuados em conformidade com as Resoluções CMN nº 3.922/2010 e nº 4.392/2014.', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (327, 2, '1.1.4.1.1.10.02.00.00.00', 'FUNDOS DE INVESTIMENTO EM AÇÕES  ', 'Registra os investimentos realizados pelo RPPS em fundo de investimentos em ações, efetuados em conformidade com as Resoluções CMN nº 3.922/2010 e nº 4.392/2014.', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (328, 2, '1.1.4.1.1.10.03.00.00.00', 'FUNDOS DE INVESTIMENTO MULTIMERCADO ', 'Registra os investimentos realizados pelo RPPS em fundo de investimentos multimercado, efetuados em conformidade com as Resoluções CMN nº 3.922/2010 e nº 4.392/2014.', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (329, 2, '1.1.4.1.1.10.04.00.00.00', 'FUNDOS DE ÍNDICES REFERENCIADOS EM AÇÕES', 'Registra os investimentos realizados pelo RPPS em fundos de índices referenciados em ações, efetuados em conformidade com as Resoluções CMN nº 3.922/2010 e nº 4.392/2014.', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (330, 2, '1.1.4.1.1.10.05.00.00.00', 'FUNDOS DE INVESTIMENTOS EM PARTICIPAÇÕES', 'Registra os investimentos realizados pelo RPPS em fundos de investimentos em participações, efetuados em conformidade com as Resoluções CMN nº 3.922/2010 e nº 4.392/2014.', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (331, 2, '1.1.4.1.1.10.06.00.00.00', 'FUNDOS DE INVESTIMENTOS IMOBILIÁRIOS', 'Registra os investimentos realizados pelo RPPS em fundo de investimentos imobiliários, efetuados em conformidade com as Resoluções CMN nº 3.922/2010 e nº 4.392/2014.', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (332, 2, '1.1.4.1.1.11.01.00.00.00', 'FUNDOS DE INVESTIMENTO IMOBILIÁRIOS', 'Registra o somatório dos investimentos realizados pelo RPPS com recursos previdenciários em fundos de investimento imobiliários, efetuados em conformidade com as Resoluções CMN nº 3.922/2010 e nº 4.392/2014.', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (333, 2, '1.1.4.1.1.12.01.00.00.00', 'TÍTULOS E VALORES EM ENQUADRAMENTO', 'Registra os investimentos realizados pelo RPPS em desacordo com as regras estabelecidas pelas Resoluções CMN nº 3.922/2010 e nº 4.392/2014.', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (334, 2, '1.1.4.1.1.13.01.00.00.00', 'TÍTULOS E VALORES NÃO SUJEITOS AO ENQUADRAMENTO', 'Registra os investimentos realizados pelo RPPS em ativos não sujeitos as regras das Resoluções CMN nº 3.922/2010 e nº 4.392/2014.', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (335, 2, '1.1.4.1.1.14.01.00.00.00', 'APLICAÇÕES COM A TAXA DE ADMINISTRAÇÃO DO RPPS', 'Registra os investimentos realizados pelo RPPS com recursos da taxa de administração, sujeitos às regras das Resoluções CMN nº 3.922/2010 e nº 4.392/2014.', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (336, 2, '1.1.4.1.1.15.00.00.00.00', 'FUNDO DE APLICAÇÕES EM COTAS - RENDA VARIÁVEL', 'Registra os valores, realizáveis até 12 (doze) meses da data das demonstrações, aplicados em fundos de aplicações em cotas - renda variável.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (337, 2, '1.1.4.1.1.99.00.00.00.00', 'OUTROS TÍTULOS E VALORES MOBILIÁRIOS', 'Registra os valores, realizáveis até 12 (doze) meses da data das demonstrações, de outros títulos e valores mobiliários.', 1, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (338, 2, '1.1.5.1.1.01.00.00.00.00', 'MERCADORIAS PARA VENDA OU REVENDA', 'Registra o valor das mercadorias para venda ou revenda e doações relativas a estoques da entidade.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (339, 2, '1.1.5.1.1.02.00.00.00.00', 'MERCADORIAS ESTOQUES REGULATÓRIOS', 'Registra o valor das mercadorias adquiridas para revenda relativas a estoques públicos.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (340, 2, '1.1.5.1.1.99.00.00.00.00', 'OUTRAS MERCADORIAS PARA REVENDA', 'Registra o valor das demais mercadorias adquiridas para revenda.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (341, 2, '1.1.5.2.1.01.00.00.00.00', 'PRODUTOS ACABADOS', 'Registra o valor de produtos manufaturados já terminados, oriundos da própria produção da entidade e disponíveis para venda, estocados na fábrica, ou em depósitos, ou em filiais, ou ainda com terceiros em consignação.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (342, 2, '1.1.5.2.1.02.00.00.00.00', 'SERVIÇOS ACABADOS', 'Registra os valores pertinentes a serviços acabados que estão pendentes de faturamento ou de transferência para outras contas do ativo.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (343, 2, '1.1.5.3.1.01.00.00.00.00', 'PRODUTOS EM ELABORAÇÃO  ', 'Registra a totalidade das matérias-primas já requisitadas que estão em processo de transformação e o montante de custos diretos e indiretos relativos aos produtos em elaboração não concluídos na data do balanço patrimonial.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (344, 2, '1.1.5.3.1.02.00.00.00.00', 'SERVIÇOS EM ELABORAÇÃO', 'Registra os custos diretos e indiretos relativos aos serviços em elaboração não concluídos na data do balanço patrimonial.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (345, 2, '1.1.5.6.1.01.00.00.00.00', 'MATERIAL DE CONSUMO', 'Registra os valores dos materiais de consumo adquiridos e estocados em almoxarifados, destinados a atender ao consumo interno da unidade.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (346, 2, '1.1.5.6.1.02.00.00.00.00', 'GÊNEROS ALIMENTÍCIOS', 'Registra os valores dos gêneros alimentícios adquiridos e estocados em almoxarifados, destinados a atender ao consumo interno da unidade.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (347, 2, '1.1.5.6.1.03.00.00.00.00', 'MATERIAIS DE CONSTRUÇÃO', 'Registra os valores dos materiais de construção adquiridos e estocados em almoxarifados, destinados a atender ao consumo interno da unidade.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (348, 2, '1.1.5.6.1.04.00.00.00.00', 'AUTOPEÇAS', 'Registra os valores de autopeças adquiridas e estocadas em almoxarifados, destinadas a atender ao consumo interno da unidade.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (349, 2, '1.1.5.6.1.05.00.00.00.00', 'MEDICAMENTOS E MATERIAIS HOSPITALARES', 'Registra os valores dos medicamentos e materias hospitalares adquiridos e estocados em almoxarifados, destinados a atender ao consumo interno da unidade.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (350, 2, '1.1.5.6.1.06.00.00.00.00', 'MATERIAIS GRÁFICOS', 'Registra os valores dos materiais gráficos adquiridos e estocados em almoxarifados, destinados a atender ao consumo interno da unidade.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (351, 2, '1.1.5.6.1.07.00.00.00.00', 'MATERIAL DE EXPEDIENTE', 'Registra os valores dos materiais de expediente adquiridos e estocados em almoxarifados, destinados a atender ao consumo interno da unidade.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (352, 2, '1.1.5.6.1.08.00.00.00.00', 'MATERIAIS A CLASSIFICAR', 'Registra os valores dos materiais estocados pendentes de classificação e identificação.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (353, 2, '1.1.5.6.1.09.00.00.00.00', 'ESTOQUE SOBRESSALENTES A ALIENAR', 'Registra os valores de bens sobressalentes que estejam disponíveis para alienação sob diversas formas (venda, leilão, etc)', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (499, 2, '1.2.2.1.1.01.07.00.00.00', 'PARTICIPAÇÃO EM CONSÓRCIOS PÚBLICOS ', 'Registra as participações permanentes do ente em consórcios públicos, avaliadas por equivalência patrimonial.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (354, 2, '1.1.5.8.1.01.00.00.00.00', 'ESTOQUE PARA DOAÇÃO OU PERMUTA', 'Registra o valor dos bens adquiridos, produzidos ou em processo de elaboração pela entidade com o objetivo de doação ou permuta no Programa Troca-troca do Governo do Estado do RS ou similares. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (355, 2, '1.2.1.1.1.01.01.00.00.00', 'IMPOSTOS', 'Registra os créditos tributários a receber provenientes de impostos.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (356, 2, '1.2.1.1.1.01.02.00.00.00', 'TAXAS', 'Registra os créditos tributários a receber provenientes de taxas.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (357, 2, '1.2.1.1.1.01.03.00.00.00', 'CONTRIBUIÇÕES DE MELHORIA', 'Registra os créditos tributários a receber provenientes de contribuições de melhoria.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (358, 2, '1.2.1.1.1.01.04.00.00.00', 'DEMAIS CONTRIBUIÇÕES', 'Registra os créditos tributários a receber provenientes de contribuições especiais, exceto contribuições previdenciárias.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (359, 2, '1.2.1.1.1.01.05.00.00.00', 'CONTRIBUIÇÕES PREVIDENCIÁRIAS DO RGPS A RECEBER', 'Registra os créditos tributários a receber provenientes de contribuições previdenciárias do RGPS.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (360, 2, '1.2.1.1.1.01.70.00.00.00', 'CRÉDITOS TRIBUTÁRIOS PARCELADOS', 'Registra os valores relativos aos créditos a receber, decorrentes de créditos tributários parcelados, exceto créditos previdenciários.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (361, 2, '1.2.1.1.1.01.71.00.00.00', 'CRÉDITOS PREVIDENCIÁRIOS PARCELADOS', 'Registra os valores relativos aos créditosa receber, decorrentes de créditos previdenciários parcelados.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (362, 2, '1.2.1.1.1.02.01.00.00.00', 'FATURAS/DUPLICATAS A RECEBER ', 'Registra os valores provenientes dos faturamentos da venda de mercadorias/produtos e serviços do estoque da entidade.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (363, 2, '1.2.1.1.1.03.01.00.00.00', 'EMPRÉSTIMOS CONCEDIDOS A RECEBER ', 'Registra os valores dos créditos por empréstimos concedidos pelo Ente, por autorização legal ou vinculação a contrato ou acordo, com vencimento a longo prazo.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (364, 2, '1.2.1.1.1.03.02.00.00.00', 'FINANCIAMENTOS CONCEDIDOS A RECEBER', 'Registra os valores dos créditos por financiamentos concedidos pelo Ente, por autorização legal ou vinculação a contrato ou acordo, com vencimento a longo prazo.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (365, 2, '1.2.1.1.1.03.03.00.00.00', 'EMPRÉSTIMOS A RECEBER - RPPS', 'Registra os créditos a receber provenientes de empréstimos concedidos por meio de recursos previdenciários.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (366, 2, '1.2.1.1.1.04.01.01.01.00', 'COBRANÇA ADMINISTRATIVA', 'Registra os valores relativos a créditos inscritos de Dívida Ativa do imposto sobre renda e proventos de qualquer natureza, em cobrança administrativa.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (367, 2, '1.2.1.1.1.04.01.01.02.00', 'COBRANÇA JUDICIAL', 'Registra os valores relativos a créditos inscritos de Dívida Ativa do imposto sobre renda e proventos de qualquer natureza, em cobrança judicial.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (368, 2, '1.2.1.1.1.04.01.05.01.00', 'COBRANÇA ADMINISTRATIVA', 'Registra os valores relativos a créditos inscritos de Dívida Ativa do iptu, em cobrança administrativa.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (369, 2, '1.2.1.1.1.04.01.05.02.00', 'COBRANÇA JUDICIAL', 'Registra os valores relativos a créditos inscritos de Dívida Ativa do iptu, em cobrança judicial.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (370, 2, '1.2.1.1.1.04.01.06.01.00', 'COBRANÇA ADMINISTRATIVA', 'Registra os valores relativos a créditos inscritos de Dívida Ativa do itbi, em cobrança administrativa.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (371, 2, '1.2.1.1.1.04.01.06.02.00', 'COBRANÇA JUDICIAL', 'Registra os valores relativos a créditos inscritos de Dívida Ativa do itbi, em cobrança judicial.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (372, 2, '1.2.1.1.1.04.01.07.01.00', 'COBRANÇA ADMINISTRATIVA', 'Registra os valores relativos a créditos inscritos de Dívida Ativa do iss, em cobrança administrativa.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (373, 2, '1.2.1.1.1.04.01.07.02.00', 'COBRANÇA JUDICIAL', 'Registra os valores relativos a créditos inscritos de Dívida Ativa do iss, em cobrança judicial.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (374, 2, '1.2.1.1.1.04.01.08.01.00', 'COBRANÇA ADMINISTRATIVA', 'Registra os valores relativos a créditos inscritos de Dívida Ativa do itr, em cobrança administrativa.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (375, 2, '1.2.1.1.1.04.01.08.02.00', 'COBRANÇA JUDICIAL', 'Registra os valores relativos a créditos inscritos de Dívida Ativa do itr, em cobrança judicial.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (376, 2, '1.2.1.1.1.04.01.09.00.00', 'DÍVIDA ATIVA DAS TAXAS', 'Registra os valores relativos a créditos inscritos de Dívida Ativa tributária de Taxas.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (377, 2, '1.2.1.1.1.04.02.00.00.00', 'CRÉDITOS PREVIDENCIÁRIOS INSCRITOS', 'Registra os valores relativos a créditos inscritos de Dívida Ativa tributária previdenciária, excluídos valores devidos pelo ente público. Estão incluídos, por exemplo, valores devidos por servidor em gozo de licença para tratamento de interesses particulares, entre outros.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (403, 2, '1.2.1.1.4.05.00.00.00.00', 'DÍVIDA ATIVA NÃO TRIBUTÁRIA ', 'Registra os valores dos créditos de dívida ativa não tributária inscritos, realizáveis no longo prazo.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (378, 2, '1.2.1.1.1.05.30.00.00.00', 'INSCRIÇÃO DE CERTIDÃO DE DECISÃO - TÍTULO EXECUTIVO DO TCE/RS', 'Registra os créditos de natureza não-tributária exigíveis a partir do recebimento, pela entidade, de certidão de decisão - título executivo, emitida pelo Tribunal de Contas do Estado com característica de liquidez e certeza, podendo ser, facultativamente inscrita como divida ativa não tributaria', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (379, 2, '1.2.1.1.2.01.00.00.00.00', 'CRÉDITOS TRIBUTÁRIOS A RECEBER', 'Registra os valores relativos a créditos a receber com vencimento após 12 (doze) meses da data das demonstrações, oriundos das variações patrimoniais aumentativas tributárias. Os tributos são: impostos, taxas, contribuições de melhoria, contribuições e empréstimos compulsórios.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (380, 2, '1.2.1.1.2.02.00.00.00.00', 'CLIENTES', 'Registra os valores das faturas/duplicatas a receber decorrentes das vendas a prazo de mercadorias ou serviços que ocorrem no curso normal das operações da entidade (com vencimento após 12 (doze) meses da data das demonstrações), representando um direito a cobrar de seus clientes.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (381, 2, '1.2.1.1.2.03.00.00.00.00', 'EMPRÉSTIMOS E FINANCIAMENTOS CONCEDIDOS', 'Registra o somatório dos valores de empréstimos e financiamentos concedidos por autorizações legais ou vinculações a contratos e acordos.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (382, 2, '1.2.1.1.2.04.00.00.00.00', 'DÍVIDA ATIVA TRIBUTÁRIA', 'Registra os valores dos créditos de dívida ativa tributária inscritos, realizáveis após os doze meses seguintes a data de publicação dos demonstrativos contábeis.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (383, 2, '1.2.1.1.2.05.00.00.00.00', 'DÍVIDA ATIVA NÃO TRIBUTÁRIA', 'Registra os valores dos créditos de dívida ativa não tributária inscritos, realizáveis no longo prazo.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (413, 2, '1.2.1.1.5.03.09.00.00.00', 'PROGRAMA DE REESTRUTURAÇÃO FISCAL DOS MUNICÍPIOS - CRÉDITOS A RECEBER', 'Registra os valores a receber decorrentes da assunção e refinanciamento, pela União, de dívidas de responsabilidade dos Municípios, nos termos da MP nº 2.185-35, de 24 de agosto de 2001.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (384, 2, '1.2.1.1.3.01.00.00.00.00', 'CRÉDITOS TRIBUTÁRIOS A RECEBER', 'Registra os valores relativos a créditos a receber com vencimento após 12 (doze) meses da data das demonstrações, oriundos da variação patrimonial aumentativa tributárias. Os tributos são: impostos, taxas, contribuições de melhoria, contribuições e empréstimos compulsório.', 1, true, 2, 'P');
