insert into contabilidade.planocontadetalhe values (386, 2, '1.2.1.1.3.03.00.00.00.00', 'EMPRÉSTIMOS E FINANCIAMENTOS CONCEDIDOS', 'Registra o somatório dos valores de empréstimos e financiamentos concedidos por autorizações legais ou vinculações a contratos e acordos.', 1, true, 2, 'P');
