insert into contabilidade.planocontadetalhe values (388, 2, '1.2.1.1.3.05.00.00.00.00', 'DÍVIDA ATIVA NÃO TRIBUTÁRIA', 'Registra os valores dos créditos de dívida ativa não tributária inscritos, realizáveis no longo prazo.', 1, true, 2, 'P');
