insert into contabilidade.planocontadetalhe values (508, 2, '1.2.2.1.1.02.05.00.00.00', 'PARTICIPAÇÕES EM ORGANISMOS INTERNACIONAIS', 'Registra as participações permanentes da unidade em outras sociedades em forma de ações ou cotas, avaliadas pelo método de custo - Participação em Organismos Internacionais.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (509, 2, '1.2.2.1.1.02.06.00.00.00', 'ADIANTAMENTO PARA AUMENTO DE CAPITAL', 'Registra as participações permanentes da unidade em outras sociedades em forma de ações ou cotas, avaliadas pelo método de custo - Adiantamento para aumento de Capital.', 1, true, 2, 'P');
