insert into contabilidade.planocontadetalhe values (523, 2, '1.2.2.1.2.02.01.00.00.00', 'PARTICIPAÇÕES EM OUTRAS SOCIEDADES', 'Registra as participações permanentes do ente em outras sociedades em forma de ações ou cotas, avaliadas pelo custo.', 1, true, 2, 'P');
