insert into contabilidade.planocontadetalhe values (527, 2, '1.2.2.1.2.02.99.00.00.00', 'OUTRAS PARTICIPAÇÕES', 'Registra as participações permanentes da unidade em outras sociedades em forma de ações ou cotas, avaliadas pelo método de custo - Outras Participações.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (528, 2, '1.2.2.2.1.99.00.00.00.00', 'OUTRAS PROPRIEDADES PARA INVESTIMENTOS', 'Registra as outras propriedades para investimentos não abrangidas nas contas anteriores, avaliadas pelo método do custo.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (529, 2, '1.2.2.3.1.01.01.00.00.00', 'TÍTULOS E VALORES EM ENQUADRAMENTO', 'Registra os títulos e valores recebidos pelo Regime Próprio da Previdência Social, que se encontram em enquadramento.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (530, 2, '1.2.2.3.1.01.02.00.00.00', 'TÍTULOS E VALORES NÃO SUJEITOS À RESOLUÇÃO DO CMN', 'Registra títulos e valores recebidos pelo Regime Próprio da Previdência Social não sujeitos a enquadramento.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (531, 2, '1.2.2.7.1.01.00.00.00.00', 'OBRAS DE ARTE E OUTROS BENS SINGULARES', 'Registra os valores provenientes de Obras de Arte e outros bens singulares, tais como jóias, antiguidades, moedas sem valor liberatório e etc.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (532, 2, '1.2.2.7.1.02.00.00.00.00', 'TÍTULOS E VALORES MOBILIÁRIOS PERMANENTE', 'Registra o valor dos Títulos e Valores Mobiliários não classificáveis no Ativo Circulante nem no Ativo Realizável a Longo Prazo, com por exemplo as Debêntures (Perpetuas).', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (533, 2, '1.2.2.7.1.03.00.00.00.00', 'BENS MÓVEIS NÃO DESTINADOS A USO', 'Registra os valores de Bens Moveis da Unidade mantidos para geração de renda.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (534, 2, '1.2.2.7.1.04.00.00.00.00', 'BENS INTANGÍVEIS NÃO DESTINADOS A USO', 'Registra o valor de Bens Intangíveis não destinados ao uso e que a Unidade não explore comercialmente.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (535, 2, '1.2.2.7.1.99.00.00.00.00', 'DEMAIS INVESTIMENTOS PERMANENTES', 'Registra o valor de Investimentos Permanentes, não classificáveis nas demais contas deste Plano.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (536, 2, '1.2.3.1.1.06.00.00.00.00', 'PEÇAS E CONJUNTOS DE REPOSIÇÃO', 'Registra o valor da aquisição ou incorporação de peças e conjuntos de reposição destinados a substituição em máquinas e equipamentos, aeronaves e embarcações, bens de segurança e socorro, entre outros.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (537, 2, '1.2.3.1.1.09.00.00.00.00', 'ARMAMENTOS', 'Registra os valores de armas que constituem objetos de defesa ou preparativos de guerra.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (538, 2, '1.2.3.1.1.10.00.00.00.00', 'SEMOVENTES', 'Registra os valores relativos aos animais destinados a produção, reprodução, engorda e aos serviços utilitários em geral.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (539, 2, '1.2.3.1.1.99.01.00.00.00', 'BENS MÓVEIS A ALIENAR', 'Representa os registros dos valores relativos aos bens móveis que, por algum motivo, foram destinados a alienação, mediante venda, permuta ou doação.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (540, 2, '1.2.3.1.1.99.02.00.00.00', 'BENS EM PODER DE OUTRA UNIDADE OU TERCEIROS ', 'Registra os valores de bens móveis de propriedade da unidade cedente, entregues a outra unidade ou terceiros por meio de convênio, comodato ou outras formas de empréstimo, distribuição ou transferência.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (541, 2, '1.2.3.1.1.99.08.00.00.00', 'BENS MÓVEIS A CLASSIFICAR', 'Registra os bens móveis pendentes de classificação e de identificação.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (542, 2, '1.2.3.1.1.99.99.00.00.00', 'OUTROS BENS MÓVEIS', 'Registra o valor da aquisição ou incorporação dos outros bens móveis não podem classificados nas contas anteriores.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (543, 2, '1.2.3.2.1.01.01.00.00.00', 'IMÓVEIS RESIDENCIAIS', 'Registra os valores relativos aos imóveis residenciais dos estados ou municípios, como apartamentos; casas; residenciais; conjuntos. Os imóveis funcionais, os próprios residenciais e as vilas militares devem ser registrados nessa conta.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (544, 2, '1.2.3.2.1.01.02.00.00.00', 'IMÓVEIS COMERCIAIS', 'Registra os valores relativos aos imóveis comerciais dos estados ou municípios, como conjuntos; salas; e lojas.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (545, 2, '1.2.3.2.1.01.03.00.00.00', 'EDIFÍCIOS', 'Registra os valores relativos aos seguintes imóveis dos estados ou municípios nas seguintes categorias: edifícios, prédios; conventos.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (546, 2, '1.2.3.2.1.01.04.00.00.00', 'TERRENOS/GLEBAS', 'Registra os valores relativos aos seguintes imóveis dos estados e municípios nas seguintes categorias: terrenos e glebas.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (547, 2, '1.2.3.2.1.01.05.00.00.00', 'ARMAZÉNS/GALPÕES', 'Registra os valores relativos aos seguintes imóveis dos estados e municípios nas seguintes categorias: armazéns e galpões.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (548, 2, '1.2.3.2.1.01.07.00.00.00', 'AEROPORTOS/ESTAÇÕES/AERÓDROMOS', 'Registra os valores relativos aos seguintes imóveis dos estados e municípios nas seguintes categorias: aeródromo; aeroporto; estação.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (549, 2, '1.2.3.2.1.01.08.00.00.00', 'IMÓVEIS DE USO EDUCACIONAL', 'Registra os valores relativos aos seguintes imóveis dos estados e municípios nas seguintes categorias: escolas; faculdades; universidades; bibliotecas.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (550, 2, '1.2.3.2.1.01.09.00.00.00', 'REPRESAS/AÇUDES', 'Registra os valores relativos aos seguintes imóveis dos estados e municípios nas seguintes categorias: açudes; represas.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (551, 2, '1.2.3.2.1.01.10.00.00.00', 'FAZENDAS, PARQUES E RESERVAS', 'Registra os valores relativos aos seguintes imóveis dos estados e municípios nas seguintes categorias: fazendas; parques; reservas.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (552, 2, '1.2.3.2.1.01.11.00.00.00', 'IMÓVEIS DE USO RECREATIVO', 'Registra os valores relativos aos seguintes imóveis dos estados e municípios que se enquadrem nas seguintes categorias: clubes; estádios; teatros.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (553, 2, '1.2.3.2.1.01.12.00.00.00', 'FARÓIS', 'Registra os valores relativos aos seguintes imóveis dos estados e municípios que se enquadrem na seguinte categoria: faróis (faroletes). Os instrumentos de auxílio a navegação aérea também devem ser registrados nesta conta.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (554, 2, '1.2.3.2.1.01.13.00.00.00', 'MUSEUS/PALÁCIOS', 'Registra os valores relativos aos seguintes imóveis dos estados e municípios: museus; palácios.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (555, 2, '1.2.3.2.1.01.14.00.00.00', 'LABORATÓRIOS/OBSERVATÓRIOS', 'Registra os valores relativos aos seguintes imóveis dos estados e municípios que se enquadrem nas seguintes categorias: laboratórios; observatórios.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (556, 2, '1.2.3.2.1.01.15.00.00.00', 'HOSPITAIS E UNIDADES DE SAÚDE', 'Registra os valores relativos aos seguintes imóveis dos estados e municípios que se enquadrem na seguinte categoria: hospitais e unidades de saúde.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (557, 2, '1.2.3.2.1.01.16.00.00.00', 'HOTÉIS', 'Registra os valores relativos aos seguintes imóveis dos estados e municípios que se enquadrem na seguinte categoria: hotéis.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (558, 2, '1.2.3.2.1.01.17.00.00.00', 'PRESÍDIOS/DELEGACIAS', 'Registra os valores relativos aos seguintes imóveis dos estados e municípios: presídios; delegacias.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (559, 2, '1.2.3.2.1.01.18.00.00.00', 'PORTOS/ESTALEIROS', 'Registra os valores relativos aos seguintes imóveis dos estados e municípios: estaleiros; portos.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (560, 2, '1.2.3.2.1.01.19.00.00.00', 'COMPLEXOS/FÁBRICAS/USINAS', 'Registra os valores relativos aos seguintes imóveis dos estados e municípios: fábricas; usinas; complexos.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (561, 2, '1.2.3.2.1.01.20.00.00.00', 'CEMITÉRIOS', 'Registra os valores relativos aos seguintes imóveis dos estados e municípios: cemitérios.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (624, 2, '2.2.2.9.1.02.00.00.00.00', '(-) ENCARGOS PREFIXADOS DE FINANCIAMENTOS EXTERNOS', 'Registra o valor dos encargos financeiros pré-estabelecidos em valores prefixados, referentes a financiamentos externos.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (562, 2, '1.2.3.2.1.01.21.00.00.00', 'ESTACIONAMENTOS E GARAGENS', 'Registra os valores relativos aos seguintes imóveis dos estados e municípios que se enquadrem na seguinte categoria: estacionamentos. Também devem ser registrados nesta conta as garagens.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (563, 2, '1.2.3.2.1.01.22.00.00.00', 'POSTOS DE FISCALIZAÇÃO', 'Registra os valores relativos aos seguintes imóveis dos estados e municípios: postos policiais. Também devem ser registrados nessa conta os demais postos de fiscalização.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (564, 2, '1.2.3.2.1.01.98.00.00.00', 'OUTROS BENS IMÓVEIS DE USO ESPECIAL', 'Registra os valores relativos aos seguintes imóveis dos estados e municípios que não se enquadrem em nenhuma outra categoria.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (565, 2, '1.2.3.2.1.04.01.00.00.00', 'EDIFÍCIOS', 'Registra os valores patrimoniais relativos aos imóveis dominicais união, estados e municípios que se enquadrem nas seguintes categorias: edifícios; prédios; conventos.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (566, 2, '1.2.3.2.1.04.02.00.00.00', 'APARTAMENTOS', 'Registra os valores patrimoniais relativos aos imóveis dominicais união, estados e municípios que se enquadrem na seguinte categoria: apartamentos.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (567, 2, '1.2.3.2.1.04.03.00.00.00', 'ARMAZÉNS ', 'Registra os valores patrimoniais relativos aos imóveis dominicais união, estados e municípios que se enquadrem na seguinte categoria: armazéns.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (568, 2, '1.2.3.2.1.04.04.00.00.00', 'CASAS', 'Registra os valores patrimoniais relativos aos imóveis dominicais união, estados e municípios que se enquadrem na seguinte categoria: casas.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (569, 2, '1.2.3.2.1.04.05.00.00.00', 'CEMITÉRIOS', 'Registra os valores patrimoniais relativos aos imóveis dominicais união, estados e municípios que se enquadrem na seguinte categoria: cemitérios.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (570, 2, '1.2.3.2.1.04.06.00.00.00', 'EDIFÍCIOS', 'Registra os valores patrimoniais relativos aos imóveis dominicais união, estados e municípios que se enquadrem na seguinte categoria: edifícios.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (571, 2, '1.2.3.2.1.04.07.00.00.00', 'GARAGENS E ESTACIONAMENTOS', 'Registra os valores patrimoniais relativos aos imóveis dominicais união, estados e municípios que se enquadrem na seguinte categoria: garagens e estacionamentos.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (572, 2, '1.2.3.2.1.04.08.00.00.00', 'FAZENDAS ', 'Registra os valores patrimoniais relativos aos imóveis dominicais união, estados e municípios que se enquadrem na seguinte categoria: fazendas.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (573, 2, '1.2.3.2.1.04.09.00.00.00', 'GALPÕES', 'Registra os valores patrimoniais relativos aos imóveis dominicais união, estados e municípios que se enquadrem na seguinte categoria: galpões.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (574, 2, '1.2.3.2.1.04.10.00.00.00', 'GLEBAS', 'Registra os valores patrimoniais relativos aos imóveis dominicais união, estados e municípios que se enquadrem na seguinte categoria: glebas.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (575, 2, '1.2.3.2.1.04.11.00.00.00', 'LOJAS ', 'Registra os valores patrimoniais relativos aos imóveis dominicais união, estados e municípios que se enquadrem na seguinte categoria: lojas.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (576, 2, '1.2.3.2.1.04.12.00.00.00', 'SALAS', 'Registra os valores patrimoniais relativos aos imóveis dominicais união, estados e municípios que se enquadrem na seguinte categoria: salas.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (577, 2, '1.2.3.2.1.04.13.00.00.00', 'TERRENOS ', 'Registra os valores patrimoniais relativos aos imóveis dominicais união, estados e municípios que se enquadrem na seguinte categoria: terrenos.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (578, 2, '1.2.3.2.1.04.14.00.00.00', 'LOTES', 'Registra os valores patrimoniais relativos aos imóveis dominicais união, estados e municípios que se enquadrem na seguinte categoria: lotes.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (579, 2, '1.2.3.2.1.04.15.00.00.00', 'LOTES INDUSTRIAIS', 'Registra os valores patrimoniais relativos aos imóveis dominicais união, estados e municípios que se enquadrem na seguinte categoria: lotes industriais.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (580, 2, '1.2.3.2.1.04.16.00.00.00', 'GLEBAS URBANAS', 'Registra os valores patrimoniais relativos aos imóveis dominicais união, estados e municípios que se enquadrem na seguinte categoria: glebas urbanas.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (581, 2, '1.2.3.2.1.04.17.00.00.00', 'GLEBAS URBANIZADAS', 'Registra os valores patrimoniais relativos aos imóveis dominicais união, estados e municípios que se enquadrem na seguinte categoria: glebas urbanizadas.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (582, 2, '1.2.3.2.1.04.18.00.00.00', 'GLEBAS RURAIS', 'Registra os valores patrimoniais relativos aos imóveis dominicais união, estados e municípios que se enquadrem na seguinte categoria: glebas rurais.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (583, 2, '1.2.3.2.1.04.99.00.00.00', 'OUTROS BENS DOMINICAIS', 'Registra os valores patrimoniais relativos aos imóveis dominicais união, estados e municípios que não se enquadrem em outras categorias.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (584, 2, '1.2.3.2.1.05.01.00.00.00', 'RUAS', 'Registra os valores de ruas que foram construídas utilizando-se recursos públicos e que estejam sob controle ou administração da unidade.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (585, 2, '1.2.3.2.1.05.02.00.00.00', 'PRAÇAS', 'Registra os valores de praças que foram construídas utilizando-se recursos públicos e que estejam sob controle ou administração da unidade.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (586, 2, '1.2.3.2.1.05.03.00.00.00', 'ESTRADAS', 'Registra os valores de estradas que foram construídas utilizando-se recursos públicos e que estejam sob controle ou administração da unidade.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (587, 2, '1.2.3.2.1.05.04.00.00.00', 'PONTES', 'Registra os valores de pontes que foram construídos utilizando-se recursos públicos e que estejam sob controle ou administração da unidade.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (588, 2, '1.2.3.2.1.05.05.00.00.00', 'VIADUTOS', 'Registra os valores de viadutos que foram construídos utilizando-se recursos públicos e que estejam sob controle ou administração da unidade.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (589, 2, '1.2.3.2.1.05.06.00.00.00', 'SISTEMAS DE ESGOTO E/OU DE ABASTECIMENTO DE ÁGUA', 'Registra os valores de SISTEMAS DE ESGOTO E/OU DE ABASTECIMENTO DE ÁGUA que foram construídos utilizando-se recursos públicos e que estejam sob controle ou administração da unidade.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (590, 2, '1.2.3.2.1.05.07.00.00.00', 'SISTEMAS DE ABASTECIMENTO DE ENERGIA', 'Registra os valores de sistemas de abastecimento de energia que foram construídos utilizando-se recursos públicos e que estejam sob controle ou administração da unidade.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (591, 2, '1.2.3.2.1.05.08.00.00.00', 'REDES DE TELECOMUNICAÇÕES', 'Registra os valores de REDES DE TELECOMUNICAÇÕES que foram construídos utilizando-se recursos públicos e que estejam sob controle ou administração da unidade.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (592, 2, '1.2.3.2.1.05.09.00.00.00', 'BENS DO PATRIMONIO CULTURAL', 'Bens com significancia histórica, cultural ou ambiental tais como monumentos e prédios históricos, sítios arqueológicos, área de conservação e reservas naturais e obras de arte, quando passíveis de mensuração e avaliação.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (593, 2, '1.2.3.2.1.05.99.00.00.00', 'OUTROS BENS DE USO COMUM DO POVO', 'Registra os valores bens de uso comum, não classificados anteriormente neste plano de contas, que foram adquiridos, produzidos ou construídos utilizando-se recursos públicos e que estejam sob controle ou administração da unidade.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (594, 2, '1.2.3.2.1.07.00.00.00.00', 'INSTALAÇÕES', 'Registra equipamentos, materiais e custo de implantação de instalações que, não obstante integradas aos edifícios, devem ser segregadas das obras civis, como, por exemplo, as instalações elétricas, hidráulicas, sanitárias, de vapor, de ar comprimido, frigoríficas, contra incêndio, de comunicações, de climatização, para combustíveis, gases, de antipoluição, para cozinha, dentre outros. E também aplicável a construção de trechos ferroviários.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (595, 2, '1.2.3.2.1.08.00.00.00.00', 'BENFEITORIAS EM PROPRIEDADE DE TERCEIROS', 'Registra construções em terrenos arrendados de terceiros e instalações e outras benfeitorias em prédios alugados. São considerados somente os gastos com construção e instalação que se incorporam ao imóvel e revertem ao proprietário do imóvel ao final da locação.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (596, 2, '1.2.3.2.1.99.01.00.00.00', 'BENS IMÓVEIS LOCADOS PARA TERCEIROS', 'Registra os bens imóveis locados para terceiros.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (597, 2, '1.2.3.2.1.99.02.00.00.00', 'IMÓVEIS EM PODER DE TERCEIROS', 'Registra os imóveis concedidos a terceiros a título de empréstimo gratuito com prazo de devolução convencionado.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (598, 2, '1.2.3.2.1.99.03.00.00.00', 'MATERIAIS TEMPORARIAMENTE SEPARADOS DE IMÓVEIS ', 'Registra os materiais provisoriamente separados de um imóvel, para nele se reempregarem.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (599, 2, '1.2.3.2.1.99.05.00.00.00', 'BENS IMÓVEIS A CLASSIFICAR', 'Registra os bens imóveis, cuja classificação esteja pendente por algum motivo, geralmente por falta de identificação ou pendência de legalização ou registro.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (600, 2, '1.2.3.2.1.99.06.00.00.00', 'BENS IMÓVEIS A ALIENAR', 'Registra os valores relativos aos bens imóveis separados para alienação, quando considerados desnecessários, inservíveis ou por decisão administrativa da unidade.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (601, 2, '1.2.3.2.1.99.99.00.00.00', 'OUTROS BENS IMÓVEIS', 'Registra os valores relativos a outros bens imóveis, para os quais não tenham sido criadas contas próprias ou específicas neste plano de contas.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (602, 2, '2.1.2.1.1.01.02.00.00.00', '(-) DESÁGIO DE TÍTULOS', 'Registra os valores relativos a deságio ocorridos em títulos.', 1, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (603, 2, '2.1.2.1.3.01.02.00.00.00', '(-) DESÁGIO DE TÍTULOS', 'Registra os valores relativos a deságio ocorridos em títulos.', 1, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (604, 2, '2.1.2.1.4.01.02.00.00.00', '(-) DESÁGIO DE TÍTULOS', 'Registra os valores relativos a deságio ocorridos em títulos.', 1, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (605, 2, '2.1.2.1.5.01.02.00.00.00', '(-) DESÁGIO DE TÍTULOS', 'Registra os valores relativos a deságio ocorridos em títulos.', 1, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (606, 2, '2.1.2.8.1.01.00.00.00.00', '(-) ENCARGOS PREFIXADOS DE EMPRÉSTIMOS INTERNOS', 'Registra o valor dos encargos financeiros pré-estabelecidos em valores prefixados, referentes a empréstimos internos.', 1, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (607, 2, '2.1.2.8.1.02.00.00.00.00', '(-) ENCARGOS PREFIXADOS DE FINANCIAMENTOS INTERNOS', 'Registra o valor dos encargos financeiros pré-estabelecidos em valores prefixados, referentes a financiamentos internos.', 1, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (608, 2, '2.1.2.8.3.01.00.00.00.00', '(-) ENCARGOS PREFIXADOS DE EMPRÉSTIMOS INTERNOS', 'Registra o valor dos encargos financeiros pré-estabelecidos em valores prefixados, referentes a empréstimos internos.', 1, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (609, 2, '2.1.2.8.3.02.00.00.00.00', '(-) ENCARGOS PREFIXADOS DE FINANCIAMENTOS INTERNOS', 'Registra o valor dos encargos financeiros pré-estabelecidos em valores prefixados, referentes a financiamentos internos.', 1, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (610, 2, '2.1.2.8.4.01.00.00.00.00', '(-) ENCARGOS PREFIXADOS DE EMPRÉSTIMOS INTERNOS', 'Registra o valor dos encargos financeiros pré-estabelecidos em valores prefixados, referentes a empréstimos internos.', 1, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (611, 2, '2.1.2.8.4.02.00.00.00.00', '(-) ENCARGOS PREFIXADOS DE FINANCIAMENTOS INTERNOS', 'Registra o valor dos encargos financeiros pré-estabelecidos em valores prefixados, referentes a financiamentos internos.', 1, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (612, 2, '2.1.2.9.1.01.00.00.00.00', '(-) ENCARGOS PREFIXADOS DE EMPRÉSTIMOS EXTERNOS', 'Registra o valor dos encargos financeiros pré-estabelecidos em valores prefixados, referentes a empréstimos externos.', 1, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (613, 2, '2.1.2.9.1.02.00.00.00.00', '(-) ENCARGOS PREFIXADOS DE FINANCIAMENTOS EXTERNOS', 'Registra o valor dos encargos financeiros pré-estabelecidos em valores prefixados, referentes a financiamentos externos.', 1, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (614, 2, '3.1.1.2.1.04.26.00.00.00', 'INSS PATRONAL    ', 'Registra as variações patrimoniais diminutivas com INSS patronal por contratação por tempo determinado.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (615, 2, '2.1.8.4.1.97.00.00.00.00', '(-) DESÁGIO NA EMISSÃO DE DEBÊNTURES', 'Registra os valores de deságio na emissão de debentures, que são os valores recebidos inferiores ao valor de resgate desses títulos na data do próprio recebimento ou do valor formalmente atribuído as debentures.', 1, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (616, 2, '2.1.8.4.1.98.00.00.00.00', '(-) CUSTO DA TRANSAÇÃO A AMORTIZAR', 'Registra os custos da transação a amortizar, que são apenas os custos incorridos e diretamente atribuíveis as atividades necessárias exclusivamente a consecução da transação. Por exemplo: taxas e comissões. Entretanto, não incluem despesas financeiras, custos internos administrativos ou custo de carregamento.', 1, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (617, 2, '2.2.2.1.3.01.02.00.00.00', '(-) DESÁGIO DE TÍTULOS', 'Registra os valores relativos a deságio ocorridos em títulos.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (618, 2, '2.2.2.1.4.01.02.00.00.00', '(-) DESÁGIO DE TÍTULOS', 'Registra os valores relativos a deságio ocorridos em títulos.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (619, 2, '2.2.2.1.5.01.02.00.00.00', '(-) DESÁGIO DE TÍTULOS', 'Registra os valores relativos a deságio ocorridos em títulos.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (620, 2, '3.1.1.2.1.03.00.00.00.00', 'SENTENÇAS JUDICIAIS     ', 'Registra as variações patrimoniais diminutivas com sentenças judiciais.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (621, 2, '2.2.2.8.1.01.00.00.00.00', '(-) ENCARGOS PREFIXADOS DE EMPRÉSTIMOS INTERNOS', 'Registra o valor dos encargos financeiros pré-estabelecidos em valores prefixados, referentes a empréstimos internos.', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (622, 2, '2.2.2.8.1.02.00.00.00.00', '(-) ENCARGOS PREFIXADOS DE FINANCIAMENTOS INTERNOS', 'Registra o valor dos encargos financeiros pré-estabelecidos em valores prefixados, referentes a financiamentos internos.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (623, 2, '2.2.2.9.1.01.00.00.00.00', '(-) ENCARGOS PREFIXADOS DE EMPRÉSTIMOS EXTERNOS', 'Registra o valor dos encargos financeiros pré-estabelecidos em valores prefixados, referentes a empréstimos externos.', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (625, 2, '3.1.3.1.1.04.00.00.00.00', 'AJUDA DE CUSTO  ', 'Registra as variações patrimoniais diminutivas realizadas a titulo de ajuda de custo de pessoal civil. ', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (626, 2, '2.2.7.2.1.01.02.00.00.00', '(-) CONTRIBUIÇÕES DO ENTE PARA O PLANO FINANCEIRO DO RPPS', 'Registra, de acordo com o resultado da avaliação atuarial, o valor presente das contribuições (normal, suplementar ou aportes periódicos) futuras do ente, por prazo de vigência indeterminado, para financiar os benefícios já em fase de pagamento.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (627, 2, '2.2.7.2.1.01.03.00.00.00', '(-) CONTRIBUIÇÕES DO APOSENTADO PARA O PLANO FINANCEIRO DO RPPS  ', 'Registra, de acordo com o resultado da avaliação atuarial, o valor presente das contribuições futuras dos inativos, por prazo de vigência indeterminado, para financiar os benefíciosjá em fase de pagamento.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (628, 2, '2.2.7.2.1.01.04.00.00.00', '(-) CONTRIBUIÇÕES DO PENSIONISTA PARA O PLANO FINANCEIRO DO RPPS              ', 'Registra, de acordo com o resultado da avaliação atuarial, o valor presente das contribuições futuras dos pensionistas, por prazo de vigência indeterminado, para financiar os benefícios já em fase de pagamento.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (629, 2, '2.2.7.2.1.01.05.00.00.00', '(-) COMPENSAÇÃO PREVIDENCIÁRIA DO PLANO FINANCEIRO DO RPPS       ', 'Registra, de acordo com o resultado da avaliação atuarial, o valor presente da compensação previdenciária conforme expressa o artigo 11, da Portaria MPS nº 403/2008.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (630, 2, '2.2.7.2.1.01.07.00.00.00', '(-) COBERTURA DE INSUFICIÊNCIA FINANCEIRA', 'Registra, de acordo com o resultado da avaliação atuarial, o valor presente das insuficiências financeiras futuras do plano financeiro considerando o §1º do artigo 2º da Lei nº 9.717/98.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (631, 2, '2.2.7.2.1.02.02.00.00.00', '(-) CONTRIBUIÇÕES DO ENTE PARA O PLANO FINANCEIRO DO RPPS ', 'Registra, de acordo com o resultado da avaliação atuarial, o valor presente das contribuições (normal, suplementar ou aportes periódicos) futuras do ente, incidentes sobre as remunerações da geração atual.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (632, 2, '2.2.7.2.1.02.03.00.00.00', '(-) CONTRIBUIÇÕES DO ATIVO PARA O PLANO FINANCEIRO DO RPPS   ', 'Registra, de acordo com o resultado da avaliação atuarial, o somatório do valor presente das contribuições futuras dos servidores ativos, incidentes sobre as remunerações da geração atual.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (633, 2, '2.2.7.2.1.02.04.00.00.00', '(-) COMPENSAÇÃO PREVIDENCIÁRIA DO PLANO FINANCEIRO DO RPPS      ', 'Registra, de acordo com o resultado da avaliação atuarial, o valor presente da compensação previdenciária conforme expressa o artigo 11, da Portaria MPS nº 403/2008.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (634, 2, '2.2.7.2.1.02.06.00.00.00', '(-) COBERTURA DE INSUFICIÊNCIA FINANCEIRA  ', 'Registra, de acordo com o resultado da avaliação atuarial, o valor presente das insuficiências financeiras futuras do plano financeiro, considerando o §1º do artigo 2º da Lei nº 9.717/98.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (635, 2, '2.2.7.2.1.03.02.00.00.00', '(-) CONTRIBUIÇÕES DO ENTE PARA O PLANO PREVIDENCIÁRIO DO RPPS                       ', 'Registra, de acordo com o resultado da avaliação atuarial, o valor presente das contribuições (normal, suplementar ou aportes periódicos) futuras do ente, por prazo de vigência indeterminado, para financiar os benefícios já em fase de pagamento.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (636, 2, '2.2.7.2.1.03.03.00.00.00', '(-) CONTRIBUIÇÕES DO APOSENTADO PARA O PLANO PREVIDENCIÁRIO DO RPPS          ', 'Registra, de acordo com o resultado da avaliação atuarial, o valor presente das contribuições futuras dos inativos, por prazo de vigência indeterminado, para financiar os benefícios já em fase de pagamento.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (637, 2, '2.2.7.2.1.03.04.00.00.00', '(-) CONTRIBUIÇÕES DO PENSIONISTA PARA O PLANO PREVIDENCIÁRIO DO RPPS           ', 'Registra, de acordo com o resultado da avaliação atuarial, o valor presente das contribuições futuras dos pensionistas, por prazo de vigência indeterminado, para financiar os benefícios já em fase de pagamento.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (638, 2, '2.2.7.2.1.03.05.00.00.00', '(-) COMPENSAÇÃO PREVIDENCIÁRIA DO PLANO PREVIDENCIÁRIO DO RPPS             ', 'Registra, de acordo com o resultado da avaliação atuarial, o valor presente da compensação previdenciária conforme expressa o artigo 11 da Portaria MPS nº 403/2008.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (639, 2, '2.2.7.2.1.03.07.00.00.00', '(-) APORTES FINANCEIROS PARA COBERTURA DO DÉFICIT ATUARIAL - PLANO DE AMORTIZAÇÃO', 'Registra o valor presente dos aportes financeiros projetados para cobertura do déficit atuarial, conforme plano de amortização estabelecido em lei.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (640, 2, '2.2.7.2.1.04.02.00.00.00', '(-) CONTRIBUIÇÕES DO ENTE PARA O PLANO PREVIDENCIÁRIO DO RPPS                        ', 'Registra, de acordo com o resultado da avaliação atuarial, o valor presente das contribuições (normal, suplementar ou aportes periódicos) futuras do ente, incidentes sobre as remunerações da geração atual.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (641, 2, '2.2.7.2.1.04.03.00.00.00', '(-) CONTRIBUIÇÕES DO ATIVO PARA O PLANO PREVIDENCIÁRIO DO RPPS                        ', 'Registra, de acordo com o resultado da avaliação atuarial, o somatório do valor presente das contribuições futuras dos servidores ativos, incidentes sobre as remunerações da geração atual.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (642, 2, '2.2.7.2.1.04.04.00.00.00', '(-) COMPENSAÇÃO PREVIDENCIÁRIA DO PLANO PREVIDENCIÁRIO DO RPPS       ', 'Registra, de acordo com o resultado da avaliação atuarial, o valor presente da compensação previdenciária conforme expressa o artigo 11 da Portaria MPS nº 403/2008.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (643, 2, '2.2.7.2.1.04.06.00.00.00', '(-) APORTES PARA COBERTURA DO DÉFICIT ATUARIAL - PLANO DE AMORTIZAÇÃO', 'Registra o valor presente dos aportes para cobertura do déficit atuarial, conforme plano de amortização estabelecido em lei.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (644, 2, '2.2.7.2.1.05.98.00.00.00', '(-) OUTROS CRÉDITOS DO PLANO DE AMORTIZAÇÃO   ', 'Registra, de acordo com o resultado da avaliação atuarial, o valor presente líquido dos direitos incorporados ao patrimônio do RPPS com base em legislação específica, como exemplo: direitos sobre royalties, bem como registro tempestivo do plano de amortização implementado em lei do ente federativo, considerando que o ajuste contábil das reservas matemáticas somente ocorrerá na apresentação de uma nova reavaliação atuarial.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (645, 2, '3.3.1.1.1.40.00.00.00.00', 'MATERIAL BIOLÓGICO', 'Registra as Variações Patrimoniais Diminutivas provenientes da utilização de Material Biológico.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (646, 2, '3.1.1.1.1.01.10.00.00.00', 'RETRIBUIÇÃO ADICIONAL VARIÁVEL E PRÓ-LABORE (LEI 7711/88)', 'Registra o valor da despesa com retribuição adicional variável e pró-labore (lei 7711/88)', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (647, 2, '3.1.1.1.1.03.00.00.00.00', 'SENTENCAS JUDICIAIS', 'Registra as variações patrimoniais diminutivas provenientes de sentenças judiciais.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (648, 2, '3.1.1.2.1.01.01.00.00.00', 'VENCIMENTOS E SALÁRIOS  ', 'Registra as variações patrimoniais diminutivas realizadas com vencimentos e salários do pessoal civil regidos pelo Regime Geral da Previdência Social.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (649, 2, '3.1.1.2.1.01.02.00.00.00', 'ADICIONAL NOTURNO', 'Registra as variações patrimoniais diminutivas com remunerações a empregados em atividade noturna.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (650, 2, '3.1.1.2.1.01.03.00.00.00', 'INCORPORAÇÕES    ', 'Registra as variações patrimoniais diminutivas realizadas a título de vencimentos e vantagens por incorporações.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (651, 2, '3.1.1.2.1.01.04.00.00.00', 'ABONO DE PERMANÊNCIA    ', 'Registra as variações patrimoniais diminutivas provenientes de despesas com pagamento do abono de permanência, devido aos empregados que, tendo completado as exigências para aposentadoria voluntária, opte por permanecer em atividade.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (652, 2, '3.1.1.2.1.01.05.00.00.00', 'ADICIONAL DE PERICULOSIDADE    ', 'Registra as variações patrimoniais diminutivas com remuneração de empregados que exercem atividades perigosas, conforme o § 1º, do artigo 193, do Decreto-Lei nº 5.452, de 1º de maio de 1943 (CLT).', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (653, 2, '3.1.1.2.1.04.25.00.00.00', 'OBRIGAÇÕES PATRONAIS    ', 'Registra as variações patrimoniais diminutivas com obrigações patronais por contratação por tempo determinado.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (654, 2, '3.1.1.2.1.01.06.00.00.00', 'ADICIONAL DE INSALUBRIDADE     ', 'Registra as variações patrimoniais diminutivas com remuneração de empregados em atividade em locais insalubres, conforme artigo 192, do Decreto-Lei nº 5.452, de 1º de maio de 1943 (CLT).', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (655, 2, '3.1.1.2.1.01.07.00.00.00', 'REMUNERAÇÃO PARTICIPANTES DE ÓRGÃO DE DELIBERAÇÃO COLETIVA ', 'Registra as variações patrimoniais diminutivas realizadas a título de remuneração de membros de órgãos de deliberação coletiva (Conselho Consultivo, Conselho de Administração, Conselho Fiscal ou outros órgãos colegiados), observado o disposto na Lei nº 7733, de 14/02/89.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (656, 2, '3.1.1.2.1.01.08.00.00.00', 'INCENTIVO A QUALIFICAÇÃO', 'Registra as variações patrimoniais diminutivas provenientes de despesas com incentivo a qualificação de empregados que possuírem educação formal superior ao exigido pelo emprego/cargo que ocupam, em áreas de interesse do órgão.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (657, 2, '3.1.1.2.1.01.09.00.00.00', 'ADICIONAL DE TRANSFERÊNCIA - ART. 469/CLT    ', 'Registra as variações patrimoniais diminutivas com remuneração de servidores que exercem foram transferidos, conforme art. 469 da CLT.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (658, 2, '3.1.1.2.1.01.10.00.00.00', 'RETR. ADIC. VARIÁVEL E PRÓ-LABORE (LEI 7711/88) ', 'Registra as variações patrimoniais diminutivas realizadas a título de retribuição adicional variável e pró-labore de êxito, conforme Lei 7.711/88, artigos terceiro e quinto.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (659, 2, '3.1.1.2.1.01.11.00.00.00', 'REMUNERAÇÃO DE DIRETORES', 'Registra as variações patrimoniais diminutivas realizadas a título de remuneração de diretores de empresas públicas e de economia mista.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (660, 2, '3.1.1.2.1.01.12.00.00.00', 'VANTAGEM PECUNIARIA INDIVIDUAL ', 'Registra as variações patrimoniais diminutivas realizadas com a vantagem pecuniária individual.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (661, 2, '3.1.1.2.1.01.13.00.00.00', 'ABONO PROVISÓRIO - PESSOAL CIVIL      ', 'Registra as variações patrimoniais diminutivas realizadas com abono provisório a pessoal civil.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (662, 2, '3.1.1.2.1.01.14.00.00.00', 'GRATIFICAÇÃO POR EXERCÍCIO DE CARGOS  ', 'Registra as variações patrimoniais diminutivas realizadas com gratificação por exercício de cargos, como GAJ, etc.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (663, 2, '3.1.1.2.1.01.15.00.00.00', 'INDENIZAÇÃO A ANISTIADO POLÍTICO      ', 'Registra as variações patrimoniais diminutivas realizadas a título de indenização de anistiados políticos, conforme a Lei 10.559/2002.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1039, 2, '3.5.1.1.2.05.00.00.00.00', 'VALORES DIFERIDOS - BAIXA ', 'Registra o valor da cota diferida no processo de baixa dos recursos diferidos.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (664, 2, '3.1.1.2.1.01.16.00.00.00', 'GRATIFICAÇÃO POR EXERCÍCIO DE FUNÇÕES ', 'Registra as variações patrimoniais diminutivas realizadas com gratificação por exercício de funções, de coordenação, assessoramento, chefia e encargo de atividades específicas.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (665, 2, '3.1.1.2.1.01.17.00.00.00', 'INDENIZAÇÃO DE LOCALIZAÇÃO     ', 'Registra as variações patrimoniais diminutivas realizadas a título de indenização de localização específica determinada por lei.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (666, 2, '3.9.4.3.1.99.00.00.00.00', 'OUTROS INCENTIVOS A CULTURA', 'Registra os demais incentivos financeiros concedidos, visando a promoção da cultura.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (667, 2, '3.1.1.2.1.01.18.00.00.00', 'GRATIFICAÇÃO DE TEMPO DE  SERVIÇO     ', 'Registra as variações patrimoniais diminutivas com gratificações adquiridas em função de contagem de tempo de serviço, pessoal civil.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (668, 2, '3.1.1.2.1.01.19.00.00.00', 'GRATIFICAÇÕES ESPECIAIS ', 'Registra as variações patrimoniais diminutivas com gratificações de natureza especial concedidas em virtude de lei a pessoal civil, tais como: gratificação especial de localização, etc.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (669, 2, '3.1.1.2.1.01.20.00.00.00', 'GRATIFICAÇÃO POR ATIVIDADES EXPOSTAS  ', 'Registra as variações patrimoniais diminutivas com gratificações, quando pelo exercício, expõe o servidor a riscos.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (670, 2, '3.1.1.2.1.01.21.00.00.00', 'FÉRIAS VENCIDAS E PROPORCIONAIS', 'Registra as variações patrimoniais diminutivas com pagamento de férias vencidas e proporcionais na rescisão de contrato de trabalho ou demissão do empregado.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (671, 2, '3.1.1.2.1.01.22.00.00.00', '13º SALÁRIO      ', 'Registra as variações patrimoniais diminutivas realizadas com gratificação de natal (13º salário) do pessoal civil.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (672, 2, '3.1.1.2.1.01.23.00.00.00', 'FÉRIAS - ABONO PECUNIÁRIO      ', 'Registra as variações patrimoniais diminutivas provenientes de despesas com a conversão em abono pecuniário de um terço do valor da remuneração devida ao empregado no período de férias.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (673, 2, '3.1.1.2.1.01.24.00.00.00', 'FÉRIAS - ABONO CONSTITUCIONAL  ', 'Registra as variações patrimoniais diminutivas provenientes do valor do abono concedido a todos empregados como remuneração do período de férias anuais - um terço a mais do que o salário normal.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (674, 2, '3.1.1.2.1.01.25.00.00.00', 'LICENÇA-PRÊMIO   ', 'Registra as variações patrimoniais diminutivas realizadas com licença-prêmio por assiduidade no trabalho.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (675, 2, '3.1.1.2.1.01.26.00.00.00', 'LICENÇA CAPACITAÇÃO     ', 'Registra as variações patrimoniais diminutivas realizadas com licença para capacitação.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (676, 2, '3.1.1.2.1.01.27.00.00.00', 'ADIANTAMENTO  PECUNIÁRIO', 'Registra as variações patrimoniais diminutivas com adiantamento pecuniário devidos aos servidores em decorrência de determinação legal.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (677, 2, '3.1.1.2.1.01.28.00.00.00', 'REPRESENTAÇÃO MENSAL    ', 'Registra as variações patrimoniais diminutivas realizadas com representação mensal, por exemplo do "DAS" e etc.', 1, true, 2, 'N');
