insert into contabilidade.planocontadetalhe values (810, 2, '3.2.2.3.1.70.00.00.00.00', 'SENTENÇAS JUDICIAIS - PENSÕES - PESSOAL MILITAR', 'Registra as variações patrimoniais diminutivas com pagamento de pensões em decorrência de sentença judicial.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (811, 2, '3.2.2.3.1.99.00.00.00.00', 'OUTRAS PENSÕES - PESSOAL MILITAR', 'Registra as variações patrimoniais diminutivas com pagamento de outras pensões, não especificado anteriormente.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (812, 2, '3.2.9.1.1.12.03.00.00.00', 'SALÁRIO FAMÍLIA - PENSIONISTA PESSOAL CIVIL', 'Registra o valor das Variações Patrimoniais Diminutivas com Salário-Família devido a Pensionista Pessoal Civil.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (813, 2, '3.3.1.1.1.10.00.00.00.00', 'MATERIAL QUIMÍCO', 'Registra as Variações Patrimoniais Diminutivas provenientes da utilização de todos os elementos ou compostos químicos destinados ao fabrico de Produtos químicos, análises laboratoriais, bem como aqueles destinados ao combate de pragas ou opizootias. ácidos - Inseticidas - produtos químicos para tratamento de água - reagentes químicos - sais - solventes - substâncias utilizadas para combater insetos, fungos e bactérias e outros.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (814, 2, '3.2.9.1.1.01.00.00.00.00', 'AUXÍLIO FUNERAL ATIVO CIVIL', 'Registra o valor das variações patrimoniais diminutivas com auxílio devido a família do servidor ativo civil falecido, em valor equivalente a um mês de remuneração ou proventos. Devido também a terceiro que custear comprovadamente as despesas com funeral do servidor. Também será devido auxilio funeral, em caso de falecimento de servidor em serviço fora do local de trabalho, inclusive no exterior e as despesas de transporte do corpo (traslado) correrão a conta dos recursos da União, autarquia ou fundação publica (art. 228, Lei 8112/90).', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (815, 2, '3.2.9.1.1.02.00.00.00.00', 'AUXÍLIO FUNERAL INATIVO CIVIL', 'Registra o valor das variações patrimoniais diminutivas com o auxílio devido a família do servidor inativo civil, em valor equivalente a um mês de remuneração ou proventos. Devido também a terceiro que custear comprovadamente as variações patrimoniais diminutivas com funeral do inativo civil.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (816, 2, '3.2.9.1.1.03.00.00.00.00', 'AUXÍLIO NATALIDADE ATIVO CIVIL', 'Registra o valor das Variações Patrimoniais Diminutivas com auxílio natalidade - ativo civil, devido a servidora, cônjuge ou companheiro servidor público, por motivo de nascimento de filho.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (817, 2, '3.2.9.1.1.04.00.00.00.00', 'AUXÍLIO NATALIDADE INATIVO CIVIL', 'Registra o valor das Variações Patrimoniais Diminutivas com auxílio natalidade inativo civil, devido, a servidora, cônjuge ou companheiro servidor público, por motivo de nascimento de filho.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (818, 2, '3.2.9.1.1.05.00.00.00.00', 'AUXÍLIO RECLUSÃO ATIVO CIVIL', 'Registra o valor das variações patrimoniais diminutivas com auxílio reclusão devido a família do servidor ativo civil, afastado por motivo de prisão.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (819, 2, '3.2.9.1.1.06.00.00.00.00', 'AUXÍLIO RECLUSÃO INATIVO CIVIL', 'Registra o valor das variações patrimoniais diminutivas com auxÍlio reclusão devido a família do servidor inativo civil, afastado por motivo de prisão.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (820, 2, '3.2.9.1.1.07.00.00.00.00', 'AUXÍLIO FUNERAL PENSIONISTA CIVIL', 'Registra o valor das variações patrimoniais diminutivas com o auxílio devido a família do servidor pensionista, em valor equivalente a um mês de remuneração ou proventos. Devido também a terceiro que custear comprovadamente as variações patrimoniais diminutivas com funeral do pensionista.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (821, 2, '3.2.9.1.1.08.00.00.00.00', 'AUXÍLIO RECLUSÃO PENSIONISTA CIVIL', 'Registra o valor das variações patrimoniais diminutivas com o auxílio devido a família do servidor pensionista, em valor equivalente a um mês de remuneração ou proventos. Devido também a terceiro que custear comprovadamente as variações patrimoniais diminutivas com funeral do pensionista.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1044, 2, '3.5.1.2.2.02.02.00.00.00', 'DOAÇÕES CONCEDIDAS DE BENS IMÓVEIS', 'Registra o valor de doações de bens imóveis entre unidades de órgãos diferentes.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (822, 2, '3.2.9.1.1.09.00.00.00.00', 'AUXÍLIO NATALIDADE PENSIONISTA CIVIL', 'Registra o valor das variações patrimoniais diminutivas com auxílio natalidade a pensionista civil, devido a servidora, cônjuge ou companheiro servidor público, por motivo de nascimento de filho.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (823, 2, '3.2.9.1.1.10.00.00.00.00', 'AUXÍLIO-DOENÇA', 'Registra as variações patrimoniais diminutivas com auxílio-doença, devido ao segurado que ficar incapacitado para o trabalho.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (824, 2, '3.2.9.1.1.11.00.00.00.00', 'SALÁRIO MATERNIDADE', 'Registra as variações patrimoniais diminutivas com salário-maternidade, devido a segurada gestante, na forma da Lei 6.136/74, durante o período de licença gestante previsto em lei.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (825, 2, '3.2.9.1.1.12.01.00.00.00', 'SALÁRIO FAMÍLIA - ATIVO PESSOAL CIVIL', 'Registra o valor das Variações Patrimoniais Diminutivas com Salário-Família - Ativo Pessoal Civil.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (826, 2, '3.3.1.1.1.01.00.00.00.00', 'COMBUSTÍVEIS E LUBRIFICANTES AUTOMOTIVOS', 'Registra as variações Patrimoniais Diminutivas provenientes da utilização de Combustíveis para motores a combustão interna de veículos rodoviários, tratores em geral, embarcações diversas e grupos geradores estacionados ou transportáveis, e todos os óleos lubrificantes destinados aos sistemas hidráulicos hidramáticos de caixa de transmissão de força e graxas grafitadas para altas e baixas temperaturas. aditivos - álcool hidratado - fluído para amortecedores - fluido para transmissão hidráulica - gasolina - graxas - óleo diesel - óleo para carter - óleo para freio e outros.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (827, 2, '3.3.1.1.1.03.00.00.00.00', 'GÁS E OUTROS MATERIAIS ENGARRAFADOS', 'Registra as variações patrimoniais diminutivas provenientes da utilização de gás de uso industrial, de tratamento de água, de iluminação, de uso médico, bem como gases nobres para uso em laboratório cientifico, tais como: acetileno - carbônico freon - helio - hidrogênio - Liquefeito de petróleo - nitrogênio - oxigênio e outros. Registra, ainda, o valor das despesas com gás, pó químico, água pressurizadas e outros materiais utilizado nas recargas de Extintores de Incêndio.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (828, 2, '3.3.1.1.1.04.00.00.00.00', 'EXPLOSIVOS E MUNIÇÕES', 'Registra as variações Patrimoniais Diminutivas provenientes da utilização de cargas de projeção em peças de artilharia, mísseis guiados e não guiados, capsulas ou estojos para recarga e explosivos de uso Militar e Paramilitar. balas e similares - estopim - explosivos, tais como: artefatos explosivos - artigos pirotécnicos - capsulas de detonação - dinamite - espoleta - fogos de artifício - granada - pólvora e outros.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (829, 2, '3.3.1.1.1.05.00.00.00.00', 'ALIMENTOS PARA ANIMAIS', 'Registra as Variações Patrimoniais Diminutivas provenientes da utilização de alimentos destinados a gado bovino, equino, muar, e bufalino, caprinos, suínos, ovinos, aves de qualquer espécie, como também para animais silvestres em cativeiro (jardins zoológicos ou laboratórios) e outros. alfafa - alpiste - capim verde - farelo - farinhas em geral - fubá grosso - milho em grão - ração balanceada - sal mineral - suplementos vitamínicos e outros.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (830, 2, '3.3.1.1.1.06.00.00.00.00', 'GÊNEROS ALIMENTAÇÃO', 'Registra as Variações Patrimoniais Diminutivas provenientes da utilização de gêneros de alimentação ao natural, beneficiados ou conservados, tais como: açúcar - adoçante - água mineral - bebidas - café - carnes em geral - cereais - chás - condimentos - frutas - gelo - legumes - refrigerantes - sucos - temperos - verduras e outros.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (831, 2, '3.3.1.1.1.07.00.00.00.00', 'ANIMAIS PARA PESQUISA E ABATE', 'Registra as Variações Patrimoniais Diminutivas provenientes da utilização de animais para pesquisa e abate. Incluem-se nesta classificação os peixes e mariscos, todas as espécies de mamíferos, abelhas para estudos, pesquisa e produção de Mel, bem assim qualquer outro animal destinado a estudo genético ou alimentação. boi - cabrito - cobaias em geral - macaco - rato - rã e outros.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (832, 2, '3.3.1.1.1.08.00.00.00.00', 'MATERIAL FARMACOLÓGICO', 'Registra as Variações Patrimoniais Diminutivas provenientes da utilização de medicamentos ou componentes destinados a manipulação de drogas medicamentosas. medicamentos - soro - vacinas e outros.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (833, 2, '3.3.1.1.1.09.00.00.00.00', 'MATERIAL ODONTOLÓGICO', 'Registra as Variações Patronais Diminutivas provenientes da utilização de materiais para pacientes da área odontológica, bem como os utilizados indiretamente pelos protéticos na convecção de próteses diversas. agulhas - amalgama - anestésicos - broca - cimento odontológico - espátula odontológica - filmes para raio X - platina - resinas odontológicas - seringas - sugador e outros.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (861, 2, '3.3.3.1.1.01.01.00.00.00', 'DEPRECIAÇÃO DE BENS MÓVEIS', 'Registra a redução do valor dos bens móveis pelo desgaste ou perda de utilidade por uso, ação da natureza ou obsolescência.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1325, 2, '5.1.1.2.0.00.00.00.00.00', 'REVISAO DO PPA', 'Registra o somatório dos valores monetários das revisões anuais autorizadas durante o período de vigência do plano plurianual.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (834, 2, '3.3.1.1.1.11.00.00.00.00', 'MATERIAL DE COUDELARIA OU DE USO ZOOTÉCNICO', 'Registra as Variações Patrimoniais Diminutivas provenientes da utilização de materiais utilizados no arreamento de animais destinados a montaria, com exceção da sela, como também aqueles destinados ao adestramento de cães de guarda ou outro animal domestico. argolas de metal - arreamento - barrigueiras - bridões - cabrestos - cinchas - Cravos - escovas para animais - estribos - ferraduras - mantas de pano - material para apicultura - material de ferragem e contenção de animais - peitorais -raspadeiras e outros.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (835, 2, '3.3.1.1.1.13.00.00.00.00', 'MATERIAL DE CAÇA E PESCA', 'Registra as Variações Patrimoniais diminutivas provenientes da utilização de materiais de caça e pesca.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (836, 2, '3.3.1.1.1.14.00.00.00.00', 'MATERIAL EDUCATIVO E ESPORTIVO', 'Registra as Variações Patrimoniais diminutivas provenientes da utilização de materiais consumidos diretamente nas atividades educativas e esportivas de crianças e adultos. apitos - bolas - bonés - botas especiais - brinquedos educativos - calções - camisas de malha - chuteiras - cordas - esteiras - joelheiras - luvas - materiais pedagógicos - meias - óculos para motociclistas - patins - quimonos - raquetes - redes para pratica de esportes - tênis e sapatilhas - tornozeleiras - touca para natação e outros.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (837, 2, '3.3.1.1.1.15.00.00.00.00', 'MATERIAL PARA FESTIVIDADES E HOMENAGENS', 'Registra as Variações Patrimoniais diminutivas provenientes da utilização de materiais de consumo utilizados em festividades e homenagens, incluindo artigos para decoração e Buffet. arranjos e coroas de flores - bebidas - doces - salgados - placas comemorativas (exceto as placas para distribuição gratuita) e outros.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3307, 2, '8.1.1.1.1.01.10.00.00.00', 'CAUÇÕES EXECUTADAS', 'REGISTRA O VALOR RECEBIDO DAS GARANTIAS POR CAUÇÕES NO PAÍS.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (838, 2, '3.3.1.1.1.16.00.00.00.00', 'MATERIAL DE EXPEDIENTE', 'Registra as Variações Patrimoniais diminutivas provenientes da utilização de materiais aplicados diretamente nos trabalhos administrativos, nos escritórios públicos, nos centros de estudos e pesquisas, nas escolas, nas universidades etc. agenda - alfinete de aço - almofada p/carimbos - apagador - apontador de lápis - arquivo p/disquete - bandeja para papeis - bloco p/rascunho - bobina papel p/calculadoras - borracha - caderno - caneta -capa de processo - carimbos em geral - cartolina - classificador -clipe - cola - colchete - corretivo - envelope - espátula - estêncil -estilete - extrator de grampos - fita adesiva - fita p/maquina de escrever e calcular - giz - goma elástica - grafite - grampeador -grampos - guia p/arquivo - guia de endereçamento postal - impressos e formulários em geral - intercalador p/fichário - lacre - lápis -lapiseira - limpa tipos - livros de ata, de ponto e de protocolo -papeis - pastas em geral - percevejo - perfurador - pinça - placas de acrílico - plásticos - porta-lápis - registrador - régua - selos p/correspondência - tesoura - tintas - toner - transparências - etiquetas e outros.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (839, 2, '3.3.1.1.1.17.00.00.00.00', 'MATERIAL DE PROCESSAMENTO DE DADOS', 'Registra as Variações Patrimoniais Diminutivas provenientes da utilização de suprimentos de ti, inclusive pecas para reposição. cartuchos de tinta - capas plásticas protetoras para micros e impressoras - cd-rom virgem - disquetes - etiquetas em formulários - contínuos -leitora/smartcard - mouse e teclado (reposição) - mouse pad - pecas e acessórios para computadores e periféricos - recarga de cartuchos de tinta - toner para impressoras a laser - cartões magnéticos - reposição de leitora/token pen-drive/outros.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (840, 2, '3.3.1.1.1.18.00.00.00.00', 'MATERIAIS E MEDICAMENTOS P/USO VETERINÁRIO', 'Registra as Variações Patrimoniais Diminutivas provenientes da utilização de materiais e medicamentos para uso veterinário. vacinas - medicamentos.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (841, 2, '3.3.1.1.1.19.00.00.00.00', 'MATERIAL DE ACONDICIONAMENTO E EMBALAGEM', 'Registra as Variações Patrimoniais Diminutivas provenientes da utilização de materiais aplicados diretamente nas preservações, acomodações ou embalagens de qualquer produto. arame - barbante - caixas plásticas, de madeira, papelão e isopor -cordas - engradados - fitas de aço ou metálicas - fitas gomadoras -garrafas e potes - linha - papel de embrulho - papelão - sacolas - sacos - e outros.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (842, 2, '3.3.1.1.1.20.00.00.00.00', 'MATERIAL DE CAMA, MESA E BANHO', 'Registra as Variações Patrimoniais Diminutivas provenientes da utilização de materiais utilizados em dormitórios coletivos, residenciais, hotéis, restaurantes etc. cobertores - colchas - colchonetes - fronhas - guardanapos - lençóis -toalhas - travesseiros - e outros.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (843, 2, '3.3.1.1.1.21.00.00.00.00', 'MATERIAL DE COPA E COZINHA', 'Registra as Variações Patrimoniais Diminutivas provenientes da utilização de materiais para refeitórios de qualquer tipo, cozinhas residenciais, de hotéis, de hospitais, de escolas, de universidades, de fabricas etc. abridor de garrafa - açucareiros - artigos de vidro e plástico -bandejas - coadores - colheres - copos - ebulidores - facas - farinheiras - fósforos - frigideiras - garfos - garrafas térmicas - paliteiros - panelas - panos de cozinha - papel alumínio - pratos -recipientes para água - suportes de copos p/cafezinho - tigelas -velas - xícaras - e outros.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (844, 2, '3.3.1.1.1.22.00.00.00.00', 'MATERIAL DE LIMPEZA E PRODUTOS DE HIGIENIZAÇÃO', 'Registra as Variações Patrimoniais Diminutivas provenientes da utilização de materiais destinados a higienização pessoal, de ambientes de trabalho, de hospitais etc. álcool etílico - anticorrosivo - aparelho de barbear descartável -balde plástico - bomba p/inseticida - capacho - cera - cesto p/lixo- creme dental - desinfetante - desodorizante - detergente - escova de dentes - escova p/roupas e sapatos - espanador - esponja - estopa -flanela - inseticida - lustra-móveis - mangueira - naftalina - para lixo - palha de aço - panos p/limpeza - papel higiênico - pasta para limpeza de utensílios - porta - sabão - removedor - rodo - sabão - sabonete - saco p/lixo - saponáceo - soda cáustica - toalha de papel- vassoura - e outros.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (845, 2, '3.3.1.1.1.23.00.00.00.00', 'UNIFORMES, TECIDOS E AVIAMENTOS', 'Registra as Variações Patrimoniais Diminutivas provenientes da utilização de uniformes ou qualquer tecido ou material sintético que se destine a confecção de roupas, com linhas de qualquer espécie destinadas a costuras e outros materiais de consumo empregados direta ou indiretamente na confecção de roupas. agasalhos - artigos de costura - aventais - blusas - botões - cadarços- calcados - calcas - camisas - capas - chapéus - cintos - elásticos -gravatas - guarda-pós - linhas - macacões - meias - tecidos em geral -uniformes militares ou de uso civil - zíperes - e outros.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (846, 2, '3.3.1.1.1.37.00.00.00.00', 'SUPRIMENTOS DE ARMAMENTO', 'Registra as Variações Patrimoniais Diminutivas provenientes da utilização de Suprimentos de Armamento.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (847, 2, '3.3.1.1.1.38.00.00.00.00', 'SUPRIMENTO DE PROTEÇÃO AO VOO', 'Registra as Variações Patrimoniais Diminutivas provenientes da utilização de Suprimentos de proteção ao Voo.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (862, 2, '3.3.1.1.1.41.00.00.00.00', 'MATERIAL PARA UTILIZAÇÃO EM GRÁFICA', 'Registra as Variações Patrimoniais Diminutivas provenientes da utilização de todos os materiais de consumo de uso gráfico, tais como: chapas de offset - clichês - cola - espirais - fotolitos - logotipos - papel - solventes - tinta - tipos - e outros.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (848, 2, '3.3.1.1.1.39.00.00.00.00', 'MATERIAL PARA MANUTENÇÃO DE VEÍCULOS', 'Registra as Variações Patrimoniais Diminutivas provenientes da utilização de materiais para aplicação e manutenção de veículos rodoviários, viaturas blindadas e tratores em geral. água destilada - amortecedores - baterias - borrachas - buzina - cabos de acelerador - cabos de embreagem - camará de ar - carburador completo - cifa - colar de embreagem - condensador e platinado - correias- disco de embreagem - ignição - junta homocinetica - lâmpadas e lanternas p/veículos - lonas e pastilhas de freio - mangueiras -material utilizado em lanternagem e pintura - motor de reposição -para-brisa - para-choque - platô - pneus - reparos - retentores -retrovisores - rolamentos - tapetes - válvula da marcha lenta e termostática - velas - e outros.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (864, 2, '3.3.1.1.1.43.00.00.00.00', 'MATERIAL PARA REABILITAÇÃO PROFISSIONAL', 'Registra as Variações Patrimoniais Diminutivas provenientes da utilização de materiais para programas de reabilitação profissional. bastões - bengalas - joelheiras - meias elásticas e assemelhados -óculos - orteses - pesos - próteses, instrumentos de trabalho e implementos profissionais.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (889, 2, '3.3.1.2.1.99.00.00.00.00', 'OUTROS MATERIAIS DE DISTRIBUIÇÃO GRATUITA', 'Registra as variações patrimoniais diminutivas provenientes da utilização de materiais para distribuição gratuita, não contemplados em rubricas especificas.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1138, 2, '3.6.1.7.1.02.00.00.00.00', 'AJUSTE PARA PERDAS EM CLIENTES', 'Registra a variação patrimonial diminutiva com ajuste para perdas créditos relativos a clientes.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (849, 2, '3.3.1.1.1.24.00.00.00.00', 'MATERIAL P/MANUT. E BENS IMÓVEIS/INSTALAÇÕES', 'Registra as Variações Patrimoniais Diminutivas provenientes da utilização de materiais de consumo para aplicação, manutenção e reposição de qualquer bem publico. amianto - aparelhos sanitários - arames liso e farpado - areia -basculante - boca de lobo - boia - brita - brocha - cabo metálico -cal - cano - cerâmica - cimento - cola - condutores de fios - conexões- curvas - esquadrias - fechaduras - ferro - gaxetas - grades -impermeabilizantes - isolantes acústicos e térmicos - janelas - joelhos - ladrilhos - lavatórios - lixas - madeira - marcos de concreto - massa corrida - niple - papel de parede - parafusos - peças p/elevadores, portões elétricos, ar condicionado central, etc- pias- pigmentos - portas e portais - pregos - rolos solventes - sifão - tacos - tampa p/vaso - tampão de ferro - tanque - tela de estuque - telha - tijolo - tinta - torneira - trincha - tubo de concreto -válvulas - verniz - vidro - aquecedores a gás e outros.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (850, 2, '3.3.1.1.1.25.00.00.00.00', 'MATERIAL PARA MANUTENÇÃO DE BENS', 'Registra as Variações Patrimoniais Diminutivas provenientes da utilização de componentes, pecas, acessórios e sobressalentes para aplicação, manutenção e reposição em bens moveis em geral. cabos - chaves - cilindros p/maquinas copiadoras - compressor p/ar condicionado - mangueira p/fogão - pecas de reposição de aparelhos e maquinas em geral - materiais de reposição para instrumentos musicais - vidro de mesa e outros.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (851, 2, '3.3.1.1.1.26.00.00.00.00', 'MATERIAL ELÉTRICO E ELETRÔNICO', 'Registra as Variações Patrimoniais Diminutivas provenientes da utilização de materiais de consumo para aplicação, manutenção e reposição dos sistemas, aparelhos e equipamentos elétricos e eletrônicos. benjamins - bocais - calhas - capacitores e resistores - chaves de ligação - circuitos eletrônicos - condutores - componentes de aparelho eletrônico - diodos - disjuntores - eletrodos - eliminador de pilhas -espelhos para interruptores - fios e cabos - fita isolante - fusíveis- interruptores - lâmpadas e luminárias - pilhas e baterias - pinos e plugs - placas de baquelita - reatores - receptáculos - resistências -starts - suportes - tomada de corrente - e outros.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (852, 2, '3.3.1.1.1.27.00.00.00.00', ' MATERIAL DE MANOBRA E PATRULHAMENTO', 'Registra as Variações Patrimoniais Diminutivas provenientes da utilização de materiais de consumo utilizados em campanha militar ou paramilitar, em manobras de tropas, em treinamento ou em ação em patrulhamento ostensivo ou rodoviário, em campanha de saúde publica etc. binóculo - carta náutica - cantil - cordas - flâmulas e bandeiras desinalizacao - lanternas - medicamentos de pronto-socorro - mochilas -piquetes - sacolas - sacos de dormir - sinaleiros - e outros.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (853, 2, '3.3.1.1.1.28.00.00.00.00', 'MATERIAL DE PROTEÇÃO E SEGURANÇA', 'Registra as Variações Patrimoniais Diminutivas provenientes da utilização de materiais de consumo utilizados diretamente na proteção de pessoas ou bens públicos, para socorro de pessoas e animais ou para socorro de veículos, aeronaves e embarcações, assim como qualquer outro item aplicado diretamente nas atividades de sobrevivência de pessoas, na selva, no mar ou em sinistros diversos, tais como: botas - cadeados - calcados especiais - capacetes - chaves - cintos - coletes - dedais - guarda-chuvas - lona - luvas - mangueira de lona -mascaras - passadeira antiderrapante - óculos - cabina de papelão e outros.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (854, 2, '3.3.1.1.1.29.00.00.00.00', 'MATERIAL PARA ÁUDIO, VÍDEO E FOTO', 'Registra as Variações Patrimoniais Diminutivas provenientes da utilização de materiais de consumo de emprego direto em filmagem e revelação, ampliações e reproduções de sons e imagens. aetze especial p/chapa de papel - álbuns p/retratos - alto-falantes- antenas - artigos para gravação em acetato - filmes virgens - fitas virgens de áudio e vídeo - lâmpadas especiais - material p/radiografia, microfilmagem e cinematografia - molduras - papel p/revelação de fotografias - pegadores - reveladores - e outros.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (855, 2, '3.3.1.1.1.30.00.00.00.00', 'MATERIAL PARA COMUNICAÇÕES', 'Registra as Variações Patrimoniais Diminutivas provenientes da utilização de materiais para comunicações, assim como os componentes, circuitos impressos ou integrados, pecas ou acessórios de reposição, chips, e partes de equipamentos de comunicação materiais para instalações: radiofônicas, radiotelegráficas, telegráficas e outros. - bateria para telefone celular- bloqueador telefônico - chave comutadora para telefone - fio para telefone - tomada para telefone - materiais para instalações radiofônicas - radiotelegráficas - telegráficas - outros.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (856, 2, '3.3.1.1.1.31.00.00.00.00', 'SEMENTES, MUDAS DE PLANTAS E INSUMOS', 'Registra as Variações Patrimoniais Diminutivas provenientes da utilização de qualquer tipo de semente destinada ao plantio e mudas de plantas frutíferas ou ornamentais, assim como todos os insumos utilizados para fertilização. adubos - argila - plantas ornamentais - borbulhas - bulbos - enxertos- fertilizantes - mudas envasadas ou com raízes nuas - sementes -terra - tubérculos - xaxim - e outros.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (857, 2, '3.3.1.1.1.32.00.00.00.00', 'SUPRIMENTO DE AVIAÇÃO', 'Registra as Variações Patrimoniais Diminutivas provenientes da utilização de suplementos para avaliação.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (858, 2, '3.3.1.1.1.33.00.00.00.00', 'MATERIAL PARA PRODUÇÃO INDUSTRIAL', 'Registra as Variações Patrimoniais Diminutivas provenientes da utilização de matérias-primas utilizadas na transformação, beneficiamento e industrialização de um produto final. borracha - couro - matérias-primas em geral - minérios - e outros.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (859, 2, '3.3.1.1.1.34.00.00.00.00', 'SUPRIMENTOS PARA MAQ. E MOTORES NAVIOS E EMBARCAÇÕES', 'Registra as Variações Patrimoniais Diminutivas provenientes da utilização de material para manutenção e reparo de maquinas e motores de navios, inclusive da esquadra, e de embarcações em geral.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (860, 2, '3.3.1.1.1.35.00.00.00.00', 'MATERIAL LABORATORIAL', 'Registra as Variações Patrimoniais Diminutivas provenientes da utilização de todos os utensílios usados em analises laboratoriais. almofarizes - bastões - bico de gás - cálices - corantes - filtros de papel - fixadoras - frascos - funis - garra metálica - laminas de vidro p/microscópio - lâmpadas especiais - luvas de borracha - metáfise metaloides p/analise - pinças - rolhas - vidraria: balão volumétrico - becker - conta-gotas - erlemeyer - pipeta - proveta - termômetro - tubo de ensaio - material de laboratório didático e outros.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (863, 2, '3.3.1.1.1.42.00.00.00.00', 'FERRAMENTAS', 'Registra as Variações Patrimoniais Diminutivas provenientes da utilização de todos os tipos de ferramentas utilizadas em oficinas, carpintarias, jardins etc. alicate - broca - caixa p/ferramentas - canivete - chaves em geral -enxada - espátulas - ferro de solda - foice - lamina de serra - lima -machado - martelo - pá - picareta - ponteira - prumo - serrote -tesoura de podar - trena - e outros.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (938, 2, '3.3.2.3.1.09.00.00.00.00', 'SERVIÇOS DE ALIMENTAÇÃO', 'Registra as variações patrimoniais diminutivas provenientes da utilização de serviços de fornecimento de alimentação.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (865, 2, '3.3.1.1.1.44.00.00.00.00', 'MATERIAL DE SINALIZAÇÃO VISUAL E OUTROS', 'Registra as Variações Patrimoniais Diminutivas provenientes da utilização de materiais para identificação, sinalização visual, endereçamento e outros. placas de sinalização em geral, tais como, placas indicativas para o setores e seções, placas para veículos, plaquetas para tombamento de material, placas sinalizadoras de trânsito, cones sinalizadores de trânsito, crachás, botons identificadores para servidores e outros.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (866, 2, '3.3.1.1.1.45.00.00.00.00', 'MATERIAL TÉCNICO PARA SELEÇÃO E TREINAMENTO', 'Registra as Variações Patrimoniais Diminutivas provenientes da utilização de materiais técnicos utilizados em processos de seleção e treinamento pela própria unidade gestora ou para distribuição não gratuita, tais como: apostilas e similares - folhetos de orientação - livros - manuais explicativos para candidatos - e outros.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (867, 2, '3.3.1.1.1.46.00.00.00.00', 'MATERIAL BIBLIOGRÁFICO', 'Registra as Variações Patrimoniais Diminutivas provenientes da utilização de material bibliográfico tais como: jornais - revistas - periódicos em geral - anuários médicos - anuário estático - livros em geral e outros, podendo estar na forma de cd-rom e os materiais bibliográficos para bibliotecas públicas.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (868, 2, '3.3.1.1.1.48.00.00.00.00', 'BENS MÓVEIS NÃO ATIVÁVEIS', 'Registra as Variações Patrimoniais Diminutivas provenientes da aquisição de bens moveis de natureza permanente não ativáveis, ou seja, aqueles considerados como despesa operacional, para fins de dedução de imposto de renda, desde que atenda as especificações contidas no artigo 301 do rir (regulamento de imposto de renda). esta conta é utilizada exclusivamente pelas unidades regidas pela lei 6404/76.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (869, 2, '3.3.1.1.1.49.00.00.00.00', 'BILHETES DE PASSAGEM', 'Registra as Variações Patrimoniais Diminutivas provenientes da utilização de bilhetes de passagem para guarda em estoque.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (870, 2, '3.3.1.1.1.50.00.00.00.00', 'BANDEIRAS, FLÂMULAS E INSÍGNIAS', 'Registra as Variações Patrimoniais Diminutivas provenientes da utilização de bandeiras, flâmulas e insígnias, a saber: brasões, escudos, armas da republica, selo nacional e outros.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (871, 2, '3.3.1.1.1.51.00.00.00.00', 'DISCOTECAS E FILMOTECAS NÃO IMOBILIZÁVEL', 'Registra as Variações Patrimoniais Diminutivas provenientes da utilização de discotecas e filmotecas não imobilizável.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (872, 2, '3.3.1.1.1.52.00.00.00.00', 'MATERIAL DE CARÁTER SECRETO OU RESERVADO', 'Registra as Variações Patrimoniais Diminutivas provenientes da utilização de material de caráter secreto ou reservado.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (873, 2, '3.3.1.1.1.53.00.00.00.00', 'MATERIAL METEOROLÓGICO', 'Registra as Variações Patrimoniais Diminutivas provenientes da utilização de material meteorológico, tais como: radiossondas, balão de látex, etc.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (874, 2, '3.3.1.1.1.54.00.00.00.00', 'MATERIAL P/MANUT. CONSERV. DE ESTRADAS E VIAS', 'Registra as Variações Patrimoniais Diminutivas provenientes da utilização de materiais para reparos, recuperações e adaptações de estradas, ferrovias e rodovias.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (875, 2, '3.3.1.1.1.58.00.00.00.00', 'SOBRESSALENTES PARA MÁQUINAS E EQUP. PARA PRODUÇÃO INDUSTRIAL', 'Registra as Variações Patrimoniais Diminutivas provenientes de Sobressalentes para Máquinas e Equipamentos para Produção Industrial.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (876, 2, '3.3.1.1.1.70.00.00.00.00', 'AQUISIÇÃO DE SOFTWARES DE BASE', 'Registra as Variações Patrimoniais Diminutivas provenientes da aquisição de Softwares de Base.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (877, 2, '3.3.1.1.1.71.00.00.00.00', 'MATERIAIS PARA CONSERVAÇÃO E MANUTENÇÃO DE BENS DE USO COMUM DO POVO', 'Registra as Variações Patrimoniais Diminutivas provenientes de Materiais para Conservação e Manutenção de Bens de uso Comum do Povo.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (878, 2, '3.3.1.1.1.98.00.00.00.00', 'SENTENÇAS JUDICIAIS DE FORNECEDORES DE MATERIAIS', 'Registra as Variações Patrimoniais Diminutivas provenientes de Sentenças Judiciais de Fornecedores de Materiais.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (879, 2, '3.3.1.1.1.99.00.00.00.00', 'OUTROS MATERIAIS DE CONSUMO', 'Registra as Variações Patrimoniais Diminutivas provenientes da utilização de outros materiais de consumo que não se enquadrem nas rubricas anteriores.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (880, 2, '3.3.1.2.1.01.00.00.00.00', 'MERCADORIAS DOADAS', 'Registra as variações patrimoniais diminutivas provenientes da utilização de produtos adquiridos com a finalidade de doação.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (881, 2, '3.3.1.2.1.02.00.00.00.00', 'MATERIAL DESTINADO À ASSISTÊNCIA SOCIAL', 'Registra as variações patrimoniais diminutivas provenientes da utilização de mat.de saúde (farmacológico, odontológico, hospitalar, medicamentos, órtese e prótese), gêneros alimentícios, mater. de cama, mesa, copa, cozinha, limpeza, higienização, uniformes, tecidos, aviamentos, manut. mov/imov., ferramentas e outros distinados a assistência social.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (882, 2, '3.3.1.2.1.03.00.00.00.00', 'MATERIAL EDUCACIONAL E CULTURAL', 'Registra as variações patrimoniais diminutivas provenientes da utilização de material educacional (material escolar, didático, técnico, material p/áudio, vídeo e foto) e material cultural (material religioso e esportivo).', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (883, 2, '3.3.1.2.1.04.00.00.00.00', 'MATERIAL DE ACONDICIONAMENTO E EMBALAGEM', 'Registra as Variações Patrimoniais Diminutivas provenientes da utilização de material de acondicionamento e embalagem.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (884, 2, '3.3.1.2.1.05.00.00.00.00', 'MATERIAL PARA CERIMONIAL', 'Registra as variações patrimoniais diminutivas provenientes da aquisição de materiais oferecidos a autoridades a titulo de homenagem.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (885, 2, '3.5.1.2.2.02.03.00.00.00', 'TRANFERÊNCIAS CONCEDIDAS DE BENS MÓVEIS ', 'Registra o valor dos bens móveis entre unidades do mesmo órgão.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (886, 2, '3.3.1.2.1.06.00.00.00.00', 'MATERIAL PARA DIVULGAÇÃO', 'Registra as variações patrimoniais diminutivas provenientes da utilização de material para publicidade e divulgação de programas do governo, para conscientizacao social. ex: camisetas, bonés, chaveiros, canetas, botons, com logomarcas, folders, cartazes, cartilhas e manuais, etc.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3304, 2, '8.1.1.1.1.01.07.00.00.00', 'SEGUROS-GARANTIA A EXECUTAR', 'Registra o valor dos seguros-garantia pendentes de execução, no país.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (887, 2, '3.3.1.2.1.07.00.00.00.00', 'MATERIAL DESTINADO A CONTRIBUINTE', 'Registra as variações patrimoniais diminutivas provenientes da utilização de material (cd-rom, formulários, etc.) para distribuição aos contribuintes.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (888, 2, '3.3.1.2.1.08.00.00.00.00', 'MATERIAL P/ IDENTIFICAÇÃO DE BENEFICIÁRIOS', 'Registra as Variações Patrimoniais Diminutivas provenientes da distribuição de Material para Identificação de Beneficiários.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (890, 2, '3.3.2.1.1.01.00.00.00.00', ' DIÁRIAS PESSOAL CIVIL', 'Registra as variações patrimoniais diminutivas provenientes da utilização de diárias de pessoal civil, cobrindo alimentação, pousada e locomoção urbana do servidor público ou celetista que se deslocar de sua sede em objeto de serviço, em caráter eventual ou transitório.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (891, 2, '3.3.2.1.1.02.00.00.00.00', ' DIÁRIAS - PESSOAL MILITAR', 'Registra as variações patrimoniais diminutivas provenientes da utilização de diárias decorrentes do deslocamento do militar da sede de sua unidade por motivo de serviço, destinadas à indenização das despesas de alimentação e pousada.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (892, 2, '3.3.2.1.1.03.00.00.00.00', ' DIÁRIAS - COLABORADORES EVENTUAIS', 'Registra as variações patrimoniais diminutivas provenientes da utilização de diárias pagas a prestadores de serviços de caráter eventual, sem vínculo com a administração pública.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (893, 2, '3.3.2.1.1.04.00.00.00.00', 'DIÁRIAS A CONSELHEIROS', 'Registra as variações patrimoniais diminutivas provenientes da utilização de diárias a membros de órgãos de deliberação coletiva (conselhos).', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (894, 2, '3.3.2.2.1.01.00.00.00.00', 'CONSULTORIA E ASSESSORIA', 'Registra as variações patrimoniais diminutivas provenientes da utilização de serviços nas áreas de consultorias e assessorias técnicas, ou assemelhadas.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (895, 2, '3.3.2.2.1.02.00.00.00.00', 'PERÍCIAS', 'Registra as variações patrimoniais diminutivas proveniente da utilização de serviços de pericias realizadas por profissionais técnicos.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (896, 2, '3.3.2.2.1.03.00.00.00.00', 'AUDITORIA EXTERNA', 'Registra as variações patrimoniais diminutivas proveniente da utilização de serviços de auditoria.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (897, 2, '3.3.2.2.1.04.00.00.00.00', 'HONORÁRIOS ADVOCATÍCIOS - ÔNUS DE SUCUMBÊNCIA', 'Registra as variações patrimoniais diminutivas proveniente da utilização de serviços advocatícios decorrentes do ônus da sucumbência, entendido este como o ônus que recai sobre a parte vencida numa ação, para pagamento dos honorários advocatícios a vencedora.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (898, 2, '3.3.2.2.1.05.00.00.00.00', 'SERVIÇOS MÉDICOS E ODONTÓLOGICOS', 'Registra as variações patrimoniais diminutivas proveniente da utilização de serviços médicos e odontológicos prestados por pessoa física, sem vínculo empregatício. Consultas - raio x - tratamento odontológico - e outros.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (899, 2, '3.3.2.2.1.06.00.00.00.00', 'SELEÇÃO E TREINAMENTO', 'Registra as variações patrimoniais diminutivas proveniente da utilização de serviços prestados nas áreas de instrução e orientação profissional, recrutamento e seleção de pessoal e treinamento, por pessoa física, inclusive a gratificação por encargo de curso ou concurso, normatizada pelo art. 76-a, da lei 8112/90 e o decreto 6114/2007, bolsa sênior (servidores aposentados do órgão) bolsa de multiplicadores (servidores da ativa do órgão).', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (900, 2, '3.3.2.2.1.07.00.00.00.00', 'COMUNICAÇÃO EM GERAL', 'Registra as variações patrimoniais diminutivas proveniente da utilização de serviços de comunicação geral prestados por pessoa física, tais como: confecção de material p/ comunicação visual; geração de matérias para divulgação por meio dos veículos de comunicação; e outros.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (901, 2, '3.3.2.2.1.08.00.00.00.00', 'LIMPEZA E CONSERVAÇÃO', 'Registra as variações patrimoniais diminutivas proveniente da utilização de serviços de limpeza e conservação de bens imóveis. Dedetização - faxina - e outros.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (902, 2, '3.3.2.2.1.09.00.00.00.00', 'SERVIÇOS DOMÉSTICOS', 'Registra as variações patrimoniais diminutivas proveniente da utilização de serviços domésticos prestados por pessoa física sem vínculo empregatício, tais como: cozinha - lavagem de roupas - e outros.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (903, 2, '3.3.2.2.1.10.00.00.00.00', 'VIGILÂNCIA OSTENSIVA', 'Registra as variações patrimoniais diminutivas proveniente da utilização de serviços de vigilância ostensiva nos casos em que o contrato especifique o quantitativo físico do pessoal a ser utilizado.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (904, 2, '3.3.2.2.1.11.00.00.00.00', 'MANUTENÇÃO E CONSERVAÇÃO', 'Registra as variações patrimoniais diminutivas proveniente da utilização de serviços de manutenção e conservação de bens móveis e imóveis.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (905, 2, '3.3.2.2.1.12.00.00.00.00', 'CONDOMÍNIOS', 'Registra as variações patrimoniais diminutivas proveniente da utilização de serviços condominiais a conta do locatório, quando previstas no contrato de locação.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (906, 2, '3.3.2.2.1.14.00.00.00.00', 'DIREITOS AUTORAIS', 'Registra as variações patrimoniais diminutivas proveniente da utilização de direitos autorais de propriedade de terceiros sobre obras cientificas, literárias, etc, em que a divulgação seja de interesse do governo. Registra o valor referente a utilização de serviços decorrentes de incentivos aos autores a titulo de royalties.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (907, 2, '3.3.2.2.1.15.00.00.00.00', 'SERVIÇOS TÉCNICOS PROFISSIONAIS', 'Registra as variações patrimoniais diminutivas proveniente da utilização de serviços prestados por profissionais técnicos, nas seguintes áreas: administração - advocacia - arquitetura - contabilidade - economia - engenharia - estatística e outras.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (908, 2, '3.3.2.2.1.16.00.00.00.00', 'ESTAGIÁRIOS', 'Registra as variações patrimoniais diminutivas proveniente da utilização de serviços prestados por estudantes na condição de estagiários ou monitores.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (909, 2, '3.3.2.2.1.18.00.00.00.00', 'CAPATAZIA, ESTIVA E PESAGEM', 'Registra as variações patrimoniais diminutivas proveniente da utilização de serviços prestados na movimentação e pesagem de cargas (mercadorias e produtos).', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (910, 2, '3.3.2.2.1.19.00.00.00.00', 'CONFERENCIAS, EXPOSIÇÕES E ESPETÁCULOS', 'Registra as variações patrimoniais diminutivas proveniente da utilização de serviços prestados por conferencistas, expositores e artistas pelos serviços prestados.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (911, 2, '3.3.2.2.1.20.00.00.00.00', 'ARMAZENAGEM', 'Registra as variações patrimoniais diminutivas proveniente da utilização de serviços de aluguel de galpões, silos e outros locais destinados a armazenagem de mercadorias e produtos. Inclui, ainda, os dispêndios de garantia dos estoques armazenados.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3305, 2, '8.1.1.1.1.01.08.00.00.00', 'SEGUROS-GARANTIA EXECUTADAS', 'REGISTRA O VALOR RECEBIDO DOS SEGUROS-GARANTIA, NO PAÍS.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (913, 2, '3.3.2.2.1.22.00.00.00.00', 'FORNECIMENTO DE ALIMENTAÇÃO', 'Registra as variações patrimoniais diminutivas proveniente da utilização de refeições preparadas, inclusive lanches e similares.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (914, 2, '3.3.2.2.1.23.00.00.00.00', 'SERVIÇOS DE CARÁTER SECRETO OU RESERVADO', 'Registra as variações patrimoniais diminutivas proveniente da utilização de serviços de caráter sigiloso constantes em regulamento do órgão.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (915, 2, '3.3.2.2.1.24.00.00.00.00', 'SERVIÇOS DE REABILITAÇÃO PROFISSIONAL', 'Registra as variações patrimoniais diminutivas proveniente da utilização de serviços de reabilitação profissional prestados por pessoa física sem vínculo empregatício, como objetivo de proporcionar aos incapacitados (parcial ou totalmente) os meios indicados para a reeducação e readaptação profissional e social, de modo que possam voltar a participar do mercado de trabalho. Ex.: contratação de profissional para ministrar curso profissionalizante.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (916, 2, '3.3.2.2.1.25.00.00.00.00', 'SERVIÇOS DE ASSISTÊNCIA SOCIAL', 'Registra as variações patrimoniais diminutivas proveniente da utilização de serviços de assistência social prestados por pessoa física sem vínculo empregatício a servidores, segurados carentes, abrigados, internados e a seus dependentes, tais como ajuda de custo supletiva, gêneros alimentícios, documentação, transporte e sepultamento.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (917, 2, '3.3.2.2.1.26.00.00.00.00', 'SERV. DE APOIO ADMIN., TÉCNICO E OPERACIONAL', 'Registra as variações patrimoniais diminutivas provenientes da utilização de serviços de natureza eventual prestados por pessoa física, tais como: assistência técnica - capina - jardinagem - operadores de máquinas e motoristas - recepcionistas - serviços auxiliares - e outros.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (918, 2, '3.3.2.2.1.27.00.00.00.00', 'SERV. DE CONSERV. E REBENEFIC. DE MERCADORIAS', 'Registra as variações patrimoniais diminutivas proveniente da utilização de serviços de natureza eventual prestados por pessoa física na conservação e rebeneficiamento de mercadorias.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (919, 2, '3.3.2.2.1.28.00.00.00.00', 'CONFECÇÃO DE MATERIAL DE ACONDIC. E EMBALAGEM', 'Registra as variações patrimoniais diminutivas proveniente da utilização de serviços prestados por pessoa física na confecção de: bolsas - caixas - mochilas - sacolas - e outros.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (920, 2, '3.3.2.2.1.29.00.00.00.00', 'CONFECÇÃO DE UNIFORMES, BANDEIRAS E FLÂMULAS', 'Registra as variações patrimoniais diminutivas proveniente da utilização de serviços de costureiras, alfaiates e afins utilizados na confecção de uniformes, bandeiras, flâmulas, brasões e estandartes.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (921, 2, '3.3.2.2.1.30.00.00.00.00', 'FRETES E TRANSPORTES DE ENCOMENDAS', 'Registra as variações patrimoniais diminutivas proveniente da utilização de serviços prestados por pessoa física em: fretes e carretos - remessa de encomendas - transporte de mercadorias e produtos - e outros.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (922, 2, '3.3.2.2.1.31.00.00.00.00', 'JETONS E GRATIFICAÇÕES A CONSELHEIROS', 'Registra as variações patrimoniais diminutivas proveniente da participação em órgãos de deliberações coletivas (conselhos).', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (923, 2, '3.3.2.2.1.34.00.00.00.00', 'SERVIÇOS DE ÁUDIO, VÍDEO E FOTO', 'Registra as variações patrimoniais diminutivas proveniente da utilização de serviços de filmagens, gravações e fotografias, prestados por pessoa física.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (924, 2, '3.3.2.2.1.35.00.00.00.00', 'SERVIÇOS JUDICIÁRIOS', 'Registra as variações patrimoniais diminutivas proveniente da apropriação de custas processuais decorrentes de ações judiciais, diligências (inclusive condução) salários e honorários dos avaliadores, peritos judiciais e serviços de cartório, quando a nota é emitida em nome do tabelião.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (925, 2, '3.3.2.2.1.36.00.00.00.00', 'SEGUROS EM GERAL', 'Registra as variações patrimoniais diminutivas proveniente da apropriação de prêmios pagos por seguros de qualquer natureza, inclusive cobertura de danos causados a pessoas ou bens de terceiros, prêmios de seguros de bens do estado ou de terceiros, seguro obrigatório de veículos.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (926, 2, '3.3.2.2.1.37.00.00.00.00', 'HOSPEDAGENS', 'Registra as variações patrimoniais diminutivas proveniente da utilização de serviços de hospedagens de servidores e convidados do governo em viagens, a locais onde não existem estabelecimentos comerciais habilitados em prestar esse tipo de serviços, pagos diretamente a pessoas físicas.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (927, 2, '3.3.2.2.1.38.00.00.00.00', 'DESPESAS COM LOCOMOÇÃO', 'Registra as variações patrimoniais diminutivas proveniente da utilização de meios de transportes aéreos, terrestres, fluviais ou marítimas, locação ou uso de veículos para transporte de pessoas e suas respectivas bagagens, inclusive quando ocorrer em decorrência de mudanças de domicílio no interesse da administração.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (928, 2, '3.3.2.2.1.39.00.00.00.00', 'SERVIÇOS GRÁFICOS E EDITORIAIS', 'Registra as variações patrimoniais diminutivas com serviços de artes gráficas prestados  por pessoa física, bem como com serviços editoriais diversos. Confecção de impressos em geral - encadernação de livros jornais e revistas - impressão de jornais - boletins - encartes - folders e assemelhados - plastificação de impressos - serviços de identificação de livros editados usando código de barras - serviços editoriais diversos.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (929, 2, '3.3.2.2.1.99.00.00.00.00', 'OUTROS SERVIÇOS PRESTADOS POR PESSOA FÍSICA', 'Registra as variações patrimoniais diminutivas provenientes da utilização de outros serviços prestados por pessoa física, não contemplados em itens específicos.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (930, 2, '3.3.2.3.1.01.00.00.00.00', 'CONSULTORIA E ASSESSORIA', 'Registra as variações patrimoniais diminutivas provenientes da utilização de serviços nas áreas de consultorias e assessorias técnicas, ou assemelhadas.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (931, 2, '3.3.2.3.1.02.00.00.00.00', 'PERÍCIAS', 'Registra as variações patrimoniais diminutivas proveniente da utilização de serviços de pericias realizadas por empresas especializadas.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (932, 2, '3.3.2.3.1.03.00.00.00.00', 'AUDITORIA EXTERNA', 'Registra as variações patrimoniais diminutivas provenientes da utilização de serviços de auditoria externa.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (933, 2, '3.3.2.3.1.04.00.00.00.00', 'COMUNICAÇÃO', 'Registra as variações patrimoniais diminutivas provenientes da utilização de serviços de comunicação, prestados por pessoa jurídica.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (934, 2, '3.3.2.3.1.05.00.00.00.00', 'PUBLICIDADE', 'Registra as variações patrimoniais diminutivas provenientes da utilização de serviços de publicidade.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (935, 2, '3.3.2.3.1.06.00.00.00.00', 'MANUTENÇÃO E CONSERVAÇÃO', 'Registra as variações patrimoniais diminutivas provenientes da utilização de serviços de manutenção de bens móveis e imóveis.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (936, 2, '3.3.2.3.1.07.00.00.00.00', 'SERVIÇOS DE APOIO', 'Registra as variações patrimoniais diminutivas provenientes da utilização de serviços prestados por pessoa jurídica a título de apoio as atividades administrativas, técnicas e operacionais dos órgãos públicos, nos casos em que o contrato não especifique o quantitativo físico do pessoal a ser utilizado.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (937, 2, '3.3.2.3.1.08.00.00.00.00', 'SERVIÇOS DE ÁGUA E ESGOTO, ENERGIA ELÉTRICA, GÁS E OUTROS', 'Registra as variações patrimoniais diminutivas provenientes da utilização de serviços de água e esgoto, energia elétrica, gás e outros.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (939, 2, '3.3.2.3.1.11.00.00.00.00', 'SERVIÇOS RELACIONADOS À TECNOLOGIA DA INFORMAÇÃO', 'Registra as variações patrimoniais diminutivas provenientes da utilização de serviços de processamento de dados prestados por empresas especializadas na área de informática; atualização e adaptação de programas de processamento de dados; suporte técnico, revisão, correção de problemas operacionais, análise p/acrescentar novas funções, hospedagem de sistemas e outros.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (940, 2, '3.3.2.3.1.12.00.00.00.00', 'SERVIÇOS DE TRANSPORTE', 'Registra as variações patrimoniais diminutivas provenientes da utilização de serviços de transporte de servidores, trabalhadores de uma entidade ou de mercadorias e produtos diversos.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (941, 2, '3.3.2.3.1.13.00.00.00.00', 'ARMAZENAGEM', 'Registra as variações patrimoniais diminutivas provenientes da utilização de serviços de aluguel de galpões, silos e outros locais destinados a armazenagem de mercadorias e produtos. Inclui, ainda, as variações provenientes de garantia dos estoques armazenados e a utilização de serviço especializado na solução de gestão de estoque, incluindo gestão de materiais e transporte de materiais e equipamentos.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (942, 2, '3.3.2.3.1.14.00.00.00.00', 'ASSINATURAS DE PERIODICOS E ANUIDADES', 'Registra as variações patrimoniais diminutivas provenientes da utilização de assinaturas de TV (TV a cabo), jornais, inclusive diário oficial, revistas, recortes de publicações, software, podendo estar na forma de disquete, CD-ROM, boletins e outros que não se destinem a coleções ou bibliotecas.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (943, 2, '3.3.2.3.1.15.00.00.00.00', 'CAPATAZIA, ESTIVA E PESAGEM', 'Registra as variações patrimoniais diminutivas provenientes da utilização de serviços de movimentação e pesagem de cargas (mercadorias e produtos).', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (944, 2, '3.3.2.3.1.17.00.00.00.00', 'COMISSÕES E CORRETAGENS', 'Registra as variações patrimoniais diminutivas provenientes da apropriação de valor referente a comissões e corretagens decorrentes de serviços prestados por empresas de intermediação e representação comercial.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (945, 2, '3.3.2.3.1.18.00.00.00.00', 'CONDOMÍNIOS', 'Registra as variações patrimoniais diminutivas provenientes da apropriação das taxas condominiais a conta do proprietário, ou do locatário, conforme previsto no contrato de locação.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (946, 2, '3.3.2.3.1.19.00.00.00.00', 'CONFECÇÃO DE MATERIAL DE ACONDIC. E EMBALAGEM', 'Registra as variações patrimoniais diminutivas provenientes da utilização de serviços de confecção de materiais destinados a preservação, acomodação ou embalagem de produtos diversos, tais como: - bolsas - caixas - mochilas - sacolas e outros. Somente serão classificados como serviços, caso a unidade forneça a matéria-prima.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (947, 2, '3.3.2.3.1.20.00.00.00.00', 'CONFECÇÃO DE UNIFORMES, BANDEIRAS E FLÂMULAS', 'Registra as variações patrimoniais diminutivas provenientes da utilização de serviços de confecção de: - bandeiras - brasões - estandartes - flâmulas - uniformes (inclusive as despesas relacionadas com auxílio fardamento descritos na lei nº  8.237/91) e outros. Somente serão classificados como serviços, caso a unidade forneça a matéria-prima.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (948, 2, '3.3.2.3.1.21.00.00.00.00', 'DIREITOS AUTORAIS', 'Registra as variações patrimoniais diminutivas provenientes da utilização de direitos autorais sobre obras científicas, literárias ou em que a divulgação seja de interesse do governo.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (949, 2, '3.3.2.3.1.22.00.00.00.00', 'EXPOSIÇÕES, CONGRESSOS, CONFERÊNCIAS E OUTROS', 'Registra as variações patrimoniais diminutivas provenientes de serviços utilizados na instalação e manutenção de: conferencias - reuniões técnicas - congressos - exposições - feiras - festejos populares - festivais - e outros.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (950, 2, '3.3.2.3.1.23.00.00.00.00', 'FESTIVIDADES E HOMENAGENS', 'Registra as variações patrimoniais diminutivas provenientes de serviços utilizados na organização de eventos, tais como: coquetéis - festas de congraçamento - recepções - e outras.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (951, 2, '3.3.2.3.1.45.00.00.00.00', 'SERVIÇOS FUNERÁRIOS', 'Registra as variações patrimoniais diminutivas proveniente da utilização de serviços de remoções, sepultamentos e transladações.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (952, 2, '3.3.2.3.1.24.00.00.00.00', 'HONORÁRIOS ADVOCATÍCIOS - ÔNUS DE SUCUMBÊNCIA', 'Registra as variações patrimoniais diminutivas provenientes da apropriação dos honorários advocatícios decorrentes do ônus da sucumbência, entendido este como o ônus que recai sobre a parte vencida numa ação, para pagamento dos honorários advocatícios a vencedora.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (953, 2, '3.3.2.3.1.25.00.00.00.00', 'HOSPEDAGENS', 'Registra as variações patrimoniais diminutivas provenientes da utilização de serviços de hospedagens e alimentação de servidores e convidados do governo em viagens oficiais pagos diretamente a estabelecimentos hoteleiros (quando não houver pagamento de diárias).', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (954, 2, '3.3.2.3.1.26.00.00.00.00', 'PATROCÍNIO', 'Registra as variações patrimoniais diminutivas provenientes da utilização de patrocínios a atividades ou eventos, de natureza cultural, esportiva, educacional, ambiental, cientifica, comunitária, promocional etc. Para influenciar favoravelmente o público e/ou atingir outros objetivos relacionados com a promoção de atos, obras, planos, ações, bens ou serviços. Não inclui o patrocínio de mídia, assim considerados aqueles em que o proponente e um veículo de comunicação ou um gestor de meios ou instalações que funcionem como veículo de mídia alternativa e aqueles em que um veículo de comunicação e o único ou o principal realizador da ação patrocinada, ainda que o proponente do projeto e provedor de conteúdo para a ação patrocinada não se enquadre na definição de veículo de comunicação ou meio de mídia alternativa.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (955, 2, '3.3.2.3.1.27.00.00.00.00', 'PRODUÇÕES JORNALÍSTICAS', 'Registra as variações patrimoniais diminutivas provenientes da utilização de serviços de edição de jornais, revistas, noticiários e materiais jornalísticos para vídeos.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (956, 2, '3.3.2.3.1.28.00.00.00.00', 'PROMOÇÃO', 'Registra as variações patrimoniais diminutivas provenientes da utilização de serviços realizados por integrantes do SICOM ou por terceiros, que empreguem recursos de não-mídia, realizadas com objetivo de incentivar públicos de interesse a conhecerem ou comprarem produtos, serviços, marcas, conceitos ou políticas públicas.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (957, 2, '3.3.2.3.1.29.00.00.00.00', 'SEGUROS EM GERAL', 'Registra as variações patrimoniais diminutivas provenientes da apropriação de prêmios pagos por seguros de qualquer natureza, inclusive cobertura de danos causados a pessoas ou bens de terceiros, prêmios de seguros de bens do estado ou de terceiros, seguro obrigatório de veículos.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1042, 2, '3.5.1.1.2.13.00.00.00.00', 'CORRESPONDÊNCIA DE CRÉDITOS - SALDOS FINANCEIROS', 'Registra a apropriação da transferência de créditos internos entre UG de mesma gestão referentes a contas com saldos financeiras em rotinas contábeis orçamentárias.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (958, 2, '3.3.2.3.1.30.00.00.00.00', 'SELEÇÃO E TREINAMENTO', 'Registra as variações patrimoniais diminutivas provenientes da utilização de serviços prestados nas áreas de instrução e orientação profissional, recrutamento e seleção de pessoal (concurso público) e treinamento.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (959, 2, '3.3.2.3.1.99.00.00.00.00', 'OUTROS SERVIÇOS TERCEIROS - PJ', 'Registra as variações patrimoniais diminutivas provenientes das demais prestação de serviços por pessoa jurídica fornecida a entidade governamental.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (960, 2, '1.2.3.2.1.99.00.00.00.00', 'DEMAIS BENS IMÓVEIS', 'Compreende os demais bens imóveis não classificados anteriormente nesse plano de contas.', 1, false, 0, ' ');
insert into contabilidade.planocontadetalhe values (961, 2, '3.3.2.3.1.31.00.00.00.00', 'SERV. MÉDICO-HOSPITALAR, ODONTOL. E LABORATORIAIS', 'Registra as variações patrimoniais diminutivas provenientes da utilização de serviços médico-hospitalares, odontológicos e laboratoriais, prestados por pessoas jurídicas sem vínculo empregatício, tais como: análises clínicas - cirurgias - consultas - ecografias - endoscopias - enfermagem - esterilização - exames de laboratório - raio x - tomografias - tratamento odontológico - ultrassonografias - e outros.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (962, 2, '3.3.2.3.1.32.00.00.00.00', 'SERVIÇOS BANCÁRIOS', 'Registra as variações patrimoniais diminutivas provenientes da apropriação de comissões, tarifas e remunerações decorrentes de serviços prestados por bancos e outras instituições financeiras, bem como despesas com a guarda/custódia de valores (cofres de aluguel).', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (963, 2, '3.3.2.3.1.33.00.00.00.00', 'SERVIÇOS DE ANÁLISES E PESQUISA CIENTÍFICAS', 'Registra as variações patrimoniais diminutivas provenientes da utilização de serviços de análises físico-químicas e pesquisas científicas, não relacionadas com apoio ao ensino, tais como: análises minerais - análises de solo - análises químicas - coleta de dados em experimentos - tratamento e destinação de resíduos e outros.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (964, 2, '3.3.2.3.1.34.00.00.00.00', 'SERVIÇOS DE APOIO DO ENSINO', 'Registra as variações patrimoniais diminutivas provenientes da utilização de serviços com o objetivo de proporcionar o desenvolvimento e o aperfeiçoamento do ensino, em todos os níveis, inclusive pesquisas experiências e assemelhados.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (965, 2, '3.3.2.3.1.35.00.00.00.00', 'SERVIÇOS DE ASSISTÊNCIA SOCIAL', 'Registra as variações patrimoniais diminutivas provenientes de serviços de assistência social prestada a servidores, segurados carentes, abrigados, internados e a seus dependentes, tais como: - ajuda de custo supletiva - gêneros alimentícios - documentação - transporte e sepultamento.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (966, 2, '3.3.2.3.1.36.00.00.00.00', 'SERVIÇOS DE ÁUDIO VÍDEO E FOTO', 'Registra as variações patrimoniais diminutivas provenientes da utilização de serviços de filmagens, gravações, revelações, ampliações e reproduções de sons e imagens, tais como: confecção de álbuns - confecção de crachás funcionais por firmas especializadas - emolduramento de fotografias - imagens de satélites - revelação de filmes - microfilmagem e outros.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (967, 2, '3.3.2.3.1.38.00.00.00.00', 'SERVIÇOS DE CONSERV. E REBENEF. DE MERCADORIAS', 'Registra as variações patrimoniais diminutivas provenientes da utilização de serviços utilizados na conservação e rebeneficiamento de mercadorias.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (968, 2, '3.3.2.3.1.39.00.00.00.00', 'SERVIÇOS DE CONTROLE AMBIENTAL', 'Registra as variações patrimoniais diminutivas provenientes da utilização de serviços de controle ambiental.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (969, 2, '3.3.2.3.1.40.00.00.00.00', 'SERVIÇOS DE CÓPIAS E REPRODUÇÃO DE DOCUMENTOS', 'Registra as variações patrimoniais diminutivas provenientes da utilização de serviços de copias xerográficas, inclusive a locação e a manutenção de equipamentos reprográficos, cópias e reproduções de documentos e publicações em geral, inclusive por meio magnético e digitalização.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (970, 2, '3.3.2.3.1.41.00.00.00.00', 'SERVIÇOS DE CRECHE E ASSISTÊNCIA PRÉ ESCOLAR', 'Registra as variações patrimoniais diminutivas proveniente da utilização de serviços prestados por entidades de assistência social para atender os dependentes de servidores do órgão, habilitados a usufruírem desse benefício.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (971, 2, '3.3.2.3.1.42.00.00.00.00', 'SERVIÇOS DE INCINERAÇÃO/DESTRUIÇÃO DE MATERIAL', 'Registra as variações patrimoniais diminutivas proveniente da utilização de serviço de processo de incineração e destruição de materiais, bem como resíduos industriais.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (972, 2, '3.3.2.3.1.43.00.00.00.00', 'SERVIÇOS DE PRODUÇÃO INDUSTRIAL', 'Registra as variações patrimoniais diminutivas proveniente da utilização de serviços de transformação, beneficiamento e industrialização de matérias-primas que resultarão em um produto final. Somente serão classificados como serviços, caso a unidade forneça a matéria-prima.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (973, 2, '3.3.2.3.1.44.00.00.00.00', 'SERVIÇOS DE REABILITAÇÃO PROFISSIONAL', 'Registra as variações patrimoniais diminutivas proveniente da utilização de serviços de reabilitação profissional prestados por pessoa jurídica, com o objetivo de proporcionar aos incapacitados (parcial ou totalmente), os meios indicados para a reeducação e readaptação profissional e social, de modo que possam voltar a participar do mercado de trabalho. Ex.: contratação de empresa para ministrar curso profissionalizante.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (974, 2, '3.3.2.3.1.46.00.00.00.00', 'SERVIÇOS GRÁFICOS E EDITORIAIS', 'Registra as variações patrimoniais diminutivas proveniente da utilização de serviços de artes gráficas prestados por pessoa jurídica, bem como com serviços editoriais diversos. - Confecção de impressos em geral - encadernação de livros jornais e revistas - impressão de jornais - boletins - encartes - folders e assemelhados - plastificação de impressos - serviços de identificação de livros editados usando código de barras - serviços editoriais diversos.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (975, 2, '3.3.2.3.1.47.00.00.00.00', 'SERVIÇOS JUDICIÁRIOS', 'Registra as variações patrimoniais diminutivas proveniente da apropriação de custas processuais decorrentes de ações judiciais, diligencias (inclusive condução) salários e honorários dos avaliadores, peritos judiciais e oficiais de justiça e serviços de cartório.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (976, 2, '3.3.2.3.1.51.00.00.00.00', 'SERVIÇOS TÉCNICOS PROFISSIONAIS', 'Registra as variações patrimoniais diminutivas proveniente da utilização de serviços prestados por empresas especializadas nas seguintes áreas: advocacia - arquitetura - contabilidade - economia - engenharia - estatística e outras. Exceto os serviços de consultoria que devem ser classificados em conta específica.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (998, 2, '3.4.1.2.1.01.00.00.00.00', 'JUROS DA DÍVIDA CONTRATADA NO EXTERIOR', 'Registra a variação patrimonial diminutiva com juros da dívida pública contratada no exterior com vistas a execução de obras, fornecimento de bens ou prestação de serviços, ou da celebração de contratos de financiamento.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (977, 2, '3.3.2.3.1.52.00.00.00.00', 'TAXA DE ADMINISTRAÇÃO', 'Registra as variações patrimoniais diminutivas proveniente da utilização de serviços de organização e administração prestados por pessoa jurídica, tais como: - taxa de administração paga ao instituto Euvaldo Lodi IEl e ao centro de integração empresa-escola - CIEE, decorrente dos serviços de seleção e recrutamento de estudantes, tendo como objetivo o ingresso ao mercado de trabalho e programas de estágio; - taxa de administração patrimonial das contribuições do Banco Central do Brasil, na qualidade de patrocinador, destinado ao custeio das aposentadorias e pensões concedidas com base na Lei 8.112/1990, e outros.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (978, 2, '3.3.2.3.1.54.00.00.00.00', 'LOCAÇÃO DE MÃO-DE-OBRA', 'Registra as variações patrimoniais diminutivas proveniente da utilização de serviços prestados por pessoas jurídicas para órgãos públicos, tais como limpeza e higiene, vigilância ostensiva e outros, nos casos em que o contrato especifique o quantitativo físico do pessoal a ser utilizado.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (979, 2, '3.3.2.3.1.55.00.00.00.00', 'ARRENDAMENTO MERCANTIL OPERACIONAL', 'REGISTRA AS VARIAÇÕES PATRIMONIAIS DIMINUTIVAS PROVENIENTES DE ARRENDAMENTO MERCANTIL OPERACIONAL', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (980, 2, '3.4.2.1.3.02.00.00.00.00', 'ENCARGOS DE MORA', 'Registra a variação patrimonial diminutiva decorrente de encargos a título de penalidade em virtude de atrasos e/ou não cumprimento dos prazos contratuais dos empréstimos e financiamentos internos contraídos com pessoas jurídicas de direito público ou privado.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (981, 2, '3.3.2.3.1.56.00.00.00.00', 'PASSAGENS E DESPESAS COM LOCOMOÇÃO', 'Registra as variações patrimoniais diminutivas proveniente da utilização de passagens (aéreas, terrestres, fluviais ou marítimas), taxas de embarque, seguros, fretamento, pedágios, locação ou uso de veículos para transporte de pessoas e suas respectivas bagagens, inclusive quando ocorrer em decorrência de mudanças de domicilio no interesse da administração.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (982, 2, '3.3.3.1.1.01.02.00.00.00', 'DEPRECIAÇÃO DE BENS IMÓVEIS', 'Registra a redução do valor dos bens imóveis pelo desgaste ou perda de utilidade por uso, ação da natureza ou obsolescência.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (983, 2, '3.3.3.2.1.01.00.00.00.00', 'AMORTIZAÇÃO DE IMOBILIZADO', 'Registra a redução do valor aplicado na aquisição de direitos, do ativo imobilizado, com existência ou exercício de duração limitada, ou cujo objeto seja bem de utilização por prazo legal ou contratualmente limitado.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (984, 2, '3.3.3.2.1.02.00.00.00.00', 'AMORTIZAÇÃO DE INTANGÍVEL', 'Registra a redução do valor aplicado na aquisição de direitos de propriedade e quaisquer outros, inclusive ativos intangíveis, com existência ou exercício de duração limitada, ou cujo objeto sejam bens de utilização por prazo legal ou contratualmente limitado.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (985, 2, '3.5.1.2.2.02.04.00.00.00', 'DOAÇÕES CONCEDIDAS DE BENS MÓVEIS ', 'Registra o valor das doações de bens móveis entre unidades de órgãos diferentes.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (986, 2, '3.4.1.1.1.01.00.00.00.00', 'JUROS DA DÍVIDA CONTR. C/INSTIT. FINANCEIRAS', 'Registra a variação patrimonial diminutiva com juros da dívida pública derivada de obrigações assumidas com instituições financeiras com vistas a execução de obras, fornecimento de bens ou prestação de serviços, ou da celebração de contratos de financiamento.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (987, 2, '3.4.1.1.1.02.00.00.00.00', 'ENCARGOS DA DÍVIDA CONTR. C/INSTIT. FINANCEIRAS', 'Registra a variação patrimonial diminutiva com encargos da dívida pública derivada de obrigações assumidas com instituições financeiras com vistas a execução de obras, fornecimento de bens ou prestação de serviços, ou da celebração de contratos de financiamento.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (988, 2, '3.4.1.1.1.99.00.00.00.00', 'JUROS E ENCARGOS DE OUTRAS DÍVIDAS CONTRATUAIS', 'Registra a variação patrimonial diminutiva provenientes de juros e encargos de outras dívidas contratadas.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (989, 2, '3.4.1.1.3.01.00.00.00.00', 'JUROS DA DÍVIDA CONTR. INTERNA INTER OFSS - UNIÃO', 'Registra a variação patrimonial diminutiva com juros da dívida pública derivada de obrigações assumidas com a união com vistas a execução de obras, fornecimento de bens ou prestação de serviços, ou da celebração de contratos de financiamento.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (990, 2, '3.4.1.1.3.02.00.00.00.00', 'ENCARGOS DA DÍVIDA CONTR. INTERNA INTER OFSS - UNIÃO', 'Registra a variação patrimonial diminutiva com encargos da dívida pública derivada de obrigações assumidas com a união com vistas a execução de obras, fornecimento de bens ou prestação de serviços, ou da celebração de contratos de financiamento.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (991, 2, '3.4.1.1.3.99.00.00.00.00', 'JUROS E ENCARGOS DE OUTRAS DÍVIDAS CONTRATUAIS - INTERNA INTER OFSS - UNIÃO', 'Registra a variação patrimonial diminutiva provenientes de juros e encargos de outras dívidas contratadas.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (992, 2, '3.4.1.1.4.01.00.00.00.00', 'JUROS DA DÍVIDA CONTR. INTERNA INTER OFSS - ESTADO', 'Registra a variação patrimonial diminutiva com juros da dívida pública derivada de obrigações assumidas com os estados com vistas a execução de obras, fornecimento de bens ou prestação de serviços, ou da celebração de contratos de financiamento.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (993, 2, '3.4.1.1.4.02.00.00.00.00', 'ENCARGOS DA DÍVIDA CONTR. INTERNA INTER OFSS - ESTADO', 'Registra a variação patrimonial diminutiva com encargos da dívida pública derivada de obrigações assumidas com os estados com vistas a execução de obras, fornecimento de bens ou prestação de serviços, ou da celebração de contratos de financiamento.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (994, 2, '3.4.1.1.4.99.00.00.00.00', 'JUROS E ENCARGOS DE OUTRAS  DÍVIDAS CONTRATUAIS - INTERNA INTER OFSS - ESTADO', 'Registra a variação patrimonial diminutiva provenientes de juros e encargos de outras dívidas contratadas.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (995, 2, '3.4.1.1.5.01.00.00.00.00', 'JUROS DA DÍVIDA CONTR. INTERNA INTER OFSS - MUNICÍPIO', 'Registra a variação patrimonial diminutiva com juros da dívida pública derivada de obrigações assumidas com os municípios com vistas a execução de obras, fornecimento de bens ou prestação de serviços, ou da celebração de contratos de financiamento.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (996, 2, '3.4.1.1.5.02.00.00.00.00', 'ENCARGOS DA DÍVIDA CONTR. INTERNA INTER OFSS - MUNICÍPIO', 'Registra a variação patrimonial diminutiva com encargos da dívida pública derivada de obrigações assumidas com os municípios com vistas a execução de obras, fornecimento de bens ou prestação de serviços, ou da celebração de contratos de financiamento.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (997, 2, '3.4.1.1.5.99.00.00.00.00', 'JUROS E ENCARGOS DE OUTRAS  DÍVIDAS CONTRATUAIS - INTERNA INTER OFSS - MUNICÍPIO', 'Registra a variação patrimonial diminutiva provenientes de juros e encargos de outras dívidas contratadas.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1043, 2, '3.5.1.2.2.02.01.00.00.00', 'TRANSFERÊNCIAS CONCEDIDAS DE BENS IMÓVEIS', 'Registra o valor das transferências de bens imóveis entre unidades do mesmo órgão.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (999, 2, '3.4.1.2.1.02.00.00.00.00', 'ENCARGOS DA DÍVIDA CONTRATADA NO EXTERIOR', 'Registra a variação patrimonial diminutiva com encargos da dívida pública contratada no exterior com vistas a execução de obras, fornecimento de bens ou prestação de serviços, ou da celebração de contratos de financiamento.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1000, 2, '3.4.1.4.1.01.00.00.00.00', 'JUROS S/ ADIANTAMENTOS BANCÁRIOS', 'Registra a variação patrimonial diminutiva decorrente de juros incidentes sobre antecipações de créditos contratadas com bancos e outros agentes financeiros.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1001, 2, '3.5.2.1.4.05.00.00.00.00', 'RESTITUIÇÃO DE IPVA', 'Registra o valor das variações patrimoniais diminutivas com restituições de IPVA.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1002, 2, '3.4.2.1.1.01.00.00.00.00', 'JUROS DE MORA ', 'Registra a variação patrimonial diminutiva decorrente de juros a título de penalidade em virtude de atrasos e/ou não cumprimento dos prazos contratuais dos empréstimos e financiamentos internos contraídos com pessoas jurídicas de direito público ou privado.', 1, true, 2, 'N');
