insert into contabilidade.planocontadetalhe values (1005, 2, '3.6.2.2.1.01.08.00.00.00', 'PERDAS COM ALIENAÇÃO DE BENS MÓVEIS EM ALMOXARIFADO', 'Registra a variação patrimonial diminutiva de perdas com alienação de bens móveis em almoxarifado.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1006, 2, '3.4.2.1.4.01.00.00.00.00', 'JUROS DE MORA', 'Registra a variação patrimonial diminutiva decorrente de juros a título de penalidade em virtude de atrasos e/ou não cumprimento dos prazos contratuais dos empréstimos e financiamentos internos contraídos com pessoas jurídicas de direito público ou privado.', 1, true, 2, 'N');
