insert into contabilidade.planocontadetalhe values (1010, 2, '3.4.2.2.1.01.00.00.00.00', 'JUROS DE MORA', 'Registra a variação patrimonial diminutiva decorrente de juros a título de penalidade em virtude de atrasos e/ou não cumprimento dos prazos contratuais dos empréstimos e financiamentos internos contraídos com pessoas jurídicas de direito público ou privado.', 1, true, 2, 'N');
