insert into contabilidade.planocontadetalhe values (1012, 2, '3.4.2.3.1.01.01.00.00.00', 'JUROS DE  SERVICOS TERCEIROS - PESSOA FÍSICA', 'Registra a variação patrimonial diminutiva com juros referentes a penalidade em virtude de atrasos e não cumprimento dos prazos dos contratos de prestação de serviços com pessoa física.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1013, 2, '3.4.2.3.1.01.02.00.00.00', 'JUROS DE SERVICOS TERCEIROS - PESSOA JURÍDICA', 'Registra a variação patrimonial diminutiva com juros referentes a penalidade em virtude de atrasos e não cumprimento dos prazos dos contratos de prestação de serviços com pessoa jurídica.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1014, 2, '3.4.2.3.1.99.01.00.00.00', 'OUTROS ENCARGOS S/ SERVIÇOS TERCEIROS - PESSOA FÍSICA', 'Registra a variação patrimonial diminutiva com outros encargos referentes a penalidade em virtude de atrasos e não cumprimento dos prazos dos contratos de prestação de serviços com pessoas físicas, que não se enquadrem nos itens anteriores.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1015, 2, '3.4.2.3.1.99.02.00.00.00', 'OUTROS ENCARGOS S/ SERVIÇOS TERCEIROS - PESSOA JURÍDICA', 'Registra a variação patrimonial diminutiva com outros encargos referentes a penalidade em virtude de atrasos e não cumprimento dos prazos dos contratos de prestação de serviços com pessoas jurídicas, que não se enquadrem nos itens anteriores.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1016, 2, '3.4.2.3.1.99.03.00.00.00', 'OUTROS ENCARGOS S/ FONECIMENTO DE BENS', 'Registra a variação patrimonial diminutiva com outros encargos referentes a penalidade em virtude de atrasos e não cumprimento dos prazos dos contratos de aquisição de bens, que não se enquadrem nos itens anteriores.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1017, 2, '3.4.2.4.1.01.00.00.00.00', 'JUROS', 'Registra a variação patrimonial diminutiva com juros a título de penalidade em virtude de atrasos e não cumprimento dos prazos de obrigações tributárias devidas.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1018, 2, '3.4.2.4.1.02.00.00.00.00', 'MULTAS DEDUTÍVEIS', 'Registra a variação patrimonial diminutiva com multas resultantes do pagamento com atraso das obrigações tributárias, como também as multas pagas pelo descumprimento de obrigações acessórias exigidas pela legislação tributária. As multas pagas pela administração pública estão sujeitas ao direito de regresso contra aqueles que lhes deram causa. Esta conta registra as multas consideradas dedutíveis pela legislação na determinação do lucro real, ou seja, apenas as multas por infrações fiscais de natureza compensatória e as impostas por infrações de que não resultem falta ou insuficiência de pagamento de tributo (Art. 344., §5º do Decreto 3.000, de 26 de marco de 1999 - RIR/99).', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1037, 2, '3.5.1.1.2.02.00.00.00.00', 'REPASSE CONCEDIDO  ', 'Registra a variação patrimonial diminutiva relativa ao valor dos recursos concedidos a titulo de transferências financeiras entre órgãos diferentes da administração direta ou indireta, correspondentes ao orçamento anual.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1038, 2, '3.5.1.1.2.04.00.00.00.00', 'RECURSOS ARRECADADOS - CONCEDIDOS ', 'Registra a variação patrimonial diminutiva relativa ao valor concedido para outra UG, referente a recursos que foram arrecadados (classificados como receita), para pagamento de variação patrimonial diminutiva na UG recebedora.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1019, 2, '3.4.2.4.1.03.00.00.00.00', 'MULTAS INDEDUTÍVEIS', 'Registra a variação patrimonial diminutiva com multas resultantes do pagamento com atraso das obrigações tributárias, como também as multas pagas pelo descumprimento de obrigações acessórias exigidas pela legislação tributária. As multas pagas pela administração pública estão sujeitas ao direito de regresso contra aqueles que lhes deram causa. Esta conta registra as multas consideradas indedutíveis pela legislação na determinação do lucro real, ou seja, todas as multas por infrações fiscais, salvo as de natureza compensatória e as impostas por infrações de que não resultem falta ou insuficiência de pagamento de tributo (art. 344., §5º do decreto 3.000, de 26 de marco de 1999 -rir/99).', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1020, 2, '3.4.3.1.1.01.00.00.00.00', 'VARIAÇÕES MONETÁRIAS DE DÍVIDA CONTRATUAL INTERNA - CONSOLIDAÇÃO', 'Registra a Variação Patrimonial Diminutiva proveniente de Variações da nossa própria moeda em relação aos índices ou coeficientes aplicáveis por dispositivo legal ou contratual referentes a Dívida Contratual. Ressalte-se será tratada como variação monetária apenas a Correção Monetária Pós-Fixada.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1021, 2, '3.4.3.1.1.02.00.00.00.00', 'VARIAÇÕES CAMBIAIS DE DÍVIDA CONTRATUAL INTERNA - CONSOLIDAÇÃO', 'Registra a Variação Patrimonial Diminutiva proveniente de variações do valor da nossa moeda em relação as moedas estrangeiras referentes a Dívida Contratual.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3306, 2, '8.1.1.1.1.01.09.00.00.00', 'CAUÇÕES A EXECUTAR', 'Registra o valor das garantias por cauções pendentes de execução, no país.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (1022, 2, '3.4.3.1.3.01.00.00.00.00', 'VARIAÇÕES MONETARIAS DE DÍVIDA CONTRATUAL INTERNA - INTER OFSS - UNIÃO', 'Registra a Variação Patrimonial Diminutiva proveniente de variações da nossa própria moeda em relação aos índices ou coeficientes aplicáveis por dispositivo legal ou contratual referentes a dívida contratual. ressalte-se será tratada como Variação Monetária apenas a Correção Monetária Pós - Fixada.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1023, 2, '3.4.3.1.4.01.00.00.00.00', 'VARIAÇÕES MONETÁRIAS DE DÍVIDA CONTRATUAL INTERNA - INTER OFSS - ESTADO', 'Registra a Variação Patrimonial Diminutiva proveniente de variações da nossa própria moeda em relação aos índices ou coeficientes aplicáveis por dispositivo legal ou contratual referentes a dívida contratual. ressalte-se será tratada como Variação Monetária apenas a Correção Monetária Pós - Fixada.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1024, 2, '3.4.3.1.5.01.00.00.00.00', 'VARIAÇÕES MONETÁRIAS DE DÍVIDA CONTRATUAL INTERNA - INTER OFSS - MUNICÍPIO', 'Registra a Variação Patrimonial Diminutiva proveniente de variações da nossa própria moeda em relação aos índices ou coeficientes aplicáveis por dispositivo legal ou contratual referentes a dívida contratual. ressalte-se será tratada como Variação Monetária apenas a Correção Monetária Pós - Fixada.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1025, 2, '3.5.2.1.4.01.00.00.00.00', 'CONTRIBUIÇÃO PATRONAL PARA O RPPS DO ESTADO REFERENTE A PESSOAL REQUISITADO', 'Registra o valor das variações patrimoniais diminutivas realizadas com pagamento de contribuição patronal quando o servidor é contribuinte do RPPS do Estado.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1026, 2, '3.4.3.2.1.01.00.00.00.00', 'VARIAÇÕES MONETÁRIAS DA DÍVIDA CONTRATUAL EXTERNA ', 'Registra a Variação Patrimonial Diminutiva proveniente de variações da nossa própria moeda em relação aos índices ou coeficientes aplicáveis por dispositivo legal ou contratual referentes a dívida contratual. Ressalte-se será tratada como Variação Monetária apenas a Correção Monetária Pós - Fixada.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1027, 2, '3.4.3.2.1.02.00.00.00.00', 'VARIAÇÕES CAMBIAIS DE DÍVIDA CONTRATUAL EXTERNA ', 'Registra a Variação Patrimonial Diminutiva proveniente de variações do valor da nossa moeda em relação as moedas estrangeiras referentes a dívida contratual.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1028, 2, '3.4.3.3.1.01.00.00.00.00', 'VARIAÇÕES MONETÁRIAS DE DÍVIDA MOBILIÁRIA', 'Registra a Variação Patrimonial Diminutiva proveniente de variações da nossa própria moeda em relação aos índices ou coeficientes aplicáveis por dispositivo legal ou contratual referentes a dívida contratual. Ressalte-se será tratada como Variação Monetária apenas a Correção Monetária Pós - Fixada.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1029, 2, '3.4.3.9.1.99.00.00.00.00', 'OUTRAS VARIAÇÕES CAMBIAIS', 'Registra a Variação Patrimonial Diminutiva proveniente de variação do valor da nossa moeda em relação as moedas estrangeiras, com exceção a dívida Contratual e Mobiliaria.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1030, 2, '3.4.3.9.3.01.70.00.00.00', 'ATUALIZAÇÃO MONETÁRIA DE PRECATÓRIOS', 'Registra a Variação Patrimonial Diminutiva proveniente de variações da nossa própria moeda em relação aos índices ou coeficientes aplicáveis por dispositivo legal ou contratual, com exceção a dívida contratual e mobiliaria. Ressalte-se será tratada como Variação Monetária apenas a Correção Monetária Pós - Fixada - Atualização Monetária de Precatórios.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1031, 2, '3.4.3.9.3.01.71.00.00.00', 'ATUALIZAÇÃO MONETÁRIA DE TRIBUTOS RENEGOCIADOS', 'Registra a Variação Patrimonial Diminutiva proveniente de variações da nossa própria moeda em relação aos índices ou coeficientes aplicáveis por dispositivo legal ou contratual, com exceção a dívida contratual e mobiliaria. Ressalte-se será tratada como Variação Monetária apenas a Correção Monetária Pós - Fixada - Atualização Monetária de Tributos Renegociados.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1032, 2, '3.4.3.9.3.02.00.00.00.00', 'OUTRAS VARIAÇÕES CAMBIAIS', 'Registra a Variação Patrimonial Diminutiva proveniente de variação do valor da nossa moeda em relação as moedas estrangeiras, com exceção a dívida contratual e mobiliaria.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1033, 2, '3.4.3.9.4.01.00.00.00.00', 'OUTRAS VARIAÇÕES MONETÁRIAS', 'Registra a Variação Patrimonial Diminutiva proveniente de variações da nossa própria moeda em relação aos índices ou coeficientes aplicáveis por dispositivo legal ou contratual, com exceção a dívida contratual e mobiliaria. Ressalte-se será tratada como variação monetária apenas a correção monetária pós - fixada.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1034, 2, '3.4.3.9.4.02.00.00.00.00', 'OUTRAS VARIAÇÕES CAMBIAIS', 'Registra a variação patrimonial diminutiva proveniente de variação do valor da nossa moeda em relação as moedas estrangeiras, com exceção a dívida contratual e mobiliaria.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1035, 2, '3.4.3.9.5.01.00.00.00.00', 'OUTRAS VARIAÇÕES MONETÁRIAS', 'Registra a Variação Patrimonial Diminutiva proveniente de variações da nossa própria moeda em relação aos índices ou coeficientes aplicáveis por dispositivo legal ou contratual, com exceção a dívida contratual e mobiliaria. Ressalte-se será tratada como Variação Monetária apenas a Correção Monetária Pós - Fixada.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1036, 2, '3.4.3.9.5.02.00.00.00.00', 'OUTRAS VARIAÇÕES CAMBIAIS', 'Registra a Variação Patrimonial Diminutiva proveniente de Variação do valor da nossa moeda em relação as moedas estrangeiras, com exceção a dívida Contratual e Mobiliaria.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1045, 2, '3.5.1.2.2.02.99.00.00.00', 'OUTRAS TRANSFERÊNCIAS  NÃO FINANCEIRAS CONCEDIDAS - INDEPENDENTES DE EXECUÇÃO ORÇAMENTÁRIA', 'Registra o valor das demais transferências concedidas de bens ou valores independentes da execução orçamentária.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1046, 2, '3.5.1.3.2.01.01.00.00.00', 'RECURSOS PARA COBERTURA DE INSUFICIÊNCIAS FINANCEIRAS', 'Registra os recursos orçamentários efetivamente utilizados para a cobertura de insuficiências financeiras entre as receitas e despesas previdenciárias no exercício de referência.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1047, 2, '3.5.1.3.2.01.02.00.00.00', 'RECURSOS PARA FORMAÇÃO DE RESERVA', 'Registra os recursos transferidos pelo ente federativo ao RPPS para formação de reserva espontânea, para futuros pagamentos de benefícios do plano financeiro.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1048, 2, '3.5.1.3.2.01.99.00.00.00', 'OUTROS APORTES PARA O RPPS ', 'Registra o somatório de eventuais aportes de recursos no RPPS para outras necessidades financeiras que não a cobertura de insuficiências financeiras e formação de reservas.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1049, 2, '3.5.1.3.2.02.01.00.00.00', 'RECURSOS PARA COBERTURA DE DÉFICIT FINANCEIRO', 'Registra o somatório dos recursos necessários ao equilíbrio financeiro do plano previdenciário, ou seja, à cobertura de déficit entre as receitas e despesas previdenciárias, referentes ao exercício atual.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1050, 2, '3.5.1.3.2.02.02.00.00.00', 'RECURSOS PARA COBERTURA DE DÉFICIT ATUARIAL', 'Registra os recursos orçamentários alocados para cobertura de déficit atuarial no exercício de referência, desde que não definidos por lei como contribuições suplementares.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1051, 2, '3.5.1.3.2.02.99.00.00.00', 'OUTROS APORTES PARA O RPPS', 'Registra outros aportes financeiros para o RPPS com outras finalidades previdenciárias.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1052, 2, '3.5.2.1.4.02.00.00.00.00', 'PROGRAMA TROCA-TROCA', 'Registra o valor das variações patrimoniais diminutivas que o município tem que repassar para o Estado referente ao programa troca-troca.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1053, 2, '3.5.2.1.4.03.00.00.00.00', 'TRANSFERÊNCIAS PARA GRUPAMENTOS DE INCÊNDIO', 'Registra o valor das variações patrimoniais diminutivas que o município tem que repassar para os grupamentos de incêndio.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1054, 2, '3.6.2.3.1.01.00.00.00.00', 'PERDAS COM ALIENAÇÃO DE SOFTWARES', 'Registra a variação patrimonial diminutiva de perdas com alienação de softwares.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1055, 2, '3.5.2.1.4.04.00.00.00.00', 'RESTITUIÇÃO DE TRANSFERÊNCIAS E CONVÊNIOS RECEBIDOS DO ESTADO', 'Registra o valor das variações patrimoniais diminutivas com restituições de convênios e transferências recebidas do Estado, como, por exemplo: saldo de juros de aplicações financeiras; saldos de valores não utilizados.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1056, 2, '3.5.3.1.1.01.00.00.00.00', 'CONTRIBUIÇÕES', 'Registra o valor utilizado para transferências correntes e de capital aos entes da Federação e a entidades privadas sem fins lucrativos, exceto para os serviços essenciais de assistência social, médica e educacional;', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1057, 2, '3.5.3.1.1.02.00.00.00.00', 'AUXÍLIOS', 'Registra o valor utilizado para transferências de capital aos entes da Federação e a entidades privadas sem fins lucrativos;', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1058, 2, '3.6.3.3.1.05.00.00.00.00', 'PERDAS INVOLUNTÁRIAS COM MATERIAIS EM TRÂNSITO', 'Registra a variação patrimonial diminutiva com perdas involuntárias de materiais em trânsito.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1059, 2, '3.5.3.1.1.03.00.00.00.00', 'SUBVENÇÕES SOCIAIS', 'Registra o valor utilizado para transferências correntes às entidades públicas ou privadas sem fins lucrativos para os serviços essenciais de assistência social, médica e educacional;', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1060, 2, '3.5.7.2.1.01.00.00.00.00', 'DIÁRIAS ', 'Registra as variações patrimoniais diminutivas de diárias decorrentes de delegação ou descentralização aos consórcios públicos para execução de ações de responsabilidade exclusiva do delegante.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1061, 2, '3.5.7.2.1.02.00.00.00.00', 'PASSAGENS E DESPESAS COM LOCOMOÇÃO', 'Registra as variações patrimoniais diminutivas de passagens e despesas com locomoção decorrentes de delegação ou descentralização aos consórcios públicos para execução de ações de responsabilidade exclusiva do delegante.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1062, 2, '3.5.7.2.1.03.00.00.00.00', 'MATERIAL DE CONSUMO', 'Registra as variações patrimoniais diminutivas de material de consumo decorrentes de delegação ou descentralização aos consórcios públicos para execução de ações de responsabilidade exclusiva do delegante.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1063, 2, '3.5.7.2.1.04.00.00.00.00', 'OUTROS SERVIÇOS DE TERCEIRO - PESSOA FÍSICA', 'Registra as variações patrimoniais diminutivas de outros serviços de terceiro, pessoa física, decorrentes de delegação ou descentralização aos consórcios públicos para execução de ações de responsabilidade exclusiva do delegante.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1064, 2, '3.5.7.2.1.05.00.00.00.00', 'OUTROS SERVIÇOS DE TERCEIRO - PESSOA JURÍDICA', 'Registra as variações patrimoniais diminutivas de outros serviços de terceiro, pessoa jurídica, decorrentes de delegação ou descentralização aos consórcios públicos para execução de ações de responsabilidade exclusiva do delegante.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1065, 2, '3.5.7.2.1.06.00.00.00.00', 'INDENIZAÇÕES E RESTITUIÇÕES', 'Registra as variações patrimoniais diminutivas de indenizações e restituições decorrentes de delegação ou descentralização aos consórcios públicos para execução de ações de responsabilidade exclusiva do delegante.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1066, 2, '3.5.7.2.1.07.00.00.00.00', 'DEMAIS VPD COM DELEGAÇÃO', 'Registra as demais variações patrimoniais diminutivas decorrentes de delegação ou descentralização aos consórcios públicos para execução de ações de responsabilidade exclusiva do delegante.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1067, 2, '3.6.1.1.1.01.01.00.00.00', 'REAVALIAÇÃO DE MÁQUINAS, APARELHOS, EQUIPAMENTOS E FERRAMENTAS', 'Registra a variação patrimonial diminutiva relativa à adoção do valor de mercado ou de consenso entre as partes para máquinas, ferramentas, aparelhos, equipamentos, acessórios etc, quando esse for inferior ao valor liquido contábil.', 1, true, 2, ' ');
insert into contabilidade.planocontadetalhe values (1068, 2, '3.6.1.1.1.01.02.00.00.00', 'REAVALIAÇÃO DE BENS DE INFORMÁTICA', 'Registra a variação patrimonial diminutiva relativa à adoção do valor de mercado ou de consenso entre as partes paraequipamentos de processamento de dados e sistemas aplicativos, entre outros, quando esse for inferior ao valor liquido contábil.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1069, 2, '3.6.1.1.1.01.03.00.00.00', 'REAVALIAÇÃO DE MÓVEIS E UTENSÍLIOS', 'Registra a variação patrimonial diminutiva relativa à adoção do valor de mercado ou de consenso entre as partes para mobiliário em geral e utensílios, entre outros, quando esse for inferior ao valor liquido contábil.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1139, 2, '3.6.1.7.1.03.00.00.00.00', 'AJUSTE PARA PERDAS EM CRÉDITOS DE TRANSFERÊNCIAS A RECEBER', 'Registra a variação patrimonial diminutiva com ajuste para perdas em créditos de transferências a receber.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1070, 2, '3.6.1.1.1.01.04.00.00.00', 'REAVALIAÇÃO DE MATERIAIS CULTURAIS, EDUCACIONAIS E DE COMUNICAÇÃO', 'Registra a variação patrimonial diminutiva relativa à adoção do valor de mercado ou de consenso entre as partes para materiais bibliográficos, discotecas, filmotecas, de comunicação, entre outros, quando esse for inferior ao valor liquido contábil.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1071, 2, '3.6.1.1.1.01.05.00.00.00', 'REAVALIAÇÃO DE VEÍCULOS', 'Registra a variação patrimonial diminutiva relativa à adoção do valor de mercado ou de consenso entre as partes para transportes aéreos, aquáticos e terrestres, entre outros, quando esse for inferior ao valor liquido contábil.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1072, 2, '3.6.1.1.1.01.06.00.00.00', 'REAVALIAÇÃO DE PEÇAS E CONJUNTOS DE REPOSIÇÃO', 'Registra a variação patrimonial diminutiva relativa à adoção do valor de mercado ou de consenso entre as partes para peças e conjuntos de reposição destinados a substituição em máquinas e equipamentos, aeronaves e embarcações, bens de segurança e socorro, entre outros, quando esse for inferior ao valor liquido contábil.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1073, 2, '3.6.1.1.1.01.07.00.00.00', 'REAVALIAÇÃO DE BENS MÓVEIS EM ANDAMENTO', 'Registra a variação patrimonial diminutiva relativa à adoção do valor de mercado ou de consenso entre as partes para bens móveis em andamento, quando esse for inferior ao valor liquido contábil.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1074, 2, '3.6.1.1.1.01.08.00.00.00', 'REAVALIAÇÃO DE BENS MÓVEIS EM ALMOXARIFADO', 'Registra a variação patrimonial diminutiva relativa à adoção do valor de mercado ou de consenso entre as partes para bens permanentes a serem estocados em almoxarifado, quando esse for inferior ao valor liquido contábil.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1075, 2, '3.6.1.1.1.01.09.00.00.00', 'REAVALIAÇÃO DE ARMAMENTOS', 'Registra a variação patrimonial diminutiva relativa à adoção do valor de mercado ou de consenso entre as partes para armas que constituem objetos de defesa ou preparativos de guerra, quando esse for inferior ao valor liquido contábil.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1076, 2, '3.6.1.1.1.01.10.00.00.00', 'REAVALIAÇÃO DE SEMOVENTES', 'Registra a variação patrimonial diminutiva relativa à adoção do valor de mercado ou de consenso entre as partes para animais destinados a produção, reprodução, engorda e aos serviços utilitários em geral, quando esse for inferior ao valor liquido contábil.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1077, 2, '3.6.2.2.1.01.09.00.00.00', 'PERDAS COM ALIENAÇÃO DE ARMAMENTOS', 'Registra a variação patrimonial diminutiva de perdas com alienação de armamentos.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1078, 2, '3.6.1.1.1.01.99.00.00.00', 'REAVALIAÇÃO DE DEMAIS BENS MÓVEIS', 'Registra a variação patrimonial diminutiva relativa à adoção do valor de mercado ou de consenso entre as partes para demais bens móveis não classificados em grupos específicos, quando esse for inferior ao valor liquido contábil.', 1, true, 2, ' ');
insert into contabilidade.planocontadetalhe values (1079, 2, '3.6.1.1.1.02.01.00.00.00', 'REAVALIAÇÃO DE BENS DE USO ESPECIAL', 'Registra a variação patrimonial diminutiva relativa à adoção do valor de mercado ou de consenso entre as partes para os bens, tais como edifícios ou terrenos destinados a serviço ou estabelecimento da administração estadual ou municipal, inclusive os de suas autarquias e fundações públicas, quando esse for inferior ao valor liquido contábil.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1080, 2, '3.6.1.1.1.02.02.00.00.00', 'REAVALIAÇÃO DE BENS DOMINICAIS', 'Registra a variação patrimonial diminutiva relativa à adoção do valor de mercado ou de consenso entre as partes para os bens que constituem o patrimônio das pessoas jurídicas de direito público, como objeto de direito pessoal, ou real, de cada uma dessas entidades. Compreende ainda, não dispondo a lei em contrário, os bens pertencentes as pessoas jurídicas de direito público a que se tenha dado estrutura de direito privado, quando esse for inferior ao valor liquido contábil.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1081, 2, '3.6.1.1.1.02.03.00.00.00', 'REAVALIAÇÃO DE BENS DE USO COMUM DO POVO', 'Registra a variação patrimonial diminutiva relativa à adoção do valor de mercado ou de consenso entre as partes para os bens de uso comum do povo construídos ou adquiridos por pessoas jurídicas de direito público, quando esse for inferior ao valor liquido contábil.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1082, 2, '3.6.1.1.1.02.04.00.00.00', 'REAVALIAÇÃO DE BENS IMÓVEIS EM ANDAMENTO', 'Registra a variação patrimonial diminutiva relativa à adoção do valor de mercado ou de consenso entre as partes para os valores de bens imóveis em andamento, quando esse for inferior ao valor liquido contábil.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1083, 2, '3.6.1.1.1.02.05.00.00.00', 'REAVALIAÇÃO DE INSTALAÇÕES', 'Registra a variação patrimonial diminutiva relativa à adoção do valor de mercado ou de consenso entre as partes para equipamentos, materiais e custo de implantação de instalações que, não obstante integradas aos edifícios, devem ser segregadas das obras civis, como, por exemplo, as instalações elétricas, hidráulicas, sanitárias, de vapor, de ar comprimido, frigoríficas, contra incêndio, de comunicações, de climatização, para combustíveis, gases, de antipoluição, para cozinha, dentre outros. E também aplicável a construção de trechos ferroviários, quando esse for inferior ao valor liquido contábil.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1084, 2, '3.6.1.1.1.02.06.00.00.00', 'REAVALIAÇÃO DE BENFEITORIAS EM PROPRIEDADE DE TERCEIROS', 'Registra a variação patrimonial diminutiva relativa à adoção do valor de mercado ou de consenso entre as partes para construções em terrenos arrendados de terceiros e instalações e outras benfeitorias em prédios alugados. São considerados somente os gastos com construção e instalação que se incorporam ao imóvel e revertem ao proprietário do imóvel ao final da locação, quando esse for inferior ao valor liquido contábil.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1085, 2, '3.6.1.1.1.02.99.00.00.00', 'REAVALIAÇÃO DE DEMAIS BENS IMÓVEIS', 'Registra a variação patrimonial diminutiva relativa à adoção do valor de mercado ou de consenso entre as partes para os demais bens imóveis não classificados anteriormente nesse plano de contas, quando esse for inferior ao valor liquido contábil.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (1086, 2, '3.6.1.4.1.01.00.00.00.00', 'REDUÇÃO A VALOR RECUPERÁVEL DE PARTICIPAÇÕES PERMANENTES', 'Registra a variação patrimonial diminutiva relativa à redução a valor recuperável de participações permanentes em outras entidades.', 1, true, 2, 'N');
