insert into contabilidade.planocontadetalhe values (1244, 2, '3.6.5.0.1.06.00.00.00.00', 'DESINCORPORAÇÃO DE INVESTIMENTOS PERMANENTES', 'Registra a contrapartida de desincorporação de investimentos permanentes;', 1, true, 2, 'N');
