insert into contabilidade.planocontadetalhe values (1340, 2, '5.2.2.1.2.03.03.00.00.00', 'CRÉDITOS EXTRAORDINÁRIOS REABERTOS - SUPLEMENTAÇÃO', 'Registra os valores referentes à suplementação de créditos extraordinários reabertos nos termos do § 2º do art. 168 da C.F./88.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (1341, 2, '5.2.2.1.3.01.00.00.00.00', 'SUPERÁVIT FINANCEIRO DE EXERCÍCIO ANTERIOR ', 'Registra os valores pertinentes aos créditos adicionais abertos cuja origem de recursos seja superávit financeiro apurado no Balanço Patrimonial do exercício anterior.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (1342, 2, '5.2.2.1.3.02.00.00.00.00', ' EXCESSO DE ARRECADAÇÃO          ', 'Registra os valores pertinentes aos créditos adicionais abertos cuja origem de recursos seja excesso de arrecadação.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (1343, 2, '5.2.2.1.3.03.00.00.00.00', 'ANULAÇÃO DE DOTAÇÃO', 'Registra os valores pertinentes aos créditos adicionais abertos cuja origem de recursos seja a anulação parcial ou total de dotações orçamentárias ou créditos adicionais, autorizados em lei.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (1344, 2, '5.2.2.1.3.04.00.00.00.00', 'OPERAÇÕES DE CREDITO', 'Registra os valores pertinentes aos créditos adicionais abertos cuja origem de recursos seja operações de crédito autorizadas.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (1345, 2, '5.2.2.1.3.05.00.00.00.00', 'RESERVA DE CONTINGENCIA', 'Registra os valores pertinentes aos créditos adicionais abertos cuja origem de recursos seja a reserva de contingência.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (1346, 2, '5.2.2.1.3.06.00.00.00.00', 'DOTAÇÃO TRANSFERIDA', 'Registra os valores de alterações da lei orçamentária com controle por origem de crédito.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (1347, 2, '5.2.2.1.3.07.00.00.00.00', 'RECURSOS SEM DESPESAS CORRESPONDENTES', 'Registra os valores pertinentes aos créditos adicionais abertos cuja origem de recursos sejam os recursos que, em decorrência de veto, emenda ou rejeição do projeto de lei orçamentária anual, ficarem sem despesas correspondentes.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (1348, 2, '5.2.2.1.9.01.01.00.00.00', 'ACRESCIMO', 'Registra a movimentação dos créditos por acréscimo decorrente de alteração do quadro de detalhamento de despesas - QDD.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (1349, 2, '5.2.2.1.9.02.01.00.00.00', 'ACRÉSCIMO', 'Registra os valores dos acréscimos resultantes de alterações da lei orçamentária em virtude de remanejamento.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (1350, 2, '5.2.2.2.2.01.01.00.00.00', 'CREDITOS RECEBIDOS ', 'Registra o valor dos créditos recebidos pela administração direta de outros órgãos e entidades.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (1351, 2, '5.2.2.2.2.02.01.00.00.00', 'CREDITOS RECEBIDOS', 'Registra o valor dos créditos recebidos pela administração indireta de mesma ou de diferente unidade orçamentária do órgão emitente.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (1352, 2, '5.2.2.9.1.01.00.00.00.00', 'PRÉ-EMPENHOS EMITIDOS', 'Registra os valores dos pré-empenhos emitidos pela própria unidade gestora detentora pelo credito disponível.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (1353, 2, '5.2.2.9.1.02.00.00.00.00', 'REFORÇO DE PRÉ-EMPENHO', 'Registra os valores de reforço de pré-empenho emitido pela própria unidade detentora do crédito disponível.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (1354, 2, '5.2.2.9.1.03.00.00.00.00', 'ANULAÇÃO DE PRÉ-EMPENHO', 'Registra a anulação de pré-empenho emitido pela própria unidade detentora do crédito disponível.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (1355, 2, '5.2.2.9.2.01.01.00.00.00', 'EMISSAO DE EMPENHOS       ', 'Registra o valor da emissão de empenho da despesa, inclusive referente àquela despesa que já se encontra pré-empenhada.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (1356, 2, '5.2.2.9.2.01.02.00.00.00', 'REFORÇO DE EMPENHOS       ', 'Registra o valor da emissão de nota de empenho de despesa visando suplementar o anterior cujo valor seja insuficiente.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (1357, 2, '5.3.1.1.0.00.00.00.00.00', 'RP NÃO PROCESSADOS INSCRITOS', 'Registra os valores inscritos em restos a pagar não-processados relativos às despesas empenhadas e não liquidadas até o ultimo dia do exercício financeiro imediatamente anterior.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (1358, 2, '5.3.1.2.0.00.00.00.00.00', 'RP NÃO PROCESSADOS - EXERCÍCIOS ANTERIORES', 'Registra o valor de restos a pagar não processados relativo a exercícios anteriores que não foram cancelados porque tiveram seu prazo de validade prorrogado.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (1359, 2, '5.3.1.3.0.00.00.00.00.00', 'RP NÃO PROCESSADOS RESTABELECIDOS', 'Registra o valor por restabelecimento de empenho de restos a pagar já cancelados em exercícios anteriores com base em ato normativo específico.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (1360, 2, '5.3.1.6.0.00.00.00.00.00', 'RP NÃO PROCESSADOS RECEBIDOS POR TRANSFERÊNCIA', 'Registra o valor da transferência de restos a pagar não processados decorrente de transformação, cisão, fusão e extinção de órgãos ou UG.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (1473, 2, '1.1.1.2.0.00.00.00.00.00', 'CAIXA E EQUIVALENTES DE CAIXA EM MOEDA ESTRANGEIRA', 'Compreende o somatório dos valores de caixa e equivalentes de caixa em moeda estrangeira.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1361, 2, '5.3.1.7.0.00.00.00.00.00', 'RP NÃO PROCESSADOS - INSCRIÇÃO NO EXERCÍCIO', 'Registra o valor das despesas empenhadas inscritas no exercício como restos a pagar não processados, a ser transferido no exercício seguinte para a conta 531100000.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (1362, 2, '5.3.2.1.0.00.00.00.00.00', 'RP PROCESSADOS - INSCRITOS', 'Registra o somatório dos valores inscritos em restos a pagar processados relativos às despesas empenhadas, liquidadas e não pagas no exercício financeiro em que foi empenhado.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (1363, 2, '5.3.2.2.0.00.00.00.00.00', 'RP PROCESSADOS - EXERCÍCIOS ANTERIORES', 'Registra os valores de restos a pagar processados relativos às despesas empenhadas, liquidadas e não pagas no exercício financeiro subseqüente.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (1364, 2, '5.3.2.6.0.00.00.00.00.00', 'RP PROCESSADOS RECEBIDOS POR TRANSFERÊNCIA', 'Registra o valor da transferência de restos a pagar processados decorrente de transformação, cisão, fusão e extinção de órgãos ou UG.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (1365, 2, '5.3.2.7.0.00.00.00.00.00', 'RP PROCESSADOS - INSCRIÇÃO NO EXERCÍCIO', 'Registra o valor das despesas empenhadas inscritas no exercício como restos a pagar processados, a ser transferido no exercício seguinte para a conta 532100000.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (1366, 2, '6.2.1.3.1.01.00.00.00.00', '(-) FUNDEB', 'Registra o somatório dos valores relativos as deduções de receitas realizadas por transferências ao FUNDEB.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (1367, 2, '6.2.1.3.1.02.00.00.00.00', '(-) TRANSFERÊNCIAS CONSTITUCIONAIS E LEGAIS A MUNICÍPIOS', 'Registra o somatório dos valores relativos as deduções de receitas realizadas por transferências constitucionais e legais aos municípios, as quais representem repartição de receita orçamentária.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (1368, 2, '6.2.1.3.2.00.00.00.00.00', '(-) RENÚNCIA', 'Registra o somatório dos valores relativos as deduções de receitas realizadas por renúncia, detalhada por natureza de receita.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (1369, 2, '6.2.1.3.9.00.00.00.00.00', '(-) OUTRAS DEDUÇÕES DA RECEITA REALIZADA', 'Registra o somatório dos valores relativos as outras deduções de receitas realizadas, detalhada por natureza de receita.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (1370, 2, '6.2.2.1.3.99.00.00.00.00', '(-) OUTROS CRÉDITOS UTILIZADOS', 'Registra a contrapartida de despesas realizadas pelas entidades ou órgão da administração direta/indireta que utilizam o SIAFI no modulo parcial.   Registra a contrapartida de despesas liquidadas na rotina de suprimento de fundos para evitar a emissão de lista de item (li) para reclassificação da despesa.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (1371, 2, '7.1.1.1.1.01.01.00.00.00', 'AVAIS', 'Registra o valor da garantia de pagamento de título de crédito exclusivamente, de natureza pessoal, dada por terceiros, no país.', 1, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (1372, 2, '7.1.1.1.1.01.02.00.00.00', 'FIANÇAS', 'Registra o valor da obrigação acessória recebida no país, por órgãos e entidades, pelo cumprimento da obrigação do devedor, caso esse não cumpra.', 1, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (1373, 2, '7.1.1.1.1.01.03.00.00.00', 'HIPOTECAS', 'REGISTRA O TOTAL DAS GARANTIAS DE VALORES POR HIPOTECAS RECEBIDAS NO PAÍS.', 1, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (1374, 2, '7.1.1.1.1.01.04.00.00.00', 'SEGUROS-GARANTIA', 'REGISTRA A GARANTIA DE VALORES POR SEGUROS RECEBIDOS NO PAÍS.', 1, true, 1, 'N');
