insert into contabilidade.planocontadetalhe values (1376, 2, '7.1.1.1.1.01.06.00.00.00', 'GARANTIAS INSTITUÍDAS POR LEI ESPECÍFICA', 'REGISTRA O VALOR REFERENTE A GARANTIAS RECEBIDAS NA FORMA PREVISTA EM LEI ESPECÍFICA, NO PAÍS E NO EXTERIOR. ESTA CATEGORIA INCLUI AS GARANTIAS OU RISCOS ASSUMIDOS EM OPERAÇÕES REALIZADAS NO ÂMBITO DE FUNDOS, PROGRAMAS E OPERAÇÕES ESPECIAIS, NO PAÍS.', 1, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (1377, 2, '7.1.1.1.1.01.07.00.00.00', 'GARANTIAS DA DÍVIDA PÚBLICA', 'REGISTRA O TOTAL DAS GARANTIAS RECEBIDAS DA DÍVIDA PÚBLICA, NO PAÍS.', 1, true, 1, 'N');
