insert into contabilidade.planocontadetalhe values (1379, 2, '7.1.1.1.1.01.99.00.00.00', 'OUTRAS GARANTIAS RECEBIDAS NO PAÍS', 'REGISTRA O VALOR DE OUTRAS GARANTIAS RECEBIDAS, NÃO INCLUÍDAS NOS ITENS ANTERIORES, SOBRE OBRIGAÇÕES CONTRAÍDAS NO PAÍS.', 1, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (1380, 2, '7.1.1.1.1.03.01.00.00.00', 'AVAIS', 'Registra o valor das contragarantias recebidas decorrentes das concessões de avais por obrigações contraídas, no país.', 1, true, 1, 'N');
