insert into contabilidade.planocontadetalhe values (1398, 2, '7.1.1.9.2.00.00.00.00.00', 'PARCELAMENTO DE DÉBITOS PREVIDENCIÁRIOS', 'Registra, a título de controle, os valores relativos às parcelas de débitos previdenciários do RPPS devidas pelo ente público.', 1, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (1399, 2, '7.1.2.1.1.01.01.00.00.00', 'AVAIS', 'Registra o valor da garantia de pagamento de título de crédito exclusivamente, de natureza pessoal, dada a terceiros, no país.', 1, true, 1, 'N');
