insert into contabilidade.planocontadetalhe values (1496, 2, '1.1.2.2.0.00.00.00.00.00', 'CLIENTES', 'Compreende os valores das faturas/duplicatas a receber decorrentes das vendas a prazo de mercadorias ou serviços que ocorram no curso normal das operações da entidade, representando um direito a cobrar de seus clientes.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1497, 2, '1.1.2.2.1.00.00.00.00.00', 'CLIENTES - CONSOLIDAÇÃO', 'Compreende os valores das faturas/duplicatas a receber decorrentes das vendas a prazo de mercadorias ou serviços que ocorrem no curso normal das operações da unidade, representando um direito a cobrar de seus clientes. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1498, 2, '1.1.2.3.0.00.00.00.00.00', 'CRÉDITOS DE TRANSFERÊNCIAS A RECEBER', 'Compreende os valores relativos a créditos a receber oriundos da variação patrimoniais aumentativas decorrentes de transferências da União, estados, Distrito Federal e municípios, consórcios públicos e outras instituições.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1499, 2, '1.1.2.3.1.00.00.00.00.00', 'CRÉDITOS DE TRANSFERÊNCIAS A RECEBER - CONSOLIDAÇÃO', 'Compreende os valores relativos a créditos a receber oriundos da variação patrimoniais aumentativas decorrentes de transferências da União, estados, Distrito Federal e municípios, consórcios públicos e outras instituições. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
