insert into contabilidade.planocontadetalhe values (1526, 2, '1.1.2.4.5.00.00.00.00.00', 'EMPRÉSTIMOS E FINANCIAMENTOS CONCEDIDOS-INTER OFSS - MUNICÍPIO', 'Compreende o somatório dos valores de empréstimos e financiamentos concedidos por autorizações legais ou vinculações a contratos e acordos. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1527, 2, '1.1.2.4.5.01.00.00.00.00', 'EMPRÉSTIMOS CONCEDIDOS', 'Compreende o somatório dos valores dos empréstimos concedidos por autorizações legais ou vinculações a contratos e acordos, exceto os concedidos com recursos do RPPS.', 1, false, 0, ' ');
insert into contabilidade.planocontadetalhe values (1528, 2, '1.1.2.4.5.02.00.00.00.00', 'FINANCIAMENTOS CONCEDIDOS', 'Compreende o somatório dos valores dos financiamentos concedidos por autorizações legais ou vinculações a contratos e acordos, exceto os concedidos com recursos do RPPS.', 1, false, 0, ' ');
insert into contabilidade.planocontadetalhe values (1529, 2, '1.1.2.4.5.03.00.00.00.00', 'JUROS E ENCARGOS SOBRE EMPRÉSTIMOS E FINANCIAMENTOS CONCEDIDOS A RECEBER', 'Compreende o somatório dos valores dos juros e encargos sobre empréstimos e financiamentos concedidos a receber.', 1, false, 0, ' ');
insert into contabilidade.planocontadetalhe values (1530, 2, '1.1.2.4.5.07.00.00.00.00', 'EMPRÉSTIMOS E FINANCIAMENTOS CONCEDIDOS COM RECURSOS PREVIDENCIÁRIOS', 'Compreende o somatório dos valores de empréstimos e financiamentos concedidos por autorizações legais ou vinculações a contratos e acordos.', 1, false, 0, ' ');
insert into contabilidade.planocontadetalhe values (1531, 2, '1.1.2.4.5.08.00.00.00.00', 'PROGRAMA DE REESTRUTURAÇÃO FISCAL', 'Compreende o somatório dos valores a receber em decorrência da assunção e refinanciamento, pela União, de dívidas de responsabilidade dos Municípios, nos termos da MP nº 2.185-35, de 24 de agosto de 2001.', 1, false, 0, ' ');
insert into contabilidade.planocontadetalhe values (1532, 2, '1.1.2.5.0.00.00.00.00.00', 'DÍVIDA ATIVA TRIBUTÁRIA', 'Compreende os valores dos créditos de dívida ativa tributária inscritos, realizáveis em até 12 meses da data das demonstrações.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1533, 2, '1.1.2.5.1.00.00.00.00.00', 'DÍVIDA ATIVA TRIBUTÁRIA - CONSOLIDAÇÃO', 'Compreende os valores dos créditos de dívida ativa tributária inscritos, realizáveis em até 12 meses da data das demonstrações. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1534, 2, '1.1.2.5.1.01.00.00.00.00', 'DÍVIDA ATIVA TRIBUTÁRIA DOS IMPOSTOS', 'Compreende os valores relativos aos créditos a receber, inscritos em dívida ativa, decorrentes da cobrança da modalidade de tributo cuja obrigação tem por fato gerador uma situação independente de qualquer atividade estatal específica relativa ao contribuinte.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1535, 2, '1.1.2.5.1.01.01.00.00.00', 'DÍVIDA ATIVA DO IMPOSTO SOBRE A RENDA E PROVENTOS DE QUALQUER NATUREZA', 'Compreende os valores relativos a créditos a receber, decorrentes da cobrança do imposto sobre a renda e proventos de qualquer natureza', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1536, 2, '1.1.2.5.1.01.05.00.00.00', 'DÍVIDA ATIVA DO IPTU', 'Compreende os valores relativos a créditos a receber, inscritos em dívida ativa, decorrentes da cobrança do imposto sobre a propriedade predial e territorial urbana.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1537, 2, '1.1.2.5.1.01.06.00.00.00', 'DÍVIDA ATIVA DO ITBI', 'Compreende os valores relativos a créditos a receber, inscritos em dívida ativa, decorrentes da cobrança do imposto sobre transmissão "inter vivos" de bens imóveis e de direitos reais sobre imóveis.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1538, 2, '1.1.2.5.1.01.07.00.00.00', 'DÍVIDA ATIVA DO ISS', 'Compreende os valores relativos a créditos a receber, inscritos em dívida ativa, decorrentes da cobrança do imposto sobre serviços de qualquer natureza.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1539, 2, '1.1.2.5.1.01.08.00.00.00', 'DÍVIDA ATIVA DO ITR', 'Compreende os valores relativos a créditos a receber, inscritos em dívida ativa, decorrentes da cobrança imposto sobre a propriedade territorial rural, devidos aos municípios ou ao Distrito Federal devido a convênios firmados com a União, conforme inciso III, parágrafo 4º do artigo 153 da Constituição Federal.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1540, 2, '1.1.2.5.1.02.00.00.00.00', 'DÍVIDA ATIVA TRIBUTÁRIA DAS TAXAS', 'Compreende os valores relativos aos créditos a receber, inscritos em dívida ativa, decorrentes da cobrança da modalidade de tributo que tem como fato gerador o exercício regular do poder de polícia ou a utilização efetiva ou potencial de serviço público específico e divisível, prestado ao contribuinte ou posto a sua disposição.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1541, 2, '1.1.2.5.1.02.01.00.00.00', 'DÍVIDA ATIVA DAS TAXAS PELO EXERCÍCIO DO PODER DE POLÍCIA', 'Compreende os valores relativos aos créditos a receber, inscritos em dívida ativa, decorrentes da cobrança das taxas pelo exercício do poder de polícia.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1542, 2, '1.1.2.5.1.02.02.00.00.00', 'DÍVIDA ATIVA DAS TAXAS PELA PRESTAÇÃO DE SERVIÇOS', 'Compreende os valores relativos aos créditos a receber, inscritos em dívida ativa, decorrentes da cobrança das taxas pela prestação de serviços.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1543, 2, '1.1.2.5.1.03.00.00.00.00', 'DÍVIDA ATIVA DAS CONTRIBUIÇÕES DE MELHORIA', 'Compreende os valores relativos aos créditos a receber, inscritos em dívida ativa, decorrentes da cobrança dos valores decorrentes da contribuição instituída para fazer face ao custo de obras públicas de que decorra valorização imobiliária.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1544, 2, '1.1.2.5.1.03.01.00.00.00', 'DÍVIDA ATIVA DAS CONTRIBUIÇÕES DE MELHORIA', 'Compreende os  valores relativos aos créditos a receber, inscritos em dívida ativa, decorrentes da cobrança das contribuições de melhoria.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1545, 2, '1.1.2.5.1.04.00.00.00.00', 'DÍVIDA ATIVA DAS DEMAIS CONTRIBUIÇÕES', 'Compreende os valores relativos aos créditos a receber, inscritos em dívida ativa, decorrentes da cobrança dos valores decorrentes das demais contribuições.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1546, 2, '1.1.2.5.1.04.01.00.00.00', 'DÍVIDA ATIVA DA CONTRIBUIÇÃO PARA O CUSTEIO DO SERVIÇO DE ILUMINAÇÃO PÚBLICA', 'Compreende os valores relativos aos créditos a receber, inscritos em dívida ativa de contribuição para o custeio do serviço de iluminação pública, conforme artigo 149-A da Constituição Federal de 1988.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1547, 2, '1.1.2.5.1.05.00.00.00.00', 'CRÉDITOS NÃO PREVIDENCIÁRIOS INSCRITOS', 'Compreende os valores relativos a créditos inscritos de Dívida Ativa tributária não previdenciária.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1548, 2, '1.1.2.5.1.06.00.00.00.00', 'CRÉDITOS PREVIDENCIÁRIOS INSCRITOS', 'Compreende os valores relativos a créditos inscritos em Dívida Ativa tributária previdenciária, excluídos valores devidos pelo ente público. Estão incluídos, por exemplo, valores devidos por servidor em gozo de licença para tratamento de interesses particulares, entre outros.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1549, 2, '1.1.2.5.2.00.00.00.00.00', 'DÍVIDA ATIVA TRIBUTÁRIA - INTRA OFSS ', 'Compreende os valores dos créditos de dívida ativa tributária inscritos, realizáveis em até 12 meses da data das demonstrações. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do ente.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1550, 2, '1.1.2.5.2.01.00.00.00.00', 'DÍVIDA ATIVA TRIBUTÁRIA DOS IMPOSTOS', 'Compreende os valores relativos aos créditos a receber, inscritos em dívida ativa, decorrentes da cobrança da modalidade de tributo cuja obrigação tem por fato gerador uma situação independente de qualquer atividade estatal específica relativa ao contribuinte.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1551, 2, '1.1.2.5.2.02.00.00.00.00', 'DÍVIDA ATIVA TRIBUTÁRIA DAS TAXAS', 'Compreende os valores relativos aos créditos a receber, inscritos em dívida ativa, decorrentes da cobrança da modalidade de tributo que tem como fato gerador o exercício regular do poder de polícia ou a utilização efetiva ou potencial de serviço público específico e divisível, prestado ao contribuinte ou posto a sua disposição.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1667, 2, '1.2.1.1.1.04.01.07.00.00', 'DÍVIDA ATIVA DO ISS', 'Compreende os valores relativos a créditos inscritos de Dívida Ativa do iss.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1552, 2, '1.1.2.5.2.03.00.00.00.00', 'DÍVIDA ATIVA DAS CONTRIBUIÇÕES DE MELHORIA', 'Compreende os valores relativos aos créditos a receber, inscritos em dívida ativa, decorrentes da cobrança dos valores decorrentes da contribuição instituída para fazer face ao custo de obras públicas de que decorra valorização imobiliária.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1553, 2, '1.1.2.5.2.04.00.00.00.00', 'DÍVIDA ATIVA DAS DEMAIS CONTRIBUIÇÕES', 'Compreende os valores relativos aos créditos a receber, inscritos em dívida ativa, decorrentes da cobrança dos valores decorrentes das demais contribuições.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1554, 2, '1.1.2.5.3.00.00.00.00.00', 'DÍVIDA ATIVA TRIBUTÁRIA - INTER OFSS - UNIÃO', 'Compreende os valores dos créditos de dívida ativa tributária inscritos, realizáveis em até 12 meses da data das demonstrações. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) de entes públicos distintos, para permitir a consolidação nacional realizada pelo Poder Executivo da União. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1555, 2, '1.1.2.5.4.00.00.00.00.00', 'DÍVIDA ATIVA TRIBUTÁRIA - INTER OFSS - ESTADO', 'Compreende os valores dos créditos de dívida ativa tributária inscritos, realizáveis em até 12 meses da data das demonstrações. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1556, 2, '1.1.2.5.5.00.00.00.00.00', 'DÍVIDA ATIVA TRIBUTÁRIA - INTER OFSS - MUNICÍPIO', 'Compreende os valores dos créditos de dívida ativa tributária inscritos, realizáveis em até 12 meses da data das demonstrações. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1557, 2, '1.1.2.6.0.00.00.00.00.00', 'DÍVIDA ATIVA NÃO TRIBUTÁRIA ', 'Compreende os valores dos créditos de dívida ativa não tributária inscritos, derivados de clientes, realizáveis no curto prazo.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1558, 2, '1.1.2.6.1.00.00.00.00.00', 'DÍVIDA ATIVA NÃO TRIBUTÁRIA - CONSOLIDAÇÃO', 'Compreende os valores dos créditos de dívida ativa não tributária inscritos, realizáveis em até 12 meses da data das demonstrações. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1559, 2, '1.1.2.6.1.01.00.00.00.00', 'DÍVIDA ATIVA NÃO TRIBUTÁRIA', 'Compreende os valores dos créditos de dívida ativa não tributária tais como os provenientes de empréstimos compulsórios, contribuições estabelecidas em lei, multas de qualquer origem ou natureza (exceto as tributárias), foros, laudêmios, aluguéis, taxas de ocupação, custas processuais, preços de serviços prestados por estabelecimentos públicos e outros, exigíveis por transcurso de prazo para pagamento, inscritos na forma de legislação própria, após apurada sua liquidez e certeza.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1560, 2, '1.1.2.6.2.00.00.00.00.00', 'DÍVIDA ATIVA NÃO TRIBUTÁRIA  - INTRA OFSS', 'Compreende os valores dos créditos de dívida ativa não tributária inscritos, realizáveis em até 12 meses da data das demonstrações. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do ente.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1561, 2, '2.3.9.2.0.00.00.00.00.00', '(-) COTAS EM TESOURARIA', 'Compreende o valor das cotas da entidade que foram adquiridas pela própria entidade.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1562, 2, '1.1.2.6.3.00.00.00.00.00', 'DÍVIDA ATIVA NÃO TRIBUTÁRIA  - INTER OFSS - UNIÃO', 'Compreende os valores dos créditos de dívida ativa não tributária inscritos, realizáveis em até 12 meses da data das demonstrações. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1563, 2, '1.1.2.6.4.00.00.00.00.00', 'DÍVIDA ATIVA NÃO TRIBUTÁRIA  - INTER OFSS - ESTADO', 'Compreende os valores dos créditos de dívida ativa não tributária inscritos, realizáveis em até 12 meses da data das demonstrações. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um Estado.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1564, 2, '1.1.2.6.5.00.00.00.00.00', 'DÍVIDA ATIVA NÃO TRIBUTÁRIA  - INTER OFSS - MUNICÍPIO', 'Compreende os valores dos créditos de dívida ativa não tributária inscritos, realizáveis em até 12 meses da data das demonstrações. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um Município.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1565, 2, '1.1.3.0.0.00.00.00.00.00', 'DEMAIS CRÉDITOS E VALORES A CURTO PRAZO', 'Compreende os valores a receber por demais transações realizáveis no curto prazo.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1566, 2, '1.1.3.1.0.00.00.00.00.00', 'ADIANTAMENTOS CONCEDIDOS', 'Compreende as antecipações concedidas a pessoal (tais como antecipações de salários e ordenados, adiantamentos de 13º salário, adiantamentos de férias e outros) e a terceiros, incluídos os adiantamentos a fornecedores.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1567, 2, '1.1.3.1.1.00.00.00.00.00', 'ADIANTAMENTOS CONCEDIDOS - CONSOLIDAÇÃO', 'Compreende as antecipações concedidas a pessoal (tais como antecipações de salários e ordenados, adiantamentos de 13º salário, adiantamentos de ferias e outros) e a terceiros, incluídos os adiantamentos a fornecedores. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1568, 2, '1.1.3.1.1.01.00.00.00.00', 'ADIANTAMENTOS CONCEDIDOS A PESSOAL', 'Compreende os valores das antecipações concedidas a servidores e a dirigentes da unidade, tais como antecipações de salários e ordenados, adiantamentos de 13º salário, adiantamentos de férias e de gratificações natalinas, entre outras.', 1, false, 0, ' ');
insert into contabilidade.planocontadetalhe values (1569, 2, '1.1.3.2.1.00.00.00.00.00', 'TRIBUTOS A RECUPERAR/COMPENSAR - CONSOLIDAÇÃO', 'Compreende o somatório dos valores dos tributos a recuperar/compensar. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1570, 2, '1.1.3.2.2.00.00.00.00.00', 'TRIBUTOS A RECUPERAR/COMPENSAR - INTRA OFSS', 'Compreende o somatório dos valores dos tributos a recuperar/compensar. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do ente.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1668, 2, '1.2.1.1.1.04.01.08.00.00', 'DÍVIDA ATIVA DO ITR', 'Compreende os valores relativos a créditos inscritos de Dívida Ativa do itr.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1571, 2, '1.1.3.2.3.00.00.00.00.00', 'TRIBUTOS A RECUPERAR/COMPENSAR - INTER OFSS - UNIÃO', 'Compreende o somatório dos valores dos tributos a recuperar/compensar. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1572, 2, '1.1.3.2.4.00.00.00.00.00', 'TRIBUTOS A RECUPERAR/COMPENSAR - INTER OFSS - ESTADO', 'Compreende o somatório dos valores dos tributos a recuperar/compensar. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1573, 2, '1.1.3.2.5.00.00.00.00.00', 'TRIBUTOS A RECUPERAR/COMPENSAR - INTER OFSS - MUNICÍPIO', 'Compreende o somatório dos valores dos tributos a recuperar/compensar. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1574, 2, '1.1.3.3.0.00.00.00.00.00', 'CRÉDITOS A RECEBER POR DESCENTRALIZAÇÃO DA PRESTAÇÃO DE SERVIÇOS PÚBLICOS', 'Compreende os créditos a receber decorrentes da descentralização de serviços públicos, tanto por meio de outorga a entidades da administração indireta como por meio de delegação, nas formas de concessão, inclusive parcerias público-privada - PPP, permissão ou autorização ao particular do direito de exploração de serviços públicos.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1575, 2, '1.1.3.3.1.00.00.00.00.00', 'CRÉDITOS A RECEBER POR DESCENTRALIZAÇÃO DA PRESTAÇÃO DE SERVIÇOS PÚBLICOS - CONSOLIDAÇÃO', 'Compreende os créditos a receber decorrentes da descentralização de serviços públicos, tanto por meio de outorga a entidades da administração indireta, como por meio de delegação, nas formas de concessão, inclusive parcerias público-privada - PPP, permissão ou autorização ao particular do direito de exploração de serviços públicos. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1576, 2, '1.1.3.4.0.00.00.00.00.00', 'CRÉDITOS POR DANOS AO PATRIMÔNIO', 'Compreende os valores realizáveis no curto prazo, provenientes de direitos oriundos de danos ao patrimônio, apurados em sindicância, prestação de contas, tomada de contas, processos judiciais e outros.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1577, 2, '1.1.3.4.1.00.00.00.00.00', 'CRÉDITOS POR DANOS AO PATRIMÔNIO - CONSOLIDAÇÃO', 'Compreende os valores realizáveis no curto prazo, provenientes de direitos oriundos de danos ao patrimônio, apurados em sindicância, prestação de contas, tomada de contas, processos judiciais e outros. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1578, 2, '1.1.3.5.0.00.00.00.00.00', 'DEPÓSITOS RESTITUÍVEIS E VALORES VINCULADOS', 'Compreende os valores de depósitos e cauções efetuados e recebidos pela entidade para garantia de contratos, bem como para direito de uso, exploração temporária de bens ou de natureza judicial, depósitos compulsórios e demais recursos vinculados, realizáveis no curto prazo.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1579, 2, '1.1.3.5.1.00.00.00.00.00', 'DEPÓSITOS RESTITUÍVEIS E VALORES VINCULADOS - CONSOLIDAÇÃO', 'Compreende os valores de depósitos e cauções efetuados e recebidos pela entidade para garantia de contratos, bem como para direito de uso, exploração temporária de bens ou de natureza judicial, depósitos compulsórios e demais recursos vinculados, realizáveis no curto prazo. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1580, 2, '1.1.3.6.0.00.00.00.00.00', 'CRÉDITOS PREVIDENCIÁRIOS A RECEBER A CURTO PRAZO', 'Compreende os valores relativos aos créditos previdenciários a receber, realizáveis no curto prazo.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1581, 2, '1.1.3.6.1.00.00.00.00.00', 'CRÉDITOS PREVIDENCIÁRIOS A RECEBER A CURTO PRAZO - CONSOLIDAÇÃO', 'Compreende os valores relativos aos créditos previdenciários a receber, realizáveis no curto prazo. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1582, 2, '1.1.3.6.1.01.00.00.00.00', 'CONTRIBUIÇÕES PREVIDENCIÁRIAS A RECEBER - ', 'Registra os valores relativos aos créditos a receber, decorrentes das contribuições para o financiamento da previdência social.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1583, 2, '1.1.3.6.1.02.00.00.00.00', 'CRÉDITOS PREVIDENCIÁRIOS PARCELADOS', 'Registra os valores relativos aos créditos a receber, decorrentes de créditos previdenciários parcelados.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1584, 2, '1.1.3.6.2.00.00.00.00.00', 'CRÉDITOS PREVIDENCIÁRIOS A RECEBER A CURTO PRAZO - INTRA OFSS', 'Compreende os valores relativos aos créditos previdenciários a receber, realizáveis no curto prazo. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do ente.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1585, 2, '1.1.3.6.2.01.00.00.00.00', 'CONTRIBUIÇÕES PREVIDENCIÁRIAS A RECEBER', 'Registra os valores relativos aos créditos a receber, decorrentes das contribuições para o financiamento da previdência social.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1586, 2, '1.1.3.6.2.02.00.00.00.00', 'CRÉDITOS PREVIDENCIÁRIOS PARCELADOS', 'Registra os valores relativos aos créditos a receber, decorrentes de créditos previdenciários parcelados.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1587, 2, '1.1.3.6.2.03.00.00.00.00', 'COMPENSAÇÃO FINANCEIRA ENTRE REGIMES PREVIDENCIÁRIOS', 'Registra os valores relativos aos créditos a receber decorrentes de compensação financeira entre regimes de previdência, por contagem recíproca de tempo de contribuição.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1588, 2, '1.1.3.6.2.99.00.00.00.00', 'OUTROS CRÉDITOS PREVIDENCIÁRIOS ', 'Registra os valores relativos a outros créditos previdenciários devidos ao RPPS pelo ente, sujeitos a pagamento em parcela única ou parcelados.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1589, 2, '1.1.3.6.3.00.00.00.00.00', 'CRÉDITOS PREVIDENCIÁRIOS A RECEBER A CURTO PRAZO -  INTER OFSS - UNIÃO', 'Compreende os valores relativos aos créditos previdenciários a receber, realizáveis no curto prazo. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1590, 2, '1.1.3.6.3.03.00.00.00.00', 'COMPENSAÇÃO FINANCEIRA ENTRE REGIMES PREVIDENCIÁRIOS', 'Registra os valores relativos aos créditos a receber decorrentes de compensação financeira entre regimes de previdência, por contagem recíproca de tempo de contribuição.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1591, 2, '1.1.3.6.3.99.00.00.00.00', 'OUTROS CRÉDITOS PREVIDENCIÁRIOS ', 'Registra os valores relativos a outros créditos previdenciários devidos ao RPPS pelo ente, sujeitos a pagamento em parcela única ou parcelados.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1592, 2, '1.1.3.6.4.00.00.00.00.00', 'CRÉDITOS PREVIDENCIÁRIOS A RECEBER A CURTO PRAZO - INTER OFSS - ESTADO', 'Compreende os valores relativos aos créditos previdenciários a receber, realizáveis no curto prazo. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1593, 2, '1.1.3.6.4.03.00.00.00.00', 'COMPENSAÇÃO FINANCEIRA ENTRE REGIMES PREVIDENCIÁRIOS', 'Registra os valores relativos aos créditos a receber decorrentes de compensação financeira entre regimes de previdência, por contagem recíproca de tempo de contribuição.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1594, 2, '1.1.3.6.4.99.00.00.00.00', 'OUTROS CRÉDITOS PREVIDENCIÁRIOS ', 'Registra os valores relativos a outros créditos previdenciários devidos ao RPPS pelo ente, sujeitos a pagamento em parcela única ou parcelados.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1595, 2, '1.1.3.6.5.00.00.00.00.00', 'CRÉDITOS PREVIDENCIÁRIOS A RECEBER A CURTO PRAZO - INTER OFSS - MUNICÍPIO', 'Compreende os valores relativos aos créditos previdenciários a receber, realizáveis no curto prazo. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1596, 2, '1.1.3.6.5.03.00.00.00.00', 'COMPENSAÇÃO FINANCEIRA ENTRE REGIMES PREVIDENCIÁRIOS', 'Registra os valores relativos aos créditos a receber decorrentes de compensação financeira entre regimes de previdência, por contagem recíproca de tempo de contribuição.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1597, 2, '1.1.3.6.5.99.00.00.00.00', 'OUTROS CRÉDITOS PREVIDENCIÁRIOS ', 'Registra os valores relativos a outros créditos previdenciários devidos ao RPPS pelo ente, sujeitos a pagamento em parcela única ou parcelados.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1598, 2, '1.1.3.8.0.00.00.00.00.00', 'OUTROS CRÉDITOS A RECEBER E VALORES A CURTO PRAZO', 'Compreende os outros créditos e valores realizáveis no curto prazo, provenientes de direitos obtidos junto a diversos devedores.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1599, 2, '1.1.3.8.1.00.00.00.00.00', 'OUTROS CRÉDITOS A RECEBER E VALORES A CURTO PRAZO - CONSOLIDAÇÃO', 'Compreende os outros créditos e valores realizáveis no curto prazo, provenientes de direitos obtidos junto a diversos devedores. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1600, 2, '1.1.3.8.1.27.00.00.00.00', 'TÍTULOS A RECEBER', 'Compreende os valores a receber a curto prazo representados por notas promissórias, letras de câmbio e outros.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1601, 2, '1.2.1.1.1.04.01.00.00.00', 'CRÉDITOS NÃO PREVIDENCIÁRIOS INSCRITOS', 'Compreende os valores relativos a créditos inscritos de Dívida Ativa tributária não previdenciária.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1602, 2, '1.1.4.0.0.00.00.00.00.00', 'INVESTIMENTOS E APLICAÇÕES TEMPORÁRIAS A CURTO PRAZO', 'Compreendem as aplicações de recursos em títulos e valores mobiliários, não destinadas à negociação e que não façam parte das atividades operacionais da entidade, resgatáveis no curto prazo, alem das aplicações temporárias em metais preciosos.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1603, 2, '1.1.4.1.0.00.00.00.00.00', 'TÍTULOS E VALORES MOBILIÁRIOS', 'Compreendem as aplicações de recursos em títulos e valores mobiliários, não destinadas à negociação e que não façam parte das atividades operacionais da entidade, resgatáveis no curto prazo.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1604, 2, '1.1.4.1.1.00.00.00.00.00', 'TÍTULOS E VALORES MOBILIÁRIOS- CONSOLIDAÇÃO', 'Compreendem as aplicações de recursos em títulos e valores mobiliários, não destinadas à negociação e que não façam parte das atividades operacionais da entidade, resgatáveis em até 12 (doze) meses da data das demonstrações. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1605, 2, '1.1.4.1.1.09.00.00.00.00', 'APLICAÇÕES EM SEGMENTO DE RENDA FIXA - RPPS', 'Compreende o somatório dos investimentos realizados pelo RPPS com recursos previdenciários, efetuados em conformidade com a legislação específica.', 1, false, 0, ' ');
insert into contabilidade.planocontadetalhe values (1606, 2, '1.1.4.1.1.10.00.00.00.00', 'APLICAÇÕES EM SEGMENTO DE RENDA VARIÁVEL - RPPS', 'Compreende o somatório dos investimentos realizados pelo RPPS com recursos previdenciários, efetuados em conformidade com a legislação específica.', 1, false, 0, ' ');
insert into contabilidade.planocontadetalhe values (1607, 2, '1.1.4.1.1.11.00.00.00.00', 'APLICAÇÕES EM SEGMENTO IMOBILIÁRIO - RPPS', 'Compreende o somatório dos investimentos realizados pelo RPPS com recursos previdenciários não financeiros em segmento imobiliário.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1608, 2, '1.1.4.1.1.12.00.00.00.00', 'APLICAÇÕES EM ENQUADRAMENTO - RPPS', 'Compreende os investimentos realizados pelo RPPS em desacordo com as regras estabelecidas pelas Resoluções CMN nº 3.922/2010 e nº 4.392/2014.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1609, 2, '1.1.4.1.1.13.00.00.00.00', 'TÍTULOS E VALORES NÃO SUJEITOS AO ENQUADRAMENTO - RPPS', 'Compreende os investimentos realizados pelo RPPS em ativos não sujeitos às regras das Resoluções CMN nº 3.922/2010 e nº 4.392/2014.', 1, false, 0, ' ');
insert into contabilidade.planocontadetalhe values (1610, 2, '1.1.4.1.1.14.00.00.00.00', 'APLICAÇÕES COM A TAXA DE ADMINISTRAÇÃO DO RPPS', 'Compreende os investimentos realizados pelo RPPS com recursos da taxa de administração, sujeitos às regras das Resoluções CMN nº 3.922/2010 e nº 4.392/2014.', 1, false, 0, ' ');
insert into contabilidade.planocontadetalhe values (1611, 2, '1.1.4.2.0.00.00.00.00.00', 'APLICAÇÃO TEMPORÁRIA EM METAIS PRECIOSOS', 'Compreende as aplicações de recursos em metais preciosos, não destinados a negociação e que não façam parte das atividades operacionais da entidade, resgatáveis no curto prazo.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1612, 2, '1.1.4.2.1.00.00.00.00.00', 'APLICAÇÃO TEMPORÁRIA EM METAIS PRECIOSOS - CONSOLIDAÇÃO', 'Compreende as aplicações de recursos em metais preciosos, não destinados a negociação e que não façam parte das atividades operacionais da entidade, resgatáveis no curto prazo. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (1613, 2, '1.1.4.3.0.00.00.00.00.00', 'APLICAÇÕES EM SEGMENTO DE IMÓVEIS', 'Compreende os investimentos de longo prazo realizados em segmento de imóveis, realizáveis no curto prazo.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1614, 2, '1.1.4.3.1.00.00.00.00.00', 'APLICAÇÕES EM SEGMENTO DE IMÓVEIS - CONSOLIDAÇÃO', 'Compreende os investimentos de longo prazo realizados em segmento de imóveis, realizáveis no curto prazo. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (1615, 2, '1.1.5.0.0.00.00.00.00.00', 'ESTOQUES', 'Compreende o valor dos bens adquiridos, produzidos ou em processo de elaboração pela entidade com o objetivo de venda ou utilização própria no curso normal das atividades.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1616, 2, '1.1.5.1.0.00.00.00.00.00', 'MERCADORIAS PARA REVENDA', 'Compreende todos os produtos adquiridos de terceiros para revenda, que não sofrem nenhum processo de transformação na entidade.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1617, 2, '1.1.5.1.1.00.00.00.00.00', 'MERCADORIAS PARA REVENDA - CONSOLIDAÇÃO', 'Compreende todos os produtos adquiridos de terceiros para revenda, que não sofrem nenhum processo de transformação na entidade. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1618, 2, '1.1.5.2.0.00.00.00.00.00', 'PRODUTOS E SERVIÇOS ACABADOS', 'Compreende os produtos já terminados e oriundos da própria produção da entidade e disponíveis para venda, estocados na fabrica, ou em depósitos, ou em filiais, ou ainda com terceiros em consignação e os serviços acabados.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1619, 2, '1.1.5.2.1.00.00.00.00.00', 'PRODUTOS E SERVIÇOS ACABADOS - CONSOLIDAÇÃO', 'Compreende os produtos já terminados oriundos da própria produção da entidade e disponíveis para venda, estocados na fabrica, ou em depósitos, ou em filiais, ou ainda com terceiros em consignação e os serviços acabados. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1620, 2, '1.1.5.3.0.00.00.00.00.00', 'PRODUTOS E SERVIÇOS EM ELABORAÇÃO', 'Compreende os produtos e serviços em andamento não concluídos na data do balanço.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1621, 2, '1.1.5.3.1.00.00.00.00.00', 'PRODUTOS E SERVIÇOS EM ELABORAÇÃO - CONSOLIDAÇÃO', 'Compreende os produtos e serviços em andamento não concluídos na data do balanço. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1622, 2, '1.1.5.4.0.00.00.00.00.00', 'MATÉRIAS-PRIMAS', 'Compreende o estoque de matérias-primas, que será utilizado no processo produtivo.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1623, 2, '1.1.5.4.1.00.00.00.00.00', 'MATÉRIAS-PRIMAS - CONSOLIDAÇÃO', 'Compreende o estoque de matérias-primas, que será utilizado no processo produtivo.. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1624, 2, '1.1.5.5.0.00.00.00.00.00', 'MATERIAIS EM TRÂNSITO', 'Compreende o valor dos materiais em processo de transferência para outras unidades da entidade.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1625, 2, '1.1.5.5.1.00.00.00.00.00', 'MATERIAIS EM TRÂNSITO - CONSOLIDAÇÃO', 'Compreende o valor dos materiais em processo de transferência para outras unidades da entidade. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1626, 2, '1.1.5.6.0.00.00.00.00.00', 'ALMOXARIFADO', 'Compreende o valor dos materiais destinados ao consumo interno da unidade.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1627, 2, '1.1.5.6.1.00.00.00.00.00', 'ALMOXARIFADO - CONSOLIDAÇÃO', 'Compreende o valor dos materiais destinados ao consumo interno da unidade. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1628, 2, '1.1.5.8.0.00.00.00.00.00', 'OUTROS ESTOQUES', 'Compreende o valor dos outros bens adquiridos, produzidos ou em processo de elaboração pela entidade com o objetivo de venda ou utilização própria no curso normal das atividades.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1629, 2, '1.1.5.8.1.00.00.00.00.00', 'OUTROS ESTOQUES - CONSOLIDAÇÃO', 'Compreende o valor dos outros bens adquiridos, produzidos ou em processo de elaboração pela entidade com o objetivo de venda ou utilização própria no curso normal das atividades. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1630, 2, '1.1.6.0.0.00.00.00.00.00', 'ATIVO NÃO CIRCULANTE MANTIDO PARA VENDA', 'Compreende os ativos não circulantes cuja recuperação esperada do seu valor contábil venha a ocorrer por meio de uma transação de venda em vez do uso contínuo, dentro de um prazo inferior a 12 meses.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1631, 2, '1.1.6.1.0.00.00.00.00.00', 'INVESTIMENTO MANTIDO PARA VENDA', 'Compreende os ativos de investimentos mantidos para venda, segundo um plano de venda com prazo inferior a doze meses.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1632, 2, '1.1.6.1.1.00.00.00.00.00', 'INVESTIMENTO MANTIDO PARA VENDA - CONSOLIDAÇÃO', 'Compreende os ativos de investimentos mantidos para venda, segundo um plano de venda com prazo inferior a doze meses. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (1633, 2, '1.1.6.1.2.00.00.00.00.00', 'INVESTIMENTO MANTIDO PARA VENDA - INTRA OFSS', 'Compreende os ativos de investimentos mantidos para venda, segundo um plano de venda com prazo inferior a doze meses. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do ente.', 1, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (1634, 2, '1.2.2.1.5.02.00.00.00.00', 'PARTICIPAÇÕES AVALIADAS PELO MÉTODO DE CUSTO', 'Compreende as participações permanentes da unidade em outras sociedades em forma de ações ou cotas, avaliadas pelo método de custo.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1635, 2, '1.1.6.1.3.00.00.00.00.00', 'INVESTIMENTO MANTIDO PARA VENDA - INTER OFSS - UNIÃO', 'Compreende os ativos de investimentos mantidos para venda, segundo um plano de venda com prazo inferior a doze meses. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 1, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (1636, 2, '1.1.6.1.4.00.00.00.00.00', 'INVESTIMENTO MANTIDO PARA VENDA - INTER OFSS - ESTADO', 'Compreende os ativos de investimentos mantidos para venda, segundo um plano de venda com prazo inferior a doze meses. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 1, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (1637, 2, '1.1.6.1.5.00.00.00.00.00', 'INVESTIMENTO MANTIDO PARA VENDA - INTER OFSS - MUNICÍPIO', 'Compreende os ativos de investimentos mantidos para venda, segundo um plano de venda com prazo inferior a doze meses. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município. ', 1, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (1638, 2, '1.1.6.2.0.00.00.00.00.00', 'IMOBILIZADO MANTIDO PARA VENDA', 'Compreende os ativos imobilizados mantidos para venda, segundo um plano de venda com prazo inferior a doze meses.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1639, 2, '1.1.6.2.1.00.00.00.00.00', 'IMOBILIZADO MANTIDO PARA VENDA - CONSOLIDAÇÃO', 'Compreende os ativos imobilizados mantidos para venda, segundo um plano de venda com prazo inferior a doze meses. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (1640, 2, '1.1.6.3.0.00.00.00.00.00', 'INTANGÍVEL MANTIDO PARA VENDA', 'Compreende os ativos intangíveis mantidos para venda, segundo um plano de venda com prazo inferior a doze meses.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1641, 2, '1.1.6.3.1.00.00.00.00.00', 'INTANGÍVEL MANTIDO PARA VENDA - CONSOLIDAÇÃO', 'Compreende os ativos intangíveis mantidos para venda, segundo um plano de venda com prazo inferior a doze meses. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (1642, 2, '1.2.1.1.1.04.01.01.00.00', 'DÍVIDA ATIVA DO IMPOSTO SOBRE A RENDA E PROVENTOS DE QUALQUER NATUREZA', 'Compreende os valores relativos a créditos inscritos de Dívida Ativa do imposto sobre renda e proventos de qualquer natureza.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1643, 2, '1.1.9.0.0.00.00.00.00.00', 'VARIAÇÕES PATRIMONIAIS DIMINUTIVAS PAGAS ANTECIPADAMENTE', 'Compreende pagamentos de variações patrimoniais diminutivas (VPD) antecipadas, cujos benefícios ou prestação de serviço a entidade ocorrerão no curto prazo.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1644, 2, '1.1.9.1.0.00.00.00.00.00', 'PRÊMIOS DE SEGUROS A APROPRIAR', 'Compreende os valores pagos a titulo de prêmios de seguro a apropriar.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1645, 2, '1.1.9.1.1.00.00.00.00.00', 'PRÊMIOS DE SEGUROS A APROPRIAR - CONSOLIDAÇÃO', 'Compreende os valores pagos a titulo de prêmios de seguro a apropriar. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'p');
insert into contabilidade.planocontadetalhe values (1646, 2, '1.1.9.2.1.00.00.00.00.00', 'VPD FINANCEIRAS A APROPRIAR - CONSOLIDAÇÃO', 'Compreende os valores pagos, a título de VPD financeiras a apropriar. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'p');
insert into contabilidade.planocontadetalhe values (1647, 2, '1.1.9.3.0.00.00.00.00.00', 'ASSINATURAS E ANUIDADES A APROPRIAR', 'Compreende os valores pagos a titulo de assinaturas e anuidades a apropriar.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1648, 2, '1.1.9.3.1.00.00.00.00.00', 'ASSINATURAS E ANUIDADES A APROPRIAR - CONSOLIDAÇÃO', 'Compreende os valores pagos a titulo de assinaturas e anuidades a apropriar. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'p');
insert into contabilidade.planocontadetalhe values (1649, 2, '1.1.9.4.0.00.00.00.00.00', 'ALUGUEIS PAGOS A APROPRIAR', 'Compreende os valores pagos a titulo de aluguel a apropriar.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1650, 2, '1.1.9.4.1.00.00.00.00.00', 'ALUGUEIS PAGOS A APROPRIAR - CONSOLIDAÇÃO', 'Compreende os valores pagos a titulo de aluguel a apropriar. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'p');
insert into contabilidade.planocontadetalhe values (1651, 2, '1.1.9.5.0.00.00.00.00.00', 'TRIBUTOS PAGOS A APROPRIAR', 'Compreende os valores pagos a titulo de tributos a apropriar.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1652, 2, '1.1.9.5.1.00.00.00.00.00', 'TRIBUTOS PAGOS A APROPRIAR - CONSOLIDAÇÃO', 'Compreende os valores pagos a titulo de tributos a apropriar. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'p');
insert into contabilidade.planocontadetalhe values (1653, 2, '1.1.9.6.0.00.00.00.00.00', 'CONTRIBUIÇÕES CONFEDERATIVAS A APROPRIAR', 'Compreende os valores pagos a titulo de contribuições confederativas a apropriar', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1654, 2, '1.1.9.6.1.00.00.00.00.00', 'CONTRIBUIÇÕES CONFEDERATIVAS A APROPRIAR - CONSOLIDAÇÃO', 'Compreende os valores pagos a titulo de contribuições confederativas a apropriar. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'p');
insert into contabilidade.planocontadetalhe values (1655, 2, '1.1.9.7.0.00.00.00.00.00', 'BENEFÍCIOS A PESSOAL A APROPRIAR', 'Compreende os valores pagos a titulo de beneficio a pessoal a apropriar.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1656, 2, '1.1.9.7.1.00.00.00.00.00', 'BENEFÍCIOS A PESSOAL A APROPRIAR - CONSOLIDAÇÃO', 'Compreende os valores pagos a titulo de beneficio a pessoal a apropriar. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (1657, 2, '1.1.9.8.0.00.00.00.00.00', 'DEMAIS VPD A APROPRIAR', 'Compreende os demais valores pagos a apropriar.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1658, 2, '1.1.9.8.1.00.00.00.00.00', 'DEMAIS VPD A APROPRIAR - CONSOLIDAÇÃO', 'Compreende os demais valores pagos a apropriar. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (1659, 2, '1.2.0.0.0.00.00.00.00.00', 'ATIVO NÃO CIRCULANTE', 'Compreende o ativo não circulante: o ativo realizável a longo prazo, os investimentos, o imobilizado e o intangível.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1660, 2, '1.2.1.0.0.00.00.00.00.00', 'ATIVO REALIZÁVEL A LONGO PRAZO', 'Compreende os bens, direitos e despesas antecipadas realizáveis no longo prazo.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1729, 2, '1.2.3.1.1.08.00.00.00.00', 'BENS MÓVEIS EM ALMOXARIFADO', 'Compreende os valores de bens permanentes a serem estocados em almoxarifado.', 1, false, 0, ' ');
insert into contabilidade.planocontadetalhe values (1661, 2, '1.2.1.1.0.00.00.00.00.00', 'CRÉDITOS A LONGO PRAZO', 'Compreende os valores a receber por fornecimento de bens, serviços, créditos tributários, dívida ativa, transferências e empréstimos e financiamentos concedidos e com vencimento no longo prazo.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1662, 2, '1.2.1.1.1.00.00.00.00.00', 'CRÉDITOS A LONGO PRAZO - CONSOLIDAÇÃO', 'Compreende os valores a receber por fornecimento de bens, serviços, créditos tributários, dívida ativa, transferências e empréstimos e financiamentos concedidos com vencimento no longo prazo. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1663, 2, '1.2.1.1.1.01.00.00.00.00', 'CRÉDITOS TRIBUTÁRIOS A RECEBER', 'Compreende os valores relativos a créditos a receber com vencimento após 12 (doze) meses da data das demonstrações, oriundos das variações patrimoniais aumentativas tributárias. Os tributos são: impostos, taxas, contribuições de melhoria, contribuições e empréstimos compulsórios.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1664, 2, '1.2.1.1.1.02.00.00.00.00', 'CLIENTES', 'Compreende os valores das faturas/duplicatas a receber decorrentes das vendas a prazo de mercadorias ou serviços que ocorrem no curso normal das operações da entidade (com vencimento após 12 (doze) meses da data das demonstrações), representando um direito a cobrar de seus clientes.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1665, 2, '1.2.1.1.1.03.00.00.00.00', 'EMPRÉSTIMOS E FINANCIAMENTOS CONCEDIDOS', 'Compreende o somatório dos valores de empréstimos e financiamentos concedidos por autorizações legais ou vinculações a contratos e acordos.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1666, 2, '1.2.1.1.1.04.00.00.00.00', 'DÍVIDA ATIVA TRIBUTÁRIA', 'Compreende os valores dos créditos de dívida ativa tributária inscritos, realizáveis após os doze meses seguintes a data de publicação dos demonstrativos contábeis.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1669, 2, '1.2.1.1.1.05.00.00.00.00', 'DÍVIDA ATIVA NÃO TRIBUTÁRIA', 'Compreende os valores dos créditos de dívida ativa não tributária inscritos, realizáveis no longo prazo.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1670, 2, '1.2.1.1.2.00.00.00.00.00', 'CRÉDITOS A LONGO PRAZO - INTRA OFSS', 'Compreende os valores a receber por fornecimento de bens, serviços, créditos tributários, dívida ativa, transferências e empréstimos e financiamentos concedidos com vencimento no longo prazo. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do ente.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1671, 2, '1.2.1.1.3.00.00.00.00.00', 'CRÉDITOS A LONGO PRAZO - INTER OFSS - UNIÃO', 'Compreende os valores a receber por fornecimento de bens, serviços, créditos tributários, dívida ativa, transferências e empréstimos e financiamentos concedidos com vencimento no longo prazo. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) de entes públicos distintos, para permitir a consolidação nacional realizada pelo Poder Executivo da União. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1672, 2, '1.2.1.1.4.00.00.00.00.00', 'CRÉDITOS A LONGO PRAZO - INTER OFSS - ESTADO', 'Compreende os valores a receber por fornecimento de bens, serviços, créditos tributários, dívida ativa, transferências e empréstimos e financiamentos concedidos com vencimento no longo prazo. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) de entes públicos distintos, para permitir a consolidação nacional realizada pelo Poder Executivo da União. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1673, 2, '1.2.1.1.4.03.00.00.00.00', 'EMPRÉSTIMOS E FINANCIAMENTOS CONCEDIDOS', 'Compreende o somatório dos valores de empréstimos e financiamentos concedidos por autorizações legais ou vinculações a contratos e acordos.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1674, 2, '1.2.1.1.5.00.00.00.00.00', 'CRÉDITOS A LONGO PRAZO - INTER OFSS - MUNICÍPIO', 'Compreende os valores a receber por fornecimento de bens, serviços, créditos tributários, dívida ativa, transferências e empréstimos e financiamentos concedidos com vencimento no longo prazo. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) de entes públicos distintos, para permitir a consolidação nacional realizada pelo Poder Executivo da União. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1675, 2, '1.2.1.1.5.03.00.00.00.00', 'EMPRÉSTIMOS E FINANCIAMENTOS CONCEDIDOS', 'Compreende o somatório dos valores de empréstimos e financiamentos concedidos por autorizações legais ou vinculações a contratos e acordos.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1676, 2, '1.2.1.2.0.00.00.00.00.00', 'DEMAIS CRÉDITOS E VALORES A LONGO PRAZO', 'Compreende os valores a receber por demais transações, com vencimento no longo prazo.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1677, 2, '1.2.1.2.1.00.00.00.00.00', 'DEMAIS CRÉDITOS E VALORES A LONGO PRAZO - CONSOLIDAÇÃO', 'Compreende os valores a receber por demais transações, com vencimento no longo prazo. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1678, 2, '1.2.1.2.1.01.00.00.00.00', 'ADIANTAMENTOS CONCEDIDOS A PESSOAL E A TERCEIROS', 'Compreende as antecipações concedidas à pessoal, tais como antecipações de salários e ordenados, adiantamentos de 13º salário, adiantamentos de ferias e outros, alem da entrega de numerário a terceiros sem vinculação especifica ao fornecimento de bens ou serviços.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1679, 2, '1.2.1.2.1.02.00.00.00.00', 'TRIBUTOS A RECUPERAR/COMPENSAR', 'Compreende o somatório dos valores dos tributos a recuperar/compensar.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1680, 2, '1.2.1.2.1.04.00.00.00.00', 'CRÉDITOS POR DANOS AO PATRIMÔNIO PROVENIENTES DE CRÉDITOS ADMINISTRATIVOS', 'Compreende os valores realizáveis após os doze meses seguintes a data de publicação das demonstrações contábeis, provenientes de direitos oriundos de danos ao patrimônio, apurados em processos administrativos.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1681, 2, '1.2.1.2.1.05.00.00.00.00', 'CRÉDITOS POR DANOS AO PATRIMÔNIO APURADOS EM TOMADA DE CONTAS ESPECIAL', 'Compreende os valores realizáveis após os doze meses seguintes a data de publicação das demonstrações contábeis, provenientes de direitos oriundos de danos ao patrimônio, apurados em tomada de contas especial.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1730, 2, '1.2.3.1.1.99.00.00.00.00', 'DEMAIS BENS MÓVEIS', 'Compreende o valor da aquisição ou incorporação dos demais bens móveis não classificados em grupos específicos.', 1, false, 0, ' ');
insert into contabilidade.planocontadetalhe values (1682, 2, '1.2.1.2.1.06.00.00.00.00', 'DEPÓSITOS RESTITUÍVEIS E VALORES VINCULADOS', 'Compreende os valores de depósitos e cauções efetuados e recebidos pela entidade para garantia de contratos, bem como para direito de uso, exploração temporária de bens ou de natureza judicial, depósitos compulsórios e demais recursos vinculados, realizáveis após os doze meses seguintes a data de publicação das demonstrações contábeis.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1683, 2, '1.2.1.2.1.98.00.00.00.00', 'OUTROS CRÉDITOS A RECEBER E VALORES A LONGO PRAZO', 'Compreende os outros créditos e valores realizáveis após os doze meses seguintes a data da publicação das demonstrações contábeis, provenientes de direitos obtidos junto a diversos devedores.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1684, 2, '1.2.1.2.1.98.99.00.00.00', 'OUTROS CRÉDITOS A RECEBER E VALORES A LONGO PRAZO', 'Compreende o valor de outros créditos a receber e valores realizáveis no longo prazo.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1685, 2, '1.2.3.2.1.06.00.00.00.00', 'BENS IMÓVEIS EM ANDAMENTO', 'Compreende os valores de bens imóveis em andamento.', 1, false, 0, ' ');
insert into contabilidade.planocontadetalhe values (1686, 2, '1.2.1.3.0.00.00.00.00.00', 'INVESTIMENTOS E APLICAÇÕES TEMPORÁRIAS A LONGO PRAZO', 'Compreende as aplicações de recursos em títulos, valores mobiliários e imobiliários, não destinadas à negociação e que não façam parte das atividades operacionais da entidade, resgatáveis no longo prazo.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1687, 2, '1.2.1.3.1.00.00.00.00.00', 'INVESTIMENTOS E APLICAÇÕES TEMPORÁRIAS A LONGO PRAZO - CONSOLIDAÇÃO', 'Compreende as aplicações de recursos em títulos, valores mobiliários e imobiliários, não destinadas à negociação e que não façam parte das atividades operacionais da entidade, resgatáveis no longo prazo. Não inclui as aplicações dos recursos do RPPS. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1688, 2, '1.2.1.3.1.01.00.00.00.00', 'TÍTULOS E VALORES MOBILIÁRIOS', 'Compreendem as aplicações de recursos em títulos e valores mobiliários, não destinadas à negociação e que não façam parte das atividades operacionais da entidade, resgatáveis após os doze meses seguintes a data da publicação das demonstrações contábeis.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1689, 2, '1.2.1.3.1.02.00.00.00.00', 'APLICAÇÃO TEMPORÁRIA EM METAIS PRECIOSOS', 'Compreendem as aplicações de recursos em metais preciosos, não destinados a negociação e que não façam parte das atividades operacionais da entidade, resgatáveis após os doze meses seguintes a data da publicação das demonstrações contábeis.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1690, 2, '1.2.1.4.0.00.00.00.00.00', 'ESTOQUES', 'Compreende o valor dos bens adquiridos, produzidos ou em processo de elaboração pela entidade para utilização própria ou para venda, previstos para período posterior aos 12 (doze) meses seguintes a data da publicação das demonstrações contábeis.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1691, 2, '1.2.1.4.1.00.00.00.00.00', 'ESTOQUES - CONSOLIDAÇÃO', 'Compreende o valor dos bens adquiridos, produzidos ou em processo de elaboração pela entidade com o objetivo de venda ou utilização própria no curso normal das atividades. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1692, 2, '1.2.1.9.0.00.00.00.00.00', 'VARIAÇÕES PATRIMONIAIS DIMINUTIVAS PAGAS ANTECIPADAMENTE', 'Compreende pagamentos de variações patrimoniais diminutivas (VPD) antecipadas, cujos benefícios ou prestação de serviço à entidade ocorrerão no longo prazo.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1693, 2, '1.2.1.9.1.00.00.00.00.00', 'VARIAÇÕES PATRIMONIAIS DIMINUTIVAS PAGAS ANTECIPADAMENTE- CONSOLIDAÇÃO', 'Compreende pagamentos de variações patrimoniais diminutivas (VPD) antecipadas, cujos benefícios ou prestação de serviço a entidade ocorrerão no longo prazo. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1694, 2, '1.2.2.0.0.00.00.00.00.00', 'INVESTIMENTOS', 'Compreende as participações permanentes em outras sociedades, bem como os bens e direitos não classificáveis no ativo circulante nem no ativo realizável a longo prazo e que não se destinem a manutenção da atividade da entidade.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1695, 2, '1.2.2.1.0.00.00.00.00.00', 'PARTICIPAÇÕES PERMANENTES', 'Compreende as participações permanentes da unidade em outras entidades em forma de ações ou cotas.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1696, 2, '1.2.2.1.1.00.00.00.00.00', 'PARTICIPAÇÕES PERMANENTES - CONSOLIDAÇÃO', 'Compreende as participações permanentes da unidade em outras entidades em forma de ações ou cotas. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1697, 2, '1.2.2.1.1.01.00.00.00.00', 'PARTICIPAÇÕES AVALIADAS PELO MÉTODO DE EQUIVALÊNCIA PATRIMONIAL', 'Compreende as participações permanentes da unidade em outras entidades em forma de ações ou cotas, avaliadas pelo método de equivalência patrimonial.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1698, 2, '1.2.2.1.1.02.00.00.00.00', 'PARTICIPAÇÕES AVALIADAS PELO MÉTODO DE CUSTO', 'Compreende as participações permanentes da unidade em outras sociedades em forma de ações ou cotas, avaliadas pelo método de custo.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1699, 2, '1.2.2.1.2.00.00.00.00.00', 'PARTICIPAÇÕES PERMANENTES - INTRA OFSS', 'Compreende as participações permanentes da entidade em outras sociedades em forma de ações ou cotas. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do ente.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1700, 2, '1.2.2.1.2.01.00.00.00.00', 'PARTICIPAÇÕES AVALIADAS PELO MÉTODO DE EQUIVALÊNCIA PATRIMONIAL', 'Compreende as participações permanentes da unidade em outras entidades em forma de ações ou cotas, avaliadas pelo método de equivalência patrimonial.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1701, 2, '1.2.2.1.2.02.00.00.00.00', 'PARTICIPAÇÕES AVALIADAS PELO MÉTODO DE CUSTO', 'Compreende as participações permanentes da unidade em outras sociedades em forma de ações ou cotas, avaliadas pelo método de custo.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1702, 2, '1.2.2.1.3.00.00.00.00.00', 'PARTICIPAÇÕES PERMANENTES - INTER OFSS - UNIÃO', 'Compreende as participações permanentes da entidade em outras sociedades em forma de ações ou cotas. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1703, 2, '1.2.2.1.3.01.00.00.00.00', 'PARTICIPAÇÕES AVALIADAS PELO MÉTODO DE EQUIVALÊNCIA PATRIMONIAL', 'Compreende as participações permanentes da unidade em outras entidades em forma de ações ou cotas, avaliadas pelo método de equivalência patrimonial.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1704, 2, '1.2.2.1.3.02.00.00.00.00', 'PARTICIPAÇÕES AVALIADAS PELO MÉTODO DE CUSTO', 'Compreende as participações permanentes da unidade em outras sociedades em forma de ações ou cotas, avaliadas pelo método de custo.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1731, 2, '1.2.3.2.0.00.00.00.00.00', 'BENS IMÓVEIS', 'Compreende o valor dos bens imóveis, os quais são bens vinculados ao solo e que não podem ser retirados sem destruição ou dano, destinados ao uso e que a entidade não esteja explorando comercialmente.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1705, 2, '1.2.2.1.4.00.00.00.00.00', 'PARTICIPAÇÕES PERMANENTES - INTER OFSS - ESTADO', 'Compreende as participações permanentes da entidade em outras sociedades em forma de ações ou cotas. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1706, 2, '1.2.2.1.4.01.00.00.00.00', 'PARTICIPAÇÕES AVALIADAS PELO MÉTODO DE EQUIVALÊNCIA PATRIMONIAL', 'Compreende as participações permanentes da unidade em outras entidades em forma de ações ou cotas, avaliadas pelo método de equivalência patrimonial.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1707, 2, '1.2.2.1.4.02.00.00.00.00', 'PARTICIPAÇÕES AVALIADAS PELO MÉTODO DE CUSTO', 'Compreende as participações permanentes da unidade em outras sociedades em forma de ações ou cotas, avaliadas pelo método de custo.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1708, 2, '1.2.2.1.5.00.00.00.00.00', 'PARTICIPAÇÕES PERMANENTES - INTER OFSS - MUNICÍPIO', 'Compreende as participações permanentes da entidade em outras sociedades em forma de ações ou cotas. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1709, 2, '1.2.2.1.5.01.00.00.00.00', 'PARTICIPAÇÕES AVALIADAS PELO MÉTODO DE EQUIVALÊNCIA PATRIMONIAL', 'Compreende as participações permanentes da unidade em outras entidades em forma de ações ou cotas, avaliadas pelo método de equivalência patrimonial.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1710, 2, '1.2.2.2.0.00.00.00.00.00', 'PROPRIEDADES PARA INVESTIMENTO', 'Compreende a propriedade (terreno ou edifício - ou parte de edifício - ou ambos) mantida (pelo proprietário ou pelo arrendatário em arrendamento financeiro) para auferir aluguel ou para valorização do capital ou para ambas, e não para: uso na produção ou fornecimento de bens ou serviços ou para finalidades administrativas; ou venda no curso ordinário do negócio.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1711, 2, '1.2.2.2.1.00.00.00.00.00', 'PROPRIEDADES PARA INVESTIMENTO - CONSOLIDAÇÃO', 'Compreende a propriedade (terreno ou edifício - ou parte de edifício - ou ambos) mantida (pelo proprietário ou pelo arrendatário em arrendamento financeiro) para auferir aluguel ou para valorização do capital ou para ambas, e não para: uso na produção ou fornecimento de bens ou serviços ou para finalidades administrativas; ou venda no curso ordinário do negócio. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1712, 2, '1.2.2.2.1.01.00.00.00.00', 'BENS IMÓVEIS PARA FUTURA UTILIZAÇÃO', 'Compreende os valores de imóveis da unidade mantidos para futura utilização.', 1, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (1713, 2, '1.2.2.2.1.02.00.00.00.00', 'BENS IMÓVEIS NÃO DESTINADOS A USO', 'Compreende os valores de imóveis da unidade mantidos para geração de renda.', 1, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (1714, 2, '1.2.2.3.0.00.00.00.00.00', 'INVESTIMENTOS DO RPPS DE LONGO PRAZO', 'Compreende os investimentos realizados pelo Regime Próprio da Previdência Social, em conformidade com a legislação que trata das aplicações e investimentos dos RPPS.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1715, 2, '1.2.2.3.1.00.00.00.00.00', 'INVESTIMENTOS DO RPPS DE LONGO PRAZO - CONSOLIDAÇÃO', 'Compreende os investimentos realizados pelo Regime Próprio da Previdência Social, em conformidade com a legislação que trata das aplicações e investimentos dos RPPS. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1716, 2, '1.2.2.3.1.01.00.00.00.00', 'TÍTULOS E VALORES MOBILIÁRIOS - RPPS', 'Compreende os investimentos realizados pelo Regime Próprio da Previdência Social em títulos e valores mobiliários .', 1, false, 0, ' ');
insert into contabilidade.planocontadetalhe values (1717, 2, '1.2.2.3.1.02.00.00.00.00', 'APLICAÇÕES EM SEGMENTO DE IMÓVEIS - RPPS', 'Compreende os investimentos realizados pelo Regime Próprio da Previdência Social em aplicações em segmentos de imóveis.', 1, false, 0, ' ');
insert into contabilidade.planocontadetalhe values (1718, 2, '1.2.2.7.0.00.00.00.00.00', 'DEMAIS INVESTIMENTOS PERMANENTES', 'Compreende os demais direitos de qualquer natureza não classificáveis no ativo circulante nem no ativo realizável a longo prazo e que não se destinem a manutenção das atividades da entidade.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1719, 2, '1.2.2.7.1.00.00.00.00.00', 'DEMAIS INVESTIMENTOS PERMANENTES - CONSOLIDAÇÃO', 'Compreende os demais direitos de qualquer natureza não classificáveis no ativo circulante nem no ativo realizável a longo prazo e que não se destinem a manutenção das atividades da entidade. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1720, 2, '1.2.3.0.0.00.00.00.00.00', 'IMOBILIZADO', 'Compreende os direitos que tenham por objeto bens corpóreos destinados a manutenção das atividades da entidade ou exercidos com essa finalidade, inclusive os decorrentes de operações que transfiram a ela os benefícios, os riscos e o controle desses bens.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1721, 2, '1.2.3.1.0.00.00.00.00.00', 'BENS MÓVEIS', 'Compreende o valor da aquisição ou incorporação de bens corpóreos, que tem existência material e que podem ser transportados por movimento próprio ou removidos por forca alheia sem alteração da substancia ou da destinação economico-social, que constituam meio para a produção de outros bens ou serviços.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1722, 2, '1.2.3.1.1.00.00.00.00.00', 'BENS MÓVEIS- CONSOLIDAÇÃO', 'Compreende o valor da aquisição ou incorporação de bens corpóreos, que tem existência material e que podem ser transportados por movimento próprio ou removidos por forca alheia sem alteração da substancia ou da destinação economico-social, que constituam meio para a produção de outros bens ou serviços. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1723, 2, '1.2.3.1.1.01.00.00.00.00', 'MÁQUINAS, APARELHOS, EQUIPAMENTOS E FERRAMENTAS', 'Compreende o valor da aquisição ou incorporação de máquinas, ferramentas, aparelhos, equipamentos, acessórios etc.', 1, false, 0, ' ');
insert into contabilidade.planocontadetalhe values (1724, 2, '1.2.3.1.1.02.00.00.00.00', 'BENS DE INFORMÁTICA', 'Compreende o valor da aquisição ou incorporação de equipamentos de processamento de dados e sistemas aplicativos, entre outros.', 1, false, 0, ' ');
insert into contabilidade.planocontadetalhe values (1725, 2, '1.2.3.1.1.03.00.00.00.00', 'MÓVEIS E UTENSÍLIOS', 'Compreende o valor da aquisição ou incorporação de mobiliário em geral e utensílios, entre outros.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1726, 2, '1.2.3.1.1.04.00.00.00.00', 'MATERIAIS CULTURAIS, EDUCACIONAIS E DE COMUNICAÇÃO', 'Compreende o valor da aquisição ou incorporação de materiais bibliográficos, discotecas, filmotecas, de comunicação, entre outros.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1727, 2, '1.2.3.1.1.05.00.00.00.00', 'VEÍCULOS', 'Compreende o valor da aquisição ou incorporação de meios de transportes aéreos, aquáticos e terrestres, entre outros.', 1, false, 0, ' ');
insert into contabilidade.planocontadetalhe values (1728, 2, '1.2.3.1.1.07.00.00.00.00', 'BENS MÓVEIS EM ANDAMENTO', 'Compreende os valores de bens móveis em andamento.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1732, 2, '1.2.3.2.1.00.00.00.00.00', 'BENS IMÓVEIS- CONSOLIDAÇÃO', 'Compreende o valor dos bens imóveis, os quais são bens vinculados ao solo e que não podem ser retirados sem destruição ou dano, destinados ao uso e que a entidade não esteja explorando comercialmente. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1733, 2, '1.2.3.2.1.01.00.00.00.00', 'BENS DE USO ESPECIAL', 'Compreende os bens, tais como edifícios ou terrenos destinados a serviço ou estabelecimento da administração estadual ou municipal, inclusive os de suas autarquias e fundações públicas.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1734, 2, '1.2.3.2.1.04.00.00.00.00', 'BENS DOMINICAIS', 'Compreende os bens que constituem o patrimônio das pessoas jurídicas de direito público, como objeto de direito pessoal, ou real, de cada uma dessas entidades. Compreende ainda, não dispondo a lei em contrário, os bens pertencentes as pessoas jurídicas de direito público a que se tenha dado estrutura de direito privado.', 1, false, 0, ' ');
insert into contabilidade.planocontadetalhe values (1735, 2, '1.2.3.2.1.05.00.00.00.00', 'BENS DE USO COMUM DO POVO', 'Compreende os bens de uso comum do povo construídos ou adquiridos por pessoas jurídicas de direito público.', 1, false, 0, ' ');
insert into contabilidade.planocontadetalhe values (1736, 2, '1.2.4.1.0.00.00.00.00.00', 'SOFTWARES', 'Compreende os valores dos softwares pertencentes à entidade e não integrantes a um hardware, englobando os valores referentes à sua construção, implementação e instalação.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1737, 2, '1.2.4.1.1.00.00.00.00.00', 'SOFTWARES - CONSOLIDAÇÃO', 'Compreende os valores dos softwares pertencentes à entidade e não integrantes a um hardware, englobando os valores referentes à sua construção, implementação e instalação. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1738, 2, '1.2.4.2.0.00.00.00.00.00', 'MARCAS, DIREITOS E PATENTES INDUSTRIAIS', 'Compreende os valores pertinentes a bens intangíveis, englobando os gastos com registro de marca, nome, invenções próprias, direitos de uso de comunicação e direitos autorais, alem de desembolsos a terceiros por contratos de uso de marcas, patentes ou processos de fabricação (tecnologia).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1739, 2, '1.2.4.2.1.00.00.00.00.00', 'MARCAS, DIREITOS E PATENTES INDUSTRIAIS - CONSOLIDAÇÃO', 'Compreende os valores pertinentes a bens intangíveis, englobando os gastos com registro de marca, nome, invenções próprias, direitos de uso de comunicação, direitos autorais e direitos sobre recursos naturais, alem de desembolsos a terceiros por contratos de uso de marcas, patentes ou processos de fabricação (tecnologia). Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1740, 2, '1.2.4.3.0.00.00.00.00.00', 'DIREITO DE USO DE IMÓVEIS', 'Compreende os valores pertinentes a bens intangíveis representados pela aquisição do direito de uso de imóveis.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1741, 2, '1.2.4.3.1.00.00.00.00.00', 'DIREITO DE USO DE IMÓVEIS- CONSOLIDAÇÃO', 'Compreende os valores pertinentes a bens intangíveis representados pela aquisição de direito de uso de imóveis. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (1742, 2, '1.2.5.0.0.00.00.00.00.00', 'DIFERIDO', 'Compreende as despesas pré-operacionais e os gastos de reestruturação que contribuirão, efetivamente, para o aumento do resultado de mais de um exercício social e que não configurem tão somente uma redução de custos ou acréscimo na eficiência operacional. Compreende os saldos compreendidos até 2008 e que deverão ser integralmente amortizados até 2017.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1743, 2, '1.2.5.1.0.00.00.00.00.00', 'GASTOS DE IMPLANTAÇÃO E PRÉ-OPERACIONAIS', 'Compreende os gastos com novos empreendimentos, incorridos antes do início de suas operações. Compreende os saldos compreendidos até 2008 e que deverão ser integralmente amortizados até 2017.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1744, 2, '1.2.5.1.1.00.00.00.00.00', 'GASTOS DE IMPLANTAÇÃO E PRÉ-OPERACIONAIS - CONSOLIDAÇÃO', 'Compreende os gastos com novos empreendimentos, incorridos antes do início de suas operações. Compreende os saldos registrados até 2008 e que deverão ser integralmente amortizados até 2017. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (1745, 2, '1.2.5.2.0.00.00.00.00.00', 'GASTOS DE REORGANIZAÇÃO', 'Compreende os gastos com a reorganização, que contribuirão, efetivamente, para o aumento do resultado de mais de um exercício social, registrados até 2008 e que deverão ser integralmente amortizados até 2017.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1746, 2, '1.2.5.2.1.00.00.00.00.00', 'GASTOS DE REORGANIZAÇÃO - CONSOLIDAÇÃO', 'Compreende os gastos com a reorganização, que contribuirão, efetivamente, para o aumento do resultado de mais de um exercício social, registrados até 2008 e que deverão ser integralmente amortizados até 2017. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (1747, 2, '4.2.1.1.3.97.00.00.00.00', '(-) DEDUÇÕES', 'Compreendem as deduções das variações patrimoniais umentativas.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1748, 2, '2.1.2.8.0.00.00.00.00.00', '(-) ENCARGOS FINANCEIROS A APROPRIAR - INTERNO', 'Compreende os encargos financeiros estabelecidos em valores prefixados, inclusos como contrapartida nas contas de empréstimo e de financiamento a curto prazo - interno, mas que ainda não transcorreram por não ter ocorrido ainda o fato gerador.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1749, 2, '2.1.2.8.1.00.00.00.00.00', '(-) ENCARGOS FINANCEIROS A APROPRIAR - INTERNO - CONSOLIDAÇÃO', 'Compreende os encargos financeiros estabelecidos em valores prefixados, inclusos como contrapartida nas contas de empréstimo e de financiamento a curto prazo - interno, mas que ainda não transcorreram por não ter ocorrido ainda o fato gerador. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1750, 2, '2.1.2.8.3.00.00.00.00.00', '(-) ENCARGOS FINANCEIROS A APROPRIAR - INTERNO - INTER OFSS - UNIÃO', 'Compreende os encargos financeiros estabelecidos em valores prefixados, inclusos como contrapartida nas contas de empréstimo e de financiamento a curto prazo - interno, mas que ainda não transcorreram por não ter ocorrido ainda o fato gerador. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1751, 2, '2.1.2.8.4.00.00.00.00.00', '(-) ENCARGOS FINANCEIROS A APROPRIAR - INTERNO - INTER OFSS - ESTADO', 'Compreende os encargos financeiros estabelecidos em valores prefixados, inclusos como contrapartida nas contas de empréstimo e de financiamento a curto prazo - interno, mas que ainda não transcorreram por não ter ocorrido ainda o fato gerador. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1752, 2, '2.1.2.8.5.00.00.00.00.00', '(-) ENCARGOS FINANCEIROS A APROPRIAR - INTERNO - INTER OFSS - MUNICÍPIO', 'Compreende os encargos financeiros estabelecidos em valores prefixados, inclusos como contrapartida nas contas de empréstimo e de financiamento a curto prazo - interno, mas que ainda não transcorreram por não ter ocorrido ainda o fato gerador. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 1, false, 0, 'P');
