insert into contabilidade.planocontadetalhe values (1782, 2, '3.0.0.0.0.00.00.00.00.00', 'VARIAÇÃO PATRIMONIAL DIMINUTIVA', 'Compreende o decréscimo no beneficio econômico durante o período contábil sob a forma de saída de recurso ou redução de ativo ou incremento em passivo, que resulte em decréscimo do patrimônio liquido e que não seja proveniente de distribuição aos proprietários da entidade.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1783, 2, '3.1.0.0.0.00.00.00.00.00', 'PESSOAL E ENCARGOS', 'Compreende a remuneração do pessoal ativo civil ou militar, correspondente ao somatório das variações patrimoniais diminutivas com subsídios, vencimentos, soldos e vantagens pecuniárias fixas ou variáveis estabelecidas em lei decorrentes do pagamento pelo efetivo exercício do cargo, emprego ou função de confiança no setor público. Compreende ainda, obrigações trabalhistas de responsabilidade do empregador, incidentes sobre a folha de pagamento dos órgãos e demais entidades do setor público, contribuições a entidades fechadas de previdência e benefícios eventuais a pessoal civil e militar, destacados os custos de pessoal e encargos inerentes as mercadorias e produtos vendidos e serviços prestados.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1784, 2, '3.1.1.0.0.00.00.00.00.00', 'REMUNERAÇÃO A PESSOAL', 'Compreende a remuneração do pessoal ativo civil ou militar, correspondente ao somatório das variações patrimoniais diminutivas com subsídios, vencimentos, soldos e vantagens pecuniárias fixas e variáveis estabelecidas em lei decorrentes do pagamento pelo efetivo exercício do cargo, emprego ou função de confiança no setor público, bem como as com contratos de terceirização de mão de obra que se refiram à substituição de servidores e empregados públicos.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1785, 2, '3.1.1.1.0.00.00.00.00.00', 'REMUNERAÇÃO A PESSOAL ATIVO CIVIL - ABRANGIDOS PELO RPPS', 'Compreende a remuneração do pessoal ativo civil abrangidos pelo RPPS, correspondente ao somatório das variações patrimoniais diminutivas com subsídios, vencimentos e vantagens pecuniárias fixas e variáveis estabelecidas em lei decorrentes do pagamento pelo efetivo exercício do cargo ou função de confiança no setor público.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1786, 2, '3.1.1.1.1.00.00.00.00.00', 'REMUNERAÇÃO A PESSOAL ATIVO CIVIL - ABRANGIDOS PELO RPPS - CONSOLIDAÇÃO', 'Compreende a remuneração do pessoal ativo civil abrangidos pelo RPPS, correspondente ao somatório das variações patrimoniais diminutivas com subsídios, vencimentos e vantagens pecuniárias fixas e variáveis estabelecidas em lei decorrentes do pagamento pelo efetivo exercício do cargo ou função de confiança no setor público. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1787, 2, '3.1.1.1.1.01.00.00.00.00', 'VENCIMENTOS E VANTAGENS FIXAS - PESSOAL CIVIL - RPPS', 'Compreende o somatório dos valores com vencimentos e vantagens fixas do pessoal civil do tipo: gratificação, representação, adicional insalubridade, férias, 13 salário, licença-prêmio, abono pecuniário, adicional noturno, etc.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1788, 2, '3.1.1.1.1.02.00.00.00.00', 'OUTRAS DESPESAS VARIÁVEIS - PESSOAL CIVIL - RPPS', 'Compreende o valor de outras despesas variáveis - Pessoal Civil - RPPS.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1789, 2, '3.1.1.2.0.00.00.00.00.00', 'REMUNERAÇÃO A PESSOAL ATIVO CIVIL - ABRANGIDOS PELO RGPS', 'Compreende a remuneração do pessoal ativo civil abrangidos pelo RGPS, correspondente ao somatório das variações patrimoniais diminutivas com vencimentos e vantagens pecuniárias fixas e variáveis estabelecidas em lei decorrentes do pagamento pelo efetivo exercício do emprego, inclusive os ocupantes de cargos em comissão não investidos em cargo efetivo, no setor público.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1790, 2, '3.1.1.2.1.00.00.00.00.00', 'REMUNERAÇÃO A PESSOAL ATIVO CIVIL - ABRANGIDOS PELO RGPS - CONSOLIDAÇÃO', 'Compreende a remuneração do pessoal ativo civil abrangidos pelo RGPS, correspondente ao somatório das variações patrimoniais diminutivas com vencimentos e vantagens pecuniárias fixas e variáveis estabelecidas em lei decorrentes do pagamento pelo efetivo exercício do emprego, inclusive os ocupantes de cargos em comissão não investidos em cargo efetivo, no setor público. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1791, 2, '3.1.1.2.1.01.00.00.00.00', 'VENCIMENTOS E VANTAGENS FIXAS - PESSOAL CIVIL - RGPS', 'Compreende o somatório dos valores com vencimentos e vantagens fixas do pessoal civil do tipo: gratificação, representação, adicional insalubridade, férias, 13º salário, licença-prêmio, abono pecuniário, adicional noturno, etc.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1793, 2, '3.1.1.2.1.04.00.00.00.00', 'CONTRATAÇÃO POR TEMPO DETERMINADO     ', 'Compreende as variações patrimoniais diminutivas com contratação por tempo determinado.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1794, 2, '3.1.1.3.0.00.00.00.00.00', 'REMUNERAÇÃO A PESSOAL ATIVO MILITAR - ABRANGIDOS PELO RPPS', 'Compreende a remuneração do pessoal ativo militar, abrangidos por regime próprio dos militares ou não, correspondente ao somatório das variações patrimoniais diminutivas com soldos e vantagens pecuniárias fixas e variáveis estabelecidas em lei decorrentes do pagamento pelo efetivo exercício do cargo ou função de confiança no setor público.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1795, 2, '3.1.9.0.0.00.00.00.00.00', 'OUTRAS VARIAÇÕES PATRIMONIAIS DIMINUTIVAS - PESSOAL E ENCARGOS', 'Compreende outras variações patrimoniais diminutivas, relacionadas com pessoal e encargos, não abrangidas nos grupos anteriores, tais como as indenizações e restituições trabalhistas.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1796, 2, '3.1.1.3.1.00.00.00.00.00', 'REMUNERAÇÃO A PESSOAL ATIVO MILITAR - ABRANGIDOS PELO RPPS - CONSOLIDAÇÃO', 'Compreende a remuneração do pessoal ativo militar, abrangidos por regime próprio dos militares ou não, correspondente ao somatório das variações patrimoniais diminutivas com soldos e vantagens pecuniárias fixas e variáveis estabelecidas em lei decorrentes do pagamento pelo efetivo exercício do cargo ou função de confiança no setor público. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
