insert into contabilidade.planocontadetalhe values (1800, 2, '3.1.2.1.2.00.00.00.00.00', 'ENCARGOS PATRONAIS - RPPS - INTRA OFSS', 'Compreende os encargos trabalhistas de responsabilidade do empregador, incidentes sobre a folha de pagamento dos servidores públicos ativos, pertencentes aos órgãos e demais entidades do setor público. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do ente.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1801, 2, '3.1.2.1.3.00.00.00.00.00', 'ENCARGOS PATRONAIS - RPPS - INTER OFSS - UNIÃO', 'Compreende os encargos trabalhistas de responsabilidade do empregador, incidentes sobre a folha de pagamento dos servidores públicos ativos, pertencentes aos órgãos e demais entidades do setor público.  Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1802, 2, '3.1.2.1.4.00.00.00.00.00', 'ENCARGOS PATRONAIS - RPPS - INTER OFSS - ESTADO', 'Compreende os encargos trabalhistas de responsabilidade do empregador, incidentes sobre a folha de pagamento dos servidores públicos ativos, pertencentes aos órgãos e demais entidades do setor público.  Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1803, 2, '3.1.2.1.5.00.00.00.00.00', 'ENCARGOS PATRONAIS - RPPS - INTER OFSS - MUNICÍPIO', 'Compreende os encargos trabalhistas de responsabilidade do empregador, incidentes sobre a folha de pagamento dos servidores públicos ativos, pertencentes aos órgãos e demais entidades do setor público.  Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1804, 2, '3.1.2.2.0.00.00.00.00.00', 'ENCARGOS PATRONAIS - RGPS', 'Compreende os encargos trabalhistas de responsabilidade do empregador, incidentes sobre a folha de pagamento dos empregados ativos, pertencentes aos órgãos e demais entidades do setor público, bem como ocupantes de cargo em comissão não investidos, em cargo efetivo.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1805, 2, '3.1.2.2.1.00.00.00.00.00', 'ENCARGOS PATRONAIS - RGPS - CONSOLIDAÇÃO', 'Compreende os encargos trabalhistas de responsabilidade do empregador, incidentes sobre a folha de pagamento dos empregados ativos, pertencentes aos órgãos e demais entidades do setor público, bem como ocupantes de cargo em comissão não investido em cargo efetivo. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1806, 2, '3.1.2.2.2.00.00.00.00.00', 'ENCARGOS PATRONAIS - RGPS - INTRA OFSS', 'Compreende os encargos trabalhistas de responsabilidade do empregador, incidentes sobre a folha de pagamento dos empregados ativos, pertencentes aos órgãos e demais entidades do setor público, bem como ocupantes de cargo em comissão não investido em cargo efetivo. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do ente.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1818, 2, '3.1.2.9.2.00.00.00.00.00', 'OUTROS ENCARGOS PATRONAIS - INTRA OFSS', 'Compreende outras variações patrimoniais diminutivas, relacionadas aos encargos patronais, não abrangidas nos grupos anteriores. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do ente.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1807, 2, '3.1.2.2.3.00.00.00.00.00', 'ENCARGOS PATRONAIS - RGPS - INTER OFSS - UNIÃO', 'Compreende os encargos trabalhistas de responsabilidade do empregador, incidentes sobre a folha de pagamento dos empregados ativos, pertencentes aos órgãos e demais entidades do setor público, bem como ocupantes de cargo em comissão não investido em cargo efetivo. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1819, 2, '3.1.2.9.3.00.00.00.00.00', 'OUTROS ENCARGOS PATRONAIS - INTER OFSS - UNIÃO', 'Compreende outras variações patrimoniais diminutivas, relacionadas aos encargos patronais, não abrangidas nos grupos anteriores. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1808, 2, '3.1.2.3.0.00.00.00.00.00', 'ENCARGOS PATRONAIS - FGTS', 'Compreende os valores recolhidos mensalmente pelos empregadores, em conta bancária vinculada do trabalhador no FGTS, correspondente a percentual definido em lei sobre a remuneração paga ou devida, no mês anterior, a cada trabalhador, incluídas na remuneração as parcelas de que tratam os artigos. 457 e 458 da CLT e a gratificação de natal a que se refere à Lei nº 4.090, de 13 de julho de 1962, com as modificações da Lei nº 4.749, de 12 de agosto de 1965. Entende-se por empregador a pessoa física ou a pessoa jurídica de direito privado ou de direito público, da administração pública direta, indireta ou fundacional de qualquer dos poderes, da União, dos Estados, do Distrito Federal e dos Municípios, que admitir trabalhadores a seu serviço, bem assim aquele que, regido por legislação especial, encontrar-se nessa condição ou figurar como fornecedor ou tomador de mão de obra, independente da responsabilidade solidária e/ou subsidiária a que eventualmente venha obrigar-se. Considera-se trabalhador toda pessoa física que prestar serviços a empregador, a locador ou tomador de mão de obra, excluídos os eventuais, os autônomos e os servidores públicos civis e militares sujeitos a regime jurídico próprio. O recolhimento do FGTS é obrigatório também nos casos de afastamento para prestação do serviço militar obrigatório e licença por acidente do trabalho. Não se incluem na remuneração, para os fins desta lei, as parcelas elencadas no § 9º do art. 28 da Lei nº 8.212, de 24 de julho de 1991. ', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1809, 2, '3.1.9.1.0.00.00.00.00.00', 'INDENIZAÇÕES E RESTITUIÇÕES TRABALHISTAS', 'Compreende o valor total com variações patrimoniais diminutivas resultante do pagamento efetuado a servidores públicos civis e empregados de entidades integrantes da administração pública, inclusive férias e aviso prévio indenizados, multas e contribuições incidentes sobre os depósitos do fundo de garantia por tempo de serviço, etc., em função da perda da condição de servidor ou empregado, podendo ser em decorrência da participação em programa de desligamento voluntário.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1810, 2, '3.1.2.3.1.00.00.00.00.00', 'ENCARGOS PATRONAIS - FGTS - CONSOLIDAÇÃO', 'Compreende os valores recolhidos mensalmente pelos empregadores, em conta bancaria vinculada do trabalhador no FGTS, correspondente a percentual definido em lei sobre a remuneração paga ou devida, no mês anterior, a cada trabalhador, incluídas na remuneração as parcelas de que tratam os artigos. 457 e 458 da CLT e a gratificação de natal a que se refere à lei nº 4.090, de 13 de julho de 1962, com as modificações da lei nº 4.749, de 12 de agosto de 1965. Entende-se por empregador a pessoa física ou a pessoa jurídica de direito privado ou de direito público, da administração pública direta, indireta ou fundacional de qualquer dos poderes, da União, dos estados, do distrito federal e dos municípios, que admitir trabalhadores a seu serviço, bem assim aquele que, regido por legislação especial, encontrar-se nessa condição ou figurar como fornecedor ou tomador de mão de obra, independente da responsabilidade solidaria e/ou subsidiaria a que eventualmente venha obrigar-se. Considera-se trabalhador toda pessoa física que prestar serviços a empregador, a locador ou tomador de mão de obra, excluídos os eventuais, os autônomos e os servidores públicos civis e militares sujeitos a regime jurídico próprio. O recolhimento do FGTS e obrigatório também nos casos de afastamento para prestação do serviço militar obrigatório e licença por acidente do trabalho. Não se incluem na remuneração, para os fins desta lei, as parcelas elencadas no § 9º do art. 28 da lei nº 8.212, de 24 de julho de 1991. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1811, 2, '3.1.2.4.0.00.00.00.00.00', 'CONTRIBUIÇÕES SOCIAIS GERAIS', 'Compreende os encargos patronais relativos ao salário educação e as contribuições compulsórias dos empregadores sobre a folha de salários, destinados as entidades privadas de serviço social e de formação profissional, vinculadas ao sistema sindical, tais como SESI, SENAI, SESC e SENAC.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1812, 2, '3.1.2.4.1.00.00.00.00.00', 'CONTRIBUIÇÕES SOCIAIS GERAIS - CONSOLIDAÇÃO', 'Compreende os encargos patronais relativos ao salário educação e as contribuições compulsórias dos empregadores sobre a folha de salários, destinados as entidades privadas de serviço social e de formação profissional, vinculadas ao sistema sindical, tais como SESI, SENAI, SESC e SENAC. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1813, 2, '3.1.2.5.0.00.00.00.00.00', 'CONTRIBUIÇÕES A ENTIDADES FECHADAS DE PREVIDÊNCIA', 'Compreende o valor total das variações patrimoniais diminutivas relacionadas ao regime de previdência privada, de caráter complementar, organizado de forma autônoma em relação ao regime geral de previdência social, de caráter facultativo, baseado na constituição de reservas que garantam o benefício, nos termos do caput do art. 202 da constituição federal. Entende-se por entidades fechadas aquelas acessíveis, na forma regulamentada pelo órgão regulador e fiscalizador, exclusivamente aos empregados de uma empresa ou grupo de empresas e aos servidores da União, dos estados, do distrito federal e dos municípios, entes denominados patrocinadores.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1814, 2, '3.1.2.5.1.00.00.00.00.00', 'CONTRIBUIÇÕES A ENTIDADES FECHADAS DE PREVIDÊNCIA - CONSOLIDAÇÃO', 'Compreende o valor total das variações patrimoniais diminutivas relacionadas ao regime de previdência privada, de caráter complementar, organizado de forma autônoma em relação ao regime geral de previdência social, de caráter facultativo, baseado na constituição de reservas que garantam o benefício, nos termos do caput do art. 202 da constituição federal. Entende-se por entidades fechadas aquelas acessíveis, na forma regulamentada pelo órgão regulador e fiscalizador, exclusivamente aos empregados de uma empresa ou grupo de empresas e aos servidores da União, dos estados, do distrito federal e dos municípios, entes denominados patrocinadores. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1815, 2, '3.1.2.9.0.00.00.00.00.00', 'OUTROS ENCARGOS PATRONAIS', 'Compreende outras variações patrimoniais diminutivas, relacionadas aos encargos patronais, não abrangidas nos grupos anteriores.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1816, 2, '3.1.2.9.1.00.00.00.00.00', 'OUTROS ENCARGOS PATRONAIS - CONSOLIDAÇÃO', 'Compreende outras variações patrimoniais diminutivas, relacionadas aos encargos patronais, não abrangidas nos grupos anteriores. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1817, 2, '3.2.1.1.1.01.00.00.00.00', 'PROVENTOS - PESSOAL CIVIL', 'Compreende as Variações Patrimoniais Diminutivas com a concessão de aposentadoria a Pessoal Civil.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1887, 2, '3.3.2.0.0.00.00.00.00.00', 'SERVIÇOS', 'Compreende as variações patrimoniais diminutivas provenientes da prestação de serviços fornecidas à entidade governamental.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1820, 2, '3.1.2.9.4.00.00.00.00.00', 'OUTROS ENCARGOS PATRONAIS - INTER OFSS - ESTADO', 'Compreende outras variações patrimoniais diminutivas, relacionadas aos encargos patronais, não abrangidas nos grupos anteriores. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1821, 2, '3.1.2.9.5.00.00.00.00.00', 'OUTROS ENCARGOS PATRONAIS - INTER OFSS - MUNICÍPIO', 'Compreende outras variações patrimoniais diminutivas, relacionadas aos encargos patronais, não abrangidas nos grupos anteriores. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1822, 2, '3.1.9.1.1.00.00.00.00.00', 'INDENIZAÇÕES E RESTITUIÇÕES TRABALHISTAS - CONSOLIDAÇÃO', 'Compreende o valor total com variações patrimoniais diminutivas resultante do pagamento efetuado a servidores públicos civis e empregados de entidades integrantes da administração pública, inclusive ferias e aviso prévio indenizados, multas e contribuições incidentes sobre os depósitos do fundo de garantia por tempo de serviço, etc., em função da perda da condição de servidor ou empregado, podendo ser em decorrência da participação em programa de desligamento voluntario. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1823, 2, '3.1.9.2.0.00.00.00.00.00', 'PESSOAL REQUISITADO DE OUTROS ÓRGÃOS E ENTES', 'Compreende as variações patrimoniais diminutivas  com pessoal requisitado de outros órgãos e entes.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1824, 2, '1.1.2.9.1.01.01.06.00.00', '(-) PERDAS ESTIMADAS NO ITBI', 'Registra o ajuste para perdas estimadas com o não recebimento do ITBI', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (1825, 2, '3.1.3.0.0.00.00.00.00.00', 'BENEFÍCIOS A PESSOAL', 'Compreende o valor total das variações patrimoniais diminutivas com benefícios devidos a pessoal civil e militar , tais como para o pessoal civil: ajuda-de-custo, indenização de transporte, auxílio-moradia, auxilia-alimentação, auxilia-transporte bem como outros decorrentes de acordo ou convenção coletiva no que se refere aos empregados públicos. Para os militares: adicional de compensação orgânica não incorporada, gratificação de localidade especial, gratificação de representação, transporte, ajuda-de-custo, auxílio-fardamento, auxílio-alimentação e outros benefícios eventuais relativos ao local ou a natureza do trabalho. Estão excluídas deste grupo as despesas com vencimentos, soldos e quaisquer outras vantagens pecuniárias, bem como as despesas relacionadas aos benefícios previdenciários ou assistenciais, tais como: aposentadoria, auxílio-natalidade, salário-família, licença para tratamento de saúde, licença a gestante, a adotante e licença-maternidade, licença por acidente em serviço, assistência a saúde, garantia de condições individuais e ambientais de trabalho satisfatórias, pensão vitalícia e temporária, auxílio-funeral, auxílio-reclusão, auxílio-invalidez, assistência a saúde. Estão excluídas ainda as indenizações e restituições trabalhistas decorrentes da perda da condição de servidor ou empregado, tais como ferias, aviso prévio indenizado e outras.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1826, 2, '3.1.3.1.0.00.00.00.00.00', 'BENEFÍCIOS A PESSOAL - RPPS', 'Compreende o valor total das variações patrimoniais diminutivas com benefícios a servidor público, tais como: ajuda-de-custo, indenização de transporte, auxílio-moradia, auxílio-transporte,auxílio-alimentação e outros benefícios relativos ao local ou a natureza do trabalho. Estão excluídas deste grupo os vencimentos e quaisquer outras vantagens pecuniárias permanentes, bem como os benefícios previdenciários ou assistenciais, tais como: aposentadoria, auxílio-natalidade, salário-família, licença para tratamento de saúde, licença a gestante, a adotante e licença-maternidade, licença por acidente em serviço, assistência a saúde, pensão vitalícia e temporária, auxílio-funeral, auxílio-reclusão, auxílio-invalidez, assistência a saúde. Estão excluídas ainda as indenizações e restituições trabalhistas decorrentes da perda da condição de servidor ou empregado, tais como ferias, aviso prévio indenizados e outras.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1827, 2, '3.1.3.1.1.00.00.00.00.00', 'BENEFÍCIOS A PESSOAL - RPPS - CONSOLIDAÇÃO', 'Compreende o valor total das variações patrimoniais diminutivas com benefícios a servidor público, tais como: ajuda-de-custo, indenização de transporte, auxílio-moradia, auxílio-transporte,auxílio-alimentação e outros benefícios relativos ao local ou a natureza do trabalho. Estão excluídas deste grupo os vencimentos e quaisquer outras vantagens pecuniárias permanentes, bem como os benefícios previdenciários ou assistenciais, tais como: aposentadoria, auxílio-natalidade, salário-família, licença para tratamento de saúde, licença a gestante, a adotante e licença-maternidade, licença por acidente em serviço, assistência a saúde, pensão vitalícia e temporária, auxílio-funeral, auxílio-reclusão, auxílio-invalidez, assistência a saúde. Estão excluídas ainda as indenizações e restituições trabalhistas decorrentes da perda da condição de servidor ou empregado, tais como ferias, aviso prévio indenizado e outras. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1828, 2, '3.1.3.2.0.00.00.00.00.00', 'BENEFÍCIOS A PESSOAL - RGPS', 'Compreende o valor total das variações patrimoniais diminutivas com benefícios devidos aos empregados públicos, e ainda outros relativos a acordo ou convenção coletiva. Estão excluídos deste grupo os vencimentos e quaisquer outras vantagens pecuniárias, bem como os benefícios previdenciários ou assistenciais, tais como: aposentadoria, auxílio-natalidade, salário-família, licença para tratamento de saúde, licença a gestante, a adotante e licença-maternidade, licença por acidente em serviço, assistência a saúde, garantia de condições individuais e ambientais de trabalho satisfatórias, pensão vitalícia e temporária, auxílio-funeral, auxílio-reclusão, auxílio-invalidez, assistência a saúde. Estão excluídas ainda as indenizações e restituições trabalhistas decorrentes da perda da condição de servidor ou empregado, tais como ferias, aviso prévio indenizado e outras.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1845, 2, '3.2.2.1.1.00.00.00.00.00', 'PENSÕES - RPPS - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais diminutivas com pagamento de pensões aos dependentes dos segurados, após seu óbito, pelo regime próprio da previdência social - RPPS. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1846, 2, '3.2.2.2.0.00.00.00.00.00', 'PENSÕES - RGPS', 'Compreende as variações patrimoniais diminutivas com pagamento de pensões aos dependentes dos segurados, após seu óbito, regidos pelo regime geral da previdência social -RGPS.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1955, 2, '3.9.1.1.0.00.00.00.00.00', 'PREMIAÇÕES CULTURAIS', 'Compreende o valor gasto com prêmios, condecorações, medalhas, troféus, etc., de caráter cultural.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1829, 2, '3.1.3.2.1.00.00.00.00.00', 'BENEFÍCIOS A PESSOAL - RGPS - CONSOLIDAÇÃO', 'Compreende o valor total das variações patrimoniais diminutivas com benefícios devidos aos empregados públicos, e ainda outros relativos a acordo ou convenção coletiva. Estão excluídas deste grupo os vencimentos e quaisquer outras vantagens pecuniárias, bem como os benefícios previdenciários ou assistenciais, tais como: aposentadoria, auxílio-natalidade, salário-família, licença para tratamento de saúde, licença a gestante, a adotante e licença-maternidade, licença por acidente em serviço, assistência a saúde, garantia de condições individuais e ambientais de trabalho satisfatórias, pensão vitalícia e temporária, auxílio-funeral, auxílio-reclusão, auxílio-invalidez, assistência a saúde. Estão excluídos ainda as indenizações e restituições trabalhistas decorrentes da perda da condição de servidor ou empregado, tais como ferias, aviso prévio indenizados e outras. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1830, 2, '3.1.3.3.0.00.00.00.00.00', 'BENEFÍCIOS A PESSOAL - MILITAR', 'Compreende o valor total das variações patrimoniais diminutivas com benefícios devidos a pessoal militar, tais como: adicional de compensação orgânica não incorporada, gratificação de localidade especial, gratificação de representação, transporte, ajuda-de-custo, auxílio-fardamento, auxílio-alimentação e outros benefícios eventuais relativos ao local ou a natureza do trabalho. Estão excluídos deste grupo os soldos e quaisquer outras vantagens pecuniárias permanentes, bem como as os benefícios previdenciários ou assistenciais, tais como: aposentadoria, auxílio-natalidade, salário-família, licença para tratamento de saúde, licença a gestante, a adotante e licença-maternidade, licença por acidente em serviço, assistência a saúde, garantia de condições individuais e ambientais de trabalho satisfatórias, pensão vitalícia e temporária, auxílio-funeral, auxílio-reclusão, auxílio-invalidez, assistência a saúde.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1831, 2, '3.1.3.3.1.00.00.00.00.00', 'BENEFÍCIOS A PESSOAL - MILITAR - CONSOLIDAÇÃO', 'Compreende o valor total das variações patrimoniais diminutivas com benefícios devidos a pessoal militar, tais como: adicional de compensação orgânica não incorporada, gratificação de localidade especial, gratificação de representação, transporte, ajuda-de-custo, auxílio-fardamento, auxílio-alimentação e outros benefícios eventuais relativos ao local ou a natureza do trabalho. Estão excluídos deste grupo os soldos e quaisquer outras vantagens pecuniárias permanentes, bem como as os benefícios previdenciários ou assistenciais, tais como: aposentadoria, auxílio-natalidade, salário-família, licença para tratamento de saúde, licença a gestante, a adotante e licença-maternidade, licença por acidente em serviço, assistência a saúde, garantia de condições individuais e ambientais de trabalho satisfatórias, pensão vitalícia e temporária, auxílio-funeral, auxílio-reclusão, auxílio-invalidez, assistência a saúde. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1832, 2, '3.1.9.2.1.00.00.00.00.00', 'PESSOAL REQUISITADO DE OUTROS ÓRGÃOS E ENTES - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais diminutivas  com pessoal requisitado de outros órgãos e entes.  Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1833, 2, '3.1.9.9.0.00.00.00.00.00', 'OUTRAS VPD DE PESSOAL E ENCARGOS', 'Compreende outras variações patrimoniais diminutivas, relacionadas com pessoal e encargos, não abrangidas nos grupos anteriores.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1834, 2, '3.1.9.9.1.00.00.00.00.00', 'OUTRAS VPD DE PESSOAL E ENCARGOS - CONSOLIDAÇÃO', 'Compreende outras variações patrimoniais diminutivas, relacionadas com pessoal e encargos, não abrangidas nos grupos anteriores. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1835, 2, '3.2.0.0.0.00.00.00.00.00', 'BENEFÍCIOS PREVIDENCIÁRIOS E ASSISTENCIAIS', 'Compreendem as variações patrimoniais diminutivas relativas às aposentadorias, pensões, reformas, reserva remunerada e outros benefícios previdenciários de caráter contributivo, do regime próprio da previdência social - RPPS e do regime geral da previdência social - RGPS, bem como as ações de assistência social, que são políticas de seguridade social não contributiva, visando ao enfrentamento da pobreza, a garantia dos mínimos sociais, ao provimento de condições para atender contingencias sociais e a universalização dos direitos sociais.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1836, 2, '3.2.1.0.0.00.00.00.00.00', 'APOSENTADORIAS E REFORMAS', 'Compreendem os benefícios de prestação continuada assegurados pela previdência social com o objetivo de garantir meios indispensáveis de manutenção, por motivo de incapacidade, idade avançada e tempo de serviço.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1837, 2, '3.2.1.1.0.00.00.00.00.00', 'APOSENTADORIAS - RPPS', 'Compreendem os benefícios de prestação continuada assegurados pela previdência social com o objetivo de garantir meios indispensáveis de manutenção, por motivo de incapacidade, idade avançada e tempo de serviço, abrangidas pelo RPPS.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1838, 2, '3.2.1.1.1.00.00.00.00.00', 'APOSENTADORIAS - RPPS - CONSOLIDAÇÃO', 'Compreendem os benefícios de prestação continuada assegurados pela previdência social com o objetivo de garantir meios indispensáveis de manutenção, por motivo de incapacidade, idade avançada e tempo de serviço, abrangidas pelo RPPS. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1839, 2, '3.2.1.4.1.00.00.00.00.00', 'REFORMA - PESSOAL MILITAR - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais diminutivas com reserva remunerada e reformas dos militares. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1840, 2, '3.2.1.4.1.01.00.00.00.00', 'PROVENTOS REFORMA - PESSOAL MILITAR', 'Compreende as variações patrimoniais diminutivas com os proventos da reforma dos militares', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1841, 2, '3.2.1.9.0.00.00.00.00.00', 'OUTRAS APOSENTADORIAS', 'Compreende as variações patrimoniais diminutivas provenientes de outras aposentadorias', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1842, 2, '3.2.1.9.1.00.00.00.00.00', 'OUTRAS APOSENTADORIAS - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais diminutivas provenientes de outras aposentadorias. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1843, 2, '3.2.2.0.0.00.00.00.00.00', 'PENSÕES', 'Compreendem os benefícios da previdência social que garantem uma renda aos dependentes do segurado falecido.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1844, 2, '3.2.2.1.0.00.00.00.00.00', 'PENSÕES - RPPS', 'Compreende as variações patrimoniais diminutivas com pagamento de pensões aos dependentes dos segurados, após seu óbito, pelo regime próprio da previdência social - RPPS', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1847, 2, '3.2.2.2.1.00.00.00.00.00', 'PENSÕES - RGPS - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais diminutivas com pagamento de pensões aos dependentes dos segurados, após seu óbito, regidos pelo regime geral da previdência social - RGPS. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1848, 2, '3.2.2.3.0.00.00.00.00.00', 'PENSÕES - PESSOAL MILITAR', 'Compreende as variações patrimoniais diminutivas com pagamento de pensões aos dependentes dos militares, após seu óbito, regidos pelo regime próprio.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1849, 2, '3.2.2.3.1.00.00.00.00.00', 'PENSÕES - PESSOAL MILITAR - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais diminutivas com pagamento de pensões aos dependentes dos militares, após seu óbito, regidos pelo regime próprio. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1850, 2, '3.2.2.9.0.00.00.00.00.00', 'OUTRAS PENSÕES', 'Compreende as variações patrimoniais diminutivas provenientes de outras pensões.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1851, 2, '3.2.2.9.1.00.00.00.00.00', 'OUTRAS PENSÕES - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais diminutivas provenientes de outras pensões. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1852, 2, '3.2.3.0.0.00.00.00.00.00', 'BENEFÍCIOS DE PRESTAÇÃO CONTINUADA', 'Compreendem os benefícios de prestação continuada', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1853, 2, '3.2.3.1.0.00.00.00.00.00', 'BENEFÍCIOS DE PRESTAÇÃO CONTINUADA AO IDOSO', 'Compreendem os benefícios de prestação continuada ao idoso e renda mensal vitalícia por idade.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1854, 2, '3.2.3.1.1.00.00.00.00.00', 'BENEFÍCIOS DE PRESTAÇÃO CONTINUADA AO IDOSO - CONSOLIDAÇÃO', 'Compreendem os benefícios de prestação continuada e renda mensal vitalícia por idade. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1855, 2, '3.2.3.2.0.00.00.00.00.00', 'BENEFÍCIOS DE PRESTAÇÃO CONTINUADA AO PORTADOR DE DEFICIÊNCIA', 'Compreendem os benefícios de prestação continuada ao portador de deficiência e renda mensal vitalícia - invalidez', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1856, 2, '3.2.3.2.1.00.00.00.00.00', 'BENEFÍCIOS DE PRESTAÇÃO CONTINUADA AO PORTADOR DE DEFICIÊNCIA - CONSOLIDAÇÃO', 'Compreendem os benefícios de prestação continuada ao portador de deficiência e renda mensal vitalícia - invalidez. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1857, 2, '3.2.3.9.1.00.00.00.00.00', 'OUTROS BENEFÍCIOS DE PRESTAÇÃO CONTINUADA - CONSOLIDAÇÃO', 'Compreende outros benefícios de prestação continuada. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1858, 2, '3.2.4.0.0.00.00.00.00.00', 'BENEFÍCIOS EVENTUAIS', 'Compreendem as provisões suplementares e provisórias, prestadas aos cidadãos e as famílias em virtude de nascimento, morte, situações de vulnerabilidade temporária e de calamidade pública. As provisões relativas a programas, projetos, serviços e benefícios diretamente vinculados ao campo da saúde, educação, integração nacional e das demais políticas setoriais não se incluem na modalidade de benefícios eventuais da assistência social.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1859, 2, '3.2.4.1.0.00.00.00.00.00', 'AUXÍLIO POR NATALIDADE', 'Compreende o beneficio eventual que visa o pagamento de auxílio por natalidade as famílias cuja renda mensal per capita seja inferior a 1/4 (um quarto) do salário mínimo.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1860, 2, '3.2.4.1.1.00.00.00.00.00', 'AUXÍLIO POR NATALIDADE - CONSOLIDAÇÃO', 'Compreende o beneficio eventual que visa o pagamento de auxílio por natalidade as famílias cuja renda mensal per capita seja inferior a 1/4 (um quarto) do salário mínimo. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1861, 2, '3.2.4.2.0.00.00.00.00.00', 'AUXÍLIO POR MORTE', 'Compreende o beneficio eventual que visa o pagamento de auxílio por morte as famílias cuja renda mensal per capita seja inferior a 1/4 (um quarto) do salário mínimo.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1862, 2, '3.2.4.2.1.00.00.00.00.00', 'AUXÍLIO POR MORTE - CONSOLIDAÇÃO', 'Compreende o beneficio eventual que visa o pagamento de auxílio por morte as famílias cuja renda mensal per capita seja inferior a 1/4 (um quarto) do salário mínimo. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1863, 2, '3.2.4.3.0.00.00.00.00.00', 'BENEFÍCIOS EVENTUAIS POR SITUAÇÕES DE VULNERABILIDADE TEMPORÁRIA', 'Compreende as provisões suplementares e provisórias, prestadas aos cidadãos e as famílias em virtude de situações de vulnerabilidade temporária, com prioridade para a criança, a família, o idoso, a pessoa portadora de deficiência, a gestante e a nutriz.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1864, 2, '3.3.1.1.0.00.00.00.00.00', 'CONSUMO DE MATERIAL', 'Compreende as variações patrimoniais diminutivas provenientes de requisição de material de consumo para uso interno.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1865, 2, '3.2.4.3.1.00.00.00.00.00', 'BENEFÍCIOS EVENTUAIS POR SITUAÇÕES DE VULNERABILIDADE TEMPORÁRIA - CONSOLIDAÇÃO', 'Compreende as provisões suplementares e provisórias, prestadas aos cidadãos e as famílias em virtude de situações de vulnerabilidade temporária, com prioridade para a criança, a família, o idoso, a pessoa portadora de deficiência, a gestante e a nutriz. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1866, 2, '3.2.4.4.0.00.00.00.00.00', 'BENEFÍCIOS EVENTUAIS EM CASO DE CALAMIDADE PÚBLICA', 'Compreendem os benefícios para atendimento de vitimas de calamidade pública, de modo a assegurar lhes a sobrevivência e a reconstrução de sua autonomia. Entende-se se por estado de calamidade pública o reconhecimento pelo poder público de situação anormal, advinda de baixas ou altas temperaturas, tempestades, enchentes, inversão térmica, desabamentos, incêndios, epidemias, causando sérios danos à comunidade afetada, inclusive a incolumidade ou a vida de seus integrantes.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1867, 2, '3.2.9.2.0.00.00.00.00.00', 'OUTROS BENEFÍCIOS PREVIDENCIÁRIOS - RGPS', 'Compreende outras variações patrimoniais diminutivas, relacionadas com benefícios previdenciários do RGPS, não abrangidas nos grupos anteriores.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1888, 2, '3.3.2.1.0.00.00.00.00.00', 'DIÁRIAS', 'Compreende as variações patrimoniais diminutivas provenientes da utilização de diárias pagas aos servidores, empregados públicos e colaboradores eventuais, para fazer face a despesas com pousada, alimentação e locomoção urbana.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1868, 2, '3.2.4.4.1.00.00.00.00.00', 'BENEFÍCIOS EVENTUAIS EM CASO DE CALAMIDADE PÚBLICA - CONSOLIDAÇÃO', 'Compreendem os benefícios para atendimento de vitimas de calamidade pública, de modo a assegurar - lhes a sobrevivência e a reconstrução de sua autonomia. Entende-se por estado de calamidade pública o reconhecimento pelo poder público de situação anormal, advinda de baixas ou altas temperaturas, tempestades, enchentes, inversão térmica, desabamentos, incêndios, epidemias, causando sérios danos à comunidade afetada, inclusive a incolumidade ou a vida de seus integrantes. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1869, 2, '3.2.4.9.0.00.00.00.00.00', 'OUTROS BENEFÍCIOS EVENTUAIS', 'Compreende a variação patrimonial diminutiva proveniente de outros benefícios eventuais', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1870, 2, '3.2.4.9.1.00.00.00.00.00', 'OUTROS BENEFÍCIOS EVENTUAIS - CONSOLIDAÇÃO', 'Compreende a variação patrimonial diminutiva proveniente de outros benefícios eventuais.Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1871, 2, '3.2.5.0.0.00.00.00.00.00', 'POLÍTICAS PÚBLICAS DE TRANSFERÊNCIA DE RENDA', 'Compreende as políticas públicas que visem contribuir para a redução da fome, da pobreza, da desigualdade e de outras formas de privação vividas pelas famílias mais excluídas, considerando três dimensões: o alivio imediato da pobreza, por meio da transferência de renda diretamente as famílias pobres e extremamente pobres; a contribuição para a redução da pobreza da geração seguinte, por meio do reforço do direito de acesso aos serviços de saúde e de educação, com o cumprimento das condicionalidades nestas áreas; e a articulação de ações complementares, de forma a desenvolver as capacidades das famílias beneficiárias.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1872, 2, '3.2.5.0.1.00.00.00.00.00', 'POLÍTICAS PÚBLICAS DE TRANSFERÊNCIA DE RENDA - CONSOLIDAÇÃO', 'Compreende as políticas públicas que visem contribuir para a redução da fome, da pobreza, da desigualdade e de outras formas de privação vividas pelas famílias mais excluídas, considerando três dimensões: o alivio imediato da pobreza, por meio da transferência de renda diretamente as famílias pobres e extremamente pobres; a contribuição para a redução da pobreza da geração seguinte, por meio do reforço do direito de acesso aos serviços de saúde e de educação, com o cumprimento das condicionalidades nestas áreas; e a articulação de ações complementares, de forma a desenvolver as capacidades das famílias beneficiarias. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1873, 2, '3.2.9.0.0.00.00.00.00.00', 'OUTROS BENEFÍCIOS PREVIDENCIÁRIOS E ASSISTENCIAIS', 'Compreende outras variações patrimoniais diminutivas, relacionadas com benefícios previdenciários ou assistenciais, não abrangidas nos grupos anteriores.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1874, 2, '3.2.9.1.0.00.00.00.00.00', 'OUTROS BENEFÍCIOS PREVIDENCIÁRIOS - RPPS', 'Compreende outras variações patrimoniais diminutivas, relacionadas com benefícios previdenciários do RPPS, não abrangidas nos grupos anteriores.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1875, 2, '3.3.3.0.0.00.00.00.00.00', 'DEPRECIAÇÃO, AMORTIZAÇÃO E EXAUSTÃO', 'Compreende o decréscimo no beneficio de um bem durante o período contábil decorrente de depreciação, amortização e exaustão.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1876, 2, '3.2.9.1.1.00.00.00.00.00', 'OUTROS BENEFÍCIOS PREVIDENCIÁRIOS - RPPS - CONSOLIDAÇÃO', 'Compreende outras variações patrimoniais diminutivas, relacionadas com benefícios previdenciários do RPPS, não abrangidas nos grupos anteriores. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1877, 2, '3.2.9.2.1.00.00.00.00.00', 'OUTROS BENEFÍCIOS PREVIDENCIÁRIOS - RGPS - CONSOLIDAÇÃO', 'Compreende outras variações patrimoniais diminutivas, relacionadas com benefícios previdenciários do RGPS, não abrangidas nos grupos anteriores. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1878, 2, '3.2.9.3.0.00.00.00.00.00', 'OUTROS BENEFÍCIOS PREVIDENCIÁRIOS - MILITAR', 'Compreende outras variações patrimoniais diminutivas, relacionadas com benefícios previdenciários do regime próprio dos militares, não abrangidas nos grupos anteriores.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1879, 2, '3.2.9.3.1.00.00.00.00.00', 'OUTROS BENEFÍCIOS PREVIDENCIÁRIOS - MILITAR - CONSOLIDAÇÃO', 'Compreende outras variações patrimoniais diminutivas, relacionadas com benefícios previdenciários do regime próprio dos militares, não abrangidas nos grupos anteriores. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1880, 2, '3.2.9.9.0.00.00.00.00.00', 'OUTROS BENEFÍCIOS PREVIDENCIÁRIOS E ASSISTENCIAIS', 'Compreende as variações patrimoniais diminutivas provenientes de outros benefícios previdenciários e assistenciais', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1881, 2, '3.2.9.9.1.00.00.00.00.00', 'OUTROS BENEFÍCIOS PREVIDENCIÁRIOS E ASSISTENCIAIS - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais diminutivas provenientes de outros benefícios previdenciários e assistenciais. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1882, 2, '3.3.0.0.0.00.00.00.00.00', 'USO DE BENS, SERVIÇOS E CONSUMO DE CAPITAL FIXO', 'Compreende o somatório das variações patrimoniais diminutivas com manutenção e operação da maquina pública, exceto despesas com pessoal e encargos que serão registradas em grupo específico (despesas de pessoal e encargos). Compreende: diárias, material de consumo, material de distribuição gratuita, passagens e despesas com locomoção, serviços de terceiros, arrendamento mercantil operacional, aluguel, depreciação, amortização, exaustão, entre outras.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1883, 2, '3.3.1.0.0.00.00.00.00.00', 'USO DE MATERIAL DE CONSUMO', 'Compreende as variações patrimoniais diminutivas provenientes da distribuição do material de consumo. Um material é considerado de consumo quando for de duração inferior a dois anos, frágil, perecível, incorporável, transformável ou cuja finalidade seja para consumo imediato ou para reposição.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1884, 2, '3.3.1.1.1.00.00.00.00.00', 'CONSUMO DE MATERIAL - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais diminutivas provenientes de requisição de material de consumo para uso interno.Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1885, 2, '3.3.1.2.0.00.00.00.00.00', 'DISTRIBUIÇÃO DE MATERIAL GRATUITO', 'Compreende as variações patrimoniais diminutivas provenientes da distribuição de material gratuito.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2408, 2, '1.2.3.8.1.01.07.00.00.00', '(-) DEPRECIAÇÃO ACUMULADA DE BENS MÓVEIS EM ANDAMENTO', 'Registra a depreciação acumulada de bens móveis em andamento.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (1886, 2, '3.3.1.2.1.00.00.00.00.00', 'DISTRIBUIÇÃO DE MATERIAL GRATUITO - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais diminutivas provenientes da distribuição de material gratuito. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1889, 2, '3.3.2.1.1.00.00.00.00.00', 'DIÁRIAS - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais diminutivas provenientes da utilização de diárias pagas aos servidores, empregados públicos e colaboradores eventuais, para fazer face a despesas com pousada, alimentação e locomoção urbana.Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1890, 2, '3.3.2.2.0.00.00.00.00.00', 'SERVIÇOS TERCEIROS - PF', 'Compreende as variações patrimoniais diminutivas provenientes da prestação de serviços por pessoa física fornecida a entidade governamental. Na classificação da despesa de material por encomenda, a variação patrimonial diminutiva só devera ser classificada com serviços de terceiros se o próprio órgão ou entidade fornecer a matéria-prima.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1891, 2, '3.3.2.2.1.00.00.00.00.00', 'SERVIÇOS TERCEIROS - PF - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais diminutivas provenientes da prestação de serviços por pessoa física fornecida a entidade governamental. Na classificação da despesa de material por encomenda, a variação patrimonial diminutiva só devera ser classificada com serviços de terceiros se o próprio órgão ou entidade fornecer a matéria-prima. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1892, 2, '3.3.2.3.0.00.00.00.00.00', 'SERVIÇOS TERCEIROS - PJ', 'Compreende as variações patrimoniais diminutivas provenientes da prestação de serviços por pessoa jurídica fornecida a entidade governamental. Na classificação da despesa de material por encomenda, a variação patrimonial diminutiva só devera ser classificada com serviços de terceiros se o próprio órgão ou entidade fornecer a matéria-prima.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1893, 2, '3.3.2.3.1.00.00.00.00.00', 'SERVIÇOS TERCEIROS - PJ - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais diminutivas provenientes da prestação de serviços por pessoa jurídica fornecida a entidade governamental. Na classificação da despesa de material por encomenda, a variação patrimonial diminutiva só devera ser classificada com serviços de terceiros se o próprio órgão ou entidade fornecer a matéria-prima. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1894, 2, '3.3.2.4.0.00.00.00.00.00', 'CONTRATO DE TERCEIRIZAÇÃO POR SUBSTITUIÇÃO DE MÃO DE OBRA - ART. 18, § 1º, LC 101/00', 'Compreende a apropriação das despesas relativas à mão de obra, constantes dos contratos de terceirização, classificáveis no grupo de despesa com pessoal e encargos em obediência ao disposto no artigo 18, § 1º, da lei complementar nº 101, de 2000.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1895, 2, '3.3.2.4.1.00.00.00.00.00', 'CONTRATO DE TERCEIRIZAÇÃO POR SUBSTITUIÇÃO DE MÃO DE OBRA - ART. 18 § 1º, LC 101/00 - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais diminutivas relativas à mão de obra, constantes dos contratos de terceirização, classificáveis no grupo de despesa com pessoal e encargos em obediência ao disposto no artigo 18, § 1º, da lei complementar nº 101, de 2000. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1896, 2, '3.3.3.1.0.00.00.00.00.00', 'DEPRECIAÇÃO', 'Compreende a redução do valor dos bens tangíveis pelo desgaste ou perda de utilidade por uso, ação da natureza ou obsolescência.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1897, 2, '3.3.3.1.1.00.00.00.00.00', 'DEPRECIAÇÃO - CONSOLIDAÇÃO', 'Compreende a redução do valor dos bens tangíveis pelo desgaste ou perda de utilidade por uso, ação da natureza ou obsolescência. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1898, 2, '3.3.3.1.1.01.00.00.00.00', 'DEPRECIAÇÃO DE IMOBILIZADO', 'Compreende a redução do valor dos bens tangíveis, do ativo imobilizado, pelo desgaste ou perda de utilidade por uso, ação da natureza ou obsolescência.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1899, 2, '3.3.3.2.0.00.00.00.00.00', 'AMORTIZAÇÃO', 'Compreende a redução do valor aplicado na aquisição de direitos de propriedade e quaisquer outros, inclusive ativos intangíveis, com existência ou exercício de duração limitada, ou cujo objeto sejam bens de utilização por prazo legal ou contratualmente limitado.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1900, 2, '3.3.3.2.1.00.00.00.00.00', 'AMORTIZAÇÃO - CONSOLIDAÇÃO', 'Compreende a redução do valor aplicado na aquisição de direitos de propriedade e quaisquer outros, inclusive ativos intangíveis, com existência ou exercício de duração limitada, ou cujo objeto sejam bens de utilização por prazo legal ou contratualmente limitado. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1901, 2, '3.3.3.3.0.00.00.00.00.00', 'EXAUSTÃO', 'Compreende a redução do valor decorrente da exploração dos recursos minerais, florestais e outros recursos naturais esgotáveis.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1902, 2, '3.3.3.3.1.00.00.00.00.00', 'EXAUSTÃO - CONSOLIDAÇÃO', 'Compreende a redução do valor decorrente da exploração dos recursos minerais, florestais e outros recursos naturais esgotáveis. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1903, 2, '3.4.0.0.0.00.00.00.00.00', 'VARIAÇÕES PATRIMONIAIS DIMINUTIVAS FINANCEIRAS', 'Compreende as variações patrimoniais diminutivas com operações financeiras, tais como: juros incorridos, descontos concedidos, comissões, despesas bancarias e correções monetárias.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1904, 2, '3.4.1.0.0.00.00.00.00.00', 'JUROS E ENCARGOS DE EMPRÉSTIMOS E FINANCIAMENTOS OBTIDOS', 'Compreende a variação patrimonial diminutiva com juros e encargos de empréstimos e financiamentos contraídos com pessoas jurídicas de direito público ou privado.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1905, 2, '3.4.1.1.0.00.00.00.00.00', 'JUROS E ENCARGOS DA DÍVIDA CONTRATUAL INTERNA', 'Compreende a variação patrimonial diminutiva com juros e encargos da dívida pública interna derivada de obrigações assumidas com pessoas jurídicas de direito público ou privado com vistas à execução de obras, fornecimento de bens ou prestação de serviços, ou da celebração de contratos de financiamento.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1965, 2, '3.4.4.0.0.00.00.00.00.00', 'DESCONTOS FINANCEIROS CONCEDIDOS', 'Compreende o valor da variação patrimonial diminutiva com descontos financeiros concedidos a clientes por pagamentos antecipados de duplicatas e outros títulos. Não se confundem com descontos nos preços de venda concedidos incondicionalmente, ou abatimentos de preços, que são deduções da receita.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1906, 2, '3.4.1.1.1.00.00.00.00.00', 'JUROS E ENCARGOS DA DÍVIDA CONTRATUAL INTERNA - CONSOLIDAÇÃO', 'Compreende a variação patrimonial diminutiva com juros e encargos da dívida pública interna derivada de obrigações assumidas com pessoas jurídicas de direito público ou privado com vistas à execução de obras, fornecimento de bens ou prestação de serviços, ou da celebração de contratos de financiamento. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1939, 2, '3.4.2.3.1.99.00.00.00.00', 'OUTROS ENCARGOS DE MORA', 'Compreende a Variação Patrimonial Diminutiva com outros encargos referentes a penalidade em virtude de atrasos e não cumprimento dos prazos dos contratos de prestação de serviços e aquisição de bens, que não se enquadrem nos itens anteriores.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1907, 2, '3.4.1.1.3.00.00.00.00.00', 'JUROS E ENCARGOS DA DÍVIDA CONTRATUAL INTERNA - INTER OFSS - UNIÃO', 'Compreende a variação patrimonial diminutiva com juros e encargos da dívida pública interna derivada de obrigações assumidas com pessoas jurídicas de direito público ou privado com vistas à execução de obras, fornecimento de bens ou prestação de serviços, ou da celebração de contratos de financiamento. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) de. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1908, 2, '3.4.1.1.4.00.00.00.00.00', 'JUROS E ENCARGOS DA DÍVIDA CONTRATUAL INTERNA - INTER OFSS - ESTADO', 'Compreende a variação patrimonial diminutiva com juros e encargos da dívida pública interna derivada de obrigações assumidas com pessoas jurídicas de direito público ou privado com vistas à execução de obras, fornecimento de bens ou prestação de serviços, ou da celebração de contratos de financiamento. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1909, 2, '3.4.1.1.5.00.00.00.00.00', 'JUROS E ENCARGOS DA DÍVIDA CONTRATUAL INTERNA - INTER OFSS - MUNICÍPIO', 'Compreende a variação patrimonial diminutiva com juros e encargos da dívida pública interna derivada de obrigações assumidas com pessoas jurídicas de direito público ou privado com vistas à execução de obras, fornecimento de bens ou prestação de serviços, ou da celebração de contratos de financiamento. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1910, 2, '3.4.1.2.0.00.00.00.00.00', 'JUROS E ENCARGOS DA DÍVIDA CONTRATUAL EXTERNA', 'Compreende a variação patrimonial diminutiva com juros e encargos da dívida pública externa derivada de obrigações assumidas com pessoas jurídicas de direito público ou privado com vistas à execução de obras, fornecimento de bens ou prestação de serviços, ou da celebração de contratos de financiamento.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1911, 2, '3.4.1.2.1.00.00.00.00.00', 'JUROS E ENCARGOS DA DÍVIDA CONTRATUAL EXTERNA - CONSOLIDAÇÃO', 'Compreende a variação patrimonial diminutiva com juros e encargos da dívida pública externa derivada de obrigações assumidas com pessoas jurídicas de direito público ou privado com vistas à execução de obras, fornecimento de bens ou prestação de serviços, ou da celebração de contratos de financiamento.Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1912, 2, '3.4.1.3.0.00.00.00.00.00', 'JUROS E ENCARGOS DA DÍVIDA MOBILIÁRIA', 'Compreende a variação patrimonial diminutiva com juros e encargos da dívida pública representada por títulos emitidos pelo governo. São considerados encargos da dívida mobiliaria: comissões, corretagens, seguros, deságio e outros.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1913, 2, '3.4.1.3.1.00.00.00.00.00', 'JUROS E ENCARGOS DA DÍVIDA MOBILIÁRIA - CONSOLIDAÇÃO', 'Compreende a variação patrimonial diminutiva com juros e encargos da dívida pública representada por títulos emitidos pelo governo. São considerados encargos da dívida mobiliaria: comissões, corretagens, seguros, deságio e outros. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1914, 2, '3.9.6.3.0.00.00.00.00.00', 'PARTICIPAÇÕES DE ADMINISTRADORES', 'Compreende as participações de administradores incidentes sobre o lucro após imposto de renda e contribuição social sobre o lucro liquido.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1915, 2, '3.4.1.4.0.00.00.00.00.00', 'JUROS E ENCARGOS DE EMPRÉSTIMOS POR ANTECIPAÇÃO DE RECEITA ORÇAMENTÁRIA', 'Compreende a variação patrimonial diminutiva com juros e encargos sobre empréstimos contraídos por antecipação de receita orçamentária para atender insuficiência de caixa durante o exercício financeiro.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1916, 2, '3.4.1.4.1.00.00.00.00.00', 'JUROS E ENCARGOS DE EMPRÉSTIMOS POR ANTECIPAÇÃO DE RECEITA ORÇAMENTÁRIA - CONSOLIDAÇÃO', 'Compreende a variação patrimonial diminutiva com juros e encargos sobre empréstimos contraídos por antecipação de receita orçamentária para atender insuficiência de caixa durante o exercício financeiro. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1917, 2, '3.4.1.8.0.00.00.00.00.00', 'OUTROS JUROS E ENCARGOS DE EMPRÉSTIMOS E FINANCIAMENTOS INTERNOS', 'Compreende a variação patrimonial diminutiva com juros e encargos de empréstimos e financiamentos internos que não sejam referentes a dívida contratual, a dívida mobiliaria e a por antecipação de receita orçamentária.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1918, 2, '3.4.1.8.1.00.00.00.00.00', 'OUTROS JUROS E ENCARGOS DE EMPRÉSTIMOS E FINANCIAMENTOS INTERNOS - CONSOLIDAÇÃO', 'Compreende a variação patrimonial diminutiva com juros e encargos de empréstimos e financiamentos internos que não sejam referentes a dívida contratual, a dívida mobiliaria e a por antecipação de receita orçamentária. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1919, 2, '3.4.1.8.3.00.00.00.00.00', 'OUTROS JUROS E ENCARGOS DE EMPRÉSTIMOS E FINANCIAMENTOS INTERNOS - INTER OFSS - UNIÃO', 'Compreende a variação patrimonial diminutiva com juros e encargos de empréstimos e financiamentos internos que não sejam referentes a dívida contratual, a dívida mobiliaria e a por antecipação de receita orçamentária. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1988, 2, '3.5.1.3.2.02.00.00.00.00', 'PLANO PREVIDENCIÁRIO', 'Compreende o valor total concedido ao RPPS para cobertura de déficit financeiro ou atuarial e outros aportes, no âmbito do plano previdenciário.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1920, 2, '3.4.1.8.4.00.00.00.00.00', 'OUTROS JUROS E ENCARGOS DE EMPRÉSTIMOS E FINANCIAMENTOS INTERNOS - INTER OFSS - ESTADO', 'Compreende a variação patrimonial diminutiva com juros e encargos de empréstimos e financiamentos internos que não sejam referentes a dívida contratual, a dívida mobiliaria e a por antecipação de receita orçamentária. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1921, 2, '3.9.1.0.0.00.00.00.00.00', 'PREMIAÇÕES', 'Compreende as aquisições de prêmios, condecorações, medalhas, troféus, etc., bem como com o pagamento de prêmios em pecúnia, inclusive decorrentes de sorteios lotéricos.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1940, 2, '3.4.2.4.0.00.00.00.00.00', 'JUROS E ENCARGOS DE MORA DE OBRIGAÇÕES TRIBUTÁRIAS', 'Compreende a variação patrimonial diminutiva com juros e encargos a titulo de penalidade em virtude de atrasos e não cumprimento dos prazos de obrigações tributárias devidas.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1972, 2, '3.4.9.0.0.00.00.00.00.00', 'OUTRAS VARIAÇÕES PATRIMONIAIS DIMINUTIVAS - FINANCEIRAS', 'Compreende outras variações patrimoniais diminutivas financeiras, não abrangidas nos grupos anteriores.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1922, 2, '3.4.1.8.5.00.00.00.00.00', 'OUTROS JUROS E ENCARGOS DE EMPRÉSTIMOS E FINANCIAMENTOS INTERNOS - INTER OFSS - MUNICÍPIO', 'Compreende a variação patrimonial diminutiva com juros e encargos de empréstimos e financiamentos internos que não sejam referentes a dívida contratual, a dívida mobiliaria e a por antecipação de receita orçamentária. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1923, 2, '3.4.1.9.0.00.00.00.00.00', 'OUTROS JUROS E ENCARGOS DE EMPRÉSTIMOS E FINANCIAMENTOS EXTERNOS', 'Compreende a variação patrimonial diminutiva com juros e encargos de empréstimos e financiamentos externos que não sejam referentes a dívida contratual, a dívida mobiliaria e a por antecipação de receita orçamentária.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1924, 2, '3.4.1.9.1.00.00.00.00.00', 'OUTROS JUROS E ENCARGOS DE EMPRÉSTIMOS E FINANCIAMENTOS EXTERNOS - CONSOLIDAÇÃO', 'Compreende a variação patrimonial diminutiva com juros e encargos de empréstimos e financiamentos externos que não sejam referentes a dívida contratual, a dívida mobiliaria e a por antecipação de receita orçamentária. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1925, 2, '3.4.2.0.0.00.00.00.00.00', 'JUROS E ENCARGOS DE MORA', 'Compreende o montante de variação patrimonial diminutiva com juros e encargos a titulo de penalidade em virtude de atrasos e não cumprimento dos prazos contratuais.', 1, false, 0, 'N');
