insert into contabilidade.planocontadetalhe values (1931, 2, '5.1.2.2.0.00.00.00.00.00', 'PROJETO INICIAL DA LOA - DESPESA', 'Compreende o somatório dos valores monetários constantes do projeto da lei orçamentária anual remetido pelo poder executivo ao poder legislativo para apreciação e aprovação.', 1, false, 0, 'N');
