insert into contabilidade.planocontadetalhe values (1937, 2, '3.4.2.3.1.02.00.00.00.00', 'MULTAS DEDUTÍVEIS', 'Compreende a Variação Patrimonial Diminutiva com multas, que sejam dedutíveis na determinação do lucro real pela legislação, referentes a penalidade em virtude de atrasos e não cumprimento dos prazos dos contratos de prestação de serviços e aquisição de bens.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1938, 2, '3.4.2.3.1.03.00.00.00.00', 'MULTAS INDEDUTÍVEIS', 'Compreende a Variação Patrimonial Diminutiva com multas, que sejam indedutíveis na determinação do lucro real pela legislação, referentes a penalidade em virtude de atrasos e não cumprimento dos prazos dos contratos de prestação de serviços e aquisição de bens.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3380, 2, '8.1.2.1.1.01.13.00.00.00', 'CAUÇÕES A EXECUTAR', 'Registra o valor das garantias por cauções pendentes de execução, no país.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (1941, 2, '3.4.2.4.1.00.00.00.00.00', 'JUROS E ENCARGOS DE MORA DE OBRIGAÇÕES TRIBUTÁRIAS - CONSOLIDAÇÃO', 'Compreende a variação patrimonial diminutiva com juros e encargos a titulo de penalidade em virtude de atrasos e não cumprimento dos prazos de obrigações tributárias devidas. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1942, 2, '3.4.2.9.0.00.00.00.00.00', 'OUTROS JUROS E ENCARGOS DE MORA', 'Compreende a variação patrimonial diminutiva com juros e encargos a titulo de penalidade em virtude de atrasos e não cumprimento dos prazos em situações não compreendidas nas classificações anteriores.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1943, 2, '3.4.3.0.0.00.00.00.00.00', 'VARIAÇÕES MONETÁRIAS E CAMBIAIS', 'Compreende a variação patrimonial diminutiva proveniente de variações da nossa própria moeda em relação aos índices ou coeficientes aplicáveis por dispositivo legal ou contratual e a variação do valor da nossa moeda em relação às moedas estrangeiras. Ressalte-se que será tratada como variação monetária apenas a correção monetária pós-fixada.', 1, false, 0, 'N');
