insert into contabilidade.planocontadetalhe values (1963, 2, '3.5.1.3.0.00.00.00.00.00', 'TRANSFERÊNCIAS CONCEDIDAS PARA APORTES DE RECURSOS PARA O RPPS', 'Compreende o valor das transferências para aportes financeiros do ente para cobertura de insuficiências financeiras, formação de reserva, e cobertura de déficits financeiros ou atuariais do RPPS e outros aportes, exceto os decorrentes de alíquota de contribuição suplementar.', 1, false, 0, 'N');
