insert into contabilidade.planocontadetalhe values (2071, 2, '3.6.2.2.1.01.00.00.00.00', 'PERDAS COM ALIENAÇÃO DE BENS MOVEIS', 'Compreende a variação patrimonial diminutiva de perdas com alienação de bens móveis.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1966, 2, '3.4.4.0.1.00.00.00.00.00', 'DESCONTOS FINANCEIROS CONCEDIDOS  - CONSOLIDAÇÃO', 'Compreende o valor da variação patrimonial diminutiva com descontos financeiros concedidos a clientes por pagamentos antecipados de duplicatas e outros títulos. Não se confundem com descontos nos preços de venda concedidos incondicionalmente, ou abatimentos de preços, que são deduções da receita. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1967, 2, '3.4.8.0.0.00.00.00.00.00', 'APORTES AO BANCO CENTRAL', 'Compreende os aportes de recursos do Tesouro Nacional ao Banco Central do Brasil. Conta de uso exclusivo da União.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1968, 2, '3.4.8.1.0.00.00.00.00.00', 'RESULTADO NEGATIVO DO BANCO CENTRAL', 'Compreende os aportes de títulos públicos para cobertura de resultado negativo do Banco Central do Brasil, conforme art. 7º da Lei Complementar 101, de 4/5/2000. ', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1969, 2, '3.4.8.1.1.00.00.00.00.00', 'RESULTADO NEGATIVO DO BANCO CENTRAL - CONSOLIDAÇÃO', 'Compreende os aportes de títulos públicos para cobertura de resultado negativo do Banco Central do Brasil, conforme art. 7º da Lei Complementar 101, de 4/5/2000. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1970, 2, '3.4.8.2.0.00.00.00.00.00', 'MANUTENÇÃO DA CARTEIRA DE TÍTULOS', 'Compreende os aportes de títulos públicos ao Banco Central do Brasil, para complementação de carteira, conforme disposto na Lei nº 10.179, de 6/2/2011.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1971, 2, '3.4.8.2.1.00.00.00.00.00', 'MANUTENÇÃO DA CARTEIRA DE TÍTULOS - CONSOLIDAÇÃO', 'Compreende os aportes de títulos públicos ao Banco Central do Brasil, para complementação de carteira, conforme disposto na Lei nº 10.179, de 6/2/2011. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1973, 2, '3.4.9.1.0.00.00.00.00.00', 'JUROS E ENCARGOS EM SENTENÇAS JUDICIAIS', 'Compreende os juros e encargos resultantes de pagamento de precatórios e de sentenças judiciais transitadas em julgado.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1974, 2, '3.4.9.2.0.00.00.00.00.00', 'JUROS E ENCARGOS EM INDENIZAÇÕES E RESTITUIÇÕES', 'Compreende as variações patrimoniais diminutivas com indenizações e restituições referentes a juros e encargos.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1975, 2, '3.4.9.2.1.00.00.00.00.00', 'JUROS E ENCARGOS EM INDENIZAÇÕES E RESTITUIÇÕES - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais diminutivas com indenizações e restituições referentes a juros e encargos. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1976, 2, '3.4.9.9.0.00.00.00.00.00', 'OUTRAS VARIAÇÕES PATRIMONIAIS DIMINUTIVAS FINANCEIRAS', 'Compreende as variações patrimoniais diminutivas provenientes de operações financeiras não compreendidas nas contas anteriores.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1977, 2, '3.4.9.9.1.00.00.00.00.00', 'OUTRAS VARIAÇÕES PATRIMONIAIS DIMINUTIVAS FINANCEIRAS - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais diminutivas provenientes de operações financeiras não compreendidas nas contas anteriores. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1978, 2, '3.5.0.0.0.00.00.00.00.00', 'TRANSFERÊNCIAS E DELEGAÇÕES CONCEDIDAS', 'Compreende o somatório das variações patrimoniais diminutivas com transferências intergovernamentais, transferências intragovernamentais, transferências a instituições multigovernamentais, transferências a instituições privadas com ou sem fins lucrativos, transferências a convênios, transferências ao exterior e execuções orçamentárias delegadas.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1979, 2, '3.5.1.0.0.00.00.00.00.00', 'TRANSFERÊNCIAS INTRAGOVERNAMENTAIS', 'Compreende as variações patrimoniais diminutivas decorrentes das transferências financeiras relativas à execução orçamentária, e de bens e valores, referentes às transações intragovernamentais.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1980, 2, '3.5.1.1.0.00.00.00.00.00', 'TRANSFERÊNCIAS CONCEDIDAS PARA A EXECUÇÃO ORÇAMENTÁRIA', 'Compreende o valor das transferências financeiras concedidas e correspondência de créditos em virtude da execução orçamentária (cota, repassse e sub-repasse). Não Inclui o valor repassado para aportes no RPPS ou RGPS.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1981, 2, '3.5.1.1.2.00.00.00.00.00', 'TRANSFERÊNCIAS CONCEDIDAS PARA A EXECUÇÃO ORÇAMENTÁRIA -  INTRA OFSS', 'Compreende o valor das transferências financeiras concedidas e correspondência de créditos em virtude da execução orçamentária (cota, repassse e sub-repasse). Não Inclui o valor repassado para aportes no RPPS ou RGPS. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1982, 2, '3.5.1.2.0.00.00.00.00.00', 'TRANSFERÊNCIAS CONCEDIDAS - INDEPENDENTES DE EXECUÇÃO ORÇAMENTÁRIA', 'Compreende o valor das transferências financeiras, de bens ou valores, concedidas para restos a pagar e outras finalidades independentes da execução orçamentária.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1983, 2, '3.5.1.2.2.00.00.00.00.00', 'TRANSFERÊNCIAS CONCEDIDAS - INDEPENDENTES DE EXECUÇÃO ORÇAMENTÁRIA - INTRA OFSS', 'Compreende o valor das transferências financeiras, de bens ou valores, concedidas para restos a pagar e outras finalidades independentes da execução orçamentária. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do ente.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1984, 2, '3.5.1.2.2.01.00.00.00.00', 'TRANSFERÊNCIAS FINANCEIRAS CONCEDIDAS - INDEPENDENTES DE EXECUÇÃO ORÇAMENTÁRIA', 'Compreende o valor das transferências financeiras concedidas para restos a pagar e outras finalidades independentes da execução orçamentária.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1985, 2, '3.5.1.2.2.02.00.00.00.00', 'TRANSFERÊNCIAS  NÃO FINANCEIRAS CONCEDIDAS - INDEPENDENTES DE EXECUÇÃO ORÇAMENTÁRIA', 'Compreende o valor das transferências concedidas de bens ou valores independentes da execução orçamentária.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1986, 2, '3.5.1.3.2.00.00.00.00.00', 'TRANSFERÊNCIAS CONCEDIDAS PARA APORTES DE RECURSOS PARA O RPPS - INTRA OFSS', 'Compreende o valor das transferências para aportes financeiros do ente para cobertura de insuficiências financeiras, formação de reserva, e cobertura de déficits financeiros ou atuariais do RPPS e outros aportes exceto os decorrentes de alíquota de contribuição suplementar. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do ente.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1987, 2, '3.5.1.3.2.01.00.00.00.00', 'PLANO FINANCEIRO', 'Compreende o valor total dos valores concedidos pelo RPPS para cobertura de insuficiências financeiras, formação de reserva e outras necessidades financeiras, no âmbito do plano financeiro.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3246, 2, '5.2.1.1.2.99.00.00.00.00', '(-) OUTRAS DEDUÇÕES', 'Registra a previsão de outras deduções da receita aprovada na LOA.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (1989, 2, '3.5.1.4.0.00.00.00.00.00', 'TRANSFERÊNCIAS CONCEDIDAS PARA APORTES DE RECURSOS PARA O RGPS', 'Compreende o valor das transferências para os aportes financeiros da União para a cobertura de déficits financeiros ou atuariais do RGPS.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1990, 2, '3.5.1.4.2.00.00.00.00.00', 'TRANSFERÊNCIAS CONCEDIDAS PARA APORTES DE RECURSOS PARA O RGPS  - INTRA OFSS', 'Compreende o valor das transferências para os aportes financeiros da União para a cobertura de déficits financeiros ou atuariais do RGPS. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do ente.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1991, 2, '3.5.2.0.0.00.00.00.00.00', 'TRANSFERÊNCIAS INTER GOVERNAMENTAIS', 'Compreende as variações patrimoniais diminutivas decorrentes de transferências a União, Estados, Distrito Federal, Municípios, inclusive as entidades vinculadas, de bens e/ou valores.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1992, 2, '3.5.2.1.0.00.00.00.00.00', 'DISTRIBUIÇÃO CONSTITUCIONAL OU LEGAL DE RECEITAS', 'Compreende as variações patrimoniais diminutivas decorrentes da transferência a outras esferas de governo de receitas tributárias, de contribuições e de outras receitas vinculadas, prevista na Constituição ou em leis específicas, cuja competência de arrecadação é do órgão transferidor.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1993, 2, '3.5.2.1.1.00.00.00.00.00', 'DISTRIBUIÇÃO CONSTITUCIONAL OU LEGAL DE RECEITAS - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais diminutivas decorrentes da transferência a outras esferas de governo de receitas tributárias, de contribuições e de outras receitas vinculadas, prevista na constituição ou em leis específicas, cuja competência de arrecadação é do órgão transferidor. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS). Por exemplo, empresa independente de um ente recebendo transferência de outro ente. (a empresa independente não pertence ao OFSS mas pertence ao conceito de governamental).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1994, 2, '3.5.3.1.0.00.00.00.00.00', 'TRANSFERÊNCIAS A INSTITUIÇÕES PRIVADAS SEM FINS LUCRATIVOS', 'Compreende as variações patrimoniais diminutivas decorrentes das transferências de bens e valores a instituições privadas sem fins lucrativos que não tenham vinculo com a administração pública, exemplo: ONGs, OSCIPS e OS.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1995, 2, '3.5.2.1.3.00.00.00.00.00', 'DISTRIBUIÇÃO CONSTITUCIONAL OU LEGAL DE RECEITAS - INTER OFSS - UNIÃO', 'Compreende as variações patrimoniais diminutivas decorrentes da transferência a outras esferas de governo de receitas tributárias, de contribuições e de outras receitas vinculadas, prevista na Constituição ou em leis específicas, cuja competência de arrecadação é do órgão transferidor. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) de entes públicos distintos, para permitir a consolidação nacional realizada pelo Poder Executivo da União.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1996, 2, '3.5.2.1.4.00.00.00.00.00', 'DISTRIBUIÇÃO CONSTITUCIONAL OU LEGAL DE RECEITAS - INTER OFSS - ESTADO', 'Compreende as variações patrimoniais diminutivas decorrentes da transferência a outras esferas de governo de receitas tributárias, de contribuições e de outras receitas vinculadas, prevista na Constituição ou em leis específicas, cuja competência de arrecadação é do órgão transferidor. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1997, 2, '3.5.2.1.5.00.00.00.00.00', 'DISTRIBUIÇÃO CONSTITUCIONAL OU LEGAL DE RECEITAS - INTER OFSS - MUNICÍPIO', 'Compreende as variações patrimoniais diminutivas decorrentes da transferência a outras esferas de governo de receitas tributárias, de contribuições e de outras receitas vinculadas, prevista na Constituição ou em leis específicas, cuja competência de arrecadação é do órgão transferidor. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1998, 2, '3.5.2.2.0.00.00.00.00.00', 'TRANSFERÊNCIAS AO FUNDEB', 'Compreende as variações patrimoniais diminutivas decorrentes da transferência de recursos dos entes, incluindo a complementação da União, para a composição do Fundo de Manutenção e Desenvolvimento da Educação Básica e de Valorização dos Profissionais da Educação, instituído pela E.C. n.º 53/2006 e regulamentado pela lei 11.494/2007.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (1999, 2, '3.5.2.2.4.00.00.00.00.00', 'TRANSFERÊNCIAS AO FUNDEB - INTER-OFSS - ESTADO ', 'Compreende as variações patrimoniais diminutivas decorrentes da transferência de recursos dos entes, incluindo a complementação da União, para a composição do Fundo de Manutenção e Desenvolvimento da Educação Básica e de Valorização dos Profissionais da Educação, instituído pela E.C. nº 53/2006 e regulamentado pela lei 11.494/2007. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2000, 2, '3.5.2.3.0.00.00.00.00.00', 'TRANSFERÊNCIAS VOLUNTÁRIAS', 'Compreende as variações patrimoniais diminutivas decorrentes de transferências voluntárias a União, estados, distrito federal, municípios, inclusive as entidades vinculadas, bem como a demais entidades, de bens e/ou valores.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2001, 2, '3.5.2.3.1.00.00.00.00.00', 'TRANSFERÊNCIAS VOLUNTÁRIAS - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais diminutivas decorrentes de transferências voluntárias a União, estados, distrito federal, municípios, inclusive as entidades vinculadas, de bens e/ou valores. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS). Por exemplo, empresa independente de um ente recebendo transferência de outro ente. (A empresa independente não pertence ao OFSS, mas pertence ao conceito de governamental).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2002, 2, '3.5.2.3.3.00.00.00.00.00', 'TRANSFERÊNCIAS VOLUNTÁRIAS - INTER OFSS - UNIÃO', 'Compreende as variações patrimoniais diminutivas decorrentes de transferências voluntárias de bens e/ou valores. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2003, 2, '3.5.2.3.4.00.00.00.00.00', 'TRANSFERÊNCIAS VOLUNTÁRIAS - INTER-OFSS - ESTADO ', 'Compreende as variações patrimoniais diminutivas decorrentes de transferências voluntárias de bens e/ou valores. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2240, 2, '5.2.2.1.2.00.00.00.00.00', 'DOTAÇÃO ADICIONAL POR TIPO DE CREDITO', 'Compreende o somatório dos valores monetários da dotação orçamentária decorrentes da abertura de créditos adicionais e seus cancelamentos.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2004, 2, '3.5.2.3.5.00.00.00.00.00', 'TRANSFERÊNCIAS VOLUNTÁRIAS - INTER-OFSS - MUNICÍPIO ', 'Compreende as variações patrimoniais diminutivas decorrentes de transferências voluntárias de bens e/ou valores. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2005, 2, '3.5.2.4.0.00.00.00.00.00', 'OUTRAS TRANSFERÊNCIAS', 'Compreende as variações patrimoniais diminutivas decorrentes demais transferências a União, estados, distrito federal, municípios, inclusive as entidades vinculadas, de bens e/ou valores.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2006, 2, '3.5.2.4.1.00.00.00.00.00', 'OUTRAS TRANSFERÊNCIAS - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais diminutivas decorrentes demais transferências a União, estados, distrito federal, municípios, inclusive as entidades vinculadas, de bens e/ou valores. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2007, 2, '3.5.2.4.3.00.00.00.00.00', 'OUTRAS TRANSFERÊNCIAS - INTER OFSS - UNIÃO', 'Compreende as variações patrimoniais diminutivas decorrentes demais transferências a União, estados, distrito federal, municípios, inclusive as entidades vinculadas, de bens e/ou valores. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2008, 2, '3.5.2.4.4.00.00.00.00.00', 'OUTRAS TRANSFERÊNCIAS - INTER OFSS - ESTADO', 'Compreende as variações patrimoniais diminutivas decorrentes demais transferências a União, estados, distrito federal, municípios, inclusive as entidades vinculadas, de bens e/ou valores. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2083, 2, '3.6.3.3.1.00.00.00.00.00', 'PERDAS INVOLUNTÁRIAS COM ESTOQUES - CONSOLIDAÇÃO', 'Compreende o desfazimento físico involuntário de bem do estoque, como o que resulta de sinistros como incêndio e inundações. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2009, 2, '3.5.2.4.5.00.00.00.00.00', 'OUTRAS TRANSFERÊNCIAS - INTER OFSS - MUNICÍPIO', 'Compreende as variações patrimoniais diminutivas decorrentes demais transferências a União, estados, distrito federal, municípios, inclusive as entidades vinculadas, de bens e/ou valores. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2010, 2, '3.5.3.0.0.00.00.00.00.00', 'TRANSFERÊNCIAS A INSTITUIÇÕES PRIVADAS', 'Compreende as variações patrimoniais diminutivas decorrentes das transferências financeiras a instituições privadas, inclusive de bens e valores.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2011, 2, '3.6.2.0.0.00.00.00.00.00', 'PERDAS COM ALIENAÇÃO', 'Compreende a perda com alienação de ativos, ou seja, quando o valor alienado do ativo e menor que o seu valor contábil, de maneira que a diferença compreende a perda.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2012, 2, '3.5.3.1.1.00.00.00.00.00', 'TRANSFERÊNCIAS A INSTITUIÇÕES PRIVADAS SEM FINS LUCRATIVOS - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais diminutivas decorrentes das transferências de bens e valores a instituições privadas sem fins lucrativos que não tenham vinculo com a administração pública, exemplo: ONGs,OSCIPS E OS. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2013, 2, '3.5.3.2.0.00.00.00.00.00', 'TRANSFERÊNCIAS A INSTITUIÇÕES PRIVADAS COM FINS LUCRATIVOS', 'Compreende as variações patrimoniais diminutivas decorrentes das transferências de bens e valores a instituições privadas com fins lucrativos que não tenham vínculos com administração pública.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2014, 2, '3.5.3.2.1.00.00.00.00.00', 'TRANSFERÊNCIAS A INSTITUIÇÕES PRIVADAS COM FINS LUCRATIVOS - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais diminutivas decorrentes das transferências de bens e valores a instituições privadas com fins lucrativos, que não tenham vínculos com a administração pública. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2015, 2, '3.5.4.0.0.00.00.00.00.00', 'TRANSFERÊNCIAS A INSTITUIÇÕES MULTIGOVERNAMENTAIS', 'Compreende as variações patrimoniais diminutivas decorrentes das transferências a instituições multigovernamentais, da quais o ente transferidor não participe.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2016, 2, '3.5.4.0.1.00.00.00.00.00', 'TRANSFERÊNCIAS A INSTITUIÇÕES MULTIGOVERNAMENTAIS - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais diminutivas decorrentes das transferências a instituições multigovernamentais, das quais o ente transferidor não participe. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2017, 2, '3.5.5.0.0.00.00.00.00.00', 'TRANSFERÊNCIAS A CONSÓRCIOS PÚBLICOS', 'Compreende as variações patrimoniais diminutivas decorrentes das transferências a consórcios públicos, dos quais o ente transferidor participe.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2018, 2, '3.5.5.0.1.00.00.00.00.00', 'TRANSFERÊNCIAS A CONSÓRCIOS PÚBLICOS - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais diminutivas decorrentes das transferências a consórcios públicos, dos quais o ente transferidor participe. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2019, 2, '3.5.6.0.0.00.00.00.00.00', 'TRANSFERÊNCIAS AO EXTERIOR', 'Compreende as variações patrimoniais diminutivas decorrentes de transferências a organismos e fundos internacionais, de governos estrangeiros e instituições privadas com ou sem fins lucrativos no exterior.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2020, 2, '3.5.6.0.1.00.00.00.00.00', 'TRANSFERÊNCIAS AO EXTERIOR - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais diminutivas decorrentes de transferências a organismos e fundos internacionais, de governos estrangeiros e instituições privadas com ou sem fins lucrativos no exterior. Compreende os valores de operações efetuadas entre uma unidade pertencente ao orçamento fiscal e da seguridade social (OFSS) com unidade que não pertença ao OFSS de ente público.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2021, 2, '3.5.7.0.0.00.00.00.00.00', 'EXECUÇÃO ORÇAMENTÁRIA DELEGADA', 'Compreende as variações patrimoniais diminutivas decorrentes de transferência de recursos financeiros, decorrentes de delegação ou descentralização aos Entes (União, Estados, Distrito Federal ou Municípios) ou Consórcios Públicos para execução de ações de responsabilidade exclusiva do delegante.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2022, 2, '3.5.7.1.0.00.00.00.00.00', 'EXECUÇÃO ORÇAMENTÁRIA DELEGADA A ENTES', 'Compreende as variações patrimoniais diminutivas decorrentes de transferência de recursos financeiros, decorrentes de delegação ou descentralização aos Entes (União, Estados, Distrito Federal, Municípios ou consórcios públicos) para execução de ações de responsabilidade exclusiva do delegante.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2023, 2, '3.5.7.1.3.00.00.00.00.00', 'EXECUÇÃO ORÇAMENTÁRIA DELEGADA A ENTES - INTER OFSS - UNIÃO', 'Compreende as variações patrimoniais diminutivas decorrentes de transferência de recursos financeiros, decorrentes de delegação ou descentralização aos Entes (União, Estados, Distrito Federal ou Municípios) para execução de ações de responsabilidade exclusiva do delegante. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2024, 2, '3.5.7.1.4.00.00.00.00.00', 'EXECUÇÃO ORÇAMENTÁRIA DELEGADA A ENTES - INTER OFSS - ESTADO', 'Compreende as variações patrimoniais diminutivas decorrentes de transferência de recursos financeiros, decorrentes de delegação ou descentralização aos Entes (União, Estados, Distrito Federal ou Municípios) para execução de ações de responsabilidade exclusiva do delegante. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2025, 2, '3.5.7.1.5.00.00.00.00.00', 'EXECUÇÃO ORÇAMENTÁRIA DELEGADA A ENTES - INTER OFSS - MUNICÍPIO', 'Compreende as variações patrimoniais diminutivas decorrentes de transferência de recursos financeiros, decorrentes de delegação ou descentralização aos Entes (União, Estados, Distrito Federal ou Municípios) para execução de ações de responsabilidade exclusiva do delegante. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2026, 2, '3.5.7.2.0.00.00.00.00.00', 'EXECUÇÃO ORÇAMENTÁRIA DELEGADA A CONSÓRCIOS', 'Compreende as variações patrimoniais diminutivas decorrentes de transferência de recursos financeiros, decorrentes de delegação ou descentralização aos Consórcios Públicos para execução de ações de responsabilidade exclusiva do delegante.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2084, 2, '3.6.3.9.0.00.00.00.00.00', 'OUTRAS PERDAS INVOLUNTÁRIAS', 'Compreendem o desfazimento físico involuntário de outros bens, como as que resultam de sinistros como incêndio e inundações.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2027, 2, '3.5.7.2.1.00.00.00.00.00', 'EXECUÇÃO ORÇAMENTÁRIA DELEGADA A CONSÓRCIOS - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais diminutivas decorrentes de transferência de recursos financeiros, decorrentes de delegação ou descentralização aos Consórcios Públicos para execução de ações de responsabilidade exclusiva do delegante. Compreende os valores de operações efetuadas entre uma unidade pertencente ao orçamento fiscal e da seguridade social (OFSS) com unidade que não pertença ao OFSS de ente público.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2028, 2, '3.5.9.0.0.00.00.00.00.00', 'OUTRAS TRANSFERÊNCIAS E DELEGAÇÕES CONCEDIDAS', 'Compreende as variações patrimoniais diminutivas decorrentes de demais transferências e delegações concedidas não compreendidas nas contas anteriores. ', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2029, 2, '3.5.9.0.1.00.00.00.00.00', 'OUTRAS TRANSFERÊNCIAS CONCEDIDAS - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais diminutivas decorrentes de demais transferências concedidas não compreendidas nas contas anteriores. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2030, 2, '3.6.2.1.0.00.00.00.00.00', 'PERDAS COM ALIENAÇÃO DE INVESTIMENTOS', 'Compreende a perda com alienação de investimentos, ou seja, quando o valor alienado do ativo e menor que o seu valor contábil, de maneira que a diferença compreende a perda.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2031, 2, '3.6.0.0.0.00.00.00.00.00', 'DESVALORIZAÇÃO E PERDA DE ATIVOS E INCORPORAÇÃO DE PASSIVOS', 'Compreende a variação patrimonial diminutiva com desvalorização e perdas de ativos, nos casos de reavaliação, redução a valor recuperável, provisões para perdas, perdas com alienação e perdas involuntárias. Compreende também a variação patrimonial diminutiva com incorporação de passivo.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2032, 2, '3.6.1.0.0.00.00.00.00.00', 'REAVALIAÇÃO, REDUÇÃO A VALOR RECUPERÁVEL E AJUSTE PARA PERDAS', 'Compreende as variações patrimoniais diminutivas relativas a reavaliação, redução a valor recuperável e ajuste para perdas.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2033, 2, '3.6.1.1.0.00.00.00.00.00', 'REAVALIAÇÃO DE IMOBILIZADO', 'Compreende a variação patrimonial diminutiva relativa à adoção do valor de mercado ou de consenso entre as partes para bens do ativo imobilizado, quando esse for inferior ao valor liquido contábil.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2034, 2, '3.6.1.1.1.00.00.00.00.00', 'REAVALIAÇÃO DE IMOBILIZADO - CONSOLIDAÇÃO', 'Compreende a variação patrimonial diminutiva relativa à adoção do valor de mercado ou de consenso entre as partes para bens do ativo imobilizado, quando esse for inferior ao valor liquido contábil. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2035, 2, '3.6.1.1.1.01.00.00.00.00', 'REAVALIAÇÃO DE BENS MÓVEIS', 'Compreende a variação patrimonial diminutiva relativa à adoção do valor de mercado ou de consenso entre as partes para bens móveis, quando esse for inferior ao valor liquido contábil.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2036, 2, '3.6.1.1.1.02.00.00.00.00', 'REAVALIAÇÃO DE BENS IMÓVEIS', 'Compreende a variação patrimonial diminutiva relativa à adoção do valor de mercado ou de consenso entre as partes para bens imóveis, quando esse for inferior ao valor liquido contábil.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2037, 2, '3.6.1.2.0.00.00.00.00.00', 'REAVALIAÇÃO DE INTANGÍVEIS', 'Compreende a variação patrimonial diminutiva relativa à adoção do valor de mercado ou de consenso entre as partes para ativos intangíveis, quando esse for inferior ao valor liquido contábil.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2038, 2, '3.6.1.2.1.00.00.00.00.00', 'REAVALIAÇÃO DE INTANGÍVEIS - CONSOLIDAÇÃO', 'Compreende a variação patrimonial diminutiva relativa à adoção do valor de mercado ou de consenso entre as partes para ativos intangíveis, quando esse for inferior ao valor líquido contábil. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2039, 2, '3.6.1.3.0.00.00.00.00.00', 'REAVALIAÇÃO DE OUTROS ATIVOS', 'Compreende a variação patrimonial diminutiva relativa à adoção do valor de mercado ou de consenso entre as partes para outros ativos, quando esse for inferior ao valor liquido contábil.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2040, 2, '3.6.1.3.1.00.00.00.00.00', 'REAVALIAÇÃO DE OUTROS ATIVOS - CONSOLIDAÇÃO', 'Compreende a variação patrimonial diminutiva relativa à adoção do valor de mercado ou de consenso entre as partes para outros ativos, quando esse for inferior ao valor liquido contábil. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2041, 2, '3.6.1.4.0.00.00.00.00.00', 'REDUÇÃO A VALOR RECUPERÁVEL DE INVESTIMENTOS', 'Compreende a variação patrimonial diminutiva com a redução nos benefícios econômicos futuros ou no potencial de serviços de um investimento, que reflete um declínio na sua utilidade além do reconhecimento sistemático por meio da depreciação.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2042, 2, '3.6.1.4.1.00.00.00.00.00', 'REDUÇÃO A VALOR RECUPERÁVEL DE INVESTIMENTOS - CONSOLIDAÇÃO', 'Compreende a variação patrimonial diminutiva com a redução nos benefícios econômicos futuros ou no potencial de serviços de um investimento, que reflete um declínio na sua utilidade além do reconhecimento sistemático por meio da depreciação.Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2043, 2, '3.6.1.4.2.00.00.00.00.00', 'REDUÇÃO A VALOR RECUPERÁVEL DE INVESTIMENTOS - INTRA OFSS', 'Compreende a variação patrimonial diminutiva com a redução nos benefícios econômicos futuros ou no potencial de serviços de um investimento, que reflete um declínio na sua utilidade além do reconhecimento sistemático por meio da depreciação. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do ente.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2044, 2, '3.6.1.4.3.00.00.00.00.00', 'REDUÇÃO A VALOR RECUPERÁVEL DE INVESTIMENTOS - INTER OFSS - UNIÃO', 'Compreende a variação patrimonial diminutiva com a redução nos benefícios econômicos futuros ou no potencial de serviços de um investimento, que reflete um declínio na sua utilidade além do reconhecimento sistemático por meio da depreciação. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2045, 2, '3.6.1.4.4.00.00.00.00.00', 'REDUÇÃO A VALOR RECUPERÁVEL DE INVESTIMENTOS - INTER OFSS - ESTADO', 'Compreende a variação patrimonial diminutiva com a redução nos benefícios econômicos futuros ou no potencial de serviços de um investimento, que reflete um declínio na sua utilidade além do reconhecimento sistemático por meio da depreciação.Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2086, 2, '3.6.4.0.0.00.00.00.00.00', 'INCORPORAÇÃO DE PASSIVOS', 'Compreende a contrapartida de incorporação de passivo, como nos casos de extinção e fusão de entidades ou de restos a pagar com prescrição interrompida.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2046, 2, '3.6.1.4.5.00.00.00.00.00', 'REDUÇÃO A VALOR RECUPERÁVEL DE INVESTIMENTOS - INTER OFSS - MUNICÍPIO', 'Compreende a variação patrimonial diminutiva com a redução nos benefícios econômicos futuros ou no potencial de serviços de um investimento, que reflete um declínio na sua utilidade além do reconhecimento sistemático por meio da depreciação.Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2047, 2, '3.6.1.5.0.00.00.00.00.00', 'REDUÇÃO A VALOR RECUPERÁVEL DE IMOBILIZADO', 'Compreende a variação patrimonial diminutiva com a redução nos benefícios econômicos futuros ou no potencial de serviços de um ativo imobilizado, que reflete um declínio na sua utilidade além do reconhecimento sistemático por meio da depreciação.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2048, 2, '3.6.1.5.1.00.00.00.00.00', 'REDUÇÃO A VALOR RECUPERÁVEL DE IMOBILIZADO - CONSOLIDAÇÃO', 'Compreende a variação patrimonial diminutiva com a redução nos benefícios econômicos futuros ou no potencial de serviços de um ativo imobilizado, que reflete um declínio na sua utilidade além do reconhecimento sistemático por meio da depreciação. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2049, 2, '3.6.1.5.1.01.00.00.00.00', 'REDUÇÃO A VALOR RECUPERÁVEL DE BENS MÓVEIS', 'Compreende a variação patrimonial diminutiva com a redução nos benefícios econômicos futuros ou no potencial de serviços de bens móveis, que reflete um declínio na sua utilidade além do reconhecimento sistemático por meio da depreciação.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2050, 2, '3.8.0.0.0.00.00.00.00.00', 'CUSTO DAS MERCADORIAS VENDIDAS, DOS PRODUTOS VENDIDOS E DOS SERVIÇOS PRESTADOS', 'Compreende as variações patrimoniais diminutivas relativas aos custos das mercadorias vendidas, dos produtos vendidos e dos serviços prestados.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2051, 2, '3.6.1.5.1.02.00.00.00.00', 'REDUÇÃO A VALOR RECUPERÁVEL DE BENS IMÓVEIS', 'Compreende a variação patrimonial diminutiva com a redução nos benefícios econômicos futuros ou no potencial de serviços de bens imóveis, que reflete um declínio na sua utilidade além do reconhecimento sistemático por meio da depreciação.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2052, 2, '3.6.1.6.0.00.00.00.00.00', 'REDUÇÃO A VALOR RECUPERÁVEL DE INTANGÍVEIS', 'Compreende a variação patrimonial diminutiva com a redução nos benefícios econômicos futuros ou no potencial de serviços de um ativo intangível, que reflete um declínio na sua utilidade além do reconhecimento sistemático por meio da depreciação.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2053, 2, '3.6.1.6.1.00.00.00.00.00', 'REDUÇÃO A VALOR RECUPERÁVEL DE INTANGÍVEIS - CONSOLIDAÇÃO', 'Compreende a variação patrimonial diminutiva com a redução nos benefícios econômicos futuros ou no potencial de serviços de um ativo intangível, que reflete um declínio na sua utilidade além do reconhecimento sistemático por meio da depreciação. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2054, 2, '3.6.1.7.0.00.00.00.00.00', 'VARIAÇÃO PATRIMONIAL DIMINUTIVA COM AJUSTE DE PERDAS DE CRÉDITOS E DE INVESTIMENTOS E APLICAÇÕES TEMPORÁRIOS', 'Compreende a variação patrimonial diminutiva com ajuste de perdas de créditos por inadimplência ou outros fatores que impossibilitam o recebimento de créditos. Por exemplo, a variação patrimonial diminutiva com ajuste para créditos de liquidação duvidosa e ajuste para créditos da dívida ativa. Compreende também a variação patrimonial diminutiva com ajuste de perdas em investimentos e aplicações temporários, não destinados à negociação e que não façam parte das atividades operacionais da entidade, resgatáveis no curto e no longo prazo.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2268, 2, '7.1.1.1.1.02.00.00.00.00', 'GARANTIAS RECEBIDAS NO EXTERIOR', 'Compreende o valor recebido de compromisso de adimplência de obrigação financeira ou contratual, no exterior.', 1, false, 0, ' ');
insert into contabilidade.planocontadetalhe values (2055, 2, '3.6.1.7.1.00.00.00.00.00', 'VARIAÇÃO PATRIMONIAL DIMINUTIVA COM AJUSTE DE PERDAS DE CRÉDITOS E DE INVESTIMENTOS E APLICAÇÕES TEMPORÁRIOS - CONSOLIDAÇÃO', 'Compreende a variação patrimonial diminutiva com ajuste de perdas de créditos por inadimplência ou outros fatores que impossibilitam o recebimento de créditos. Compreende também a variação patrimonial diminutiva com ajuste de perdas em investimentos e aplicações temporários, não destinados à negociação e que não façam parte das atividades operacionais da entidade, resgatáveis no curto e no longo prazo. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2056, 2, '3.6.1.7.1.05.00.00.00.00', 'AJUSTE PARA PERDAS EM DÍVIDA ATIVA TRIBUTÁRIA', 'Compreende a variação patrimonial diminutiva com ajuste para perdas em créditos da dívida ativa tributária.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2057, 2, '3.6.1.7.1.07.00.00.00.00', 'AJUSTE PARA PERDAS EM INVESTIMENTOS E APLICAÇÕES TEMPORÁRIOS', 'Compreende a variação patrimonial diminutiva com ajuste de perdas em investimentos e aplicações temporários, não destinados à negociação e que não façam parte das atividades operacionais da entidade, resgatáveis no curto e no longo prazo.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2058, 2, '3.6.1.7.2.00.00.00.00.00', 'VARIAÇÃO PATRIMONIAL DIMINUTIVA COM AJUSTE DE PERDAS DE CRÉDITOS E DE INVESTIMENTOS E APLICAÇÕES TEMPORÁRIOS - INTRA OFSS', 'Compreende a variação patrimonial diminutiva com ajuste de perdas de créditos por inadimplência ou outros fatores que impossibilitam o recebimento de créditos.  Compreende também a variação patrimonial diminutiva com ajuste de perdas em investimentos e aplicações temporários, não destinados à negociação e que não façam parte das atividades operacionais da entidade, resgatáveis no curto e no longo prazo. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do ente.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2059, 2, '3.6.1.7.2.05.00.00.00.00', 'AJUSTE PARA PERDAS EM DÍVIDA ATIVA TRIBUTÁRIA', 'Compreende a variação patrimonial diminutiva com ajuste para perdas em créditos da dívida ativa tributária.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2060, 2, '3.6.1.7.3.00.00.00.00.00', 'VARIAÇÃO PATRIMONIAL DIMINUTIVA COM AJUSTE DE PERDAS DE CRÉDITOS E DE INVESTIMENTOS E APLICAÇÕES TEMPORÁRIOS - INTER OFSS - UNIÃO', 'Compreende a variação patrimonial diminutiva com ajuste de perdas de créditos por inadimplência ou outros fatores que impossibilitam o recebimento de créditos.  Compreende também a variação patrimonial diminutiva com ajuste de perdas em investimentos e aplicações temporários, não destinados à negociação e que não façam parte das atividades operacionais da entidade, resgatáveis no curto e no longo prazo. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2061, 2, '3.6.1.7.3.05.00.00.00.00', 'AJUSTE PARA PERDAS EM DÍVIDA ATIVA TRIBUTÁRIA', 'Compreende a variação patrimonial diminutiva com ajuste para perdas em créditos da dívida ativa tributária.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2085, 2, '3.6.3.9.1.00.00.00.00.00', 'OUTRAS PERDAS INVOLUNTÁRIAS - CONSOLIDAÇÃO', 'Compreende o desfazimento físico involuntário de outros bens, como as que resultam de sinistros como incêndio e inundações. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2062, 2, '3.6.1.7.4.00.00.00.00.00', 'VARIAÇÃO PATRIMONIAL DIMINUTIVA COM AJUSTE DE PERDAS DE CRÉDITOS E DE INVESTIMENTOS E APLICAÇÕES TEMPORÁRIOS - INTER OFSS - ESTADO', 'Compreende a variação patrimonial diminutiva com ajuste de perdas de créditos por inadimplência ou outros fatores que impossibilitam o recebimento de créditos.  Compreende também a variação patrimonial diminutiva com ajuste de perdas em investimentos e aplicações temporários, não destinados à negociação e que não façam parte das atividades operacionais da entidade, resgatáveis no curto e no longo prazo. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2063, 2, '3.6.1.7.4.05.00.00.00.00', 'AJUSTE PARA PERDAS EM DÍVIDA ATIVA TRIBUTÁRIA', 'Compreende a variação patrimonial diminutiva com ajuste para perdas em créditos da dívida ativa tributária.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2064, 2, '3.6.1.7.5.00.00.00.00.00', 'VARIAÇÃO PATRIMONIAL DIMINUTIVA COM AJUSTE DE PERDAS DE CRÉDITOS E DE INVESTIMENTOS E APLICAÇÕES TEMPORÁRIOS - INTER OFSS - MUNICÍPIO', 'Compreende a variação patrimonial diminutiva com ajuste de perdas de créditos por inadimplência ou outros fatores que impossibilitam o recebimento de créditos.  Compreende também a variação patrimonial diminutiva com ajuste de perdas em investimentos e aplicações temporários, não destinados à negociação e que não façam parte das atividades operacionais da entidade, resgatáveis no curto e no longo prazo. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2065, 2, '3.6.1.7.5.05.00.00.00.00', 'AJUSTE PARA PERDAS EM DÍVIDA ATIVA TRIBUTÁRIA', 'Compreende a variação patrimonial diminutiva com ajuste para perdas em créditos da dívida ativa tributária.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2066, 2, '3.6.1.8.0.00.00.00.00.00', 'VARIAÇÃO PATRIMONIAL DIMINUTIVA COM AJUSTE DE PERDAS DE ESTOQUES', 'Compreende a variação patrimonial diminutiva com ajuste para redução a valor de mercado de estoques.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2067, 2, '3.6.1.8.1.00.00.00.00.00', 'VARIAÇÃO PATRIMONIAL DIMINUTIVA COM AJUSTE DE PERDAS DE ESTOQUES - CONSOLIDAÇÃO', 'Compreende a variação patrimonial diminutiva com ajuste para perdas de estoques. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2068, 2, '3.6.2.1.1.00.00.00.00.00', 'PERDAS COM ALIENAÇÃO DE INVESTIMENTOS - CONSOLIDAÇÃO', 'Compreende a perda com alienação de investimentos, ou seja, quando o valor alienado do ativo e menor que o seu valor contábil, de maneira que a diferença compreende a perda. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2069, 2, '3.6.2.2.0.00.00.00.00.00', 'PERDAS COM ALIENAÇÃO DE IMOBILIZADO', 'Compreende a perda com alienação de ativos imobilizados, ou seja, quando o valor alienado do ativo e menor que o seu valor contábil, de maneira que a diferença compreende a perda.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2070, 2, '3.6.2.2.1.00.00.00.00.00', 'PERDAS COM ALIENAÇÃO DE IMOBILIZADO - CONSOLIDAÇÃO', 'Compreende a perda com alienação de ativos imobilizados, ou seja, quando o valor alienado do ativo e menor que o seu valor contábil, de maneira que a diferença compreende a perda. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2072, 2, '3.6.2.3.0.00.00.00.00.00', 'PERDAS COM ALIENAÇÃO DE INTANGÍVEIS', 'Compreende a perda com alienação de ativos intangíveis, ou seja, quando o valor alienado do ativo e menor que o seu valor contábil, de maneira que a diferença compreende a perda.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2073, 2, '3.6.2.3.1.00.00.00.00.00', 'PERDAS COM ALIENAÇÃO DE INTANGÍVEIS - CONSOLIDAÇÃO', 'Compreende a perda com alienação de ativos intangíveis, ou seja, quando o valor alienado do ativo e menor que o seu valor contábil, de maneira que a diferença compreende a perda. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2074, 2, '3.6.2.9.0.00.00.00.00.00', 'PERDAS COM ALIENAÇÃO DE DEMAIS ATIVOS', 'Compreende a perda com alienação de demais ativos, não discriminados nas categorias anteriores, incluindo os investimentos do RPPS, quando o valor alienado do ativo e menor que o seu valor contábil, de maneira que a diferença compreende a perda.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2075, 2, '3.6.2.9.1.00.00.00.00.00', 'PERDAS COM ALIENAÇÃO DE DEMAIS ATIVOS - CONSOLIDAÇÃO', 'Compreende a perda com alienação de demais ativos, não discriminados nas categorias anteriores, incluindo os investimentos do RPPS, quando o valor alienado do ativo e menor que o seu valor contábil, de maneira que a diferença compreende a perda. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2076, 2, '3.6.3.0.0.00.00.00.00.00', 'PERDAS INVOLUNTÁRIAS', 'Compreendem o desfazimento físico involuntário do bem, como o que resulta de sinistros como incêndio e inundações.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2077, 2, '3.6.3.1.0.00.00.00.00.00', 'PERDAS INVOLUNTÁRIAS COM IMOBILIZADO', 'Compreendem o desfazimento físico involuntário de bem do ativo imobilizado, como o que resulta de sinistros como incêndio e inundações.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2078, 2, '3.6.3.1.1.00.00.00.00.00', 'PERDAS INVOLUNTÁRIAS COM IMOBILIZADO - CONSOLIDAÇÃO', 'Compreende o desfazimento físico involuntário de bem do ativo imobilizado, como o que resulta de sinistros como incêndio e inundações. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2079, 2, '3.6.3.1.1.01.00.00.00.00', 'PERDAS INVOLUNTÁRIAS DE BENS MOVEIS', 'Compreende a variação patrimonial diminutiva com perdas involuntárias de bens móveis.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2080, 2, '3.6.3.2.0.00.00.00.00.00', 'PERDAS INVOLUNTÁRIAS COM INTANGÍVEIS', 'Compreendem o desfazimento físico involuntário de bem do ativo intangível, como o que resulta de sinistros como incêndio e inundações.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2081, 2, '3.6.3.2.1.00.00.00.00.00', 'PERDAS INVOLUNTÁRIAS COM INTANGÍVEIS - CONSOLIDAÇÃO', 'Compreende o desfazimento físico involuntário de bem do ativo intangível, como o que resulta de sinistros como incêndio e inundações. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2082, 2, '3.6.3.3.0.00.00.00.00.00', 'PERDAS INVOLUNTÁRIAS COM ESTOQUES', 'Compreendem o desfazimento físico involuntário de bem do estoque, como o que resulta de sinistros como incêndio e inundações.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3381, 2, '8.1.2.1.1.01.15.00.00.00', 'CAUÇÕES EXECUTADA', 'Registra o valor recebido das garantias por cauções no país.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (2087, 2, '3.6.4.0.1.00.00.00.00.00', 'INCORPORAÇÃO DE PASSIVOS - CONSOLIDAÇÃO', 'Compreende a variação patrimonial diminutiva com incorporação de passivo, como nos casos de extinção e fusão de entidades ou de restos a pagar com prescrição interrompida. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2088, 2, '3.6.5.0.0.00.00.00.00.00', 'DESINCORPORAÇÃO DE ATIVOS', 'Compreende a contrapartida de desincorporação de ativo,  como nos casos de baixa de ativos inservíveis ou outros eventos sob controle da entidade.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2089, 2, '3.6.5.0.1.00.00.00.00.00', 'DESINCORPORAÇÃO DE ATIVOS - CONSOLIDAÇÃO', 'Compreende a contrapartida de desincorporação de ativo,  como nos casos de baixa de ativos inservíveis ou de desfalque de bens públicos ou outros eventos sob controle da entidade. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2090, 2, '3.6.5.0.1.01.00.00.00.00', 'DESINCORPORAÇÃO DE DÍVIDA ATIVA TRIBUTÁRIA', 'Compreende a contrapartida de desincorporação da dívida ativa tributária em virtude de cancelamento, anistia, remissão, adjudicação, anulação, prescrição, extinção, desconto ou abatimento.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2091, 2, '3.7.0.0.0.00.00.00.00.00', 'TRIBUTÁRIAS', 'Compreendem as variações patrimoniais diminutivas relativas aos impostos, taxas, contribuições de melhoria, contribuições sociais, contribuições econômicas e contribuições especiais.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2092, 2, '3.8.1.0.0.00.00.00.00.00', 'CUSTO DE MERCADORIAS VENDIDAS', 'Compreende as variações patrimoniais diminutivas relativas aos custos apropriados às mercadorias, sendo registradas apenas no momento da venda destas.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2093, 2, '3.7.1.0.0.00.00.00.00.00', 'IMPOSTOS, TAXAS E CONTRIBUIÇÕES DE MELHORIA', 'Compreendem as variações patrimoniais diminutivas relativas às obrigações relativas às prestações pecuniárias compulsórias, em moeda ou cujo valor nela possa se exprimir, que não constitua sanção de ato ilícito, instituída em lei e cobrada mediante atividade vinculada. Como: impostos, taxas e contribuições de melhoria.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2094, 2, '3.7.1.1.0.00.00.00.00.00', 'IMPOSTOS', 'Compreende as variações patrimoniais diminutivas com impostos, apurados no período de competência, e vinculados à atividade administrativa do contribuinte, definidos no CTN.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2095, 2, '3.7.1.1.1.00.00.00.00.00', 'IMPOSTOS- CONSOLIDAÇÃO', 'Compreende as variações patrimoniais diminutivas com impostos, apurados no período de competência e vinculados atividade administrativa do contribuinte, definidos no CTN. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2096, 2, '3.7.1.2.0.00.00.00.00.00', 'TAXAS', 'Compreende as variações patrimoniais diminutivas com taxas cobradas pela União, Estados, Distrito Federal ou Municípios, no âmbito de suas respectivas contribuições, decorrentes da contraprestação de serviços públicos ao contribuinte postos a sua disposição, inclusive o exercício de poder de policia.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2153, 2, '3.9.4.2.0.00.00.00.00.00', 'INCENTIVOS A CIÊNCIA', 'Compreende o apoio financeiro concedido a pesquisadores, individual ou coletivamente, exceto na condição de estudante, no desenvolvimento de pesquisas cientificas e tecnológicas, nas suas mais diversas modalidades.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2097, 2, '3.7.1.2.1.00.00.00.00.00', 'TAXAS - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais diminutivas com taxas cobradas pela União, Estados, Distrito Federal ou Municípios, no âmbito de suas respectivas contribuições, decorrentes da contraprestação de serviços públicos ao contribuinte postos a sua disposição, inclusive o exercício de poder de policia. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2098, 2, '3.7.1.3.0.00.00.00.00.00', 'CONTRIBUIÇÕES DE MELHORIA', 'Compreende as variações patrimoniais diminutivas com tributo cuja obrigação tem por fato gerador um beneficio especial auferido pelo contribuinte que por consequência promove uma valorização imobiliária e patrimonial decorrente de obra pública de competência da União, Estados, Distrito Federal ou Municípios , amparadas em lei e limitadas ao total da despesa pública realizada.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2099, 2, '3.7.1.3.1.00.00.00.00.00', 'CONTRIBUIÇÕES DE MELHORIA - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais diminutivas com titulo cuja obrigação tem por fato gerador um beneficio especial auferido pelo contribuinte que por consequência promove uma valorização imobiliária e patrimonial decorrente de obra pública de competência da União, Estados, Distrito Federal ou municípios, amparadas em lei e limitadas ao total da despesa pública realizada. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2100, 2, '3.7.2.0.0.00.00.00.00.00', 'CONTRIBUIÇÕES', 'Compreende as variações patrimoniais diminutivas com contribuições sociais, econômicas e outras, decorrentes da intervenção do estado (União, Estados, Distrito Federal e Municípios) no domínio econômico e de interesse da categoria de profissionais.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2101, 2, '3.7.2.1.0.00.00.00.00.00', 'CONTRIBUIÇÕES SOCIAIS', 'Compreende a variação patrimonial diminutiva com contribuições sociais constituídas por ordem social e profissional, instituídas pelo estado, entre elas o PIS/PASEP, CSLL e COFINS, etc.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2102, 2, '3.9.6.2.1.00.00.00.00.00', 'PARTICIPAÇÕES DE EMPREGADOS - CONSOLIDAÇÃO', 'Compreende as participações de empregados incidentes sobre o lucro após imposto de renda e contribuição social sobre o lucro liquido. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2103, 2, '3.7.2.1.1.00.00.00.00.00', 'CONTRIBUIÇÕES SOCIAIS - CONSOLIDAÇÃO', 'Compreende a variação patrimonial diminutiva com contribuições sociais constituídas por ordem social e profissional, instituídas pelo Estado, entre elas o PIS/PASEP, CSLL e COFINS, etc. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2104, 2, '3.7.2.1.2.00.00.00.00.00', 'CONTRIBUIÇÕES SOCIAIS - INTRA OFSS', 'Compreende a variação patrimonial diminutiva com contribuições sociais constituídas por ordem social e profissional, instituídas pelo Estado, entre elas o PIS/PASEP, CSLL e COFINS, etc. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do ente.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2105, 2, '3.7.2.1.3.00.00.00.00.00', 'CONTRIBUIÇÕES SOCIAIS - INTER OFSS - UNIÃO', 'Compreende a variação patrimonial diminutiva com contribuições sociais constituídas por ordem social e profissional, instituídas pelo Estado, entre elas o PIS/PASEP, CSLL e COFINS, etc. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2230, 2, '5.1.1.0.0.00.00.00.00.00', 'PPA - APROVADO', 'Compreende o somatório dos valores monetários previstos para a execução dos programas e ações (projetos, atividades e operações especiais) estabelecidos no plano plurianual.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2106, 2, '3.7.2.1.4.00.00.00.00.00', 'CONTRIBUIÇÕES SOCIAIS - INTER OFSS - ESTADO', 'Compreende a variação patrimonial diminutiva com contribuições sociais constituídas por ordem social e profissional, instituídas pelo Estado, entre elas o PIS/PASEP, CSLL e COFINS, etc. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2107, 2, '3.7.2.1.5.00.00.00.00.00', 'CONTRIBUIÇÕES SOCIAIS - INTER OFSS - MUNICÍPIO', 'Compreende a variação patrimonial diminutiva com contribuições sociais constituídas por ordem social e profissional, instituídas pelo Estado, entre elas o PIS/PASEP,CSLL e COFINS, etc. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2108, 2, '3.7.2.2.0.00.00.00.00.00', 'CONTRIBUIÇÕES DE INTERVENÇÃO NO DOMÍNIO ECONÔMICO', 'Compreende a variação patrimonial diminutiva com contribuições de intervenção no domínio econômico.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2109, 2, '3.7.2.2.1.00.00.00.00.00', 'CONTRIBUIÇÕES DE INTERVENÇÃO NO DOMÍNIO ECONÔMICO - CONSOLIDAÇÃO', 'Compreende a variação patrimonial diminutiva com contribuições de intervenção no domínio econômico. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2110, 2, '3.7.2.3.0.00.00.00.00.00', 'CONTRIBUIÇÃO PARA O CUSTEIO DO SERVIÇO DE ILUMINAÇÃO PÚBLICA - COSIP', 'Compreende o valor da variação patrimonial diminutiva com a contribuição para custeio do serviço de iluminação pública (art.149-a da C.F.)', 1, false, 0, 'N');
