insert into contabilidade.planocontadetalhe values (2150, 2, '3.9.4.0.0.00.00.00.00.00', 'INCENTIVOS', 'Compreende os incentivos financeiros concedidos relativos à educação, a ciência e a cultura.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2151, 2, '3.9.4.1.0.00.00.00.00.00', 'INCENTIVOS A EDUCAÇÃO', 'Compreende a ajuda financeira concedida pelo estado a estudantes comprovadamente carentes, e concessão de auxílio para o desenvolvimento de estudos e pesquisas de natureza cientifica realizadas por pessoas físicas na condição de estudante.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2152, 2, '3.9.4.1.1.00.00.00.00.00', 'INCENTIVOS A EDUCAÇÃO - CONSOLIDAÇÃO', 'Compreende a ajuda financeira concedida pelo estado a estudantes comprovadamente carentes, e concessão de auxílio para o desenvolvimento de estudos e pesquisas de natureza cientifica realizadas por pessoas físicas na condição de estudante. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2326, 2, '1.1.2.9.1.01.70.00.00.00', '(-) PERDAS ESTIMADAS EM CRÉDITOS TRIBUTÁRIOS PARCELADOS', 'Registra o ajuste para perdas estimadas com o não recebimento de créditos tributários parcelados.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2154, 2, '3.9.4.2.1.00.00.00.00.00', 'INCENTIVOS A CIÊNCIA - CONSOLIDAÇÃO', 'Compreende o apoio financeiro concedido a pesquisadores, individual ou coletivamente, exceto na condição de estudante, no desenvolvimento de pesquisas cientificas e tecnológicas, nas suas mais diversas modalidades. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
