insert into contabilidade.planocontadetalhe values (2160, 2, '3.9.4.9.1.00.00.00.00.00', 'OUTROS INCENTIVOS - CONSOLIDAÇÃO', 'Compreende os incentivos financeiros concedidos. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2161, 2, '3.9.5.0.0.00.00.00.00.00', 'SUBVENÇÕES ECONÔMICAS', 'Compreende a variação patrimonial diminutiva com o pagamento de subvenções econômicas, a qualquer título, autorizadas em leis específicas, tais como: ajuda financeira a entidades privadas com fins lucrativos; concessão de bonificações a produtores, distribuidores e vendedores; cobertura, direta ou indireta, de parcela de encargos de empréstimos e financiamentos e dos custos de aquisição, de produção, de escoamento, de distribuição, de venda e de manutenção de bens, produtos e serviços em geral; e, ainda, outras operações com características semelhantes.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2162, 2, '3.9.5.0.1.00.00.00.00.00', 'SUBVENÇÕES ECONÔMICAS - CONSOLIDAÇÃO', 'Compreende a variação patrimonial diminutiva com o pagamento de subvenções econômicas, a qualquer título, autorizadas em leis específicas, tais como: ajuda financeira a entidades privadas com fins lucrativos; concessão de bonificações a produtores, distribuidores e vendedores; cobertura, direta ou indireta, de parcela de encargos de empréstimos e financiamentos e dos custos de aquisição, de produção, de escoamento, de distribuição, de venda e de manutenção de bens, produtos e serviços em geral; e, ainda, outras operações com características semelhantes. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2163, 2, '3.9.6.0.0.00.00.00.00.00', 'PARTICIPAÇÕES E CONTRIBUIÇÕES', 'Compreende as participações de terceiros nos lucros, não relativas ao investimento dos acionistas, tais como: participações de debêntures, empregados, administradores e partes beneficiárias, mesmo na forma de instrumentos financeiros, além da contribuição a instituições ou fundos de assistência ou previdência de empregados.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2164, 2, '3.9.6.1.0.00.00.00.00.00', 'PARTICIPAÇÕES DE DEBÊNTURES', 'Compreende as participações de debêntures incidentes sobre o lucro após imposto de renda e contribuição social sobre o lucro liquido.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2165, 2, '3.9.6.1.1.00.00.00.00.00', 'PARTICIPAÇÕES DE DEBÊNTURES - CONSOLIDAÇÃO', 'Compreende as participações de debêntures incidentes sobre o lucro após imposto de renda e contribuição social sobre o lucro liquido. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2166, 2, '3.9.6.2.0.00.00.00.00.00', 'PARTICIPAÇÕES DE EMPREGADOS', 'Compreende as participações de empregados incidentes sobre o lucro após imposto de renda e contribuição social sobre o lucro liquido.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2232, 2, '5.1.2.1.0.00.00.00.00.00', 'PROJETO INICIAL DA LEI ORCAMENTARIA  - RECEITA', 'Compreende o somatório dos valores monetários constantes do projeto da lei orçamentaria anual remetido pelo poder executivo ao poder legislativo para apreciação e aprovação.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2167, 2, '3.9.6.3.1.00.00.00.00.00', 'PARTICIPAÇÕES DE ADMINISTRADORES - CONSOLIDAÇÃO', 'Compreende as participações de administradores incidentes sobre o lucro após imposto de renda e contribuição social sobre o lucro liquido. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2168, 2, '3.9.6.4.0.00.00.00.00.00', 'PARTICIPAÇÕES DE PARTES BENEFICIARIAS', 'Compreende as participações de partes beneficiarias incidentes sobre o lucro após imposto de renda e contribuição social sobre o lucro liquido.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2169, 2, '3.9.6.4.1.00.00.00.00.00', 'PARTICIPAÇÕES DE PARTES BENEFICIARIAS - CONSOLIDAÇÃO', 'Compreende as participações de partes beneficiarias incidentes sobre o lucro após imposto de renda e contribuição social sobre o lucro liquido. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2170, 2, '3.9.6.5.0.00.00.00.00.00', 'PARTICIPAÇÕES DE INSTITUIÇÕES OU FUNDOS DE ASSISTÊNCIA OU PREVIDÊNCIA DE EMPREGADOS', 'Compreende as contribuições da empresa, incidentes sobre o lucro após imposto de renda e contribuição social sobre o lucro liquido, para instituições ou fundos de assistência ou previdência de empregados.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2171, 2, '3.9.6.5.1.00.00.00.00.00', 'PARTICIPAÇÕES DE INSTITUIÇÕES OU FUNDOS DE ASSISTÊNCIA OU PREVIDÊNCIA DE EMPREGADOS - CONSOLIDAÇÃO', 'Compreende as contribuições da empresa, incidentes sobre o lucro após imposto de renda e contribuição social sobre o lucro líquido, para instituições ou fundos de assistência ou previdência de empregados. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2172, 2, '3.9.7.0.0.00.00.00.00.00', 'VPD DE CONSTITUIÇÃO DE PROVISÕES', 'Compreende a constituição de provisões, entendidas como os passivos de vencimento ou montante incertos. Não se confundem com os passivos derivados de apropriação por competência, como férias e décimo - terceiro salário.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2173, 2, '3.9.7.1.0.00.00.00.00.00', 'VPD DE PROVISÃO PARA RISCOS TRABALHISTAS', 'Compreende os passivos de prazo ou de valor incertos, relacionados a pagamento de reclamações trabalhistas.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2174, 2, '3.9.7.1.1.00.00.00.00.00', 'VPD DE PROVISÃO PARA RISCOS TRABALHISTAS - CONSOLIDAÇÃO', 'Compreende os passivos de prazo ou de valor incertos, relacionados a pagamento de reclamações trabalhistas. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2175, 2, '3.9.7.2.0.00.00.00.00.00', ' VPD DE PROVISÕES MATEMÁTICAS PREVIDÊNCIÁRIAS A LONGO PRAZO', 'Compreende a constituição de provisões de passivos de prazo ou de valor incertos, relacionados a futuros benefícios previdenciários a serem pagos aos contribuintes.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2176, 2, '3.9.7.2.1.00.00.00.00.00', ' VPD DE PROVISÕES MATEMÁTICAS PREVIDÊNCIÁRIAS A LONGO PRAZO - CONSOLIDAÇÃO', 'Compreende a constituição de provisões de passivos de prazo ou de valor incertos, relacionados a futuros benefícios previdenciários a serem pagos aos contribuintes. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2177, 2, '3.9.7.3.0.00.00.00.00.00', 'VPD DE PROVISÕES PARA RISCOS FISCAIS', 'Compreende a constituição de provisões de passivos de prazo ou de valor incertos, relacionados ao pagamento de autuações fiscais.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2178, 2, '3.9.7.3.1.00.00.00.00.00', 'VPD DE PROVISÕES PARA RISCOS FISCAIS - CONSOLIDAÇÃO', 'Compreende a constituição de provisões de passivos de prazo ou de valor incertos, relacionados ao pagamento de autuações fiscais. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2179, 2, '3.9.7.4.0.00.00.00.00.00', 'VPD DE PROVISÃO PARA RISCOS CÍVEIS', 'Compreende a constituição de provisões de passivos de prazo ou de valor incertos, relacionados a pagamento de indenizações a fornecedores e clientes.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2180, 2, '3.9.7.4.1.00.00.00.00.00', 'VPD DE PROVISÃO PARA RISCOS CÍVEIS - CONSOLIDAÇÃO', 'Compreende a constituição de provisões de passivos de prazo ou de valor incertos, relacionados a pagamentos de indenizações a fornecedores e clientes. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2181, 2, '3.9.7.5.0.00.00.00.00.00', 'VPD DE PROVISÃO PARA REPARTIÇÃO DE CRÉDITOS', 'Compreende a constituição de provisões de passivos de prazo ou de valores incertos relacionados aos créditos tributários e não tributários reconhecidos no lançamento por parte do agente arrecadador, a serem repartidos com outros entes da federação.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2182, 2, '3.9.7.5.5.00.00.00.00.00', 'VPD DE PROVISÃO PARA REPARTIÇÃO DE CRÉDITOS - INTER OFSS - MUNICÍPIO', 'Compreende a constituição de provisões de passivos de prazo ou de valores incertos relacionados aos créditos tributários e não tributários reconhecidos no lançamento por parte do agente arrecadador, a serem repartidos com outros entes da federação. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2183, 2, '3.9.7.6.0.00.00.00.00.00', 'VPD DE PROVISÃO PARA RISCOS DECORRENTES DE CONTRATOS DE PPP ', 'Compreende a constituição de provisões de passivos de prazo ou de valores incertos relacionados aos riscos de demanda, construção, disponibilidade ou outros riscos decorrentes de contratos de PPP, de acordo com a Lei n.11.079/2004.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2184, 2, '3.9.7.6.1.00.00.00.00.00', 'VPD DE PROVISÃO PARA RISCOS DECORRENTES DE CONTRATOS DE PPP - CONSOLIDAÇÃO', 'Compreende a constituição de provisões de passivos de prazo ou de valores incertos relacionados aos riscos de demanda, construção, disponibilidade ou outros riscos decorrentes de contratos de PPP, de acordo com a Lei n.11.079/2004. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2185, 2, '3.9.7.9.0.00.00.00.00.00', 'VPD DE OUTRAS PROVISÕES ', 'Compreende a constituição de provisões de passivos de prazo ou de valor incertos não classificadas anteriormente neste plano de contas.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2186, 2, '3.9.7.9.1.00.00.00.00.00', 'VPD DE OUTRAS PROVISÕES - CONSOLIDAÇÃO ', 'Compreende a constituição de provisões de passivos de prazo ou de valor incertos não classificadas anteriormente neste plano de contas. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2187, 2, '3.9.9.0.0.00.00.00.00.00', 'DIVERSAS VARIAÇÕES PATRIMONIAIS DIMINUTIVAS', 'Compreende outras variações patrimoniais diminutivas não classificadas em itens específicos.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2290, 2, '7.2.0.0.0.00.00.00.00.00', 'ADMINISTRAÇÃO FINANCEIRA', 'Compreende as contas de registro da programação financeira e de controle das disponibilidades.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2188, 2, '3.9.9.1.0.00.00.00.00.00', 'COMPENSAÇÃO FINANCEIRA ENTRE RGPS/RPPS', 'Compreende as variações patrimoniais diminutivas provenientes da compensação financeira entre o regime geral de previdência social e os regimes próprios de previdência social dos servidores da União, dos estados, do distrito federal e dos municípios na hipótese de contagem recíproca de tempo de contribuição (não concomitante).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2189, 2, '3.9.9.1.2.00.00.00.00.00', 'COMPENSAÇÃO FINANCEIRA ENTRE RGPS/RPPS - INTRA OFSS', 'Registra as variações patrimoniais diminutivas provenientes da compensação financeira entre o regime geral de previdência social e os regimes próprios de previdência social dos servidores da União, dos estados, do distrito federal e dos municípios na hipótese de contagem recíproca de tempo de contribuição (não concomitante).  Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do ente.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2190, 2, '3.9.9.1.3.00.00.00.00.00', 'COMPENSAÇÃO FINANCEIRA ENTRE RGPS/RPPS - INTER OFSS - UNIÃO', 'Compreende as variações patrimoniais diminutivas provenientes da compensação financeira entre o regime geral de previdência social e os regimes próprios de previdência social dos servidores da União, dos estados, do distrito federal e dos municípios na hipótese de contagem recíproca de tempo de contribuição (não concomitante). Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2208, 2, '3.9.9.6.1.00.00.00.00.00', 'INDENIZAÇÕES E RESTITUIÇÕES - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais diminutivas provenientes de indenizações e/ou restituições diversas, não especificadas no plano de contas. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2382, 2, '2.1.3.2.1.02.01.00.00.00', 'CONTAS NÃO FINANCIADAS A PAGAR', 'Registra os valores não financiados, ou seja, em uma única parcela, de contas a pagar', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2191, 2, '3.9.9.1.4.00.00.00.00.00', 'COMPENSAÇÃO FINANCEIRA ENTRE RGPS/RPPS - INTER OFSS - ESTADO', 'Compreende as variações patrimoniais diminutivas provenientes da compensação financeira entre o regime geral de previdência social e os regimes próprios de previdência social dos servidores da União, dos estados, do distrito federal e dos municípios na hipótese de contagem recíproca de tempo de contribuição (não concomitante). Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2192, 2, '3.9.9.1.5.00.00.00.00.00', 'COMPENSAÇÃO FINANCEIRA ENTRE RGPS/RPPS - INTER OFSS - MUNICÍPIO', 'Compreende as variações patrimoniais diminutivas provenientes da compensação financeira entre o regime geral de previdência social e os regimes próprios de previdência social dos servidores da União, dos estados, do distrito federal e dos municípios na hipótese de contagem recíproca de tempo de contribuição (não concomitante). Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2193, 2, '3.9.9.2.0.00.00.00.00.00', 'COMPENSAÇÃO FINANCEIRA ENTRE REGIMES PRÓPRIOS', 'Compreende as variações patrimoniais diminutivas provenientes da compensação financeira entre regimes próprios de previdência social dos servidores da União, dos estados, do distrito federal e dos municípios na hipótese de contagem recíproca de tempo de contribuição (não concomitante).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2194, 2, '3.9.9.2.3.00.00.00.00.00', 'COMPENSAÇÃO FINANCEIRA ENTRE REGIMES PRÓPRIOS - INTER OFSS - UNIÃO', 'Compreende as variações patrimoniais diminutivas provenientes da compensação financeira entre regimes próprios de previdência social dos servidores da União, dos estados, do distrito federal e dos municípios na hipótese de contagem recíproca de tempo de contribuição (não concomitante). Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2195, 2, '3.9.9.2.4.00.00.00.00.00', 'COMPENSAÇÃO FINANCEIRA ENTRE REGIMES PRÓPRIOS - INTER OFSS - ESTADO', 'Compreende as variações patrimoniais diminutivas provenientes da compensação financeira entre regimes próprios de previdência social dos servidores da União, dos estados, do distrito federal e dos municípios na hipótese de contagem recíproca de tempo de contribuição (não concomitante). Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2196, 2, '3.9.9.2.5.00.00.00.00.00', 'COMPENSAÇÃO FINANCEIRA ENTRE REGIMES PRÓPRIOS - INTER OFSS - MUNICÍPIO', 'Compreende as variações patrimoniais diminutivas provenientes da compensação financeira entre regimes próprios de previdência social dos servidores da União, dos estados, do distrito federal e dos municípios na hipótese de contagem recíproca de tempo de contribuição (não concomitante). Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2197, 2, '3.9.9.3.0.00.00.00.00.00', 'VARIAÇÃO PATRIMONIAL DIMINUTIVA COM BONIFICAÇÕES', 'Compreende as variações patrimoniais diminutivas provenientes de bonificações concedidas na venda de mercadorias.  ', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2198, 2, '3.9.9.3.1.00.00.00.00.00', 'VARIAÇÃO PATRIMONIAL DIMINUTIVA COM BONIFICAÇÕES - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais diminutivas provenientes de bonificações concedidas na venda de mercadorias. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2199, 2, '3.9.9.4.0.00.00.00.00.00', 'AMORTIZAÇÃO DE ÁGIO EM INVESTIMENTOS', 'Compreende as variações patrimoniais diminutivas provenientes de amortização de ágio em investimentos.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2200, 2, '3.9.9.4.1.00.00.00.00.00', 'AMORTIZAÇÃO DE ÁGIO EM INVESTIMENTOS - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais diminutivas provenientes de amortização de ágio em investimentos. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2201, 2, '3.9.9.4.2.00.00.00.00.00', 'AMORTIZAÇÃO DE ÁGIO EM INVESTIMENTOS - INTRA OFSS', 'Compreende as variações patrimoniais diminutivas provenientes de amortização de ágio em investimentos. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do ente.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2202, 2, '3.9.9.4.3.00.00.00.00.00', 'AMORTIZAÇÃO DE ÁGIO EM INVESTIMENTOS - INTER OFSS - UNIÃO', 'Compreende as variações patrimoniais diminutivas provenientes de amortização de ágio em investimentos. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2203, 2, '3.9.9.4.4.00.00.00.00.00', 'AMORTIZAÇÃO DE ÁGIO EM INVESTIMENTOS - INTER OFSS - ESTADO', 'Compreende as variações patrimoniais diminutivas provenientes de amortização de ágio em investimentos. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2204, 2, '3.9.9.4.5.00.00.00.00.00', 'AMORTIZAÇÃO DE ÁGIO EM INVESTIMENTOS - INTER OFSS - MUNICÍPIO', 'Compreende as variações patrimoniais diminutivas provenientes de amortização de ágio em investimentos. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2205, 2, '3.9.9.5.0.00.00.00.00.00', 'MULTAS ADMINISTRATIVAS', 'Compreende as variações patrimoniais diminutivas provenientes de multas administrativas diversas.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2206, 2, '3.9.9.5.1.00.00.00.00.00', 'MULTAS ADMINISTRATIVAS - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais diminutivas provenientes de multas administrativas diversas. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2207, 2, '3.9.9.6.0.00.00.00.00.00', 'INDENIZAÇÕES E RESTITUIÇÕES', 'Compreende as variações patrimoniais diminutivas provenientes de indenizações e/ou restituições diversas, não especificadas no plano de contas.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2239, 2, '5.2.2.1.1.00.00.00.00.00', 'DOTAÇÃO INICIAL', 'Compreende a dotação inicial autorizada na lei orçamentária anual.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2209, 2, '3.9.9.7.0.00.00.00.00.00', 'COMPENSAÇÕES AO RGPS', 'Compreende as compensações diversas ao Fundo do Regime Geral de Previdência Social, tais como recomposição do fundo em virtude de isenções, reduções de alíquota ou base de cálculo e outros benefícios concedidos.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2210, 2, '3.9.9.7.1.00.00.00.00.00', 'COMPENSAÇÕES AO RGPS - CONSOLIDAÇÃO', 'Compreende as compensações diversas ao Fundo do Regime Geral de Previdência Social, tais como recomposição do fundo em virtude de isenções, reduções de alíquota ou base de cálculo e outros benefícios concedidos. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2211, 2, '3.9.9.7.3.00.00.00.00.00', 'COMPENSAÇÕES AO RGPS - INTER OFSS - UNIÃO', 'Compreende as compensações diversas ao Fundo do Regime Geral de Previdência Social, tais como recomposição do fundo em virtude de isenções, reduções de alíquota ou base de cálculo e outros benefícios concedidos. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2212, 2, '3.9.9.9.0.00.00.00.00.00', 'VARIAÇÕES PATRIMONIAIS DIMINUTIVAS DECORRENTES DE FATOS GERADORES DIVERSOS', 'Compreende as variações patrimoniais diminutivas decorrentes de fatos geradores diversos.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2213, 2, '3.9.9.9.1.00.00.00.00.00', 'VARIAÇÕES PATRIMONIAIS DIMINUTIVAS DECORRENTES DE FATOS GERADORES DIVERSOS - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais diminutivas decorrentes de fatos geradores diversos. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2214, 2, '4.1.2.1.1.97.00.00.00.00', '(-) DEDUÇÕES', 'Compreende as deduções por renuncia de variações patrimoniais aumentativas como por exemplo: a anistia, a remissão, o subsidio, o crédito presumido, a concessão de isenção em caráter não geral, a alteração de alíquota ou modificação de base de cálculo que implique redução discriminada de tributos ou contribuições e outros benefícios que correspondam a tratamento diferenciado.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2215, 2, '4.2.1.1.1.97.00.00.00.00', '(-) DEDUÇÕES', 'Compreendem as deduções das contribuições sociais - RPPS.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2216, 2, '4.2.1.1.2.97.00.00.00.00', '(-) DEDUÇÕES', 'Compreendem as deduções das variações patrimoniais aumentativas.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2217, 2, '4.2.1.1.4.97.00.00.00.00', '(-) DEDUÇÕES', 'Compreendem as deduções das variações patrimoniais umentativas.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2218, 2, '4.2.1.1.5.97.00.00.00.00', '(-) DEDUÇÕES', 'Compreendem as deduções das variações patrimoniais umentativas.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2219, 2, '4.3.1.9.0.00.00.00.00.00', '(-) DEDUÇÕES DA VENDA BRUTA DE MERCADORIAS', 'Compreende as deduções das vendas de mercadorias, como devoluções, abatimentos e descontos comerciais concedidos.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2220, 2, '4.3.1.9.1.00.00.00.00.00', '(-) DEDUÇÕES DA VENDA BRUTA DE MERCADORIAS - CONSOLIDAÇÃO', 'Compreende as deduções das vendas de mercadorias, como devoluções, abatimentos e descontos comerciais concedidos. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2221, 2, '4.3.2.9.0.00.00.00.00.00', '(-) DEDUÇÕES DE VENDA BRUTA DE PRODUTOS', 'Compreende as deduções das vendas de produtos, como devoluções, abatimentos e descontos comerciais concedidos.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2222, 2, '4.3.2.9.1.00.00.00.00.00', '(-) DEDUÇÕES DA VENDA BRUTA DE PRODUTOS - CONSOLIDAÇÃO', 'Compreende as deduções das vendas de produtos, como devoluções, abatimentos e descontos comerciais concedidos. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2223, 2, '4.3.3.9.0.00.00.00.00.00', '(-) DEDUÇÕES DO VALOR BRUTO DE EXPLORAÇÃO DE BENS, DIREITOS E PRESTAÇÃO DE SERVIÇOS', 'Compreende as deduções das prestações de serviços, como devoluções, abatimentos e descontos comerciais concedidos.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2224, 2, '4.3.3.9.1.00.00.00.00.00', '(-) DEDUÇÕES DO VALOR BRUTO DE EXPLORAÇÃO DE BENS, DIREITOS E PRESTAÇÃO DE SERVIÇOS - CONSOLIDAÇÃO', 'Compreende as deduções das prestações de serviços, como devoluções, abatimentos e descontos comerciais concedidos. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2225, 2, '4.5.2.1.3.97.00.00.00.00', '(-) DEDUÇÕES', 'Compreende as deduções de VPAs referentes às transferências constitucionais e legais de receitas - Inter OFSS -União.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2226, 2, '4.5.2.1.4.97.00.00.00.00', '(-) DEDUÇÕES', 'Compreende as deduções das VPA de transferencias constitucionais e legais de receita - Inter OFSS - Estado.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2227, 2, '4.6.2.2.1.97.00.00.00.00', '(-) DEDUÇÃO DOS GANHOS COM ALIENAÇÃO DE IMOBILIZADO', 'Compreende as deduções dos ganho com alienação de ativo imobilizado - Dedução dos Ganhos com Alienação de Imobilizado.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2228, 2, '5.0.0.0.0.00.00.00.00.00', 'CONTROLES DA APROVAÇÃO DO PLANEJAMENTO E ORÇAMENTO', 'Compreende as contas com função de registrar os atos e fatos ligados a execução orçamentária.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2229, 2, '5.1.0.0.0.00.00.00.00.00', 'PLANEJAMENTO APROVADO', 'Compreende o somatório dos valores monetários previstos para execução dos programas e ações (projetos, atividades e operações especiais) estabelecidos no plano plurianual e projeto de lei orçamentária anual.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2233, 2, '5.2.0.0.0.00.00.00.00.00', 'ORÇAMENTO APROVADO', 'Compreende o somatório dos valores relativos à previsão da receita, fixação da despesa e suas alterações no orçamento geral da União durante o exercício financeiro.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2234, 2, '5.2.1.0.0.00.00.00.00.00', 'PREVISÃO DA RECEITA', 'Compreende o somatório dos valores relativos à previsão da receita pública aprovada pela lei orçamentária anual e suas alterações.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2235, 2, '5.2.1.1.0.00.00.00.00.00', 'PREVISÃO INICIAL DA RECEITA', 'Compreende o valor da receita previsão inicial da receita aprovado na LOA.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2236, 2, '5.2.1.2.1.00.00.00.00.00', 'PREVISÃO ADICIONAL DA RECEITA', 'Compreende o valor adicional da receita para abertura de créditos adicionais.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2237, 2, '5.2.2.0.0.00.00.00.00.00', 'FIXAÇÃO DA DESPESA', 'Compreende o somatório dos valores relativos à fixação da despesa pública aprovada pela lei orçamentária e suas alterações.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2238, 2, '5.2.2.1.0.00.00.00.00.00', 'DOTAÇÃO ORÇAMENTÁRIA', 'Compreende o somatório dos valores monetários da dotação orçamentária inicial, adicional e seus cancelamentos.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2241, 2, '5.2.2.1.2.02.00.00.00.00', 'CREDITO ADICIONAL - ESPECIAL', 'Compreende o somatório dos valores dos créditos adicionais especiais destinados a atender programas não contemplados na lei orçamentária anual.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2242, 2, '5.2.2.1.2.03.00.00.00.00', 'CREDITO ADICIONAL - EXTRAORDINÁRIO', 'Compreende o somatório dos valores referentes à abertura de créditos adicionais extraordinários destinados a despesas imprevisíveis e urgentes como as decorrentes de guerra, comoção interna ou calamidade pública.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2243, 2, '5.2.2.1.3.00.00.00.00.00', 'DOTAÇÃO ADICIONAL POR FONTE', 'Compreende o somatório dos valores da dotação adicional por fonte de recursos.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2244, 2, '5.2.2.1.9.01.00.00.00.00', 'ALTERAÇÃO DO QUADRO DE DETALHAMENTO DA DESPESA ', 'Compreende a movimentação dos créditos por acréscimo ou redução decorrente de alteração do quadro de detalhamento de despesas - QDD (elemento de despesa).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2245, 2, '5.2.2.1.9.02.00.00.00.00', 'ALTERAÇÃO DA LEI ORCAMENTÁRIA ', 'Compreende as alterações na lei orçamentária, inclusive as decorrentes de transposição, remanejamento e transferência de dotações orçamentárias.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2246, 2, '5.2.2.2.0.00.00.00.00.00', 'MOVIMENTAÇÃO DE CRÉDITOS RECEBIDOS', 'Compreende o somatório dos valores dos recebimentos de créditos orçamentários através de destaque, provisão ou por fusão, cisão ou extinção de unidades.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2247, 2, '5.2.2.2.1.00.00.00.00.00', 'DESCENTRALIZAÇÃO INTERNA DE CRÉDITOS - PROVISÃO', 'Compreende os valores dos créditos descentralizados das unidades orçamentárias para as unidades administrativas sob sua jurisdição ou entre estas, no âmbito do próprio ministério, secretaria ou órgão equivalente, recebidos ao longo do exercício.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2248, 2, '5.2.2.2.2.00.00.00.00.00', 'DESCENTRALIZAÇÃO EXTERNA DE CRÉDITOS - DESTAQUE', 'Compreende a descentralização do credito inicial ou adicional recebido de unidades ou órgãos pertencentes a ministérios, secretarias e órgãos equivalentes distintos ou entre estes e entidades da administração indireta.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2249, 2, '5.2.2.2.2.01.00.00.00.00', 'ADMINISTRAÇÃO DIRETA                ', 'Compreende o valor referente a movimentação de créditos decorrentes de recebimento ou de transferência de outros órgãos e entidades de igual ou de diferente unidade orçamentária.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2250, 2, '5.2.2.2.2.02.00.00.00.00', 'ADMINISTRAÇÃO INDIRETA                 ', 'Compreende o valor referente a movimentação de créditos decorrentes de recebimento ou de transferência de outros órgãos e entidades de igual ou de diferente unidade orçamentária.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2251, 2, '5.2.2.2.9.00.00.00.00.00', 'OUTRAS DESCENTRALIZAÇÕES DE CRÉDITOS', 'Compreende as movimentações de créditos recebidos por cisão, fusão, extinção, compensação e outras transações.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2252, 2, '5.2.2.3.0.00.00.00.00.00', 'DETALHAMENTO DE CREDITO', 'Compreende o somatório relativos às dotações detalhadas relativas a cada ação orçamentária (projeto, atividade ou operações especiais).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2253, 2, '5.2.2.9.0.00.00.00.00.00', 'OUTROS CONTROLES DA DESPESA ORÇAMENTÁRIA', 'Compreende o somatório dos valores das despesas pré-empenhadas e empenhadas por detalhamento específico.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2254, 2, '5.2.2.9.1.00.00.00.00.00', 'PRÉ-EMPENHOS DA DESPESA', 'Compreende o credito orçamentário pré-empenhado, para atender objetivo especifico, nos casos em que a despesa a ser realizada, por suas características, exige um intervalo de tempo desde a decisão da realização da despesa até a efetivação da emissão de NE.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2255, 2, '5.2.2.9.2.00.00.00.00.00', 'EMPENHOS POR EMISSÃO', 'Compreende o somatório dos valores de empenho emitido por ato emanado de autoridade competente que cria para o poder público a obrigação de pagar as despesas.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2256, 2, '5.2.2.9.2.01.00.00.00.00', 'EXECUÇÃO DA DESPESA POR NOTA DE EMPENHO', 'Compreende os valores executados da despesa, detalhados por nota de empenho.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2257, 2, '5.3.0.0.0.00.00.00.00.00', 'INSCRIÇÃO DE RESTOS A PAGAR', 'Compreende o somatório relativo ao valor da inscrição das despesas empenhadas e não pagas.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2258, 2, '5.3.1.0.0.00.00.00.00.00', 'INSCRIÇÃO DE RP NÃO PROCESSADOS', 'Compreende o somatório dos valores inscritos em restos a pagar não-processados relativos às despesas empenhadas e não liquidadas.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2259, 2, '5.3.2.0.0.00.00.00.00.00', 'INSCRIÇÃO DE RP PROCESSADOS', 'Compreende o somatório dos valores inscritos em restos a pagar processados.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2260, 2, '6.2.1.3.0.00.00.00.00.00', '(-) DEDUÇÕES DA RECEITA ORÇAMENTÁRIA', 'Compreende o somatório dos valores relativos às deduções de receitas realizadas (devoluções, restituições, e outras), detalhada por natureza de receita.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2261, 2, '6.2.1.3.1.00.00.00.00.00', '(-) DEDUÇÕES POR TRANSFERÊNCIAS CONSTITUCIONAIS E LEGAIS', 'Compreende o somatório dos valores relativos as deduções de receitas realizadas por transferências constitucionais e legais, detalhada por natureza de receita.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2262, 2, '7.0.0.0.0.00.00.00.00.00', 'CONTROLES DEVEDORES', 'Compreende as contas em que são registrados atos potenciais e controles específicos.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2291, 2, '7.2.1.0.0.00.00.00.00.00', 'DISPONIBILIDADES POR DESTINAÇÃO', 'Compreende as contas que registram os controles sobre as disponibilidades por destinação de recursos.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2263, 2, '7.1.0.0.0.00.00.00.00.00', 'ATOS POTENCIAIS', 'Compreende contas relacionadas às situações não compreendidas no patrimônio, mas que, direta ou indiretamente, possam vir à afeta-lo, exclusive as que dizem respeito a atos e fatos ligados a execução orçamentária e financeira e as contas com função precípua de controle.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2264, 2, '7.1.1.0.0.00.00.00.00.00', 'ATOS POTENCIAIS ATIVOS', 'Compreende os atos e fatos que possam vir a aumentar o ativo da entidade governamental.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2265, 2, '7.1.1.1.0.00.00.00.00.00', 'GARANTIAS E CONTRAGARANTIAS RECEBIDAS', 'Compreende contas relacionadas ao registro de avais, fianças e hipotecas recebidas no país e no exterior, bem como emolumentos consulares e outras garantias e contragarantias.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2266, 2, '7.1.1.1.1.00.00.00.00.00', 'GARANTIAS E CONTRAGARANTIAS RECEBIDAS - CONSOLIDAÇÃO', 'Compreende o valor recebido de compromisso de adimplência de obrigação financeira ou contratual, no país. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, ' ');
insert into contabilidade.planocontadetalhe values (2267, 2, '7.1.1.1.1.01.00.00.00.00', 'GARANTIAS RECEBIDAS NO PAÍS', 'COMPREENDE O VALOR RECEBIDO DE COMPROMISSO DE ADIMPLÊNCIA DE OBRIGAÇÃO FINANCEIRA OU CONTRATUAL, NO PAÍS.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3317, 2, '8.1.1.1.1.03.02.00.00.00', 'AVAIS EXECUTADOS', 'REGISTRA O VALOR RECEBIDO DAS CONTRAGARANTIAS RECEBIDAS POR AVAL NO PAÍS.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (2269, 2, '7.1.1.1.1.03.00.00.00.00', 'CONTRAGARANTIAS RECEBIDAS NO PAÍS', 'Compreende o valor das contragarantias recebidas referentes às concessões de garantias concedidas sobre obrigações contraídas no país.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2270, 2, '7.1.1.1.1.04.00.00.00.00', 'CONTRAGARANTIAS RECEBIDAS NO EXTERIOR', 'Compreende o valor das contragarantias recebidas referentes às concessões de garantias concedidas sobre obrigações contraídas no exterior.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2271, 2, '7.1.1.2.0.00.00.00.00.00', 'DIREITOS CONVENIADOS E OUTROS INSTRUMENTOS CONGÊNERES', 'Compreende contas relacionadas ao registro, no convenente, dos convênios firmados entre entidades, objetivando o cumprimento de finalidades comuns.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2272, 2, '7.1.1.2.1.00.00.00.00.00', 'DIREITOS CONVENIADOS E OUTROS INSTRUMENTOS CONGÊNERES - CONSOLIDAÇÃO', 'Compreende contas relacionadas ao registro, no convenente, dos convênios firmados entre entidades objetivando o cumprimento de finalidades comuns. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2273, 2, '7.1.1.3.0.00.00.00.00.00', 'DIREITOS CONTRATUAIS', 'Compreende contas relacionadas ao registro dos valores de direitos contratuais, quando a administração pública participa como contratada.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2274, 2, '7.1.1.3.1.00.00.00.00.00', 'DIREITOS CONTRATUAIS - CONSOLIDAÇÃO', 'Compreende contas relacionadas ao registro dos valores de direitos contratuais, quando a administração pública participa como contratada. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2275, 2, '7.1.1.9.0.00.00.00.00.00', 'OUTROS ATOS POTENCIAIS ATIVOS', 'Compreende os atos potenciais ativos não contemplados em contas especificas.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2276, 2, '7.1.1.9.1.00.00.00.00.00', 'OUTROS ATOS POTENCIAIS ATIVOS - CONSOLIDAÇÃO', 'Compreende os atos potenciais ativos não contemplados em contas especificas. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2277, 2, '7.1.2.0.0.00.00.00.00.00', 'ATOS POTENCIAIS PASSIVOS', 'Compreende os atos e fatos que possam vir a aumentar o passivo ou diminuir o ativo da entidade governamental.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2278, 2, '7.1.2.1.0.00.00.00.00.00', 'GARANTIAS E CONTRAGARANTIAS CONCEDIDAS', 'Compreende contas relacionadas ao registro de avais, fianças e hipotecas concedidas no país e no exterior, bem como emolumentos consulares e outras garantias e contragarantias.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2279, 2, '7.1.2.1.1.00.00.00.00.00', 'GARANTIAS E CONTRAGARANTIAS CONCEDIDAS - CONSOLIDAÇÃO', 'Compreende o valor concedido de compromisso de adimplência de obrigação financeira ou contratual, no país. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, ' ');
insert into contabilidade.planocontadetalhe values (2280, 2, '7.1.2.1.1.01.00.00.00.00', 'GARANTIAS CONCEDIDAS NO PAÍS', 'Compreende o valor concedido de compromisso de adimplência de obrigação financeira ou contratual, no país.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2281, 2, '7.1.2.1.1.02.00.00.00.00', 'GARANTIAS CONCEDIDAS NO EXTERIOR', 'Compreende o valor concedido de compromisso de adimplência de obrigação financeira ou contratual, no exterior.', 1, false, 0, ' ');
insert into contabilidade.planocontadetalhe values (2282, 2, '7.1.2.1.1.03.00.00.00.00', 'CONTRAGARANTIAS CONCEDIDAS NO PAÍS', 'Compreende o valor das contragarantias concedidas referentes as concessões de garantias concedidas sobre obrigações contraídas no pais.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2283, 2, '7.1.2.1.1.04.00.00.00.00', 'CONTRAGARANTIAS CONCEDIDAS NO EXTERIOR', 'Compreende o valor das contragarantias concedidas referentes às concessões de garantias concedidas sobre obrigações contraídas no exterior.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2284, 2, '7.1.2.2.0.00.00.00.00.00', 'OBRIGAÇÕES CONVENIADAS E OUTROS INSTRUMENTOS CONGÊNERES', 'Compreende contas relacionadas ao registro, no concedente, do valor dos convênios firmados entre entidades, objetivando o cumprimento de finalidades comuns.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2285, 2, '7.1.2.2.1.00.00.00.00.00', 'OBRIGAÇÕES CONVENIADAS E OUTROS INSTRUMENTOS CONGÊNERES - CONSOLIDAÇÃO', 'Compreende contas relacionadas ao registro, no convenente, dos convênios firmados entre entidades objetivando o cumprimento de finalidades comuns. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2286, 2, '7.1.2.3.0.00.00.00.00.00', 'OBRIGAÇÕES CONTRATUAIS', 'Compreende contas relacionadas ao registro dos valores de obrigações contratuais, quando a administração pública participa como contratante.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2287, 2, '7.1.2.3.1.00.00.00.00.00', 'OBRIGAÇÕES CONTRATUAIS - CONSOLIDAÇÃO', 'Compreende contas relacionadas ao registro dos valores de obrigações contratuais, quando a administração pública participa como contratante. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2288, 2, '7.1.2.3.1.08.00.00.00.00', 'CONTRATOS DE PPP', 'Compreende o valor dos passivos decorrentes de contrato de PPP, incluindo o valor das obrigações contratuais com as contraprestações futuras, assim como os riscos não provisionados e outros passivos contingentes.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2289, 2, '7.1.2.9.0.00.00.00.00.00', 'OUTROS ATOS POTENCIAIS PASSIVOS', 'Compreende os atos potenciais passivos não contemplados em contas especificas.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3591, 2, '8.9.1.2.1.04.00.00.00.00', 'ADIANTAMENTOS IMPUGNADOS', 'Registra os valores dos adiantamentos concedidos impugnados.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (2293, 2, '7.2.1.2.0.00.00.00.00.00', 'LIMITE DE RESTOS A PAGAR POR DESTINAÇÃO', 'Compreende as contas que controlam a inscrição do limite de restos a pagar, classificados por destinação de recursos', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2294, 2, '7.2.1.3.0.00.00.00.00.00', 'RECURSO DIFERIDO POR DESTINAÇÃO', 'Compreende as contas que controlam a inscrição dos recursos diferidos. Recursos diferidos são as sobras de recursos financeiros ao final do exercício (recurso diferido), que deveriam ser devolvidas a conta única, porem, ao invés disso, essas sobras são liberadas para uso (apenas no exercício seguinte) através de descontos das transferências financeiras (cota, repasse e sub-repasse) do exercício seguinte.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2295, 2, '7.2.2.0.0.00.00.00.00.00', 'PROGRAMAÇÃO FINANCEIRA', 'Compreende as contas que registram as cotas, repasses e sub-repasses para atender a despesas orçamentárias, restos a pagar autorizados e demais dispêndios extra orçamentários.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2296, 2, '7.2.3.0.0.00.00.00.00.00', 'INSCRIÇÃO DO LIMITE ORÇAMENTÁRIO', 'Compreende as contas que controlam o limite de empenho e movimentação de créditos orçamentários, conforme estabelecidos em ato próprio dos poderes e ministério público.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3389, 2, '8.1.2.1.1.03.03.00.00.00', 'AVAIS EXECUTADOS', 'Registra o valor recebido das contragarantias recebidas por aval no país.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (2297, 2, '7.2.4.0.0.00.00.00.00.00', 'CONTROLES DA ARRECADAÇÃO', 'Compreende as contas que registram o valor da arrecadação liquida da receita orçamentária, por meio de documentos de arrecadação como DARF, GRU, DAR, entre outros.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2298, 2, '7.2.4.1.0.00.00.00.00.00', 'CONTROLES DE DOCUMENTOS DE ARRECADAÇÃO', 'COMPREENDE AS CONTAS QUE REGISTRAM O VALOR DA ARRECADACAO LIQUIDA DA RECEITA ORCAMENTARIA, POR MEIO DE DOCUMENTOS DE ARRECADAÇÃO.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2299, 2, '7.3.0.0.0.00.00.00.00.00', 'DÍVIDA ATIVA', 'Compreende o controle dos créditos a serem inscritos em dívida ativa, dos que se encontram em processamento. Compreende as contas que controlam os créditos passiveis de serem encaminhados e inscritos em dívida ativa o de inscrição e a tramitação dos créditos inscritos.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2300, 2, '7.3.1.0.0.00.00.00.00.00', 'CONTROLE DO ENCAMINHAMENTO DE CRÉDITOS PARA INSCRIÇÃO EM DÍVIDA ATIVA', 'Compreende os valores passiveis de serem encaminhados e inscritos em dívida ativa.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2301, 2, '7.3.1.1.0.00.00.00.00.00', 'ENCAMINHAMENTO DE CRÉDITOS PARA INSCRIÇÃO EM DÍVIDA ATIVA', 'Compreende o montante dos créditos passíveis de serem encaminhados para inscrição em Dívida Ativa.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2302, 2, '7.3.1.1.1.00.00.00.00.00', 'ENCAMINHAMENTO DE CRÉDITOS PARA INSCRIÇÃO EM DÍVIDA ATIVA TRIBUTÁRIA', 'Compreende o montante dos créditos passíveis de serem encaminhados para inscrição em Dívida Ativa Tributária.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2303, 2, '7.3.1.1.2.00.00.00.00.00', 'ENCAMINHAMENTO DE CRÉDITOS PARA INSCRIÇÃO EM DÍVIDA ATIVA NÃO-TRIBUTÁRIA', 'Compreende o montante dos créditos a encaminhar e encaminhados para inscrição em Dívida Ativa Não-Tributária.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2304, 2, '7.3.2.0.0.00.00.00.00.00', 'CONTROLE DA INSCRIÇÃO DE CRÉDITOS EM DÍVIDA ATIVA', 'Compreende as contas que controlam os créditos passiveis de serem inscritos em dívida ativa pelo órgão responsável pela inscrição em dívida ativa.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2305, 2, '7.3.2.1.0.00.00.00.00.00', 'INSCRIÇÃO DE CRÉDITOS EM DÍVIDA ATIVA', 'Compreende os valores dos créditos passíveis de serem inscritos em dívida ativa pelo órgão responsável pela inscrição em dívida ativa.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2306, 2, '7.3.2.1.1.00.00.00.00.00', 'INSCRIÇÃO DE CRÉDITOS EM DÍVIDA ATIVA TRIBUTÁRIA', 'Compreende o valor dos créditos de origem tributária passíveis de serem inscritos em dívida ativa pelo órgão competente.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2307, 2, '7.3.2.1.2.00.00.00.00.00', 'INSCRIÇÃO DE CRÉDITOS EM DÍVIDA ATIVA NÃO-TRIBUTÁRIA', 'Compreende o valor dos créditos de natureza não-tributária passíveis de serem inscritos em dívida ativa pelo órgão competente.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2308, 2, '7.4.0.0.0.00.00.00.00.00', 'RISCOS FISCAIS', 'Compreende as contas que controlam os riscos fiscais que não preencham os requisitos para reconhecimento como passivo, conforme identificados no anexo de riscos fiscais da lei de diretrizes orçamentárias.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2309, 2, '7.4.1.0.0.00.00.00.00.00', 'CONTROLE DE PASSIVOS CONTINGENTES', 'Compreende as contas que registram o controle dos riscos fiscais que não preencham os requisitos para reconhecimento como passivo classificados como passivos contingentes, conforme identificados no anexo de riscos fiscais da lei de diretrizes orçamentárias.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2310, 2, '7.4.1.1.0.00.00.00.00.00', 'PASSIVOS CONTINGENTES', 'Compreende os riscos fiscais classificados como Passivos Contingentes.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2311, 2, '7.9.1.2.0.00.00.00.00.00', 'RESPONSABILIDADE DE TERCEIROS POR VALORES, TÍTULOS E BENS', 'Compreende contas relacionadas ao registro da responsabilidade de terceiros com a administração pública por títulos, valores e bens.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2312, 2, '7.4.2.0.0.00.00.00.00.00', 'CONTROLE DOS DEMAIS RISCOS FISCAIS', 'Compreende as contas que registram os riscos fiscais que não preencham os requisitos para reconhecimento como passivo, não classificados como passivos contingentes, conforme identificados no anexo de riscos fiscais da lei de diretrizes orçamentárias.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2313, 2, '7.4.2.1.0.00.00.00.00.00', 'DEMAIS RISCOS FISCAIS ', 'Compreende os riscos fiscais não classificados como passivos contingentes.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2314, 2, '7.5.0.0.0.00.00.00.00.00', 'CONSÓRCIOS PÚBLICOS', 'Compreende as contas que controlam o registro de atos dos consórcios públicos (do ente consorciado e/ou do próprio consórcio), incluindo os controles do contrato de rateio, controle da prestação de contas, bem como as informações que serão consolidadas no ente consorciado para fins de elaboração dos demonstrativos dos consórcios, conforme Portaria STN 72/2012.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2315, 2, '7.5.3.0.0.00.00.00.00.00', 'CONSOLIDAÇÃO DA EXECUÇÃO DO CONSÓRCIO', 'Compreende as informações referentes aos Consórcios Públicos, atribuídas ao ente consorciado com base no contrato de rateio,que serão enviadas pelo consórcio para os entes consorciados para fins de elaboração dos demonstrativos fiscais ( Saúde, pessoal, educação e disponibilidade de caixa), em atendimento a Portaria STN n.º 72/2012. Conta para uso do ente consorciado.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2316, 2, '7.8.0.0.0.00.00.00.00.00', 'CUSTOS', 'Compreende as contas que controlam os custos de bens e serviços produzidos.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2317, 2, '7.9.0.0.0.00.00.00.00.00', 'OUTROS CONTROLES', 'Compreende as contas de controles não especificadas anteriormente nos grupos dessa classe.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2318, 2, '7.9.1.0.0.00.00.00.00.00', 'RESPONSABILIDADE POR VALORES, TÍTULOS E BENS', 'Compreende as contas relacionadas ao registro das responsabilidades por valores, títulos e bens.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2319, 2, '7.9.1.1.0.00.00.00.00.00', 'RESPONSABILIDADE COM TERCEIROS POR VALORES, TÍTULOS E BENS', 'Compreende as contas relacionadas ao registro da responsabilidade da administração pública com terceiros por títulos, valores e bens.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (2320, 2, '1.1.2.9.1.01.04.00.00.00', '(-) PERDAS ESTIMADAS EM DEMAIS CONTRIBUIÇÕES', 'Registra o ajuste para perdas estimadas com o não recebimento de demais contribuições.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2321, 2, '1.1.2.9.1.01.03.00.00.00', '(-) PERDAS ESTIMADAS EM CONTRIBUIÇÕES DE MELHORIA', 'Registra o ajuste para perdas estimadas com o não recebimento de contribuições de melhoria.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2322, 2, '1.1.2.9.1.01.01.01.00.00', '(-) PERDAS ESTIMADAS NO IMPOSTO SOBRE A RENDA E PROVENTOS DE QUALQUER NATUREZA', 'Registra o ajuste para perdas estimadas com o não recebimento do Imposto sobre a Renda e Proventos de Qualquer Natureza.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2323, 2, '1.1.2.9.1.01.01.07.00.00', '(-) PERDAS ESTIMADAS NO ISS', 'Registra o ajuste para perdas estimadas com o não recebimento do ISS', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2324, 2, '1.1.2.9.1.01.01.08.00.00', '(-) PERDAS ESTIMADAS NO ITR', 'Registra o ajuste para perdas estimadas com o não recebimento do ITR', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2325, 2, '1.1.2.9.1.01.02.00.00.00', '(-) PERDAS ESTIMADAS EM TAXAS', 'Registra o ajuste para perdas estimadas com o não recebimento de taxas.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2327, 2, '1.1.2.9.1.02.01.00.00.00', '(-) PERDAS ESTIMADAS EM CLIENTE FATURAS/DUPLICATAS A RECEBER', 'Registra o ajuste para perdas estimadas com o não recebimento das faturas/duplicatas a receber decorrentes das vendas a prazo de mercadorias ou serviços que ocorrem no curso normal das operações da unidade, representando um direito a cobrar de seus clientes.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2328, 2, '1.1.2.9.1.03.01.00.00.00', '(-) PERDAS ESTIMADAS EM CRÉDITOS DE EMPRÉSTIMOS  CONCEDIDOS', 'Registra o ajuste para perdas estimadas com o não recebimento de créditos de empréstimos concedidos.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2329, 2, '1.1.2.9.1.03.02.00.00.00', '(-) PERDAS ESTIMADAS EM CRÉDITOS DE FINANCIAMENTOS CONCEDIDOS', 'Registra o ajuste para perdas estimadas com o não recebimento de créditos de financiamentos concedidos.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2330, 2, '1.1.2.9.1.04.01.01.00.00', '(-) PERDAS ESTIMADAS EM CRÉDITOS DE DÍVIDA ATIVA TRIBUTÁRIA - IMPOSTO SOBRE A RENDA E PROVENTOS DE QUALQUER NATUREZA', 'Registra o ajuste para perdas estimadas com o não recebimento dos créditos inscritos em dívida ativa tributária decorrentes do imposto sobre a renda e proventos de qualquer natureza.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2331, 2, '1.1.2.9.1.04.01.05.00.00', '(-) PERDAS ESTIMADAS EM CRÉDITOS DE DÍVIDA ATIVA TRIBUTÁRIA - IPTU', 'Registra o ajuste para perdas estimadas com o não recebimento dos créditos inscritos em dívida ativa tributária decorrentes do iptu.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2332, 2, '1.1.2.9.1.04.01.06.00.00', '(-) PERDAS ESTIMADAS EM CRÉDITOS DE DÍVIDA ATIVA TRIBUTÁRIA - ITBI', 'Registra o ajuste para perdas estimadas com o não recebimento dos créditos inscritos em dívida ativa tributária decorrentes do itbi.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2333, 2, '1.1.2.9.1.04.01.07.00.00', '(-) PERDAS ESTIMADAS EM CRÉDITOS DE DÍVIDA ATIVA TRIBUTÁRIA - ISS', 'Registra o ajuste para perdas estimadas com o não recebimento dos créditos inscritos em dívida ativa tributária decorrentes do iss.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2334, 2, '1.1.2.9.1.04.01.08.00.00', '(-) PERDAS ESTIMADAS EM CRÉDITOS DE DÍVIDA ATIVA TRIBUTÁRIA - ITR', 'Registra o ajuste para perdas estimadas com o não recebimento dos créditos inscritos em dívida ativa tributária decorrentes do itr.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2335, 2, '1.1.2.9.1.04.02.00.00.00', '(-) PERDAS ESTIMADAS EM CRÉDITOS DE DÍVIDA ATIVA TRIBUTÁRIA - TAXAS', 'Registra o ajuste para perdas estimadas com o não recebimento dos créditos inscritos em dívida ativa tributária decorrentes de taxas.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2336, 2, '1.1.2.9.1.04.03.00.00.00', '(-) PERDAS ESTIMADAS EM CRÉDITOS DE DÍVIDA ATIVA TRIBUTÁRIA - CONTRIBUIÇÕES DE MELHORIA', 'Registra o ajuste para perdas estimadas com o não recebimento dos créditos inscritos em dívida ativa tributária decorrentes de contribuições de melhoria.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2337, 2, '1.1.2.9.1.04.04.00.00.00', '(-) PERDAS ESTIMADAS EM CRÉDITOS DE DÍVIDA ATIVA TRIBUTÁRIA - DEMAIS CONTRIBUIÇÕES', 'Registra o ajuste para perdas estimadas com o não recebimento dos créditos inscritos em dívida ativa tributária decorrentes de demais contribuições.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2338, 2, '1.1.2.9.1.05.00.00.00.00', '(-) PERDAS ESTIMADAS EM CRÉDITOS DE DÍVIDA ATIVA NÃO TRIBUTÁRIA ', 'Registra o ajuste para perdas estimadas com o não recebimento dos créditos inscritos em dívida ativa não tributária.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2339, 2, '1.1.2.9.2.03.01.00.00.00', '(-) PERDAS ESTIMADAS EM CRÉDITOS DE EMPRÉSTIMOS  CONCEDIDOS', 'Registra o ajuste para perdas estimadas com o não recebimento de créditos de empréstimos concedidos.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2340, 2, '1.1.2.9.2.03.02.00.00.00', '(-) PERDAS ESTIMADAS EM CRÉDITOS DE FINANCIAMENTOS CONCEDIDOS', 'Registra o ajuste para perdas estimadas com o não recebimento de créditos de financiamentos concedidos.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2341, 2, '1.1.2.9.2.04.01.00.00.00', '(-) PERDAS ESTIMADAS EM CRÉDITOS DE DÍVIDA ATIVA TRIBUTÁRIA - IMPOSTOS', 'Registra o ajuste para perdas estimadas com o não recebimento dos créditos inscritos em dívida ativa tributária decorrentes de impostos.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2342, 2, '1.1.2.9.2.04.02.00.00.00', '(-) PERDAS ESTIMADAS EM CRÉDITOS DE DÍVIDA ATIVA TRIBUTÁRIA - TAXAS', 'Registra o ajuste para perdas estimadas com o não recebimento dos créditos inscritos em dívida ativa tributária decorrentes de taxas.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2343, 2, '1.1.2.9.2.04.03.00.00.00', '(-) PERDAS ESTIMADAS EM CRÉDITOS DE DÍVIDA ATIVA TRIBUTÁRIA - CONTRIBUIÇÕES DE MELHORIA', 'Registra o ajuste para perdas estimadas com o não recebimento dos créditos inscritos em dívida ativa tributária decorrentes de contribuições de melhoria.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2344, 2, '1.1.2.9.2.04.04.00.00.00', '(-) PERDAS ESTIMADAS EM CRÉDITOS DE DÍVIDA ATIVA TRIBUTÁRIA - DEMAIS CONTRIBUIÇÕES', 'Registra o ajuste para perdas estimadas com o não recebimento dos créditos inscritos em dívida ativa tributária decorrentes de demais contribuições.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2345, 2, '1.1.2.9.2.05.00.00.00.00', '(-) PERDAS ESTIMADAS EM CRÉDITOS DE DÍVIDA ATIVA NÃO TRIBUTÁRIA ', 'Registra o ajuste para perdas estimadas com o não recebimento dos créditos inscritos em dívida ativa não tributária.', 2, true, 2, 'P');
