insert into contabilidade.planocontadetalhe values (2407, 2, '1.2.3.8.1.01.06.00.00.00', '(-) DEPRECIAÇÃO ACUMULADA DE PEÇAS E CONJUNTOS DE REPOSIÇÃO', 'Registra a depreciação acumulada de peças e conjuntos de reposição destinados a substituição em máquinas e equipamentos, aeronaves e embarcações, bens de segurança e socorro, entre outros.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2409, 2, '1.2.3.8.1.01.08.00.00.00', '(-) DEPRECIAÇÃO ACUMULADA DE BENS MÓVEIS EM ALMOXARIFADO', 'Registra a depreciação acumulada de bens permanentes a serem estocados em almoxarifado.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2410, 2, '1.2.3.8.1.01.09.00.00.00', '(-) DEPRECIAÇÃO ACUMULADA DE ARMAMENTOS', 'Registra a depreciação acumulada de armas que constituem objetos de defesa ou preparativos de guerra.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2411, 2, '1.2.3.8.1.01.10.00.00.00', '(-) DEPRECIAÇÃO ACUMULADA DE SEMOVENTES', 'Registra a depreciação acumulada de animais destinados a produção, reprodução, engorda e aos serviços utilitários em geral.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2412, 2, '1.2.3.8.1.01.99.00.00.00', '(-) DEPRECIAÇÃO ACUMULADA DE DEMAIS BENS MÓVEIS', 'Registra a depreciação acumulada de demais bens móveis não classificados em grupos específicos.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2413, 2, '1.2.3.8.1.02.01.00.00.00', '(-) DEPRECIAÇÃO ACUMULADA DE BENS DE USO ESPECIAL', 'Registra a depreciação acumulada de bens como edifícios ou terrenos destinados a serviço ou estabelecimento da administração estadual ou municipal, inclusive os de suas autarquias e fundações públicas.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2414, 2, '1.2.3.8.1.02.02.00.00.00', '(-) DEPRECIAÇÃO ACUMULADA DE BENS DOMINICAIS', 'Registra a depreciação acumulada de bens que constituem o patrimônio das pessoas jurídicas de direito público, como objeto de direito pessoal, ou real, de cada uma dessas entidades. Compreende ainda, não dispondo a lei em contrário, os bens pertencentes as pessoas jurídicas de direito público a que se tenha dado estrutura de direito privado.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2415, 2, '1.2.3.8.1.02.03.00.00.00', '(-) DEPRECIAÇÃO ACUMULADA DE BENS DE USO COMUM DO POVO', 'Registra a depreciação acumulada de bens de uso comum do povo construídos ou adquiridos por pessoas jurídicas de direito público.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2416, 2, '2.1.1.3.1.03.01.00.00.00', 'PRECATÓRIOS DE BENEFÍCIOS ASSISTENCIAIS - REGIME ESPECIAL - ANTES DE 05/05/2000 ', 'Registra as obrigações referentes a precatórios de benefícios assistenciais,  sujeitos ao regime especial instituído pela emenda constitucional 62/2009, anteriores a 05/05/2000 (Lei de Responsabilidade Fiscal).', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2417, 2, '1.2.3.8.1.02.05.00.00.00', '(-) DEPRECIAÇÃO ACUMULADA DE INSTALAÇÕES', 'Registra a depreciação acumulada de equipamentos, materiais e custo de implantação de instalações que, não obstante integradas aos edifícios, devem ser segregadas das obras civis, como, por exemplo, as instalações elétricas, hidráulicas, sanitárias, de vapor, de ar comprimido, frigoríficas, contra incêndio, de comunicações, de climatização, para combustíveis, gases, de antipoluição, para cozinha, dentre outros. E também aplicável a construção de trechos ferroviários.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2418, 2, '1.2.3.8.1.02.06.00.00.00', '(-) DEPRECIAÇÃO ACUMULADA DE BENFEITORIAS EM PROPRIEDADE DE TERCEIROS', 'Registra a depreciação acumulada de construções em terrenos arrendados de terceiros e instalações e outras benfeitorias em prédios alugados. São considerados somente os gastos com construção e instalação que se incorporam ao imóvel e revertem ao proprietário do imóvel ao final da locação.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2419, 2, '1.2.3.8.1.02.99.00.00.00', '(-) DEPRECIAÇÃO ACUMULADA DE DEMAIS BENS IMÓVEIS', 'Registra a depreciação acumulada de os demais bens imóveis não classificados anteriormente nesse plano de contas.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2420, 2, '1.2.3.8.1.03.00.00.00.00', '(-) EXAUSTÃO ACUMULADA - BENS MÓVEIS', 'Registra a diminuição do valor dos elementos do ativo imobilizado, bens móveis, devido à perda do valor, decorrente de sua exploração, de direitos cujo objeto sejam recursos minerais ou florestais ou bens aplicados nessa exploração.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2421, 2, '1.2.3.8.1.04.00.00.00.00', '(-) EXAUSTÃO ACUMULADA - BENS IMÓVEIS', 'Registra a diminuição do valor dos elementos do ativo imobilizado, bens imóveis, devido à perda do valor, decorrente de sua exploração, de direitos cujo objeto sejam recursos minerais ou florestais ou bens aplicados nessa exploração.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2422, 2, '1.2.3.8.1.05.00.00.00.00', '(-) AMORTIZAÇÃO ACUMULADA - BENS MÓVEIS', 'Registra a diminuição do valor dos elementos do ativo imobilizado, bens móveis, devido à perda do valor do capital aplicado na aquisição de direitos de propriedade industrial ou comercial e quaisquer outros com existência ou exercício de duração limitada ou cujo objeto sejam bens de utilização por prazo legal ou contratualmente limitado.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2423, 2, '1.2.3.8.1.06.00.00.00.00', '(-) AMORTIZAÇÃO ACUMULADA - BENS IMÓVEIS', 'Registra a diminuição do valor dos elementos do ativo imobilizado, bens Imóveis, devido à perda do valor do capital aplicado na aquisição de direitos de propriedade industrial ou comercial e quaisquer outros com existência ou exercício de duração limitada ou cujo objeto sejam bens de utilização por prazo legal ou contratualmente limitado.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2424, 2, '1.2.4.8.1.01.00.00.00.00', '(-) AMORTIZAÇÃO ACUMULADA - SOFTWARES', 'Registra a diminuição do valor do capital aplicado em softwares, pertencentes ao ativo intangível.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2425, 2, '1.2.4.8.1.02.00.00.00.00', '(-) AMORTIZAÇÃO ACUMULADA - MARCAS, DIREITOS E PATENTES', 'Registra a diminuição do valor do capital aplicado em marcas, direitos e patentes, pertencentes ao ativo intangível.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2426, 2, '1.2.4.8.1.03.00.00.00.00', '(-) AMORTIZAÇÃO ACUMULADA - DIREITO DE USO DE IMÓVEIS', 'Registra a diminuição do valor do capital aplicado em direito de uso de imóveis, pertencentes ao ativo intangível.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2427, 2, '1.2.4.9.1.01.00.00.00.00', '(-) REDUÇÃO AO VALOR RECUPERÁVEL DE INTANGÍVEL - SOFTWARES', 'Registra os valores de ajuste ao valor recuperável do software pertencente ao ativo intangível, quando esse for inferior ao valor liquido contábil.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2428, 2, '1.2.4.9.1.02.00.00.00.00', '(-) REDUÇÃO AO VALOR RECUPERÁVEL DE INTANGÍVEL - MARCAS, DIREITOS E PATENTES', 'Registra os valores de ajuste ao valor recuperável das marcas, direitos e patentes, quando esse for inferior ao valor liquido contábil.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2429, 2, '1.2.4.9.1.03.00.00.00.00', '(-) REDUÇÃO AO VALOR RECUPERÁVEL DE INTANGÍVEL - DIREITO DE USO', 'Registra os valores de ajuste ao valor recuperável de direito de uso, quando esse for inferior ao valor liquido contábil.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2430, 2, '1.2.5.9.1.01.00.00.00.00', '(-) AMORTIZAÇÃO ACUMULADA - GASTOS DE IMPLANTAÇÃO E PRÉ-OPERACIONAIS', 'Registra a perda do valor do capital aplicado em despesas pré-operacionais.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2431, 2, '1.2.5.9.1.02.00.00.00.00', '(-) AMORTIZAÇÃO ACUMULADA - GASTOS DE REORGANIZAÇÃO', 'Registra a perda do valor do capital aplicado em gastos de reestruturação.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2432, 2, '2.1.1.1.1.01.01.00.00.00', 'SALÁRIOS, REMUNERAÇÕES E BENEFÍCIOS', 'Registra as obrigações referentes a salários ou remunerações, bem como benefícios aos quais o empregado ou servidor tenha direito.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2433, 2, '2.1.1.1.1.01.02.00.00.00', 'DÉCIMO TERCEIRO SALÁRIO', 'Registra as obrigações referentes ao décimo terceiro salário, geralmente apropriadas na base de 1/12 do valor bruto da folha de pagamento da unidade.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2434, 2, '2.1.1.1.1.01.03.00.00.00', 'FÉRIAS', 'Registra as obrigações referentes a férias, geralmente apropriadas como percentuais da folha de pagamento da unidade.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2435, 2, '2.1.1.1.1.01.04.00.00.00', 'LICENÇA-PRÊMIO', 'Registra os valores das obrigações constituídas com base em percentuais de salários, destinados ao pagamento de licença-prêmio.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2436, 2, '2.1.1.1.1.01.05.00.00.00', 'PARTICIPAÇÕES A EMPREGADOS', 'Registra os valores das obrigações constituídas para pagamento de participações a empregados.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2437, 2, '2.1.1.2.2.07.00.00.00.00', 'APORTE PARA COBERTURA DE DÉFICIT ATUARIAL A PAGAR  ', 'Registra os valores devidos ao RPPS pelo ente a título de aporte para cobertura de déficit atuarial.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2438, 2, '2.1.1.1.1.04.01.00.00.00', 'PRECATÓRIOS DE PESSOAL - REGIME ESPECIAL - ANTES DE 05/05/2000 ', 'Registra as obrigações referentes a precatórios de proventos de aposentadoria, reformas ou pensões,  sujeitos ao regime especial instituído pela emenda constitucional 62/2009, anteriores a 05/05/2000 (Lei de Responsabilidade Fiscal).', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2439, 2, '2.1.1.1.1.04.02.00.00.00', 'PRECATÓRIOS DE PESSOAL - REGIME ESPECIAL - A PARTIR DE 05/05/2000 - VENCIDOS E NÃO PAGOS', 'Registra as obrigações referentes a precatórios de salários ou remunerações, bem como a benefícios aos quais o empregado ou servidor tenha direito,  sujeitos ao regime especial instituído pela emenda constitucional 62/2009, a partir de 05/05/2000 (Lei de Responsabilidade Fiscal), não pagos durante a execução do orçamento em que deveriam ter sido incluídos, caso fosse observada à regra geral, prevista no §5º do artigo 100 da CF/88.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2440, 2, '2.1.1.1.1.04.03.00.00.00', 'PRECATÓRIOS DE PESSOAL - REGIME ESPECIAL - A PARTIR DE 05/05/2000 - NÃO VENCIDOS', 'Registra as obrigações referentes a precatórios de salários ou remunerações, bem como a benefícios aos quais o empregado ou servidor tenha direito,  sujeitos ao regime especial instituído pela emenda constitucional 62/2009, a partir de 05/05/2000 (Lei de Responsabilidade Fiscal), dentro do prazo de pagamento caso fosse observada a regra geral, estabelicida no § 5º do artigo 100 da CF/88.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2441, 2, '2.1.1.1.1.05.01.00.00.00', 'PRECATÓRIOS DE PESSOAL - REGIME ORDINÁRIO - ANTES DE 05/05/2000 ', 'Registra as obrigações referentes a precatórios de salários ou remunerações, bem como a benefícios aos quais o empregado ou servidor tenha direito,  não sujeitos ao regime especial instituído pela emenda constitucional 62/2009, anteriores a 05/05/2000 (Lei de Responsabilidade Fiscal).', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2442, 2, '2.1.1.4.3.01.01.00.00.00', 'CONTRIBUIÇÕES AO RGPS SOBRE SALÁRIOS E REMUNERAÇÕES', 'Registra os valores relativos às contribuições à previdência social, incidentes sobre salários e remunerações pagos.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2443, 2, '2.1.1.1.1.05.02.00.00.00', 'PRECATÓRIOS DE PESSOAL - REGIME ORDINÁRIO - A PARTIR DE 05/05/2000 - VENCIDOS E NÃO PAGOS', 'Registra as obrigações referentes a precatórios de salários ou remunerações, bem como a benefícios aos quais o empregado ou servidor tenha direito,  não sujeitos ao regime especial instituído pela emenda constitucional 62/2009, a partir de 05/05/2000 (Lei de Responsabilidade Fiscal), não pagos durante a execução do orçamento em que deveriam ter sido incluídos em observância ao disposto no § 5º do artigo 100 da CF/88.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2444, 2, '2.1.1.1.1.05.03.00.00.00', 'PRECATÓRIOS DE PESSOAL - REGIME ORDINÁRIO - A PARTIR DE 05/05/2000 - NÃO VENCIDOS', 'Registra as obrigações referentes a precatórios de salários ou remunerações, bem como a benefícios aos quais o empregado ou servidor tenha direito,  não sujeitos ao regime especial instituído pela emenda constitucional 62/2009, a partir de 05/05/2000 (Lei de Responsabilidade Fiscal), dentro do prazo de pagamento previsto no § 5º do artigo 100 da CF/88.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2445, 2, '2.1.1.1.1.06.00.00.00.00', 'PESSOAL A PAGAR - SENTENÇAS JUDICIAIS - EXCETO PRECATÓRIOS', 'Registra as obrigações decorrentes de sentenças judiciais referentes a salários ou remunerações, bem como a benefícios aos quais o empregado ou servidor tenha direito,  exceto precatórios.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2446, 2, '2.1.1.2.1.01.00.00.00.00', 'BENEFÍCIOS PREVIDENCIÁRIOS A PAGAR', 'Registra as obrigações referentes a proventos de aposentadoria, reformas ou pensões.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2447, 2, '2.1.1.2.1.04.01.00.00.00', 'PRECATÓRIOS DE BENEFÍCIOS PREVIDENCIÁRIOS - REGIME ESPECIAL - ANTES DE 05/05/2000 ', 'Registra as obrigações referentes a precatórios de proventos de aposentadoria, reformas ou pensões,  sujeitos ao regime especial instituído pela emenda constitucional 62/2009, anteriores a 05/05/2000 (Lei de Responsabilidade Fiscal).', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2448, 2, '2.1.1.2.1.04.02.00.00.00', 'PRECATÓRIOS DE BENEFÍCIOS PREVIDENCIÁRIOS - REGIME ESPECIAL - A PARTIR DE 05/05/2000 - VENCIDOS E NÃO PAGOS', 'Registra as obrigações referentes a precatórios de proventos de aposentadoria, reformas ou pensões,  sujeitos ao regime especial instituído pela emenda constitucional 62/2009, a partir de 05/05/2000 (Lei de Responsabilidade Fiscal), não pagos durante a execução do orçamento em que deveriam ter sido incluídos, caso fosse observada à regra geral, prevista no §5º do artigo 100 da CF/88.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2449, 2, '2.1.1.2.1.04.03.00.00.00', 'PRECATÓRIOS DE BENEFÍCIOS PREVIDENCIÁRIOS - REGIME ESPECIAL - A PARTIR DE 05/05/2000 - NÃO VENCIDOS', 'Registra as obrigações referentes a precatórios de proventos de aposentadoria, reformas ou pensões,  sujeitos ao regime especial instituído pela emenda constitucional 62/2009, a partir de 05/05/2000 (Lei de Responsabilidade Fiscal), dentro do prazo de pagamento caso fosse observada a regra geral, estabelicida no § 5º do artigo 100 da CF/88.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2450, 2, '2.1.1.2.1.05.01.00.00.00', 'PRECATÓRIOS DE BENEFÍCIOS PREVIDENCIÁRIOS - REGIME ORDINÁRIO - ANTES DE 05/05/2000 ', 'Registra as obrigações referentes a precatórios de proventos de aposentadoria, reformas ou pensões,  não sujeitos ao regime especial instituído pela emenda constitucional 62/2009, anteriores a 05/05/2000 (Lei de Responsabilidade Fiscal).', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2451, 2, '2.1.1.2.1.05.02.00.00.00', 'PRECATÓRIOS DE BENEFÍCIOS PREVIDENCIÁRIOS - REGIME ORDINÁRIO - A PARTIR DE 05/05/2000 - VENCIDOS E NÃO PAGOS', 'Registra as obrigações referentes a precatórios de proventos de aposentadoria, reformas ou pensões,  não sujeitos ao regime especial instituído pela emenda constitucional 62/2009, a partir de 05/05/2000 (Lei de Responsabilidade Fiscal), não pagos durante a execução do orçamento em que deveriam ter sido incluídos em observância ao disposto no § 5º do artigo 100 da CF/88.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2476, 2, '2.1.1.4.1.04.00.00.00.00', 'PREVIDÊNCIA SOCIAL RURAL', 'Registra os valores relativos as obrigações das empresas ou instituições, resultantes do cálculo da previdência social rural.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2452, 2, '2.1.1.2.1.05.03.00.00.00', 'PRECATÓRIOS DE BENEFÍCIOS PREVIDENCIÁRIOS - REGIME ORDINÁRIO - A PARTIR DE 05/05/2000 - NÃO VENCIDOS', 'Registra as obrigações referentes a precatórios de proventos de aposentadoria, reformas ou pensões,  não sujeitos ao regime especial instituído pela emenda constitucional 62/2009, a partir de 05/05/2000 (Lei de Responsabilidade Fiscal), dentro do prazo de pagamento previsto no § 5º do artigo 100 da CF/88.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2453, 2, '2.1.1.2.1.06.00.00.00.00', 'BENEFÍCIOS PREVIDENCIÁRIOS A PAGAR - DECISÕES JUDICIAIS - EXCETO PRECATÓRIOS', 'Registra as obrigações decorrentes de sentenças judiciais referentes a proventos de aposentadoria, reformas ou pensões,  exceto precatórios', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2454, 2, '2.1.1.2.2.05.01.00.00.00', 'OBRIGAÇÕES DO RPPS DA UNIÃO JUNTO AO RGPS', 'Registra os valores relativos às obrigações do RPPS da União a pagar ao RGPS decorrentes de compensação financeira entre regimes, por contagem recíproca de tempo de contribuição.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2455, 2, '2.1.1.2.2.05.02.00.00.00', 'OBRIGAÇÕES DO RGPS JUNTO AO RPPS DA UNIÃO  ', 'Registra os valores relativos às obrigações do RGPS a pagar ao RPPS da União decorrentes de compensação financeira entre regimes, por contagem recíproca de tempo de contribuição.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2456, 2, '2.1.1.2.2.06.00.00.00.00', 'APORTE PARA COBERTURA DE DÉFICIT FINANCEIRO A PAGAR ', 'Registra os valores devidos ao RPPS pelo ente a título de aporte para cobertura de déficit financeiro.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2457, 2, '2.1.3.2.1.01.03.00.00.00', 'PARCELAMENTO DE FORNECEDORES A PAGAR', 'Registra o parcelamento de dívidas com fornecedores a pagar.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2458, 2, '2.1.1.2.3.05.01.00.00.00', 'OBRIGAÇÕES DO RPPS JUNTO AO RGPS', 'Registra os valores relativos às obrigações do RPPS a pagar ao RGPS decorrentes de compensação financeira entre regimes, por contagem recíproca de tempo de contribuição.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2459, 2, '2.1.1.2.3.05.02.00.00.00', 'OBRIGAÇÕES DO RPPS JUNTO AO RPPS DA UNIÃO', 'Registra os valores relativos às obrigações do RPPS a pagar ao RPPS da União decorrentes de compensação financeira entre regimes, por contagem recíproca de tempo de contribuição.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2460, 2, '2.1.1.2.4.05.01.00.00.00', 'OBRIGAÇÕES DO RPPS JUNTO AO RPPS DE ESTADO', 'Registra os valores relativos às obrigações do RPPS a pagar ao RPPS de um estado decorrentes de compensação financeira entre regimes, por contagem recíproca de tempo de contribuição.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2461, 2, '2.1.1.2.4.05.02.00.00.00', 'OBRIGAÇÕES DO RGPS JUNTO AO RPPS DE ESTADO', 'Registra os valores relativos às obrigações do RGPS a pagar ao RPPS de um estado decorrentes de compensação financeira entre regimes, por contagem recíproca de tempo de contribuição.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2462, 2, '2.1.1.2.5.05.01.00.00.00', 'CRÉDITOS DO RPPS JUNTO AO RPPS DE MUNICÍPIO', 'Registra os valores relativos às obrigações do RPPS a pagar ao RPPS de um município decorrentes de compensação financeira entre regimes, por contagem recíproca de tempo de contribuição.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2463, 2, '2.1.1.2.5.05.02.00.00.00', 'CRÉDITOS DO RGPS JUNTO AO RPPS DE MUNICÍPIO', 'Registra os valores relativos às obrigações do RGPS a pagar ao RPPS de um município decorrentes de compensação financeira entre regimes, por contagem recíproca de tempo de contribuição.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2464, 2, '2.1.1.3.1.01.00.00.00.00', 'BENEFÍCIOS ASSISTENCIAIS A PAGAR', 'Registra as obrigações relativas aos benefícios assistenciais a pagar.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2465, 2, '2.1.1.4.3.01.02.00.00.00', 'CONTRIBUIÇÕES AO RGPS - DÉBITO PARCELADO', 'Registra os valores de debito parcelado que se referem ao não recolhimento de obrigações da folha de pagamento junto à previdência.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2466, 2, '2.1.1.3.1.03.02.00.00.00', 'PRECATÓRIOS DE BENEFÍCIOS ASSISTENCIAIS - REGIME ESPECIAL - A PARTIR DE 05/05/2000 - VENCIDOS E NÃO PAGOS', 'Registra as obrigações referentes a precatórios de benefícios assistenciais,  sujeitos ao regime especial instituído pela emenda constitucional 62/2009, a partir de 05/05/2000 (Lei de Responsabilidade Fiscal), não pagos durante a execução do orçamento em que deveriam ter sido incluídos, caso fosse observada à regra geral, prevista no §5º do artigo 100 da CF/88.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2467, 2, '2.1.1.3.1.03.03.00.00.00', 'PRECATÓRIOS DE BENEFÍCIOS ASSISTENCIAIS - REGIME ESPECIAL - A PARTIR DE 05/05/2000 - NÃO VENCIDOS', 'Registra as obrigações referentes a precatórios de benefícios assistenciais,  sujeitos ao regime especial instituído pela emenda constitucional 62/2009, a partir de 05/05/2000 (Lei de Responsabilidade Fiscal), dentro do prazo de pagamento caso fosse observada a regra geral, estabelicida no § 5º do artigo 100 da CF/88.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2468, 2, '2.1.1.3.1.04.01.00.00.00', 'PRECATÓRIOS DE BENEFÍCIOS ASSISTENCIAIS - REGIME ORDINÁRIO - ANTES DE 05/05/2000 ', 'Registra as obrigações referentes a precatórios de benefícios assistenciais,  não sujeitos ao regime especial instituído pela emenda constitucional 62/2009, anteriores a 05/05/2000 (Lei de Responsabilidade Fiscal).', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2469, 2, '2.1.1.3.1.04.02.00.00.00', 'PRECATÓRIOS DE BENEFÍCIOS ASSISTENCIAIS - REGIME ORDINÁRIO - A PARTIR DE 05/05/2000 - VENCIDOS E NÃO PAGOS', 'Registra as obrigações referentes a precatórios de benefícios assistenciais,  não sujeitos ao regime especial instituído pela emenda constitucional 62/2009, a partir de 05/05/2000 (Lei de Responsabilidade Fiscal), não pagos durante a execução do orçamento em que deveriam ter sido incluídos em observância ao disposto no § 5º do artigo 100 da CF/88.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2470, 2, '2.1.1.3.1.04.03.00.00.00', 'PRECATÓRIOS DE BENEFÍCIOS ASSISTENCIAIS - REGIME ORDINÁRIO - A PARTIR DE 05/05/2000 - NÃO VENCIDOS', 'Registra as obrigações referentes a precatórios de benefícios assistenciais,  não sujeitos ao regime especial instituído pela emenda constitucional 62/2009, a partir de 05/05/2000 (Lei de Responsabilidade Fiscal), dentro do prazo de pagamento previsto no § 5º do artigo 100 da CF/88.', 2, true, 2, 'X');
