insert into contabilidade.planocontadetalhe values (2533, 2, '2.1.2.1.5.02.05.00.00.00', 'ANTECIPAÇÃO DA RECEITA ORÇAMENTÁRIA', 'Registra os valores referentes a operações de crédito por antecipação de receita destinada a atender insuficiência de caixa durante o exercício financeiro, devendo cumprir as exigências mencionadas no art. 32 da lei complementar nº 101, publicada em 04/05/2000 e aquelas previstas no art. 38 da referida lei.', 2, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (2534, 2, '2.1.2.1.5.02.98.00.00.00', 'OUTROS CONTRATOS - EMPRÉSTIMOS INTERNOS', 'Registra os valores das operações de crédito internas em contratos, para as quais não haja contas específicas.', 2, true, 2, 'X');
