insert into contabilidade.planocontadetalhe values (2575, 2, '2.1.4.1.1.10.00.00.00.00', 'COFINS A RECOLHER', 'Registra o valor das obrigações exigíveis a curto prazo a recolher relativas à Contribuição para Financiamento da Seguridade Social (COFINS).', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2576, 2, '2.1.3.1.1.01.01.00.00.00', 'FORNECEDORES NÃO FINANCIADOS A PAGAR', 'Registra os valores a pagar não financiados, ou seja, em uma única parcela, aos fornecedores nacionais de bens, materiais e serviços envolvidos com as atividades operacionais da entidade.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2577, 2, '2.1.3.1.1.01.02.00.00.00', 'FORNECEDORES FINANCIADOS A PAGAR', 'Registra os valores a pagar financiados diretamente com fornecedores nacionais de bens, materiais e serviços envolvidos com as atividades operacionais da entidade, nos termos do art. 29, inciso III da LC 101/2000.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2578, 2, '2.1.3.1.1.01.03.00.00.00', 'PARCELAMENTO DE FORNECEDORES A PAGAR', 'Registra o parcelamento de dívidas com fornecedores a pagar, nos termos do art. 29, inciso III da LC 101/2000.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2579, 2, '2.1.3.1.1.01.99.00.00.00', 'DEMAIS FORNECEDORES A PAGAR', 'Registra os valores de demais fornecedores a pagar, nos termos do art. 29, inciso III da LC 101/2000.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2580, 2, '2.1.3.1.1.03.01.00.00.00', 'CONTAS NÃO FINANCIADAS A PAGAR', 'Registra os valores não financiados, ou seja, em uma única parcela, de contas a pagar', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2581, 2, '2.1.3.1.1.03.02.00.00.00', 'CONTAS FINANCIADAS A PAGAR', 'Registra os valores financiados de contas a pagar.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2582, 2, '2.1.3.1.1.03.03.00.00.00', 'PARCELAMENTO DE CONTAS A PAGAR', 'Registra o parcelamento de dívidas com contas a pagar.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2583, 2, '2.1.3.1.1.03.99.00.00.00', 'DEMAIS CONTAS A PAGAR', 'Registra os valores de demais contas a pagar.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2584, 2, '2.1.3.1.1.05.01.00.00.00', 'PRECATÓRIOS DE FORNECEDORES NACIONAIS - REGIME ESPECIAL - ANTES DE 05/05/2000 ', 'Registra as obrigações referentes a precatórios de fornecedores nacionais,  sujeitos ao regime especial instituído pela emenda constitucional 62/2009, anteriores a 05/05/2000 (Lei de Responsabilidade Fiscal).', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2585, 2, '2.1.3.1.1.05.02.00.00.00', 'PRECATÓRIOS DE FORNECEDORES NACIONAIS - REGIME ESPECIAL - A PARTIR DE 05/05/2000 - VENCIDOS E NÃO PAGOS', 'Registra as obrigações referentes a precatórios de fornecedores nacionais,  sujeitos ao regime especial instituído pela emenda constitucional 62/2009, a partir de 05/05/2000 (Lei de Responsabilidade Fiscal), não pagos durante a execução do orçamento em que deveriam ter sido incluídos, caso fosse observada à regra geral, prevista no §5º do artigo 100 da CF/88.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2586, 2, '2.1.3.1.1.05.03.00.00.00', 'PRECATÓRIOS DE FORNECEDORES NACIONAIS - REGIME ESPECIAL - A PARTIR DE 05/05/2000 - NÃO VENCIDOS', 'Registra as obrigações referentes a precatórios de fornecedores nacionais,  sujeitos ao regime especial instituído pela emenda constitucional 62/2009, a partir de 05/05/2000 (Lei de Responsabilidade Fiscal), dentro do prazo de pagamento caso fosse observada a regra geral, estabelicida no § 5º do artigo 100 da CF/88.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2587, 2, '2.1.3.1.1.06.01.00.00.00', 'PRECATÓRIOS DE FORNECEDORES NACIONAIS - REGIME ORDINÁRIO - ANTES DE 05/05/2000 ', 'Registra as obrigações referentes a precatórios de fornecedores nacionais,  não sujeitos ao regime especial instituído pela emenda constitucional 62/2009, anteriores a 05/05/2000 (Lei de Responsabilidade Fiscal).', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2588, 2, '2.1.3.1.1.06.02.00.00.00', 'PRECATÓRIOS DE FORNECEDORES NACIONAIS - REGIME ORDINÁRIO - A PARTIR DE 05/05/2000 - VENCIDOS E NÃO PAGOS', 'Registra as obrigações referentes a precatórios de fornecedores nacionais,  não sujeitos ao regime especial instituído pela emenda constitucional 62/2009, a partir de 05/05/2000 (Lei de Responsabilidade Fiscal), não pagos durante a execução do orçamento em que deveriam ter sido incluídos em observância ao disposto no § 5º do artigo 100 da CF/88.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2589, 2, '2.1.3.1.1.06.03.00.00.00', 'PRECATÓRIOS DE FORNECEDORES NACIONAIS - REGIME ORDINÁRIO - A PARTIR DE 05/05/2000 - NÃO VENCIDOS', 'Registra as obrigações referentes a precatórios de fornecedores nacionais,  não sujeitos ao regime especial instituído pela emenda constitucional 62/2009, a partir de 05/05/2000 (Lei de Responsabilidade Fiscal), dentro do prazo de pagamento previsto no § 5º do artigo 100 da CF/88.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2614, 2, '2.1.4.2.1.07.00.00.00.00', 'RECURSOS FISCAIS ESTADUAIS', 'Registra o valor das Obrigações junto ao Governo Estadual, referente a Recursos Fiscais Estaduais.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2670, 2, '2.1.7.9.1.01.00.00.00.00', 'PROVISÃO PARA GARANTIAS', 'Registra os valores das provisões destinadas a cobrir despesas com a prestação de garantia relativas a produtos vendidos.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2590, 2, '2.1.3.1.1.07.01.00.00.00', 'PRECATÓRIOS DE CONTAS A PAGAR - REGIME ESPECIAL - ANTES DE 05/05/2000 ', 'Registra as obrigações referentes a precatórios de contas a pagar de credores nacionais,  sujeitos ao regime especial instituído pela emenda constitucional 62/2009, anteriores a 05/05/2000 (Lei de Responsabilidade Fiscal).', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2591, 2, '2.1.3.1.1.07.02.00.00.00', 'PRECATÓRIOS DE CONTAS A PAGAR - REGIME ESPECIAL - A PARTIR DE 05/05/2000 - VENCIDOS E NÃO PAGOS', 'Registra as obrigações referentes a precatórios de contas a pagar de credores nacionais,  sujeitos ao regime especial instituído pela emenda constitucional 62/2009, a partir de 05/05/2000 (Lei de Responsabilidade Fiscal), não pagos durante a execução do orçamento em que deveriam ter sido incluídos, caso fosse observada à regra geral, prevista no §5º do artigo 100 da CF/88.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2592, 2, '2.1.3.1.1.07.03.00.00.00', 'PRECATÓRIOS DE CONTAS A PAGAR - REGIME ESPECIAL - A PARTIR DE 05/05/2000 - NÃO VENCIDOS', 'Registra as obrigações referentes a precatórios de contas a pagar de credores nacionais,  sujeitos ao regime especial instituído pela emenda constitucional 62/2009, a partir de 05/05/2000 (Lei de Responsabilidade Fiscal), dentro do prazo de pagamento caso fosse observada a regra geral, estabelicida no § 5º do artigo 100 da CF/88.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2593, 2, '2.1.4.1.1.11.00.00.00.00', 'PIS/PASEP A RECOLHER', 'Registra o valor das obrigações a recolher relativas ao Programa de Integração Social (PIS) e ao Programa de Formação do Patrimônio do Servidor Público (PASEP).', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2594, 2, '2.1.3.1.1.08.01.00.00.00', 'PRECATÓRIOS DE CONTAS A PAGAR - REGIME ORDINÁRIO - ANTES DE 05/05/2000 ', 'Registra as obrigações referentes a precatórios de contas a pagar de credores nacionais,  não sujeitos ao regime especial instituído pela emenda constitucional 62/2009, anteriores a 05/05/2000 (Lei de Responsabilidade Fiscal).', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2595, 2, '2.1.3.1.1.08.02.00.00.00', 'PRECATÓRIOS DE CONTAS A PAGAR - REGIME ORDINÁRIO - A PARTIR DE 05/05/2000 - VENCIDOS E NÃO PAGOS', 'Registra as obrigações referentes a precatórios de contas a pagar de credores nacionais,  não sujeitos ao regime especial instituído pela emenda constitucional 62/2009, a partir de 05/05/2000 (Lei de Responsabilidade Fiscal), não pagos durante a execução do orçamento em que deveriam ter sido incluídos em observância ao disposto no § 5º do artigo 100 da CF/88.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2596, 2, '2.1.3.1.1.08.03.00.00.00', 'PRECATÓRIOS DE CONTAS A PAGAR - REGIME ORDINÁRIO - A PARTIR DE 05/05/2000 - NÃO VENCIDOS', 'Registra as obrigações referentes a precatórios de contas a pagar de credores nacionais,  não sujeitos ao regime especial instituído pela emenda constitucional 62/2009, a partir de 05/05/2000 (Lei de Responsabilidade Fiscal), dentro do prazo de pagamento previsto no § 5º do artigo 100 da CF/88.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2597, 2, '2.1.3.1.1.09.00.00.00.00', 'FORNECEDORES NACIONAIS - DECISÕES JUDICIAIS - EXCETO PRECATÓRIOS', 'Registra as obrigações decorrentes de decisões judiciais referentes a fornecedores nacionais, exceto precatórios.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2598, 2, '2.1.3.1.1.10.00.00.00.00', 'CONTAS A PAGAR NACIONAIS - DECISÕES JUDICIAIS - EXCETO PRECATÓRIOS', 'Registra as obrigações decorrentes de decisões judiciais referentes a contas a pagar de credores nacionais, exceto precatórios.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2599, 2, '2.1.3.2.1.01.01.00.00.00', 'FORNECEDORES NÃO FINANCIADOS A PAGAR', 'Registra os valores a pagar não financiados, ou seja, em uma única parcela, aos fornecedores nacionais de bens, materiais e serviços envolvidos com as atividades operacionais da entidade.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2600, 2, '2.1.3.2.1.01.02.00.00.00', 'FORNECEDORES FINANCIADOS A PAGAR', 'Registra os valores a pagar financiados diretamente com fornecedores nacionais de bens, materiais e serviços envolvidos com as atividades operacionais da entidade.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2601, 2, '2.1.4.1.3.08.00.00.00.00', 'CIDE A RECOLHER', 'Registra os valores das obrigações exigíveis a curto prazo relativas à Contribuição de Intervenção no Domínio Econômico (CIDE) (Lei nº 10.168/2000).', 2, true, 2, 'X');
