insert into contabilidade.planocontadetalhe values (2659, 2, '2.1.4.3.5.08.00.00.00.00', 'TAXA DE INSPEÇÃO VEICULAR', 'Registra os compromissos exigíveis a Curto Prazo, decorrentes da Taxa de Inspeção Veicular.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2660, 2, '2.1.4.3.5.99.00.00.00.00', 'OUTROS TRIBUTOS E CONTRIBUIÇÕES MUNICIPAIS A RECOLHER', 'Registra os compromissos exigíveis a Curto Prazo, decorrentes da incidência de tributos para os quais não haja contas especificas.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2661, 2, '2.1.7.1.1.01.00.00.00.00', 'PROVISÃO PARA INDENIZAÇÕES TRABALHISTAS', 'Registra os valores das provisões constituídas visando o pagamento de indenizações trabalhistas.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2662, 2, '2.1.7.1.1.02.00.00.00.00', 'PROVISÃO PARA PAGAMENTO DE DISSÍDIOS COLETIVOS', 'Registra os valores das provisões constituídas visando o pagamento de dissídios coletivos.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2663, 2, '2.1.7.3.1.01.01.00.00.00', 'PROVISÃO PARA PAGAMENTO DE AUTOS DE INFRAÇÃO NÃO RECORRIDOS', 'Registra os valores das provisões para pagamento de autos de infração já lavrados, para os quais a unidade ainda não apresentou recurso administrativo.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2664, 2, '2.1.7.3.1.01.02.00.00.00', 'PROVISÃO PARA PAGAMENTO DE AUTOS DE INFRAÇÃO RECORRIDOS', 'Registra os valores das provisões para pagamento de autos de infração já lavrados, para os quais a unidade apresentou recurso administrativo.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2665, 2, '2.1.7.3.1.02.01.00.00.00', 'PROVISÃO PARA PAGAMENTOS DE AUTUAÇÕES FISCAIS NA ESFERA JUDICIAL NÃO RECORRIDAS', 'Registra os valores das provisões para pagamento de autuações fiscais que se encontram na esfera judicial e que não estão em fase recursal.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2666, 2, '2.1.7.3.1.02.02.00.00.00', 'PROVISÃO PARA PAGAMENTOS DE AUTUAÇÕES FISCAIS NA ESFERA JUDICIAL RECORRIDAS', 'Registra os valores das provisões para pagamento de autuações fiscais que se encontram na esfera judicial em fase recursal.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2667, 2, '2.1.7.4.1.02.00.00.00.00', 'PROVISÃO PARA PAGAMENTO DE SEGUROS - SINISTROS A LIQUIDAR', 'Registra os valores das provisões para pagamento de seguros referentes a sinistros a liquidar.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2668, 2, '2.1.7.4.1.03.00.00.00.00', 'PROVISÃO PARA PAGAMENTO DE SEGUROS - SINISTROS CIENTIFICADOS', 'Registra os valores das provisões para pagamento de seguros referentes a sinistros já cientificados.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2669, 2, '2.1.7.4.1.04.00.00.00.00', 'PROVISÃO PARA PAGAMENTO DE SEGUROS - SINISTROS NÃO CIENTIFICADOS', 'Registra os valores das provisões para pagamento de seguros referentes a sinistros não cientificados.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2671, 2, '2.1.7.9.1.02.00.00.00.00', 'PROVISÃO PARA REESTRUTURAÇÃO', 'Registra os valores das provisões destinadas a cobrir obrigações oriundas da venda ou extinção de uma linha de negócios, fechamento de fábricas ou locais de negócios, mudanças na estrututa da administração e reorganizações com efeito relevante na natureza e foco das operações da entidade.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (2672, 2, '2.1.7.9.1.99.00.00.00.00', 'OUTRAS PROVISÕES A CURTO PRAZO', 'Registra os valores das provisões não classificáveis nas demais contas deste plano de contas.', 2, true, 2, 'p');
insert into contabilidade.planocontadetalhe values (2673, 2, '2.1.8.3.1.01.00.00.00.00', 'ARRENDAMENTO OPERACIONAL A PAGAR', 'Registra as obrigações a curto prazo referentes a arrendamentos mercantis, nos quais não são transferidos ao arrendador os riscos e benefícios inerentes a propriedade, não havendo a possibilidade de opção de compra do bem arrendado.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2674, 2, '2.1.8.4.1.01.00.00.00.00', 'DEBÊNTURES CONVERSÍVEIS EM AÇÕES NO CURTO PRAZO', 'Registra os títulos emitidos pela entidade que conferirão aos seus titulares direito de credito contra ela, nas condições constantes da escritura de emissão do título e que são conversíveis em ações, com vencimento até o termino do exercício seguinte.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2675, 2, '2.1.8.4.1.02.00.00.00.00', 'DEBÊNTURES NÃO-CONVERSÍVEIS EM AÇÕES NO CURTO PRAZO', 'Registra os títulos emitidos pela entidade que conferirão aos seus titulares direito de credito contra ela, nas condições constantes da escritura de emissão do título e que não são conversíveis em ações, com vencimento até o termino do exercício seguinte.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2676, 2, '2.1.8.4.1.96.00.00.00.00', 'ÁGIO NA EMISSÃO DE DEBÊNTURES', 'Registra os valores de ágio na emissão de debentures, que são os valores recebidos que supera o de resgate desses títulos na data do próprio recebimento ou do valor formalmente atribuído as debentures.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2677, 2, '2.1.8.4.1.99.00.00.00.00', 'OUTROS TÍTULOS', 'Registra outros títulos de dívida com vencimento até o termino do exercício seguinte.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2678, 2, '2.1.8.6.1.01.00.00.00.00', 'OBRIGAÇÕES DECORRENTES DE ATIVOS CONSTRUÍDOS PELA SPE', 'Compreende os passivos decorrentes dos contratos de Parceria Público Privada - PPP. Deve abranger a contraprestação referente à incorporação dos ativos.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2679, 2, '2.1.8.6.1.02.00.00.00.00', 'OBRIGAÇÕES DECORRENTES DA CONTRAPRESTAÇÃO DE SERVIÇOS EM CONTRATOS DE PPP', 'Compreende os passivos decorrentes dos contratos de Parceria Público Privada - PPP. Deve abranger a contraprestação referente à prestação dos serviços objeto do contrato, incluindo a parcela variável condicionada à qualidade do serviço.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2680, 2, '2.1.8.8.1.04.01.00.00.00', 'DEPÓSITOS E CAUÇÕES', 'Registra os valores das obrigações exigíveis contraídas com o recebimento de depósitos e/ou cauções vinculados a contratos ou outros instrumentos, para garantias de operações específicas.', 2, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (2681, 2, '2.1.8.8.1.01.01.00.00.00', 'RPPS - RETENÇÕES SOBRE VENCIMENTOS E VANTAGENS', 'Registra o valor das retenções procedidas em pagamentos de servidores a ser recolhido ao RPPS do servidor.', 2, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (2682, 2, '2.1.8.8.1.01.02.00.00.00', 'INSS', 'Registra o valor das retenções procedidas em pagamentos de empregados regidos pela consolidação das leis do trabalho (CLT) ou de serviços de terceiros, a ser recolhido ao instituto nacional do seguro social/previdência social.', 2, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (2683, 2, '2.1.8.8.1.01.03.00.00.00', ' ENCARGOS SOCIAIS - OUTRAS ENTIDADES', 'Registra o valor a ser recolhido a outras entidades, em função de dispositivos legais com as quais a entidade mantenha convenio de arrecadação direta. Exemplo: FNDE, INCRA, DPC, SENAI, SESI, SENAC, FAER, SEBRAE, SENAT, SESCOOP, SESC.', 2, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (2684, 2, '2.1.8.8.1.01.04.00.00.00', 'IMPOSTO SOBRE A RENDA RETIDO NA FONTE - IRRF', 'Registra os valores referentes as retenções na fonte, pela entidade, do imposto sobre a renda, relativas as importâncias pagas a terceiros ou creditadas a servidores ou empregados, sobre as quais incida o referido imposto.', 2, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (2685, 2, '2.1.8.8.1.01.05.00.00.00', 'INDENIZAÇÕES E RESTITUIÇÕES', 'Registra os valores relativos as indenizações e restituições de tributos com autorizações concedidas, porém não devolvidas aos legítimos credores pela entidade.', 2, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (2686, 2, '2.1.8.8.1.01.06.00.00.00', 'IMPOSTOS E CONTRIBUIÇÕES DIVERSOS', 'Registra os valores referentes as retenções na fonte, pela entidade, de impostos e contribuições diversos, relativas as importâncias pagas a terceiros, sobre os quais incidam os referidos tributos.', 2, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (2687, 2, '2.1.8.8.1.01.07.00.00.00', ' ICMS ', 'Registra os valores relativos ao imposto sobre a circulação de mercadorias e serviços retidos por força de legislação ou por acordo entre as partes envolvidas na transação em consignações.', 2, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (2688, 2, '2.1.8.8.1.01.08.00.00.00', ' ISS ', 'Registra os valores do imposto sobre serviços retidos em consignações por forca de legislação, circunstancias ou acordo entre as partes envolvidos na transação, em situações que a entidade como parte contratante, atue como substituta tributária.', 2, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (2689, 2, '2.1.8.8.1.01.09.00.00.00', 'OUTROS TRIBUTOS ESTADUAIS E MUNICIPAIS', 'Registra os valores em consignação relativos a outros tributos a serem repassados aos estados e municípios.', 2, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (2690, 2, '2.1.8.8.1.01.10.00.00.00', 'PENSÃO ALIMENTÍCIA', 'Registra os valores das retenções em folha procedidas em pagamentos a empregados ou a servidores, autorizados por esses ou por determinação judicial, a título de pensão alimentícia.', 2, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (2691, 2, '2.1.8.8.1.01.11.00.00.00', 'PLANOS DE PREVIDÊNCIA E ASSISTÊNCIA MÉDICA', 'Registra os descontos efetuados em folhas de pagamento do pessoal para posterior recolhimento a favor de instituições de previdência e assistência médica.', 2, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (2692, 2, '2.1.8.8.1.01.12.00.00.00', 'ASSISTÊNCIA A SAÚDE - ADMINISTRAÇÃO PRÓPRIA', 'Registra os valores das consignações retidos pela entidade, ou entregues a essa, que serão administrados pelo próprio órgão/entidade para assistência a saúde de seus servidores.', 2, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (2693, 2, '2.1.8.8.1.01.13.00.00.00', 'RETENÇÕES - ENTIDADES REPRESENTATIVAS DE CLASSES', 'Registra os descontos efetuados em folhas de pagamento de pessoal para posterior recolhimento a favor de instituições representativas de classe.', 2, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (2694, 2, '2.1.8.8.1.01.14.00.00.00', 'RETENÇÕES - PLANOS DE SEGUROS', 'Registra os valores das retenções efetuadas em folha de pagamento dos servidores referentes as contribuições a planos de seguro de vida em grupo.', 2, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (2695, 2, '2.1.8.8.1.01.15.00.00.00', 'RETENÇÕES - EMPRÉSTIMOS E FINANCIAMENTOS', 'Registra os valores das retenções efetuadas em folha de pagamento dos servidores referentes a empréstimos e financiamentos concedidos por terceiros, bem como retenções de parcelas de consórcios e segurados do INSS.', 2, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (2696, 2, '2.1.8.8.1.01.16.00.00.00', 'RETENÇÃO RELATIVA A VALE TRANSPORTE', 'Registra os valores das consignações retidas pela entidade a serem repassados para as empresas prestadoras dos serviços de fornecimento de vale-transporte. Trata-se dos valores referentes aos 6% instituídos pelo artigo 9º do decreto nº 95.247/1987 e suas alterações.', 2, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (2697, 2, '2.1.8.8.1.01.17.00.00.00', 'RETENÇÃO RELATIVA A VALE ALIMENTAÇÃO', 'Registra os valores das consignações retidas pela entidade a serem repassados para as empresas prestadoras dos serviços de fornecimento de cartão-alimentação/refeição.', 2, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (2698, 2, '2.1.8.8.1.01.99.00.00.00', 'OUTROS CONSIGNATÁRIOS', 'Registra os valores das consignações retidos pela entidade, ou entregues a essa, em confiança, por diversos contribuintes sujeitos a recolhimentos e ou pagamentos aos favorecidos.', 2, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (2699, 2, '2.1.8.8.1.02.00.00.00.00', 'GARANTIAS', 'Registra a garantia do cumprimento de uma obrigação, que se efetiva com o oferecimento de bens ou recursos financeiros ou ainda retenções de um percentual do valor do contrato como garantia de cumprimento do mesmo.', 2, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (2700, 2, '2.1.8.8.1.03.01.00.00.00', 'DEPÓSITOS RECEBIDOS POR DETERMINAÇÃO JUDICIAL', 'Registra os valores de obrigações, decorrentes de depósitos recebidos por determinação judicial.', 2, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (2701, 2, '2.1.8.8.1.03.02.00.00.00', 'DEPÓSITOS PARA RECURSOS JUDICIAIS', 'Registra os valores relativos as obrigações contraídas por depósitos efetuados a favor da entidade destinados ao exercício de direito de recurso junto a justiça e encontrados vinculados em contas bancárias.', 2, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (2702, 2, '2.2.1.1.1.01.00.00.00.00', 'PESSOAL A PAGAR', 'Registra os valores relativos a vencimentos e vantagens fixas e variáveis devidas aos servidores civis e militares, bem como as aposentadorias, reformas e pensões.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2703, 2, '2.1.8.8.1.04.02.00.00.00', 'DEPÓSITOS ESPECIAIS', 'Registra o valor relativo a retenções de depósitos vinculados a restituir no curso do exercício seguinte a entidade transferidora, decorrente de contratos ou instrumentos congêneres, convenção, acordo ou ajuste.', 2, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (2704, 2, '2.1.8.8.1.04.03.00.00.00', 'DEPÓSITOS DE TERCEIROS', 'Registra os valores relativos aos depósitos de terceiros de diversas origens, inclusive desconhecidas, não reclamados pelos credores.', 2, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (2705, 2, '2.1.8.8.1.04.04.00.00.00', 'DEPÓSITOS DE VEICULOS ALIENÁVEIS', 'Registra o valor dos recebimentos provenientes da alienação de veículos removidos, recolhidos ou apreendidos de acordo com a Resolução do Contran nº 178/2005, pendentes de transferências diversas.', 2, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (2706, 2, '2.1.8.8.1.04.05.00.00.00', 'DEPÓSITOS A TRANSFERIR', 'Registra os valores das retenções de depósitos de diversas origens recebidos por UG central cuja devolução deve ser realizada no curso do exercício seguinte.', 2, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (2707, 2, '2.1.8.8.1.04.99.00.00.00', 'OUTROS DEPÓSITOS', 'Registra compromissos exigíveis até o término do exercício seguinte, decorrentes de recebimentos a título de depósitos, para os quais não haja contas específicas.', 2, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (2708, 2, '2.1.8.8.1.99.00.00.00.00', 'OUTROS VALORES RESTITUÍVEIS', 'Registra outros valores restituíveis em posse da entidade, no papel de fiel depositária.', 2, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (2709, 2, '2.1.8.9.1.01.01.00.00.00', 'INDENIZAÇÕES A SERVIDORES', 'Registra o valor das despesas a serem indenizadas decorrentes de liquidação de pagamentos efetuados com auxílio - alimentação bem como reembolsos de gastos realizados pelos servidores custeados pelo programa de assistência a saúde e benefícios sociais do órgão responsável.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2710, 2, '2.1.8.9.1.01.02.00.00.00', 'INDENIZAÇÕES E RESTITUIÇÕES DIVERSAS DO EXERCÍCIO', 'Registra os valores relativos as diversas indenizações e restituições no exercÍcio.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2711, 2, '2.1.8.9.1.01.03.00.00.00', 'INDENIZAÇÕES E RESTITUIÇÕES DIVERSAS DE EXERCÍCIOS ANTERIORES', 'Registra os valores relativos as diversas indenizações e restituições de exercÍcios anteriores.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2712, 2, '2.1.8.9.1.01.04.00.00.00', 'RESTITUIÇÕES DE CONTRIBUIÇÕES PREVIDENCIÁRIAS', 'Registra os valores relativos a restituições de contribuições previdenciárias a pagar.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2713, 2, '2.1.8.9.1.02.00.00.00.00', 'DIÁRIAS A PAGAR', 'Registra os valores relativos as diárias a pagar.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2714, 2, '2.1.8.9.1.03.00.00.00.00', 'SUPRIMENTOS DE FUNDOS A PAGAR', 'Registra os valores relativos aos suprimentos de fundos a pagar.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2715, 2, '2.1.8.9.1.05.01.00.00.00', 'CONVÊNIOS A PAGAR DO EXERCÍCIO', 'Registra os valores a pagar referentes a convênios firmados no exercício.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2716, 2, '2.1.8.9.1.05.02.00.00.00', 'CONVÊNIOS A PAGAR DE EXERCÍCIOS ANTERIORES', 'Registra os valores a pagar referentes a convênios firmados em exercícios anteriores.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2717, 2, '2.1.8.9.1.09.01.00.00.00', 'TERMOS DE PARCERIA A PAGAR DO EXERCÍCIO', 'Registra os valores a pagar referentes a termos de parceria firmados no exercício.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2718, 2, '2.1.8.9.1.09.02.00.00.00', 'TERMOS DE PARCERIA A PAGAR DE EXERCÍCIOS ANTERIORES', 'Registra os valores a pagar referentes a termos de parceria firmados em exercícios anteriores.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2719, 2, '2.1.8.9.1.10.00.00.00.00', 'TERMO DE COMPROMISSO A PAGAR', 'Registra os valores a pagar retidos a título de termo de compromisso.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2720, 2, '2.2.1.3.1.01.00.00.00.00', 'BENEFÍCIOS ASSISTENCIAIS A PAGAR', 'Registra os valores das obrigações relativas aos benefícios assistenciais.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2721, 2, '2.1.8.9.1.11.00.00.00.00', 'CONTRATOS DE GESTÂO A PAGAR', 'Registra as obrigações relativas aos contratos entre a administração publica e a iniciativa privada para gestão de atividades tipicas de governo.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2722, 2, '2.1.8.9.1.12.00.00.00.00', 'SUBVENÇÕES A PAGAR', 'Registra o somatório das subvenções a pagar de exercícios anteriores.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2723, 2, '2.1.8.9.1.13.00.00.00.00', 'TRANSFERÊNCIAS ORÇAMENTÁRIAS A LIBERAR ', 'Registra os compromissos exigíveis provenientes da apropriação da despesa de transferência.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2724, 2, '2.1.8.9.1.14.00.00.00.00', 'CONSÓRCIOS A PAGAR', 'Registra as obrigações a pagar junto a consórcios.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2725, 2, '6.3.2.2.0.00.00.00.00.00', 'RP PROCESSADOS PAGOS', 'Registra o valor dos RP processados pagos.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (2726, 2, '2.2.1.1.1.03.01.00.00.00', 'PRECATÓRIOS DE PESSOAL - REGIME ESPECIAL - ANTES DE 05/05/2000 ', 'Registra as obrigações referentes a precatórios de proventos de aposentadoria, reformas ou pensões,  sujeitos ao regime especial instituído pela emenda constitucional 62/2009, anteriores a 05/05/2000 (Lei de Responsabilidade Fiscal).', 2, true, 2, 'X');
