insert into contabilidade.planocontadetalhe values (2809, 2, '2.2.3.1.1.01.03.00.00.00', 'PARCELAMENTO DE FORNECEDORES A PAGAR', 'Registra o parcelamento de dívidas com fornecedores a pagar.', 2, true, 2, 'X');
