insert into contabilidade.planocontadetalhe values (2811, 2, '2.2.3.1.1.04.01.00.00.00', 'PRECATÓRIOS DE FORNECEDORES NACIONAIS - REGIME ESPECIAL - ANTES DE 05/05/2000 ', 'Registra as obrigações referentes a precatórios de fornecedores nacionais,  sujeitos ao regime especial instituído pela emenda constitucional 62/2009, anteriores a 05/05/2000 (Lei de Responsabilidade Fiscal).', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2812, 2, '2.2.3.1.1.04.02.00.00.00', 'PRECATÓRIOS DE FORNECEDORES NACIONAIS - REGIME ESPECIAL - A PARTIR DE 05/05/2000 - VENCIDOS E NÃO PAGOS', 'Registra as obrigações referentes a precatórios de fornecedores nacionais,  sujeitos ao regime especial instituído pela emenda constitucional 62/2009, a partir de 05/05/2000 (Lei de Responsabilidade Fiscal), não pagos durante a execução do orçamento em que deveriam ter sido incluídos, caso fosse observada à regra geral, prevista no §5º do artigo 100 da CF/88.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2813, 2, '2.2.3.1.1.04.03.00.00.00', 'PRECATÓRIOS DE FORNECEDORES NACIONAIS - REGIME ESPECIAL - A PARTIR DE 05/05/2000 - NÃO VENCIDOS', 'Registra as obrigações referentes a precatórios de fornecedores nacionais,  sujeitos ao regime especial instituído pela emenda constitucional 62/2009, a partir de 05/05/2000 (Lei de Responsabilidade Fiscal), dentro do prazo de pagamento caso fosse observada a regra geral, estabelicida no § 5º do artigo 100 da CF/88.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2814, 2, '2.2.3.1.1.05.01.00.00.00', 'PRECATÓRIOS DE FORNECEDORES NACIONAIS - REGIME ORDINÁRIO - ANTES DE 05/05/2000 ', 'Registra as obrigações referentes a precatórios de fornecedores nacionais,  não sujeitos ao regime especial instituído pela emenda constitucional 62/2009, anteriores a 05/05/2000 (Lei de Responsabilidade Fiscal).', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2815, 2, '2.2.3.1.1.05.02.00.00.00', 'PRECATÓRIOS DE FORNECEDORES NACIONAIS - REGIME ORDINÁRIO - A PARTIR DE 05/05/2000 - VENCIDOS E NÃO PAGOS', 'Registra as obrigações referentes a precatórios de fornecedores nacionais,  não sujeitos ao regime especial instituído pela emenda constitucional 62/2009, a partir de 05/05/2000 (Lei de Responsabilidade Fiscal), não pagos durante a execução do orçamento em que deveriam ter sido incluídos em observância ao disposto no § 5º do artigo 100 da CF/88.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (2816, 2, '2.2.3.1.1.05.03.00.00.00', 'PRECATÓRIOS DE FORNECEDORES NACIONAIS - REGIME ORDINÁRIO - A PARTIR DE 05/05/2000 - NÃO VENCIDOS', 'Registra as obrigações referentes a precatórios de fornecedores nacionais,  não sujeitos ao regime especial instituído pela emenda constitucional 62/2009, a partir de 05/05/2000 (Lei de Responsabilidade Fiscal), dentro do prazo de pagamento previsto no § 5º do artigo 100 da CF/88.', 2, true, 2, 'X');
