insert into contabilidade.planocontadetalhe values (2973, 2, '4.2.1.1.5.01.02.00.00.00', 'CONTR.PATRONAL - PAGTO SENTENCAS JUDICIAIS - RPPS', 'Registra a VPA de recolhimento da contribuição patronal, oriunda do pagamento de sentenças judiciais.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (2974, 2, '4.2.1.1.5.99.00.00.00.00', 'OUTRAS CONTRIBUIÇÕES SOCIAIS - RPPS', 'Registra o valor das vpa oriundas de contribuições previdenciarias nao en-quadradas nos subitens anteriores.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (2975, 2, '4.2.1.9.1.01.01.00.00.00', 'CONTRIBUICAO DOS SERVIDORES ATIVOS PARA A ASSISTENCIA SOCIAL DO SERVIDOR', 'Registra o valor total da contribuição do servidor ativo para a assistência social do servidor', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (2976, 2, '4.2.1.9.1.01.02.00.00.00', 'CONTRIBUICAO SERVIDORES INATIVOS E PENSIONISTAS PARA A ASSISTENCIA SOCIAL DO SERVIDOR', 'Registra o valor total da contribuição do servidor inativo e pensionistas para a assistência social do servidor.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (2977, 2, '4.2.1.9.1.01.03.00.00.00', 'CONTRIBUICAO DOS SERVIDORES ATIVOS PARA A ASSISTENCIA MEDICA DO SERVIDOR', 'Registra o valor total da contribuição do servidor ativo para a assistência medica do servidor', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (2978, 2, '4.2.1.9.1.01.04.00.00.00', 'CONTRIBUICAO DOS SERVIDORES INATIVOS PARA A ASSISTENCIA MEDICA DO SERVIDOR', 'Registra o valor total da contribuição do servidor inativo para a assistência medica do servidor', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (2979, 2, '4.2.1.9.1.01.05.00.00.00', 'CONTRIBUICAO DOS PENSIONISTAS PARA A ASSISTENCIA MEDICA DO SERVIDOR', 'Registra o valor total da contribuição do pensionista para a assistência medica do servidor', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (2980, 2, '4.2.1.9.1.96.00.00.00.00', 'OUTRAS CONTRIBUICOES SOCIAIS', 'Registra o valor das VPA oriundas de contribuições sociais não enquadradas nos subitens anteriores.                                    ', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3160, 2, '4.6.2.3.1.01.00.00.00.00', 'GANHOS COM ALIENAÇÃO DE SOFTWARES', 'Registra a variação patrimonial aumentativa de ganhos com alienação de softwares.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (2981, 2, '4.2.3.0.1.01.00.00.00.00', 'CONTRIBUIÇÃO DE ILUMINAÇÃO PÚBLICA ', 'Registra as contribuições de iluminação pública, nos termos do artigo 149-a da constituição federal, acrescentado pela emenda constitucional n.ºª 39/02, sendo facultada a cobrança da contribuição na fatura de consumo de energia elétrica.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (2982, 2, '4.3.3.1.1.01.00.00.00.00', 'PRESTAÇÃO DE SERVICOS DE TREINAMENTO', 'Registra as variações patrimoniais aumentativas provenientes da prestação de instrução.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (2983, 2, '4.3.3.1.1.02.00.00.00.00', 'EXPLORAÇÃO DO PATRIMONIO IMOBILIÁRIO', 'Registra o valor das variações patrimoniais aumentativas provenientes da utilização, por terceiros, de bens imóveis pertencentes ao setor público.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (2984, 2, '4.3.3.1.1.03.00.00.00.00', 'PRESTAÇÃO DE SERVIÇOS DE LOCAÇÃO', 'Registra as variações patrimoniais aumentativas provenientes de alugueis, exceto alugueis de imóveis, que já possui rubrica própria.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (2985, 2, '4.3.3.1.1.04.00.00.00.00', 'PRESTAÇÃO DE SERVIÇOS DE PESQUISAS E ANÁLISES', 'Registra as variações patrimoniais aumentativas provenientes da prestação de serviços de pesquisas e analise.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (2986, 2, '4.3.3.1.1.05.00.00.00.00', 'SERVIÇOS DE ESTUDOS E PESQUISAS', 'Registra as variações patrimoniais aumentativas provenientes de serviços de pesquisas e estudos técnico-sociais, econômicos, científicos, culturais etc., realizadas sob contrato.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (2987, 2, '4.3.3.1.1.06.00.00.00.00', 'PRESTAÇÃO DE SERVIÇOS DE CONSULTORIA', 'Registra as variações patrimoniais aumentativas provenientes da prestação de serviços de assessoria e consultoria.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (2988, 2, '4.6.2.2.1.02.01.00.00.00', 'PRODUTO DE ALIENAÇÕES', 'Registra o ganho com alienação de ativo imobilizado, ou seja, quando o valor alienado do referido ativo e maior que o seu valor contábil, de maneira que a diferença compreende o ganho - Produtos de Alienações.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (2989, 2, '4.3.3.1.1.07.00.00.00.00', 'SERVIÇOS CONSULT. ASSIST. TEC. ANÁLISE PROJETOS', 'Registra as variações patrimoniais aumentativas provenientes de serviços de consultoria, assistência técnica e análise de projetos prestados. VPA proporcionada por consultorias técnico-financeiras, assessoria, organização e administração de empresas, auditoria, contabilidade e escrituração, perícias contábeis, análise de projetos, etc.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (2990, 2, '4.3.3.1.1.08.00.00.00.00', 'PRESTAÇÃO DE SERVIÇOS RELACIONADOS A T.I.', 'Registra as variações patrimoniais aumentativas provenientes da prestação de serviços relacionados a tecnologia da informação.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (2991, 2, '4.3.3.1.1.09.00.00.00.00', 'PRESTAÇÃO DE SERVIÇOS DE ADM. DE REDE DE COMUNIC. DE DADOS', 'Registra as variações patrimoniais aumentativas provenientes da prestação serviços de gerenciamento de redes de comunicação de dados.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (2992, 2, '4.3.3.1.1.10.00.00.00.00', 'SERVICOS DE PROCESSAMENTO DE DADOS', 'Registra as variações patrimoniais aumentativas provenientes de serviços de processamentos de dados prestados. VPA decorrente de prestação de serviços de processamento de dados para terceiros: preparo de programa, análise de sistemas, digitação, conferencia, etc.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (2993, 2, '4.3.3.1.1.11.00.00.00.00', 'SERVIÇO DE INFORMAÇÕES CIENTÍFICAS E TECNOLÓGICAS', 'Registra as variações patrimoniais aumentativas provenientes de serviços de informações científicas e tecnológicas.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (2994, 2, '4.3.3.1.1.98.00.00.00.00', 'SERVIÇOS ADMINISTRATIVOS - RPPS', 'Registra as variações patrimoniais aumentativas provenientes de serviços administrativos prestados pelo RPPS, geralmente remunerados por meio de taxa de administração de serviços. ', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (2995, 2, '4.3.3.1.1.13.00.00.00.00', 'SERVIÇOS DE TECNOLOGIA', 'Registra as variações patrimoniais aumentativas provenientes de serviços tecnológicos prestados. VPA proporcionada por: a) analises químicas, ensaios físicos e mecânicos, controle e experimentação qualitativa de matérias-primas, insumos e produtos fabricados; padronização e especificação de produtos; ajustes dos processos e técnicas de produção industrial (sistema de tecnologia)b) especificação e controle de qualidade de medicamentos, insumos farmacêuticos, drogas, cosméticos, produtos químicos, alimentos, e outros, por meio de provas especificas de identificação, de pureza e de testes de contaminação microbiológica.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (2996, 2, '4.3.3.1.1.14.00.00.00.00', 'SERVIÇOS DE COMUNICAÇÃO', 'Registra as variações patrimoniais aumentativas provenientes de atividades de comunicação, conforme descrição abaixo: a) serviço postal, de entrega e transporte de volumes e correspondências; b) serviço de comunicação telefônica local, interurbana e internacional e de transmissão de dados; c) serviço de radiodifusão e de agenciamento de publicidade.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (2997, 2, '4.3.3.1.1.15.00.00.00.00', 'PRESTAÇÃO DE SERVIÇOS RELACIONADOS A ARMAZENAGEM', 'Registra as variações patrimoniais aumentativas provenientes da prestação de serviços de armazenagem.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (2998, 2, '4.3.3.1.1.16.00.00.00.00', 'PRESTAÇÃO DE SERVIÇOS COMPLEMENTARES', 'Registra as variações patrimoniais aumentativas provenientes da prestação de serviços complementares quando da estocagem em armazenagem.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (2999, 2, '4.3.3.1.1.17.00.00.00.00', 'PRESTAÇÃO DE SERVIÇOS RELACIONADOS AO BENEFICIAMENTO DE GRÃOS', 'Registra as variações patrimoniais aumentativas provenientes da prestação de serviços de beneficiamento de grãos.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3000, 2, '4.3.3.1.1.20.00.00.00.00', 'FORNECIMENTO DE MÃO-DE-OBRA', 'Registra as variações patrimoniais aumentativas provenientes do fornecimento de mão-de-obra.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3001, 2, '4.3.3.1.1.21.00.00.00.00', 'PRESTAÇÃO DE SERVIÇOS DE DISTRIB. DE GÊNEROS ALIMENTÍCIOS', 'Registra as variações patrimoniais aumentativas provenientes da prestação de serviços de distribuição de gêneros alimentícios.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3002, 2, '4.3.3.1.1.22.00.00.00.00', 'SERVICOS DE HOSPEDAGEM E ALIMENTAÇÃO', 'Registra as variações patrimoniais aumentativas provenientes de serviços de hospedagem e alimentação prestados. VPA proporcionada por hospedagem, com ou sem alimentação, fornecimento de refeições, lanches e bebidas para consumo imediato. Excluem as VPA provenientes de empresas fornecedoras de alimentos preparados para hospitais, fabricas, etc. Que se classificam em VPA de produtos alimentares.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3003, 2, '4.3.3.1.1.23.00.00.00.00', 'CONCESSAO E PERMISSAO - SERV. DE TRANSPORT', 'Registra as variações patrimoniais aumentativas associadas a outorga dos serviços públicos de transporte a iniciativa privada, proveniente da atuação da fiscalização, da normatização e do controle dos serviços concedidos.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3004, 2, '4.3.3.1.1.24.00.00.00.00', 'OUTORGA SERV. EXPL. PROD PETR. GAS NATURAL', 'Registra as variações patrimoniais aumentativas provenientes de atividades de exploração, desenvolvimento e produção de petróleo e gás natural, exercidas mediante contratos de concessão.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3005, 2, '4.3.3.1.1.25.00.00.00.00', 'OUTORGA DE DIREITOS DE USO DE REC. HIDR.', 'Registra as variações patrimoniais aumentativas provenientes de outorga a particulares de direitos de uso da agua.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3006, 2, '4.3.3.1.1.26.00.00.00.00', 'OUTORGA DIREITOS DE EXPL. E PESQ. MINER', 'Registra as variações patrimoniais aumentativas provenientes da compensação financeira pela exploração de recursos minerais devido por todas as empresas que realizam o aproveitamento de uma jazida mineral garantida a essas a propriedade do produto da lavra.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3007, 2, '4.3.3.1.1.27.00.00.00.00', ' CONCESSÃO FLORESTAL', 'Registra as variações patrimoniais aumentativas provenientes de atividades de exploração e gestão de direitos de uso de florestas públicas, recursos florestais, produtos e serviços delas decorrentes, para produção sustentável, exercidas mediante contratos de concessão, a particulares que estejam em condições de atender as exigências do respectivo edital de licitação e que demonstrem capacidade para seu desempenho, por sua conta e risco e prazo determinado.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3008, 2, '4.3.3.1.1.28.00.00.00.00', 'CONCESSÃO E PERMISSÃO - DIR. USO DE BENS PÚBLICOS', 'Registra as variações patrimoniais aumentativas provenientes da utilização e exploração de bens públicos por terceiros.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3009, 2, '4.3.3.1.1.29.00.00.00.00', 'COMPENSAÇÕES FINANCEIRAS', 'Registra as variações patrimoniais aumentativas provenientes dos recursos decorrentes do artigo 20, parágrafo 1º da constituição federal, o qual dispõe: "e assegurada, nos termos da lei, aos estados, ao distrito federal e aos municípios, bem como aos órgãos da administração direta da União, participação no resultado da exploração de petróleo ou gás natural, de recursos hídricos para fins de geração de energia elétrica e de outros recursos minerais no respectivo território, plataforma continental, mar territorial ou zona economia exclusiva, ou compensação financeira por essa exploração".', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3010, 2, '4.3.3.1.1.30.00.00.00.00', 'SERVICOS DE TRANSPORTE', 'Registra as variações patrimoniais aumentativas provenientes de serviços de transporte rodoviário, ferroviário, hidroviário, aéreo, especiais e tarifa de pedágio.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3011, 2, '4.3.3.1.1.31.00.00.00.00', 'SERVICOS PORTUARIOS', 'Registra as variações patrimoniais aumentativas provenientes de serviços portuários. Abrangem os recursos oriundos da exploração dos portos, terminais marítimos, atracadouros e ancoradouros, referentes a estiva, desestiva, dragagem, atracação, sinalização, comunicação náutica, docagem, etc....', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3012, 2, '4.6.5.3.1.01.00.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL DE SOFTWARES', 'Registra a variação patrimonial aumentativa com a reversão de redução a valor recuperável de serviços de softwares.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3013, 2, '4.3.3.1.1.32.00.00.00.00', 'SERVICOS DE SOCORRO MARITIMO', 'Registra as variações patrimoniais aumentativas provenientes de serviço de socorro marítimo prestado. VPA de serviços de salvamento, por navio de socorro ou equipe de salvamento da marinha, de embarcação e cargas perigosas (desencalhe, mergulho, outros socorros), bem como serviços de reboque marítimo, dentre outros.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3107, 2, '4.5.2.3.4.01.00.00.00.00', 'CONTRIBUIÇÕES', 'Registra a variação patrimonial aumentativa decorrente de transferências correntes e de capital aos entes da Federação e a entidades privadas sem fins lucrativos, exceto para os serviços essenciais de assistência social, médica e educacional;', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3014, 2, '4.3.3.1.1.33.00.00.00.00', 'SERVICOS DE SAUDE', 'Registra as variações patrimoniais aumentativas provenientes da prestação de serviços de saúde: hospitalares gerais ou especializados, maternidade, centro de reabilitação, assistência médico-odontológica (inclusive ambulatorial), saúde pública, etc.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3015, 2, '4.3.3.1.1.34.00.00.00.00', 'CERTIFICAÇÃO E HOMOLOGAÇÃO DE PROD. TELECOM.', 'Registra as variações patrimoniais aumentativas provenientes de certificação e homologação de prod. Telecom.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3016, 2, '4.3.3.1.1.35.00.00.00.00', 'SERVIÇOS DE METROLOGIA E CERTIFICAÇÃO', 'Registra as variações patrimoniais aumentativas provenientes de serviços de metrologia e certificação prestados. VPA de serviços metrológicos em geral, tais como aferição de medidas e instrumentos de medir, serviços de arqueação de tanques para armazenagem, etc.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3017, 2, '4.3.3.1.1.36.00.00.00.00', 'SERVIÇOS DE INSPEÇÃO E FISCALIZAÇÃO', 'Registra as variações patrimoniais aumentativas provenientes de serviços de inspeção e fiscalização prestados. VPA proporcionada pela constatação das condições higiênico-sanitárias e técnicas de produtos ou estabelecimentos, ou resultantes de ação externa e direta dos órgãos do poder público destinada a verificação do cumprimento da legislação.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3018, 2, '4.3.3.1.1.37.00.00.00.00', 'SERVIÇOS ADMINISTRATIVOS', 'Registra as variações patrimoniais aumentativas provenientes de serviços administrativos prestados, das atividades de apoio administrativo executadas em organizações de qualquer natureza, tais como: a) taxas de expedição de certificados; b) taxas de registro, renovação, vistoria, licença, cadastramento, etc. C) datilografia, microfilmagem, copias xerográficas, heliográficas, fotostáticas, etc. d) taxas de inscrição em concursos. e) taxa de administração de serviços. F) venda de editais.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3019, 2, '4.3.3.1.1.38.00.00.00.00', 'SERVIÇOS DE METEOROLOGIA', 'Registra as variações patrimoniais aumentativas provenientes de serviços de meteorologia prestados. VPA proporcionada pelo fornecimento de dados meteorológicos e de pareceres técnicos, bem como conserto, comparação e aferição de equipamentos de meteorologia.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3020, 2, '4.4.2.4.1.13.00.00.00.00', 'MULTAS E JUROS DEMAIS CONTRIBUIÇÕES', 'Registra os valores relativos aos créditos aos créditos a receber, decorrentes da cobrança das demais contribuições.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3021, 2, '4.3.3.1.1.39.00.00.00.00', 'SERVIÇOS EDUCACIONAIS', 'Registra as variações patrimoniais aumentativas provenientes das atividades do sistema educacional, cuja natureza esteja diretamente relacionada a formação do educando (matriculas, anuidades, etc.). As VPA de atividades auxiliares, de apoio ou derivadas dos serviços educacionais propriamente ditos, devem ser classificadas nos títulos apropriados. Exemplos: matriculas e anuidades, serviços educacionais, taxas de expedição de documentos, copias xerográficas, heliográficas, etc, serviço de credenciamento, autorização e reconhecimento de cursos.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3022, 2, '4.3.3.1.1.40.00.00.00.00', 'SERVIÇOS AGROPECUÁRIOS', 'Registra as variações patrimoniais aumentativas provenientes de serviços agropecuário: a) preparo e correção de solos (destocamento, aração, gradeação, calagem, adubação, drenagem, irrigação, capina, desmatamento, etc.); b) semeadura e plantio; c) combate a pragas (pulverização, dedetização); d)colheita e preparação de produtos agrícolas; e)inseminação artificial; f)incubação de ovos; g)vacinação de animais; h) outros serviços auxiliares de agricultura e pecuária.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3023, 2, '4.3.3.1.1.41.00.00.00.00', 'SERVIÇOS DE REPARAÇÃO, MANUTENÇÃO E INSTALAÇÃO', 'Registra as variações patrimoniais aumentativas provenientes de serviços de reparação, manutenção e instalação prestados. VPA de serviços de reparação de artefatos de metal; reparação e manutenção de maquinas e aparelhos de uso doméstico; reparação, manutenção e instalação de maquinas e aparelhos elétricos e eletrônicos e de comunicação; reparação e manutenção de instalações elétricas, de gás, de agua, etc. incluem-se também, nesse título, os serviços de confecção sob medida. Não são considerados nesse título, classificando-se em VPA industrial: reparação e manutenção de veículos ferroviários, embarcações e aeronaves (indústria de material de transporte).', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3024, 2, '4.3.3.1.1.42.00.00.00.00', 'SERVIÇOS RECREATIVOS E CULTURAIS', 'Registra as variações patrimoniais aumentativas provenientes de serviços recreativos e culturais prestados. VPA proporcionada pela exploração de instalações para recreação, pratica desportiva e cultural (cinemas, teatros, salões para recitais, concertos, conferencias, planetários, estádios desportivos, autódromos, museus, bibliotecas, promoção e/ou produção de espetáculos artísticos culturais e esportivos).', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3025, 2, '4.3.3.1.1.44.00.00.00.00', 'SERVIÇOS DE REGISTRO DO COMÉRCIO', 'Registra as variações patrimoniais aumentativas provenientes de serviços de registro do comercio prestados. VPA advinda da prestação de serviços de registro do comercio e atividades afins, tratando-se de: a) serviços prestados pela junta comercial do distrito federal; b) serviços constantes do cadastro nacional de empresa, devidos no âmbito das juntas comerciais dos estados e do distrito federal; c) remuneração de serviços prestados pelo departamento nacional de registro do comercio.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3026, 2, '4.3.3.1.1.45.00.00.00.00', 'SERVIÇOS DE FORNECIMENTO DE ÁGUA', 'Registra as variações patrimoniais aumentativas provenientes de serviços prestados de fornecimento de agua aos irrigantes aa amortização dos investimentos da infraestrutura de irrigação dos projetos públicos, conforme dec.89.496, de 29.03de 84, relativos a tarifas k-1 e k-2.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3027, 2, '4.3.3.1.1.46.00.00.00.00', 'SERVIÇOS DE PERFURAÇÃO E INSTALAÇÃO DE POÇOS', 'Registra as variações patrimoniais aumentativas provenientes de serviços prestados de perfuração e instalação de poços tubulares profundos, poços artesianos ou similares.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3028, 2, '4.3.3.1.1.47.00.00.00.00', 'SERVIÇOS DE GEOPROCESSAMENTO', 'Registra as variações patrimoniais aumentativas provenientes de serviços prestados a terceiros de interpretação de imagem aerofotogrametrica, execução de mapas digitalizados diversos, venda de cartas e imagens de satélites, videográficas e similares.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3029, 2, '4.3.3.1.1.48.00.00.00.00', 'SERVIÇOS DE CADASTRAMENTO DE FORNECEDORES', 'Registra as variações patrimoniais aumentativas provenientes de prestação de serviços de cadastramento de empresas fornecedoras de bens e serviços ao governo federal.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3030, 2, '4.3.3.1.1.52.00.00.00.00', 'TAR.INSCR.CONCURSOS E PROCESSOS SELETIVOS', 'Registra as variações patrimoniais aumentativas provenientes de tarifas de inscrição em concursos e processos seletivos.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3031, 2, '4.3.3.1.1.54.00.00.00.00', 'GARANTIAS E AVAIS', 'Registra as variações patrimoniais aumentativas provenientes da prestação de garantias e avais nas operações de credito. Fato gerador: concessão de garantias e avais, de natureza não-financeiras.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3108, 2, '4.5.2.3.4.02.00.00.00.00', 'AUXÍLIOS', 'Registra a variação patrimonial aumentativa decorrente de transferências de capital aos entes da Federação e a entidades privadas sem fins lucrativos;', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3032, 2, '4.3.3.1.1.55.00.00.00.00', 'CREDENCIAMENTO EMP.PREST.SERVICOS DE VISTORIA', 'Registra as variações patrimoniais aumentativas provenientes do valor a ser pago por empresas na obtenção de credenciamento para prestação de serviços de vistoria. - Destinação legal: órgão arrecadador; - amparo legal: resolução CONTRAN 282, de 26 de junho de 2008.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3033, 2, '4.3.3.1.1.56.00.00.00.00', 'SERVICOS VETERINARIOS', 'Registra as variações patrimoniais aumentativas provenientes de serviços veterinários.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3034, 2, '4.3.3.1.1.59.00.00.00.00', 'SERVICOS FINANCEIROS', 'Registra as variações patrimoniais aumentativas com serviços financeiros', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3035, 2, '4.3.3.1.1.60.00.00.00.00', 'SERV. COMERCIAIS DE PRODUTOS, DADOS E MAT. INFORMÁTICA', 'Registra as variações patrimoniais aumentativas provenientes da comercialização de produtos, dados e materiais de informática, tais como disquetes, softwares, programas, CD-Rom, fitas magnéticas e assemelhados, bem como informações em redes e sistemas de dados disponíveis em meio de hardware.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3036, 2, '4.3.3.1.1.61.00.00.00.00', 'SERVIÇOS DE TURISMO', 'Registra as variações patrimoniais aumentativas com serviços de turismo.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3037, 2, '4.3.3.1.1.99.00.00.00.00', 'OUTRAS VARIAÇÕES PATRIMONIAIS AUMENTATIVAS PROVENIENTES DE PRESTAÇÃO DE SERVIÇOS', 'Registra as variações patrimoniais aumentativas provenientes da prestação de outros serviços não enquadrados nos itens anteriores.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3038, 2, '4.4.2.4.1.14.00.00.00.00', 'MULTAS E JUROS CONTRIBUIÇÃO PARA O CUSTEIO DO SERVIÇO DE ILUMINAÇÃO PÚBLICA', 'Registra os valores relativos aos créditos a receber dos Municípios e o Distrito Federal que instituirem contribuição, na forma das respectivas leis, para o custeio do serviço de iluminação pública, conforme artigo 149-A da Constituição Federal de 1988. ', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3039, 2, '4.4.2.3.1.05.00.00.00.00', 'JUROS E ENCARGOS DE MORA DA DIVIDA ATIVA DO PROGRAMA TROCA-TROCA', 'Registra o valor da arrecadação de VPA de multas e juros de mora da dívida ativa do programa troca-troca.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3040, 2, '4.4.2.3.1.06.00.00.00.00', 'MULTAS E JUROS DE MORA DA DIVIDA ATIVA DA PRESTACAO DE SERVICOS', 'Registra o valor da arrecadação de VPA de multas e juros de mora da dívida ativa da prestação de serviços.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3041, 2, '4.4.2.3.1.07.00.00.00.00', 'MULTAS E JUROS DE MORA DA DIVIDA ATIVA DOS AUTOS DE INFRACAO', 'Registra o valor da arrecadação de VPA de multas e juros de mora da dívida ativa dos autos de infração.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3042, 2, '4.4.2.3.1.99.00.00.00.00', 'OUTROS JUROS E ENCARGOS DE MORA SOBRE FORNECIMENTO DE BENS E SERVICOS', 'Registra a variação patrimonial aumentativa proveniente de outros juros e encargos de mora sobre fornecimento de bens e servicos', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3043, 2, '4.4.2.4.1.01.00.00.00.00', 'MULTAS E JUROS SOBRE IMPOSTO SOBRE A RENDA E PROVENTOS DE QUALQUER NATUREZA', 'Registra os valores relativos a créditos a receber, decorrentes da cobrança do Imposto sobre a Renda e Proventos de Qualquer Natureza retidos na fonte.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3044, 2, '4.4.2.4.1.05.00.00.00.00', 'MULTAS E JUROS SOBRE IPTU', 'Registra os valores relativos a créditos a receber, decorrentes da cobrança do Imposto sobre a Propriedade Predial e Territorial Urbana.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3045, 2, '4.4.2.4.1.06.00.00.00.00', 'MULTAS E JUROS SOBRE ITBI', 'Registra os valores relativos a créditos a receber, decorrentes da cobrança do Imposto sobre Transmissão "Inter Vivos" de Bens Imóveis e de Direitos Reais sobre Imóveis', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3046, 2, '4.4.2.4.1.07.00.00.00.00', 'MULTAS E JUROS SOBRE ISS', 'Registra os valores relativos aos créditos a receber, decorrentes do Imposto Sobre Serviços de Qualquer Natureza.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3047, 2, '4.4.2.4.1.08.00.00.00.00', 'MULTAS E JUROS SOBRE ITR', 'Registra os valores relativos aos créditos a receber, decorrentes do Imposto Sobre a Propriedade Territorial Rural, devidos aos municípios ou ao Distrito Federal devido a convênios firmados com a União, conforme inciso III, parágrafo 4º do artigo 153 da Constituição Federal.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3048, 2, '4.4.2.4.1.09.00.00.00.00', 'MULTAS E JUROS SOBRE TAXAS PELO EXERCÍCIO DO PODER DE POLÍCIA', 'Registra os valores relativos aos créditos a receber, decorrentes da cobrança das taxas pelo exercício do poder de polícia.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3049, 2, '4.4.2.4.1.10.00.00.00.00', 'MULTAS E JUROS TAXAS PELA PRESTAÇÃO DE SERVIÇOS', 'Registra os valores relativos aos créditos a receber, decorrentes da cobrança das taxas pela prestação de serviços.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3050, 2, '4.4.2.4.1.11.00.00.00.00', 'MULTAS E JUROS CONTRIBUIÇÕES DE MELHORIA', 'Registra os valores relativos aos créditos a receber, decorrentes da cobrança dos valores decorrentes da contribuição instituída para fazer face ao custo de obras públicas de que decorra valorização imobiliária.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3051, 2, '4.4.2.4.1.15.00.00.00.00', 'MULTAS E JUROS CRÉDITOS TRIBUTARIOS PARCELADOS', 'Registra os valores relativos aos créditos aos créditos a receber, decorrentes de Créditos Tributários Parcelados.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3052, 2, '4.4.2.4.1.16.00.00.00.00', 'MULTAS E JUROS DE DÍVIDA ATIVA TRIBUTÁRIA', 'Registra os valores de multas e juros de dívida ativa tributária.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3053, 2, '4.4.2.4.1.99.00.00.00.00', 'JUROS E ENCARGOS DE MORA SOBRE OUTROS CRÉDITOS TRIBUTÁRIOS', 'Registra os juros e encargos de mora sobre outros créditos tributários.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3054, 2, '4.4.5.1.1.01.00.00.00.00', 'REMUNERAÇÃO DE DEPÓSITOS DE RECURSOS VINCULADOS', 'Registra o valor da VPA proveniente da remuneração de depositos bancarios de recursos vinculados, tais como: royalties, FUNDEB, fundo de saúde, regime próprio de previdência social dos servidores, manutenção e desenvolvimento do ensino, ações e serviços públicos de saúde (ASPS), fundetur, etc. da remuneração de aplicações financeiras de recursos vinculados, tais como: royalties, FUNDEB, fundo de saúde, regime próprio de previdência social dos servidores, manutenção e desenvolvimento do ensino, ASPS, etc.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3055, 2, '4.4.5.1.1.02.00.00.00.00', 'REMUNERAÇÃO DE DEPÓSITOS DE RECURSOS NÃO VINCULADOS', 'Registra o valor da VPA proveniente da remuneração de depósitos bancários de recursos não vinculados, inclusive recursos próprios. ', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3056, 2, '4.4.5.1.1.03.00.00.00.00', 'REMUNERAÇÃO DOS INVESTIMENTOS DO REGIME PRÓPRIO DE PREVIDÊNCIA SOCIAL', 'Registra o somatório das VPA decorrentes de remuneração da carteira de investimentos dos RPPS.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3057, 2, '4.4.5.1.1.96.00.00.00.00', 'REMUNERACAO DE OUTROS DEPOSITOS BANCARIOS  ', 'Registra a variação patrimonial aumentativa decorrente da remuneração de outros depositos bancarios do ente existentes no agente financeiro não relacionados nas contas acima.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3058, 2, '4.9.9.9.1.10.00.00.00.00', 'RESTITUICAO PELO USO DE BENS DO MUNICIPIO', 'Registra o valor total da arrecadação da VPA proveniente da utilização de bens do município. Ex: telefone móvel.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3109, 2, '4.9.9.9.1.11.00.00.00.00', 'RESTITUICAO PELO PAGAMENTO INDEVIDO', 'Registra o valor da restituição proveniente de pagamento indevido.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3059, 2, '4.4.5.2.1.01.00.00.00.00', 'REMUNERAÇÃO DE APLICAÇÕES FINANCEIRAS DE RECURSOS VINCULADOS', 'Registra o valor da VPA proveniente da remuneração de aplicações financeiras de recursos vinculados, tais como: royalties, FUNDEB, fundo de saúde, regime próprio de previdência social dos servidores, manutenção e desenvolvimento do ensino, ações e serviços públicos de saúde (ASPS), fundetur, etc. da remuneração de aplicações financeiras de recursos vinculados, tais como: royalties, FUNDEB, fundo de saúde, regime próprio de previdência social dos servidores, manutenção e desenvolvimento do ensino, ASPS, etc.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3060, 2, '4.4.5.2.1.02.00.00.00.00', 'REMUNERAÇÃO DE APLICAÇÕES FINANCEIRAS DE RECURSOS NÃO VINCULADOS', 'Registra o valor da VPA proveniente da remuneração de aplicações financeiras de recursos não vinculados, inclusive recursos próprios. ', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3061, 2, '4.4.5.2.1.03.00.00.00.00', 'REMUNERAÇÃO DOS INVESTIMENTOS DO REGIME PRÓPRIO DE PREVIDÊNCIA SOCIAL', 'Registra o valor da VPA decorrentes de remuneração da carteira de investimentos dos RPPS.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3062, 2, '4.4.5.2.1.96.00.00.00.00', 'REMUNERACAO DE OUTRAS APLICAÇÕES FINANCEIRAS ', 'Registra a variação patrimonial aumentativa decorrente da remuneração de outras aplicações financeiras do ente existentes no agente financeiro não relacionados nas contas acima.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3063, 2, '4.5.1.1.2.02.00.00.00.00', 'REPASSE RECEBIDO', 'Registra o valor dos recursos recebidos decorrentes de transferências financeiras entre órgãos da administração direta e indireta, correspondentes ao orçamento anual.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3064, 2, '4.5.1.1.2.03.00.00.00.00', 'SUB-REPASSE RECEBIDO', 'Registra o valor dos recursos recebidos decorrentes de transferências financeiras entre órgãos da administração direta e indireta, correspondentes ao orçamento anual.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3065, 2, '4.5.1.1.2.04.00.00.00.00', 'RECURSOS ARRECADADOS - RECEBIDOS', 'Registra o valor recebido de outro órgão ou entidade referente aos recursos que foram arrecadados (classificados como receita) para pagamento de despesas na unidade recebedora.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3066, 2, '4.5.1.3.2.01.01.00.00.00', 'RECURSOS PARA COBERTURA DE INSUFICIÊNCIAS FINANCEIRAS', 'Registra os recursos orçamentários efetivamente utilizados para a cobertura de insuficiências financeiras entre as receitas e despesas previdenciárias no exercício de referência.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3067, 2, '4.5.1.3.2.01.02.00.00.00', 'RECURSOS PARA FORMAÇÃO DE RESERVA', 'Registra os recursos transferidos pelo ente federativo ao RPPS para formação de reserva espontânea, para futuros pagamentos de benefícios do plano financeiro.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3068, 2, '4.5.1.3.2.01.99.00.00.00', 'OUTROS APORTES PARA O RPPS', 'Registra o somatório do recebimento de eventuais aportes de recursos no RPPS para outras necessidades financeiras que não a cobertura de insuficiências financeiras e formação de reservas.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3161, 2, '4.6.2.3.1.02.00.00.00.00', 'GANHOS COM ALIENAÇÃO DE MARCAS, DIREITOS E PATENTES INDUSTRIAIS', 'Registra a variação patrimonial aumentativa de ganhos com alienação de marcas, direitos e patentes industriais.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3069, 2, '4.5.1.3.2.02.01.00.00.00', 'RECURSOS PARA COBERTURA DE DÉFICIT FINANCEIRO', 'Registra o somatório dos recebimentos de recursos necessários ao equilíbrio financeiro do plano previdenciário, ou seja, à cobertura de déficit entre as receitas e despesas previdenciárias, referentes ao exercício atual.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3070, 2, '4.5.1.3.2.02.02.00.00.00', 'RECURSOS PARA COBERTURA DE DÉFICIT ATUARIAL', 'Registra os recursos orçamentários alocados para cobertura de déficit atuarial no exercício de referência, desde que não definidos por lei como contribuições suplementares.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3071, 2, '4.5.1.3.2.02.03.00.00.00', 'TRANSFERÊNCIA DE BENS IMÓVEIS', 'Registra o valor dos bens imóveis recebido pelos RPPS para cobertura de déficit financeiro ou atuarial.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3072, 2, '4.5.1.3.2.02.04.00.00.00', 'TRANFERÊNCIAS DE BENS MÓVEIS ', 'Registra o valor dos bens móveis recebidos pelo RPPS para cobertura de déficit financeiro ou atuarial.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3073, 2, '4.5.1.3.2.02.99.00.00.00', 'OUTROS APORTES PARA O RPPS', 'Registra outros aportes financeiros para o RPPS com outras finalidades previdenciárias.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3074, 2, '4.5.2.3.4.03.00.00.00.00', 'SUBVENÇÕES SOCIAIS', 'Registra a variação patrimonial aumentativa decorrente de transferências às entidades privadas sem fins lucrativos para os serviços essenciais de assistência social, médica e educacional;', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3075, 2, '4.5.2.3.4.99.00.00.00.00', 'DEMAIS TRANSFERÊNCIAS VOLUNTÁRIAS', 'Registra a variação patrimonial aumentativa decorrente das demais transferências voluntárias.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3076, 2, '4.5.2.1.3.02.00.00.00.00', 'COTA-PARTE FPM', 'Registra a variação patrimonial aumentativa decorrente da transferência da cota-parte do Fundo de Participação dos Municípios.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3077, 2, '4.5.2.1.3.03.00.00.00.00', 'COTA-PARTE ITR', 'Registra a variação patrimonial aumentativa decorrente da transferência da cota-parte do Imposto Territorial Rural.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3078, 2, '4.5.2.1.3.04.00.00.00.00', 'COTA-PARTE IPI', 'Registra a variação patrimonial aumentativa decorrente da transferência da cota-parte do Imposto sobre Produtos Industrializados.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3079, 2, '4.5.2.1.3.05.00.00.00.00', 'COTA-PARTE IMPOSTO SOBRE OPERAÇÕES DE CRÉDITO, CAMBIO E SEGURO, OU RELATIVA A TITULOS OU VALORES MOBILIARIOS - COMERCIALIZAÇÃO DO OURO', 'Registra a variação patrimonial aumentativa decorrente da transferência da cota-parte do Imposto sobre Operações de Crédito, Câmbio e Seguro ou relativa a títulos ou valores mobiliários - comercialização do ouro.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3080, 2, '4.5.2.1.3.06.00.00.00.00', 'TRANSFERENCIA DA COMPENSAÇÃO FINANCEIRA PELA EXPLORAÇÃO DE RECURSOS NATURAIS', 'Registra a variação patrimonial aumentativa decorrente da transferência da compensação financeira pela exploração dos recursos naturais.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3081, 2, '4.5.2.1.3.07.00.00.00.00', 'TRANSFERÊNCIAS DE RECURSOS DO SUS', 'Registra a variação patrimonial aumentativa decorrente da transferência de recursos do SUS.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3082, 2, '4.5.2.1.3.08.00.00.00.00', 'TRANSFERÊNCIAS DE RECURSOS DO FUNDO NACIONAL DE ASSITENCIA SOCIAL - FNAS', 'Registra a variação patrimonial aumentativa decorrente da transferência de recursos do Fundo Nacional de Assistência Social - FNAS.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3083, 2, '4.5.2.1.3.09.00.00.00.00', 'TRANSFERÊNCIAS DE RECURSOS DO FUNDO NACIONAL DO DESENVOLVIMENTO DA EDUCAÇÃO - FNDE', 'Registra a variação patrimonial aumentativa decorrente da transferência de transferências de recursos do Fundo Nacional do Desenvolvimento da Educação - FNDE.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3084, 2, '4.5.2.1.3.10.00.00.00.00', 'TRANSFERENCIA FINANCEIRA DO ICMS DESONERAÇÃO - LC 87/96 (LEI KANDIR)', 'Registra a variação patrimonial aumentativa decorrente da transferência da transferência financeira do ICMS Desoneração - LC 87/1996 (Lei Kandir).', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3085, 2, '4.5.2.1.3.11.00.00.00.00', 'TRANSFERENCIA DA UNIAO - PASEP', 'Registra a VPA recebida da união referente ao PASEP.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3238, 2, '4.9.9.6.1.99.00.00.00.00', 'OUTRAS INDENIZAÇÕES', 'Registra a variação patrimonial aumentativa proveniente de outras indenizações.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3086, 2, '4.5.2.1.3.12.00.00.00.00', 'AUXÍLIO FINANCEIRO - ESFORÇO EXPORTADOR (MP N° 193/04)', 'Registra o valor da transferencia recebida da uniao referente ao auxilio exportador - CEX (registra o valor da arrecadação de receita de transferência da compensação financeira.), instituida pela Medida Provisoria 193.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3087, 2, '4.5.2.1.3.13.00.00.00.00', 'FPM - APOIO FINANCEIRO (MP 462/2009)', 'Registra o valor da prestação de apoio financeiro pela união aos entes federados que recebem recursos do fundo de participação dos municípios - FPM, no exercício de 2009, com o objetivo de superar dificuldades financeiras emergenciais. ', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3088, 2, '4.5.2.1.3.14.00.00.00.00', 'FPM - APOIO FINANCEIRO (MP 480/2010)', 'Registra o valor da prestação de apoio financeiro pela união aos entes federados que recebem recursos do fundo de participação dos municípios - FPM, no exercício de 2010, com o objetivo de superar dificuldades financeiras emergenciais. ', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3089, 2, '4.5.2.1.3.15.00.00.00.00', 'FPM - APOIO FINANCEIRO (Lei Federal nº 12.859/2013)', 'Registra o valor da prestação de apoio financeiro pela união aos entes federados que recebem recursos do fundo de participação dos municípios - FPM, nos exercícios de 2013 e 2014, com o objetivo de incentivar a melhoria da qualidade dos serviços públicos municipais. ', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3090, 2, '4.5.2.1.3.16.00.00.00.00', 'TRANSFERENCIAS DE CONVENIOS DA UNIAO E DE SUAS ENTIDADES', 'Registra o valor total dos recursos oriundos de convênios firmados, com ou sem contraprestações de serviços, com a união ou com suas entidades, para realização de objetivos de interesse comum dos partícipes, e destinados a custear despesas correntes. Ex: para o sistema unico de saude - SUS, convenios da união destinadas a programas de educação, convenios da união destinadas a programas de assistencia social, convenios da união destinadas a programas de combate a fome, destinadas a programas de saneamento basico além de outras transferencias de convenios da união.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3091, 2, '4.5.2.1.3.99.00.00.00.00', 'OUTRAS PARTICIPAÇÕES NA RECEITA DA UNIÃO', 'Registra as outras variações patrimoniais aumentativas decorrentes da transferência de receitas da União, prevista na Constituição ou em leis específicas, cuja competência de arrecadação é da União.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3092, 2, '4.5.2.1.4.01.00.00.00.00', 'COTA-PARTE ICMS', 'Registra a variação patrimonial aumentativa decorrente da transferência da cota-parte de ICMS.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3093, 2, '4.5.2.1.4.02.00.00.00.00', 'COTA-PARTE IPVA', 'Registra a variação patrimonial aumentativa decorrente da transferência da cota-parte de IPVA.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3094, 2, '4.5.2.1.4.03.00.00.00.00', 'COTA-PARTE IPI-EXPORTAÇÃO', 'Registra a variação patrimonial aumentativa decorrente da transferência da cota-parte de IPI-Exportação.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3095, 2, '4.5.2.1.4.04.00.00.00.00', 'COTA-PARTE DA CONTRIBUIÇÃO DE INTERVENÇÃO NO DOMÍNIO ECONÔMICO', 'Registra o valor total das receitas recebidas pelos Municípios por meio de transferências constitucionais da contribuição de intervenção no domínio econômico (Emenda Constitucional nº 42, de 19/12/2003).', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3096, 2, '4.5.2.1.4.05.00.00.00.00', 'TRANSFERÊNCIA DA COMPENSAÇÃO FINANCEIRA PELA EXPLORAÇÃO DE RECURSOS NATURAIS', 'Registra o valor da arrecadação de receita com a transferência da cota-parte da compensação financeira proveniente da exploração de recursos naturais.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3097, 2, '4.5.2.3.4.04.00.00.00.00', 'SUBVENÇÕES ECONÔMICAS', 'Registra o valor utilizado para transferências correntes às entidades públicas ou privadas com fins lucrativos para os serviços essenciais de assistência social, médica e educacional;', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3098, 2, '4.5.2.1.4.06.00.00.00.00', 'TRANSFERÊNCIA DE RECURSOS DO ESTADO PARA PROGRAMAS DE SAÚDE - REPASSE FUNDO A FUNDO', 'Registra o valor de receita da transferência de recursos do Sistema Único de Saúde oriundo do Fundo Estadual de Saúde para o Fundo Municipal de Saúde (Ações Básicas de Vigilância Sanitária, Atenção à Saúde dos Povos Indígenas, Programa de Assistência Farmacêutica Básica, Programa de Combate às Carências Nutricionais, Programa de Saúde da Família, Programa de Agentes Comunitários, Programa Nacional de Vigilância Epidemiológica e Controle de Doenças e outros).', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3099, 2, '4.5.2.1.4.07.00.00.00.00', 'COTA-PARTE DA MULTA DE TRANSITO', 'Registra o valor total das VPA recebidas através de cota-parte da multa de trânsito transferida pelo Estado e executadas como recurso livre até 30 de junho de 2009.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3100, 2, '4.5.2.1.4.08.00.00.00.00', 'TRANSFERENCIAS DE CONVENIOS DOS ESTADOS E DO DISTRITO FEDERAL E DE SUAS ENTIDADES', 'Registra o valor total dos recursos oriundos de convênios firmados, com ou sem contraprestações de serviços com estados ou com o distrito federal e respectivas entidades públicas, para realização de objetivos de interesse comum dos partícipes, e destinados a custear despesas correntes. Ex: convenios dos estados para o sistema unico de saude - SUS, convenios dos estados destinadas a programas de educação, programa de abrigagem a população adulta de rua, revisão de beneficios de prestação continuada - BPC, programa de atendimento a criança, programa de apoio a pessoa portadora de deficiencia, programa de atenção a pessoa idosa, programa asema-apoio socio-educativo em meio aberto, programa OASF - orientação e apoio socio-familiar, programa de abrigo as crianças e adolescentes, transferencias relativas ao PROSAN além de outras transferencias de convenios dos estados.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3101, 2, '4.5.2.1.4.99.00.00.00.00', 'OUTRAS PARTICIPAÇÕES NA RECEITA DOS ESTADOS', 'Registra as outras variações patrimoniais aumentativas decorrentes da transferência de outras esferas de governo de receitas tributárias, de contribuições e de outras receitas vinculadas, prevista na Constituição ou em leis específicas, cuja competência de arrecadação é do órgão transferidor.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3102, 2, '4.5.2.3.3.01.00.00.00.00', 'CONTRIBUIÇÕES', 'Registra a variação patrimonial aumentativa decorrente de transferências correntes e de capital aos entes da Federação e a entidades privadas sem fins lucrativos, exceto para os serviços essenciais de assistência social, médica e educacional;', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3103, 2, '4.5.2.3.3.02.00.00.00.00', 'AUXÍLIOS', 'Registra a variação patrimonial aumentativa decorrente de transferências de capital aos entes da Federação e a entidades privadas sem fins lucrativos;', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3104, 2, '4.5.2.3.3.03.00.00.00.00', 'SUBVENÇÕES SOCIAIS', 'Registra a variação patrimonial aumentativa decorrente de transferências às entidades privadas sem fins lucrativos para os serviços essenciais de assistência social, médica e educacional;', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3105, 2, '4.5.2.3.3.04.00.00.00.00', 'SUBVENÇÕES ECONÔMICAS', 'Registra o valor utilizado para transferências correntes às entidades públicas ou privadas com fins lucrativos para os serviços essenciais de assistência social, médica e educacional;', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3106, 2, '4.5.2.3.3.99.00.00.00.00', 'DEMAIS TRANSFERÊNCIAS VOLUNTÁRIAS', 'Registra a variação patrimonial aumentativa decorrente das demais transferências voluntárias.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3110, 2, '4.5.2.3.5.01.00.00.00.00', 'CONTRIBUIÇÕES', 'Registra a variação patrimonial aumentativa decorrente de transferências correntes e de capital aos entes da Federação e a entidades privadas sem fins lucrativos, exceto para os serviços essenciais de assistência social, médica e educacional;', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3111, 2, '4.5.2.3.5.02.00.00.00.00', 'AUXÍLIOS', 'Registra a variação patrimonial aumentativa decorrente de transferências de capital aos entes da Federação e a entidades privadas sem fins lucrativos;', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3112, 2, '4.5.2.3.5.03.00.00.00.00', 'SUBVENÇÕES SOCIAIS', 'Registra a variação patrimonial aumentativa decorrente de transferências às entidades privadas sem fins lucrativos para os serviços essenciais de assistência social, médica e educacional;', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3113, 2, '4.5.2.3.5.04.00.00.00.00', 'SUBVENÇÕES ECONÔMICAS', 'Registra o valor utilizado para transferências correntes às entidades públicas ou privadas com fins lucrativos para os serviços essenciais de assistência social, médica e educacional;', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3114, 2, '4.5.2.3.5.99.00.00.00.00', 'DEMAIS TRANSFERÊNCIAS VOLUNTÁRIAS', 'Registra a variação patrimonial aumentativa decorrente das demais transferências voluntárias.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3115, 2, '4.5.3.1.1.01.00.00.00.00', 'TRANSFERÊNCIAS DAS INSTITUIÇÕES PRIVADAS SEM FINS LUCRATIVOS PARA CONVÊNIOS', 'Registra a variação patrimonial aumentativa decorrente das transferências financeiras das instituições privadas sem fins lucrativos para convênios.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3116, 2, '4.5.3.1.1.02.00.00.00.00', 'TRANSFERÊNCIAS DAS INSTITUIÇÕES PRIVADAS SEM FINS LUCRATIVOS PARA COMBATE A FOME', 'Registra a variação patrimonial aumentativa decorrente das transferências financeiras das instituições privadas sem fins lucrativos para combate à fome.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3117, 2, '4.5.3.1.1.99.00.00.00.00', 'OUTRAS TRANSFERÊNCIAS DAS INSTITUIÇÕES PRIVADAS SEM FINS LUCRATIVOS', 'Registra a variação patrimonial aumentativa decorrente de outras transferências financeiras das instituições privadas sem fins lucrativos.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3118, 2, '4.5.3.2.1.01.00.00.00.00', 'TRANSFERÊNCIAS DAS INSTITUIÇÕES PRIVADAS COM FINS LUCRATIVOS PARA CONVÊNIOS', 'Registra a variação patrimonial aumentativa decorrente das transferências financeiras das instituições privadas com fins lucrativos para convênios.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3119, 2, '4.5.3.2.1.02.00.00.00.00', 'TRANSFERÊNCIAS DAS INSTITUIÇÕES PRIVADAS COM FINS LUCRATIVOS PARA COMBATE A FOME', 'Registra a variação patrimonial aumentativa decorrente das transferências financeiras das instituições privadas com fins lucrativos para combate à fome.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3120, 2, '4.5.3.2.1.99.00.00.00.00', 'OUTRAS TRANSFERÊNCIAS DAS INSTITUIÇÕES PRIVADAS COM FINS LUCRATIVOS ', 'Registra a variação patrimonial aumentativa decorrente de outras transferências financeiras das instituições privadas com fins lucrativos.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3121, 2, '4.5.4.0.1.01.00.00.00.00', 'TRANSFERÊNCIAS DE RECURSOS DO FUNDEB', 'Registra as variações patrimoniais aumentativas decorrentes das transferências das instituições multigovernamentais, das quais o ente recebedor não participe - Transferências de Recursos do FUNDEB.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3122, 2, '4.5.4.0.1.02.00.00.00.00', 'TRANSFERÊNCIAS DE RECURSOS DA COMPLEMENTAÇÃO DO FUNDEB', 'Registra as variações patrimoniais aumentativas decorrentes das transferências das instituições multigovernamentais, das quais o ente recebedor não participe - Transferências de Recursos da Complementação do FUNDEB.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3123, 2, '4.5.4.0.1.99.00.00.00.00', 'OUTRAS TRANSFERÊNCIAS MULTIGOVERNAMENTAIS', 'Registra as variações patrimoniais aumentativas decorrentes das transferências das instituições multigovernamentais, das quais o ente recebedor não participe - Outras Transferências Multigovernamentais.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3124, 2, '4.6.1.1.1.01.01.00.00.00', 'REAVALIAÇÃO DE MÁQUINAS, APARELHOS, EQUIPAMENTOS E FERRAMENTAS', 'Registra a variação patrimonial aumentativa relativa à adoção do valor de mercado ou de consenso entre as partes para máquinas, ferramentas, aparelhos, equipamentos, acessórios etc, quando esse for inferior ao valor liquido contábil.', 2, true, 2, ' ');
insert into contabilidade.planocontadetalhe values (3125, 2, '4.6.1.1.1.01.02.00.00.00', 'REAVALIAÇÃO DE BENS DE INFORMÁTICA', 'Registra a variação patrimonial aumentativa relativa à adoção do valor de mercado ou de consenso entre as partes paraequipamentos de processamento de dados e sistemas aplicativos, entre outros, quando esse for inferior ao valor liquido contábil.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3126, 2, '4.6.1.1.1.01.03.00.00.00', 'REAVALIAÇÃO DE MÓVEIS E UTENSÍLIOS', 'Registra a variação patrimonial aumentativa relativa à adoção do valor de mercado ou de consenso entre as partes para mobiliário em geral e utensílios, entre outros, quando esse for inferior ao valor liquido contábil.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3127, 2, '4.6.1.1.1.01.04.00.00.00', 'REAVALIAÇÃO DE MATERIAIS CULTURAIS, EDUCACIONAIS E DE COMUNICAÇÃO', 'Registra a variação patrimonial aumentativa relativa à adoção do valor de mercado ou de consenso entre as partes para materiais bibliográficos, discotecas, filmotecas, de comunicação, entre outros, quando esse for inferior ao valor liquido contábil.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3128, 2, '4.6.1.1.1.01.05.00.00.00', 'REAVALIAÇÃO DE VEÍCULOS', 'Registra a variação patrimonial aumentativa relativa à adoção do valor de mercado ou de consenso entre as partes para transportes aéreos, aquáticos e terrestres, entre outros, quando esse for inferior ao valor liquido contábil.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3129, 2, '4.6.1.1.1.01.06.00.00.00', 'REAVALIAÇÃO DE PEÇAS E CONJUNTOS DE REPOSIÇÃO', 'Registra a variação patrimonial aumentativa relativa à adoção do valor de mercado ou de consenso entre as partes para peças e conjuntos de reposição destinados a substituição em máquinas e equipamentos, aeronaves e embarcações, bens de segurança e socorro, entre outros, quando esse for inferior ao valor liquido contábil.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3130, 2, '4.6.1.1.1.01.07.00.00.00', 'REAVALIAÇÃO DE BENS MÓVEIS EM ANDAMENTO', 'Registra a variação patrimonial aumentativa relativa à adoção do valor de mercado ou de consenso entre as partes para bens móveis em andamento, quando esse for inferior ao valor liquido contábil.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3131, 2, '4.6.1.1.1.01.08.00.00.00', 'REAVALIAÇÃO DE BENS MÓVEIS EM ALMOXARIFADO', 'Registra a variação patrimonial aumentativa relativa à adoção do valor de mercado ou de consenso entre as partes para bens permanentes a serem estocados em almoxarifado, quando esse for inferior ao valor liquido contábil.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3132, 2, '4.6.1.1.1.01.09.00.00.00', 'REAVALIAÇÃO DE ARMAMENTOS', 'Registra a variação patrimonial aumentativa relativa à adoção do valor de mercado ou de consenso entre as partes para armas que constituem objetos de defesa ou preparativos de guerra, quando esse for inferior ao valor liquido contábil.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3133, 2, '4.6.1.1.1.01.10.00.00.00', 'REAVALIAÇÃO DE SEMOVENTES', 'Registra a variação patrimonial aumentativa relativa à adoção do valor de mercado ou de consenso entre as partes para animais destinados a produção, reprodução, engorda e aos serviços utilitários em geral, quando esse for inferior ao valor liquido contábil.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3134, 2, '4.6.1.1.1.01.99.00.00.00', 'REAVALIAÇÃO DE DEMAIS BENS MÓVEIS', 'Registra a variação patrimonial aumentativa relativa à adoção do valor de mercado ou de consenso entre as partes para demais bens móveis não classificados em grupos específicos, quando esse for inferior ao valor liquido contábil.', 2, true, 2, ' ');
insert into contabilidade.planocontadetalhe values (3135, 2, '4.6.1.1.1.02.01.00.00.00', 'REAVALIAÇÃO DE BENS DE USO ESPECIAL', 'Registra a variação patrimonial aumentativa relativa à adoção do valor de mercado ou de consenso entre as partes para os bens, tais como edifícios ou terrenos destinados a serviço ou estabelecimento da administração estadual ou municipal, inclusive os de suas autarquias e fundações públicas, quando esse for inferior ao valor liquido contábil.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3136, 2, '4.6.1.1.1.02.02.00.00.00', 'REAVALIAÇÃO DE BENS DOMINICAIS', 'Registra a variação patrimonial aumentativa relativa à adoção do valor de mercado ou de consenso entre as partes para os bens que constituem o patrimônio das pessoas jurídicas de direito público, como objeto de direito pessoal, ou real, de cada uma dessas entidades. Compreende ainda, não dispondo a lei em contrário, os bens pertencentes as pessoas jurídicas de direito público a que se tenha dado estrutura de direito privado, quando esse for inferior ao valor liquido contábil.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3137, 2, '4.6.1.1.1.02.03.00.00.00', 'REAVALIAÇÃO DE BENS DE USO COMUM DO POVO', 'Registra a variação patrimonial aumentativa relativa à adoção do valor de mercado ou de consenso entre as partes para os bens de uso comum do povo construídos ou adquiridos por pessoas jurídicas de direito público, quando esse for inferior ao valor liquido contábil.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3138, 2, '4.6.2.3.1.03.00.00.00.00', 'GANHOS COM ALIENAÇÃO DE DIREITO DE USO DE IMÓVEIS', 'Registra a variação patrimonial aumentativa de ganhos com alienação de direito de uso de imóveis.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3139, 2, '4.6.1.1.1.02.04.00.00.00', 'REAVALIAÇÃO DE BENS IMÓVEIS EM ANDAMENTO', 'Registra a variação patrimonial aumentativa relativa à adoção do valor de mercado ou de consenso entre as partes para os valores de bens imóveis em andamento, quando esse for inferior ao valor liquido contábil.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3162, 2, '4.6.5.1.1.01.00.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL DE PARTICIPAÇÕES PERMANENTES', 'Registra a variação patrimonial aumentativa com a reversão de redução a valor recuperável de participações permanentes em outras entidades.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3140, 2, '4.6.1.1.1.02.05.00.00.00', 'REAVALIAÇÃO DE INSTALAÇÕES', 'Registra a variação patrimonial aumentativa relativa à adoção do valor de mercado ou de consenso entre as partes para equipamentos, materiais e custo de implantação de instalações que, não obstante integradas aos edifícios, devem ser segregadas das obras civis, como, por exemplo, as instalações elétricas, hidráulicas, sanitárias, de vapor, de ar comprimido, frigoríficas, contra incêndio, de comunicações, de climatização, para combustíveis, gases, de antipoluição, para cozinha, dentre outros. E também aplicável a construção de trechos ferroviários, quando esse for inferior ao valor liquido contábil.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3141, 2, '4.6.1.1.1.02.06.00.00.00', 'REAVALIAÇÃO DE BENFEITORIAS EM PROPRIEDADE DE TERCEIROS', 'Registra a variação patrimonial aumentativa relativa à adoção do valor de mercado ou de consenso entre as partes para construções em terrenos arrendados de terceiros e instalações e outras benfeitorias em prédios alugados. São considerados somente os gastos com construção e instalação que se incorporam ao imóvel e revertem ao proprietário do imóvel ao final da locação, quando esse for inferior ao valor liquido contábil.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3142, 2, '4.6.1.1.1.02.99.00.00.00', 'REAVALIAÇÃO DE DEMAIS BENS IMÓVEIS', 'Registra a variação patrimonial aumentativa relativa à adoção do valor de mercado ou de consenso entre as partes para os demais bens imóveis não classificados anteriormente nesse plano de contas, quando esse for inferior ao valor liquido contábil.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3143, 2, '4.6.2.1.1.01.00.00.00.00', 'GANHOS COM ALIENAÇÃO DE PARTICIPAÇÕES PERMANENTES', 'Registra a variação patrimonial aumentativa de ganhos com alienação de participações permanentes.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3144, 2, '4.6.2.1.1.02.00.00.00.00', 'GANHOS COM ALIENAÇÃO DE PROPRIEDADES PARA INVESTIMENTO', 'Registra a variação patrimonial aumentativa de ganhos com alienação de propriedades para investimento.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3145, 2, '4.6.2.1.1.03.00.00.00.00', 'GANHOS COM ALIENAÇÃO DE INVESTIMENTOS DO RPPS DE LONGO PRAZO', 'Registra a variação patrimonial aumentativa de ganhos com alienação de investimentos do RPPS de longo prazo.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3146, 2, '4.6.2.1.1.99.00.00.00.00', 'GANHOS COM ALIENAÇÃO DE DEMAIS INVESTIMENTOS PERMANENTES', 'Registra a variação patrimonial aumentativa de ganhos com alienação de demais investimentos permanentes.', 2, true, 2, 'N');
