insert into contabilidade.planocontadetalhe values (3188, 2, '4.6.5.2.1.01.01.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL DE MÁQUINAS, APARELHOS, EQUIPAMENTOS E FERRAMENTAS', 'Registra a variação patrimonial aumentativa com a reversão de redução a valor recuperável de máquinas, ferramentas, aparelhos, equipamentos, acessórios etc.', 2, true, 2, ' ');
insert into contabilidade.planocontadetalhe values (3189, 2, '4.6.5.2.1.01.02.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL DE BENS DE INFORMÁTICA', 'Registra a variação patrimonial aumentativa com a reversão de redução a valor recuperável de equipamentos de processamento de dados e sistemas aplicativos, entre outros.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3190, 2, '4.6.5.2.1.01.03.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL DE MÓVEIS E UTENSÍLIOS', 'Registra a variação patrimonial aumentativa com a reversão de redução a valor recuperável de mobiliário em geral e utensílios, entre outros.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3191, 2, '4.6.5.2.1.01.04.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL DE MATERIAIS CULTURAIS, EDUCACIONAIS E DE COMUNICAÇÃO', 'Registra a variação patrimonial aumentativa com a reversão de redução a valor recuperável de materiais bibliográficos, discotecas, filmotecas, de comunicação, entre outros.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3192, 2, '4.6.5.2.1.01.05.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL DE VEÍCULOS', 'Registra a variação patrimonial aumentativa com a reversão de redução a valor recuperável de transportes aéreos, aquáticos e terrestres, entre outros.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3193, 2, '4.6.5.2.1.01.06.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL DE PEÇAS E CONJUNTOS DE REPOSIÇÃO', 'Registra a variação patrimonial aumentativa com a reversão de redução a valor recuperável de peças e conjuntos de reposição destinados a substituição em máquinas e equipamentos, aeronaves e embarcações, bens de segurança e socorro, entre outros.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3194, 2, '4.6.5.2.1.01.07.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL DE BENS MÓVEIS EM ANDAMENTO', 'Registra a variação patrimonial aumentativa com a reversão de redução a valor recuperável de bens móveis em andamento.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3195, 2, '4.6.5.2.1.01.08.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL DE BENS MÓVEIS EM ALMOXARIFADO', 'Registra a variação patrimonial aumentativa com a reversão de redução a valor recuperável de bens permanentes a serem estocados em almoxarifado.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3196, 2, '4.6.5.2.1.01.09.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL DE ARMAMENTOS', 'Registra a variação patrimonial aumentativa com a reversão de redução a valor recuperável de armas que constituem objetos de defesa ou preparativos de guerra.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3197, 2, '4.6.5.2.1.01.10.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL DE SEMOVENTES', 'Registra a variação patrimonial aumentativa com a reversão de redução a valor recuperável de animais destinados a produção, reprodução, engorda e aos serviços utilitários em geral.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3198, 2, '4.6.5.2.1.01.99.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL DE DEMAIS BENS MÓVEIS', 'Registra a variação patrimonial aumentativa com a reversão de redução a valor recuperável de demais bens móveis não classificados em grupos específicos.', 2, true, 2, ' ');
insert into contabilidade.planocontadetalhe values (3199, 2, '4.6.5.2.1.02.01.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL DE BENS DE USO ESPECIAL', 'Registra a variação patrimonial aumentativa com a reversão de redução a valor recuperável de bens como edifícios ou terrenos destinados a serviço ou estabelecimento da administração estadual ou municipal, inclusive os de suas autarquias e fundações públicas.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3200, 2, '4.6.5.2.1.02.02.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL DE BENS DOMINICAIS', 'Registra a variação patrimonial aumentativa com a reversão de redução a valor recuperável de bens que constituem o patrimônio das pessoas jurídicas de direito público, como objeto de direito pessoal, ou real, de cada uma dessas entidades. Compreende ainda, não dispondo a lei em contrário, os bens pertencentes as pessoas jurídicas de direito público a que se tenha dado estrutura de direito privado.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3201, 2, '4.6.5.2.1.02.03.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL DE BENS DE USO COMUM DO POVO', 'Registra a variação patrimonial aumentativa com a reversão de redução a valor recuperável de bens de uso comum do povo construídos ou adquiridos por pessoas jurídicas de direito público.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3202, 2, '4.6.5.2.1.02.04.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL DE BENS IMÓVEIS EM ANDAMENTO', 'Registra a variação patrimonial aumentativa com a reversão de redução a valor recuperável de valores de bens imóveis em andamento.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3203, 2, '4.6.5.2.1.02.05.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL DE INSTALAÇÕES', 'Registra a variação patrimonial aumentativa com a reversão de redução a valor recuperável de equipamentos, materiais e custo de implantação de instalações que, não obstante integradas aos edifícios, devem ser segregadas das obras civis, como, por exemplo, as instalações elétricas, hidráulicas, sanitárias, de vapor, de ar comprimido, frigoríficas, contra incêndio, de comunicações, de climatização, para combustíveis, gases, de antipoluição, para cozinha, dentre outros. E também aplicável a construção de trechos ferroviários.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3204, 2, '4.6.5.2.1.02.06.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL DE BENFEITORIAS EM PROPRIEDADE DE TERCEIROS', 'Registra a variação patrimonial aumentativa com a reversão de redução a valor recuperável de construções em terrenos arrendados de terceiros e instalações e outras benfeitorias em prédios alugados. São considerados somente os gastos com construção e instalação que se incorporam ao imóvel e revertem ao proprietário do imóvel ao final da locação.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3205, 2, '4.6.5.2.1.02.99.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL DE DEMAIS BENS IMÓVEIS', 'Registra a variação patrimonial aumentativa com a reversão de redução a valor recuperável de os demais bens imóveis não classificados anteriormente nesse plano de contas.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3206, 2, '4.6.5.2.1.03.00.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL DE IMOBILIZADO MANTIDO PARA VENDA', 'Registra a variação patrimonial aumentativa com a reversão de redução a valor recuperável de imobilizados mantidos para venda', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3207, 2, '4.6.5.3.1.02.00.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL DE MARCAS, DIREITOS E PATENTES ', 'Registra a variação patrimonial aumentativa com a reversão de redução a valor recuperável de serviços de marcas, direitos e patentes.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3208, 2, '4.6.5.3.1.03.00.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL DE DIREITO DE USO DE IMÓVEIS', 'Registra a variação patrimonial aumentativa com a reversão de redução a valor recuperável de direito de uso de imóveis.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3209, 2, '4.6.5.3.1.04.00.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL DE INTANGÍVEL MANTIDO PARA VENDA', 'Registra a variação patrimonial aumentativa com a reversão de redução a valor recuperável de intangíveis mantidos para venda.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3242, 2, '4.9.9.9.1.04.00.00.00.00', 'RECEITAS DIRETAMENTE ARRECADADAS PELO FUNDO DE ASSISTENCIA SOCIAL DOS SERVIDORES', 'Registra o valor total das VPA correntes arrecadadas diretamente pelo fundo de assistência social dos servidores', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3210, 2, '4.9.9.9.1.07.00.00.00.00', 'RECEITAS DECORRENTES DO RECEBIMENTO DE CERTIDÃO - TÍTULO EXECUTIVO DO TCE/RS', 'Registra a VPA decorrentes do recebimento total ou parcial  de certidão - título executivo emitido pelo  TCE/RS o qual foi registrado no ativo como créditos a receber e não como divida ativa não-tributária', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3211, 2, '4.9.7.1.1.01.00.00.00.00', 'REVERSÃO DE PROVISÃO PARA RISCOS TRABALHISTAS', 'Registra a variação patrimonial aumentativa proveniente de reversão de provisão para riscos trabalhistas.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3212, 2, '4.9.7.1.1.02.00.00.00.00', 'REVERSÃO DE PROVISÕES MATEMÁTICAS PREVIDENCIÁRIAS A LONGO PRAZO', 'Registra a variação patrimonial aumentativa proveniente de reversão de provisões matemáticas previdenciárias a longo prazo.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3213, 2, '4.9.7.1.1.03.00.00.00.00', 'REVERSÃO DE PROVISÕES PARA RISCOS FISCAIS', 'Registra a variação patrimonial aumentativa proveniente de reversão de provisões para riscos fiscais.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3214, 2, '4.9.7.1.1.04.00.00.00.00', 'REVERSÃO DE PROVISÕES PARA RISCOS CÍVEIS', 'Registra a variação patrimonial aumentativa proveniente de reversão de provisão riscos cíveis.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3215, 2, '4.9.7.1.1.05.00.00.00.00', 'REVERSÃO DE PROVISÕES REPARTIÇÃO DE CRÉDITO', 'Registra a variação patrimonial aumentativa proveniente de reversão de provisões por repartição de crédito.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3216, 2, '4.9.7.1.1.06.00.00.00.00', 'REVERSÃO DE PROVISÕES DECORRENTES DE CONTRATOS DE PPP', 'Registra a variação patrimonial aumentativa proveniente de reversão de provisões decorrentes de contratos de PPP.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3217, 2, '4.9.7.1.1.99.00.00.00.00', 'REVERSÃO DE OUTRAS PROVISÕES', 'Registra a variação patrimonial aumentativa proveniente de reversão de outras provisões.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3218, 2, '4.9.9.1.3.01.00.00.00.00', 'COMPENSAÇÕES FINANCEIRAS ENTRE O REGIME GERAL E OS REGIMES PRÓPRIOS DE PREVIDÊNCIA DOS SERVIDORES - PRINCIPAL', 'Registra a VPA decorrente de compensações financeiras entre o regime geral e os regimes próprios de previdência dos servidores - principal', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3219, 2, '4.9.9.1.3.02.00.00.00.00', 'COMPENSAÇÕES FINANCEIRAS ENTRE O REGIME GERAL E OS REGIMES PRÓPRIOS DE PREVIDÊNCIA DOS SERVIDORES - PARCELAMENTOS', 'Registra a VPA decorrente de compensações financeiras entre o regime geral e os regimes próprios de previdência dos servidores - parcelamentos', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3220, 2, '4.9.9.5.1.03.00.00.00.00', 'MULTA DE POLUICAO DE AGUAS', 'Registra as variações patrimoniais  aumentativas provenientes de penalidades pecuniarias destinadas a punir o infrator  pela  poluiçao  de  aguas.  Multas   dev.  lancamento   oleos,produtos oleosos e substancias quimicas toxicas nas aguas publicas.                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3221, 2, '4.9.9.5.1.07.00.00.00.00', 'MULTAS PREVISTAS NA LEGISLAÇÃO SANITARIA', 'Registra as variações patrimoniais  aumentativas provenientes de multas  aplicadas  com o fim de punir a quem transgride o disposto na legislação sanitaria. Devidas quando da infração, fraude, falsificação e adulteração das   materias-primas e produtos farmaceuticos, bem como quaisquer produtos ou  insumos que interessem a saude publica.                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3222, 2, '4.9.9.5.1.08.00.00.00.00', 'MULTAS PREVISTAS LEGISLAÇÃO DE REGISTRO COMERCIO', 'Registra as variações patrimoniais  aumentativas provenientes de multas aplicadas  com  o fim de punir a quem infringe as leis ou regulamentos que disciplinam as atividades de agentes auxiliares do comercio, de armazens gerais e  outros sujeitos ao controle e fiscalização dos orgaos de registro do comercio.                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3223, 2, '4.9.9.5.1.11.00.00.00.00', 'MULTAS PREVISTAS NA LEGISLAÇÃO DE TRANSITO', 'Registra as variações patrimoniais  aumentativas provenientes de multas  aplicadas  com o fim de punir a quem transgride a legislação referente a transito.  Constituem VPA vinculada ao ministerio da justica.                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         ', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3224, 2, '4.9.9.9.1.06.00.00.00.00', 'RECEITAS DECORRENTES DA COMPRA DE DOSES DE SEMEN DE ANIMAIS PELOS PRODUTORES', 'Registra o valor total da VPA decorrente da compra pelos produtos de sêmen de animais.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3243, 2, '4.9.9.9.1.05.00.00.00.00', 'RECEITAS DIRETAMENTE ARRECADADAS PELO FUNDO DE ASSISTENCIA A SAUDE DOS SERVIDORES', 'Registra o valor total das VPA correntes arrecadadas diretamente pelo fundo de assistência a saúde dos servidores', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3244, 2, '5.2.1.1.2.01.01.00.00.00', '(-) FUNDEB', 'Registra a previsão de dedução da receita aprovada na LOA por transferências ao FUNDEB.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (3225, 2, '4.9.9.5.1.14.00.00.00.00', 'MULTAS E JUROS PREVISTOS EM CONTRATOS', 'Registra as variações patrimoniais  aumentativas provenientes de  multas e juros previstos em contratos                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3226, 2, '4.9.9.9.1.08.00.00.00.00', 'PROGRAMA TROCA-TROCA', 'Registra o valor total da VPA proveniente do pagamento pelos agricultores do valor que lhes foi entregue em sementes pelo município. Inclusive a VPA da divida ativa.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3227, 2, '4.9.9.9.1.09.00.00.00.00', 'RESTITUICOES DETERMINADAS PELO TCE', 'Registra a VPA proveniente de créditos exigíveis a partir do recebimento, pelo credor, de certidão de decisão - título executivo, emitida pelo TCE/RS, com característica de liquidez e certeza, inscrita em Dívida Ativa Não Tributária.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3228, 2, '5.2.2.1.3.09.00.00.00.00', '(-) CANCELAMENTO DE DOTAÇÕES', 'Registra o cancelamento / remanejamento de dotações para abertura de créditos adicionais.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (3229, 2, '4.9.9.5.1.21.00.00.00.00', 'MULTAS POR DANOS AO MEIO AMBIENTE', 'Registra as variações patrimoniais  aumentativas provenientes de  multas por danos ao meio ambiente. Amparo legal: Lei 9 605 de 12 fev1998 .                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3230, 2, '4.9.9.5.1.25.00.00.00.00', 'MULTAS APLICADAS PELOS TRIBUNAIS DE CONTAS', 'Registra as variações patrimoniais  aumentativas provenientes de aplicação de penas pecuniarias incidentes sobre as multas aplicadas pelos tribunais de contas,  pelo não cumprimento a decisão dos mesmos.                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   ', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3231, 2, '4.9.9.5.1.27.00.00.00.00', 'MULTAS POR AUTOS DE INFRACAO', 'Registra as variações patrimoniais  aumentativas provenientes de multas punitivas  aplicadas pelo não cumprimento nos casos previstos nos regulamentos ou nos contratos, ou pela reincidencia em fatos que tenham gerado advertencia.                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3232, 2, '4.9.9.5.1.28.00.00.00.00', 'MULTA POR INFRAÇÃO À LEGISLAÇÃO DE LICITAÇÃO', 'Registra o valor da arrecadação de VPA de multas aplicadas por infrações praticadas em inobservância à legislação aplicada aos procedimentos de licitação.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3233, 2, '4.9.9.5.1.99.00.00.00.00', 'OUTRAS MULTAS ADMINISTRATIVAS', 'Registra as variações patrimoniais  aumentativas provenientes de outras multas administrativas nao enquadradas nas contas anteriores.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3234, 2, '4.9.9.6.1.01.00.00.00.00', 'INDENIZ. POR DANOS CAUSADOS AO PATR. PÚBLICO', 'Registra a variação patrimonial aumentativa proveniente de indenizações por danos causados ao patrimônio público.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3235, 2, '4.9.9.6.1.02.00.00.00.00', 'INDENIZAÇÃO POR PERDA/QUEBRA DE MERCADORIAS', 'Registra a variação patrimonial aumentativa proveniente de indenização por perda/quebra de mercadorias.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3236, 2, '4.9.9.6.1.03.00.00.00.00', 'INDENIZ. POSSE OU OCUPAÇÃO ILIC. BENS ', 'Registra a variação patrimonial aumentativa proveniente de indenização por posse ou ocupação ilícita de bens.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3237, 2, '4.9.9.6.1.04.00.00.00.00', 'REPOSIÇÃO/INDENIZAÇÃO DE SERVIDORES/AGENTES PÚBLICOS', 'Registra a variação patrimonial aumentativa proveniente de reposição ou indenização por parte de servidores ou agentes públicos.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3239, 2, '4.9.9.9.1.01.00.00.00.00', 'VPA DE ONUS SUCUMBENCIA DE ACOES JUDICIAIS', 'Registra a variação patrimonial aumentativa decorrente de custas do processo de apuração, inscrição e cobrança da divida ativa do municipio, bem como pela defesa judicial da fazenda municipal, paga pelo devedor da ação. ', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3240, 2, '4.9.9.9.1.02.00.00.00.00', ' "TERCEIRIZAÇÃO" DA FOLHA DE PAGAMENTO DOS AGENTES PUBLICOS', 'Registra a variação patrimonial aumentativa proveniente da terceirização da folha  de pagamento dos agentes publicos como contrapartida da prestação de serviços de disponibilização de creditos em contas correntes e da concessão de emprestimos e financiamentos com amortização consignada em folha de pagamento. ', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3241, 2, '4.9.9.9.1.03.00.00.00.00', 'OUTRAS RECEITAS DIRETAMENTE ARRECADADAS PELO RPPS', 'Registra o valor total das demais vpas correntes arrecadadas diretamente pelo regime próprio de previdência', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3245, 2, '5.2.1.1.2.02.00.00.00.00', '(-) RENÚNCIA', 'Registra a previsão de renúncia da receita aprovada na LOA.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (3247, 2, '5.2.1.2.1.03.01.00.00.00', '(-) FUNDEB', 'Registra a previsão de dedução da receita para abertura de créditos adicionais por motivo de reestimativa ou correção da receita por transferências ao FUNDEB.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (3248, 2, '5.2.1.2.1.04.00.00.00.00', '(-) PREVISÃO DE DEDUÇÕES DA RECEITA  POR RENÚNCIA', 'Registra a previsão de renúncia da receita para abertura de créditos adicionais por motivo de reestimativa ou correção da receita.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (3249, 2, '5.2.1.2.1.99.00.00.00.00', '(-) PREVISÃO DE OUTRAS DEDUÇÕES DA RECEITA', 'Registra a previsão de outras deduções da receita para abertura de créditos adicionais por motivo de reestimativa ou correção da receita.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (3250, 2, '5.2.1.2.9.00.00.00.00.00', '(-) ANULAÇÃO DA PREVISÃO DA RECEITA', 'Registra o valor da anulação da receita prevista no orçamento, na gestão fundos e nas administrações direta e indireta.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (3251, 2, '5.2.2.1.9.01.09.00.00.00', '(-) REDUÇÃO', 'Registra a movimentação dos créditos por redução decorrente de alteração do quadro de detalhamento de despesas - QDD.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (3252, 2, '5.2.2.1.9.04.00.00.00.00', '(-) CANCELAMENTO DE DOTAÇÕES', 'Registra o valor da redução da dotação devido a alteração da lei orçamentária em virtude de cancelamento.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (3253, 2, '5.2.2.2.2.01.09.00.00.00', '(-) CREDITOS TRANSFERIDOS              ', 'Registra a movimentação de créditos de entidades da administração indireta ou entre órgãos da administração direta de unidade orçamentária diferente.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (3254, 2, '6.3.2.6.0.00.00.00.00.00', 'RP PROCESSADOS TRANSFERIDOS', 'Registra o valor da transferência de restos a pagar pela desincorporação de saldos decorrente de transformação, cisão, fusão e extinção de órgãos ou UG.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (3255, 2, '5.2.2.2.2.02.09.00.00.00', '(-) CREDITOS TRANSFERIDOS              ', 'Registra a movimentação de créditos de órgãos da administração direta ou entre entidades da administração indireta de mesma ou de diferente unidade orçamentária, não formalizada a termo de contrato.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (3256, 2, '5.2.2.9.2.01.03.00.00.00', '(-) ANULAÇÃO DE EMPENHOS', 'REGISTRA O VALOR REFERENTE A REVERSÃO TOTAL OU PARCIAL DE DESPESA À DOTAÇÃO INICIAL CORRESPONDENTE, ATRAVÉS DA "NOTA DE ANULAÇÃO" DA NE.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (3257, 2, '5.2.2.9.2.01.04.00.00.00', '(-) CANCEL. DE EMPENHO POR FALTA DE DISPON. CAIXA', 'Registra o cancelamento de empenhos por falta de disponibilidade de caixa.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (3258, 2, '6.1.1.1.0.00.00.00.00.00', 'PPA A ALOCAR EM LEIS ORÇAMENTÁRIAS ANUAIS', 'Registra o somatório dos valores monetários do plano plurianual durante o seu período de vigência, detalhado por programas de trabalho a serem selecionados na elaboracao das leis orçamentárias anuais, nos quatro anos do PPA.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (3259, 2, '6.1.1.2.0.00.00.00.00.00', 'PPA ALOCADO EM LEIS ORÇAMENTÁRIAS ANUAIS', 'Registra o somatório dos valores monetários do plano plurianual aprovado, detalhado por programa de trabalho, alocado nas leis orçamentárias anuais ou relativos aos valores dos créditos antecipados pela LDO, dentro do período de vigência do PPA.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (3260, 2, '6.1.1.3.0.00.00.00.00.00', 'PPA EXECUTADO ', 'Registra o somatório dos valores monetários empenhados do plano plurianual no seu período de vigência, detalhado por programa de trabalho, autorizado nas leis orçamentárias anuais.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (3261, 2, '6.1.2.1.0.00.00.00.00.00', 'PROCESSAMENTO DO PLOA -RECEITA', 'Registra o somatório dos valores monetários das receitas previstas no projeto de lei orçamentária durante as suas fases de tramitação.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (3262, 2, '6.1.2.2.0.00.00.00.00.00', 'PROCESSAMENTO DO PLOA -DESPESA', 'Registra o somatório dos valores monetários fixados para as despesas no projeto de lei orçamentária durante as suas fases de tramitação.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (3263, 2, '6.2.1.2.0.00.00.00.00.00', 'RECEITA REALIZADA', 'Registra o somatório dos valores relativos às receitas realizadas, detalhada por natureza de receita.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (3264, 2, '6.2.2.1.1.00.00.00.00.00', 'CREDITO DISPONÍVEL', 'Registra o valor da disponibilidade de credito referente à dotação inicial e adicional aprovada no orçamento geral da União na LOA ou lei especifica ou antecipada pela lei de diretrizes orçamentárias - LDO.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (3265, 2, '6.2.2.1.2.01.00.00.00.00', 'BLOQUEIO DE CREDITO                             ', 'Registra o valor da disponibilidade de créditos orçamentários por contenção ou contingenciamento pela setorial orçamentária, SOF e outros.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (3266, 2, '6.2.2.1.2.02.00.00.00.00', 'CRÉDITO PRE-EMPENHADO ', 'Registra os valores dos pré-empenhos emitidos pela unidade ou por outra unidade gestora.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (3267, 2, '6.2.2.1.2.99.00.00.00.00', 'OUTRAS INDISPONIBILIDADES', 'Registra o valor das indisponibilidades de créditos orçamentários de natureza eventual, para as quais não há contas específicas.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (3268, 2, '6.2.2.1.3.01.00.00.00.00', 'CREDITO EMPENHADO A LIQUIDAR', 'Registra o valor da despesa empenhada a ser liquidada', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (3269, 2, '6.2.2.1.3.02.00.00.00.00', 'CREDITO EMPENHADO EM LIQUIDAÇÃO', 'Registra o valor da despesa cujo fato gerador já ocorreu, mas que ainda não foram conferidos o objeto, e o valor, ou seja, não houve a liquidação.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (3270, 2, '6.2.2.1.3.03.00.00.00.00', 'CREDITO EMPENHADO LIQUIDADO A PAGAR', 'Registra o valor da apropriação das despesas empenhadas com posterior verificação de sua regularidade por constituição do direto do credor.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (3271, 2, '6.2.2.1.3.04.00.00.00.00', 'CREDITO EMPENHADO LIQUIDADO PAGO', 'Registra o valor da despesa empenhada liquidada paga.', 2, true, 4, 'N');
