insert into contabilidade.planocontadetalhe values (3633, 2, '1.1.2.9.2.02.00.00.00.00', '(-) PERDAS ESTIMADAS EM CLIENTE', 'Compreende o ajuste para perdas estimadas com o não recebimento das faturas/duplicatas a receber decorrentes de vendas de mercadorias ou da prestação de serviços.', 2, false, 0, ' ');
insert into contabilidade.planocontadetalhe values (3634, 2, '1.1.2.9.2.03.00.00.00.00', '(-) PERDAS ESTIMADAS EM CRÉDITOS DE EMPRÉSTIMOS E FINANCIAMENTOS CONCEDIDOS', 'Compreende o ajuste para perdas estimadas com o não recebimento de créditos de empréstimos e financiamentos concedidos.', 2, false, 0, ' ');
insert into contabilidade.planocontadetalhe values (3635, 2, '1.1.2.9.2.04.00.00.00.00', '(-) PERDAS ESTIMADAS EM CRÉDITOS DE DÍVIDA ATIVA TRIBUTÁRIA', 'Compreende o ajuste para perdas estimadas com o não recebimento dos créditos inscritos em dívida ativa tributária.', 2, false, 0, ' ');
insert into contabilidade.planocontadetalhe values (3636, 2, '1.1.2.9.3.00.00.00.00.00', '(-) AJUSTE DE PERDAS DE CRÉDITOS A CURTO PRAZO - INTER OFSS - UNIÃO', 'Compreende o ajuste para perdas estimadas com o não recebimento de valores referentes a créditos a curto prazo, por inadimplência de terceiros e outras. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 2, false, 0, 'N');
