insert into contabilidade.planocontadetalhe values (3638, 2, '2.1.2.1.4.02.00.00.00.00', 'EMPRÉSTIMOS INTERNOS - EM CONTRATOS', 'Compreende os valores das operações de crédito internas em contratos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3639, 2, '1.1.2.9.3.03.00.00.00.00', '(-) PERDAS ESTIMADAS EM CRÉDITOS DE EMPRÉSTIMOS E FINANCIAMENTOS CONCEDIDOS', 'Compreende o ajuste para perdas estimadas com o não recebimento de créditos de empréstimos e financiamentos concedidos.', 2, false, 0, ' ');
insert into contabilidade.planocontadetalhe values (3640, 2, '1.1.2.9.3.04.00.00.00.00', '(-) PERDAS ESTIMADAS EM CRÉDITOS DE DÍVIDA ATIVA TRIBUTÁRIA', 'Compreende o ajuste para perdas estimadas com o não recebimento dos créditos inscritos em dívida ativa tributária.', 2, false, 0, ' ');
insert into contabilidade.planocontadetalhe values (3641, 2, '1.1.2.9.4.00.00.00.00.00', '(-) AJUSTE DE PERDAS DE CRÉDITOS A CURTO PRAZO - INTER OFSS - ESTADO', 'Compreende o ajuste para perdas estimadas com o não recebimento de valores referentes a créditos a curto prazo, por inadimplência de terceiros e outras. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3642, 2, '1.1.2.9.4.02.00.00.00.00', '(-) PERDAS ESTIMADAS EM CLIENTE', 'Compreende o ajuste para perdas estimadas com o não recebimento das faturas/duplicatas a receber decorrentes de vendas de mercadorias ou da prestação de serviços.', 2, false, 0, ' ');
