insert into contabilidade.planocontadetalhe values (3646, 2, '1.1.2.9.5.01.00.00.00.00', '(-) PERDAS ESTIMADAS EM CRÉDITOS TRIBUTÁRIOS A RECEBER', 'Compreende o ajuste para perdas estimadas com o não recebimento dos créditos tributários', 2, false, 0, ' ');
