insert into contabilidade.planocontadetalhe values (3650, 2, '1.1.3.9.0.00.00.00.00.00', '(-) AJUSTE DE PERDAS DE DEMAIS CRÉDITOS E VALORES A CURTO PRAZO', 'Compreende o ajuste de perdas estimadas com o não recebimento de valores referentes a demais créditos e valores a curto prazo, por inadimplência de terceiros e outras.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3651, 2, '1.1.3.9.1.00.00.00.00.00', '(-) AJUSTE DE PERDAS DE DEMAIS CRÉDITOS E VALORES A CURTO PRAZO - CONSOLIDAÇÃO', 'Compreende o ajuste de perdas estimadas com o não recebimento de valores referentes a demais créditos e valores a curto prazo, por inadimplência de terceiros e outras. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3652, 2, '1.1.3.9.1.04.00.00.00.00', '(-) AJUSTE  PARA PERDAS EM CRÉDITOS POR DANOS AO PATRIMÔNIO', 'Compreende os valores das provisões para perdas de créditos por danos ao patrimônio, verificados em processos administrativos ou apurados em tomada de contas especial.', 2, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (3653, 2, '1.1.4.9.0.00.00.00.00.00', '(-) AJUSTE DE PERDAS DE INVESTIMENTOS E APLICAÇÕES TEMPORÁRIAS', 'Compreende a diferença entre o valor recuperável do ativo e seu valor contábil, quando o primeiro for menor.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3654, 2, '1.1.4.9.1.00.00.00.00.00', '(-) AJUSTE DE PERDAS DE INVESTIMENTOS E APLICAÇÕES TEMPORÁRIAS - CONSOLIDAÇÃO', 'Compreende os ajustes de perdas estimadas e redução a valor recuperável de investimentos e aplicações temporárias. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3655, 2, '1.1.5.9.0.00.00.00.00.00', '(-) AJUSTE DE PERDAS DE ESTOQUES', 'Compreende o registro das perdas conhecidas em estoques e calculadas por estimativa, relativas a estoques deteriorados ou obsoletos e para dar cobertura a diferenças físicas, quando tais perdas não puderem ser baixadas das próprias contas, pelo fato de não estarem identificados os itens específicos e por constituírem estimativas, bem como o registro do ajuste  de perdas para os estoque que tiverem o valor de mercado inferior ao seu custo.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3656, 2, '1.1.5.9.1.00.00.00.00.00', '(-) AJUSTE DE PERDAS DE ESTOQUES - CONSOLIDAÇÃO', 'Compreende o registro das perdas conhecidas em estoques e calculadas por estimativa, relativas a estoques deteriorados ou obsoletos e para dar cobertura a diferenças físicas, quando tais perdas não puderem ser baixadas das próprias contas, pelo fato de não estarem identificados os itens específicos e por constituírem estimativas, bem como o registro do ajuste  de perdas para os estoque que tiverem o valor de mercado inferior ao seu custo. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3657, 2, '1.1.6.9.0.00.00.00.00.00', '(-) REDUÇÃO A VALOR RECUPERÁVEL DE ATIVOS MANTIDOS PARA VENDA', 'Compreende os valores lançados a título de redução a valor recuperável de ativos mantidos para venda, segundo um plano de venda com prazo inferior a doze meses.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3658, 2, '1.1.6.9.1.00.00.00.00.00', '(-) REDUÇÃO A VALOR RECUPERÁVEL DE ATIVOS MANTIDOS PARA VENDA - CONSOLIDAÇÃO', 'Compreende os valores lançados a título de redução a valor recuperável de ativos mantidos para venda, segundo um plano de venda com prazo inferior a doze meses. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (3659, 2, '1.1.6.9.2.00.00.00.00.00', '(-) REDUÇÃO A VALOR RECUPERÁVEL DE ATIVOS MANTIDOS PARA VENDA - INTRA OFSS', 'Compreende os valores lançados a título de redução a valor recuperável de ativos mantidos para venda, segundo um plano de venda com prazo inferior a doze meses. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do ente.', 2, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (3660, 2, '1.1.6.9.3.00.00.00.00.00', '(-) REDUÇÃO A VALOR RECUPERÁVEL DE ATIVOS MANTIDOS PARA VENDA - INTER OFSS - UNIÃO', 'Compreende os valores lançados a título de redução a valor recuperável de ativos mantidos para venda, segundo um plano de venda com prazo inferior a doze meses. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 2, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (3661, 2, '1.1.6.9.4.00.00.00.00.00', '(-) REDUÇÃO A VALOR RECUPERÁVEL DE ATIVOS MANTIDOS PARA VENDA - INTER OFSS - ESTADO', 'Compreende os valores lançados a título de redução a valor recuperável de ativos mantidos para venda, segundo um plano de venda com prazo inferior a doze meses. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 2, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (3662, 2, '1.1.6.9.5.00.00.00.00.00', '(-) REDUÇÃO A VALOR RECUPERÁVEL DE ATIVOS MANTIDOS PARA VENDA - INTER OFSS - MUNICÍPIO', 'Compreende os valores lançados a título de redução a valor recuperável de ativos mantidos para venda, segundo um plano de venda com prazo inferior a doze meses. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 2, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (3663, 2, '1.2.1.1.1.99.00.00.00.00', '(-) AJUSTE DE PERDAS DE CRÉDITOS A LONGO PRAZO', 'Compreende o ajuste de perdas estimadas com o não recebimento de valores referentes a créditos a longo prazo, por inadimplência de terceiros e outras.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3664, 2, '1.2.1.1.1.99.04.00.00.00', '(-) AJUSTE DE PERDAS DE DÍVIDA ATIVA TRIBUTÁRIA', 'Compreende o ajuste para cobertura de perdas estimadas na cobrança de dívida ativa tributária.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3665, 2, '1.2.1.1.2.99.00.00.00.00', '(-) AJUSTE DE PERDAS DE CRÉDITOS A LONGO PRAZO', 'Compreende os ajustes de perdas estimadas com o não recebimento de valores referentes a créditos a longo prazo, por inadimplência de terceiros e outras.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3666, 2, '1.2.1.1.3.99.00.00.00.00', '(-) AJUSTE DE PERDAS DE CRÉDITOS A LONGO PRAZO', 'Compreende os ajustes de perdas estimadas s com o não recebimento de valores referentes a créditos a longo prazo, por inadimplência de terceiros e outras.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3975, 2, '2.2.8.2.0.00.00.00.00.00', 'OBRIGAÇÕES POR DANOS A TERCEIROS A LONGO PRAZO', 'Compreende os valores exigíveis no longo prazo, provenientes de danos a terceiros.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3667, 2, '1.2.1.1.4.99.00.00.00.00', '(-) AJUSTE DE PERDAS DE CRÉDITOS A LONGO PRAZO', 'Compreende os ajustes de perdas estimadas com o não recebimento de valores referentes a créditos a longo prazo, por inadimplência de terceiros e outras.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3668, 2, '1.2.1.1.5.99.00.00.00.00', '(-) AJUSTE DE PERDAS DE CRÉDITOS A LONGO PRAZO', 'Compreende os ajustes de perdas estimadas s com o não recebimento de valores referentes a créditos a longo prazo, por inadimplência de terceiros e outras.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3669, 2, '1.2.3.9.1.01.00.00.00.00', '(-) REDUÇÃO AO VALOR RECUPERÁVEL DE IMOBILIZADO - BENS MÓVEIS', 'Compreende os valores de ajuste ao valor recuperável de bens moveis, quando esse for inferior ao valor liquido contábil.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3670, 2, '1.2.1.2.1.99.00.00.00.00', '(-) AJUSTE DE PERDAS DE DEMAIS CRÉDITOS E VALORES A LONGO PRAZO', 'Compreende o ajuste de perdas estimadas com o não recebimento de valores referentes a demais créditos a longo prazo, por inadimplência de terceiros e outras.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3671, 2, '1.2.1.3.1.99.00.00.00.00', '(-) AJUSTE DE PERDAS DE INVESTIMENTOS E APLICAÇÕES TEMPORÁRIAS A LONGO PRAZO', 'Compreende a diferença entre o valor recuperável do ativo e seu valor contábil, quando o primeiro for menor.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3672, 2, '1.2.3.9.1.02.00.00.00.00', '(-) REDUÇÃO AO VALOR RECUPERÁVEL DE IMOBILIZADO - BENS IMÓVEIS', 'Compreende os valores de ajuste ao valor recuperável de bens imóveis, quando esse for inferior ao valor liquido contábil.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3673, 2, '1.2.2.8.0.00.00.00.00.00', '(-) DEPRECIAÇÃO ACUMULADA DE INVESTIMENTOS', 'Compreende a diminuição do valor dos elementos do ativo investimento devido a desgaste pelo uso, ação da natureza ou obsolescência, quando couber, como a depreciação das propriedades mantidas para investimento.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3674, 2, '1.2.2.8.1.00.00.00.00.00', '(-) DEPRECIAÇÃO ACUMULADA DE INVESTIMENTOS - CONSOLIDAÇÃO', 'Compreende a diminuição do valor dos elementos do ativo investimento devido a desgaste pelo uso, ação da natureza ou obsolescência, quando couber, como a depreciação das propriedades mantidas para investimento. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3675, 2, '1.2.2.8.1.01.00.00.00.00', '(-) DEPRECIAÇÃO ACUMULADA DE INVESTIMENTOS - CONSOLIDAÇÃO - PROPRIEDADES PARA INVESTIMENTO', 'Compreende a diminuição do valor dos elementos do ativo investimento devido a desgaste pelo uso, ação da natureza ou obsolescência, quando couber, das propriedades mantidas para investimento.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3676, 2, '1.2.2.9.0.00.00.00.00.00', '(-) REDUÇÃO AO VALOR RECUPERÁVEL DE INVESTIMENTOS', 'Compreende os valores de ajuste ao valor recuperável de investimentos, quando esse for inferior ao valor lÍquido contábil.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3677, 2, '1.2.2.9.1.00.00.00.00.00', '(-) REDUÇÃO AO VALOR RECUPERÁVEL DE INVESTIMENTOS - CONSOLIDAÇÃO', 'Compreende os valores de ajuste ao valor recuperável de investimentos, quando esse for inferior ao valor liquido contábil. . Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3678, 2, '1.2.2.9.1.01.00.00.00.00', '(-) REDUÇÃO AO VALOR RECUPERÁVEL DE INVESTIMENTOS - PARTICIPAÇÕES PERMANENTES', 'Compreende os valores de ajuste ao valor recuperável de participações permanentes, quando esse for inferior ao valor liquido contábil.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3679, 2, '1.2.2.9.1.02.00.00.00.00', '(-) REDUÇÃO AO VALOR RECUPERÁVEL DE PROPRIEDADES PARA INVESTIMENTO', 'Compreende os valores de ajuste ao valor recuperável de propriedades para investimento, quando esse for inferior ao valor liquido contábil.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3680, 2, '1.2.2.9.2.00.00.00.00.00', '(-) REDUÇÃO AO VALOR RECUPERÁVEL DE INVESTIMENTOS-INTRA OFSS', 'Compreende os valores de ajuste ao valor recuperável de investimentos, quando esse for inferior ao valor liquido contábil. . Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do ente.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3681, 2, '1.2.2.9.3.00.00.00.00.00', '(-) REDUÇÃO AO VALOR RECUPERÁVEL DE INVESTIMENTOS-INTER OFSS - UNIÃO', 'Compreende os valores de ajuste ao valor recuperável de investimentos, quando esse for inferior ao valor liquido contábil. . Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3682, 2, '1.2.2.9.4.00.00.00.00.00', '(-) REDUÇÃO AO VALOR RECUPERÁVEL DE INVESTIMENTOS - INTER OFSS - ESTADO', 'Compreende os valores de ajuste ao valor recuperável de investimentos, quando esse for inferior ao valor liquido contábil. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3683, 2, '1.2.2.9.5.00.00.00.00.00', '(-) REDUÇÃO AO VALOR RECUPERÁVEL DE INVESTIMENTOS - INTER OFSS - MUNICÍPIO', 'Compreende os valores de ajuste ao valor recuperável de investimentos, quando esse for inferior ao valor liquido contábil. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3684, 2, '1.2.3.8.0.00.00.00.00.00', '(-) DEPRECIAÇÃO, EXAUSTÃO E AMORTIZAÇÃO ACUMULADAS', 'Compreende a diminuição do valor dos elementos do ativo imobilizado devido a desgaste pelo uso, ação da natureza ou obsolescência, bem como a perda do valor, decorrente de sua exploração, de direitos cujo objeto sejam recursos minerais ou florestais ou bens aplicados nessa exploração e a perda do valor do capital aplicado na aquisição de direitos de propriedade industrial ou comercial e quaisquer outros com existência ou exercício de duração limitada ou cujo objeto sejam bens de utilização por prazo legal ou contratualmente limitado.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3685, 2, '1.2.3.8.1.00.00.00.00.00', '(-) DEPRECIAÇÃO, EXAUSTÃO E AMORTIZAÇÃO ACUMULADAS - CONSOLIDAÇÃO', 'Compreende a diminuição do valor dos elementos do ativo imobilizado devido a desgaste pelo uso, ação da natureza ou obsolescência, bem como a perda do valor, decorrente de sua exploração, de direitos cujo objeto sejam recursos minerais ou florestais ou bens aplicados nessa exploração e a perda do valor do capital aplicado na aquisição de direitos de propriedade industrial ou comercial e quaisquer outros com existência ou exercício de duração limitada ou cujo objeto sejam bens de utilização por prazo legal ou contratualmente limitado. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3686, 2, '1.2.3.8.1.01.00.00.00.00', '(-) DEPRECIAÇÃO ACUMULADA - BENS MÓVEIS', 'Compreende a diminuição do valor dos elementos do ativo imobilizado, bens móveis, devido a desgaste pelo uso, ação da natureza ou obsolescência.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4614, 2, '2.3.7.2.5.02.00.00.00.00', 'LUCROS E PREJUÍZOS ACUMULADOS DE EXERCÍCIOS ANTERIORES', 'Registra o saldo dos lucros e prejuízos acumulados nos exercícios anteriores das empresas.', 3, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (3687, 2, '1.2.3.8.1.02.00.00.00.00', '(-) DEPRECIAÇÃO ACUMULADA - BENS IMÓVEIS', 'Compreende a diminuição do valor dos elementos do ativo imobilizado, bens imóveis, devido a desgaste pelo uso, ação da natureza ou obsolescência.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3688, 2, '1.2.3.9.0.00.00.00.00.00', '(-) REDUÇÃO AO VALOR RECUPERÁVEL DE IMOBILIZADO', 'Compreende os valores de ajuste ao valor recuperável do imobilizado, quando esse for inferior ao valor liquido contábil.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3689, 2, '1.2.3.9.1.00.00.00.00.00', '(-) REDUÇÃO AO VALOR RECUPERÁVEL DE IMOBILIZADO - CONSOLIDAÇÃO', 'Compreende os valores de ajuste ao valor recuperável do imobilizado, quando esse for inferior ao valor liquido contábil. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3690, 2, '1.2.4.8.0.00.00.00.00.00', '(-) AMORTIZAÇÃO ACUMULADA', 'Compreende a diminuição do valor do capital aplicado na aquisição de direitos da propriedade industrial ou comercial e quaisquer outros com existência ou exercício de duração limitada, ou cujo objeto sejam bens de utilização por prazo legal ou contratualmente limitado.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3691, 2, '1.2.4.8.1.00.00.00.00.00', '(-) AMORTIZAÇÃO ACUMULADA - CONSOLIDAÇÃO', 'Compreende a diminuição do valor do capital aplicado na aquisição de direitos da propriedade industrial ou comercial e quaisquer outros com existência ou exercício de duração limitada, ou cujo objeto sejam bens de utilização por prazo legal ou contratualmente limitado. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3692, 2, '1.2.4.9.0.00.00.00.00.00', '(-) REDUÇÃO AO VALOR RECUPERÁVEL DE INTANGÍVEL', 'Compreende os valores de ajuste ao valor recuperável do ativo intangível, quando esse for inferior ao valor liquido contábil.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3693, 2, '1.2.4.9.1.00.00.00.00.00', '(-) REDUÇÃO AO VALOR RECUPERÁVEL DE INTANGÍVEL - CONSOLIDAÇÃO', 'Compreende os valores de ajuste ao valor recuperável do ativo intangível, quando esse for inferior ao valor liquido contábil. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3694, 2, '1.2.5.9.0.00.00.00.00.00', '(-) AMORTIZAÇÃO ACUMULADA', 'Compreende a perda do valor do capital aplicado em despesas pré-operacionais e gastos de reestruturação. ', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3695, 2, '1.2.5.9.1.00.00.00.00.00', '(-) AMORTIZAÇÃO ACUMULADA - CONSOLIDAÇÃO', 'Compreende a perda do valor do capital aplicado em despesas pré-operacionais e gastos de reestruturação. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3696, 2, '2.0.0.0.0.00.00.00.00.00', 'PASSIVO E PATRIMÔNIO LÍQUIDO', 'Passivo compreende as obrigações existentes da entidade oriundas de eventos passados de cuja liquidação se espera que resulte em fluxo de saída de recursos que incorporem benefícios econômicos ou serviços em potencial. Patrimônio liquido compreende a diferença entre o ativo e o passivo.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3697, 2, '2.1.0.0.0.00.00.00.00.00', 'PASSIVO CIRCULANTE', 'Compreende as obrigações conhecidas e estimadas que atendam a qualquer um dos seguintes critérios: tenham prazos estabelecidos ou esperados dentro do ciclo operacional da entidade; sejam mantidos primariamente para negociação; tenham prazos estabelecidos ou esperados no curto prazo; sejam valores de terceiros ou retenções em nome deles, quando a entidade do setor público for fiel depositaria, independentemente do prazo de exigibilidade.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3698, 2, '2.1.1.0.0.00.00.00.00.00', 'OBRIGAÇÕES TRABALHISTAS, PREVIDENCIÁRIAS E ASSISTENCIAIS A PAGAR A CURTO PRAZO', 'Compreende as obrigações referentes a salários ou remunerações, bem como benefícios aos quais o empregado ou servidor tenha direito, aposentadorias, reformas, pensões e encargos a pagar, benefícios assistenciais, inclusive os precatórios decorrentes dessas obrigações, com vencimento no curto prazo.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3699, 2, '2.1.2.1.3.01.00.00.00.00', 'EMPRÉSTIMOS INTERNOS - EM TÍTULOS', 'Compreende os valores das operações de créditos internas decorrentes da emissão de títulos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3700, 2, '2.1.1.1.0.00.00.00.00.00', 'PESSOAL A PAGAR', 'Compreende as obrigações a curto prazo referentes a salários ou remunerações, bem como benefícios aos quais o empregado ou servidor tenha direito, quando pagos em data posterior a qual forem incorridos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3701, 2, '2.1.1.1.1.00.00.00.00.00', 'PESSOAL A PAGAR - CONSOLIDAÇÃO', 'Compreende as obrigações referentes a salários ou remunerações, bem como benefícios aos quais o empregado ou servidor tenha direito, quando pagos em data posterior a qual forem incorridos. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3702, 2, '2.1.1.1.1.01.00.00.00.00', 'PESSOAL A PAGAR', 'Compreende as obrigações referentes a salários ou remunerações, bem como benefícios aos quais o empregado ou servidor tenha direito.', 2, false, 0, ' ');
insert into contabilidade.planocontadetalhe values (3703, 2, '2.1.1.4.2.21.00.00.00.00', 'OBRIGAÇÃO DE REPASSE PARA COBERTURA DE DÉFICIT DO RPPS', 'Compreende os valores relativos a obrigação de repasse para cobertura de deficit do RPPS não repassado dentro do mês de competencia.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3704, 2, '2.1.1.1.1.04.00.00.00.00', 'PRECATÓRIOS DE PESSOAL - REGIME ESPECIAL', 'Compreende as obrigações referentes a precatórios de salários ou remunerações, bem como a benefícios aos quais o empregado ou servidor tenha direito, sujeitos ao regime especial instituído pela emenda constitucional 62/ 2009.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3705, 2, '2.1.1.1.1.05.00.00.00.00', 'PRECATÓRIOS DE PESSOAL - REGIME ORDINÁRIO', 'Compreende as obrigações referentes a precatórios de proventos de aposentadoria, reformas ou pensões,  não sujeitos ao regime especial instituído pela emenda constitucional 62/ 2009.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3706, 2, '2.1.1.2.0.00.00.00.00.00', 'BENEFÍCIOS PREVIDENCIÁRIOS A PAGAR', 'Compreende as obrigações a curto prazo referentes a proventos de aposentadoria, reformas ou pensões aos quais o aposentado, reformado ou pensionista tenha direito, quando pagos em data posterior a qual forem incorridos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3746, 2, '2.1.2.1.3.05.00.00.00.00', 'PROGRAMA DE APOIO À REESTRUTURAÇÃO E AO AJUSTE FISCAL DOS MUNICÍPIOS', 'Compreende a obrigação decorrente da assunção e do refinanciamento, pela União, da dívida pública de Municípios, nos termos da MP nº 2.185-35, de 24 de agosto de 2001.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3707, 2, '2.1.1.2.1.00.00.00.00.00', 'BENEFÍCIOS PREVIDENCIÁRIOS A PAGAR - CONSOLIDAÇÃO', 'Compreende as obrigações referentes a proventos de aposentadoria, reformas ou pensões aos quais o aposentado, reformado ou pensionista tenha direito, quando pagos em data posterior a qual forem incorridos. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3708, 2, '2.1.1.2.1.04.00.00.00.00', 'PRECATÓRIOS DE BENEFÍCIOS PREVIDENCIÁRIOS - REGIME ESPECIAL', 'Compreende as obrigações referentes a precatórios de proventos de aposentadoria, reformas ou pensões, sujeitos ao regime especial instituído pela emenda constitucional 62/ 2009.', 2, false, 0, 'X');
insert into contabilidade.planocontadetalhe values (3752, 2, '2.1.2.2.0.00.00.00.00.00', 'EMPRÉSTIMOS A CURTO PRAZO - EXTERNO', 'Compreende os empréstimos contratuais ou mobiliários assumidos no exterior e transacionados, em regra, em moeda estrangeira, com vencimento no curto prazo.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3709, 2, '2.1.1.2.1.05.00.00.00.00', 'PRECATÓRIOS DE BENEFÍCIOS PREVIDENCIÁRIOS - REGIME ORDINÁRIO', 'Compreende as obrigações referentes a precatórios de proventos de aposentadoria, reformas ou pensões,  não sujeitos ao regime especial instituído pela emenda constitucional 62/ 2009.', 2, false, 0, 'X');
insert into contabilidade.planocontadetalhe values (3710, 2, '2.1.1.2.2.00.00.00.00.00', 'BENEFÍCIOS PREVIDENCIÁRIOS A PAGAR - INTRA OFSS', 'Compreende as obrigações referentes a proventos de aposentadoria, reformas ou pensões aos quais o aposentado, reformado ou pensionista tenha direito, quando pagos em data posterior a qual forem incorridos. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) do mesmo ente.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3711, 2, '2.1.1.2.2.05.00.00.00.00', 'COMPENSAÇÃO FINANCEIRA ENTRE REGIMES PREVIDENCIÁRIOS', 'Compreende os valores relativos a obrigações a pagar decorrentes de compensação financeira entre RGPS e RPPS, por contagem recíproca de tempo de contribuição.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3712, 2, '2.1.1.2.3.00.00.00.00.00', 'BENEFÍCIOS PREVIDENCIÁRIOS A PAGAR - INTER OFSS - UNIÃO', 'Compreende as obrigações referentes a proventos de aposentadoria, reformas ou pensões aos quais o aposentado, reformado ou pensionista tenha direito, quando pagos em data posterior a qual forem incorridos. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 2, false, 0, 'N');
