insert into contabilidade.planocontadetalhe values (3714, 2, '2.1.1.2.4.00.00.00.00.00', 'BENEFÍCIOS PREVIDENCIÁRIOS A PAGAR - INTER OFSS - ESTADO', 'Compreende as obrigações referentes a proventos de aposentadoria, reformas ou pensões aos quais o aposentado, reformado ou pensionista tenha direito, quando pagos em data posterior a qual forem incorridos. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um Estado.', 2, false, 0, 'N');
