insert into contabilidade.planocontadetalhe values (3718, 2, '2.1.1.3.0.00.00.00.00.00', 'BENEFÍCIOS ASSISTENCIAIS A PAGAR', 'Compreende as obrigações a curto prazo relativas aos benefícios assistenciais administrados pela previdência social, quando pagos em data posterior a qual forem incorridos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3719, 2, '2.1.1.3.1.00.00.00.00.00', 'BENEFÍCIOS ASSISTENCIAIS A PAGAR - CONSOLIDAÇÃO', 'Compreende as obrigações relativas aos benefícios assistenciais, quando pagos em data posterior a qual forem incorridos. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3720, 2, '2.1.1.3.1.03.00.00.00.00', 'PRECATÓRIOS DE BENEFÍCIOS ASSISTENCIAIS - REGIME ESPECIAL', 'Compreende as obrigações referentes a precatórios de benefícios assistenciais, sujeitos ao regime especial instituído pela emenda constitucional 62/ 2009.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3721, 2, '2.1.1.3.1.04.00.00.00.00', 'PRECATÓRIOS DE BENEFÍCIOS ASSISTENCIAIS - REGIME ORDINÁRIO', 'Compreende as obrigações referentes a precatórios de benefícios assistenciais,  não sujeitos ao regime especial instituído pela emenda constitucional 62/ 2009.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3722, 2, '2.1.2.1.3.02.00.00.00.00', 'EMPRÉSTIMOS INTERNOS - EM CONTRATOS', 'Compreende os valores das operações de crédito internas em contratos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3723, 2, '2.1.1.4.0.00.00.00.00.00', 'ENCARGOS SOCIAIS A PAGAR', 'Compreende as obrigações a curto prazo das unidades relativas a despesas incorridas e não pagas, em beneficio de seus servidores, empregados e familiares, compulsoriamente ou não, incluindo aquelas que se destinam ao financiamento da seguridade social de responsabilidade do poder público e as demais contribuições sociais.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3724, 2, '2.1.1.4.1.00.00.00.00.00', 'ENCARGOS SOCIAIS A PAGAR-CONSOLIDAÇÃO', 'Compreende as obrigações das unidades relativas a despesas incorridas e não pagas, em beneficio de seus servidores, empregados e familiares, compulsoriamente ou não, incluindo aquelas que se destinam ao financiamento da seguridade social de responsabilidade do poder público e as demais contribuições sociais. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3725, 2, '2.1.1.4.1.01.00.00.00.00', 'CONTRIBUIÇÕES AO RGPS A PAGAR', 'Registra os valores relativos as contribuições a previdência social, incidentes sobre salários e remunerações pagos e sobre serviços de terceiros.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3785, 2, '2.1.3.2.1.01.00.00.00.00', 'FORNECEDORES ESTRANGEIROS A CURTO PRAZO', 'Compreende os valores a pagar aos fornecedores estrangeiros de bens, materiais e serviços envolvidos com as atividades operacionais da entidade.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3726, 2, '2.1.4.1.2.00.00.00.00.00', 'OBRIGAÇÕES FISCAIS A CURTO PRAZO COM A UNIÃO - INTRA OFSS', 'Compreende as obrigações das entidades com o governo federal relativas a impostos, taxas e contribuições, com vencimento no curto prazo.Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do ente.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3727, 2, '2.1.1.4.2.00.00.00.00.00', 'ENCARGOS SOCIAIS A PAGAR - INTRA OFSS', 'Compreende as obrigações a curto prazo das unidades relativas a despesas incorridas e não pagas, em beneficio de seus servidores, empregados e familiares, compulsoriamente ou não, incluindo aquelas que se destinam ao financiamento da seguridade social de responsabilidade do poder público e as demais contribuições sociais. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do ente.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3728, 2, '2.1.1.4.2.22.00.00.00.00', 'OBRIGAÇÃO DE REPASSE CONCEDIDO AO RPPS PARA PAGAMENTO DE APOSENTADORIAS E PENSÕES DA FONTE TESOURO', 'Compreende os valores relativos a obrigação de repasse concedido ao RPPS para pagamento de aposentadorias e pensões de  responsabilidade da fonte tesouro não repassadas dentro do mês de competencia.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3729, 2, '2.1.1.4.2.23.00.00.00.00', 'OBRIGAÇÕES PATRONAIS A RECOLHER - PLANO DE SEGURIDADE  SOCIAL DO SERVIDOR', 'Compreende os valores das obrigações patronais devidas pelo ente para o   plano de seguridade social do servidor liquidadas e  ainda não pagas.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3730, 2, '2.1.1.4.3.00.00.00.00.00', 'ENCARGOS SOCIAIS A PAGAR - INTER OFSS - UNIÃO', 'Compreende as obrigações das unidades relativas a despesas incorridas e não pagas, em beneficio de seus servidores, empregados e familiares, compulsoriamente ou não, incluindo aquelas que se destinam ao financiamento da seguridade social de responsabilidade do poder público e as demais contribuições sociais. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3731, 2, '2.1.1.4.3.01.00.00.00.00', 'CONTRIBUIÇÕES AO RGPS A PAGAR', 'Compreende os valores relativos as contribuições a previdência social, incidentes sobre salários e remunerações pagos e sobre serviços de terceiros.', 2, false, 0, 'N');
