insert into contabilidade.planocontadetalhe values (3814, 2, '2.1.7.3.1.02.00.00.00.00', 'PROVISÃO PARA PAGAMENTOS DE AUTUAÇÕES FISCAIS - ESFERA JUDICIAL', 'Compreende os valores das provisões para pagamento de autuações fiscais que já se encontram na esfera judicial.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3815, 2, '2.1.7.4.0.00.00.00.00.00', 'PROVISÃO PARA RISCOS CÍVEIS A CURTO PRAZO', 'Compreende os passivos de prazo ou de valor incertos, relacionados a pagamento de indenizações a fornecedores e clientes, com probabilidade de ocorrerem no curto prazo.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3816, 2, '2.1.7.5.0.00.00.00.00.00', 'PROVISÃO PARA REPARTIÇÃO DE CRÉDITOS A CURTO PRAZO', 'Compreende os passivos de prazo ou de valores incertos relacionados aos créditos tributários e não tributários reconhecidos no lançamento por parte do agente arrecadador, a serem repartidos com outros entes da federação ou entidades, conforme previsão legal. Na arrecadação, esta provisão será revertida em conta específica de passivo.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3817, 2, '2.1.7.5.1.00.00.00.00.00', 'PROVISÃO PARA REPARTIÇÃO DE CRÉDITOS A CURTO PRAZO - CONSOLIDAÇÃO', 'Compreende os passivos de prazo ou de valores incertos relacionados aos créditos tributários e não tributários reconhecidos no lançamento por parte do agente arrecadador, a serem repartidos a outras entidades, conforme previsão legal. Na arrecadação, esta provisão será revertida em conta específica de passivo. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (3818, 2, '2.1.8.5.1.00.00.00.00.00', 'DIVIDENDOS E JUROS SOBRE CAPITAL PRÓPRIO A PAGAR - CONSOLIDAÇÃO', 'Compreende os dividendos aprovados pela assembleia geral a serem pagos aos acionistas e os valores a serem pagos a título de remuneração do capital próprio. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3819, 2, '8.9.3.3.0.00.00.00.00.00', 'OUTRAS OPERAÇÕES QUE INTEGRAM A DÍVIDA CONSOLIDADA', 'Compreende o valor de outras operações que  integram o conceito de dívida consolidada.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3820, 2, '2.1.7.5.3.00.00.00.00.00', 'PROVISÃO PARA REPARTIÇÃO DE CRÉDITOS A CURTO PRAZO - INTER OFSS - UNIÃO', 'Compreende os passivos de prazo ou de valores incertos relacionados aos créditos tributários e não tributários reconhecidos no lançamento por parte do agente arrecadador, a serem repartidos com outros entes da federação. Na arrecadação, esta provisão será revertida em conta de passivo referente a obrigações de repartição a outros entes. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União. Na arrecadação, esta provisão será revertida em conta específica de passivo.', 2, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (3821, 2, '2.1.7.5.4.00.00.00.00.00', 'PROVISÃO PARA REPARTIÇÃO DE CRÉDITOS A CURTO PRAZO - INTER OFSS - ESTADO', 'Compreende os passivos de prazo ou de valores incertos relacionados aos créditos tributários e não tributários reconhecidos no lançamento por parte do agente arrecadador, a serem repartidos com outros entes da federação. Na arrecadação, esta provisão será revertida em conta de passivo referente a obrigações de repartição a outros entes. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado. Na arrecadação, esta provisão será revertida em conta específica de passivo.', 2, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (3822, 2, '2.1.7.5.5.00.00.00.00.00', 'PROVISÃO PARA REPARTIÇÃO DE CRÉDITOS A CURTO PRAZO - INTER OFSS - MUNICÍPIO', 'Compreende os passivos de prazo ou de valores incertos relacionados aos créditos tributários e não tributários reconhecidos no lançamento por parte do agente arrecadador, a serem repartidos com outros entes da federação. Na arrecadação, esta provisão será revertida em conta de passivo referente a obrigações de repartição a outros entes. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município. Na arrecadação, esta provisão será revertida em conta específica de passivo.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3823, 2, '2.1.7.6.0.00.00.00.00.00', 'PROVISÃO PARA RISCOS DECORRENTES DE CONTRATOS DE PPP A CURTO PRAZO', 'Compreende os passivos de prazo ou de valores incertos relacionados aos riscos de demanda, construção, disponibilidade ou outros riscos decorrentes de contratos de PPP, de acordo com a Lei n. 11.079/2004.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3824, 2, '2.1.7.6.1.00.00.00.00.00', 'PROVISÃO PARA RISCOS DECORRENTES DE CONTRATOS DE PPP A CURTO PRAZO - CONSOLIDAÇÃO', 'Compreende os passivos de prazo ou de valores incertos relacionados aos riscos de demanda, construção, disponibilidade ou outros riscos decorrentes de contratos de PPP, de acordo com a Lei n. 11.079/2004. Compreende os valores de operações efetuadas entre uma unidade pertencente ao orçamento fiscal e da seguridade social (OFSS) com pessoa ou unidade que não pertença ao OFSS de ente público, alem dos demais fatos que não compreendem transações entre partes.', 2, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (3825, 2, '2.1.7.7.0.00.00.00.00.00', 'PROVISÃO PARA OBRIGAÇÕES DECORRENTES DA ATUAÇÃO GOVERNAMENTAL A CURTO PRAZO', 'Compreende os passivos de prazo ou de valores incertos relacionados a programas governamentais, como subsídios, auxílios, desonerações, assunção de obrigações ou outros.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3826, 2, '2.1.7.7.1.00.00.00.00.00', 'PROVISÃO PARA OBRIGAÇÕES DECORRENTES DA ATUAÇÃO GOVERNAMENTAL A CURTO PRAZO - CONSOLIDAÇÃO', 'Compreende/Registra os passivos de prazo ou de valores incertos relacionados a programas governamentais, como subsídios, auxílios, desonerações, assunção de obrigações ou outros. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (3827, 2, '2.1.7.9.0.00.00.00.00.00', 'OUTRAS PROVISÕES A CURTO PRAZO', 'Compreende os demais passivos de prazo ou de valor incertos, com probabilidade de ocorrerem no curto prazo, não classificadas anteriormente neste plano de contas.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3828, 2, '2.1.7.9.1.00.00.00.00.00', 'OUTRAS PROVISÕES A CURTO PRAZO - CONSOLIDAÇÃO', 'Compreende os demais passivos de prazo ou de valor incertos, com probabilidade de ocorrerem no curto prazo, não classificadas anteriormente neste plano de contas. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3829, 2, '2.1.8.0.0.00.00.00.00.00', 'DEMAIS OBRIGAÇÕES A CURTO PRAZO', 'Compreende as obrigações da entidade junto a terceiros não inclusas nos subgrupos anteriores, com vencimento no curto prazo, inclusive os precatórios decorrentes dessas obrigações, com vencimento no curto prazo.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3830, 2, '2.1.8.1.0.00.00.00.00.00', 'ADIANTAMENTOS DE CLIENTES', 'Compreende as antecipações recebidas por operações de fornecimento de bens ou prestação de serviços e que ensejem a devolução da quantia recebida, caso a operação não ocorra, nos termos do art. 29, inciso III da LC 101/2000.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3831, 2, '2.1.8.1.1.00.00.00.00.00', 'ADIANTAMENTOS DE CLIENTES - CONSOLIDAÇÃO', 'Compreende as antecipações recebidas por operações de fornecimento de bens ou prestação de serviços e que ensejem a devolução da quantia recebida, caso a operação não ocorra, nos termos do art. 29, inciso III da LC 101/2000. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (3832, 2, '2.1.8.2.0.00.00.00.00.00', 'OBRIGAÇÕES POR DANOS A TERCEIROS', 'Compreende os valores exigíveis no curto prazo, provenientes de danos a terceiros.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3833, 2, '2.1.8.2.1.00.00.00.00.00', 'OBRIGAÇÕES POR DANOS A TERCEIROS - CONSOLIDAÇÃO', 'Compreende os valores exigíveis no curto prazo, provenientes de danos a terceiros. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'X');
insert into contabilidade.planocontadetalhe values (3834, 2, '2.1.8.3.0.00.00.00.00.00', 'ARRENDAMENTO OPERACIONAL A PAGAR', 'Compreende as obrigações a curto prazo referentes a arrendamentos mercantis, nos quais não são transferidos ao arrendador os riscos e benefícios inerentes a propriedade, não havendo a possibilidade de opção de compra do bem arrendado.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3835, 2, '2.1.8.3.1.00.00.00.00.00', 'ARRENDAMENTO OPERACIONAL A PAGAR - CONSOLIDAÇÃO', 'Compreende as obrigações a curto prazo referentes a arrendamentos mercantis, nos quais não são transferidos ao arrendador os riscos e benefícios inerentes a propriedade, não havendo a possibilidade de opção de compra do bem arrendado. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3836, 2, '2.1.8.4.0.00.00.00.00.00', 'DEBÊNTURES E OUTROS TÍTULOS DE DÍVIDA A CURTO PRAZO', 'Compreende os títulos emitidos pela entidade que conferirão aos seus titulares direito de credito contra ela, nas condições constantes da escritura de emissão do titulo, com vencimento no curto prazo.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3837, 2, '2.1.8.4.1.00.00.00.00.00', 'DEBÊNTURES E OUTROS TÍTULOS DE DÍVIDA A CURTO PRAZO - CONSOLIDAÇÃO', 'Compreende os títulos emitidos pela entidade que conferirão aos seus titulares direito de credito contra ela, nas condições constantes da escritura de emissão do titulo, com vencimento no curto prazo. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3838, 2, '2.1.8.6.0.00.00.00.00.00', 'OBRIGAÇÕES DECORRENTES DE CONTRATOS DE PPP', 'Compreende os passivos decorrentes dos contratos de Parceria Público Privada - PPP. Deve abranger tanto a contraprestação referente à incorporação dos ativos quanto a referente à prestação dos serviços objeto do contrato, incluindo a parcela variável condicionada à qualidade do serviço.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3839, 2, '2.1.8.6.1.00.00.00.00.00', 'OBRIGAÇÕES DECORRENTES DE CONTRATOS DE PPP - CONSOLIDAÇÃO', 'Compreende os passivos decorrentes dos contratos de Parceria Público Privada - PPP. Deve abranger tanto a contraprestação referente à incorporação dos ativos quanto a referente à prestação dos serviços objeto do contrato, incluindo a parcela variável condicionada à qualidade do serviço. Compreende os valores de operações efetuadas entre uma unidade pertencente ao orçamento fiscal e da seguridade social (OFSS) com pessoa ou unidade que não pertença ao OFSS de ente público, alem dos demais fatos que não compreendem transações entre partes.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3840, 2, '2.1.8.7.0.00.00.00.00.00', 'DEPÓSITOS DE INSTITUIÇÕES AUTORIZADAS A OPERAR PELO BACEN', 'Compreende as disponibilidades mantidas no Bacen por diversas instituições, a exemplo das reservas bancárias e depósitos compulsórios. Conta de uso exclusivo da União.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3841, 2, '2.1.8.7.1.00.00.00.00.00', 'DEPÓSITOS DE INSTITUIÇÕES AUTORIZADAS A OPERAR PELO BACEN - CONSOLIDAÇÃO', 'Compreende as disponibilidades mantidas no Bacen por diversas instituições, a exemplo das reservas bancárias e depósitos compulsórios. Conta de uso exclusivo da União. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (3842, 2, '2.1.8.8.0.00.00.00.00.00', 'VALORES RESTITUÍVEIS', 'Compreende os valores de terceiros ou retenções em nome deles, quando a entidade do setor público for fiel depositaria, exigíveis no curto prazo.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3843, 2, '2.1.8.8.1.00.00.00.00.00', 'VALORES RESTITUÍVEIS - CONSOLIDAÇÃO', 'Compreende os valores de terceiros ou retenções em nome deles, quando a entidade do setor público for fiel depositaria, exigíveis no curto prazo. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3844, 2, '2.1.8.8.1.01.00.00.00.00', 'CONSIGNAÇÕES ', 'Compreende os valores entregues em confiança ou em consignações, geralmente retidos em folha de pagamento de empregados ou servidores ou nos pagamentos referentes a compras de bens e serviços.', 2, false, 0, ' ');
insert into contabilidade.planocontadetalhe values (3845, 2, '2.1.8.8.1.03.00.00.00.00', 'DEPÓSITOS JUDICIAIS', 'Compreende os valores de obrigações, decorrentes de depósitos recebidos por determinação judicial e depósitos para recursos judiciais.', 2, false, 0, ' ');
insert into contabilidade.planocontadetalhe values (3846, 2, '2.1.8.8.1.04.00.00.00.00', 'DEPÓSITOS NÃO JUDICIAIS', 'Compreende os valores de obrigações, decorrentes de depósitos recebidos, exceto depósitos judiciais.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3847, 2, '2.1.8.9.0.00.00.00.00.00', 'OUTRAS OBRIGAÇÕES A CURTO PRAZO', 'Compreende outras obrigações não classificáveis em grupos específicos deste plano de contas, com vencimento no curto prazo.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3848, 2, '2.1.8.9.1.00.00.00.00.00', 'OUTRAS OBRIGAÇÕES A CURTO PRAZO - CONSOLIDAÇÃO', 'Compreende outras obrigações não classificáveis em grupos específicos deste plano de contas, com vencimento no curto prazo. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3849, 2, '2.1.8.9.1.01.00.00.00.00', 'INDENIZAÇÕES E RESTITUIÇÕES', 'Compreende as obrigações relativas a indenizações e restituições.', 2, false, 0, ' ');
insert into contabilidade.planocontadetalhe values (3850, 2, '2.1.8.9.1.05.00.00.00.00', 'CONVÊNIOS A PAGAR', 'Compreende os valores a pagar retidos a título de convênio.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3895, 2, '2.2.2.2.0.00.00.00.00.00', 'EMPRÉSTIMOS A LONGO PRAZO - EXTERNO', 'Compreende os empréstimos contratuais ou mobiliários assumidos no exterior e transacionados, em regra, em moeda estrangeira, com vencimento no longo prazo.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3851, 2, '2.1.8.9.1.09.00.00.00.00', 'TERMOS DE PARCERIA A PAGAR', 'Compreende os valores a pagar retidos a título de termo de parceria, que é um instrumento jurídico de fomento e gestão das relações de parceria entre organizações do terceiro setor - qualificadas como organização da sociedade civil de interesse público - OSCIP, e o poder público, com objetivo de imprimir maior agilidade gerencial aos projetos, reduzir as excessivas exigências burocráticas e realizar controle dos resultados. O Termo de Parceria foi instituído e disciplinado pela Lei nº 9.790/99, de 23 de março de 1999 e Decreto nº 3.100/99.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3852, 2, '2.1.8.9.2.00.00.00.00.00', 'OUTRAS OBRIGAÇÕES A CURTO PRAZO - INTRA OFSS', 'Compreende outras obrigações não classificáveis em grupos específicos deste plano de contas, com vencimento no curto prazo. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do ente.', 2, false, 0, 'X');
insert into contabilidade.planocontadetalhe values (3853, 2, '2.2.0.0.0.00.00.00.00.00', 'PASSIVO NÃO-CIRCULANTE', 'Compreende as obrigações conhecidas e estimadas que não atendam a nenhum dos critérios para serem classificadas no passivo circulante.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3854, 2, '2.2.1.0.0.00.00.00.00.00', 'OBRIGAÇÕES TRABALHISTAS, PREVIDENCIÁRIAS E ASSISTENCIAIS A PAGAR A LONGO PRAZO', 'Compreende as obrigações referentes a salários ou remunerações, bem como benefícios aos quais o empregado ou servidor tenha direito, aposentadorias, reformas, pensões e encargos a pagar, benefícios assistenciais, inclusive os precatórios decorrentes dessas obrigações, com vencimento no longo prazo.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3855, 2, '2.2.1.1.0.00.00.00.00.00', 'PESSOAL A PAGAR', 'Compreende as obrigações a longo prazo referentes a salários ou remunerações, bem como benefícios aos quais o empregado ou servidor tenha direito, quando pagos em data posterior a qual forem incorridos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3856, 2, '2.2.1.1.1.00.00.00.00.00', 'PESSOAL A PAGAR - CONSOLIDAÇÃO', 'Compreende as obrigações a longo prazo referentes a salários ou remunerações, bem como benefícios aos quais o empregado ou servidor tenha direito, quando pagos em data posterior a qual forem incorridos. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3857, 2, '2.2.1.1.1.03.00.00.00.00', 'PRECATÓRIOS DE PESSOAL - REGIME ESPECIAL', 'Compreende as obrigações referentes a precatórios de salários ou remunerações, bem como a benefícios aos quais o empregado ou servidor tenha direito, sujeitos ao regime especial instituído pela emenda constitucional 62/ 2009.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3858, 2, '2.2.1.1.1.04.00.00.00.00', 'PRECATÓRIOS DE PESSOAL - REGIME ORDINÁRIO', 'Compreende as obrigações referentes a precatórios de proventos de aposentadoria, reformas ou pensões,  não sujeitos ao regime especial instituído pela emenda constitucional 62/ 2009.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3859, 2, '2.2.1.2.0.00.00.00.00.00', 'BENEFÍCIOS PREVIDENCIÁRIOS A PAGAR', 'Compreende as obrigações a longo prazo referentes a proventos de aposentadoria, reformas ou pensões aos quais o aposentado, reformado ou pensionista tenha direito, quando pagos em data posterior a qual forem incorridos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3860, 2, '2.2.1.2.1.00.00.00.00.00', 'BENEFÍCIOS PREVIDENCIÁRIOS A PAGAR - CONSOLIDAÇÃO', 'Compreende as obrigações a longo prazo referentes a proventos de aposentadoria, reformas ou pensões aos quais o aposentado, reformado ou pensionista tenha direito, quando pagos em data posterior a qual forem incorridos. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3861, 2, '8.9.3.3.1.00.00.00.00.00', 'PARCELAMENTO DE DÍVIDAS', 'Compreende os montantes referentes ao parcelamento de dívidas.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3862, 2, '2.2.1.2.1.02.00.00.00.00', 'PRECATÓRIOS DE BENEFÍCIOS PREVIDENCIÁRIOS - REGIME ESPECIAL', 'Compreende as obrigações referentes a precatórios de proventos de aposentadoria, reformas ou pensões, sujeitos ao regime especial instituído pela emenda constitucional 62/ 2009.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3863, 2, '2.2.1.2.1.03.00.00.00.00', 'PRECATÓRIOS DE BENEFÍCIOS PREVIDENCIÁRIOS - REGIME ORDINÁRIO', 'Compreende as obrigações referentes a precatórios de proventos de aposentadoria, reformas ou pensões,  não sujeitos ao regime especial instituído pela emenda constitucional 62/ 2009.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3864, 2, '2.3.3.4.0.00.00.00.00.00', 'CORREÇÃO MONETÁRIA DO CAPITAL REALIZADO', 'Compreende o resultado da correção monetária do capital realizado, enquanto não capitalizado.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3865, 2, '2.2.1.3.0.00.00.00.00.00', 'BENEFÍCIOS ASSISTENCIAIS A PAGAR', 'Compreende as obrigações a longo prazo relativas aos benefícios assistenciais, quando pagos em data posterior a qual forem incorridos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3866, 2, '2.2.1.3.1.00.00.00.00.00', 'BENEFÍCIOS ASSISTENCIAIS A PAGAR - CONSOLIDAÇÃO', 'Compreende as obrigações a longo prazo relativas aos benefícios assistenciais, quando pagos em data posterior a qual forem incorridos. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3867, 2, '2.2.1.3.1.02.00.00.00.00', 'PRECATÓRIOS DE BENEFÍCIOS ASSISTENCIAIS - REGIME ESPECIAL', 'Compreende as obrigações referentes a precatórios de benefícios assistenciais, sujeitos ao regime especial instituído pela emenda constitucional 62/ 2009.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3868, 2, '2.2.1.3.1.03.00.00.00.00', 'PRECATÓRIOS DE BENEFÍCIOS ASSISTENCIAIS - REGIME ORDINÁRIO', 'Compreende as obrigações referentes a precatórios de benefícios assistenciais,  não sujeitos ao regime especial instituído pela emenda constitucional 62/ 2009.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3869, 2, '2.2.1.4.0.00.00.00.00.00', 'ENCARGOS SOCIAIS A PAGAR', 'Compreende as obrigações a longo prazo das unidades relativas a despesas incorridas e não pagas, em beneficio de seus servidores, empregados e familiares, compulsoriamente ou não, incluindo aquelas que se destinam ao financiamento da seguridade social de responsabilidade do poder público e as demais contribuições sociais.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3870, 2, '2.2.1.4.1.00.00.00.00.00', 'ENCARGOS SOCIAIS A PAGAR - CONSOLIDAÇÃO', 'Compreende as obrigações a longo prazo das unidades relativas a despesas incorridas e não pagas, em beneficio de seus servidores, empregados e familiares, compulsoriamente ou não, incluindo aquelas que se destinam ao financiamento da seguridade social de responsabilidade do poder público e as demais contribuições sociais. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3871, 2, '2.2.1.4.2.00.00.00.00.00', 'ENCARGOS SOCIAIS A PAGAR - INTRA OFSS', 'Compreende as obrigações a longo prazo das unidades relativas a despesas incorridas e não pagas, em beneficio de seus servidores, empregados e familiares, compulsoriamente ou não, incluindo aquelas que se destinam ao financiamento da seguridade social de responsabilidade do poder público e as demais contribuições sociais. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do ente.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3872, 2, '2.2.1.4.3.00.00.00.00.00', 'ENCARGOS SOCIAIS A PAGAR - INTER OFSS - UNIÃO', 'Compreende as obrigações a longo prazo das unidades relativas a despesas incorridas e não pagas, em beneficio de seus servidores, empregados e familiares, compulsoriamente ou não, incluindo aquelas que se destinam ao financiamento da seguridade social de responsabilidade do poder público e as demais contribuições sociais. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3873, 2, '2.2.1.4.3.01.00.00.00.00', 'INSS A PAGAR', 'Compreende os valores relativos as contribuições a previdência social, incidentes sobre salários e remunerações pagos e sobre serviços de terceiros.', 2, false, 0, 'N');
