insert into contabilidade.planocontadetalhe values (3904, 2, '2.2.2.5.0.00.00.00.00.00', 'JUROS E ENCARGOS A PAGAR DE EMPRÉSTIMOS E FINANCIAMENTOS A LONGO PRAZO - INTERNO', 'Compreende os juros e encargos financeiros referentes a empréstimos e financiamentos, reconhecidos pelo regime de competência e pagáveis a longo prazo, assumidos dentro do país e transacionados, em regra, em moeda nacional, com vencimento no longo prazo.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (3905, 2, '2.2.7.4.1.00.00.00.00.00', 'PROVISÃO PARA RISCOS CÍVEIS A LONGO PRAZO - CONSOLIDAÇÃO', 'Compreende os passivos de prazo ou de valor incertos, relacionados a pagamento de indenizações a fornecedores e clientes, com probabilidade de ocorrerem no longo prazo. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
