insert into contabilidade.planocontadetalhe values (4040, 2, '2.3.4.0.0.00.00.00.00.00', 'AJUSTES DE AVALIAÇÃO PATRIMONIAL', 'Compreende as contrapartidas de aumentos ou diminuições de valor atribuídos a elementos do ativo e do passivo em decorrência da sua avaliação a valor justo, nos casos previstos pela lei 6.404/76 ou em normas expedidas pela comissão de valores mobiliários, enquanto não computadas no resultado do exercício em obediência ao regime de competência.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4041, 2, '2.3.4.1.0.00.00.00.00.00', 'AJUSTES DE AVALIAÇÃO PATRIMONIAL DE ATIVOS', 'Compreende as contrapartidas de aumentos ou diminuições de valor atribuídos a elementos do ativo em decorrência da sua avaliação a valor justo, nos casos previstos pela lei 6.404/76 ou em normas expedidas pela comissão de valores mobiliários, enquanto não computadas no resultado do exercício.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4042, 2, '4.1.1.2.0.00.00.00.00.00', 'IMPOSTOS SOBRE PATRIMÔNIO E A RENDA', 'Compreende os impostos sobre patrimônio e a renda, como por exemplo: imposto sobre a propriedade territorial rural, imposto sobre a propriedade predial e territorial urbana, imposto sobre a transmissão de bens imóveis e de direitos a eles relativos e impostos sobre a renda e proventos de qualquer natureza.', 2, false, 0, 'N');
