insert into contabilidade.planocontadetalhe values (4044, 2, '2.3.4.2.0.00.00.00.00.00', 'AJUSTES DE AVALIAÇÃO PATRIMONIAL DE PASSIVOS', 'Compreende as contrapartidas de aumentos ou diminuições de valor atribuídos a elementos do passivo em decorrência da sua avaliação a valor justo, nos casos previstos pela lei 6.404/76 ou em normas expedidas pela comissão de valores mobiliários, enquanto não computadas no resultado do exercício.', 2, false, 0, 'N');
