insert into contabilidade.planocontadetalhe values (4112, 2, '2.3.6.9.2.00.00.00.00.00', 'OUTRAS RESERVAS - INTRA OFSS', 'Compreende outras reservas que não forem classificadas como reservas de capital ou de lucro. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do mesmo ente.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4113, 2, '2.3.6.9.3.00.00.00.00.00', 'OUTRAS RESERVAS - INTER OFSS - UNIÃO', 'Compreende outras reservas que não forem classificadas como reservas de capital ou de lucro. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4114, 2, '2.3.6.9.4.00.00.00.00.00', 'OUTRAS RESERVAS - INTER OFSS - ESTADO', 'Compreende outras reservas que não forem classificadas como reservas de capital ou de lucro. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4115, 2, '2.3.6.9.5.00.00.00.00.00', 'OUTRAS RESERVAS - INTER OFSS - MUNICÍPIO', 'Compreende outras reservas que não forem classificadas como reservas de capital ou de lucro. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4116, 2, '4.1.1.0.0.00.00.00.00.00', 'IMPOSTOS', 'Compreende como imposto o tributo cuja obrigação tem por fato gerador uma situação independente de qualquer atividade estatal especifica, relativa ao contribuinte.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4117, 2, '4.0.0.0.0.00.00.00.00.00', 'VARIAÇÃO PATRIMONIAL AUMENTATIVA', 'Compreende o aumento no beneficio econômico durante o período contábil sob a forma de entrada de recurso ou aumento de ativo ou diminuição de passivo, que resulte em aumento do patrimônio liquido e que não sejam provenientes de aporte dos proprietários.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4118, 2, '4.1.0.0.0.00.00.00.00.00', 'IMPOSTOS, TAXAS E CONTRIBUIÇÕES DE MELHORIA', 'Compreende toda prestação pecuniária compulsória, em moeda ou cujo valor nela se possa exprimir, que não constitua sanção de ato ilícito, instituída em lei e cobrada mediante atividade administrativa plenamente vinculada. Como: impostos, taxas e contribuições de melhoria.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4119, 2, '4.1.1.1.0.00.00.00.00.00', 'IMPOSTOS SOBRE COMERCIO EXTERIOR', 'Compreende os impostos sobre operações de comercio exterior, como por exemplo: impostos sobre a importação e imposto sobre a exportação.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4120, 2, '4.1.1.1.1.00.00.00.00.00', 'IMPOSTOS SOBRE COMERCIO EXTERIOR - CONSOLIDAÇÃO', 'Compreende os impostos sobre operações de comercio exterior, como exemplo: impostos sobre a importação e imposto sobre a exportação. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4121, 2, '4.1.1.2.1.00.00.00.00.00', 'IMPOSTOS SOBRE PATRIMÔNIO E A RENDA - CONSOLIDAÇÃO', 'Compreende os impostos sobre patrimônio e a renda, como exemplo: imposto sobre a propriedade territorial rural,imposto sobre a propriedade predial e territorial urbana,imposto sobre a transmissão de bens imóveis e de direitos a eles relativos e imposto sobre a renda e proventos de qualquer natureza. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4122, 2, '4.1.1.2.1.03.00.00.00.00', 'IMPOSTO SOBRE A RENDA E PROVENTOS DE QUALQUER NATUREZA', 'Compreende a variação patrimonial aumentativa decorrente de imposto sobre a renda e proventos de qualquer natureza, retidos na fonte.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4123, 2, '4.1.1.3.0.00.00.00.00.00', 'IMPOSTOS SOBRE A PRODUÇÃO E A CIRCULAÇÃO', 'Compreende os impostos sobre a produção e a circulação, como por exemplo: imposto sobre produtos industrializados; imposto sobre operações de credito, câmbio e seguro, e sobre operações relativas a títulos e valores mobiliários; imposto sobre serviços de qualquer natureza.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4124, 2, '4.1.1.3.1.00.00.00.00.00', 'IMPOSTOS SOBRE A PRODUÇÃO E A CIRCULAÇÃO - CONSOLIDAÇÃO', 'Compreende os impostos sobre a produção e a circulação como, por exemplo, imposto sobre produtos industrializados;imposto sobre operações de crédito, cambio e seguro, e sobre operações relativas a títulos e valores mobiliários, imposto sobre serviços de qualquer natureza.Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4125, 2, '4.1.1.4.0.00.00.00.00.00', 'IMPOSTOS EXTRAORDINÁRIOS', 'Compreende os impostos instituídos pela União, temporariamente, na iminência ou no caso de guerra externa, suprimidos, gradativamente, no prazo Maximo de cinco anos, contados da celebração da paz.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4127, 2, '4.1.1.9.0.00.00.00.00.00', 'OUTROS IMPOSTOS', 'Compreende os demais impostos não classificados nos grupos anteriores.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4128, 2, '4.1.1.9.1.00.00.00.00.00', 'OUTROS IMPOSTOS - CONSOLIDAÇÃO', 'Compreende os demais impostos não classificados nos grupos anteriores. Compreende os valores de operações efetuadas entre uma unidade pertinente ao orçamento fiscal e da seguridade social (OFSS) com pessoa ou unidade que não pertença ao OFSS de ente público, alem dos demais fatos que não compreendem transações entre partes.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4129, 2, '4.1.2.0.0.00.00.00.00.00', 'TAXAS', 'Compreende as taxas cobradas pela União, pelos estados, pelo distrito federal ou pelos municípios, no âmbito de suas respectivas atribuições, tem como fato gerador o exercício regular do poder de policia, ou a utilização, efetiva ou potencial, de serviço público específico e divisível, prestado ao contribuinte ou posto a sua disposição.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4130, 2, '4.1.2.1.0.00.00.00.00.00', 'TAXAS PELO EXERCÍCIO DO PODER DE POLICIA', 'Compreende as taxas pelo poder de policia aquelas decorrentes das atividades da administração pública que, limitando ou disciplinando direito, interesse ou liberdade, regula a prática de ato ou abstenção de fato, em razão de interesse público.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4131, 2, '4.1.2.1.1.00.00.00.00.00', 'TAXAS PELO EXERCÍCIO DO PODER DE POLICIA - CONSOLIDAÇÃO', 'Compreende as taxas pelo poder de policia aquelas decorrentes das atividades da administração pública que, limitando ou disciplinando direito, interesse ou liberdade, regula a pratica de ato ou abstenção de fato em razão de interesse público. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4132, 2, '4.1.2.1.1.11.00.00.00.00', 'TAXA DE FISCALIZAÇÃO DE VIGILÂNCIA SANITÁRIA', 'Compreende as taxas pelo poder de policia aquelas decorrentes das atividades da administração pública que, limitando ou disciplinando direito, interesse ou liberdade, regula a pratica de ato ou abstenção de fato em razão de interesse público. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) - Taxa de Fiscalização de Vigilância Sanitária.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4437, 2, '8.1.1.0.0.00.00.00.00.00', 'EXECUÇÃO DOS ATOS POTENCIAIS ATIVOS', 'Compreende a execução dos atos e fatos que possa vir a afetar o ativo da entidade governamental.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4133, 2, '4.1.2.1.1.15.00.00.00.00', 'TAXA DE SERVIÇOS ADMINISTRATIVO', 'Compreende as taxas pelo poder de policia aquelas decorrentes das atividades da administração pública que, limitando ou disciplinando direito, interesse ou liberdade, regula a pratica de ato ou abstenção de fato em razão de interesse público. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) - Taxas de Serviços Administrativos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4134, 2, '4.1.2.2.0.00.00.00.00.00', 'TAXAS PELA PRESTAÇÃO DE SERVIÇOS', 'Compreende as taxas cobradas pela União, pelos estados, pelo distrito federal ou pelos municípios, no âmbito de suas respectivas atribuições, tem como fato gerador a utilização, efetiva ou potencial, de serviço público específico e divisível, prestado ao contribuinte ou posto a sua disposição.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4135, 2, '4.1.2.2.1.00.00.00.00.00', 'TAXAS PELA PRESTAÇÃO DE SERVIÇOS - CONSOLIDAÇÃO', 'Compreende as taxas cobradas pela União, pelos estados, pelo distrito federal ou pelos municípios, no âmbito de suas respectivas atribuições tem como fato gerador a utilização, efetiva ou potencial, de serviço público específico e divisível prestado ao contribuinte ou posto a sua disposição. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4136, 2, '4.1.3.0.0.00.00.00.00.00', 'CONTRIBUIÇÕES DE MELHORIA', 'Compreende como contribuição de melhoria o tributo cobrado pela União, pelos estados, pelo distrito federal ou pelos municípios, no âmbito de suas respectivas atribuições, sendo instituída para fazer face ao custo de obras públicas de que decorra valorização imobiliária, tendo como limite total a despesa realizada e como limite individual o acréscimo de valor que da obra resultar para cada imóvel beneficiado.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4137, 2, '4.1.3.1.0.00.00.00.00.00', 'CONTRIBUIÇÃO DE MELHORIA PELA EXPANSÃO DA REDE DE ÁGUA POTÁVEL E ESGOTO SANITÁRIO', 'Compreende o valor da arrecadação de receita de contribuição de melhoria decorrente de valorização de propriedades em função da expansão da rede de água potável e esgoto sanitário.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4138, 2, '4.1.3.1.1.00.00.00.00.00', 'CONTRIBUIÇÃO DE MELHORIA PELA EXPANSÃO DA REDE DE ÁGUA POTÁVEL E ESGOTO SANITÁRIO - CONSOLIDAÇÃO', 'Compreende o valor da arrecadação de receita de contribuição de melhoria decorrente de valorização de propriedade em função da pavimentação asiática, bem como pela colocação de guias, sarjetas e calcamento. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4139, 2, '6.1.2.0.0.00.00.00.00.00', 'EXECUÇÃO DO PLOA', 'Compreende o somatório dos valores monetários de receitas e despesas previstos no projeto de lei orçamentária durante as suas fases de tramitação.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4140, 2, '4.1.3.2.1.00.00.00.00.00', 'CONTRIBUIÇÃO DE MELHORIA PELA EXPANSÃO DA REDE DE ILUMINAÇÃO PÚBLICA NA CIDADE - CONSOLIDAÇÃO', 'Compreende o valor da arrecadação de receita de contribuição de melhoria decorrente de valorização de propriedades em função da expansão da rede iluminação pública na cidade. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS). Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4141, 2, '4.1.3.3.0.00.00.00.00.00', 'CONTRIBUIÇÃO DE MELHORIA PELA EXPANSÃO DE REDE DE ILUMINAÇÃO PÚBLICA RURAL', 'Compreende o valor da arrecadação de receita sobre a cobrança decorrente de valorização de propriedades em função da expansão da rede de iluminação pública rural.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4142, 2, '4.1.3.3.1.00.00.00.00.00', 'CONTRIBUIÇÃO DE MELHORIA PELA EXPANSÃO DE REDE DE ILUMINAÇÃO PÚBLICA RURAL - CONSOLIDAÇÃO', 'Compreende o valor da arrecadação de receita de contribuição de melhoria decorrente de valorização de propriedades em função da expansão da rede iluminação pública rural. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4143, 2, '4.1.3.4.0.00.00.00.00.00', 'CONTRIBUIÇÃO DE MELHORIA PELA PAVIMENTAÇÃO E OBRAS COMPLEMENTARES', 'Compreende o valor da arrecadação de receita de contribuição de melhoria decorrente de valorização de propriedades em função da pavimentação asfáltica, bem como pela colocação de guias, sarjetas e calçamento.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4144, 2, '4.1.3.4.1.00.00.00.00.00', 'CONTRIBUIÇÃO DE MELHORIA PELA PAVIMENTAÇÃO E OBRAS COMPLEMENTARES - CONSOLIDAÇÃO', 'Compreende o valor da arrecadação de receita de contribuição de melhoria decorrente de valorização de propriedades em função da pavimentação asfáltica, bem como pela colocação de guias, sarjetas e calçamento. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4145, 2, '4.1.3.9.0.00.00.00.00.00', 'OUTRAS CONTRIBUIÇÕES DE MELHORIA', 'Compreende o valor de outras contribuições de melhorias, não classificadas em itens específicos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4148, 2, '4.2.1.0.0.00.00.00.00.00', 'CONTRIBUIÇÕES SOCIAIS', 'Compreendem como contribuições sociais: a) as das empresas, incidentes sobre a remuneração paga ou creditada aos segurados a seu serviço; b) as dos empregadores domésticos; c) as dos trabalhadores, incidentes sobre o seu salário-de-contribuição; d) as sobre a receita e faturamento; e) as sobre o lucro; f) do importador de bens ou serviços do exterior; g) e outros', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4149, 2, '4.2.1.1.0.00.00.00.00.00', 'CONTRIBUIÇÕES SOCIAIS - RPPS', 'Compreende a contribuição patronal e a contribuição do segurado destinada ao custeio do regime próprio de previdência social.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4150, 2, '4.2.1.1.1.00.00.00.00.00', 'CONTRIBUIÇÕES SOCIAIS - RPPS - CONSOLIDAÇÃO', 'Compreende a contribuição patronal e a contribuição do segurado destinada ao custeio do regime próprio de previdência social. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4151, 2, '4.2.1.1.1.01.00.00.00.00', 'CONTRIBUIÇÕES PATRONAIS AO RPPS', 'Compreende a contribuição patronal destinada ao custeio do Regime Próprio de Previdência Social.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4152, 2, '4.2.1.1.1.02.00.00.00.00', 'CONTRIBUIÇÃO DO SEGURADO AO RPPS', 'Compreende a contribuição ao RPPS dos segurados, servidor ativo, servidor inativo e pensionista sobre a sua remuneração.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4153, 2, '4.2.1.1.2.00.00.00.00.00', 'CONTRIBUIÇÕES SOCIAIS - RPPS - INTRA OFSS', 'Compreende a contribuição patronal e a contribuição do segurado destinada ao custeio do regime próprio de previdência social. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do ente.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4155, 2, '4.2.1.1.3.00.00.00.00.00', 'CONTRIBUIÇÕES SOCIAIS - RPPS - INTER OFSS - UNIÃO', 'Compreende a contribuição patronal e a contribuição do segurado destinada ao custeio do regime próprio de previdência social. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4156, 2, '4.2.1.1.3.01.00.00.00.00', 'CONTRIBUIÇÕES PATRONAIS AO RPPS', 'Compreende a contribuição patronal destinada ao custeio do regime proprio de previdencia social.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4157, 2, '4.6.3.4.0.00.00.00.00.00', ' GANHOS COM INCORPORAÇÃO DE ATIVOS POR PRODUÇÃO', 'Compreende a contrapartida da incorporação de novos ativos por produção como, por exemplo, produção agrícola e laticínia.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4158, 2, '4.2.1.1.4.00.00.00.00.00', 'CONTRIBUIÇÕES SOCIAIS - RPPS - INTER OFSS - ESTADO', 'Compreende a contribuição patronal e a contribuição do segurado destinada ao custeio do regime próprio de previdência social. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4159, 2, '4.2.1.1.4.01.00.00.00.00', 'CONTRIBUIÇÕES PATRONAIS AO RPPS', 'Compreende a contribuicao patronal destinada ao custeio do regime proprio de previdencia social.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4160, 2, '4.2.1.1.5.00.00.00.00.00', 'CONTRIBUIÇÕES SOCIAIS - RPPS - INTER OFSS - MUNICÍPIO', 'Compreende a contribuição patronal e a contribuição do segurado destinada ao custeio do regime próprio de previdência social. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4161, 2, '4.2.1.1.5.01.00.00.00.00', 'CONTRIBUIÇÕES PATRONAIS AO RPPS', 'Compreende a contribuicao patronal destinada ao custeio do regime proprio de previdencia social.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4162, 2, '4.2.1.2.0.00.00.00.00.00', 'CONTRIBUIÇÕES SOCIAIS - RGPS', 'Compreende a contribuição patronal e a contribuição do segurado destinada ao custeio do regime geral de previdência social.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4163, 2, '4.2.1.2.1.00.00.00.00.00', 'CONTRIBUIÇÕES SOCIAIS - RGPS - CONSOLIDAÇÃO', 'Compreende a contribuição patronal e a contribuição do segurado destinada ao custeio do regime geral de previdência social. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4164, 2, '4.2.1.2.3.00.00.00.00.00', 'CONTRIBUIÇÕES SOCIAIS - RGPS - INTER OFSS - UNIÃO', 'Compreende a contribuição patronal e a contribuição do segurado destinada ao custeio do regime geral de previdência social. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4165, 2, '4.2.1.2.4.00.00.00.00.00', 'CONTRIBUIÇÕES SOCIAIS - RGPS - INTER OFSS - ESTADO', 'Compreende a contribuição patronal e a contribuição do segurado destinada ao custeio do regime geral de previdência social. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4166, 2, '4.2.1.2.5.00.00.00.00.00', 'CONTRIBUIÇÕES SOCIAIS - RGPS - INTER OFSS - MUNICÍPIO', 'Compreende a contribuição patronal e a contribuição do segurado destinada ao custeio do regime geral de previdência social. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4167, 2, '4.2.1.3.0.00.00.00.00.00', 'CONTRIBUIÇÃO SOBRE A RECEITA OU O FATURAMENTO', 'Compreende a contribuição do empregador, da empresa e da entidade a ela equiparada na forma da lei, incidentes sobre a receita ou o faturamento, como por exemplo: COFINS, PIS/PASEP.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4168, 2, '4.2.1.3.1.00.00.00.00.00', 'CONTRIBUIÇÃO SOBRE A RECEITA OU O FATURAMENTO - CONSOLIDAÇÃO', 'Compreende a contribuição do empregador, da empresa e da entidade a ela equiparada na forma da lei, incidentes sobre a receita ou o faturamento, como por exemplo: COFINS, PIS/PASEP. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4169, 2, '4.2.1.4.0.00.00.00.00.00', 'CONTRIBUIÇÃO SOBRE O LUCRO', 'Compreende a contribuição do empregador, da empresa e da entidade a ela equiparada na forma da lei, incidentes sobre o lucro, como por exemplo: CSLL.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4170, 2, '4.2.1.4.1.00.00.00.00.00', 'CONTRIBUIÇÃO SOBRE O LUCRO - CONSOLIDAÇÃO', 'Compreende a contribuição do empregador,da empresa e da entidade a ela equiparada na forma da lei, incidentes sobre o lucro, como por exemplo: CSLL. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4171, 2, '4.2.1.5.0.00.00.00.00.00', 'CONTRIBUIÇÃO SOBRE RECEITA DE CONCURSO DE PROGNOSTICO', 'Compreende a contribuição sobre a receita de concursos de prognósticos, que são todos e quaisquer concursos de sorteios de números, loterias, apostas, inclusive as realizadas em reuniões hípicas, nos âmbitos federal, estadual, do Distrito Federal e municipais.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4172, 2, '4.2.1.5.1.00.00.00.00.00', 'CONTRIBUIÇÃO SOBRE RECEITA DE CONCURSO DE PROGNOSTICO - CONSOLIDAÇÃO', 'Compreende a contribuição sobre a receita de concursos de prognósticos, que são todos e quaisquer concursos de sorteios de números, loterias, apostas, inclusive as realizadas em reuniões hípicas, nos âmbitos federal, estadual, do Distrito Federal e municipais. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS). Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4173, 2, '4.2.1.6.0.00.00.00.00.00', 'CONTRIBUIÇÃO DO IMPORTADOR DE BENS OU SERVIÇOS DO EXTERIOR', 'Compreende a contribuição social paga pelo importador de bens ou serviços do exterior, ou de quem a lei a ele equiparar.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4174, 2, '4.2.1.6.1.00.00.00.00.00', 'CONTRIBUIÇÃO DO IMPORTADOR DE BENS OU SERVIÇOS DO EXTERIOR - CONSOLIDAÇÃO', 'Compreende a contribuição social paga pelo importador de bens ou serviços do exterior, ou de quem a lei a ele equiparar. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4175, 2, '4.2.1.9.0.00.00.00.00.00', 'OUTRAS CONTRIBUIÇÕES SOCIAIS', 'Compreende o valor de outras contribuições sociais, não classificadas em itens específicos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4176, 2, '4.2.1.9.1.00.00.00.00.00', 'OUTRAS CONTRIBUIÇÕES SOCIAIS - CONSOLIDAÇÃO', 'Compreende o valor de outras contribuições sociais, não classificadas em itens específicos. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4177, 2, '4.2.1.9.1.01.00.00.00.00', 'CONTRIBUIÇÃO SOCIAL PARA O FINANCIAMENTO DA SEGURIDADE SOCIAL', 'Compreende o somatório das contribuições para o financiamento da  seguridade social recebidas dos servidores municipais.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4178, 2, '4.2.2.0.0.00.00.00.00.00', 'CONTRIBUIÇÕES DE INTERVENÇÃO NO DOMÍNIO ECONÔMICO', 'Compreendem as contribuições de intervenção no domínio econômico, como por exemplo, a CIDE-combustível.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4179, 2, '4.2.2.0.1.00.00.00.00.00', 'CONTRIBUIÇÕES DE INTERVENÇÃO NO DOMÍNIO ECONÔMICO - CONSOLIDAÇÃO', 'Compreendem as contribuições de intervenção no domínio econômico, como por exemplo, a CIDE combustível. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4180, 2, '4.2.3.0.0.00.00.00.00.00', 'CONTRIBUIÇÃO DE ILUMINAÇÃO PÚBLICA', 'Compreende as contribuições de iluminação pública, nos termos do artigo 149-a da constituição federal, acrescentado pela emenda constitucional n.ºª 39/02, sendo facultada a cobrança da contribuição na fatura de consumo de energia elétrica.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4181, 2, '4.2.3.0.1.00.00.00.00.00', 'CONTRIBUIÇÃO DE ILUMINAÇÃO PÚBLICA - CONSOLIDAÇÃO', 'Compreende as contribuições de iluminação pública, nos termos do artigo 149-a da constituição federal, acrescentado pela emenda constitucional n.ºª 39/02, sendo facultada a cobrança da contribuição na fatura de consumo de energia elétrica. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4182, 2, '4.2.4.0.0.00.00.00.00.00', 'CONTRIBUIÇÕES DE INTERESSE DAS CATÉGORIAS PROFISSIONAIS', 'Compreende as variações patrimoniais aumentativas provenientes de contribuições de interesse das categorias profissionais.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4183, 2, '4.2.4.0.1.00.00.00.00.00', 'CONTRIBUIÇÕES DE INTERESSE DAS CATEGORIAS PROFISSIONAIS - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais aumentativas provenientes de contribuições de interesse das categorias profissionais. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4184, 2, '4.3.0.0.0.00.00.00.00.00', 'EXPLORAÇÃO E VENDA DE BENS, SERVIÇOS E DIREITOS', 'Compreende as variações patrimoniais aumentativas auferidas com a exploração e venda de bens, serviços e direitos, que resultem em aumento do patrimônio liquido, independentemente de ingresso, segregando-se a venda bruta das deduções como devoluções, abatimentos e descontos comerciais concedidos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4185, 2, '6.2.2.1.2.00.00.00.00.00', 'CREDITO INDISPONÍVEL', 'Compreende o valor da indisponibilidade de credito orçamentário pelo seu contingenciamento ou liberação pendentes de autorização legislativa.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4186, 2, '4.3.1.1.1.00.00.00.00.00', 'VENDA BRUTA DE MERCADORIAS - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais aumentativas auferidas com a venda bruta de mercadorias, que resultem em aumento do patrimônio liquido, independentemente de ingresso. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4187, 2, '4.3.2.0.0.00.00.00.00.00', 'VENDA DE PRODUTOS', 'Compreende as variações patrimoniais aumentativas auferidas com a venda de produtos, que resultem em aumento do patrimônio liquido, segregando-se a venda bruta das deduções como devoluções, abatimentos e descontos comerciais concedidos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4188, 2, '4.3.2.1.0.00.00.00.00.00', 'VENDA BRUTA DE PRODUTOS', 'Compreende as variações patrimoniais aumentativas auferidas com a venda bruta de produtos, que resultem em aumento do patrimônio liquido, independentemente de ingresso.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4189, 2, '4.3.2.1.1.00.00.00.00.00', 'VENDA BRUTA DE PRODUTOS - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais aumentativas auferidas com a venda bruta de produtos, que resultem em aumento do patrimônio liquido, independentemente de ingresso. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4190, 2, '4.3.3.0.0.00.00.00.00.00', 'EXPLORAÇÃO DE BENS E DIREITOS E PRESTAÇÃO DE SERVIÇOS', 'Compreende as variações patrimoniais aumentativas auferidas com a prestação de serviços, que resultem em aumento do patrimônio liquido, segregando-se a venda bruta das deduções como devoluções, abatimentos e descontos comerciais concedidos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4191, 2, '4.3.3.1.0.00.00.00.00.00', 'VALOR BRUTO DE EXPLORAÇÃO DE BENS E DIREITOS E PRESTAÇÃO DE SERVIÇOS', 'Compreende as variações patrimoniais aumentativas auferidas com a prestação de serviços, que resultem em aumento do patrimônio liquido, independentemente de ingresso.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4192, 2, '4.3.3.1.1.00.00.00.00.00', 'VALOR BRUTO DE EXPLORAÇÃO DE BENS, DIREITOS E PRESTAÇÃO DE SERVIÇOS - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais aumentativas auferidas com a prestação de serviços, que resultem em aumento do patrimônio liquido independentemente de ingresso. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4193, 2, '4.4.0.0.0.00.00.00.00.00', 'VARIAÇÕES PATRIMONIAIS AUMENTATIVAS FINANCEIRAS', 'Compreende o somatório das variações patrimoniais aumentativas com operações financeiras. Compreende: descontos obtidos, juros auferidos, prêmio de resgate de títulos e debêntures, entre outros.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4194, 2, '4.4.1.0.0.00.00.00.00.00', 'JUROS E ENCARGOS DE EMPRÉSTIMOS E FINANCIAMENTOS CONCEDIDOS', 'Compreende as variações patrimoniais aumentativas provenientes de juros e encargos de empréstimos e financiamentos concedidos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4195, 2, '4.4.1.1.0.00.00.00.00.00', 'JUROS E ENCARGOS DE EMPRÉSTIMOS INTERNOS CONCEDIDOS', 'Compreende as variações patrimoniais aumentativas relativas à aplicação das taxas de juros aplicadas a empréstimos internos concedidos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4196, 2, '4.4.1.1.1.00.00.00.00.00', 'JUROS E ENCARGOS DE EMPRÉSTIMOS INTERNOS CONCEDIDOS - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais aumentativas relativas à aplicação das taxas de juros aplicadas a empréstimos internos concedidos. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4438, 2, '8.1.1.1.0.00.00.00.00.00', 'EXECUÇÃO DE GARANTIAS E CONTRAGARANTIAS RECEBIDAS', 'Compreende as contas relacionadas ao registro da execução de avais, fianças e hipotecas recebidos no país e no exterior, bem como emolumentos consulares e outras garantias e contragarantias.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4197, 2, '4.4.1.1.3.00.00.00.00.00', 'JUROS E ENCARGOS DE EMPRÉSTIMOS INTERNOS CONCEDIDOS - INTER OFSS - UNIÃO', 'Compreende as variações patrimoniais aumentativas relativas à aplicação das taxas de juros aplicadas a empréstimos internos concedidos. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4198, 2, '4.4.1.1.4.00.00.00.00.00', 'JUROS E ENCARGOS DE EMPRÉSTIMOS INTERNOS CONCEDIDOS - INTER OFSS -ESTADO', 'Compreende as variações patrimoniais aumentativas relativas à aplicação das taxas de juros aplicadas a empréstimos internos concedidos. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4199, 2, '4.4.1.1.5.00.00.00.00.00', 'JUROS E ENCARGOS DE EMPRÉSTIMOS INTERNOS CONCEDIDOS - INTER OFSS - MUNICÍPIO', 'Compreende as variações patrimoniais aumentativas relativas à aplicação das taxas de juros aplicadas a empréstimos internos concedidos. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4200, 2, '4.4.1.2.0.00.00.00.00.00', 'JUROS E ENCARGOS DE EMPRÉSTIMOS EXTERNOS CONCEDIDOS', 'Compreende as variações patrimoniais aumentativas relativas à aplicação das taxas de juros aplicadas a empréstimos externos concedidos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4201, 2, '4.4.1.2.1.00.00.00.00.00', 'JUROS E ENCARGOS DE EMPRÉSTIMOS EXTERNOS CONCEDIDOS - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais aumentativas relativas à aplicação das taxas de juros aplicadas a empréstimos externos concedidos. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4202, 2, '4.4.1.3.0.00.00.00.00.00', 'JUROS E ENCARGOS DE FINANCIAMENTOS INTERNOS CONCEDIDOS', 'Compreende as variações patrimoniais aumentativas relativas a juros sobre os valores de financiamentos internos concedidos pela União, entidades e instituições, por autorizações legais ou vinculações a contratos e acordos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4203, 2, '4.4.1.3.1.00.00.00.00.00', 'JUROS E ENCARGOS DE FINANCIAMENTOS INTERNOS CONCEDIDOS - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais aumentativas relativas a juros sobre os valores de financiamentos internos concedidos pela União, entidades e instituições, por autorizações legais ou vinculações a contratos e acordos. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4204, 2, '4.4.1.3.3.00.00.00.00.00', 'JUROS E ENCARGOS DE FINANCIAMENTOS INTERNOS CONCEDIDOS - INTER OFSS - UNIÃO', 'Compreende as variações patrimoniais aumentativas relativas a juros sobre os valores de financiamentos internos concedidos pela União, entidades e instituições, por autorizações legais ou vinculações a contratos e acordos. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4205, 2, '4.4.1.3.4.00.00.00.00.00', 'JUROS E ENCARGOS DE FINANCIAMENTOS INTERNOS CONCEDIDOS - INTER OFSS - ESTADO', 'Compreende as variações patrimoniais aumentativas relativas a juros sobre os valores de financiamentos internos concedidos pela União, entidades e instituições, por autorizações legais ou vinculações a contratos e acordos. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4206, 2, '4.4.1.3.5.00.00.00.00.00', 'JUROS E ENCARGOS DE FINANCIAMENTOS INTERNOS CONCEDIDOS - INTER OFSS - MUNICÍPIO', 'Compreende as variações patrimoniais aumentativas relativas a juros sobre os valores de financiamentos internos concedidos pela União, entidades e instituições, por autorizações legais ou vinculações a contratos e acordos. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4207, 2, '4.4.1.4.0.00.00.00.00.00', 'JUROS E ENCARGOS DE FINANCIAMENTOS EXTERNOS CONCEDIDOS', 'Compreende as variações patrimoniais aumentativas relativas a juros sobre os valores de financiamentos externos concedidos pela União, entidades e instituições, por autorizações legais ou vinculações a contratos e acordos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4208, 2, '4.4.1.4.1.00.00.00.00.00', 'JUROS E ENCARGOS DE FINANCIAMENTOS EXTERNOS CONCEDIDOS - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais aumentativas relativas a juros sobre os valores de financiamentos externos concedidos pela União, entidades e instituições, por autorizações legais ou vinculações a contratos e acordos. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4209, 2, '4.4.2.0.0.00.00.00.00.00', 'JUROS E ENCARGOS DE MORA', 'Compreende as variações patrimoniais aumentativas com penalidades pecuniárias decorrentes da inobservância de normas e com rendimentos destinados a indenização pelo atraso no cumprimento da obrigação representando o resultado das aplicações impostas ao contribuinte.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4210, 2, '4.4.2.1.0.00.00.00.00.00', 'JUROS E ENCARGOS DE MORA SOBRE EMPRÉSTIMOS E FINANCIAMENTOS INTERNOS CONCEDIDOS', 'Compreende as variações patrimoniais aumentativas decorrentes de juros e multas com penalidades pecuniárias decorrentes da inobservância de normas e com rendimentos destinados a indenização pelo atraso no cumprimento da obrigação relativa a empréstimos e financiamentos internos concedidos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4211, 2, '4.4.2.1.1.00.00.00.00.00', 'JUROS E ENCARGOS DE MORA SOBRE EMPRÉSTIMOS E FINANCIAMENTOS INTERNOS CONCEDIDOS - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais aumentativas decorrentes de juros e multas com penalidades pecuniárias decorrentes da inobservância de normas e com rendimentos destinados a indenização pelo atraso no cumprimento da obrigação relativa a empréstimos e financiamentos internos concedidos. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4212, 2, '4.5.1.1.0.00.00.00.00.00', 'TRANSFERÊNCIAS RECEBIDAS PARA A EXECUÇÃO ORÇAMENTÁRIA', 'Compreende o valor das transferências financeiras recebidas e correspondência de créditos em virtude da execução orçamentária (cota, repasse e sub-repasse). Não Inclui o valor repassado para aportes no RPPS ou RGPS.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4464, 2, '8.1.2.1.1.01.00.00.00.00', 'EXECUÇÃO DE GARANTIAS CONCEDIDAS NO PAÍS', 'Compreende as contas relacionadas ao registro da execução de avais, fianças e hipotecas concedidos no país, bem como emolumentos consulares e outras garantias e contragarantias.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4213, 2, '4.4.2.1.3.00.00.00.00.00', 'JUROS E ENCARGOS DE MORA SOBRE EMPRÉSTIMOS E FINANCIAMENTOS INTERNOS CONCEDIDOS - INTER OFSS - UNIÃO', 'Compreende as variações patrimoniais aumentativas decorrentes de juros e multas com penalidades pecuniárias decorrentes da inobservância de normas e com rendimentos destinados a indenização pelo atraso no cumprimento da obrigação relativa a empréstimos e financiamentos internos concedidos. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4214, 2, '4.4.2.1.4.00.00.00.00.00', 'JUROS E ENCARGOS DE MORA SOBRE EMPRÉSTIMOS E FINANCIAMENTOS INTERNOS CONCEDIDOS - INTER OFSS - ESTADO', 'Compreende as variações patrimoniais aumentativas decorrentes de juros e multas com penalidades pecuniárias decorrentes da inobservância de normas e com rendimentos destinados a indenização pelo atraso no cumprimento da obrigação relativa a empréstimos e financiamentos internos concedidos. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4215, 2, '4.4.2.1.5.00.00.00.00.00', 'JUROS E ENCARGOS DE MORA SOBRE EMPRÉSTIMOS E FINANCIAMENTOS INTERNOS CONCEDIDOS - INTER OFSS - MUNICÍPIO', 'Compreende as variações patrimoniais aumentativas decorrentes de juros e multas com penalidades pecuniárias decorrentes da inobservância de normas e com rendimentos destinados a indenização pelo atraso no cumprimento da obrigação relativa a empréstimos e financiamentos internos concedidos. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4216, 2, '4.4.2.2.0.00.00.00.00.00', 'JUROS E ENCARGOS DE MORA SOBRE EMPRÉSTIMOS E FINANCIAMENTOS EXTERNOS CONCEDIDOS', 'Compreende as variações patrimoniais aumentativas decorrentes de juros e multas com penalidades pecuniárias decorrentes da inobservância de normas e com rendimentos destinados a indenização pelo atraso no cumprimento da obrigação relativa a empréstimos e financiamentos externos concedidos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4217, 2, '4.4.2.2.1.00.00.00.00.00', 'JUROS E ENCARGOS DE MORA SOBRE EMPRÉSTIMOS E FINANCIAMENTOS EXTERNOS CONCEDIDOS - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais aumentativas decorrentes de juros e multas com penalidades pecuniárias decorrentes da inobservância de normas e com rendimentos destinados a indenização pelo atraso no cumprimento da obrigação relativa a empréstimos e financiamentos externos concedidos. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4218, 2, '4.4.2.3.0.00.00.00.00.00', 'JUROS E ENCARGOS DE MORA SOBRE FORNECIMENTOS DE BENS E SERVIÇOS', 'Compreende as variações patrimoniais aumentativas decorrentes de juros e multas com penalidades pecuniárias decorrentes da inobservância de normas e com rendimentos destinados a indenização pelo atraso no cumprimento da obrigação relativa a fornecimento de bens e serviços.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4219, 2, '4.4.2.3.1.00.00.00.00.00', 'JUROS E ENCARGOS DE MORA SOBRE FORNECIMENTOS DE BENS E SERVIÇOS - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais aumentativas decorrentes de juros e multas com penalidades pecuniárias decorrentes da inobservância de normas e com rendimentos destinados a indenização pelo atraso no cumprimento da obrigação relativa a fornecimento de bens e serviços. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4220, 2, '4.4.2.4.0.00.00.00.00.00', 'JUROS E ENCARGOS DE MORA SOBRE CRÉDITOS TRIBUTÁRIOS', 'Compreende a variação patrimonial aumentativa com juros e encargos a titulo de penalidade aplicada em virtude de atrasos e não cumprimento dos prazos de créditos tributários.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4221, 2, '4.4.2.4.1.00.00.00.00.00', 'JUROS E ENCARGOS DE MORA SOBRE CRÉDITOS TRIBUTÁRIOS - CONSOLIDAÇÃO', 'Compreende a variação patrimonial aumentativa com juros e encargos a titulo de penalidade aplicada em virtude de atrasos e não cumprimento dos prazos de créditos tributários. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4222, 2, '4.4.2.9.0.00.00.00.00.00', 'OUTROS JUROS E ENCARGOS DE MORA', 'Compreende as outras variações patrimoniais aumentativas decorrentes de juros e multas com penalidades pecuniárias decorrentes da inobservância de normas e com rendimentos destinados a indenização pelo atraso no cumprimento da obrigação.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4223, 2, '4.4.2.9.1.00.00.00.00.00', 'OUTROS JUROS E ENCARGOS DE MORA - CONSOLIDAÇÃO', 'Compreende as outras variações patrimoniais aumentativas decorrentes de juros e multas com penalidades pecuniárias decorrentes da inobservância de normas e com rendimentos destinados a indenização pelo atraso no cumprimento da obrigação. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4224, 2, '4.4.3.0.0.00.00.00.00.00', 'VARIAÇÕES MONETÁRIAS E CAMBIAIS', 'Compreende a variação patrimonial aumentativa proveniente de variações da nossa própria moeda em relação aos índices ou coeficientes aplicáveis por dispositivo legal ou contratual e a variação do valor da nossa moeda em relação às moedas estrangeiras. Ressalte-se que será tratada como variação monetária apenas a correção monetária pós-fixada.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4225, 2, '4.4.3.1.0.00.00.00.00.00', 'VARIAÇÕES MONETÁRIAS E CAMBIAIS DE EMPRÉSTIMOS INTERNOS CONCEDIDOS', 'Compreende a variação patrimonial aumentativa proveniente de variações da nossa própria moeda em relação aos índices ou coeficientes aplicáveis por dispositivo legal ou contratual e a variação do valor da nossa moeda em relação às moedas estrangeiras referentes aos empréstimos internos concedidos. Ressalte-se que será tratada como variação monetária apenas a correção monetária pós-fixada', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4330, 2, '4.6.2.3.0.00.00.00.00.00', 'GANHOS COM ALIENAÇÃO DE INTANGÍVEIS', 'Compreende o ganho com alienação de ativos intangíveis, ou seja, quando o valor alienado do referido ativo e maior que o seu valor contábil, de maneira que a diferença compreende o ganho.', 2, false, 0, 'N');
