insert into contabilidade.planocontadetalhe values (4610, 2, '2.3.7.2.4.04.00.00.00.00', 'LUCROS A DESTINAR DO EXERCÍCIO', 'Registra o valor dos lucros do exercício pendentes de destinação, até a aprovação da proposta pela assembleia geral.', 3, true, 2, 'N');
