insert into contabilidade.planocontadetalhe values (4244, 2, '4.4.4.0.0.00.00.00.00.00', 'DESCONTOS FINANCEIROS OBTIDOS', 'Compreende a variação patrimonial aumentativa decorrente de descontos financeiros obtidos em virtude de liquidação antecipada de obrigações.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4245, 2, '4.4.4.0.1.00.00.00.00.00', 'DESCONTOS FINANCEIROS OBTIDOS - CONSOLIDAÇÃO', 'Compreende a variação patrimonial aumentativa decorrente de descontos financeiros obtidos em virtude de liquidação antecipada de obrigações. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4246, 2, '4.4.5.0.0.00.00.00.00.00', 'REMUNERAÇÃO DE DEPÓSITOS BANCÁRIOS E APLICAÇÕES FINANCEIRAS', 'Compreende o valor total das variações patrimoniais aumentativas decorrentes da remuneração do saldo diário dos depósitos da União existentes no banco central, bem como aplicação de recursos da conta única de acordo com a rentabilidade media intrínseca dos títulos do tesouro.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4247, 2, '4.4.5.1.0.00.00.00.00.00', 'REMUNERAÇÃO DE DEPÓSITOS BANCÁRIOS', 'Compreende a variação patrimonial aumentativa decorrente da remuneração dos depósitos bancários do ente existentes no agente financeiro.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4248, 2, '4.4.5.1.1.00.00.00.00.00', 'REMUNERAÇÃO DE DEPÓSITOS BANCÁRIOS - CONSOLIDAÇÃO', 'Compreende a variação patrimonial aumentativa decorrente da remuneração dos depósitos bancários do ente existentes no agente financeiro. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4249, 2, '6.2.2.1.3.00.00.00.00.00', 'CREDITO UTILIZADO', 'Compreende o somatório dos valores referentes aos créditos orçamentários empenhados.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4250, 2, '4.4.5.2.0.00.00.00.00.00', 'REMUNERAÇÃO DE APLICAÇÕES FINANCEIRAS', 'Compreende a variação patrimonial aumentativa proveniente da remuneração de depósitos bancários, recursos oriundos de aplicações de entidades da administração pública no mercado financeiro, autorizadas por lei, em caderneta de poupança, fundo de investimento, contas remuneradas e outros.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4251, 2, '4.4.5.2.1.00.00.00.00.00', 'REMUNERAÇÃO DE APLICAÇÕES FINANCEIRAS - CONSOLIDAÇÃO', 'Compreende a variação patrimonial aumentativa proveniente da remuneração de depósitos bancários, recursos oriundos de aplicações de entidades da administração pública no mercado financeiro, autorizadas por lei, em caderneta de poupança, fundo de investimento, contas remuneradas e outros. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4254, 2, '4.4.8.1.1.00.00.00.00.00', 'RESULTADO POSITIVO DO BANCO CENTRAL - CONSOLIDAÇÃO', 'Compreende a incorporação do resultado positivo do Banco Central do Brasil, conforme art. 7º da Lei Complementar 101, de 4/5/2000. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4255, 2, '4.4.9.0.0.00.00.00.00.00', 'OUTRAS VARIAÇÕES PATRIMONIAIS AUMENTATIVAS - FINANCEIRAS', 'Compreende as variações patrimoniais aumentativas provenientes de operações financeiras não compreendidas nos subgrupos anteriores.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4256, 2, '4.4.9.0.1.00.00.00.00.00', 'OUTRAS VARIAÇÕES PATRIMONIAIS AUMENTATIVAS - FINANCEIRAS - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais aumentativas provenientes de operações financeiras não compreendidas nos subgrupos anteriores. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4257, 2, '4.5.0.0.0.00.00.00.00.00', 'TRANSFERÊNCIAS E DELEGAÇÕES RECEBIDAS', 'Compreende o somatório das variações patrimoniais aumentativas com transferências inter governamentais, transferências intragovernamentais, transferências de instituições multigovernamentais, transferências de instituições privadas com ou sem fins lucrativos, transferências de convênios, transferências do exterior e execuções orçamentárias delegadas.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4258, 2, '4.5.1.0.0.00.00.00.00.00', 'TRANSFERÊNCIAS INTRAGOVERNAMENTAIS', 'Compreende as variações patrimoniais aumentativas decorrentes das transferências financeiras relativas à execução orçamentária, e de bens e valores, referentes às transações intragovernamentais.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4259, 2, '4.5.5.0.0.00.00.00.00.00', 'TRANSFERÊNCIAS DE CONSÓRCIOS PÚBLICOS', 'Compreende as variações patrimoniais aumentativas decorrentes das transferências de consórcios públicos, dos quais o ente recebedor participe.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4260, 2, '4.5.1.1.2.00.00.00.00.00', 'TRANSFERÊNCIAS RECEBIDAS PARA A EXECUÇÃO ORÇAMENTÁRIA - INTRA OFSS', 'Compreende o valor das transferências financeiras recebidas e correspondência de créditos em virtude da execução orçamentária (cota, repassse e sub-repasse). Não inclui o valor repassado para aportes no RPPS ou RGPS. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do ente.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4261, 2, '4.5.1.2.0.00.00.00.00.00', 'TRANSFERÊNCIAS RECEBIDAS INDEPENDENTES DE EXECUÇÃO ORÇAMENTÁRIA', 'Compreende o valor das transferências, de bens ou valores, financeiras recebidas para restos a pagar e outras finalidades independentes da execução orçamentária.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4262, 2, '4.5.1.2.2.00.00.00.00.00', 'TRANSFERÊNCIAS RECEBIDAS INDEPENDENTES DE EXECUÇÃO ORÇAMENTÁRIA - INTRA OFSS', 'Compreende o valor das transferências financeiras, de bens ou valores, recebidas para restos a pagar e outras finalidades independentes da execução orçamentária. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do ente.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4263, 2, '4.5.1.2.2.01.00.00.00.00', 'TRANSFERÊNCIAS FINANCEIRAS RECEBIDAS - INDEPENDENTES DE EXECUÇÃO ORÇAMENTÁRIA', 'Compreende o valor das transferências financeiras recebidas para restos a pagar e outras finalidades independentes da execução orçamentária.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4264, 2, '4.5.1.2.2.02.00.00.00.00', 'TRANSFERÊNCIAS NÃO FINANCEIRAS RECEBIDAS - INDEPENDENTES DE EXECUÇÃO ORÇAMENTÁRIA', 'Compreende o valor das transferências recebidas de bens ou valores independentes da execução orçamentária.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4265, 2, '4.5.1.3.0.00.00.00.00.00', 'TRANSFERENCIAS RECEBIDAS PARA APORTES DE RECURSOS PARA O RPPS', 'Compreende o valor das transferências para aportes financeiros do ente para cobertura de insuficiências financeiras, formação de reserva, e cobertura de déficits financeiros ou atuariais do RPPS e outros aportes, exceto os decorrentes de alíquota de contribuição suplementar.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4266, 2, '4.5.1.3.2.00.00.00.00.00', 'TRANSFERENCIAS RECEBIDAS PARA APORTES DE RECURSOS PARA O RPPS - INTRA OFSS', 'Compreende o valor das transferências para aportes financeiros do ente para cobertura de insuficiências financeiras, formação de reserva, e cobertura de déficits financeiros ou atuariais do RPPS e outros aportes exceto os decorrentes de alíquota de contribuição suplementar. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do ente.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4267, 2, '4.5.1.3.2.01.00.00.00.00', 'PLANO FINANCEIRO', 'Compreende o valor total dos valores recebidos pelo RPPS para cobertura de insuficiências financeiras, formação de reserva e outras necessidades financeiras, no âmbito do plano financeiro.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4268, 2, '4.5.1.3.2.02.00.00.00.00', 'PLANO PREVIDENCIÁRIO', 'Compreende o valor total recebido pelo RPPS para cobertura de déficit financeiro ou atuarial e outros aportes, no âmbito do plano previdenciário.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4269, 2, '4.5.1.4.0.00.00.00.00.00', 'TRANSFERÊNCIAS RECEBIDAS PARA APORTES DE RECURSOS PARA O RGPS', 'Compreende o valor das transferências recebidas para os aportes financeiros da União para a cobertura de déficits financeiros ou atuariais do RGPS.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4270, 2, '4.5.1.4.2.00.00.00.00.00', 'TRANSFERÊNCIAS RECEBIDAS PARA APORTES DE RECURSOS PARA O RGPS  - INTRA OFSS', 'Compreende o valor das transferências recebidas para os aportes financeiros da União para a cobertura de déficits financeiros ou atuariais do RGPS. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do ente.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4271, 2, '4.5.2.0.0.00.00.00.00.00', 'TRANSFERÊNCIAS INTER GOVERNAMENTAIS', 'Compreende as variações patrimoniais aumentativas decorrentes de transferências da União, estados, distrito federal, municípios, inclusive as entidades vinculadas, de bens e/ou valores.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4272, 2, '3.1.1.1.1.01.02.00.00.00', 'ADICIONAL NOTURNO', 'Registra o valor da despesa com adicional noturno.', 3, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (4273, 2, '4.5.2.1.0.00.00.00.00.00', 'TRANSFERÊNCIAS CONSTITUCIONAIS E LEGAIS DE RECEITAS', 'Compreende as variações patrimoniais aumentativas decorrentes da transferência de outras esferas de governo de receitas tributárias, de contribuições e de outras receitas vinculadas, prevista na Constituição ou em leis específicas, cuja competência de arrecadação é do órgão transferidor.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4289, 2, '4.5.2.4.4.00.00.00.00.00', 'OUTRAS TRANSFERÊNCIAS - INTER OFSS - ESTADO', 'Compreende as variações patrimoniais aumentativas decorrentes de demais transferências da união, estados, Distrito Federal, municípios, inclusive das entidades vinculadas, de bens e/ou valores. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4274, 2, '4.5.2.1.1.00.00.00.00.00', 'TRANSFERÊNCIAS CONSTITUCIONAIS E LEGAIS DE RECEITAS - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais aumentativas decorrentes da transferência de outras esferas de governo de receitas tributárias, de contribuições e de outras receitas vinculadas, prevista na Constituição ou em leis específicas, cuja competência de arrecadação é do órgão transferidor. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS). Por exemplo, empresa independente de um ente recebendo transferência de outro ente (a empresa independente não pertence ao OFSS mas pertence ao conceito de governamental).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4275, 2, '4.5.2.1.3.00.00.00.00.00', 'TRANSFERÊNCIAS CONSTITUCIONAIS E LEGAIS DE RECEITAS - INTER OFSS - UNIÃO', 'Compreende as variações patrimoniais aumentativas decorrentes da transferência de outras esferas de governo de receitas tributárias, de contribuições e de outras receitas vinculadas, prevista na Constituição ou em leis específicas, cuja competência de arrecadação é do órgão transferidor. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4276, 2, '4.5.2.1.4.00.00.00.00.00', 'TRANSFERÊNCIAS CONSTITUCIONAIS E LEGAIS DE RECEITAS - INTER OFSS - ESTADO', 'Compreendem as variações patrimoniais aumentativas decorrentes da transferência de outras esferas de governo de receitas tributárias, de contribuições e de outras receitas vinculadas, prevista na Constituição ou em leis específicas, cuja competência de arrecadação é do órgão transferidor. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4277, 2, '4.5.2.2.0.00.00.00.00.00', 'TRANSFERÊNCIAS DO FUNDEB', 'Compreende as variações patrimoniais aumentativas decorrentes da recursos recebidos do Fundo de Manutenção e Desenvolvimento da Educação Básica e de Valorização dos Profissionais da Educação, instituído pela E.C. n.º 53/2006 e regulamentado pela lei 11.494/2007.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4278, 2, '4.5.2.2.3.00.00.00.00.00', 'TRANSFERÊNCIAS DO FUNDEB - INTER OFSS - UNIÃO', 'Compreende as variações patrimoniais aumentativas decorrentes de recursos recebidos do Fundo de Manutenção e Desenvolvimento da Educação Básica e de Valorização dos Profissionais da Educação, instituído pela E.C. n.º 53/2006 e regulamentado pela lei 11.494/2007, decorrentes de complementação da União. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4279, 2, '4.5.2.2.4.00.00.00.00.00', 'TRANSFERÊNCIAS DO FUNDEB - INTER OFSS - ESTADO', 'Compreende as variações patrimoniais aumentativas decorrentes da recursos recebidos do Fundo de Manutenção e Desenvolvimento da Educação Básica e de Valorização dos Profissionais da Educação, instituído pela E.C. n.º 53/2006 e regulamentado pela lei 11.494/2007. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4280, 2, '4.5.2.3.0.00.00.00.00.00', 'TRANSFERÊNCIAS VOLUNTÁRIAS', 'Compreendem as variações patrimoniais aumentativas decorrentes de transferências voluntárias da União, estados, Distrito Federal, municípios, inclusive das entidades vinculadas, bem como as demais entidades, de bens e/ou valores.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4281, 2, '4.5.2.3.1.00.00.00.00.00', 'TRANSFERÊNCIAS VOLUNTÁRIAS - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais aumentativas decorrentes de transferências voluntárias da União, estados, Distrito Federal, municípios, inclusive das entidades vinculadas, bem como as demais entidades, de bens e/ou valores. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4282, 2, '4.5.2.3.3.00.00.00.00.00', 'TRANSFERÊNCIAS VOLUNTÁRIAS - INTER OFSS - UNIÃO', 'Compreendem as variações patrimoniais aumentativas decorrentes de transferências voluntárias da União, estados, Distrito Federal, municípios, inclusive das entidades vinculadas, bem como as demais entidades, de bens e/ou valores. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4283, 2, '4.5.2.3.4.00.00.00.00.00', 'TRANSFERÊNCIAS VOLUNTÁRIAS - INTER OFSS - ESTADO', 'Compreendem as variações patrimoniais aumentativas decorrentes de transferências voluntárias da União, estados, Distrito Federal, municípios, inclusive das entidades vinculadas, bem como as demais entidades, de bens e/ou valores. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4284, 2, '4.5.2.3.5.00.00.00.00.00', 'TRANSFERÊNCIAS VOLUNTÁRIAS - INTER OFSS - MUNICÍPIO', 'Compreendem as variações patrimoniais aumentativas decorrentes de transferências voluntárias da União, estados, Distrito Federal, municípios, inclusive das entidades vinculadas, bem como as demais entidades, de bens e/ou valores. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4285, 2, '4.5.2.4.0.00.00.00.00.00', 'OUTRAS TRANSFERÊNCIAS', 'Compreendem as variações patrimoniais aumentativas decorrentes de demais transferências da união, estados, Distrito Federal, municípios, inclusive as entidades vinculadas, de bens e/ou valores.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4286, 2, '4.5.2.4.1.00.00.00.00.00', 'OUTRAS TRANSFERÊNCIAS - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais aumentativas decorrentes de demais transferências da união, estados, Distrito Federal, municípios, inclusive das entidades vinculadas, de bens e/ou valores. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4287, 2, '4.5.2.4.3.00.00.00.00.00', 'OUTRAS TRANSFERÊNCIAS - INTER OFSS - UNIÃO', 'Compreende as variações patrimoniais aumentativas decorrentes de demais transferências da união, estados, Distrito Federal, municípios, inclusive das entidades vinculadas, de bens e/ou valores. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4288, 2, '6.2.0.0.0.00.00.00.00.00', 'EXECUÇÃO DO ORÇAMENTO', 'Compreende o somatório dos valores relativos à realização da receita, execução da despesa e suas alterações no orçamento geral da União durante o exercício financeiro.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4331, 2, '4.6.2.3.1.00.00.00.00.00', 'GANHOS COM ALIENAÇÃO DE INTANGÍVEIS - CONSOLIDAÇÃO', 'Compreende o ganho com alienação de ativos intangíveis, ou seja, quando o valor alienado do referido ativo e maior que o seu valor contábil, de maneira que a diferença compreende o ganho. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4290, 2, '4.5.2.4.5.00.00.00.00.00', 'OUTRAS TRANSFERÊNCIAS - INTER OFSS - MUNICÍPIO', 'Compreende as variações patrimoniais aumentativas decorrentes de demais transferências da união, estados, Distrito Federal, municípios, inclusive das entidades vinculadas, de bens e/ou valores. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4291, 2, '4.5.3.0.0.00.00.00.00.00', 'TRANSFERÊNCIAS DAS INSTITUIÇÕES PRIVADAS', 'Compreende as variações patrimoniais aumentativas decorrentes das transferências financeiras das instituições privadas, inclusive de bens e valores.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4292, 2, '4.5.3.1.0.00.00.00.00.00', 'TRANSFERÊNCIAS DAS INSTITUIÇÕES PRIVADAS SEM FINS LUCRATIVOS', 'Compreende as variações patrimoniais aumentativas decorrentes das transferências financeiras das instituições privadas sem fins lucrativos, inclusive de bens e valores. Exemplo: ONGs, OSCIPS e OS.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4293, 2, '4.5.3.1.1.00.00.00.00.00', 'TRANSFERÊNCIAS DAS INSTITUIÇÕES PRIVADAS SEM FINS LUCRATIVOS - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais aumentativas decorrentes das transferências financeiras das instituições privadas sem fins lucrativos, inclusive de bens e valores. Exemplo: ONGs, OSCIPS e OS. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4294, 2, '4.5.3.2.0.00.00.00.00.00', 'TRANSFERÊNCIAS DAS INSTITUIÇÕES PRIVADAS COM FINS LUCRATIVOS', 'Compreende as variações patrimoniais aumentativas decorrentes das transferências financeiras das instituições privadas com fins lucrativos, inclusive de bens e valores.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4295, 2, '4.5.3.2.1.00.00.00.00.00', 'TRANSFERÊNCIAS DAS INSTITUIÇÕES PRIVADAS COM FINS LUCRATIVOS - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais aumentativas decorrentes das transferências financeiras das instituições privadas com fins lucrativos, inclusive de bens e valores. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4296, 2, '4.5.4.0.0.00.00.00.00.00', 'TRANSFERÊNCIAS DAS INSTITUIÇÕES MULTIGOVERNAMENTAIS', 'Compreende as variações patrimoniais aumentativas decorrentes das transferências das instituições multigovernamentais, das quais o ente recebedor não participe.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4297, 2, '4.5.4.0.1.00.00.00.00.00', 'TRANSFERÊNCIAS DAS INSTITUIÇÕES MULTIGOVERNAMENTAIS - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais aumentativas decorrentes das transferências das instituições multigovernamentais, das quais o ente recebedor não participe. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4298, 2, '4.5.5.0.1.00.00.00.00.00', 'TRANSFERÊNCIAS DE CONSÓRCIOS PÚBLICOS - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais aumentativas decorrentes das transferências de consórcios públicos, dos quais o ente recebedor participe. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4299, 2, '4.5.6.0.0.00.00.00.00.00', 'TRANSFERÊNCIAS DO EXTERIOR', 'Compreende as variações patrimoniais aumentativas decorrentes de transferências de organismos e fundos internacionais, de governos estrangeiros e instituições privadas com ou sem fins lucrativos no exterior.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4300, 2, '4.5.6.0.1.00.00.00.00.00', 'TRANSFERÊNCIAS DO EXTERIOR - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais aumentativas decorrentes de transferências de organismos e fundos internacionais, de governos estrangeiros e instituições privadas com ou sem fins lucrativos no exterior. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4301, 2, '4.5.7.0.0.00.00.00.00.00', 'EXECUÇÃO ORÇAMENTÁRIA DELEGADA', 'Compreende as variações patrimoniais aumentativas decorrentes de transferência de recursos financeiros, decorrentes de delegação ou descentralização dos Entes (União, Estados, Distrito Federal ou Municípios) ou Consórcios Públicos para execução de ações de responsabilidade exclusiva do delegante.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4302, 2, '4.5.7.1.0.00.00.00.00.00', 'EXECUÇÃO ORÇAMENTÁRIA DELEGADA DE ENTES', 'Compreende as variações patrimoniais aumentativas decorrentes de transferência de recursos financeiros, decorrentes de delegação ou descentralização dos Entes (União, Estados, Distrito Federal ou Municípios) para execução de ações de responsabilidade exclusiva do delegante.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4303, 2, '4.5.7.1.3.00.00.00.00.00', 'EXECUÇÃO ORÇAMENTÁRIA DELEGADA DE ENTES - INTER OFSS - UNIÃO', 'Compreende as variações patrimoniais aumentativas decorrentes de transferência de recursos financeiros, decorrentes de delegação ou descentralização dos Entes (União, Estados, Distrito Federal ou Municípios) para execução de ações de responsabilidade exclusiva do delegante. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4304, 2, '4.5.7.1.4.00.00.00.00.00', 'EXECUÇÃO ORÇAMENTÁRIA DELEGADA DE ENTES - INTER OFSS - ESTADO', 'Compreende as variações patrimoniais aumentativas decorrentes de transferência de recursos financeiros, decorrentes de delegação ou descentralização dos Entes (União, Estados, Distrito Federal ou Municípios) para execução de ações de responsabilidade exclusiva do delegante. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4305, 2, '4.5.7.1.5.00.00.00.00.00', 'EXECUÇÃO ORÇAMENTÁRIA DELEGADA DE ENTES - INTER OFSS - MUNICÍPIO', 'Compreende as variações patrimoniais aumentativas decorrentes de transferência de recursos financeiros, decorrentes de delegação ou descentralização dos Entes (União, Estados, Distrito Federal ou Municípios) para execução de ações de responsabilidade exclusiva do delegante. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4492, 2, '8.2.1.1.4.00.00.00.00.00', 'DISPONIBILIDADE POR DESTINAÇÃO DE RECURSOS UTILIZADA', 'Compreende o valor dos recursos utilizados por meio de pagamento de despesa orçamentária, depósitos e/ou outros.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4306, 2, '4.5.7.2.0.00.00.00.00.00', 'EXECUÇÃO ORÇAMENTÁRIA DELEGADA DE CONSÓRCIOS', 'Compreende as variações patrimoniais aumentativas decorrentes de transferência de recursos financeiros, decorrentes de delegação ou descentralização de Consórcios Públicos para execução de ações de responsabilidade exclusiva do delegante.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4307, 2, '6.2.1.0.0.00.00.00.00.00', 'EXECUÇÃO DA RECEITA', 'Compreende o somatório dos valores relativos à realização da receita pública aprovada pela lei orçamentária anual e suas alterações.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4376, 2, '6.2.2.1.0.00.00.00.00.00', 'DISPONIBILIDADES DE CREDITO', 'Compreende o somatório da disponibilidade de credito orçamentário e suas alterações.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4308, 2, '4.5.7.2.1.00.00.00.00.00', 'EXECUÇÃO ORÇAMENTÁRIA DELEGADA DE CONSÓRCIOS - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais aumentativas decorrentes de transferência de recursos financeiros, decorrentes de delegação ou descentralização de Consórcios Públicos para execução de ações de responsabilidade exclusiva do delegante. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4309, 2, '4.5.8.0.0.00.00.00.00.00', 'TRANSFERÊNCIAS DE PESSOAS FÍSICAS', 'Compreende as variações patrimoniais aumentativas decorrentes de contribuições e doações a governos e entidades da administração descentralizada realizadas por pessoas físicas.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4310, 2, '4.5.8.0.1.00.00.00.00.00', 'TRANSFERÊNCIAS DE PESSOAS FÍSICAS - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais aumentativas decorrentes de contribuições e doações a governos e entidades da administração descentralizada realizadas por pessoas físicas. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4311, 2, '4.5.9.0.0.00.00.00.00.00', 'OUTRAS TRANSFERÊNCIAS E DELEGAÇÕES RECEBIDAS', 'Compreende as variações patrimoniais aumentativas decorrentes de demais transferências e delegações recebidas não compreendidas nas contas anteriores.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4312, 2, '4.5.9.0.1.00.00.00.00.00', 'OUTRAS TRANSFERÊNCIAS E DELEGAÇÕES RECEBIDAS - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais aumentativas decorrentes de demais transferências e delegações recebidas não compreendidas nas contas anteriores. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4313, 2, '4.6.0.0.0.00.00.00.00.00', 'VALORIZAÇÃO E GANHOS COM ATIVOS E DESINCORPORAÇÃO DE PASSIVOS', 'Compreende a variação patrimonial aumentativa com reavaliação e ganhos de ativos, bem como com a desincorporação de passivos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4314, 2, '4.6.1.0.0.00.00.00.00.00', 'REAVALIAÇÃO DE ATIVOS', 'Compreende a variação patrimonial aumentativa relativa à adoção do valor de mercado ou de consenso entre as partes para bens do ativo, quando esse for superior ao valor liquido contábil.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4315, 2, '4.6.1.1.0.00.00.00.00.00', 'REAVALIAÇÃO DE IMOBILIZADO', 'Compreende a variação patrimonial aumentativa relativa à adoção do valor de mercado ou de consenso entre as partes para bens do ativo imobilizado, quando esse for superior ao valor liquido contábil.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4316, 2, '4.6.1.1.1.00.00.00.00.00', 'REAVALIAÇÃO DE IMOBILIZADO - CONSOLIDAÇÃO', 'Compreende a variação patrimonial aumentativa relativa à adoção do valor de mercado ou de consenso entre as partes para bens do ativo imobilizado, quando esse for superior ao valor liquido contábil.Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4317, 2, '4.6.1.1.1.01.00.00.00.00', 'REAVALIAÇÃO DE BENS MÓVEIS', 'Compreende a variação patrimonial aumentativa relativa à adoção do valor de mercado ou de consenso entre as partes para bens móveis, quando esse for inferior ao valor liquido contábil.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4318, 2, '4.6.1.1.1.02.00.00.00.00', 'REAVALIAÇÃO DE BENS IMÓVEIS', 'Compreende a variação patrimonial aumentativa relativa à adoção do valor de mercado ou de consenso entre as partes para bens imóveis, quando esse for inferior ao valor liquido contábil.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4319, 2, '4.6.1.2.0.00.00.00.00.00', 'REAVALIAÇÃO DE INTANGÍVEIS', 'Compreende a variação patrimonial aumentativa relativa à adoção do valor de mercado ou de consenso entre as partes para ativos intangíveis, quando esse for superior ao valor liquido contábil.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4320, 2, '4.6.1.2.1.00.00.00.00.00', 'REAVALIAÇÃO DE INTANGÍVEIS - CONSOLIDAÇÃO', 'Compreende a variação patrimonial aumentativa relativa à adoção do valor de mercado ou de consenso entre as partes para ativos intangíveis, quando esse for superior ao valor liquido contábil. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4321, 2, '4.6.1.9.0.00.00.00.00.00', 'REAVALIAÇÃO DE OUTROS ATIVOS', 'Compreende a variação patrimonial aumentativa relativa à adoção do valor de mercado ou de consenso entre as partes para outros ativos, quando esse for superior ao valor liquido contábil.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4322, 2, '4.6.1.9.1.00.00.00.00.00', 'REAVALIAÇÃO DE OUTROS ATIVOS - CONSOLIDAÇÃO', 'Compreende a variação patrimonial aumentativa relativa à adoção do valor de mercado ou de consenso entre as partes para outros ativos, quando esse for superior ao valor liquido contábil. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4323, 2, '4.6.2.0.0.00.00.00.00.00', 'GANHOS COM ALIENAÇÃO', 'Compreende o ganho com alienação de ativos, ou seja, quando o valor alienado do ativo e maior que o seu valor contábil, de maneira que a diferença compreende o ganho.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4324, 2, '4.6.2.1.0.00.00.00.00.00', 'GANHOS COM ALIENAÇÃO DE INVESTIMENTOS', 'Compreende o ganho com alienação de investimentos, ou seja, quando o valor alienado do referido ativo e maior que o seu valor contábil, de maneira que a diferença compreende o ganho.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4325, 2, '4.6.2.1.1.00.00.00.00.00', 'GANHOS COM ALIENAÇÃO DE INVESTIMENTOS - CONSOLIDAÇÃO', 'Compreende o ganho com alienação de investimentos, ou seja, quando o valor alienado do referido ativo e maior que o seu valor contábil, de maneira que a diferença compreende o ganho. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4326, 2, '4.6.2.2.0.00.00.00.00.00', 'GANHOS COM ALIENAÇÃO DE IMOBILIZADO', 'Compreende o ganho com alienação de ativo imobilizado, ou seja, quando o valor alienado do referido ativo e maior que o seu valor contábil, de maneira que a diferença compreende o ganho.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4327, 2, '4.6.2.2.1.00.00.00.00.00', 'GANHOS COM ALIENAÇÃO DE IMOBILIZADO - CONSOLIDAÇÃO', 'Compreende o ganho com alienação de ativo imobilizado, ou seja, quando o valor alienado do referido ativo e maior que o seu valor contábil, de maneira que a diferença compreende o ganho. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4328, 2, '4.6.2.2.1.01.00.00.00.00', 'GANHO LÍQUIDO COM A ALIENAÇÃO DE BENS MÓVEIS', 'Compreende o ganho com alienação de ativo imobilizado, ou seja, quando o valor alienado do referido ativo e maior que o seu valor contábil, de maneira que a diferença compreende o ganho - Ganho Líquido com a Alienação de Bens Móveis.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4329, 2, '4.6.2.2.1.02.00.00.00.00', 'GANHO LÍQUIDO COM A ALIENAÇÃO DE BENS IMÓVEIS', 'Compreende o ganho com alienação de ativo imobilizado, ou seja, quando o valor alienado do referido ativo e maior que o seu valor contábil, de maneira que a diferença compreende o ganho - Ganho Líquido com a Alienação de Bens Imóveis.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4332, 2, '4.6.2.9.0.00.00.00.00.00', 'GANHOS COM ALIENAÇÃO DE DEMAIS ATIVOS', 'Compreende o ganho com alienação de demais ativos, não discriminados nas categorias anteriores, incluindo os investimentos do RPPS, quando o valor alienado do referido ativo seja maior que o seu valor contábil, de maneira que a diferença compreenda o ganho.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4333, 2, '4.6.2.9.1.00.00.00.00.00', 'GANHOS COM ALIENAÇÃO DE DEMAIS ATIVOS - CONSOLIDAÇÃO', 'Compreende o ganho com alienação de demais ativos, não discriminados nas categorias anteriores, incluindo os investimentos do RPPS, quando o valor alienado do referido ativo seja maior que o seu valor contábil, de maneira que a diferença compreenda o ganho. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4334, 2, '4.6.3.0.0.00.00.00.00.00', 'GANHOS COM INCORPORAÇÃO DE ATIVOS', 'Compreende a contrapartida da incorporação de novos ativos descobertos, a contrapartida da incorporação de ativos semoventes nascidos, por exemplo.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4335, 2, '4.6.3.1.0.00.00.00.00.00', 'GANHOS COM INCORPORAÇÃO DE ATIVOS POR DESCOBERTAS', 'Compreende os ganhos com a incorporação de novos ativos descobertos, como por exemplo, descoberta de jazidas de recursos naturais.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4336, 2, '4.6.3.1.1.00.00.00.00.00', 'GANHOS COM INCORPORAÇÃO DE ATIVOS POR DESCOBERTAS - CONSOLIDAÇÃO', 'Compreende os ganhos com a incorporação de novos ativos descobertos, como por exemplo, descoberta de jazidas de recursos naturais. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4337, 2, '4.6.3.2.0.00.00.00.00.00', 'GANHOS COM INCORPORAÇÃO DE ATIVOS POR NASCIMENTOS', 'Compreende os ganhos com a incorporação de semoventes nascidos, como por exemplo, nascimento de bovinos e aves.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4338, 2, '4.6.3.2.1.00.00.00.00.00', 'GANHOS COM INCORPORAÇÃO DE ATIVOS POR NASCIMENTOS - CONSOLIDAÇÃO', 'Compreende os ganhos com a incorporação de semoventes nascidos, como por exemplo, nascimento de bovinos e aves. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4339, 2, '4.6.3.3.0.00.00.00.00.00', 'GANHOS COM INCORPORAÇÃO DE ATIVOS APREENDIDOS', 'Compreende os ganhos  com a incorporação de ativos apreendidos, como por exemplo, os valores apreendidos associados ao trafico ilícito de entorpecentes e drogas afins.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4340, 2, '4.6.3.3.1.00.00.00.00.00', 'GANHOS COM INCORPORAÇÃO DE ATIVOS APREENDIDOS - CONSOLIDAÇÃO', 'Compreende os ganhos  com a incorporação de ativos apreendidos, como por exemplo, os valores apreendidos associados ao trafico ilícito de entorpecentes e drogas afins. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4341, 2, '4.6.3.4.1.00.00.00.00.00', ' GANHOS COM INCORPORAÇÃO DE ATIVOS POR PRODUÇÃO - CONSOLIDAÇÃO', 'Compreende a contrapartida da incorporação de novos ativos por produção como, por exemplo, produção agrícola e laticínia. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4342, 2, '4.6.3.9.0.00.00.00.00.00', 'OUTROS GANHOS COM INCORPORAÇÃO DE ATIVOS', 'Compreende a contrapartida da incorporação de outros novos ativos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4343, 2, '4.6.3.9.1.00.00.00.00.00', 'OUTROS GANHOS COM INCORPORAÇÃO DE ATIVOS - CONSOLIDAÇÃO', 'Compreende a contrapartida da incorporação de outros novos ativos. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4344, 2, '4.6.4.0.0.00.00.00.00.00', 'GANHOS COM DESINCORPORAÇÃO DE PASSIVOS', 'Compreende a contrapartida da desincorporação de passivos, inclusive as baixas de passivo decorrentes do cancelamento de restos a pagar.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4345, 2, '4.6.4.0.1.00.00.00.00.00', 'GANHOS COM DESINCORPORAÇÃO DE PASSIVOS - CONSOLIDAÇÃO', 'Compreende a contrapartida da desincorporação de passivos, inclusive as baixas de passivo decorrentes do cancelamento de restos a pagar. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4346, 2, '4.6.5.0.0.00.00.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL', 'Compreende a reversão de redução a valor recuperável previamente reconhecida como redutora do valor de ativos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4347, 2, '4.6.5.1.0.00.00.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL DE INVESTIMENTOS', 'Compreende a variação patrimonial aumentativa com a reversão de redução a valor recuperável de um investimento.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4348, 2, '4.6.5.1.1.00.00.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL DE INVESTIMENTOS - CONSOLIDAÇÃO', 'Compreende a variação patrimonial aumentativa com a reversão de redução a valor recuperável de um investimento. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4349, 2, '4.6.5.1.2.00.00.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL DE INVESTIMENTOS - INTRA OFSS', 'Compreende a variação patrimonial aumentativa com a reversão de redução a valor recuperável de um investimento. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do ente.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4350, 2, '4.6.5.1.3.00.00.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL DE INVESTIMENTOS - INTER OFSS - UNIÃO', 'Compreende a variação patrimonial aumentativa com a reversão de redução a valor recuperável de um investimento. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4351, 2, '4.6.5.2.1.02.00.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL DE BENS IMÓVEIS', 'Compreende a variação patrimonial aumentativa com a reversão de redução nos benefícios econômicos futuros ou no potencial de serviços de bens imóveis, que reflete um declínio na sua utilidade além do reconhecimento sistemático por meio da depreciação.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4352, 2, '4.6.5.1.4.00.00.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL DE INVESTIMENTOS - INTER OFSS - ESTADO', 'Compreende a variação patrimonial aumentativa com a reversão de redução a valor recuperável de um investimento.Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4353, 2, '6.2.2.0.0.00.00.00.00.00', 'EXECUÇÃO DA DESPESA', 'Compreende o somatório da disponibilidade de credito orçamentário e da execução da despesa em suas diversas etapas.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4413, 2, '6.0.0.0.0.00.00.00.00.00', 'CONTROLES DA EXECUÇÃO DO PLANEJAMENTO E ORÇAMENTO', 'Compreende as contas com função de registrar os atos e fatos ligados à execução orçamentária.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4354, 2, '4.6.5.1.5.00.00.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL DE INVESTIMENTOS - INTER OFSS - MUNICÍPIO', 'Compreende a variação patrimonial aumentativa com a reversão de redução a valor recuperável de um investimento.Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 2, false, 0, 'N');
