insert into contabilidade.planocontadetalhe values (4403, 2, '4.9.9.5.0.00.00.00.00.00', 'MULTAS ADMINISTRATIVAS', 'Compreende as variações patrimoniais aumentativas provenientes de penalidades pecuniárias decorrentes da inobservância de normas, e com rendimentos destinados a indenização pelo atraso no cumprimento da obrigação. Representa o resultado das aplicações impostas ao contribuinte faltoso, como sanção legal no campo tributário (impostos, taxas e contribuição de melhoria) e não-tributário (contribuições sociais e econômicas, patrimoniais, industriais, serviços e diversas) e de natureza administrativa, por infrações a regulamentos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4435, 2, '8.0.0.0.0.00.00.00.00.00', 'CONTROLES CREDORES', 'Compreende as contas em que são registradas a execução de atos potenciais e controles específicos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4436, 2, '8.1.0.0.0.00.00.00.00.00', 'EXECUÇÃO DOS ATOS POTENCIAIS', 'Compreende contas relacionadas à execução de situações não compreendidas no patrimônio, mas que, direta ou indiretamente, possam vir à afeta-lo, exclusive as que dizem respeito a atos e fatos ligados a execução orçamentária e financeira e as contas com função precípua de controle.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4404, 2, '4.9.9.5.1.00.00.00.00.00', 'MULTAS ADMINISTRATIVAS - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais aumentativas provenientes de penalidades pecuniárias decorrentes da inobservância de normas, e com rendimentos destinados a indenização pelo atraso no cumprimento da obrigação. Representa o resultado das aplicações impostas ao contribuinte faltoso, como sanção legal no campo tributário (impostos, taxas e contribuição de melhoria) e não-tributário (contribuições sociais e econômicas, patrimoniais, industriais, serviços e diversas) e de natureza administrativa, por infrações a regulamentos. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4405, 2, '4.9.9.6.0.00.00.00.00.00', 'INDENIZAÇÕES E RESTITUIÇÕES', 'Compreende as variações patrimoniais aumentativas provenientes de indenizações e/ou restituições diversas.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4406, 2, '4.9.9.6.1.00.00.00.00.00', 'INDENIZAÇÕES E RESTITUIÇÕES - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais aumentativas provenientes de indenizações e/ou restituições diversas. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4407, 2, '4.9.9.9.0.00.00.00.00.00', 'VARIAÇÕES PATRIMONIAIS AUMENTATIVAS DECORRENTES DE FATOS GERADORES DIVERSOS', 'Compreende as variações patrimoniais aumentativas decorrentes de fatos geradores diversos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4408, 2, '4.9.9.9.1.00.00.00.00.00', 'VARIAÇÕES PATRIMONIAIS AUMENTATIVAS DECORRENTES DE FATOS GERADORES DIVERSOS - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais aumentativas decorrentes de fatos geradores diversos.Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4409, 2, '5.2.1.1.2.00.00.00.00.00', '(-) PREVISÃO DE DEDUÇÕES DA RECEITA', 'Compreende a previsão de deduções da receita bruta aprovada na LOA.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4410, 2, '5.2.1.1.2.01.00.00.00.00', '(-) DEDUÇÕES POR TRANSFERÊNCIAS CONSTITUCIONAIS E LEGAIS', 'Compreende a previsão de dedução da receita aprovada na LOA por transferências constitucionais e legais.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4411, 2, '5.2.1.2.1.03.00.00.00.00', '(-) PREVISÃO DE DEDUÇÕES DA RECEITA  POR TRANSFERÊNCIAS CONSTITUCIONAIS E LEGAIS', 'Registra a previsão de dedução da receita para abertura de créditos adicionais por motivo de reestimativa ou correção da receita por transferências constitucionais e legais.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4412, 2, '8.3.1.2.0.00.00.00.00.00', 'CRÉDITOS ENCAMINHADOS PARA A DÍVIDA ATIVA', 'Compreende os valores encaminhados para o órgão competente em inscrever em dívida ativa.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4417, 2, '6.3.2.0.0.00.00.00.00.00', 'EXECUÇÃO DE RP PROCESSADOS', 'Compreende o somatório dos valores relativos à transferência, liquidação e pagamento das despesas empenhadas, liquidadas no exercício financeiro de sua inscrição e não pagas.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4418, 2, '6.2.2.2.1.00.00.00.00.00', 'DESCENTRALIZAÇÃO INTERNA DE CRÉDITOS - PROVISÃO', 'Compreende os valores dos créditos descentralizados das unidades orçamentárias para as unidades administrativas sob sua jurisdição ou entre estas, no âmbito do próprio ministério, secretaria ou órgão equivalente, concedidos ao longo do exercício.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4419, 2, '6.2.2.2.2.00.00.00.00.00', 'DESCENTRALIZAÇÃO EXTERNA DE CRÉDITOS - DESTAQUE', 'Compreende a descentralização do credito inicial ou adicional concedido de unidades ou órgãos pertencentes a ministérios, secretarias e órgãos equivalentes distintos ou entre estes e entidades da administração indireta.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4420, 2, '6.2.2.2.2.01.00.00.00.00', 'ADMINISTRAÇÃO DIRETA         ', 'Compreende o valor referente ao movimento de créditos decorrentes de concessão pela unidade orçamentária do órgão da administração direta transferidora.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4421, 2, '6.2.2.2.2.02.00.00.00.00', 'ADMINISTRAÇÃO INDIRETA                    ', 'Compreende o valor referente ao movimento de créditos decorrentes de concessão pela unidade orçamentária da entidade da administração indireta transferidora.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4422, 2, '6.2.2.2.9.00.00.00.00.00', 'OUTRAS DESCENTRALIZAÇÕES DE CRÉDITOS', 'Compreende as movimentações de créditos concedidos por cisão, fusão, extinção, compensação e outras transações.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4423, 2, '6.2.2.3.0.00.00.00.00.00', 'DETALHAMENTO DE CREDITO', 'Compreende o detalhamento das dotações orçamentárias relativas a cada programa de trabalho.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4424, 2, '6.2.2.9.0.00.00.00.00.00', 'OUTROS CONTROLES DA DESPESA ORÇAMENTÁRIA', 'Compreende o somatório dos valores executados das despesas pré-empenhadas e empenhadas por detalhamento específico.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4425, 2, '6.2.2.9.1.00.00.00.00.00', 'DESPESA PRE-EMPENHADA', 'Compreende o somatório dos valores executados das despesas pré-empenhadas pela própria unidade gestora, transferidos ou recebidos por transferência, por detalhamento especifico e suas respectivas anulações.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4426, 2, '6.2.2.9.2.00.00.00.00.00', 'EMISSÃO DE EMPENHO', 'Compreende o somatório dos valores executados das despesas empenhadas por detalhamento específico.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4427, 2, '6.2.2.9.2.01.00.00.00.00', 'EMPENHOS POR NOTA DE EMPENHO', 'Compreende o valor da emissão de documentos através dos quais são registrados os estágios das despesas orçamentárias realizadas pela administração pública.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4428, 2, '6.3.0.0.0.00.00.00.00.00', 'EXECUÇÃO DE RESTOS A PAGAR', 'Compreende o somatório dos valores relativos à transferência, liquidação e pagamento das despesas empenhadas e não pagas.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4429, 2, '6.3.1.0.0.00.00.00.00.00', 'EXECUÇÃO DE RP NÃO PROCESSADOS', 'Compreende o somatório dos valores relativos à transferência, liquidação e pagamento das despesas empenhadas, não liquidadas no exercício financeiro de sua inscrição e não pagas.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4430, 2, '6.3.1.7.0.00.00.00.00.00', 'RP NÃO PROCESSADOS - INSCRIÇÃO NO EXERCÍCIO', 'Compreende o valor das despesas empenhadas inscritas no exercício como restos a pagar não processados, a ser transferido no exercício seguinte para a conta 631100000 e 631200000.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4431, 2, '6.3.1.9.0.00.00.00.00.00', 'RP NÃO PROCESSADOS CANCELADOS', 'Compreende o cancelamento de restos a pagar não processados por insuficiência de recursos, pela inscrição indevida ou para atender dispositivo legal.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4432, 2, '6.3.2.9.0.00.00.00.00.00', 'RP PROCESSADOS CANCELADOS', 'Compreende o cancelamento de restos a pagar processados por insuficiência de recursos, pela inscrição indevida ou para atender dispositivo legal.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4433, 2, '8.3.1.2.1.00.00.00.00.00', 'CRÉDITOS ENCAMINHADOS PARA A DÍVIDA ATIVA TRIBUTÁRIA', 'Compreende os créditos referentes a tributos encaminhados para o órgão competente em inscrever em dívida ativa.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4439, 2, '8.1.1.1.1.00.00.00.00.00', 'EXECUÇÃO DE GARANTIAS E CONTRAGARANTIAS RECEBIDAS - CONSOLIDAÇÃO', 'Compreende as contas relacionadas ao registro da execução de avais, fianças e hipotecas recebidos no país e no exterior, bem como emolumentos consulares e outras garantias e contragarantias. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4440, 2, '8.1.1.1.1.01.00.00.00.00', 'EXECUÇÃO DE GARANTIAS RECEBIDAS NO PAÍS', 'Compreende as contas relacionadas ao registro da execução de avais, fianças e hipotecas recebidos no país, bem como emolumentos consulares e outras garantias e contragarantias.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4441, 2, '8.1.1.1.1.02.00.00.00.00', 'EXECUÇÃO DE GARANTIAS RECEBIDAS NO EXTERIOR', 'Compreende contas relacionadas ao registro da execução de avais, fianças e hipotecas recebidas no exterior, bem como emolumentos consulares e outras garantias e contragarantias.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4442, 2, '8.1.1.1.1.03.00.00.00.00', 'EXECUÇÃO DE CONTRAGARANTIAS RECEBIDAS NO PAÍS', 'COMPREENDE CONTAS RELACIONADAS AO REGISTRO DA EXECUÇÃO DE AVAIS, FIANÇAS E HIPOTECAS RECEBIDAS NO PAÍS BEM COMO OUTRAS CONTRAGARANTIAS.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4443, 2, '8.1.1.1.1.04.00.00.00.00', 'EXECUÇÃO DE CONTRAGARANTIAS RECEBIDAS NO EXTERIOR', 'Compreende contas relacionadas ao registro da execução de avais, fianças e hipotecas recebidas no exterior, bem como outras contragarantias.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4444, 2, '8.1.1.2.0.00.00.00.00.00', 'EXECUÇÃO DE DIREITOS CONVENIADOS E OUTROS INSTRUMENTOS CONGÊNERES', 'Compreende contas relacionadas ao registro, no convenente, da execução dos convênios firmados entre entidades, objetivando o cumprimento de finalidades comuns.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4445, 2, '8.1.1.2.1.00.00.00.00.00', 'EXECUÇÃO DE DIREITOS CONVENIADOS E OUTROS INSTRUMENTOS CONGÊNERES - CONSOLIDAÇÃO', 'COMPREENDE CONTAS RELACIONADAS AO REGISTRO, NO CONVENENTE, DA EXECUÇÃO DOS CONVÊNIOS E OUTROS INSTRUMENTOS CONGÊNERES FIRMADOS ENTRE ENTIDADES, OBJETIVANDO O CUMPRIMENTO DE FINALIDADES COMUNS. COMPREENDE OS SALDOS QUE NÃO SERÃO EXCLUÍDOS NOS DEMONSTRATIVOS CONSOLIDADOS DO ORÇAMENTO FISCAL E DA SEGURIDADE SOCIAL (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4446, 2, '8.1.1.2.1.01.00.00.00.00', 'EXECUÇÃO DE CONVÊNIOS', 'Compreende a execução dos valores de convênios para entrada de recursos firmado com outras entidades com a finalidade de atingir objetivos comuns.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4447, 2, '8.1.1.2.1.02.00.00.00.00', 'TERMO DE COOPERAÇÃO', 'Compreende a execução dos valores de termo de cooperação para entrada de recursos firmados com outras entidades com a finalidade de atingir objetivos comuns.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4448, 2, '8.1.1.2.1.99.00.00.00.00', 'OUTROS INSTRUMENTOS CONGÊNERES ', 'Compreende a execução dos valores de outros instrumentos congêneres para entrada de recursos firmados com outras entidades com a finalidade de atingir objetivos comuns.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4449, 2, '8.1.1.3.0.00.00.00.00.00', 'EXECUÇÃO DE DIREITOS CONTRATUAIS', 'Compreende contas relacionadas ao registro da execução dos valores de direitos contratuais, quando a administração pública participa como contratada.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4450, 2, '8.9.3.1.0.00.00.00.00.00', 'OPERAÇÕES CONTRATUAIS INTERNAS SUJEITAS AO LIMITE', 'Compreende o valor das operações de crédito contratuais internas.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4451, 2, '8.1.1.3.1.00.00.00.00.00', 'EXECUÇÃO DE DIREITOS CONTRATUAIS - CONSOLIDAÇÃO', 'Compreende contas relacionadas ao registro da execução dos valores de direitos contratuais, quando a administração pública participa como contratada. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4452, 2, '8.1.1.3.1.01.00.00.00.00', 'CONTRATOS DE SEGUROS', 'Compreende contas relacionas ao registro da execução dos valores do contrato de seguros em que a administração pública participa como contratada no instrumento contratual com terceiros.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4453, 2, '8.1.1.3.1.02.00.00.00.00', 'CONTRATOS DE SERVIÇOS', 'Compreende contas relacionadas ao registo da execução dos valores do contrato de serviços em que a administração pública seja a contratada no instrumento contratual com terceiros.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4454, 2, '8.1.1.3.1.03.00.00.00.00', 'CONTRATOS DE ALUGUÉIS', 'Compreende contas relacionadas ao registro da execução dos valores do contrato de aluguéis em que o poder público seja o locador do bem.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4455, 2, '8.1.1.3.1.04.00.00.00.00', 'CONTRATOS DE FORNECIMENTO DE BENS', 'Compreende contas relacionadas ao registro da execução dos valores do contrato de fornecimento de bens pela administração pública a terceiros.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4456, 2, '8.1.1.3.1.05.00.00.00.00', 'CONTRATOS DE EMPRÉSTIMOS E FINANCIAMENTOS', 'Compreende valores relacionados a execução de contratos de obrigações da entidade pública com terceiros referente a empréstimos e financiamentos contraídos no exercício.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4457, 2, '8.1.1.3.1.08.00.00.00.00', 'EXECUÇÃO DE CONTRATOS DE RATEIO DE CONSÓRCIOS PÚBLICOS', 'Compreende contas relacionadas ao registro dos valores de direitos contratuais decorrentes de Consórcios Públicos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4458, 2, '8.1.1.3.1.99.00.00.00.00', 'OUTROS DIREITOS CONTRATUAIS', 'Compreende a execução dos valores relativos a outros direitos contratuais.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4459, 2, '8.1.1.9.0.00.00.00.00.00', 'EXECUÇÃO DE OUTROS ATOS POTENCIAIS ATIVOS', 'Compreende a execução dos atos potenciais ativos não contemplados em contas especificas.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4460, 2, '8.1.1.9.1.00.00.00.00.00', 'EXECUÇÃO DE OUTROS ATOS POTENCIAIS ATIVOS - CONSOLIDAÇÃO', 'Compreende a execução dos atos potenciais ativos não contemplados em contas especificas. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4461, 2, '8.1.2.0.0.00.00.00.00.00', 'EXECUÇÃO DOS ATOS POTENCIAIS PASSIVOS', 'Compreende a execução dos atos e fatos que possa vir a afetar o passivo da entidade governamental.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4462, 2, '8.1.2.1.0.00.00.00.00.00', 'EXECUÇÃO DE GARANTIAS E CONTRAGARANTIAS CONCEDIDAS', 'Compreende contas relacionadas ao registro da execução de avais, fianças e hipotecas concedidas no país e no exterior, bem como emolumentos consulares e outras garantias e contragarantias.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4463, 2, '8.1.2.1.1.00.00.00.00.00', 'EXECUÇÃO DE GARANTIAS E CONTRAGARANTIAS CONCEDIDAS - CONSOLIDAÇÃO', 'Compreende as contas relacionadas ao registro da execução de avais, fianças e hipotecas concedidos no país e no exterior, bem como emolumentos consulares e outras garantias e contragarantias. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4466, 2, '8.1.2.1.1.03.00.00.00.00', 'EXECUÇÃO DE CONTRAGARANTIAS CONCEDIDAS NO PAÍS', 'Compreende as contas relacionadas ao registro da execução de avais, fianças e hipotecas concedidos no país, bem como outras contragarantias.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4467, 2, '8.1.2.1.1.04.00.00.00.00', 'EXECUÇÃO DE CONTRAGARANTIAS CONCEDIDAS NO EXTERIOR', 'Compreende as contas relacionadas ao registro da execução de avais, fianças e hipotecas concedidos no país, bem como outras contragarantias.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4468, 2, '8.1.2.2.0.00.00.00.00.00', 'EXECUÇÃO DE OBRIGAÇÕES CONVENIADAS E OUTROS INSTRUMENTOS CONGÊNERES', 'Compreende contas relacionadas ao registro, no concedente, da execução do valor dos convênios e outros instrumentos congêneres firmados entre entidades, objetivando o cumprimento de finalidades comuns.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4469, 2, '8.1.2.2.1.00.00.00.00.00', 'EXECUÇÃO DE OBRIGAÇÕES CONVENIADAS E OUTROS INSTRUMENTOS CONGÊNERES - CONSOLIDAÇÃO', 'Compreende contas relacionadas ao registro, no concedente, da execução dos convênios e outros instrumentos congêneres firmados entre entidades, objetivando o cumprimento de finalidades comuns. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4470, 2, '8.1.2.2.1.01.00.00.00.00', 'EXECUÇÃO DE CONVÊNIOS', 'Compreende a execução dos valores de convênios para saída de recursos firmado com outras entidades com a finalidade de atingir objetivos comuns.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4471, 2, '8.1.2.2.1.02.00.00.00.00', 'TERMO DE COOPERAÇÃO', 'Compreende a execução dos valores de termo de cooperação para saída de recursos firmados com outras entidades com a finalidade de atingir objetivos comuns.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4472, 2, '8.1.2.2.1.99.00.00.00.00', 'OUTROS INSTRUMENTOS CONGÊNERES', 'Compreende a execução dos valores de outros instrumentos congêneres para saída de recursos firmados com outras entidades com a finalidade de atingir objetivos comuns.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4473, 2, '8.1.2.3.0.00.00.00.00.00', 'EXECUÇÃO DE OBRIGAÇÕES CONTRATUAIS', 'Compreende contas relacionadas ao registro da execução dos valores de obrigações contratuais, quando a administração pública participa como contratante.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4474, 2, '8.1.2.3.1.00.00.00.00.00', 'EXECUÇÃO DE OBRIGAÇÕES - CONSOLIDAÇÃO', 'Compreende contas relacionadas ao registro da execução dos valores de obrigações contratuais, quando a administração pública participa como contratante. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4475, 2, '8.1.2.3.1.01.00.00.00.00', 'CONTRATOS DE SEGUROS', 'Compreende contas relacionadas ao registro da execução dos valores do contrato de seguros em que a administração pública seja a contratante do instrumento contratual com terceiros.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4476, 2, '8.1.2.3.1.02.00.00.00.00', 'CONTRATOS DE SERVIÇOS', 'Compreende contas relacionadas ao registro da execução dos valores do contrato de serviços em que a administração pública seja a contratante.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4477, 2, '8.1.2.3.1.03.00.00.00.00', 'CONTRATOS DE ALUGUÉIS', 'Compreende contas relacionadas ao registro da execução dos valores do contrato de alugueis em que o poder público seja o locatário do bem.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4478, 2, '8.1.2.3.1.04.00.00.00.00', 'CONTRATOS DE FORNECIMENTO DE BENS', 'Compreende contas relacionadas ao registro da execução dos valores do contrato de fornecimento de bens pela administração pública a terceiros.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4479, 2, '8.1.2.3.1.05.00.00.00.00', 'CONTRATOS DE EMPRÉSTIMOS E FINANCIAMENTOS', 'Compreende valores relacionados a execução de contratos de obrigações da entidade pública com terceiros referente a empréstimos e financiamentos concedidos no exercício.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4480, 2, '8.1.2.3.1.06.00.00.00.00', 'CONTRATO DE GESTÃO', 'Compreende as contas de registro da execução dos contratos de gestão.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4481, 2, '8.1.2.3.1.07.00.00.00.00', 'TERMO DE PARCERIA', 'Compreende valores relacionados à execução de contratos de obrigações da entidade pública com terceiros referente a termo de parceria.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4482, 2, '8.1.2.3.1.08.00.00.00.00', 'CONTRATOS DE PPP', 'Compreende o valor dos passivos decorrentes de contrato de PPP, incluindo o valor das obrigações contratuais com as contraprestações futuras, assim como os riscos não provisionados e outros passivos contingentes.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4483, 2, '8.1.2.3.1.09.00.00.00.00', 'EXECUÇÃO DE CONTRATOS DE RATEIO DE CONSÓRCIOS PÚBLICOS', 'Compreende contas relacionadas ao registro dos valores de obrigações contratuais decorrentes de Consórcios Públicos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4484, 2, '8.1.2.3.1.10.00.00.00.00', 'CONTRATOS DE PPP - DO ENTE FEDERADO, EXCETO ESTATAIS NÃO DEPENDENTES', 'Compreende a previsão de valor, por contrato, das despesas derivadas de PPP contratadas pelo ente da Federação excluídas as empresas estatais não dependentes. Deve abranger todas as despesas, correntes e de capital, devidadas do conjunto das parcerias contratadas, bem como as previsões de despesas de PPP para os próximos 9 anos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4485, 2, '8.1.2.3.1.11.00.00.00.00', 'CONTRATOS DE PPP - DAS ESTATAIS NÃO DEPENDENTES', 'Compreende o valor por contrato das despesas derivadas de PPP contratadas pelas empresas estatais não dependentes. Deve abranger todas as despesas, correntes e de capital, derivadas do conhunto das parcerias contratadas, bem como as previsões de despesas de PPP para os próximos 9 anos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4486, 2, '8.1.2.3.1.99.00.00.00.00', 'OUTRAS OBRIGAÇÕES CONTRATUAIS', 'Compreende a execução dos valores relativos a outras obrigações contratuais.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4487, 2, '8.1.2.9.0.00.00.00.00.00', 'EXECUÇÃO DE OUTROS ATOS POTENCIAIS PASSIVOS', 'Compreende a execução dos atos potenciais passivos não contemplados em contas especificas.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4488, 2, '8.1.2.9.1.00.00.00.00.00', 'EXECUÇÃO DE OUTROS ATOS POTENCIAIS PASSIVOS - CONSOLIDAÇÃO', 'Compreende a execução dos atos potenciais passivos não contemplados em contas especificas. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4489, 2, '8.2.0.0.0.00.00.00.00.00', 'EXECUÇÃO DA ADMINISTRAÇÃO FINANCEIRA', 'Compreende as contas de registro da execução da programação financeira e de controle das disponibilidades.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4490, 2, '8.2.1.1.2.00.00.00.00.00', 'DISPONIBILIDADE POR DESTINAÇÃO DE RECURSOS COMPROMETIDA POR EMPENHO', 'Compreende o valor das disponibilidades de recursos comprometidas por ocasião do empenho e não liquidadas.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4491, 2, '8.2.1.1.3.00.00.00.00.00', 'DISPONIBILIDADE POR DESTINAÇÃO DE RECURSOS COMPROMETIDA POR LIQUIDAÇÃO E ENTRADAS COMPENSATÓRIAS', 'Compreende o valor das disponibilidades de recursos comprometidas por ocasião da liquidação e de entradas compensatórias e não pagas/devolvidas.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4493, 2, '8.2.1.1.5.00.00.00.00.00', 'DISPONIBILIDADE POR DESTINAÇÃO DE RECURSOS COMPROMETIDA POR PROGRAMAÇÃO FINANCEIRA OU ARRECADAÇÃO PRÓPRIA', 'Compreende o valor das disponibilidades de recursos comprometidas por programação financeira no órgão central de programação financeira ou arrecadação própria.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4494, 2, '8.2.1.2.0.00.00.00.00.00', 'EXECUÇÃO FINANCEIRA DO LIMITE DE RESTOS A PAGAR', 'Compreende as contas que registram a execução financeira do limite de restos a pagar.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4495, 2, '8.2.1.3.0.00.00.00.00.00', 'EXECUÇÃO DO RECURSO DIFERIDO POR DESTINAÇÃO', 'Compreende as contas que controlam a execução dos recursos diferidos. Recursos diferidos são as sobras de recursos financeiros ao final do exercício (recurso diferido), que deveriam ser devolvidas a conta única, porem, ao invés disso, essas sobras são liberadas para uso (apenas no exercício seguinte) através de descontos das transferências financeiras (cota, repasse e sub-repasse) do exercício seguinte.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4496, 2, '8.2.2.0.0.00.00.00.00.00', 'EXECUÇÃO DA PROGRAMAÇÃO FINANCEIRA', 'Compreende as contas que registram a execução das cotas, repasses e sub-repasses para atender a despesas orçamentárias, restos a pagar autorizados e demais dispêndios extra orçamentários.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4611, 2, '2.3.7.2.4.05.00.00.00.00', 'LUCROS A DESTINAR DE EXERCÍCIOS ANTERIORES', 'Registra o valor dos lucros de exercícios anteriores pendentes de destinação, até a aprovação da proposta pela assembleia geral.', 3, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (4497, 2, '8.2.3.0.0.00.00.00.00.00', 'EXECUÇÃO DO LIMITE ORÇAMENTÁRIO', 'Compreende as contas que controlam a execução do limite de empenho e movimentação de créditos orçamentários, conforme estabelecidos em ato próprio dos poderes e ministério público.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4498, 2, '8.2.4.0.0.00.00.00.00.00', 'CONTROLES DA ARRECADAÇÃO', 'Compreende as contas que registram os valores discriminados da arrecadação da receita orçamentária, por meio de documentos de arrecadação como DARF, GRU, DAR, entre outros.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4499, 2, '8.3.0.0.0.00.00.00.00.00', 'EXECUÇÃO DA DÍVIDA ATIVA', 'Compreende as contas que controlam a execução dos créditos passiveis de serem encaminhados e inscritos em dívida ativa.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4500, 2, '8.3.1.0.0.00.00.00.00.00', 'EXECUÇÃO DO ENCAMINHAMENTO DE CRÉDITOS PARA INSCRIÇÃO EM DÍVIDA ATIVA', 'Compreende as contas que registram os valores a serem encaminhados e os já encaminhados para o órgão competente em inscrever em dívida ativa.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4501, 2, '8.3.1.1.0.00.00.00.00.00', 'CRÉDITOS A ENCAMINHAR PARA A DÍVIDA ATIVA', 'Compreende os valores a serem encaminhados para o órgão competente em inscrever em dívida ativa.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4502, 2, '8.3.1.1.1.00.00.00.00.00', 'CRÉDITOS A ENCAMINHAR PARA A DÍVIDA ATIVA TRIBUTÁRIA', 'Compreende os créditos a serem encaminhados para o órgão competente em inscrever em dívida ativa tributária.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4503, 2, '8.3.1.1.1.01.00.00.00.00', 'CRÉDITOS A ENCAMINHAR PARA A DÍVIDA ATIVA TRIBUTÁRIA - IMPOSTOS', 'Compreende os créditos a serem encaminhados para o órgão competente em inscrever em dívida ativa, referentes a impostos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4504, 2, '8.3.1.1.2.00.00.00.00.00', 'CRÉDITOS A ENCAMINHAR PARA A DÍVIDA ATIVA NÃO-TRIBUTÁRIA', 'Compreende os créditos a serem encaminhados para o órgão competente em inscrever em dívida ativa, referentes a créditos não-tributários.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4505, 2, '8.3.1.2.2.00.00.00.00.00', 'CRÉDITOS ENCAMINHADOS PARA A DÍVIDA ATIVA NÃO TRIBUTÁRIA', 'Compreende os créditos de natureza não-tributária encaminhados para o órgão competente em inscrever em dívida ativa.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4506, 2, '8.3.1.3.0.00.00.00.00.00', 'CANCELAMENTO DE CRÉDITOS ENCAMINHADOS PARA A DÍVIDA ATIVA', 'Compreende o cancelamento dos valores indevidamente encaminhados para o órgão competente em inscrever em dívida ativa.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4507, 2, '8.3.1.4.0.00.00.00.00.00', 'CRÉDITOS INSCRITOS EM DÍVIDA ATIVA', 'Compreende os valores encaminhados para o órgão competente em inscrever em dívida ativa que foram efetivamente inscritos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4508, 2, '8.3.2.0.0.00.00.00.00.00', 'EXECUÇÃO DA INSCRIÇÃO DE CRÉDITOS EM DÍVIDA ATIVA', 'Compreende as contas que registram os valores a serem inscritos em dívida ativa pelo o órgão competente em inscrever em dívida ativa.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4509, 2, '8.3.2.1.0.00.00.00.00.00', 'CRÉDITOS A INSCREVER EM DÍVIDA ATIVA', 'Compreende os valores a serem inscritos em dívida ativa pelo o órgão competente em inscrever em dívida ativa.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4510, 2, '8.3.2.1.1.00.00.00.00.00', 'CRÉDITOS A INSCREVER EM DÍVIDA ATIVA TRIBUTÁRIA ', 'Compreende os créditos a serem inscritos em dívida ativa tributária pelo órgão competente em inscrever em dívida ativa.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4511, 2, '8.3.2.1.1.01.00.00.00.00', 'CRÉDITOS A INSCREVER EM DIVIDA ATIVA - TRIBUTÁRIA - IMPOSTOS', 'Compreende os créditos a serem inscritos em divida ativa tributária de impostos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4512, 2, '8.3.2.2.0.00.00.00.00.00', 'CRÉDITOS A INSCREVER EM DÍVIDA ATIVA DEVOLVIDOS', 'Compreende os valores a serem inscritos em dívida ativa que foram devolvidos pelo órgão competente, por incorreções na formalização do processo de encaminhamento.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4513, 2, '8.3.2.3.0.00.00.00.00.00', 'CRÉDITOS INSCRITOS EM DÍVIDA ATIVA A RECEBER', 'Compreende os valores inscritos em dívida ativa pelo o órgão competente em inscrever em dívida ativa.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4514, 2, '8.3.2.3.1.00.00.00.00.00', 'CRÉDITOS INSCRITOS EM DÍVIDA ATIVA TRIBUTÁRIA A RECEBER', 'Compreende os créditos inscritos em dívida ativa tributária pelo órgão competente em inscrever em dívida ativa.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4515, 2, '8.3.2.3.1.01.00.00.00.00', 'CRÉDITOS INSCRITOS EM DÍVIDA ATIVA TRIBUTÁRIA A RECEBER EM COBRANÇA ADMINISTRATIVA', 'Compreende os créditos a receber, inscritos em dívida ativa tributária pelo órgão competente em inscrever em dívida ativa, em fase administrativa de cobrança.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4516, 2, '8.3.2.3.1.01.01.00.00.00', 'CRÉDITOS INSCRITOS EM DÍVIDA ATIVA TRIBUTÁRIA DE IMPOSTOS A RECEBER EM COBRANÇA ADMINISTRATIVA', 'Compreende  os créditos a receber, inscritos em divida ativa tributária pelo órgão competente em inscrever em divida ativa, em fase administrativa de cobrança.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4517, 2, '8.3.2.3.1.02.00.00.00.00', 'CRÉDITOS INSCRITOS EM DÍVIDA ATIVA TRIBUTÁRIA A RECEBER EM COBRANÇA JUDICIAL', 'Compreende  os créditos a receber, inscritos em dívida ativa tributária pelo órgão competente em inscrever em dívida ativa, em fase judicial de cobrança.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4518, 2, '8.3.2.3.1.02.01.00.00.00', 'CRÉDITOS INSCRITOS EM DÍVIDA ATIVA TRIBUTÁRIA DE IMPOSTOS A RECEBER EM COBRANÇA JUDICIAL', 'Compreende  os créditos a receber, inscritos em divida ativa tributária pelo órgão competente em inscrever em divida ativa, em fase judicial de cobrança.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4519, 2, '8.3.2.3.1.02.02.00.00.00', 'CRÉDITOS INSCRITOS EM DÍVIDA ATIVA TRIBUTÁRIA DE TAXAS A RECEBER EM COBRANÇA JUDICIAL - TAXAS', 'Compreende os créditos a receber, inscritos em divida ativa tributária pelo órgão competente em inscrever em divida ativa, em fase judicial de cobrança - taxas.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4520, 2, '8.3.2.3.2.00.00.00.00.00', 'CRÉDITOS INSCRITOS EM DÍVIDA ATIVA NÃO-TRIBUTÁRIA A RECEBER', 'Compreende os créditos a receber, inscritos em dívida ativa não-tributária pelo órgão competente em inscrever em dívida ativa, em fase administrativa de cobrança.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4521, 2, '8.3.2.4.0.00.00.00.00.00', 'CRÉDITOS INSCRITOS EM DÍVIDA ATIVA RECEBIDOS', 'Compreende os valores recebidos relativos aos créditos anteriormente inscritos em dívida ativa.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4522, 2, '8.3.2.4.1.00.00.00.00.00', 'RECEBIMENTO DE CRÉDITOS INSCRITOS EM DÍVIDA ATIVA TRIBUTÁRIA', 'Compreende o recebimento dos valores referentes aos créditos inscritos em dívida ativa tributária.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4523, 2, '8.3.2.4.1.01.00.00.00.00', 'RECEBIMENTO DE CRÉDITOS INSCRITOS EM DÍVIDA ATIVA TRIBUTÁRIA EM COBRANÇA ADMINISTRATIVA', 'Compreende o recebimento dos valores referentes aos créditos inscritos em dívida ativa tributária, em fase administrativa de cobrança.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4524, 2, '8.3.2.4.1.01.01.00.00.00', 'RECEBIMENTO DE CRÉDITOS INSCRITOS EM DÍVIDA ATIVA TRIBUTÁRIA DE IMPOSTOS EM COBRANÇA ADMINISTRATIVA', 'Compreende o recebimento dos valores referentes aos créditos inscritos em divida ativa tributária de impostos, em fase administrativa de cobrança.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4612, 2, '2.3.7.2.4.06.00.00.00.00', 'RESULTADOS APURADOS POR EXTINÇÃO, FUSÃO E CISÃO', 'Registra o resultado apurado por extinção, cisão ou fusão de empresas durante o exercício.', 3, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (4525, 2, '8.3.2.4.1.02.00.00.00.00', 'RECEBIMENTO DE CRÉDITOS INSCRITOS EM DÍVIDA ATIVA TRIBUTÁRIA EM COBRANÇA JUDICIAL', 'Compreende o recebimento dos valores referentes aos créditos inscritos em dívida ativa tributária, em fase judicial de cobrança.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4526, 2, '8.3.2.4.1.02.01.00.00.00', 'RECEBIMENTO DE CRÉDITOS INSCRITOS EM DÍVIDA ATIVA TRIBUTÁRIA DE IMPOSTOS EM COBRANÇA JUDICIAL', 'Compreende o recebimento dos valores referentes aos créditos inscritos em divida ativa tributária de impostos, em fase judicial de cobrança.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4527, 2, '8.3.2.4.2.00.00.00.00.00', 'RECEBIMENTOS DE CRÉDITOS INSCRITOS EM DÍVIDA ATIVA NÃO-TRIBUTÁRIA', 'Compreende o recebimento dos valores referentes aos créditos inscritos em dívida ativa não-tributária.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4528, 2, '8.3.2.5.0.00.00.00.00.00', 'BAIXA DE CRÉDITOS INSCRITOS EM DÍVIDA ATIVA', 'Compreende os valores relativos às baixas de créditos inscritos em dívida ativa.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4529, 2, '8.3.2.5.1.00.00.00.00.00', 'BAIXAS DE CRÉDITOS INSCRITOS EM DÍVIDA ATIVA TRIBUTÁRIA', 'Compreende as baixas de créditos inscritos em dívida ativa tributária.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4530, 2, '8.3.2.5.1.01.00.00.00.00', 'BAIXAS DE CRÉDITOS INSCRITOS EM DÍVIDA ATIVA TRIBUTÁRIA - COBRANÇA ADMINISTRATIVA', 'Compreende as baixas de créditos inscritos em dívida ativa tributária, em cobrança administrativa.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4531, 2, '8.3.2.5.1.01.01.00.00.00', 'BAIXAS DE CRÉDITOS INSCRITOS EM DÍVIDA ATIVA TRIBUTÁRIA  DE IMPOSTOS- COBRANÇA ADMINISTRATIVA', 'Compreende as baixas de créditos inscritos em divida ativa tributária de impostos, em cobrança administrativa.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4532, 2, '8.3.2.5.1.02.00.00.00.00', 'BAIXAS DE CRÉDITOS INSCRITOS EM DÍVIDA ATIVA TRIBUTÁRIA - COBRANÇA JUDICIAL', 'Compreende as baixas de créditos inscritos em dívida ativa tributária, em cobrança judicial.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4533, 2, '8.3.2.5.1.02.01.00.00.00', 'BAIXAS DE CRÉDITOS INSCRITOS EM DÍVIDA ATIVA TRIBUTÁRIA  DE IMPOSTOS- COBRANÇA JUDICIAL', 'Compreende as baixas de créditos inscritos em divida ativa tributária de impostos, em cobrança judicial.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4534, 2, '8.3.2.5.2.00.00.00.00.00', 'BAIXAS DE CRÉDITOS INSCRITOS EM DÍVIDA ATIVA NÃO-TRIBUTÁRIA', 'Compreende as baixas de créditos inscritos em dívida ativa não-tributária.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4535, 2, '8.9.3.2.0.00.00.00.00.00', 'OPERAÇÕES CONTRATUAIS EXTERNAS SUJEITAS AO LIMITE', 'Compreende o valor das operações de crédito contratuais externas.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4536, 2, '8.4.0.0.0.00.00.00.00.00', 'EXECUÇÃO DOS RISCOS FISCAIS', 'Compreende as contas que controlam a execução dos riscos fiscais que não preencham os requisitos para reconhecimento como passivo, conforme identificados no anexo de riscos fiscais da lei de diretrizes orçamentárias.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4537, 2, '8.4.1.0.0.00.00.00.00.00', 'EXECUÇÃO DE PASSIVOS CONTINGENTES', 'Compreende as contas que controlam a execução dos riscos fiscais que não preencham os requisitos para reconhecimento como passivo, classificados como passivos contingentes, conforme identificados no anexo de riscos fiscais da lei de diretrizes orçamentárias.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4538, 2, '8.4.1.1.0.00.00.00.00.00', 'PASSIVOS CONTINGENTES PREVISTOS', 'Compreende a previsão dos riscos fiscais classificados como Passivos Contingentes.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4539, 2, '8.4.1.2.0.00.00.00.00.00', 'PASSIVOS CONTINGENTES CONFIRMADOS', 'Compreende a confirmação da previsão dos riscos fiscais classificados como Passivos Contingentes.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4540, 2, '8.4.2.0.0.00.00.00.00.00', 'EXECUÇÃO DOS DEMAIS RISCOS FISCAIS', 'Compreende as contas que controlam a execução dos riscos fiscais que não preencham os requisitos para reconhecimento como passivo, não classificados como passivos contingentes, conforme identificados no anexo de riscos fiscais da lei de diretrizes orçamentárias.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4541, 2, '8.4.2.1.0.00.00.00.00.00', 'DEMAIS RISCOS FISCAIS PREVISTOS ', 'Compreende a previsão dos riscos fiscais não classificados como passivos contingentes.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4542, 2, '8.4.2.2.0.00.00.00.00.00', 'DEMAIS RISCOS FISCAIS CONFIRMADOS', 'Compreende a confirmação da previsão dos riscos fiscais não classificados como passivos contingentes.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4543, 2, '8.5.0.0.0.00.00.00.00.00', 'EXECUÇÃO DOS CONSÓRCIOS PÚBLICOS', 'Compreende as contas que controlam a execução dos consórcios públicos (do ente consorciado e/ou do próprio consórcio), incluindo os controles do contrato de rateio, controle da prestação de contas, bem como as informações que serão consolidadas no ente consorciado para fins de elaboração dos demonstrativos dos consórcios, conforme Portaria STN 72/2012.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4544, 2, '8.5.2.0.0.00.00.00.00.00', 'EXECUÇÃO DA PRESTAÇÃO DE CONTAS DE CONSÓRCIO PÚBLICO', 'Compreende contas relacionadas ao registro da execução do controle da prestação de contas referentes aos valores transferidos dos Consórcios Públicos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4573, 2, '2.3.7.1.1.02.00.00.00.00', 'SUPERÁVITS OU DÉFICITS DE EXERCÍCIOS ANTERIORES', 'Registra os superávits ou déficits acumulados de exercícios anteriores da administração direta, autarquias, fundações e fundos.', 3, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (4545, 2, '8.5.3.0.0.00.00.00.00.00', 'CONSOLIDAÇÃO DA EXECUÇÃO DO CONSÓRCIO', 'Compreende as informações referentes aos Consórcios Públicos, atribuídas ao ente consorciado com base no contrato de rateio,que serão enviadas pelo consórcio para os entes consorciados para fins de elaboração dos demonstrativos fiscais ( Saúde, pessoal, educação e disponibilidade de caixa), em atendimento a Portaria STN n.º 72/2012. Conta para uso do ente consorciado.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4546, 2, '8.5.3.2.0.00.00.00.00.00', 'DESPESAS EXECUTADAS EM CONSÓRCIOS PÚBLICOS', 'Compreende as despesas executadas em consórcios públicos atribuídas ao ente consorciado com base no contrato de rateio.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4547, 2, '8.5.3.2.4.00.00.00.00.00', 'CREDITO EMPENHADO LIQUIDADO PAGO', 'Demonstra o valor da despesa empenhada liquidada paga, executadas em consórcios públicos atribuídas ao ente consorciado com base no contrato de rateio.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4548, 2, '8.5.3.2.4.01.00.00.00.00', 'INFORMAÇÃO DA EXECUÇÃO DO CONSORCIO PARA CONSOLIDAÇÃO - DESPESA COM PESSOAL - EXERCICIO ANTERIOR', 'COMPREENDE A INFORMAÇÃO ENVIADA PELO CONSORCIO REFERENTE A APLICAÇÃO DAS TRANSFERENCIAS RECEBIDAS DO ENTE CONSORCIADO PARA PAGAMENTO DE DESPESA COM PESSOAL NOS PERIODOS DO EXERCICIO ANTERIOR UTILIZADOS PARA CONSOLIDAÇÃO COMPONDO ASSIM A PERIODICIDADE DO RGF DE CADA ENTE CONSORCIADO (QUADRIMESTRE OU SEMESTRE)', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4549, 2, '8.5.3.2.4.02.00.00.00.00', 'INFORMAÇÃO DA EXECUÇÃO DO CONSORCIO PARA CONSOLIDAÇÃO - DESPESA COM PESSOAL - EXERCICIO ATUAL', 'COMPREENDE A INFORMAÇÃO ENVIADA PELO CONSORCIO REFERENTE A APLICAÇÃO DAS TRANSFERENCIAS RECEBIDAS DO ENTE CONSORCIADO PARA PAGAMENTO DE DESPESA COM PESSOAL NOS PERIODOS DO EXERCICIO ATUAL UTILIZADOS PARA CONSOLIDAÇÃO COMPONDO ASSIM A PERIODICIDADE DO RGF DE CADA ENTE CONSORCIADO (QUADRIMESTRE OU SEMESTRE)', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4550, 2, '8.5.3.3.0.00.00.00.00.00', 'EXECUÇÃO DE RP NÃO PROCESSADOS EM CONSÓRCIOS PÚBLICOS', 'Compreende o somatório dos valores relativos à transferência, liquidação e pagamento das despesas empenhadas, não liquidadas no exercício financeiro de sua inscrição e não pagas, em consórcios públicos atribuídos ao ente consorciado com base no contrato de rateio.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4551, 2, '8.5.3.4.0.00.00.00.00.00', 'EXECUÇÃO DE RP PROCESSADOS EM CONSÓRCIOS PÚBLICOS', 'Compreende o somatório dos valores relativos à transferência, liquidação e pagamento das despesas empenhadas, liquidadas no exercício financeiro de sua inscrição e não pagas, em consórcios públicos atribuídos ao ente consorciado com base no contrato de rateio.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4552, 2, '8.8.0.0.0.00.00.00.00.00', 'APURAÇÃO DE CUSTOS', 'Compreende as contas que controlam a execução dos custos dos bens e serviços produzidos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4553, 2, '8.9.0.0.0.00.00.00.00.00', 'OUTROS CONTROLES', 'Compreende as contas de controles da execução não especificados anteriormente nos grupos dessa classe.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4554, 2, '8.9.1.0.0.00.00.00.00.00', 'EXECUÇÃO DE RESPONSABILIDADE POR VALORES, TÍTULOS E BENS', 'Compreende as contas relacionadas ao registro das responsabilidades por valores, títulos e bens.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4555, 2, '8.9.1.1.0.00.00.00.00.00', 'EXECUÇÃO DE RESPONSABILIDADE COM TERCEIROS POR VALORES, TÍTULOS E BENS', 'Compreende as contas relacionadas ao registro da responsabilidade da administração pública com terceiros por títulos, valores e bens.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4556, 2, '8.9.1.2.0.00.00.00.00.00', 'EXECUÇÃO DE RESPONSABILIDADE DE TERCEIROS POR VALORES, TÍTULOS E BENS', 'Compreende contas relacionadas ao registro da responsabilidade de terceiros com a administração pública por títulos, valores e bens.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4557, 2, '8.9.1.2.1.00.00.00.00.00', 'EXECUÇÃO DE ADIANTAMENTOS/SUPRIMENTOS DE FUNDOS CONCEDIDOS', 'Compreende os valores concedidos a servidor responsável para atender despesas que não possam subordinar-se ao processo normal de aplicação, até a sua prestação de contas.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4558, 2, '8.9.1.2.2.00.00.00.00.00', 'ATIVOS DE PPP CONTABILIZADOS NO ENTE', 'Compreende o valor dos ativos produzidos por meio de Parcerias Público Privadas contabilizados no Ente.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4559, 2, '8.9.2.0.0.00.00.00.00.00', 'DIVERSOS RESPONSÁVEIS EM APURAÇÃO', 'Compreende as responsabilidades em fase de apuração decorrentes de atos praticados por gestores, servidores ou terceiros que possam resultarem prejuízos para a fazenda nacional.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4560, 2, '8.9.2.9.0.00.00.00.00.00', 'OUTRAS RESPONSABILIDADES EM APURAÇÃO', 'Compreende outras responsabilidades em apuração.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (4561, 2, '8.9.2.9.1.00.00.00.00.00', 'MULTAS E JUROS', 'Compreende os valores referentes a multas e juros pagos pelo órgão, porém de responsabilidade de servidores e que estejam em fase de apuração.', 2, false, 0, 'N');
