insert into contabilidade.planocontadetalhe values (6713, 1, '1.2.0.0.0.00.00.00.00.00', 'ATIVO NÃO CIRCULANTE', 'Compreende o ativo não circulante: o ativo realizável a longo prazo, os investimentos, o imobilizado e o intangível.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6714, 1, '1.2.1.0.0.00.00.00.00.00', 'ATIVO REALIZÁVEL A LONGO PRAZO', 'Compreende os bens, direitos e despesas antecipadas realizáveis no longo prazo.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6715, 1, '1.2.1.1.0.00.00.00.00.00', 'CRÉDITOS A LONGO PRAZO', 'Compreende os valores a receber por fornecimento de bens, serviços, créditos tributários, dívida ativa, transferências e empréstimos e financiamentos concedidos e com vencimento no longo prazo.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6716, 1, '1.2.1.1.1.00.00.00.00.00', 'CRÉDITOS A LONGO PRAZO - CONSOLIDAÇÃO', 'Compreende os valores a receber por fornecimento de bens, serviços, créditos tributários, dívida ativa, transferências e empréstimos e financiamentos concedidos com vencimento no longo prazo. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6717, 1, '1.2.1.1.1.01.00.00.00.00', 'CRÉDITOS TRIBUTÁRIOS A RECEBER', 'Compreende os valores relativos a créditos a receber com vencimento após 12 (doze) meses da data das demonstrações, oriundos das variações patrimoniais aumentativas tributárias. Os tributos são: impostos, taxas, contribuições de melhoria, contribuições e empréstimos compulsórios.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6718, 1, '1.2.1.1.1.02.00.00.00.00', 'CLIENTES', 'Compreende os valores das faturas/duplicatas a receber decorrentes das vendas a prazo de mercadorias ou serviços que ocorrem no curso normal das operações da entidade (com vencimento após 12 (doze) meses da data das demonstrações, representando um direito a cobrar de seus clientes.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6719, 1, '1.2.1.1.1.03.00.00.00.00', 'EMPRÉSTIMOS E FINANCIAMENTOS CONCEDIDOS', 'Compreende o somatório dos valores de empréstimos e financiamentos concedidos por autorizações legais ou vinculações a contratos e acordos.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6720, 1, '1.2.1.1.1.04.00.00.00.00', 'DÍVIDA ATIVA TRIBUTÁRIA', 'Compreende os valores dos créditos de dívida ativa tributária inscritos, realizáveis após os doze meses seguintes a data de publicação dos demonstrativos contábeis.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6721, 1, '1.2.1.1.2.00.00.00.00.00', 'CRÉDITOS A LONGO PRAZO - INTRA OFSS', 'Compreende os valores a receber por fornecimento de bens, serviços, créditos tributários, dívida ativa, transferências e empréstimos e financiamentos concedidos com vencimento no longo prazo. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do ente.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6722, 1, '1.2.1.1.3.00.00.00.00.00', 'CRÉDITOS A LONGO PRAZO - INTER OFSS - UNIÃO', 'Compreende os valores a receber por fornecimento de bens, serviços, créditos tributários, dívida ativa, transferências e empréstimos e financiamentos concedidos com vencimento no longo prazo. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) de entes públicos distintos, para permitir a consolidação nacional realizada pelo Poder Executivo da União. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6723, 1, '1.2.1.1.4.00.00.00.00.00', 'CRÉDITOS A LONGO PRAZO - INTER OFSS - ESTADO', 'Compreende os valores a receber por fornecimento de bens, serviços, créditos tributários, dívida ativa, transferências e empréstimos e financiamentos concedidos com vencimento no longo prazo. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) de entes públicos distintos, para permitir a consolidação nacional realizada pelo Poder Executivo da União. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6724, 1, '1.2.1.1.4.03.00.00.00.00', 'EMPRÉSTIMOS E FINANCIAMENTOS CONCEDIDOS', 'Compreende o somatório dos valores de empréstimos e financiamentos concedidos por autorizações legais ou vinculações a contratos e acordos.', 1, false, 0, 'N');
