insert into contabilidade.planocontadetalhe values (4695, 1, '1.1.1.1.1.06.04.00.00.00', 'BANCOS CONTA MOVIMENTO - TAXA DE ADMINISTRAÇÃO', 'Registra a movimentação financeira dos recursos nas contas movimento da taxa de administração do RPPS através dos agentes financeiros credenciados.', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (4696, 1, '1.1.1.1.1.19.00.00.00.00', 'BANCOS CONTA MOVIMENTO - DEMAIS CONTAS', 'Compreende o somatório das disponibilidades existentes em outras contas bancárias, que não sejam a Conta Única, agregadas pelos subitens identificativos dos bancos correspondentes.', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (4697, 1, '1.1.1.1.1.30.00.00.00.00', 'REDE BANCARIA - ARRECADAÇÃO', 'Registra o somatório dos recursos referentes a receitas arrecadadas e não recolhidas.', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (4698, 1, '1.1.1.1.1.50.01.00.00.00', 'TÍTULOS PÚBLICOS', 'Registra os valores das disponibildiades das instituições, entidades e unidades aplicadas em títulos públicos.', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (4699, 1, '1.1.1.1.1.50.02.00.00.00', 'POUPANÇA', 'Registra o valor das aplicações financeiras em poupanças e seus rendimentos (juros e atualização moentária) posteriores.', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (4700, 1, '1.1.1.1.1.50.03.00.00.00', 'FUNDOS DE INVESTIMENTO', 'Registra o valor das aplicações financeiras em fundo de investimento e seus rendimentos (juros e atualização) posteriores, conforme instrução CVM 409/2004.', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (4701, 1, '1.1.1.1.1.50.04.00.00.00', 'CDB', 'Registra os valores das disponibilidades das instituições, entidades ou unidades aplicadas em certificados de depósitos bancários (CDB).', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (4702, 1, '1.1.1.1.1.50.99.00.00.00', 'OUTRAS APLICAÇÕES FINANCEIRAS DE LIQUIDEZ IMEDIATA', 'Registra outras aplicações financeiras, não classificadas em itens anteriores, das disponibilidades financeiras das entidades, instituições ou unidades.', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (4703, 1, '1.1.1.2.1.01.00.00.00.00', 'CAIXA', 'Registra o somatório de numerários em espécie e outros valores em tesouraria no exterior', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (4704, 1, '1.1.1.2.1.02.00.00.00.00', 'BANCOS', 'Registra a livre movimentação de recursos financeiros em moeda extrangeira mantidos em contas bancárias no exterior.', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (4705, 1, '1.2.1.2.1.02.05.00.00.00', 'IR E CSLL A RECUPERAR/COMPENSAR', 'Registra o somatório dos valores do IR e da CSLL a recuperar/compensar.', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (4706, 1, '1.1.1.2.1.03.00.00.00.00', 'APLICAÇÕES FINANCEIRAS DE LIQUIDEZ IMEDIATA', 'Registra as aplicações financeiras de alta liquidez em moeda estrangeira, que são prontamente conversíveis em valores conhecidos de caixa e que estão sujeitas a um insignificante risco de mudança de valor, inclusive as aplicações referentes ao fechamento de câmbio para aquisição de moeda estrangeira e as aplicações de depósitos com juros em moeda estrangeira realizadas no curtíssimo prazo.', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (4707, 1, '1.1.2.1.1.01.01.00.00.00', 'IMPOSTO SOBRE A RENDA E PROVENTOS DE QUALQUER NATUREZA', 'Registra os valores relativos a créditos a receber, decorrentes da cobrança do Imposto sobre a Renda e Proventos de Qualquer Natureza retidos na fonte.', 1, true, 2, 'P');
