insert into contabilidade.planocontadetalhe values (5014, 1, '1.1.3.6.4.01.00.00.00.00', 'CONTRIBUIÇÕES DO RPPS A RECEBER', 'Registra os valores relativos aos créditos a receber, decorrentes das contribuições previdenciárias do RPPS.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (4986, 1, '1.1.3.3.1.01.00.00.00.00', 'CRÉDITOS A RECEBER POR DESCENTRALIZAÇÃO DA PRESTAÇÃO DE SERVIÇOS PÚBLICOS', 'Registra os créditos a receber decorrentes da descentralização de serviços públicos, tanto por meio de outorga a entidades da administração indireta, como por meio de delegação, nas formas de concessão, inclusive parcerias público-privada - PPP, permissão ou autorização ao particular do direito de exploração de serviços públicos.', 1, true, 2, 'P');
