insert into contabilidade.planocontadetalhe values (4989, 1, '1.1.3.4.1.03.00.00.00.00', 'CRÉDITOS POR DANOS AO PATRIMONIO APURADOS EM PROCESSOS JUDICIAIS  ', 'Registra os valores realizáveis no curto prazo, provenientes de direitos oriundos de danos ao patrimônio, apurados em processos judiciais. ', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (4990, 1, '1.1.3.5.1.01.00.00.00.00', 'DEPÓSITOS E CAUÇÕES RELATIVOS A CONTRATOS OU CONVENÇÕES', 'Registra os valores relativos a depósitos e cauções, efetuados por vinculações a contratos ou convenções, para garantias de operações específicas, realizáveis no curto prazo.', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (4991, 1, '1.1.3.5.1.03.00.00.00.00', 'DEPÓSITOS PARA INTERPOSIÇÃO DE RECURSOS', 'Registra os valores relativos aos depósitos vinculados, decorrentes de interposição de recursos na esfera judicial ou administrativa.', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (4992, 1, '1.1.3.5.1.04.00.00.00.00', 'DEPÓSITOS ESPECIAIS', 'Registra os valores relativos a outros depósitos em contas bancárias, vinculados a obrigações contratuais, convenções, acordos e ajustes.', 1, true, 2, 'F');
