insert into contabilidade.planocontadetalhe values (4994, 1, '1.1.3.5.1.06.00.00.00.00', 'DEPÓSITOS TRANSFERIDOS', 'Registra os valores relativos a depósitos transferidos, para garantia de operações específicas.', 1, true, 2, 'F');
