insert into contabilidade.planocontadetalhe values (4998, 1, '1.1.3.6.1.01.01.00.00.00', 'CONTRIBUIÇÕES DO RPPS A RECEBER - SERVIDOR, APOSENTADO E PENSIONISTA', 'Registra os valores relativos aos créditos a receber, decorrentes das contribuições previdenciárias do RPPS, retidas dos servidores, aposentados e pensionistas.', 1, true, 2, 'P');
