insert into contabilidade.planocontadetalhe values (5028, 1, '1.1.3.8.1.03.00.00.00.00', 'VALORES A RECUPERAR DECORRENTES DE INDENIZAÇÕES POR SINISTROS PAGOS', 'Registra os valores a recuperar referentes a indenizações pelo pagamento de sinistros.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5029, 1, '1.1.3.8.1.04.00.00.00.00', 'VALES, TICKETS E BILHETES', 'Registra o valor dos vales, tickets e bilhetes adquiridos para futura distribuição aos servidores.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5030, 1, '1.1.3.8.1.06.00.00.00.00', 'VALORES EM TRÂNSITO REALIZÁVEIS A CURTO PRAZO', 'Compreende o somatório dos valores contabilizados indevidamente em conta bancária, guia de recebimento e ordens bancárias emitidas a compensar.', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (5031, 1, '1.1.3.8.1.07.00.00.00.00', 'CRÉDITOS A RECEBER DECORRENTES DE INFRAÇÕES LEGAIS E CONTRATUAIS', 'Registra os recursos a receber provenientes da aplicação de autos de infração ou decorrentes de quebra de cláusulas contratuais. Os créditos decorrentes da quebra de cláusulas contratuais podem ser pagos em espécie, glosa ou através de fornecimentos.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5032, 1, '1.1.3.8.1.08.00.00.00.00', 'CRÉDITOS A RECEBER POR REEMBOLSO DE SALÁRIO FAMÍLIA PAGO', 'Registra os valores relativos ao salário-família, incluídos em folhas de pagamento, pagos aos empregados (CLT), com filhos menores, a compensar com as contribuições devidas pelo empregador a Previdência Social.', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (5033, 1, '1.1.3.8.1.09.00.00.00.00', 'CRÉDITOS A RECEBER POR REEMBOLSO DE SALÁRIO MATERNIDADE PAGO', 'Registra os salários pagos as servidoras gestantes, regidas pela CLT no período que perdurar a licença maternidade, prevista em lei, a deduzir das obrigações sociais devidas pelos órgãos e entidades.', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (5034, 1, '1.1.3.8.1.10.00.00.00.00', 'AUXÍLIO NATALIDADE PAGO A RECUPERAR', 'Registra os valores relativos à auxilio natalidade, pagos aos empregados regidos pela CLT, quando do nascimento de filhos destes, a recuperar, por se tratar de obrigações da Previdência Social.', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (5035, 1, '1.1.3.8.1.11.00.00.00.00', 'CRÉDITOS A RECEBER POR REEMBOLSO DE AUXÍLIO DOENÇA E ACIDENTES PAGOS', 'Registra os salários pagos aos servidores, regidos pela CLT, a título de auxilio doença/acidentes, previsto em lei, a serem reembolsados pelo INSS.', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (5036, 1, '1.1.3.8.1.12.00.00.00.00', 'CRÉDITOS A RECEBER POR CESSÃO DE PESSOAL', 'Registra os valores de créditos a receber tais como: folha de pagamento, despesa de transporte, alimentação e outras relativas à cessão de pessoal.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5037, 1, '1.1.3.8.1.13.00.00.00.00', 'CRÉDITOS A RECEBER DECORRENTES DE CESSÃO DE ÁREAS PÚBLICAS', 'Registra os valores dos créditos a receber decorrentes da cessão de áreas públicas.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5038, 1, '1.1.3.8.1.14.00.00.00.00', 'CRÉDITOS A RECEBER DECORRENTES DE ALIENAÇÃO DE BENS MÓVEIS E IMÓVEIS', 'Registra os valores dos créditos a receber decorrentes da alienação de bens móveis ou imóveis.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5039, 1, '1.1.3.8.1.15.00.00.00.00', 'CRÉDITOS A RECEBER DECORRENTES DE PAGAMENTO DE DESPESA DE TERCEIROS', 'Registra os recursos a receber provenientes de pagamentos de despesas de terceiros decorrentes de cláusulas contratuais, tais como: água, luz, telefone, instalações, transporte e aluguéis.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5040, 1, '1.1.3.8.1.16.00.00.00.00', 'CRÉDITOS A RECEBER POR ACERTO FINANCEIRO COM SERVIDORES E EX-SERVIDORES', 'Registra os valores dos créditos a receber decorrentes de acertos financeiros com servidores e ex-servidores do órgão, conforme disposto na lei 8.112/90.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5041, 1, '1.1.3.8.1.17.00.00.00.00', 'CRÉDITOS A RECEBER DECORRENTES DE FOLHA DE PAGAMENTO', 'Registra os valores dos créditos a receber decorrentes de folha de pagamento.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5042, 1, '1.1.3.8.1.18.00.00.00.00', 'DIVIDENDOS PROPOSTOS A RECEBER', 'Registra os valores dos dividendos a que a empresa tenha direito, em função de participações em outras empresas, quando tais empresas já tenham registrado na demonstração de lucros ou prejuízos acumulados a parcela de dividendos propostos a distribuir.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5044, 1, '1.1.3.8.1.27.00.00.00.00', 'TÍTULOS A RECEBER', 'Compreende os valores a receber a curto prazo representados por notas promissórias, letras de câmbio e outros.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5045, 1, '1.1.3.8.1.28.00.00.00.00', 'CREDITOS A RECEBER DE ENTIDADES FEDERAIS', 'Registra os valores a receber a curto prazo, decorrentes de direitos junto a entidades federais.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5046, 1, '1.1.3.8.1.29.00.00.00.00', 'CREDITOS A RECEBER DE ENTIDADES ESTADUAIS, DISTRITAIS E MUNICIPAIS', 'Registra os valores a receber a curto prazo, decorrentes de direitos junto a estados, DF e municípios.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5047, 1, '1.1.3.8.1.31.00.00.00.00', 'CRÉDITOS A RECEBER DE PARCELAMENTOS', 'Registra o crédito de origem fiscal ou não, se autorizado o parcelamento, excluídos os créditos tributários e previdenciários.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5048, 1, '1.1.3.8.1.99.00.00.00.00', 'OUTROS CRÉDITOS A RECEBER E VALORES DE  CURTO PRAZO', 'Registra os valores de outros créditos a receber, para os quais não tenham contas especificas neste subgrupo de contas.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5049, 1, '1.1.4.1.1.01.00.00.00.00', 'TÍTULOS PÚBLICOS', 'Compreendem os valores relativos aos titulos públicos, emitidos e em circulacao, de posse da entidade pública.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5050, 1, '1.1.4.1.1.02.00.00.00.00', 'AÇÕES', 'Compreende os valores das ações representativas das participações dos orgaos e entidades no capital das sociedades por ações havidas por aquisiões, subscrições, bonificações e doações.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5051, 1, '1.1.4.1.1.03.00.00.00.00', 'DERIVATIVOS', 'Compreende os créditos relativos a operações com derivativos.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5052, 1, '1.1.4.1.1.09.01.00.00.00', 'TÍTULOS DE RESPONSABILIDADE DO TESOURO', 'Registra os investimentos realizados pelo RPPS em títulos de emissão do Tesouro Nacional, efetuados em conformidade com as Resoluções CMN n° 3.992/2010 e 4392/2014.', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (5053, 1, '1.1.4.1.1.09.02.00.00.00', 'TÍTULOS DE RESPONSABILIDADE DO BANCO CENTRAL', 'Registra saldos remanescentes dos investimentos realizados pelo RPPS, em títulos de emissão do Banco Central do Brasil, considerando que este não emite mais títulos da Dívida Pública, conforme artº 34 da Lei Complementar nº 101/2000.', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (5054, 1, '1.1.4.1.1.09.03.00.00.00', 'DEPÓSITOS DE POUPANÇA', 'Registra os investimentos realizados pelo RPPS em poupança e seus rendimentos (juros e atualização monetária) posteriores, em conformidade com as Resoluções CMN n° 3.992/2010 e 4392/2014.', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (5055, 1, '1.1.4.1.1.09.04.00.00.00', 'FUNDOS DE INVESTIMENTO EM RENDA FIXA OU REFERENCIADOS', 'Registra os investimentos realizados pelos RPPS em fundos de investimentos em renda fixa, efetuados em conformidade com a Resolução CMN n° 3.992/2010 (alterada pela Resolução CMN nº 4.392/2014), art 7º, incisos IV.', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (5056, 1, '1.1.4.1.1.09.05.00.00.00', 'FUNDOS DE INVESTIMENTO EM RENDA FIXA - CRÉDITO PRIVADO', 'Registra os investimentos realizados pelos RPPS em fundos de investimentos em renda fixa - crédito privado, efetuados em conformidade com as Resoluções CMN n° 3.992/2010 e 4392/2014.', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (5057, 1, '1.1.4.1.1.09.06.00.00.00', 'FUNDOS DE INVESTIMENTOS EM RENDA FIXA OU REFERENCIADOS - IMA/IDkA', 'Registra os investimentos realizados pelo RPPS em fundos de investimentos ou como referenciados em indicadores de desempenho de renda fixa, constituídos sob a forma de condomínio aberto e cuja política de investimento assuma o compromisso de buscar o retorno de um dos subíndices do Índice de Mercado Anbima (IMA) ou do Índice de Duração Constante Anbima (IDkA), efetuados em conformidade com as Resoluções CMN n° 3.992/2010 e 4392/2014.', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (5058, 1, '1.1.4.1.1.09.07.00.00.00', 'FUNDOS DE INVESTIMENTOS EM DIREITOS CREDITORIOS ', 'Registra os investimentos realizados pelo RPPS em fundos de investimentos em direito creditório, efetuados em conformidade com as Resoluções CMN n° 3.992/2010 e 4392/2014.', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (5059, 1, '1.1.4.1.1.09.08.00.00.00', 'FUNDOS DE INVESTIMENTOS EM TÍTULOS DO TESOURO', 'Registra os investimentos realizados pelo RPPS, em fundos de investimentos em titulos do tesouro, efetuados em conformidade com as Resoluções CMN n° 3.992/2010 e 4392/2014.', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (5060, 1, '1.1.4.1.1.09.09.00.00.00', 'OPERAÇÕES COMPROMISSADAS', 'Registra os investimentos realizados pelo RPPS, em operações compromissadas, efetuados em conformidade com as Resoluções CMN n° 3.992/2010 e 4392/2014.', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (5061, 1, '1.1.4.1.1.09.10.00.00.00', 'LETRAS IMOBILIÁRIAS GARANTIDAS', 'Registra os investimentos realizados pelo RPPS, em letras imobiliárias garantidas, efetuados em conformidade com a Resolução CMN n° 3.992/2010 (alterada pela Resolução CMN nº 4.392/2014), art 7º, inciso V, alínea "b".', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (5062, 1, '1.1.4.1.1.10.01.00.00.00', 'FUNDOS DE INVESTIMENTOS REFERENCIADOS', 'Registra os investimentos realizados pelo RPPS em fundos de investimentos referenciados, renda variável, efetuados em conformidade com as Resoluções CMN n° 3.992/2010 e 4392/2014.', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (5063, 1, '1.1.4.1.1.10.02.00.00.00', 'FUNDOS DE INVESTIMENTO EM AÇÕES  ', 'Registra os investimentos realizados pelo RPPS em fundo de investimentos em ações, efetuados em conformidade com as Resoluções CMN n° 3.992/2010 e 4392/2014.', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (5064, 1, '1.1.4.1.1.10.03.00.00.00', 'FUNDOS DE INVESTIMENTO MULTIMERCADO ', 'Registra os investimentos realizados pelo RPPS em fundo de investimentos multimercado, efetuados em conformidade com as Resoluções CMN n° 3.992/2010 e 4392/2014.', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (5065, 1, '1.1.4.1.1.10.04.00.00.00', 'FUNDOS DE ÍNDICES REFERENCIADOS EM AÇÕES', 'Registra os investimentos realizados pelo RPPS em fundos de índices referenciados em ações, efetuados em conformidade com as Resoluções CMN n° 3.992/2010 e 4392/2014.', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (5066, 1, '1.1.4.1.1.10.05.00.00.00', 'FUNDOS DE INVESTIMENTOS EM PARTICIPAÇÕES', 'Registra os investimentos realizados pelo RPPS em fundos de investimentos em participações, efetuados em conformidade com as Resoluções CMN n° 3.992/2010 e 4392/2014.', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (5067, 1, '1.1.4.1.1.10.06.00.00.00', 'FUNDOS DE INVESTIMENTOS IMOBILIÁRIOS', 'Registra os investimentos realizados pelo RPPS em fundo de investimentos imobiliarios, efetuados em conformidade com as Resoluções CMN n° 3.992/2010 e 4392/2014.', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (5068, 1, '1.1.4.1.1.11.01.00.00.00', 'FUNDOS DE INVESTIMENTO IMOBILIÁRIOS', 'Registra o somatório dos investimentos realizados pelo RPPS com recursos previdenciários em fundos de investimento imobiliários, efetuados em conformidade com as Resoluções CMN n° 3.992/2010 e 4392/2014.', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (5069, 1, '1.1.4.1.1.12.01.00.00.00', 'TITULOS E VALORES EM ENQUADRAMENTO', 'Registra os investimentos realizados pelo RPPS, em desacordo com as regras estabelecidas pelas Resoluções CMN nº 3.992/2010 e 4.392/2014.', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (6356, 1, '5.2.2.1.9.01.01.00.00.00', 'ACRESCIMO', 'Registra a movimentação dos créditos por acréscimo decorrente de alteração do quadro de detalhamento de despesas - QDD.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (5070, 1, '1.1.4.1.1.13.01.00.00.00', 'TITULOS E VALORES NAO SUJEITOS AO ENQUADRAMENTO', 'Registra os investimentos realizados pelo RPPS, em ativos não sujeitos as regras das Resoluções CMN nº 3.992/2010 e 4.392/2014.', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (5071, 1, '1.1.4.1.1.14.01.00.00.00', 'APLICAÇÕES COM A TAXA DE ADMINISTRAÇÃO DO RPPS', 'Registra os investimentos realizados pelo RPPS, com recursos da taxa de administração, sujeitos as regras das Resoluções CMN nº 3.992/2010 e 4.392/2014.', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (5072, 1, '1.1.4.1.1.15.00.00.00.00', 'FUNDO DE APLICAÇÕES EM COTAS - RENDA VARIÁVEL', 'Registra os valores, realizáveis até 12 (doze) meses da data das demonstrações, aplicados em fundos de aplicações em cotas - renda variável.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5073, 1, '1.1.4.1.1.99.00.00.00.00', 'OUTROS TÍTULOS E VALORES MOBILIÁRIOS', 'Registra os valores, realizáveis até 12 (doze) meses da data das demonstrações, de outros títulos e valores mobiliários.', 1, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (5074, 1, '1.1.5.1.1.01.00.00.00.00', 'MERCADORIAS PARA VENDA OU REVENDA', 'Registra o valor das mercadorias para venda ou revenda e doações relativas a estoques da entidade.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5075, 1, '1.1.5.1.1.02.00.00.00.00', 'MERCADORIAS ESTOQUES REGULATÓRIOS', 'Registra o valor das mercadorias adquiridas para revenda relativas a estoques públicos.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5076, 1, '1.1.5.1.1.99.00.00.00.00', 'OUTRAS MERCADORIAS PARA REVENDA', 'Registra o valor das demais mercadorias adquiridas para revenda.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5077, 1, '1.1.5.2.1.01.00.00.00.00', 'PRODUTOS ACABADOS', 'Registra o valor de produtos manufaturados já terminados, oriundos da própria produção da entidade e disponíveis para venda, estocados na fábrica, ou em depósitos, ou em filiais, ou ainda com terceiros em consignação.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5078, 1, '1.1.5.2.1.02.00.00.00.00', 'SERVICOS ACABADOS', 'Registra os valores pertinentes a serviços acabados que estão pendentes de faturamento ou de transferência para outras contas do ativo.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5079, 1, '1.1.5.3.1.01.00.00.00.00', 'PRODUTOS EM ELABORAÇÃO  ', 'Registra a totalidade das matérias-primas já requisitadas que estão em processo de transformação e o montante de custos diretos e indiretos relativos aos produtos em elaboração não concluídos na data do balanço patrimonial.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5080, 1, '1.1.5.3.1.02.00.00.00.00', 'SERVICOS EM ELABORAÇÃO', 'Registra os custos diretos e indiretos relativos aos serviços em elaboração não concluídos na data do balanço patrimonial.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5081, 1, '1.1.5.4.1.01.00.00.00.00', 'MATERIAS-PRIMAS - ARMAZENS PROPRIOS', 'Registra o estoque de matérias-primas que serão utilizados no processo produtivo, guardadas em armazéns próprios.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5082, 1, '1.1.5.4.1.02.00.00.00.00', 'MATERIAS-PRIMAS - ARMAZENS DE TERCEIROS', 'Registra o estoque de matérias-primas que serão utilizados no processo produtivo, guardadas em armazéns de terceiros. ', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5083, 1, '1.1.5.5.1.01.00.00.00.00', 'MATERIAL EM TRANSITO', 'Compreende os valores dos materiais em trânsito relativos a transferências efetuadas entre unidades.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5084, 1, '1.1.5.6.1.02.00.00.00.00', 'GÊNEROS ALIMENTÍCIOS', 'Registra os valores dos gêneros alimentícios adquiridos e estocados em almoxarifados, destinados a atender ao consumo interno da unidade.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5085, 1, '1.1.5.6.1.03.00.00.00.00', 'MATERIAIS DE CONSTRUÇÃO', 'Registra os valores dos materiais de construção adquiridos e estocados em almoxarifados, destinados a atender ao consumo interno da unidade.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5086, 1, '1.1.5.6.1.04.00.00.00.00', 'AUTOPEÇAS', 'Registra os valores de autopeças adquiridas e estocadas em almoxarifados, destinadas a atender ao consumo interno da unidade.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5087, 1, '1.1.5.6.1.05.00.00.00.00', 'MEDICAMENTOS E MATERIAIS HOSPITALARES', 'Registra os valores dos medicamentos e materias hospitalares adquiridos e estocados em almoxarifados, destinados a atender ao consumo interno da unidade.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5088, 1, '3.1.1.1.1.01.05.00.00.00', 'ADICIONAL DE PERICULOSIDADE', 'Registra o valor da despesa com adicional de periculosidade.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5089, 1, '1.1.5.6.1.06.00.00.00.00', 'MATERIAIS GRÁFICOS', 'Registra os valores dos materiais gráficos adquiridos e estocados em almoxarifados, destinados a atender ao consumo interno da unidade.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5090, 1, '1.1.5.6.1.07.00.00.00.00', 'MATERIAL DE EXPEDIENTE', 'Registra os valores dos materiais de expediente adquiridos e estocados em almoxarifados, destinados a atender ao consumo interno da unidade.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5091, 1, '1.1.5.6.1.08.00.00.00.00', 'MATERIAIS A CLASSIFICAR', 'Registra os valores dos materiais estocados pendentes de classificação e identificação.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5092, 1, '1.1.5.6.1.09.00.00.00.00', 'ESTOQUE SOBRESSALENTES A ALIENAR', 'Registra os valores de bens sobressalentes que estejam disponíveis para alienação sob diversas formas (venda, leilão, etc)', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5093, 1, '1.2.1.1.1.01.04.00.00.00', 'DEMAIS CONTRIBUIÇÕES', 'Registra os créditos tributários a receber provenientes de contribuições especiais, exceto contribuições previdenciárias.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5094, 1, '1.2.1.1.1.01.05.00.00.00', 'CONTRIBUIÇÕES PREVIDENCIÁRIAS DO RGPS A RECEBER', 'Registra os créditos tributários a receber provenientes de contribuições previdenciárias do RGPS.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5095, 1, '1.2.1.1.1.01.70.00.00.00', 'CRÉDITOS TRIBUTÁRIOS PARCELADOS', 'Registra os valores relativos aos créditos a receber, decorrentes de Créditos Tributários Parcelados, exceto créditos previdenciários.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5096, 1, '1.2.1.1.1.01.71.00.00.00', 'CRÉDITOS PREVIDENCIÁRIOS PARCELADOS', 'Registra os valores relativos aos créditosa receber, decorrentes de créditos previdenciários parcelados.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5097, 1, '1.2.1.1.1.02.01.00.00.00', ' FATURAS/DUPLICATAS A RECEBER ', 'Registra os valores provenientes dos faturamentos da venda de mercadorias/produtos e serviços do estoque da entidade.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5098, 1, '1.2.1.1.1.03.01.00.00.00', 'EMPRÉSTIMOS CONCEDIDOS A RECEBER ', 'Registra os valores dos créditos por empréstimos concedidos pelo Ente, por autorização legal ou vinculação a contrato ou acordo, com vencimento a longo prazo.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5099, 1, '1.2.1.1.1.03.02.00.00.00', 'FINANCIAMENTOS CONCEDIDOS A RECEBER', 'Registra os valores dos créditos por financiamentos concedidos pelo Ente, por autorizaão legal ou vinculação a contrato ou acordo, com vencimento a longo prazo.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5100, 1, '1.2.1.1.1.03.03.00.00.00', 'EMPRÉSTIMOS A RECEBER - RPPS', 'Registra os créditos a receber provenientes de empréstimos concedidos por meio de recursos previdenciários.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5101, 1, '1.2.1.1.1.04.01.00.00.00', 'CRÉDITOS NÃO PREVIDENCIÁRIOS INSCRITOS', 'Registra os valores relativos a créditos inscritos de Dívida Ativa tributária não previdenciária.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5102, 1, '1.2.1.1.1.04.02.00.00.00', 'CRÉDITOS PREVIDENCIÁRIOS INSCRITOS', 'Registra os valores relativos a créditos inscritos de Dívida Ativa tributária previdenciária, excluídos valores devidos pelo ente público. Estão incluídos, por exemplo, valores devidos por servidor em gozo de licença para tratamento de interesses particulares, entre outros.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5103, 1, '1.2.1.1.1.05.00.00.00.00', 'DÍVIDA ATIVA NÃO TRIBUTÁRIA', 'Compreende os valores dos créditos de dívida ativa não tributária inscritos, realizáveis no longo prazo.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5104, 1, '1.2.1.1.2.01.00.00.00.00', 'CRÉDITOS TRIBUTÁRIOS A RECEBER', 'Compreende os valores relativos a créditos a receber com vencimento após 12 (doze) meses da data das demonstrações, oriundos daw variações patrimoniais aumentativas tributárias. Os tributos são: impostos, taxas, contribuições de melhoria, contribuições e empréstimos compulsórios.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5105, 1, '1.2.1.1.2.02.00.00.00.00', 'CLIENTES', 'Compreende os valores das faturas/duplicatas a receber decorrentes das vendas a prazo de mercadorias ou serviços que ocorrem no curso normal das operações da entidade (com vencimento após 12 (doze) meses da data das demonstrações), representando um direito a cobrar de seus clientes.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5106, 1, '1.2.1.1.2.03.00.00.00.00', 'EMPRÉSTIMOS E FINANCIAMENTOS CONCEDIDOS', 'Compreende o somatório dos valores de empréstimos e financiamentos concedidos por autorizações legais ou vinculações a contratos e acordos.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5107, 1, '1.2.1.1.2.04.00.00.00.00', 'DÍVIDA ATIVA TRIBUTÁRIA', 'Compreende os valores dos créditos de dívida ativa tributária inscritos, realizáveis após os doze meses seguintes a data de publicação dos demonstrativos contábeis.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5108, 1, '1.2.1.1.2.05.00.00.00.00', 'DÍVIDA ATIVA NÃO TRIBUTÁRIA', 'Compreende os valores dos créditos de dívida ativa não tributária inscritos, realizáveis no longo prazo.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5109, 1, '1.2.1.1.3.01.00.00.00.00', 'CRÉDITOS TRIBUTÁRIOS A RECEBER', 'Compreende os valores relativos a créditos a receber com vencimento após 12 (doze) meses da data das demonstrações, oriundos da variação patrimonial aumentativa tributárias. Os tributos são: impostos, taxas, contribuições de melhoria, contribuições e empréstimos compulsório.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5110, 1, '1.2.1.1.3.02.00.00.00.00', 'CLIENTES', 'Compreende os valores das faturas/duplicatas a receber decorrentes das vendas a prazo de mercadorias ou serviços que ocorrem no curso normal das operações da entidade (com vencimento após 12 (doze) meses da data das demonstrações), representando um direito a cobrar de seus clientes.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5111, 1, '1.2.1.1.3.03.00.00.00.00', 'EMPRÉSTIMOS E FINANCIAMENTOS CONCEDIDOS', 'Compreende o somatório dos valores de empréstimos e financiamentos concedidos por autorizações legais ou vinculações a contratos e acordos.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5112, 1, '1.2.1.1.3.04.00.00.00.00', 'DÍVIDA ATIVA TRIBUTÁRIA', 'Compreende os valores dos créditos de dívida ativa tributária inscritos, realizáveis após os doze meses seguintes a data de publicação dos demonstrativos contábeis.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5113, 1, '1.2.1.1.3.05.00.00.00.00', 'DÍVIDA ATIVA NÃO TRIBUTÁRIA', 'Compreende os valores dos créditos de dívida ativa não tributária inscritos, realizáveis no longo prazo.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5114, 1, '1.2.1.1.4.01.00.00.00.00', 'CRÉDITOS TRIBUTÁRIOS A RECEBER', 'Compreende os valores relativos a créditos a receber com vencimento após 12 (doze) meses da data das demonstrações, oriundos das variações patrimoniais aumentativas tributárias. Os tributos são: impostos, taxas, contribuições de melhoria, contribuições e empréstimos compulsórios.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5115, 1, '1.2.1.1.4.02.00.00.00.00', 'CLIENTES', 'Compreende os valores das faturas/duplicatas a receber decorrentes das vendas a prazo de mercadorias ou serviços que ocorrem no curso normal das operações da entidade (com vencimento após 12 (doze) meses da data das demonstrações), representando um direito a cobrar de seus clientes.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5116, 1, '1.2.1.1.4.03.01.00.00.00', 'EMPRÉSTIMOS CONCEDIDOS', 'Registra ao créditos a receber provenientes de empréstimos concedidos por autorizações legais ou vinculações a contratos e acordos.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5117, 1, '1.2.1.1.4.03.02.00.00.00', 'JUROS E ENCARGOS SOBRE EMPRÉSTIMOS CONCEDIDOS A RECEBER', 'Registra o somatório dos valores dos Juros e Encargos sobre Empréstimos a Receber.', 1, true, 2, 'P');
