insert into contabilidade.planocontadetalhe values (5119, 1, '1.2.1.1.4.03.04.00.00.00', 'JUROS E ENCARGOS SOBRE FINANCIAMENTOS CONCEDIDOS A RECEBER', 'Registra o somatório dos valores dos Juros e Encargos sobre Financiamentos Concedidos a Receber.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5120, 1, '1.2.1.1.4.03.05.00.00.00', 'EMPRÉSTIMOS A RECEBER - RPPS', 'Registra os créditos a receber provenientes de empréstimos concedidos por meio de recursos previdenciários.', 1, true, 2, 'P');
