insert into contabilidade.planocontadetalhe values (5122, 1, '1.2.1.1.4.03.07.00.00.00', 'FINANCIAMENTOS A RECEBER - RPPS', 'Registra os créditos a receber provenientes de financiamentos concedidos por meio de recursos previdenciários.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5123, 1, '1.2.1.1.4.03.08.00.00.00', 'JUROS E ENCARGOS SOBRE FINANCIAMENTOS A RECEBER - RPPS', 'Registra o somatório dos valores dos Juros e Encargos sobre financiamentos concedidos com recursos previdenciários.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5124, 1, '1.2.1.1.4.03.09.00.00.00', 'PROGRAMA DE REESTRUTURAÇÃO FISCAL DOS ESTADOS - CRÉDITOS A RECEBER', 'Registra os valores a receber decorrentes da assunção e refinanciamento, pela União, de dívidas de responsabilidade dos Estados e Distrito Federal, nos termos da Lei nº 9.496, de 11 de setembro de 1997.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5125, 1, '1.2.1.1.4.03.10.00.00.00', 'JUROS E ENCARGOS A RECEBER - PROGRAMA DE REESTRUTURAÇÃO FISCAL DOS ESTADOS', 'Registra os juros e encargos a receber decorrentes da assunção e refinanciamento, pela União, de dívidas de responsabilidade dos Estados e Distrito Federal, nos termos da Lei nº 9.496, de 11 de setembro de 1997.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5126, 1, '1.2.1.1.4.04.00.00.00.00', 'DÍVIDA ATIVA TRIBUTÁRIA', 'Compreende os valores dos créditos de dívida ativa tributária inscritos, realizáveis após os doze meses seguintes a data de publicação dos demonstrativos contábeis.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5127, 1, '1.2.1.1.4.05.00.00.00.00', 'DÍVIDA ATIVA NÃO TRIBUTÁRIA ', 'Compreende os valores dos créditos de dívida ativa não tributária inscritos, realizáveis no longo prazo.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (6357, 1, '5.2.2.1.9.02.01.00.00.00', 'ACRESCIMO', 'Registra os valores dos acréscimos resultantes de alterações da lei orçamentária em virtude de remanejamento.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (5128, 1, '1.2.1.1.5.01.00.00.00.00', 'CRÉDITOS TRIBUTÁRIOS A RECEBER', 'Compreende os valores relativos a créditos a receber com vencimento após 12 (doze) meses da data das demonstrações, oriundos das variações patrimoniais aumentativas tributárias. Os tributos são: impostos, taxas, contribuições de melhoria, contribuições e empréstimos compulsórios.', 1, true, 2, 'P');
