insert into contabilidade.planocontadetalhe values (5308, 1, '1.2.2.7.1.01.00.00.00.00', 'OBRAS DE ARTE E OUTROS BENS SINGULARES', 'Registra os valores provenientes de Obras de Arte e outros bens singulares, tais como jóias, antiguidades, moedas sem valor liberatório e etc.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5309, 1, '1.2.2.7.1.02.00.00.00.00', 'TÍTULOS E VALORES MOBILIÁRIOS PERMANENTE', 'Registra o valor dos Títulos e Valores Mobiliários não classificáveis no Ativo Circulante nem no Ativo Realizável a Longo Prazo, com por exemplo as Debêntures (Perpetuas).', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5310, 1, '1.2.2.7.1.03.00.00.00.00', 'BENS MOVEIS NÃO DESTINADOS A USO', 'Registra os valores de Bens Moveis da Unidade mantidos para geração de renda.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5311, 1, '1.2.2.7.1.04.00.00.00.00', 'BENS INTANGIVEIS NÃO DESTINADOS A USO', 'Registra o valor de Bens Intangíveis não destinados ao Uso e que a Unidade não explore comercialmente.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5312, 1, '1.2.2.7.1.99.00.00.00.00', 'DEMAIS INVESTIMENTOS PERMANENTES', 'Registra o valor de Investimentos Permanentes, não classificáveis nas demais contas deste Plano.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5313, 1, '1.2.3.1.1.01.01.00.00.00', 'APARELHOS DE MEDIÇÃO E ORIENTAÇÃO', 'Registra os aparelhos utilizados para medição e orientação.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5314, 1, '1.2.3.1.1.01.02.00.00.00', 'APARELHOS E EQUIPAMENTOS DE COMUNICAÇÃO', 'Registra os aparelhos e equipamentos utilizados para comunicação.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5315, 1, '1.2.3.1.1.01.03.00.00.00', 'APARELHOS, EQUIPAMENTOS E UTENSÍLIOS MÉDICOS, ODONTOLÓGICOS, LABORATORIAIS E HOSPITALARES ', 'Registra os aparelhos, equipamentos e utensílios para uso médico, odontológico, laboratorial e hospitalar.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5316, 1, '1.2.3.1.1.01.04.00.00.00', 'APARELHOS E EQUIPAMENTOS PARA ESPORTES E DIVERSÕES', 'Registra os aparelhos e equipamentos utilizados para modalidades de esportes e diversões.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5317, 1, '1.2.3.1.1.01.05.00.00.00', 'EQUIPAMENTO DE PROTEÇÃO, SEGURANÇA E SOCORRO', 'Registra os equipamentos utilizados para proteção, segurança e socorro.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5318, 1, '1.2.3.1.1.01.06.00.00.00', 'MÁQUINAS E EQUIPAMENTOS INDUSTRIAIS', 'Registra as máquinas e equipamentos de natureza industrial.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5319, 1, '1.2.3.1.1.01.07.00.00.00', 'MÁQUINAS E EQUIPAMENTOS ENERGÉTICOS', 'Registra as máquinas e equipamentos energéticos.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5320, 1, '1.2.3.1.1.01.08.00.00.00', 'MÁQUINAS E EQUIPAMENTOS GRÁFICOS', 'Registra as máquinas e equipamentos empregados na indústria gráfica ou necessários para sua industrialização.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5321, 1, '1.2.3.1.1.01.09.00.00.00', 'MÁQUINAS, FERRAMENTAS E UTENSÍLIOS DE OFICINA', 'Registra as máquinas, ferramentas ou utensílios utilizados em oficinas.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5322, 1, '1.2.3.1.1.01.10.00.00.00', 'EQUIPAMENTOS DE MONTARIA', 'Registra os equipamentos utilizados em montarias, bem como os serviços correlacionados.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5323, 1, '1.2.3.1.1.01.11.00.00.00', 'EQUIPAMENTOS E MATERIAL SIGILOSO E RESERVADO', 'Registra os equipamentos e materiais utilizados em atividades de caráter sigiloso ou reservado.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5324, 1, '1.2.3.1.1.01.12.00.00.00', 'EQUIPAMENTOS, PEÇAS E ACESSÓRIOS PARA AUTOMÓVEIS', 'Registra os equipamentos, peças e acessórios para automóveis que podem ser desincorporados, sem prejuízo dos mesmos, para aplicação em outros veículos.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5325, 1, '1.2.3.1.1.01.13.00.00.00', 'EQUIPAMENTOS, PEÇAS E ACESSÓRIOS MARÍTIMOS', 'Registra os equipamentos, peças e acessórios marítimos.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5326, 1, '1.2.3.1.1.01.14.00.00.00', 'EQUIPAMENTOS, PEÇAS E ACESSÓRIOS AERONÁUTICOS', 'Registra os equipamentos, peças e acessórios aeronáuticos.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5327, 1, '1.2.3.1.1.01.15.00.00.00', 'EQUIPAMENTOS, PEÇAS E ACESSÓRIOS DE PROTEÇÃO AO VOO', 'Registra os equipamentos, peças e acessórios de proteção de voo.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5329, 1, '1.2.3.1.1.01.17.00.00.00', 'EQUIPAMENTOS DE MANOBRAS E PATRULHAMENTO', 'Registra os equipamentos destinados ao exercício militar, serviço de bordo, guarnições, rondas ou vigilância utilizados pela unidade.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5330, 1, '1.2.3.1.1.01.18.00.00.00', 'EQUIPAMENTOS DE PROTEÇÃO E VIGILÂNCIA AMBIENTAL', 'Registra os equipamentos utilizados em sistemas de proteção e vigilância aérea e ambiental.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5331, 1, '1.2.3.1.1.01.19.00.00.00', 'MÁQUINAS, EQUIPAMENTOS E UTENSÍLIOS AGROPECUÁRIOS ', 'Registra os valores relativos a máquinas, equipamentos, ferramentas e utensílios agropecuários.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5332, 1, '1.2.3.1.1.01.20.00.00.00', 'MÁQUINAS, EQUIPAMENTOS E UTENSÍLIOS RODOVIÁRIOS ', 'Registra os valores relativos a máquinas, equipamentos, ferramentas e utensílios rodoviários.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5333, 1, '1.2.3.1.1.01.21.00.00.00', 'EQUIPAMENTOS HIDRÁULICOS E ELÉTRICOS', 'Registra os equipamentos hidráulicos e elétricos.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5334, 1, '1.2.3.1.1.01.99.00.00.00', 'OUTRAS MÁQUINAS, APARELHOS, EQUIPAMENTOS E FERRAMENTAS', 'Registra os valores referentes a máquinas, aparelhos, equipamentos e ferramentas não classificados em contas anteriores.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5335, 1, '1.2.3.1.1.02.01.00.00.00', 'EQUIPAMENTOS DE PROCESSAMENTO DE DADOS', 'Registra os equipamentos de centro de processamento de dados/data center, como servidores e equipamentos de armazenamento e rede.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5336, 1, '1.2.3.1.1.02.02.00.00.00', 'EQUIPAMENTOS DE TECNOLOGIA DA INFORMAÇÃO', 'Registra os equipamentos relacionados com tecnologia da informação, como estações de trabalho, impressoras e periféricos.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5337, 1, '1.2.3.1.1.02.03.00.00.00', 'SISTEMAS APLICATIVOS - SOFTWARES', 'Registra o valor dos softwares adquiridos ou desenvolvidos pela empresa que seja inerente e essencial para o funcionamento do computador e que não sejam classificados juntos a esse.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5338, 1, '1.2.3.1.1.03.01.00.00.00', 'APARELHOS E UTENSÍLIOS DOMÉSTICOS', 'Registra os objetos ou peças de uso caseiro ou necessários a vida familiar.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5339, 1, '1.2.3.1.1.03.02.00.00.00', 'MÁQUINAS E UTENSÍLIOS DE ESCRITÓRIO', 'Registra as máquinas e utensílios de escritório.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5340, 1, '1.2.3.1.1.03.03.00.00.00', 'MOBILIÁRIO EM GERAL', 'Registra os valores relativos aos bens móveis, de caráter geral, em uso na unidade, não classificados em contas anteriores.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5341, 1, '1.2.3.1.1.03.04.00.00.00', 'UTENSÍLIOS EM GERAL', 'Registra os valores relativos a utensílios, de caráter geral, em uso na unidade, não classificados em contas anteriores.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5342, 1, '1.2.3.1.1.04.01.00.00.00', 'BANDEIRAS, FLÂMULAS E INSÍGNIAS', 'Registra os valores relativos a bandeiras, flâmulas e insígnias, geralmente utilizadas como distintivo da nação e de corporações, pequenas chamas, adornos, sinal distintivo, emblemas, estandartes e outros símbolos.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5343, 1, '3.1.1.1.1.01.23.00.00.00', 'FÉRIAS - ABONO PECUNIÁRIO', 'Registra o valor da despesa com férias - abono pecuniário', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5344, 1, '1.2.3.1.1.04.02.00.00.00', 'COLEÇÕES E MATERIAIS BIBLIOGRÁFICOS', 'Registra os valores relativos aos objetos e materiais bibliográficos destinados a reunir, geralmente, para formação de bibliotecas de uso da unidade ou cumprir objetivos dessa.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5345, 1, '1.2.3.1.1.04.03.00.00.00', 'DISCOTECAS E FILMOTECAS', 'Registra os valores relativos a discos, CDs e coleções de fitas gravadas com músicas e fitas cinematográficas de caráter educativo, científico e informativo.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5346, 1, '1.2.3.1.1.04.04.00.00.00', 'INSTRUMENTOS MUSICAIS E ARTÍSTICOS', 'Registra os valores relativos aos instrumentos musicais e artísticos.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5347, 1, '1.2.3.1.1.04.05.00.00.00', 'EQUIPAMENTOS PARA ÁUDIO, VÍDEO E FOTO', 'Registra os valores de equipamentos de áudio, vídeo e foto.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5348, 1, '1.2.3.1.1.04.06.00.00.00', 'OBRAS DE ARTE E PEÇAS PARA EXPOSIÇÃO', 'Registra os valores relativos a obras e objetos de arte e de peças para decoração ou exposição em geral em museus, galerias, halls, prédios públicos e outros, desde que se destinem a manutenção de sua atividade, caso contrário, deve ser classificado como investimentos.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5349, 1, '1.2.3.1.1.04.99.00.00.00', 'OUTROS MATERIAIS CULTURAIS, EDUCACIONAIS E DE COMUNICAÇÃO', 'Registra os valores referentes a materiais culturais, educacionais e de comunicação não classificados em contas anteriores.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5350, 1, '1.2.3.1.1.05.01.00.00.00', 'VEÍCULOS EM GERAL', 'Registra os veículos de diversos tipos, não motorizados, para os quais não tenham sido criadas contas específicas.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5351, 1, '1.2.3.1.1.05.02.00.00.00', 'VEÍCULOS FERROVIÁRIOS', 'Registra os veículos destinados ao tráfego por via férrea e para usos diversos.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5352, 1, '1.2.3.1.1.05.03.00.00.00', 'VEÍCULOS DE TRAÇÃO MECÂNICA', 'Registra os veículos de tração mecânica.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5353, 1, '1.2.3.1.1.05.04.00.00.00', 'CARROS DE COMBATE', 'Registra os carros de combate, tais como carro-tanque, auto-choque e assemelhados.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5354, 1, '1.2.3.2.1.05.05.00.00.00', 'VIADUTOS', 'Registra os valores de viadutos que foram construídos utilizando-se recursos públicos e que estejam sob controle ou administração da unidade.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5355, 1, '1.2.3.1.1.05.05.00.00.00', 'AERONAVES', 'Registra os veículos destinados ao tráfego aéreo, geralmente de uso comercial, no transporte de passageiros e cargas ou para treinamento, defesa e ataque militar, bem como outras atividades.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5356, 1, '1.2.3.1.1.05.06.00.00.00', 'EMBARCAÇÕES', 'Registra as embarcações adquiridas ou construídas e destinadas a navegação por vias marítimas, fluviais e outras vias navegáveis.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5357, 1, '1.2.3.1.1.06.00.00.00.00', 'PEÇAS E CONJUNTOS DE REPOSIÇÃO', 'Registra o valor da aquisição ou incorporação de peças e conjuntos de reposição destinados a substituição em máquinas e equipamentos, aeronaves e embarcações, bens de segurança e socorro, entre outros.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5358, 1, '1.2.3.1.1.07.01.00.00.00', 'BENS MÓVEIS EM ELABORACÃO', 'Registra os valores relativos a todos os gastos ocorridos com bens móveis em fase de elaboração e acabamento.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5359, 1, '1.2.3.1.1.07.02.00.00.00', 'IMPORTAÇÕES EM ANDAMENTO', 'Registra os valores relativos a todos os gastos com importações em andamento de equipamentos, máquinas, aparelhos e outros bens móveis.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5360, 1, '1.2.3.1.1.07.04.00.00.00', 'ALMOXARIFADO DE MATERIAIS A SEREM APLICADOS EM BENS EM ANDAMENTO', 'Registra todos os materiais e bens da empresa destinados a aplicação na elaboração de bens móveis em andamento.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5361, 1, '1.2.3.1.1.08.01.00.00.00', 'ESTOQUE INTERNO', 'Registra os valores dos bens móveis adquiridos e estocados em almoxarifado, destinados a atender as necessidades dos órgãos adquirentes.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5362, 1, '1.2.3.1.1.08.03.00.00.00', 'BENS MÓVEIS A REPARAR', 'Registra os valores dos bens móveis que necessitam de reparos ou reformas, estocados em almoxarifado.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5363, 1, '1.2.3.1.1.08.05.00.00.00', 'BENS MÓVEIS INSERVÍVEIS', 'Registra os valores dos bens móveis inservíveis em almoxarifado, que dependem de parecer da comissão e homologação da autoridade competente para serem descarregados.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5364, 1, '1.2.3.1.1.09.00.00.00.00', 'ARMAMENTOS', 'Registra os valores de armas que constituem objetos de defesa ou preparativos de guerra.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5365, 1, '1.2.3.1.1.10.00.00.00.00', 'SEMOVENTES', 'Registra os valores relativos aos animais destinados a produção, reprodução, engorda e aos serviços utilitários em geral.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5366, 1, '1.2.3.1.1.99.01.00.00.00', 'BENS MÓVEIS A ALIENAR', 'Representa os registros dos valores relativos aos bens móveis que, por algum motivo, foram destinados a alienação, mediante venda, permuta ou doação.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5367, 1, '1.2.3.1.1.99.02.00.00.00', 'BENS EM PODER DE OUTRA UNIDADE OU TERCEIROS ', 'Registra os valores de bens móveis de propriedade da unidade cedente, entregues a outra unidade ou terceiros por meio de convênio, comodato ou outras formas de empréstimo, distribuição ou transferência.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5368, 1, '1.2.3.1.1.99.08.00.00.00', 'BENS MÓVEIS A CLASSIFICAR', 'Registra os bens móveis pendentes de classificação e de identificação.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5369, 1, '1.2.3.1.1.99.99.00.00.00', 'OUTROS BENS MÓVEIS', 'Registra o valor da aquisição ou incorporação dos outros bens móveis não podem classificados nas contas anteriores.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5370, 1, '1.2.3.2.1.01.01.00.00.00', 'IMÓVEIS RESIDENCIAIS', 'Registra os valores relativos aos imóveis residenciais dos estados ou municípios, como apartamentos; casas; residenciais; conjuntos. Os imóveis funcionais, os próprios residenciais e as vilas militares devem ser registrados nessa conta.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5371, 1, '1.2.3.2.1.01.02.00.00.00', 'IMÓVEIS COMERCIAIS', 'Registra os valores relativos aos imóveis comerciais dos estados ou municípios, como conjuntos; salas; e lojas.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5372, 1, '1.2.3.2.1.01.03.00.00.00', 'EDIFÍCIOS', 'Registra os valores relativos aos seguintes imóveis dos estados ou municípios nas seguintes categorias: edifícios, prédios; conventos.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5373, 1, '1.2.3.2.1.01.04.00.00.00', 'TERRENOS/GLEBAS', 'Registra os valores relativos aos seguintes imóveis dos estados e municípios nas seguintes categorias: terrenos e glebas.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5374, 1, '1.2.3.2.1.01.05.00.00.00', 'ARMAZÉNS/GALPÕES', 'Registra os valores relativos aos seguintes imóveis dos estados e municípios nas seguintes categorias: armazéns e galpões.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5375, 1, '1.2.3.2.1.01.06.00.00.00', 'AQUARTELAMENTOS', 'Registra os valores relativos aos seguintes imóveis da união, estados e municípios nas seguintes categorias: bases; quartéis; fortes.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5376, 1, '1.2.3.2.1.01.07.00.00.00', 'AEROPORTOS/ESTAÇÕES/AERÓDROMOS', 'Registra os valores relativos aos seguintes imóveis dos estados e municípios nas seguintes categorias: aeródromo; aeroporto; estação.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5377, 1, '1.2.3.2.1.01.08.00.00.00', 'IMÓVEIS DE USO EDUCACIONAL', 'Registra os valores relativos aos seguintes imóveis dos estados e municípios nas seguintes categorias: escolas; faculdades; universidades; bibliotecas.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5378, 1, '1.2.3.2.1.01.09.00.00.00', 'REPRESAS/AÇUDES', 'Registra os valores relativos aos seguintes imóveis dos estados e municípios nas seguintes categorias: açudes; represas.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5379, 1, '3.1.1.1.1.01.24.00.00.00', 'FÉRIAS - ABONO CONSTITUCIONAL', 'Registra o valor da despesa com férias - abono constitucional', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5380, 1, '1.2.3.2.1.01.10.00.00.00', 'FAZENDAS, PARQUES E RESERVAS', 'Registra os valores relativos aos seguintes imóveis dos estados e municípios nas seguintes categorias: fazendas; parques; reservas.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5381, 1, '1.2.3.2.1.01.11.00.00.00', 'IMÓVEIS DE USO RECREATIVO', 'Registra os valores relativos aos seguintes imóveis dos estados e municípios que se enquadrem nas seguintes categorias: clubes; estádios; teatros.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5382, 1, '1.2.3.2.1.01.12.00.00.00', 'FARÓIS', 'Registra os valores relativos aos seguintes imóveis dos estados e municípios que se enquadrem na seguinte categoria: faróis (faroletes). Os instrumentos de auxílio a navegação aérea também devem ser registrados nesta conta.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5383, 1, '1.2.3.2.1.01.13.00.00.00', 'MUSEUS/PALÁCIOS', 'Registra os valores relativos aos seguintes imóveis dos estados e municípios: museus; palácios.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5384, 1, '1.2.3.2.1.01.14.00.00.00', 'LABORATÓRIOS/OBSERVATÓRIOS', 'Registra os valores relativos aos seguintes imóveis dos estados e municípios que se enquadrem nas seguintes categorias: laboratórios; observatórios.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5385, 1, '1.2.3.2.1.01.15.00.00.00', 'HOSPITAIS E UNIDADES DE SAÚDE', 'Registra os valores relativos aos seguintes imóveis dos estados e municípios que se enquadrem na seguinte categoria: hospitais e unidades de saúde.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5386, 1, '1.2.3.2.1.01.16.00.00.00', 'HOTÉIS', 'Registra os valores relativos aos seguintes imóveis dos estados e municípios que se enquadrem na seguinte categoria: hotéis.', 1, true, 2, 'P');
