insert into contabilidade.planocontadetalhe values (5388, 1, '1.2.3.2.1.01.18.00.00.00', 'PORTOS/ESTALEIROS', 'Registra os valores relativos aos seguintes imóveis dos estados e municípios: estaleiros; portos.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5389, 1, '1.2.3.2.1.01.19.00.00.00', 'COMPLEXOS/FÁBRICAS/USINAS', 'Registra os valores relativos aos seguintes imóveis dos estados e municípios: fábricas; usinas; complexos.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5390, 1, '1.2.3.2.1.01.20.00.00.00', 'CEMITÉRIOS', 'Registra os valores relativos aos seguintes imóveis dos estados e municípios: cemitérios.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5391, 1, '1.2.3.2.1.01.21.00.00.00', 'ESTACIONAMENTOS E GARAGENS', 'Registra os valores relativos aos seguintes imóveis dos estados e municípios que se enquadrem na seguinte categoria: estacionamentos. Também devem ser registrados nesta conta as garagens.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5392, 1, '1.2.3.2.1.01.22.00.00.00', 'POSTOS DE FISCALIZAÇÃO', 'Registra os valores relativos aos seguintes imóveis dos estados e municípios: postos policiais. Também devem ser registrados nessa conta os demais postos de fiscalização.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5393, 1, '1.2.3.2.1.01.98.00.00.00', 'OUTROS BENS IMÓVEIS DE USO ESPECIAL', 'Registra os valores relativos aos seguintes imóveis dos estados e municípios que não se enquadrem em nenhuma outra categoria.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5394, 1, '1.2.3.2.1.04.01.00.00.00', 'EDIFÍCIOS', 'Registra os valores patrimoniais relativos aos imóveis dominicais união, estados e municípios que se enquadrem nas seguintes categorias: edifícios; prédios; conventos.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5395, 1, '1.2.3.2.1.04.02.00.00.00', 'APARTAMENTOS', 'Registra os valores patrimoniais relativos aos imóveis dominicais união, estados e municípios que se enquadrem na seguinte categoria: apartamentos.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5396, 1, '1.2.3.2.1.99.01.00.00.00', 'BENS IMÓVEIS LOCADOS PARA TERCEIROS', 'Registra os bens imóveis locados para terceiros.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5397, 1, '1.2.3.2.1.04.03.00.00.00', 'ARMAZÉNS ', 'Registra os valores patrimoniais relativos aos imóveis dominicais união, estados e municípios que se enquadrem na seguinte categoria: armazéns.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5398, 1, '1.2.3.2.1.04.04.00.00.00', 'CASAS', 'Registra os valores patrimoniais relativos aos imóveis dominicais união, estados e municípios que se enquadrem na seguinte categoria: casas.', 1, true, 2, 'P');
