insert into contabilidade.planocontadetalhe values (5400, 1, '1.2.3.2.1.04.06.00.00.00', 'EDIFÍCIOS', 'Registra os valores patrimoniais relativos aos imóveis dominicais união, estados e municípios que se enquadrem na seguinte categoria: edifícios.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5401, 1, '1.2.3.2.1.04.07.00.00.00', 'GARAGENS E ESTACIONAMENTOS', 'Registra os valores patrimoniais relativos aos imóveis dominicais união, estados e municípios que se enquadrem na seguinte categoria: garagens e estacionamentos.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5402, 1, '1.2.3.2.1.04.08.00.00.00', 'FAZENDAS ', 'Registra os valores patrimoniais relativos aos imóveis dominicais união, estados e municípios que se enquadrem na seguinte categoria: fazendas.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5403, 1, '1.2.3.2.1.04.09.00.00.00', 'GALPÕES', 'Registra os valores patrimoniais relativos aos imóveis dominicais união, estados e municípios que se enquadrem na seguinte categoria: galpões.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5404, 1, '1.2.3.2.1.04.10.00.00.00', 'GLEBAS', 'Registra os valores patrimoniais relativos aos imóveis dominicais união, estados e municípios que se enquadrem na seguinte categoria: glebas.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5405, 1, '1.2.3.2.1.04.11.00.00.00', 'LOJAS ', 'Registra os valores patrimoniais relativos aos imóveis dominicais união, estados e municípios que se enquadrem na seguinte categoria: lojas.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5406, 1, '1.2.3.2.1.04.12.00.00.00', 'SALAS', 'Registra os valores patrimoniais relativos aos imóveis dominicais união, estados e municípios que se enquadrem na seguinte categoria: salas.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5407, 1, '1.2.3.2.1.04.13.00.00.00', 'TERRENOS ', 'Registra os valores patrimoniais relativos aos imóveis dominicais união, estados e municípios que se enquadrem na seguinte categoria: terrenos.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5408, 1, '1.2.3.2.1.04.14.00.00.00', 'LOTES', 'Registra os valores patrimoniais relativos aos imóveis dominicais união, estados e municípios que se enquadrem na seguinte categoria: lotes.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5409, 1, '1.2.3.2.1.04.15.00.00.00', 'LOTES INDUSTRIAIS', 'Registra os valores patrimoniais relativos aos imóveis dominicais união, estados e municípios que se enquadrem na seguinte categoria: lotes industriais.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5410, 1, '1.2.3.2.1.04.16.00.00.00', 'GLEBAS URBANAS', 'Registra os valores patrimoniais relativos aos imóveis dominicais união, estados e municípios que se enquadrem na seguinte categoria: glebas urbanas.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5411, 1, '1.2.3.2.1.04.17.00.00.00', 'GLEBAS URBANIZADAS', 'Registra os valores patrimoniais relativos aos imóveis dominicais união, estados e municípios que se enquadrem na seguinte categoria: glebas urbanizadas.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5412, 1, '1.2.3.2.1.04.18.00.00.00', 'GLEBAS RURAIS', 'Registra os valores patrimoniais relativos aos imóveis dominicais união, estados e municípios que se enquadrem na seguinte categoria: glebas rurais.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5413, 1, '1.2.3.2.1.04.99.00.00.00', 'OUTROS BENS DOMINICAIS', 'Registra os valores patrimoniais relativos aos imóveis dominicais união, estados e municípios que não se enquadrem em outras categorias.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5414, 1, '1.2.3.2.1.05.01.00.00.00', 'RUAS', 'Registra os valores de ruas que foram construídas utilizando-se recursos públicos e que estejam sob controle ou administração da unidade.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5415, 1, '1.2.3.2.1.05.02.00.00.00', 'PRAÇAS', 'Registra os valores de praças que foram construídas utilizando-se recursos públicos e que estejam sob controle ou administração da unidade.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5416, 1, '1.2.3.2.1.05.03.00.00.00', 'ESTRADAS', 'Registra os valores de estradas que foram construídas utilizando-se recursos públicos e que estejam sob controle ou administração da unidade.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5417, 1, '1.2.3.2.1.05.04.00.00.00', 'PONTES', 'Registra os valores de pontes que foram construídos utilizando-se recursos públicos e que estejam sob controle ou administração da unidade.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5418, 1, '1.2.3.2.1.05.06.00.00.00', 'SISTEMAS DE ESGOTO E/OU DE ABASTECIMENTO DE ÁGUA', 'Registra os valores de sistemas de esgoto e/ou de abastecimento de água que foram construídos utilizando-se recursos públicos e que estejam sob controle ou administração da unidade.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5419, 1, '1.2.3.2.1.05.07.00.00.00', 'SISTEMAS DE ABASTECIMETNO DE ENERGIA', 'Registra os valores de sistemas de abastecimento de energia que foram construídos utilizando-se recursos públicos e que estejam sob controle ou administração da unidade.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5420, 1, '1.2.3.2.1.05.08.00.00.00', 'REDES DE TELECOMUNICAÇÕES', 'Registra os valores de redes de telecomunicações que foram construídos utilizando-se recursos públicos e que estejam sob controle ou administração da unidade.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5421, 1, '1.2.3.2.1.05.09.00.00.00', 'BENS DO PATRIMONIO CULTURAL', 'Bens com significancia histórica, cultural ou ambiental tais como monumentos e prédios históricos, sítios arqueológicos, área de conservação e reservas naturais e obras de arte, quando passíveis de mensuração e avaliação.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5422, 1, '1.2.3.2.1.05.99.00.00.00', 'OUTROS BENS DE USO COMUM DO POVO', 'Registra os valores bens de uso comum, não classificados anteriormente neste plano de contas, que foram adquiridos, produzidos ou construídos utilizando-se recursos públicos e que estejam sob controle ou administração da unidade.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5423, 1, '1.2.3.2.1.06.01.00.00.00', 'OBRAS EM ANDAMENTO', 'Registra os valores pertinentes a obras, desde sua construção até o término da mesma.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5424, 1, '1.2.3.2.1.06.05.00.00.00', 'ESTUDOS E PROJETOS', 'Registra os valores relativos a estudos e projetos, englobando limpeza do terreno, serviços topográficos, sondagens de reconhecimento, terraplenagem, drenagens, instalações provisórias como galpões, instalações elétricas e hidráulicas, utilizadas durante as obras.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5425, 1, '1.2.3.2.1.07.00.00.00.00', 'INSTALAÇÕES', 'Registra equipamentos, materiais e custo de implantação de instalações que, não obstante integradas aos edifícios, devem ser segregadas das obras civis, como, por exemplo, as instalações elétricas, hidráulicas, sanitárias, de vapor, de ar comprimido, frigoríficas, contra incêndio, de comunicações, de climatização, para combustíveis, gases, de antipoluição, para cozinha, dentre outros. E também aplicável a construção de trechos ferroviários.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5426, 1, '1.2.3.2.1.08.00.00.00.00', 'BENFEITORIAS EM PROPRIEDADE DE TERCEIROS', 'Registra construções em terrenos arrendados de terceiros e instalações e outras benfeitorias em prédios alugados. São considerados somente os gastos com construção e instalação que se incorporam ao imóvel e revertem ao proprietário do imóvel ao final da locação.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5427, 1, '1.2.3.2.1.99.02.00.00.00', 'IMÓVEIS EM PODER DE TERCEIROS', 'Registra os imóveis concedidos a terceiros a título de empréstimo gratuito com prazo de devolução convencionado.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5428, 1, '1.2.3.2.1.99.03.00.00.00', 'MATERIAIS TEMPORARIAMENTE SEPARADOS DE IMÓVEIS ', 'Registra os materiais provisoriamente separados de um imóvel, para nele se reempregarem.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5429, 1, '1.2.3.2.1.99.05.00.00.00', 'BENS IMÓVEIS A CLASSIFICAR', 'Registra os bens imóveis, cuja classificação esteja pendente por algum motivo, geralmente por falta de identificação ou pendência de legalização ou registro.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5430, 1, '1.2.3.2.1.99.06.00.00.00', 'BENS IMÓVEIS A ALIENAR', 'Registra os valores relativos aos bens imóveis separados para alienação, quando considerados desnecessários, inservíveis ou por decisão administrativa da unidade.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5431, 1, '1.2.3.2.1.99.99.00.00.00', 'OUTROS BENS IMÓVEIS', 'Registra os valores relativos a outros bens imóveis, para os quais não tenham sido criadas contas próprias ou específicas neste plano de contas.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5432, 1, '3.1.1.1.1.01.25.00.00.00', 'LICENÇA-PRÊMIO', 'Registra o valor da despesa com licença-prêmio.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5433, 1, '1.2.4.1.1.01.00.00.00.00', 'SOFTWARES', 'Registra os valores dos softwares pertencentes ao órgão, englobando os valores referentes à construção, implementação e instalação do programa.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5434, 1, '1.2.4.1.1.02.00.00.00.00', 'SOFTWARES EM DESENVOLVIMENTO', 'Registra os valores apropriados na fase de desenvolvimento do software, de acordo com a nota técnica específica para o tema.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5435, 1, '1.2.4.2.1.01.00.00.00.00', 'MARCAS E PATENTES INDUSTRIAIS', 'Registra os valores relativos a bens intangíveis, englobando os gastos com registro de marca, nome, invenções próprias, além de desembolsos a terceiros por contratos de uso de marcas, patentes ou processos de fábricação (tecnologia).', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5436, 1, '1.2.4.2.1.02.00.00.00.00', 'CONCESSÃO DE DIREITO DE USO DE COMUNICAÇÃO', 'Registra os valores relativos a bens intangíveis representados pela concessão de direito de uso de comunicação e divulgação.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5437, 1, '1.2.4.2.1.03.00.00.00.00', 'DIREITOS AUTORAIS ', 'Registra os valores relativos aos direitos autorais adquiridos pela entidade.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5438, 1, '1.2.4.2.1.04.00.00.00.00', 'DIREITOS SOBRE RECURSOS NATURAIS', 'Registra os valores relativos aos direitos obtidos por legislação e/ou por compras de direitos de reservas ou de exploração de recursos naturais, tais como jazidas e outros.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5439, 1, '1.2.4.2.1.05.00.00.00.00', 'ADIANTAMENTO PARA TRANFERÊNCIA DE TECNOLOGIA', 'Registra todos os adiantamentos a fornecedores vinculados a um contrato de transferencia de tecnologia. Representam pagamentos por conta de um valor previamente contratado.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5440, 1, '1.2.4.2.1.99.00.00.00.00', 'OUTROS DIREITOS - BENS INTANGÍVEIS', 'Registra os valores relativos a outros direitos, classificados como bens intangíveis, cuja classificação não esteja definida em contas específicas.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5441, 1, '3.1.1.1.1.01.26.00.00.00', 'LICENÇA CAPACITAÇÃO', 'Registra o valor da despesa com licença capacitação.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5442, 1, '3.1.1.1.1.01.07.00.00.00', 'ADICIONAL DE ATIVIDADES PENOSAS', 'Registra o valor da despesa com adicional de atividades penosas.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5443, 1, '3.1.1.1.1.01.27.00.00.00', 'ADIANTAMENTO PECUNIÁRIO', 'Registra o valor da despesa com adiantamento pecuniário.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5444, 1, '2.1.2.1.1.01.02.00.00.00', '(-) DESÁGIO DE TÍTULOS', 'Registra os valores relativos a deságio ocorridos em títulos.', 1, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (5445, 1, '2.1.2.1.3.01.02.00.00.00', '(-) DESÁGIO DE TÍTULOS', 'Registra os valores relativos a deságio ocorridos em títulos.', 1, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (5446, 1, '2.1.2.1.4.01.02.00.00.00', '(-) DESÁGIO DE TÍTULOS', 'Registra os valores relativos a deságio ocorridos em títulos.', 1, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (5447, 1, '2.1.2.1.5.01.02.00.00.00', '(-) DESÁGIO DE TÍTULOS', 'Registra os valores relativos a deságio ocorridos em títulos.', 1, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (5448, 1, '2.1.2.8.1.01.00.00.00.00', '(-) ENCARGOS PREFIXADOS DE EMPRÉSTIMOS INTERNOS', 'Registra o valor dos encargos financeiros pré-estabelecidos em valores prefixados, referentes a empréstimos internos.', 1, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (5449, 1, '2.1.2.8.1.02.00.00.00.00', '(-) ENCARGOS PREFIXADOS DE FINANCIAMENTOS INTERNOS', 'Registra o valor dos encargos financeiros pré-estabelecidos em valores prefixados, referentes a financiamentos internos.', 1, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (5450, 1, '2.1.2.8.3.01.00.00.00.00', '(-) ENCARGOS PREFIXADOS DE EMPRÉSTIMOS INTERNOS', 'Registra o valor dos encargos financeiros pré-estabelecidos em valores prefixados, referentes a empréstimos internos.', 1, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (5451, 1, '2.1.2.8.3.02.00.00.00.00', '(-) ENCARGOS PREFIXADOS DE FINANCIAMENTOS INTERNOS', 'Registra o valor dos encargos financeiros pré-estabelecidos em valores prefixados, referentes a financiamentos internos.', 1, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (5452, 1, '2.1.2.8.4.01.00.00.00.00', '(-) ENCARGOS PREFIXADOS DE EMPRÉSTIMOS INTERNOS', 'Registra o valor dos encargos financeiros pré-estabelecidos em valores prefixados, referentes a empréstimos internos.', 1, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (5453, 1, '2.1.2.8.4.02.00.00.00.00', '(-) ENCARGOS PREFIXADOS DE FINANCIAMENTOS INTERNOS', 'Registra o valor dos encargos financeiros pré-estabelecidos em valores prefixados, referentes a financiamentos internos.', 1, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (5454, 1, '2.1.2.9.1.01.00.00.00.00', '(-) ENCARGOS PREFIXADOS DE EMPRÉSTIMOS EXTERNOS', 'Registra o valor dos encargos financeiros pré-estabelecidos em valores prefixados, referentes a empréstimos externos.', 1, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (5455, 1, '2.1.2.9.1.02.00.00.00.00', '(-) ENCARGOS PREFIXADOS DE FINANCIAMENTOS EXTERNOS', 'Registra o valor dos encargos financeiros pré-estabelecidos em valores prefixados, referentes a financiamentos externos.', 1, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (5456, 1, '2.1.8.4.1.97.00.00.00.00', '(-) DESAGIO NA EMISSAO DE DEBENTURES', 'Registra os valores de deságio na emissão de debentures, que são os valores recebidos inferiores ao valor de resgate desses títulos na data do próprio recebimento ou do valor formalmente atribuído as debentures.', 1, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (5457, 1, '2.1.8.4.1.98.00.00.00.00', '(-) CUSTO DA TRANSAÇÃO A AMORTIZAR', 'Registra os custos da transação a amortizar, que são apenas os custos incorridos e diretamente atribuíveis as atividades necessárias exclusivamente a consecução da transação. Por exemplo: taxas e comissões. Entretanto, não incluem despesas financeiras, custos internos administrativos ou custo de carregamento.', 1, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (5458, 1, '3.1.1.1.1.01.08.00.00.00', 'INCENTIVO Á QUALIFICAÇÃO', 'Registra o valor da despesa com incentivo á qualificação.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5459, 1, '3.1.1.1.1.01.28.00.00.00', 'REPRESENTAÇÃO MENSAL', 'Registra o valor da despesa com representação mensal.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5460, 1, '2.2.2.1.1.01.02.00.00.00', '(-) DESÁGIO DE TÍTULOS', 'Registra os valores relativos a deságio ocorridos em títulos.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5461, 1, '2.2.2.1.3.01.02.00.00.00', '(-) DESÁGIO DE TÍTULOS', 'Registra os valores relativos a deságio ocorridos em títulos.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5462, 1, '2.2.2.8.1.01.00.00.00.00', '(-) ENCARGOS PREFIXADOS DE EMPRÉSTIMOS INTERNOS', 'Registra o valor dos encargos financeiros pré-estabelecidos em valores prefixados, referentes a empréstimos internos.', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (5463, 1, '2.2.2.8.1.02.00.00.00.00', '(-) ENCARGOS PREFIXADOS DE FINANCIAMENTOS INTERNOS', 'Registra o valor dos encargos financeiros pré-estabelecidos em valores prefixados, referentes a financiamentos internos.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5464, 1, '2.2.2.9.1.01.00.00.00.00', '(-) ENCARGOS PREFIXADOS DE EMPRÉSTIMOS EXTERNOS', 'Registra o valor dos encargos financeiros pré-estabelecidos em valores prefixados, referentes a empréstimos externos.', 1, true, 2, 'F');
insert into contabilidade.planocontadetalhe values (5465, 1, '2.2.2.9.1.02.00.00.00.00', '(-) ENCARGOS PREFIXADOS DE FINANCIAMENTOS EXTERNOS', 'Registra o valor dos encargos financeiros pré-estabelecidos em valores prefixados, referentes a financiamentos externos.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5466, 1, '2.2.7.2.1.01.02.00.00.00', '(-) CONTRIBUIÇÕES DO ENTE PARA O PLANO FINANCEIRO DO RPPS', 'Registra, de acordo com o resultado da avaliação atuarial, o valor presente das contribuições (normal, suplementar ou aportes periódicos) futuras do ente, por prazo de vigência indeterminado, para financiar os benefícios já em fase de pagamento.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5467, 1, '2.2.7.2.1.01.03.00.00.00', '(-) CONTRIBUIÇÕES DO APOSENTADO PARA O PLANO FINANCEIRO DO RPPS  ', 'Registra, de acordo com o resultado da avaliação atuarial, o valor presente das contribuições futuras dos inativos, por prazo de vigência indeterminado, para financiar os benefíciosjá em fase de pagamento.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5468, 1, '2.2.7.2.1.01.04.00.00.00', '(-) CONTRIBUIÇÕES DO PENSIONISTA PARA O PLANO FINANCEIRO DO RPPS              ', 'Registra, de acordo com o resultado da avaliação atuarial, o valor presente das contribuições futuras dos pensionistas, por prazo de vigência indeterminado, para financiar os benefícios já em fase de pagamento.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5469, 1, '2.2.7.2.1.01.05.00.00.00', '(-) COMPENSAÇÃO PREVIDENCIÁRIA DO PLANO FINANCEIRO DO RPPS       ', 'Registra, de acordo com o resultado da avaliação atuarial, o valor presente da compensação previdenciária conforme expressa o artigo 11, da Portaria MPS nº 403/2008.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5470, 1, '2.2.7.2.1.01.07.00.00.00', '(-) COBERTURA DE INSUFICIÊNCIA FINANCEIRA', 'Registra, de acordo com o resultado da avaliação atuarial, o valor presente das insuficiências financeiras futuras do plano financeiro considerando o §1º do artigo 2º da Lei nº 9.717/98.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5471, 1, '2.2.7.2.1.02.02.00.00.00', '(-) CONTRIBUIÇÕES DO ENTE PARA O PLANO FINANCEIRO DO RPPS ', 'Registra, de acordo com o resultado da avaliação atuarial, o valor presente das contribuições (normal, suplementar ou aportes periódicos) futuras do ente, incidentes sobre as remunerações da geração atual.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5472, 1, '2.2.7.2.1.02.03.00.00.00', '(-) CONTRIBUIÇÕES DO ATIVO PARA O PLANO FINANCEIRO DO RPPS   ', 'Registra, de acordo com o resultado da avaliação atuarial, o somatório do valor presente das contribuições futuras dos servidores ativos, incidentes sobre as remunerações da geração atual.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5473, 1, '2.2.7.2.1.02.04.00.00.00', '(-) COMPENSAÇÃO PREVIDENCIÁRIA DO PLANO FINANCEIRO DO RPPS      ', 'Registra, de acordo com o resultado da avaliação atuarial, o valor presente da compensação previdenciária conforme expressa o artigo 11, da Portaria MPS nº 403/2008.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5474, 1, '2.2.7.2.1.02.06.00.00.00', '(-) COBERTURA DE INSUFICIÊNCIA FINANCEIRA  ', 'Registra, de acordo com o resultado da avaliação atuarial, o valor presente das insuficiências financeiras futuras do plano financeiro, considerando o §1º do artigo 2º da Lei nº 9.717/98.', 1, true, 2, 'P');
