insert into contabilidade.planocontadetalhe values (5477, 1, '2.2.7.2.1.03.04.00.00.00', '(-) CONTRIBUIÇÕES DO PENSIONISTA PARA O PLANO PREVIDENCIÁRIO DO RPPS           ', 'Registra, de acordo com o resultado da avaliação atuarial, o valor presente das contribuições futuras dos pensionistas, por prazo de vigência indeterminado, para financiar os benefícios já em fase de pagamento.', 1, true, 2, 'P');
