insert into contabilidade.planocontadetalhe values (5483, 1, '2.2.7.2.1.04.06.00.00.00', '(-) APORTES PARA COBERTURA DO DÉFICIT ATUARIAL - PLANO DE AMORTIZAÇÃO', 'Registra o valor presente dos aportes para cobertura do déficit atuarial, conforme plano de amortização estabelecido em lei.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (5484, 1, '3.1.1.1.1.01.30.00.00.00', 'ADICIONAL - TETO PARLAMENTAR', 'Registra o valor da despesa com adicional - teto parlamentar.', 1, true, 2, 'N');
