insert into contabilidade.planocontadetalhe values (5776, 1, '3.3.1.1.1.53.00.00.00.00', 'MATERIAL METEOROLÓGICO', 'Registra as Variações Patrimoniais Diminutivas provenientes da utilização de material meteorológico, tais como: radiossondas, balão de látex, etc.', 1, true, 2, 'N');
