insert into contabilidade.planocontadetalhe values (5779, 1, '3.3.1.1.1.56.00.00.00.00', 'MATERIAL DE MARCAÇÃO DA FAUNA SILVESTRE', 'Registra as Variações Patrimoniais Diminutivas provenientes da utilização de Material de Marcação da Fauna Silvestre.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5780, 1, '3.3.1.1.1.57.00.00.00.00', 'MATERIAL DE CONSUMO - REPARTIÇÕES NO EXTERIOR', 'Registra as Variações Patrimoniais Diminutivas provenientes da utilização de Material de Consumo - repartições no exterior.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5781, 1, '3.3.1.1.1.58.00.00.00.00', 'SOBRESSALENTES PARA MÁQUINAS E EQUP. PARA PRODUÇÃO INDUSTRIAL', 'Registra as Variações Patrimoniais Diminutivas provenientes de Sobressalentes para Máquinas e Equipamentos para Produção Industrial.', 1, true, 2, 'N');
