insert into contabilidade.planocontadetalhe values (5783, 1, '3.3.1.1.1.71.00.00.00.00', 'MATERIAIS PARA CONSERVAÇÃO E MANUTENÇÃO DE BENS DE USO COMUM DO POVO', 'Registra as Variações Patrimoniais Diminutivas provenientes de Materiais para Conservação e Manutenção de Bens de uso Comum do Povo.', 1, true, 2, 'N');
