insert into contabilidade.planocontadetalhe values (5786, 1, '3.3.1.2.1.01.00.00.00.00', 'MERCADORIAS DOADAS', 'Registra as variações patrimoniais diminutivas provenientes da utilização de produtos adquiridos com a finalidade de doação.', 1, true, 2, 'N');
