insert into contabilidade.planocontadetalhe values (5788, 1, '3.3.1.2.1.02.00.00.00.00', 'MATERIAL DESTINADO À ASSISTÊNCIA SOCIAL', 'Registra as variações patrimoniais diminutivas provenientes da utilização de mat.de saúde(farmacológico,odontológico,hospitalar,medicamentos,órtese e prótese),gêneros alimentícios, mater.de cama,mesa,copa,cozinha,limpeza,higienização, uniformes, tecidos, aviamentos,manut.mov/imov.,ferramentas e outros distinados a assistencia social.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5789, 1, '3.3.1.2.1.03.00.00.00.00', 'MATERIAL EDUCACIONAL E CULTURAL', 'Registra as variações patrimoniais diminutivas provenientes da utilização de material educacional,(material escolar, didático, técnico, material p/áudio, vídeo e foto)e material cultural (material religioso e esportivo).', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5790, 1, '3.3.1.2.1.04.00.00.00.00', 'MATERIAL DE ACONDICIONAMENTO E EMBALAGEM', 'Registra as variações patrimoniais diminutivas provenientes da utilização de material de acondicionamento e embalagem.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5791, 1, '3.3.1.2.1.05.00.00.00.00', 'MATERIAL PARA CERIMONIAL', 'Registra as variações patrimoniais diminutivas provenientes da aquisição de materiais oferecidos a autoridades a titulo de homenagem.', 1, true, 2, 'N');
