insert into contabilidade.planocontadetalhe values (5794, 1, '3.3.1.2.1.08.00.00.00.00', 'MATERIAL P/ IDENTIFICAÇÃO DE BENEFICIARIOS', 'Registra as Variações Patrimoniais Diminutivas provenientes da distribuição de Material para Identificação de Beneficiários.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5795, 1, '3.3.1.2.1.99.00.00.00.00', 'OUTROS MATERIAIS DE DISTRIBUIÇÃO GRATUITA', 'Registra as variações patrimoniais diminutivas provenientes da utilização de materiais para distribuição gratuita, não contemplados em rubricas especificas.', 1, true, 2, 'N');
