insert into contabilidade.planocontadetalhe values (5798, 1, '3.3.2.1.1.03.00.00.00.00', 'DIARIAS - COLABORADORES EVENTUAIS', 'Registra as variações patrimoniais diminutivas provenientes da utilização de diárias pagas a prestadores de serviços de caráter eventual, sem vínculo com a administração pública.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (7812, 1, '2.1.4.3.2.03.00.00.00.00', 'TRIBUTOS MUNICIPAIS RENEGOCIADOS', 'Registra os valores devidos pela unidade relativos a Tributos que foram renegociados.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (5799, 1, '3.3.2.1.1.04.00.00.00.00', 'DIARIAS A CONSELHEIROS', 'Registra as variações patrimoniais diminutivas provenientes da utilização de diárias a membros de órgãos de deliberação coletiva (conselhos).', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5800, 1, '3.3.2.2.1.01.00.00.00.00', 'CONSULTORIA E ASSESSORIA', 'Registra as variações patrimoniais diminutivas provenientes da utilização de serviços nas áreas de consultorias e assessorias técnicas, ou assemelhadas.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5801, 1, '3.3.2.2.1.02.00.00.00.00', 'PERICIAS', 'Registra as variações patrimoniais diminutivas proveniente da utilização de serviços de pericias realizadas por profissionais técnicos.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5802, 1, '3.3.2.2.1.03.00.00.00.00', 'AUDITORIA EXTERNA', 'Registra as variações patrimoniais diminutivas proveniente da utilização de serviços de auditoria.', 1, true, 2, 'N');
