insert into contabilidade.planocontadetalhe values (5804, 1, '3.3.2.2.1.05.00.00.00.00', 'SERVICOS MEDICOS E ODONTOLOGICOS', 'Registra as variações patrimoniais diminutivas proveniente da utilização de serviços médicos e odontológicos prestados por pessoa física, sem vínculo empregatício. Consultas - raio x - tratamento odontológico - e outros.', 1, true, 2, 'N');
