insert into contabilidade.planocontadetalhe values (5807, 1, '3.3.2.2.1.08.00.00.00.00', 'LIMPEZA E CONSERVAÇÃO', 'Registra as variações patrimoniais diminutivas proveniente da utilização de serviços de limpeza e conservação de bens imóveis. Dedetização - faxina - e outros.', 1, true, 2, 'N');
