insert into contabilidade.planocontadetalhe values (5810, 1, '3.3.2.2.1.11.00.00.00.00', 'MANUTENÇÃO E CONSERVAÇÃO', 'Registra as variações patrimoniais diminutivas proveniente da utilização de serviços de manutenção e conservação de bens moveis e imóveis.', 1, true, 2, 'N');
