insert into contabilidade.planocontadetalhe values (5812, 1, '3.3.2.2.1.13.00.00.00.00', 'COMISSOES E CORRETAGENS', 'Registra as variações patrimoniais diminutivas proveniente da utilização de serviços prestados por: corretores - despachantes - leiloeiros - e outros.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5813, 1, '3.3.2.3.1.03.00.00.00.00', 'AUDITORIA EXTERNA', 'Registra as variações patrimoniais diminutivas provenientes da utilização de serviços de auditoria externa.', 1, true, 2, 'N');
