insert into contabilidade.planocontadetalhe values (5815, 1, '3.3.2.2.1.15.00.00.00.00', 'SERVICOS TECNICOS PROFISSIONAIS', 'Registra as variações patrimoniais diminutivas proveniente da utilização de serviços prestados por profissionais técnicos, nas seguintes áreas: administração - advocacia - arquitetura - contabilidade - economia -engenharia - estatística e outras.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5816, 1, '3.3.2.2.1.16.00.00.00.00', 'ESTAGIARIOS', 'Registra as variações patrimoniais diminutivas proveniente da utilização de serviços prestados por estudantes na condição de estagiários ou monitores.', 1, true, 2, 'N');
