insert into contabilidade.planocontadetalhe values (5820, 1, '3.3.2.2.1.20.00.00.00.00', 'ARMAZENAGEM', 'Registra as variações patrimoniais diminutivas proveniente da utilização de serviços de aluguel de galpões, silos e outros locais destinados a armazenagem de mercadorias e produtos. Inclui, ainda, os dispêndios de garantia dos estoques armazenados.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5821, 1, '3.3.2.2.1.21.00.00.00.00', 'LOCAÇÕES', 'Compreende as variações patrimoniais diminutivas proveniente da utilização de serviços de locação de bens moveis e imóveis.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5822, 1, '3.3.2.2.1.22.00.00.00.00', 'FORNECIMENTO DE ALIMENTAÇÃO', 'Registra as variações patrimoniais diminutivas proveniente da utilização de refeições preparadas, inclusive lanches e similares.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5823, 1, '3.3.2.2.1.23.00.00.00.00', 'SERVICOS DE CARATER SECRETO OU RESERVADO', 'Registra as variações patrimoniais diminutivas proveniente da utilização de serviços de caráter sigiloso constantes em regulamento do órgão.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5845, 1, '3.3.2.3.1.12.00.00.00.00', 'SERVIÇOS DE TRANSPORTE', 'Registra as variações patrimoniais diminutivas provenientes da utilização de serviços de transporte de servidores, trabalhadores de uma entidade ou de mercadorias e produtos diversos.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5824, 1, '3.3.2.2.1.24.00.00.00.00', 'SERVICOS DE REABILITAÇÃO PROFISSIONAL', 'Registra as variações patrimoniais diminutivas proveniente da utilização de serviços de reabilitação profissional prestados por pessoa física sem vínculo empregatício, como objetivo de proporcionar aos incapacitados (parcial ou totalmente) os meios indicados para a reeducação e readaptação profissional e social, de modo que possam voltar a participar do mercado de trabalho. Ex.: contratação de profissional para ministrar curso profissionalizante.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5825, 1, '3.3.2.2.1.25.00.00.00.00', 'SERVICOS DE ASSISTENCIA SOCIAL', 'Registra as variações patrimoniais diminutivas proveniente da utilização de serviços de assistência social prestados por pessoa física sem vínculo empregatício a servidores, segurados carentes, abrigados, internados e a seus dependentes, tais como ajuda de custo supletiva, gêneros alimentícios, documentação, transporte e sepultamento.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5826, 1, '3.3.2.3.1.17.00.00.00.00', 'COMISSOES E CORRETAGENS', 'Registra as variações patrimoniais diminutivas provenientes da apropriação de valor referente a comissões e corretagens decorrentes de serviços prestados por empresas de intermediação e representação comercial.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5827, 1, '3.3.2.2.1.26.00.00.00.00', 'SERV. DE APOIO ADMIN., TECNICO E OPERACIONAL', 'Registra as variações patrimoniais diminutivas proveniente da utilização de serviços de natureza eventual prestados por pessoa física, tais como: assistência técnica - capina - jardinagem - operadores de maquinas e motoristas - recepcionistas - serviços auxiliares - e outros.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5828, 1, '3.3.2.2.1.27.00.00.00.00', 'SERV. DE CONSERV. E REBENEFIC. DE MERCADORIAS', 'Registra as variações patrimoniais diminutivas proveniente da utilização de serviços de natureza eventual prestados por pessoa física na conservação e rebeneficiamento de mercadorias.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5829, 1, '3.3.2.2.1.28.00.00.00.00', 'CONFECÇÃO DE MATERIAL DE ACONDIC. E EMBALAGEM', 'Registra as variações patrimoniais diminutivas proveniente da utilização de serviços prestados por pessoa física na confecção de: bolsas - caixas - mochilas - sacolas - e outros.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5830, 1, '3.3.2.2.1.29.00.00.00.00', 'CONFECÇÃO DE UNIFORMES, BANDEIRAS E FLAMULAS', 'Registra as variações patrimoniais diminutivas proveniente da utilização de serviços de costureiras, alfaiates e afins utilizados na confecção de uniformes, bandeiras, flamulas, brasões e estandartes.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5831, 1, '3.3.2.2.1.30.00.00.00.00', 'FRETES E TRANSPORTES DE ENCOMENDAS', 'Registra as variações patrimoniais diminutivas proveniente da utilização de serviços prestados por pessoa física em: fretes e carretos - remessa de encomendas - transporte de mercadorias e produtos - e outros.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5832, 1, '3.3.2.2.1.31.00.00.00.00', 'JETONS E GRATIFICAÇÕES A CONSELHEIROS', 'Registra as variações patrimoniais diminutivas proveniente da participação em órgãos de deliberações coletivas (conselhos).', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5833, 1, '3.3.2.2.1.34.00.00.00.00', 'SERVICOS DE AUDIO, VIDEO E FOTO', 'Registra as variações patrimoniais diminutivas proveniente da utilização de serviços de filmagens, gravações e fotografias, prestados por pessoa física.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5834, 1, '3.3.2.2.1.35.00.00.00.00', 'SERVICOS JUDICIARIOS', 'Registra as variações patrimoniais diminutivas proveniente da apropriação de custas processuais decorrentes de ações judiciais, diligencias (inclusive condução) salários e honorários dos avaliadores, peritos judiciais e serviços de cartório, quando a nota e emitida em nome do tabelião.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5835, 1, '3.3.2.2.1.36.00.00.00.00', 'SEGUROS EM GERAL', 'Registra as variações patrimoniais diminutivas proveniente da apropriação de prêmios pagos por seguros de qualquer natureza, inclusive cobertura de danos causados a pessoas ou bens de terceiros, prêmios de seguros de bens do estado ou de terceiros, seguro obrigatório de veículos.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5836, 1, '3.3.2.2.1.37.00.00.00.00', 'HOSPEDAGENS', 'Registra as variações patrimoniais diminutivas proveniente da utilização de serviços de hospedagens de servidores e convidados do governo em viagens, a locais onde não existem estabelecimentos comerciais habilitados em prestar esse tipo de serviços, pagos diretamente a pessoas físicas. ', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5837, 1, '3.3.2.2.1.38.00.00.00.00', 'DESPESAS COM LOCOMOÇÃO', 'Registra as variações patrimoniais diminutivas proveniente da utilização de meios de transportes aéreos, terrestres, fluviais ou marítimas, locação ou uso de veículos para transporte de pessoas e suas respectivas bagagens, inclusive quando ocorrer em decorrência de mudanças de domicilio no interesse da administração.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5838, 1, '3.3.2.2.1.39.00.00.00.00', 'SERVICOS GRAFICOS E EDITORIAIS', 'Registra as variações patrimoniais diminutivas com serviços de artes gráficas prestados  por pessoa física, bem como com serviços editoriais diversos.  - confecção de impressos em geral - encadernação de livros jornais e revistas - impressão de jornais - boletins - encartes - folders e assemelhados - plastificação de impressos - serviços de identificação de livros editados usando código de barras - serviços editoriais diversos. ', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5839, 1, '3.3.2.3.1.04.00.00.00.00', 'COMUNICAÇÃO', 'Registra as variações patrimoniais diminutivas provenientes da utilização de serviços de comunicação, prestados por pessoa jurídica.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5840, 1, '3.3.2.3.1.05.00.00.00.00', 'PUBLICIDADE', 'Registra as variações patrimoniais diminutivas provenientes da utilização de serviços de publicidade.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5841, 1, '3.3.2.3.1.06.00.00.00.00', 'MANUTENÇÃO E CONSERVAÇÃO', 'Registra as variações patrimoniais diminutivas provenientes da utilização de serviços de manutenção de bens moveis e imóveis.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5842, 1, '3.3.2.3.1.07.00.00.00.00', 'SERVIÇOS DE APOIO', 'Registra as variações patrimoniais diminutivas provenientes da utilização de serviços prestados por pessoa jurídica a título de apoio as atividades administrativas, técnicas e operacionais dos órgãos públicos, nos casos em que o contrato não especifique o quantitativo físico do pessoal a ser utilizado.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5843, 1, '3.3.2.3.1.08.00.00.00.00', 'SERVIÇOS DE AGUA E ESGOTO, ENERGIA ELETRICA, GAS E OUTROS.', 'Registra as variações patrimoniais diminutivas provenientes da utilização de serviços de agua e esgoto, energia elétrica, gás e outros.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5844, 1, '3.3.2.3.1.11.00.00.00.00', 'SERVIÇOS RELACIONADOS A TECNOLOGIA DA INFORMAÇÃO', 'Registra as variações patrimoniais diminutivas provenientes da utilização de serviços de processamento de dados prestados por empresas especializadas na área de informática; atualização e adaptação de programas de processamento de dados; suporte técnico, revisão, correção de problemas operacionais, análise p/acrescentar novas funções, hospedagem de sistemas e outros.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5846, 1, '3.3.2.3.1.13.00.00.00.00', 'ARMAZENAGEM', 'Registra as variações patrimoniais diminutivas provenientes da utilização de serviços de aluguel de galpões, silos e outros locais destinados a armazenagem de mercadorias e produtos. Inclui, ainda, as variações provenientes de garantia dos estoques armazenados e a utilização de serviço especializado na solução de gestão de estoque, incluindo gestão de materiais e transporte de materiais e equipamentos.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5847, 1, '3.3.2.3.1.14.00.00.00.00', 'ASSINATURAS DE PERIODICOS E ANUIDADES', 'Registra as variações patrimoniais diminutivas provenientes da utilização de assinaturas de TV (TV a cabo), jornais, inclusive diário oficial, revistas, recortes de publicações, software, podendo estar na forma de disquete, CD-ROM, boletins e outros que não se destinem a coleções ou bibliotecas.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5848, 1, '3.3.2.3.1.15.00.00.00.00', 'CAPATAZIA, ESTIVA E PESAGEM', 'Registra as variações patrimoniais diminutivas provenientes da utilização de serviços de movimentação e pesagem de cargas (mercadorias e produtos).', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5849, 1, '3.3.2.3.1.16.00.00.00.00', 'CLASSIFICAÇÃO DE PRODUTOS', 'Registra as variações patrimoniais diminutivas provenientes da utilização de serviços de classificação de produtos de origem animal, mineral e vegetal.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5850, 1, '3.5.2.1.5.02.00.00.00.00', 'IPVA', 'Registra as variações patrimoniais diminutivas por meio de transferências constitucionais de IPVA aos municípios.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5851, 1, '3.3.2.3.1.18.00.00.00.00', 'CONDOMINIOS', 'Registra as variações patrimoniais diminutivas provenientes da apropriação das taxas condominiais a conta do proprietário, ou do locatário, conforme previsto no contrato de locação.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5852, 1, '3.3.2.3.1.19.00.00.00.00', 'CONFECÇÃO DE MATERIAL DE ACONDIC. E EMBALAGEM', 'Registra as variações patrimoniais diminutivas provenientes da utilização de serviços de confecção de materiais destinados a preservação, acomodação ou embalagem de produtos diversos, tais como: - bolsas - caixas - mochilas - sacolas e outros. Somente serão classificados como serviços, caso a unidade forneça a matéria-prima.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5853, 1, '3.3.2.3.1.20.00.00.00.00', 'CONFECÇÃO DE UNIFORMES, BANDEIRAS E FLAMULAS', 'Registra as variações patrimoniais diminutivas provenientes da utilização de serviços de confecção de: - bandeiras - brasoes - estandartes - flamulas - uniformes (inclusive as despesas relacionadas com auxílio fardamento descritos na lei num.8237/91) e outros. Somente serão classificados como serviços, caso a unidade forneça a matéria-prima.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5854, 1, '3.3.2.3.1.21.00.00.00.00', 'DIREITOS AUTORAIS', 'Registra as variações patrimoniais diminutivas provenientes da utilização de direitos autorais sobre obras cientificas, literárias ou em que a divulgação seja de interesse do governo.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5855, 1, '3.3.2.3.1.22.00.00.00.00', 'EXPOSIÇÕES, CONGRESSOS, CONFERENCIAS E OUTROS', 'Registra as variações patrimoniais diminutivas provenientes de serviços utilizados na instalação e manutenção de: conferencias - reuniões técnicas - congressos - exposições - feiras - festejos populares - festivais - e outros.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5856, 1, '3.3.2.3.1.23.00.00.00.00', 'FESTIVIDADES E HOMENAGENS', 'Registra as variações patrimoniais diminutivas provenientes de serviços utilizados na organização de eventos, tais como: coquetéis - festas de congraçamento - recepções - e outras.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5857, 1, '3.3.2.3.1.24.00.00.00.00', 'HONORARIOS ADVOCATICIOS - ONUS DE SUCUMBENCIA', 'Registra as variações patrimoniais diminutivas provenientes da apropriação dos honorários advocatícios decorrentes do ônus da sucumbência, entendido este como o ônus que recai sobre a parte vencida numa ação, para pagamento dos honorários advocatícios a vencedora.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5858, 1, '3.3.2.3.1.25.00.00.00.00', 'HOSPEDAGENS', 'Registra as variações patrimoniais diminutivas provenientes da utilização de serviços de hospedagens e alimentação de servidores e convidados do governo em viagens oficiais pagos diretamente a estabelecimentos hoteleiros (quando não houver pagamento de diárias).', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5859, 1, '3.3.2.3.1.26.00.00.00.00', 'PATROCINIO', 'Registra as variações patrimoniais diminutivas provenientes da utilização de patrocínios a atividades ou eventos, de natureza cultural, esportiva, educacional, ambiental, cientifica, comunitária, promocional etc. Para influenciar favoravelmente o público e/ou atingir outros objetivos relacionados com a promoção de atos, obras, planos, ações, bens ou serviços. Não inclui o patrocínio de mídia, assim considerados aqueles em que o proponente e um veículo de comunicação ou um gestor de meios ou instalações que funcionem como veículo de mídia alternativa e aqueles em que um veículo de comunicação e o único ou o principal realizador da ação patrocinada, ainda que o proponente do projeto e provedor de conteúdo para a ação patrocinada não se enquadre na definição de veículo de comunicação ou meio de mídia alternativa.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5860, 1, '3.3.2.3.1.27.00.00.00.00', 'PRODUÇÕES JORNALISTICAS', 'Registra as variações patrimoniais diminutivas provenientes da utilização de serviços de edição de jornais, revistas, noticiários e materiais jornalísticos para vídeos.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5861, 1, '3.3.2.3.1.28.00.00.00.00', 'PROMOÇÃO', 'Registra as variações patrimoniais diminutivas provenientes da utilização de serviços realizados por integrantes do sicom ou por terceiros, que empreguem recursos de não-mídia, realizadas com objetivo de incentivar públicos de interesse a conhecerem ou comprarem produtos, serviços, marcas, conceitos ou políticas públicas.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5862, 1, '3.5.1.2.2.02.02.00.00.00', 'DOAÇÕES CONCEDIDAS DE BENS IMÓVEIS', 'Registra o valor de doações de bens imóveis entre unidades de órgãos diferentes.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5863, 1, '3.3.2.3.1.29.00.00.00.00', 'SEGUROS EM GERAL', 'Registra as variações patrimoniais diminutivas provenientes da apropriação de prêmios pagos por seguros de qualquer natureza, inclusive cobertura de danos causados a pessoas ou bens de terceiros, prêmios de seguros de bens do estado ou de terceiros, seguro obrigatório de veículos.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5864, 1, '3.3.2.3.1.30.00.00.00.00', 'SELEÇÃO E TREINAMENTO', 'Registra as variações patrimoniais diminutivas provenientes da utilização de serviços prestados nas áreas de instrução e orientação profissional, recrutamento e seleção de pessoal (concurso público) e treinamento.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5865, 1, '3.3.2.3.1.55.00.00.00.00', 'ARRENDAMENTO MERCANTIL OPERACIONAL', 'Registra as variações patrimoniais diminutivas provenientes de arrendamento mercantil operacional', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5866, 1, '3.4.1.1.1.99.00.00.00.00', 'JUROS E ENCARGOS DE OUTRAS  DÍVIDAS CONTRATUAIS', 'Registra a variação patrimonial diminutiva provenientes de juros e encargos de outras dívidas contratadas.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8634, 1, '8.1.2.1.1.03.10.00.00.00', 'OUTRAS CONTRAGARANTIAS CONCEDIDAS NO PAÍS A EXECUTAR', 'Registra o valor de outras contragarantias pendentes de execução, no país.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (5867, 1, '3.3.2.3.1.31.00.00.00.00', 'SERV.MEDICO-HOSPITALAR,ODONTOL.E LABORATORIAIS', 'Registra as variações patrimoniais diminutivas provenientes da utilização de serviços médico-hospitalares, odontológicos e laboratoriais, prestados por pessoas jurídicas sem vínculo empregatício, tais como: analises clinicas - cirurgias - consultas - ecografias - endoscopias -enfermagem - esterilização - exames de laboratório - raio x -tomografias - tratamento odontológico - ultrassonografias - e outros.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5868, 1, '3.3.2.3.1.32.00.00.00.00', 'SERVIÇOS BANCARIOS', 'Registra as variações patrimoniais diminutivas provenientes da apropriação de comissões, tarifas e remunerações decorrentes de serviços prestados por bancos e outras instituições financeiras, bem como despesas com aguarda/custodia de valores (cofres de aluguel).', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5869, 1, '3.3.2.3.1.33.00.00.00.00', 'SERVIÇOS DE ANALISES E PESQUISA CIENTIFICAS', 'Registra as variações patrimoniais diminutivas provenientes da utilização de serviços de analises físico-químicas e pesquisas cientificas, não relacionadas com apoio ao ensino. - Análises minerais - analises de solo - analises químicas - coleta de dados em experimentos - tratamento e destinação de resíduos e outros.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5870, 1, '3.3.2.3.1.34.00.00.00.00', 'SERVIÇOS DE APOIO DO ENSINO', 'Registra as variações patrimoniais diminutivas provenientes da utilização de serviços com o objetivo de proporcionar o desenvolvimento e o aperfeiçoamento do ensino, em todos os níveis, inclusive pesquisas experiências e assemelhados.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5871, 1, '3.3.2.3.1.35.00.00.00.00', 'SERVIÇOS DE ASSISTENCIA SOCIAL', 'Registra as variações patrimoniais diminutivas provenientes de serviços de assistência social prestada a servidores, segurados carentes, abrigados, internados e a seus dependentes, tais como: - ajuda de custo supletiva - gêneros alimentícios - documentação -transporte e sepultamento.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5872, 1, '3.4.1.1.1.01.00.00.00.00', 'JUROS DA DÍVIDA CONTR.C/INSTIT.FINANCEIRAS', 'Registra a variação patrimonial diminutiva com juros da dívida pública derivada de obrigações assumidas com instituições financeiras com vistas a execução de obras, fornecimento de bens ou prestação de serviços, ou da celebração de contratos de financiamento.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5873, 1, '3.3.2.3.1.36.00.00.00.00', 'SERVIÇOS DE AUDIO VIDEO E FOTO', 'Registra as variações patrimoniais diminutivas provenientes da utilização de serviços de filmagens, gravações, revelações, ampliações e reproduções de sons e imagens. - Confecção de álbuns - confecção de crachás funcionais por firmas especializadas - emolduramento de fotografias - imagens de satélites- revelação de filmes - microfilmagem e outros.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5874, 1, '3.3.2.3.1.37.00.00.00.00', 'SERVIÇOS DE CONFECÇÃO SELOS CONTROLE FISCAL', 'Registra as variações patrimoniais diminutivas provenientes da utilização de serviços de confecção de selos/chancelas para controle fiscal.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5875, 1, '3.3.2.3.1.38.00.00.00.00', 'SERVIÇOS DE CONSERV. E REBENEF. DE MERCADORIAS', 'Registra as variações patrimoniais diminutivas provenientes da utilização de serviços utilizados na conservação e rebeneficiamento de mercadorias.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5876, 1, '3.3.2.3.1.39.00.00.00.00', 'SERVIÇOS DE CONTROLE AMBIENTAL', 'Registra as variações patrimoniais diminutivas provenientes da utilização de serviços de controle ambiental.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5877, 1, '3.3.2.3.1.40.00.00.00.00', 'SERVIÇOS DE COPIAS E REPRODUÇÃO DE DOCUMENTOS', 'Registra as variações patrimoniais diminutivas provenientes da utilização de serviços de copias xerográficas, inclusive a locação e a manutenção de equipamentos reprográficos, copias e reproduções de documentos e publicações em geral, inclusive por meio magnético e digitalização.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5878, 1, '3.3.2.3.1.41.00.00.00.00', 'SERVIÇOS DE CRECHE E ASSISTENCIA PRE ESCOLAR', 'Registra as variações patrimoniais diminutivas proveniente da utilização de serviços prestados por entidades de assistência social para atender os dependentes de servidores do órgão, habilitados a usufruírem desse benefício.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5879, 1, '3.3.2.3.1.42.00.00.00.00', 'SERVIÇOS DE INCINERAÇÃO/DESTRUIÇÃO DE MATERIAL', 'Registra as variações patrimoniais diminutivas proveniente da utilização de serviço de processo de incineração e destruição de materiais, bem como resíduos industriais.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5880, 1, '3.3.2.3.1.43.00.00.00.00', 'SERVIÇOS DE PRODUÇÃO INDUSTRIAL', 'Registra as variações patrimoniais diminutivas proveniente da utilização de serviços de transformação, beneficiamento e industrialização de matérias-primas que resultarão em um produto final. Somente serão classificados como serviços, caso a unidade forneça a matéria-prima.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5881, 1, '3.3.2.3.1.44.00.00.00.00', 'SERVIÇOS DE REABILITAÇÃO PROFISSIONAL', 'Registra as variações patrimoniais diminutivas proveniente da utilização de serviços de reabilitação profissional prestados por pessoa jurídica, com o objetivo de proporcionar aos incapacitados (parcial ou totalmente), os meios indicados para a reeducação e readaptação profissional e social, de modo que possam voltar a participar do mercado de trabalho. Ex.: contratação de empresa para ministrar curso profissionalizante.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5882, 1, '3.3.2.3.1.45.00.00.00.00', 'SERVIÇOS FUNERARIOS', 'Registra as variações patrimoniais diminutivas proveniente da utilização de serviços de remoções, sepultamentos e transladações.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5883, 1, '3.3.2.3.1.46.00.00.00.00', 'SERVIÇOS GRÁFICOS E EDITORIAIS', 'Registra as variações patrimoniais diminutivas proveniente da utilização de serviços de artes gráficas prestados por pessoa jurídica, bem como com serviços editoriais diversos. - Confecção de impressos em geral - encadernação de livros jornais e revistas - impressão de jornais - boletins - encartes - folders e assemelhados - plastificação de impressos - serviços de identificação de livros editados usando código de barras - serviços editoriais diversos.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5884, 1, '3.5.1.2.2.02.03.00.00.00', 'TRANFERÊNCIAS CONCEDIDAS DE BENS MÓVEIS ', 'Registra o valor dos bens móveis entre unidades do mesmo órgão.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5885, 1, '3.3.2.3.1.47.00.00.00.00', 'SERVIÇOS JUDICIARIOS', 'Registra as variações patrimoniais diminutivas proveniente da apropriação de custas processuais decorrentes de ações judiciais, diligencias (inclusive condução) salários e honorários dos avaliadores, peritos judiciais e oficiais de justiça e serviços de cartório.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5886, 1, '3.3.2.3.1.51.00.00.00.00', 'SERVIÇOS TECNICOS PROFISSIONAIS', 'Registra as variações patrimoniais diminutivas proveniente da utilização de serviços prestados por empresas especializadas nas seguintes áreas: advocacia - arquitetura - contabilidade - economia - engenharia -estatística e outras. Exceto os serviços de consultoria que devem ser classificados em conta especifica.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5887, 1, '3.3.2.3.1.52.00.00.00.00', 'TAXA DE ADMINISTRAÇÃO', 'Registra as variações patrimoniais diminutivas proveniente da utilização de serviços de organização e administração prestados por pessoa jurídica, tais como: - taxa de administração paga ao instituto Euvaldo Lodi IEl e ao centro de integração empresa-escola - CIEE, decorrente dos serviços de seleção e recrutamento de estudantes, tendo como objetivo o ingresso ao mercado de trabalho e programas de estágio; - taxa de administração patrimonial das contribuições do banco central do brasil, na qualidade de patrocinador, destinado ao custeio das aposentadorias e pensões concedidas com base na lei 8.112/1990, e outros.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5888, 1, '3.3.2.3.1.54.00.00.00.00', 'LOCAÇÃO DE MAO-DE-OBRA', 'Registra as variações patrimoniais diminutivas proveniente da utilização de serviços prestados por pessoas jurídicas para órgãos públicos, tais como limpeza e higiene, vigilância ostensiva e outros, nos casos em que o contrato especifique o quantitativo físico do pessoal a ser utilizado.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5889, 1, '3.3.2.3.1.56.00.00.00.00', 'PASSAGENS E DESPESAS COM LOCOMOÇÃO', 'Registra as variações patrimoniais diminutivas proveniente da utilização de passagens (aéreas, terrestres, fluviais ou marítimas), taxas de embarque, seguros, fretamento, pedágios, locação ou uso de veículos para transporte de pessoas e suas respectivas bagagens, inclusive quando ocorrer em decorrência de mudanças de domicilio no interesse da administração.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5890, 1, '3.3.2.3.1.99.00.00.00.00', 'OUTROS SERVIÇOS TERCEIROS - PJ', 'Registra as variações patrimoniais diminutivas provenientes das demais prestação de serviços por pessoa jurídica fornecida a entidade governamental.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5891, 1, '3.3.3.1.1.01.01.00.00.00', 'DEPRECIAÇÃO DE BENS MÓVEIS', 'Registra a redução do valor dos bens móveis pelo desgaste ou perda de utilidade por uso, ação da natureza ou obsolescência.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5892, 1, '3.3.3.1.1.01.02.00.00.00', 'DEPRECIAÇÃO DE BENS IMÓVEIS', 'Registra a redução do valor dos bens imóveis pelo desgaste ou perda de utilidade por uso, ação da natureza ou obsolescência.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5893, 1, '3.3.3.2.1.01.00.00.00.00', 'AMORTIZAÇÃO DE IMOBILIZADO', 'Registra a redução do valor aplicado na aquisição de direitos, do ativo imobilizado, com existência ou exercício de duração limitada, ou cujo objeto seja bem de utilização por prazo legal ou contratualmente limitado.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5894, 1, '3.3.3.2.1.02.00.00.00.00', 'AMORTIZAÇÃO DE INTANGÍVEL', 'Registra a redução do valor aplicado na aquisição de direitos de propriedade e quaisquer outros, inclusive ativos intangíveis, com existência ou exercício de duração limitada, ou cujo objeto sejam bens de utilização por prazo legal ou contratualmente limitado.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5895, 1, '3.3.3.3.1.01.00.00.00.00', 'EXAUSTÃO DE IMOBILIZADO', 'Registra a redução do valor decorrente da exploração dos recursos minerais, florestais e outros recursos naturais esgotáveis.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5896, 1, '3.4.1.1.1.02.00.00.00.00', 'ENCARGOS DA DÍVIDA CONTR.C/INSTIT.FINANCEIRAS', 'Registra a variação patrimonial diminutiva com encargos da dívida pública derivada de obrigações assumidas com instituições financeiras com vistas a execução de obras, fornecimento de bens ou prestação de serviços, ou da celebração de contratos de financiamento.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5897, 1, '3.4.1.1.3.01.00.00.00.00', 'JUROS DA DÍVIDA CONTR. INTERNA INTER OFSS - UNIÃO', 'Registra a variação patrimonial diminutiva com juros da dívida pública derivada de obrigações assumidas com a união com vistas a execução de obras, fornecimento de bens ou prestação de serviços, ou da celebração de contratos de financiamento.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5898, 1, '3.4.1.1.3.02.00.00.00.00', 'ENCARGOS DA DÍVIDA CONTR.INTERNA INTER OFSS - UNIÃO', 'Registra a variação patrimonial diminutiva com encargos da dívida pública derivada de obrigações assumidas com a união com vistas a execução de obras, fornecimento de bens ou prestação de serviços, ou da celebração de contratos de financiamento.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5899, 1, '3.4.1.1.3.99.00.00.00.00', 'JUROS E ENCARGOS DE OUTRAS  DÍVIDAS CONTRATUAIS - INTERNA INTER OFSS - UNIÃO', 'Registra a variação patrimonial diminutiva provenientes de juros e encargos de outras dívidas contratadas.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5900, 1, '3.4.1.1.4.01.00.00.00.00', 'JUROS DA DÍVIDA CONTR. INTERNA INTER OFSS - ESTADO', 'Registra a variação patrimonial diminutiva com juros da dívida pública derivada de obrigações assumidas com os estados com vistas a execução de obras, fornecimento de bens ou prestação de serviços, ou da celebração de contratos de financiamento.', 1, true, 2, 'N');
