insert into contabilidade.planocontadetalhe values (5903, 1, '3.4.1.1.5.01.00.00.00.00', 'JUROS DA DÍVIDA CONTR. INTERNA INTER OFSS - MUNICÍPIO', 'Registra a variação patrimonial diminutiva com juros da dívida pública derivada de obrigações assumidas com os municípios com vistas a execução de obras, fornecimento de bens ou prestação de serviços, ou da celebração de contratos de financiamento.', 1, true, 2, 'N');
