insert into contabilidade.planocontadetalhe values (5905, 1, '3.4.1.1.5.99.00.00.00.00', 'JUROS E ENCARGOS DE OUTRAS  DÍVIDAS CONTRATUAIS - INTERNA INTER OFSS - MUNICÍPIO', 'Registra a variação patrimonial diminutiva provenientes de juros e encargos de outras dívidas contratadas.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5906, 1, '3.4.1.2.1.01.00.00.00.00', 'JUROS DA DÍVIDA CONTRATADA NO EXTERIOR', 'Registra a variação patrimonial diminutiva com juros da dívida pública contratada no exterior com vistas a execução de obras, fornecimento de bens ou prestação de serviços, ou da celebração de contratos de financiamento.', 1, true, 2, 'N');
