insert into contabilidade.planocontadetalhe values (5908, 1, '3.4.1.4.1.01.00.00.00.00', 'JUROS S/ ADIANTAMENTOS BANCARIOS', 'Registra a variação patrimonial diminutiva decorrente de juros incidentes sobre antecipações de créditos contratadas com bancos e outros agentes financeiros.', 1, true, 2, 'N');
