insert into contabilidade.planocontadetalhe values (8636, 1, '8.1.2.1.1.04.01.00.00.00', 'AVAIS A EXECUTAR', 'Registra o valor das contragarantias recebidas por aval pendente de execução, no país.', 2, true, 1, 'N');
