insert into contabilidade.planocontadetalhe values (5931, 1, '3.4.2.3.1.99.02.00.00.00', 'OUTROS ENCARGOS S/ SERVICOS TERCEIROS - PESSOA JURIDICA', 'Registra a variação patrimonial diminutiva com outros encargos referentes a penalidade em virtude de atrasos e não cumprimento dos prazos dos contratos de prestação de serviços com pessoas jurídicas, que não se enquadrem nos itens anteriores.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5932, 1, '3.4.2.3.1.99.03.00.00.00', 'OUTROS ENCARGOS S/  FONECIMENTO DE BENS', 'Registra a variação patrimonial diminutiva com outros encargos referentes a penalidade em virtude de atrasos e não cumprimento dos prazos dos contratos de aquisição de bens, que não se enquadrem nos itens anteriores.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5933, 1, '3.4.2.4.1.01.00.00.00.00', 'JUROS', 'Registra a variação patrimonial diminutiva com juros a título de penalidade em virtude de atrasos e não cumprimento dos prazos de obrigações tributárias devidas.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5934, 1, '3.4.2.4.1.02.00.00.00.00', 'MULTAS DEDUTÍVEIS', 'Registra a variação patrimonial diminutiva com multas resultantes do pagamento com atraso das obrigações tributárias, como também as multas pagas pelo descumprimento de obrigações acessórias exigidas pela legislação tributária. As multas pagas pela administração pública estão sujeitas ao direito de regresso contra aqueles que lhes deram causa. Esta conta registra as multas consideradas dedutíveis pela legislação na determinação do lucro real, ou seja, apenas as multas por infrações fiscais de natureza compensatória e as impostas por infrações de que não resultem falta ou insuficiência de pagamento de tributo (art. 344., §5º do decreto 3.000, de 26 de marco de 1999 - rir/99).', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5935, 1, '3.4.2.4.1.03.00.00.00.00', 'MULTAS INDEDUTÍVEIS', 'Registra a variação patrimonial diminutiva com multas resultantes do pagamento com atraso das obrigações tributárias, como também as multas pagas pelo descumprimento de obrigações acessórias exigidas pela legislação tributária. As multas pagas pela administração pública estão sujeitas ao direito de regresso contra aqueles que lhes deram causa. Esta conta registra as multas consideradas indedutíveis pela legislação na determinação do lucro real, ou seja, todas as multas por infrações fiscais, salvo as de natureza compensatória e as impostas por infrações de que não resultem falta ou insuficiência de pagamento de tributo (art. 344., §5º do decreto 3.000, de 26 de marco de 1999 -rir/99).', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5936, 1, '3.4.3.1.1.01.00.00.00.00', 'VARIAÇÕES MONETARIAS DE DÍVIDA CONTRATUAL INTERNA - CONSOLIDAÇÃO', 'Registra a Variação Patrimonial Diminutiva proveniente de Variações da nossa própria moeda em relação aos índices ou coeficientes aplicáveis por dispositivo legal ou contratual referentes a dívida Contratual. Ressalte-se será tratada como variação monetária apenas a Correção Monetária Pós-Fixada.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5937, 1, '3.4.3.1.1.02.00.00.00.00', 'VARIAÇÕES CAMBIAIS DE DÍVIDA CONTRATUAL INTERNA - CONSOLIDAÇÃO', 'Registra a Variação Patrimonial Diminutiva proveniente de variações do valor da nossa moeda em relação as moedas estrangeiras referentes a dívida Contratual.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5938, 1, '3.4.3.1.3.01.00.00.00.00', 'VARIAÇÕES MONETARIAS DE DÍVIDA CONTRATUAL INTERNA - INTER OFSS - UNIÃO', 'Registra a Variação Patrimonial Diminutiva proveniente de variações da nossa própria moeda em relação aos índices ou coeficientes aplicáveis por dispositivo legal ou contratual referentes a dívida contratual. ressalte-se será tratada como Variação Monetária apenas a Correção Monetária Pós - Fixada.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5939, 1, '3.5.1.1.2.01.00.00.00.00', 'COTA CONCEDIDA ', 'Registra variação patrimonial diminutiva relativa ao valor da concessão de cota do órgão central de programação financeira para órgão setorial correspondente ao orçamento anual.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5940, 1, '3.4.3.1.4.01.00.00.00.00', 'VARIAÇÕES MONETARIAS DE DÍVIDA CONTRATUAL INTERNA - INTER OFSS - ESTADO', 'Registra a Variação Patrimonial Diminutiva proveniente de variações da nossa própria moeda em relação aos índices ou coeficientes aplicáveis por dispositivo legal ou contratual referentes a dívida contratual. ressalte-se será tratada como Variação Monetária apenas a Correção Monetária Pós - Fixada.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5941, 1, '3.4.3.1.5.01.00.00.00.00', 'VARIAÇÕES MONETARIAS DE DÍVIDA CONTRATUAL INTERNA - INTER OFSS - MUNICÍPIO', 'Registra a Variação Patrimonial Diminutiva proveniente de variações da nossa própria moeda em relação aos índices ou coeficientes aplicáveis por dispositivo legal ou contratual referentes a dívida contratual. ressalte-se será tratada como Variação Monetária apenas a Correção Monetária Pós - Fixada.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5942, 1, '3.4.3.2.1.01.00.00.00.00', 'VARIAÇÕES MONETÁRIAS DA DÍVIDA CONTRATUAL EXTERNA ', 'Registra a Variação Patrimonial Diminutiva proveniente de variações da nossa própria moeda em relação aos índices ou coeficientes aplicáveis por dispositivo legal ou contratual referentes a dívida contratual. Ressalte-se será tratada como Variação Monetária apenas a Correção Monetária Pós - Fixada.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5943, 1, '3.4.3.2.1.02.00.00.00.00', 'VARIAÇÕES CAMBIAIS DE DÍVIDA CONTRATUAL EXTERNA ', 'Registra a Variação Patrimonial Diminutiva proveniente de variações do valor da nossa moeda em relação as moedas estrangeiras referentes a dívida Contratual.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5944, 1, '3.4.3.3.1.01.00.00.00.00', 'VARIAÇÕES MONETÁRIAS DE DÍVIDA MOBILIÁRIA', 'Registra a Variação Patrimonial Diminutiva proveniente de variações da nossa própria moeda em relação aos índices ou coeficientes aplicáveis por dispositivo legal ou contratual referentes a dívida contratual. Ressalte-se será tratada como Variação Monetária apenas a Correção Monetária Pós - Fixada.', 1, true, 2, 'N');
