insert into contabilidade.planocontadetalhe values (5946, 1, '3.4.3.4.1.01.00.00.00.00', 'VARIAÇÕES MONETARIAS DE DÍVIDA MOBILIARIA EXTERNA ', 'Registra a Variação Patrimonial Diminutiva proveniente de variações da nossa própria moeda em relação aos índices ou coeficientes aplicáveis por dispositivo legal ou contratual referentes a dívida contratual. Ressalte-se será tratada como Variação Monetária apenas a Correção Monetária Pós - Fixada.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (6177, 1, '3.6.3.1.1.01.06.00.00.00', 'PERDAS INVOLUNTÁRIAS DE PEÇAS E CONJUNTOS DE REPOSIÇÃO', 'Registra a variação patrimonial diminutiva com perdas involuntárias de peças e conjuntos de reposição.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5947, 1, '3.4.3.4.1.02.00.00.00.00', 'VARIAÇÕES CAMBIAIS DE DÍVIDA MOBILIARIA EXTERNA', 'Registra a Variação Patrimonial Diminutiva proveniente de variações do valor da nossa moeda em relação as moedas estrangeiras referentes a dívida Contratual.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5948, 1, '3.6.5.0.1.05.00.00.00.00', 'DESINCORPORAÇÃO DE ESTOQUES', 'Registra a contrapartida de desincorporação de estoques.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5949, 1, '3.4.3.9.1.01.01.00.00.00', 'ENCARGOS FINANCEIROS DEDUTÍVEIS', 'Registra a Variação Patrimonial Diminutiva proveniente de variações da nossa própria moeda em relação aos índices ou coeficientes aplicáveis por dispositivo legal ou contratual, com exceção a dívida contratual e mobiliaria. Ressalte-se será tratada como Variação Monetária apenas a Correção Monetária Pós - Fixada - Encargos Financeiros Dedutíveis.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5950, 1, '3.4.3.9.1.01.02.00.00.00', 'ENCARGOS FINANCEIROS INDEDUTÍVEIS', 'Registra a Variação Patrimonial Diminutiva proveniente de variações da nossa própria moeda em relação aos índices ou coeficientes aplicáveis por dispositivo legal ou contratual, com exceção a dívida contratual e mobiliaria. Ressalte-se será tratada como Variação Monetária apenas a Correção Monetária Pós - Fixada - Encargos Financeiros Indedutíveis.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5951, 1, '3.4.3.9.1.01.70.00.00.00', 'ATUALIZAÇÃO MONETÁRIA DE PRECATÓRIOS', 'Registra a Variação Patrimonial Diminutiva proveniente de variações da nossa própria moeda em relação aos índices ou coeficientes aplicáveis por dispositivo legal ou contratual, com exceção a dívida contratual e mobiliaria. Ressalte-se será tratada como Variação Monetária apenas a Correção Monetária Pós - Fixada - Atualização Monetária de Precatórios.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5952, 1, '3.4.3.9.1.99.00.00.00.00', 'OUTRAS VARIAÇÕES CAMBIAIS', 'Registra a Variação Patrimonial Diminutiva proveniente de Variação do valor da nossa moeda em relação as moedas estrangeiras, com exceção a dívida Contratual e Mobiliaria.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5953, 1, '3.4.3.9.3.01.01.00.00.00', 'ENCARGOS FINANCEIROS DEDUTÍVEIS', 'Registra a Variação Patrimonial Diminutiva proveniente de variações da nossa própria moeda em relação aos índices ou coeficientes aplicáveis por dispositivo legal ou contratual, com exceção a dívida contratual e mobiliaria. Ressalte-se será tratada como Variação Monetária apenas a Correção Monetária Pós - Fixada - Encargos Financeiros Dedutíveis.', 1, true, 2, 'N');
