insert into contabilidade.planocontadetalhe values (5955, 1, '3.4.3.9.3.01.70.00.00.00', 'ATUALIZAÇÃO MONETÁRIA DE PRECATÓRIOS', 'Registra a Variação Patrimonial Diminutiva proveniente de variações da nossa própria moeda em relação aos índices ou coeficientes aplicáveis por dispositivo legal ou contratual, com exceção a dívida contratual e mobiliaria. Ressalte-se será tratada como Variação Monetária apenas a Correção Monetária Pós - Fixada - Atualização Monetária de Precatórios.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5956, 1, '4.3.3.9.1.08.00.00.00.00', '(-) PASEP', 'Registra o valor das deduções de impostos incidentes sobre as vendas de serviços referentes ao PIS.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5957, 1, '3.4.3.9.4.01.00.00.00.00', 'OUTRAS VARIAÇÕES MONETARIAS', 'Registra a Variação Patrimonial Diminutiva proveniente de variações da nossa própria moeda em relação aos índices ou coeficientes aplicáveis por dispositivo legal ou contratual, com exceção a dívida contratual e mobiliaria. Ressalte-se será tratada como Variação Monetária apenas a Correção Monetária Pós - Fixada.', 1, true, 2, 'N');
