insert into contabilidade.planocontadetalhe values (5959, 1, '3.4.3.9.5.01.00.00.00.00', 'OUTRAS VARIAÇÕES MONETARIAS', 'Registra a Variação Patrimonial Diminutiva proveniente de variações da nossa própria moeda em relação aos índices ou coeficientes aplicáveis por dispositivo legal ou contratual, com exceção a dívida contratual e mobiliaria. Ressalte-se será tratada como Variação Monetária apenas a Correção Monetária Pós - Fixada.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5960, 1, '3.4.3.9.5.02.00.00.00.00', 'OUTRAS VARIAÇÕES CAMBIAIS', 'Registra a Variação Patrimonial Diminutiva proveniente de Variação do valor da nossa moeda em relação as moedas estrangeiras, com exceção a dívida Contratual e Mobiliaria.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5961, 1, '3.5.1.1.2.02.00.00.00.00', 'REPASSE CONCEDIDO  ', 'Registra a variação patrimonial diminutiva relativa ao valor dos recursos concedidos a titulo de transferências financeiras entre órgãos diferentes da administração direta ou indireta, correspondentes ao orçamento anual.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5962, 1, '3.5.1.1.2.03.00.00.00.00', 'SUB-REPASSE CONCEDIDO', 'Registra a variação patrimonial diminutiva relativa ao valor total dos sub-repasses concedidos por transferências financeiras entre UG de um mesmo órgão.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5963, 1, '3.5.1.1.2.04.00.00.00.00', 'RECURSOS ARRECADADOS - CONCEDIDOS ', 'Registra a variação patrimonial diminutiva relativa ao valor concedido para outra UG, referente a recursos que foram arrecadados (classificados como receita), para pagamento de variação patrimonial diminutiva na UG recebedora.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5964, 1, '3.5.1.1.2.05.00.00.00.00', 'VALORES DIFERIDOS - BAIXA ', 'Registra o valor da cota diferida no processo de baixa dos recursos diferidos.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5965, 1, '3.5.1.1.2.08.00.00.00.00', 'VALORES DIFERIDOS - INSCRIÇÃO', 'Registra o valor da cota diferida no processo de inscrição dos recursos diferidos. ', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5966, 1, '3.5.1.1.2.09.00.00.00.00', 'DEVOLUÇÃO DE TRANSFERÊNCIAS RECEBIDAS', 'Compreende os valores das devoluções de transferências anteriormente recebidas', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5967, 1, '3.5.1.1.2.13.00.00.00.00', 'CORRESPONDÊNCIA DE CRÉDITOS - SALDOS FINANCEIROS', 'Registra a apropriação da transferência de créditos internos entre UG de mesma gestão referentes a contas com saldos financeiras em rotinas contábeis orçamentárias.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5968, 1, '3.5.1.2.2.01.01.00.00.00', 'ORDEM DE TRANSFERÊNCIAS CONCEDIDAS   ', 'Registra o valor total das ordens de transferências concedidas referentes a recursos vinculados que deverão permanecer na UG beneficiada.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5969, 1, '3.5.1.2.2.01.02.00.00.00', 'MOVIMENTO DE FUNDOS A CRÉDITO - CORRESPONDÊNCIA DE CRÉDITOS - SALDOS NAO FINANCEIROS', 'Registra a apropriação da transferência de créditos internos entre UG de mesma gestão referentes a contas não financeiras.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5970, 1, '3.5.1.2.2.01.03.00.00.00', 'MOVIMENTO DE FUNDOS A CRÉDITO - CORRESPONDÊNCIA DE CRÉDITOS - SALDOS FINANCEIROS', 'Registra a apropriação da transferência de créditos internos entre órgãos correspondentes a saldos financeiros. ', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5971, 1, '3.5.1.2.2.01.04.00.00.00', 'MOVIMENTO DE FUNDOS A CRÉDITOS - MOVIMENTO DE FUNDOS PRÓPRIOS ', 'Registra o somatório dos saldos credores incorporados por integração de balancetes, fusão, cisão.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5972, 1, '3.5.1.2.2.01.99.00.00.00', 'OUTRAS TRANSFERÊNCIAS FINANCEIRAS CONCEDIDAS - INDEPENDENTES DE EXECUÇÃO ORÇAMENTÁRIA', 'Registra o valor das demais transferências financeiras concedidas para restos a pagar e outras finalidades independentes da execução orçamentária.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5973, 1, '3.5.1.2.2.02.05.00.00.00', 'TRANSFERÊNCIAS CONCEDIDAS DE TÍTULOS E VALORES ', 'Registra o total dos títulos e valores em circulação concedidos por unidade decorrente de transferência a outra unidade de mesma gestão.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5974, 1, '3.5.1.2.2.02.06.00.00.00', 'TRANSFERÊNCIAS CONCEDIDAS DE TÍTULOS DA DÍVIDA ATIVA', 'Registra a transferência de títulos da dívida ativa de uma UG para a o órgão jurídico competente.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5975, 1, '3.5.1.2.2.02.99.00.00.00', 'OUTRAS TRANSFERÊNCIAS  NÃO FINANCEIRAS CONCEDIDAS - INDEPENDENTES DE EXECUÇÃO ORÇAMENTÁRIA', 'Registra o valor das demais transferências concedidas de bens ou valores independentes da execução orçamentária.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5976, 1, '3.6.3.1.1.01.01.00.00.00', 'PERDAS INVOLUNTÁRIAS DE  MÁQUINAS, APARELHOS, EQUIPAMENTOS E FERRAMENTAS', 'Registra a variação patrimonial diminutiva com perdas involuntárias de máquinas, aparelhos, equipamentos e ferramentas.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5977, 1, '3.5.2.3.4.03.00.00.00.00', 'SUBVENÇÕES SOCIAIS', 'Registra o valor utilizado para transferências correntes às entidades públicas ou privadas sem fins lucrativos para os serviços essenciais de assistência social, médica e educacional;', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5978, 1, '3.5.1.3.2.01.01.00.00.00', 'RECURSOS PARA COBERTURA DE INSUFICIÊNCIAS FINANCEIRAS', 'Registra os recursos orçamentários efetivamente utilizados para a cobertura de insuficiências financeiras entre as receitas e despesas previdenciárias no exercício de referência.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5979, 1, '3.5.1.3.2.01.02.00.00.00', 'RECURSOS PARA FORMAÇÃO DE RESERVA', 'Registra os recursos transferidos pelo ente federativo ao RPPS para formação de reserva espontânea, para futuros pagamentos de benefícios do plano financeiro.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5980, 1, '3.5.1.3.2.01.99.00.00.00', 'OUTROS APORTES PARA O RPPS', 'Registra o somatório de eventuais aportes de recursos no RPPS para outras necessidades financeiras que não a cobertura de insuficiências financeiras e formação de reservas.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5981, 1, '3.5.1.3.2.02.01.00.00.00', 'RECURSOS PARA COBERTURA DE DÉFICIT FINANCEIRO', 'Registra o somatório dos recursos necessários ao equilíbrio financeiro do plano previdenciário, ou seja, à cobertura de déficit entre as receitas e despesas previdenciárias, referentes ao exercício atual.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5982, 1, '3.5.1.3.2.02.02.00.00.00', 'RECURSOS PARA COBERTURA DE DÉFICIT ATUARIAL', 'Registra os recursos orçamentários alocados para cobertura de déficit atuarial no exercício de referência, desde que não definidos por lei como contribuições suplementares.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5983, 1, '3.5.1.3.2.02.99.00.00.00', 'OUTROS APORTES PARA O RPPS', 'Registra outros aportes financeiros para o RPPS com outras finalidades previdenciárias.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5984, 1, '3.5.1.4.2.01.01.00.00.00', 'PROVENIENTES DO ORÇAMENTO DA SEGURIDADE SOCIAL', 'Registra o montante do orçamento da Seguridade Social realocado da Saúde ou da Assistência Social para a Previdência.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5985, 1, '3.5.1.4.2.01.02.00.00.00', 'PROVENIENTES DO ORÇAMENTO FISCAL', 'Registra os valores das receitas do orçamento fiscal destinados para cobrir os déficits financeiros da Previdência', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5986, 1, '3.5.1.4.2.02.00.00.00.00', 'RECURSOS PARA FORMAÇÃO DE RESERVA', 'Registra os recursos transferidos pela União ao RGPS para formação de reserva espontânea, para futuros pagamentos de benefícios do plano financeiro.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (5987, 1, '3.5.1.4.2.99.00.00.00.00', 'OUTROS APORTES PARA O RGPS', 'Registra o somatório de eventuais aportes de recursos para o RGPS para outras necessidades financeiras.', 1, true, 2, 'N');
