insert into contabilidade.planocontadetalhe values (5990, 1, '3.5.2.1.5.04.00.00.00.00', 'COTA-PARTE DA CONTRIBUIÇÃO DE INTERVENÇÃO NO DOMÍNIO ECONÔMICO', 'Registra as variações patrimoniais diminutivas por meio de transferências constitucionais de da contribuição de intervenção no domínio econômico (Emenda Constitucional nº 42, de 19/12/2003) aos municípios.', 1, true, 2, 'N');
