insert into contabilidade.planocontadetalhe values (6042, 1, '3.6.1.1.1.01.01.00.00.00', 'REAVALIAÇÃO DE MÁQUINAS, APARELHOS, EQUIPAMENTOS E FERRAMENTAS', 'Registra a variação patrimonial diminutiva relativa à adoção do valor de mercado ou de consenso entre as partes para máquinas, ferramentas, aparelhos, equipamentos, acessórios etc, quando esse for inferior ao valor liquido contábil.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (6043, 1, '3.6.1.1.1.01.02.00.00.00', 'REAVALIAÇÃO DE BENS DE INFORMÁTICA', 'Registra a variação patrimonial diminutiva relativa à adoção do valor de mercado ou de consenso entre as partes paraequipamentos de processamento de dados e sistemas aplicativos, entre outros, quando esse for inferior ao valor liquido contábil.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (6044, 1, '3.6.1.1.1.01.03.00.00.00', 'REAVALIAÇÃO DE MÓVEIS E UTENSÍLIOS', 'Registra a variação patrimonial diminutiva relativa à adoção do valor de mercado ou de consenso entre as partes para mobiliário em geral e utensílios, entre outros, quando esse for inferior ao valor liquido contábil.', 1, true, 2, 'N');
