insert into contabilidade.planocontadetalhe values (6048, 1, '3.6.1.1.1.01.07.00.00.00', 'REAVALIAÇÃO DE BENS MÓVEIS EM ANDAMENTO', 'Registra a variação patrimonial diminutiva relativa à adoção do valor de mercado ou de consenso entre as partes para bens móveis em andamento, quando esse for inferior ao valor liquido contábil.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (6049, 1, '3.6.1.1.1.01.08.00.00.00', 'REAVALIAÇÃO DE BENS MÓVEIS EM ALMOXARIFADO', 'Registra a variação patrimonial diminutiva relativa à adoção do valor de mercado ou de consenso entre as partes para bens permanentes a serem estocados em almoxarifado, quando esse for inferior ao valor liquido contábil.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (6050, 1, '3.6.1.7.2.06.00.00.00.00', 'AJUSTE PARA PERDAS EM DÍVIDA ATIVA NÃO TRIBUTÁRIA', 'Registra a variação patrimonial diminutiva com ajuste para perdas em dívida ativa não tributária.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (6051, 1, '3.6.1.1.1.01.09.00.00.00', 'REAVALIAÇÃO DE ARMAMENTOS', 'Registra a variação patrimonial diminutiva relativa à adoção do valor de mercado ou de consenso entre as partes para armas que constituem objetos de defesa ou preparativos de guerra, quando esse for inferior ao valor liquido contábil.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (6052, 1, '3.6.1.1.1.01.10.00.00.00', 'REAVALIAÇÃO DE SEMOVENTES', 'Registra a variação patrimonial diminutiva relativa à adoção do valor de mercado ou de consenso entre as partes para animais destinados a produção, reprodução, engorda e aos serviços utilitários em geral, quando esse for inferior ao valor liquido contábil.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (6053, 1, '3.6.1.1.1.01.99.00.00.00', 'REAVALIAÇÃO DE DEMAIS BENS MÓVEIS', 'Registra a variação patrimonial diminutiva relativa à adoção do valor de mercado ou de consenso entre as partes para demais bens móveis não classificados em grupos específicos, quando esse for inferior ao valor liquido contábil.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (6054, 1, '3.6.1.1.1.02.01.00.00.00', 'REAVALIAÇÃO DE BENS DE USO ESPECIAL', 'Registra a variação patrimonial diminutiva relativa à adoção do valor de mercado ou de consenso entre as partes para os bens, tais como edifícios ou terrenos destinados a serviço ou estabelecimento da administração estadual ou municipal, inclusive os de suas autarquias e fundações públicas, quando esse for inferior ao valor liquido contábil.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (6055, 1, '3.6.1.1.1.02.02.00.00.00', 'REAVALIAÇÃO DE BENS DOMINICAIS', 'Registra a variação patrimonial diminutiva relativa à adoção do valor de mercado ou de consenso entre as partes para os bens que constituem o patrimônio das pessoas jurídicas de direito público, como objeto de direito pessoal, ou real, de cada uma dessas entidades. Compreende ainda, não dispondo a lei em contrário, os bens pertencentes as pessoas jurídicas de direito público a que se tenha dado estrutura de direito privado, quando esse for inferior ao valor liquido contábil.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (6056, 1, '3.6.1.1.1.02.03.00.00.00', 'REAVALIAÇÃO DE BENS DE USO COMUM DO POVO', 'Registra a variação patrimonial diminutiva relativa à adoção do valor de mercado ou de consenso entre as partes para os bens de uso comum do povo construídos ou adquiridos por pessoas jurídicas de direito público, quando esse for inferior ao valor liquido contábil.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (6057, 1, '3.6.1.1.1.02.04.00.00.00', 'REAVALIAÇÃO DE BENS IMÓVEIS EM ANDAMENTO', 'Registra a variação patrimonial diminutiva relativa à adoção do valor de mercado ou de consenso entre as partes para os valores de bens imóveis em andamento, quando esse for inferior ao valor liquido contábil.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (6058, 1, '3.6.1.1.1.02.05.00.00.00', 'REAVALIAÇÃO DE INSTALAÇÕES', 'Registra a variação patrimonial diminutiva relativa à adoção do valor de mercado ou de consenso entre as partes para equipamentos, materiais e custo de implantação de instalações que, não obstante integradas aos edifícios, devem ser segregadas das obras civis, como, por exemplo, as instalações elétricas, hidráulicas, sanitárias, de vapor, de ar comprimido, frigoríficas, contra incêndio, de comunicações, de climatização, para combustíveis, gases, de antipoluição, para cozinha, dentre outros. E também aplicável a construção de trechos ferroviários, quando esse for inferior ao valor liquido contábil.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (6059, 1, '3.6.1.5.1.01.99.00.00.00', 'REDUÇÃO A VALOR RECUPERÁVEL DE DEMAIS BENS MÓVEIS', 'Registra a variação patrimonial diminutiva relativa à redução a valor recuperável de demais bens móveis não classificados em grupos específicos.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (6060, 1, '3.6.1.1.1.02.06.00.00.00', 'REAVALIAÇÃO DE BENFEITORIAS EM PROPRIEDADE DE TERCEIROS', 'Registra a variação patrimonial diminutiva relativa à adoção do valor de mercado ou de consenso entre as partes para construções em terrenos arrendados de terceiros e instalações e outras benfeitorias em prédios alugados. São considerados somente os gastos com construção e instalação que se incorporam ao imóvel e revertem ao proprietário do imóvel ao final da locação, quando esse for inferior ao valor liquido contábil.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (6061, 1, '3.6.1.1.1.02.99.00.00.00', 'REAVALIAÇÃO DE DEMAIS BENS IMÓVEIS', 'Registra a variação patrimonial diminutiva relativa à adoção do valor de mercado ou de consenso entre as partes para os demais bens imóveis não classificados anteriormente nesse plano de contas, quando esse for inferior ao valor liquido contábil.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (6062, 1, '3.6.1.4.1.01.00.00.00.00', 'REDUÇÃO A VALOR RECUPERÁVEL DE PARTICIPAÇÕES PERMANENTES', 'Registra a variação patrimonial diminutiva relativa à redução a valor recuperável de participações permanentes em outras entidades.', 1, true, 2, 'N');
