insert into contabilidade.planocontadetalhe values (6064, 1, '3.6.1.4.1.05.00.00.00.00', 'REDUÇÃO A VALOR RECUPERÁVEL DE INVESTIMENTOS MANTIDOS PARA VENDA', 'Registra a variação patrimonial diminutiva relativa à redução a valor recuperável de investimentos mantidos para venda.', 1, true, 2, 'N');
