insert into contabilidade.planocontadetalhe values (6067, 1, '3.6.1.4.2.02.00.00.00.00', 'REDUÇÃO A VALOR RECUPERÁVEL DE PROPRIEDADES PARA INVESTIMENTO', 'Registra a variação patrimonial diminutiva relativa à redução a valor recuperável de propriedades para investimento.', 1, true, 2, 'N');
