insert into contabilidade.planocontadetalhe values (6087, 1, '3.6.1.5.1.01.02.00.00.00', 'REDUÇÃO A VALOR RECUPERÁVEL DE BENS DE INFORMÁTICA', 'Registra a variação patrimonial diminutiva relativa à redução a valor recuperável de equipamentos de processamento de dados e sistemas aplicativos, entre outros.', 1, true, 2, 'N');
