insert into contabilidade.planocontadetalhe values (6089, 1, '3.6.1.5.1.01.04.00.00.00', 'REDUÇÃO A VALOR RECUPERÁVEL DE MATERIAIS CULTURAIS, EDUCACIONAIS E DE COMUNICAÇÃO', 'Registra a variação patrimonial diminutiva relativa à redução a valor recuperável de materiais bibliográficos, discotecas, filmotecas, de comunicação, entre outros.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (6090, 1, '3.6.1.5.1.01.05.00.00.00', 'REDUÇÃO A VALOR RECUPERÁVEL DE VEÍCULOS', 'Registra a variação patrimonial diminutiva relativa à redução a valor recuperável de transportes aéreos, aquáticos e terrestres, entre outros.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (6091, 1, '3.6.1.5.1.01.06.00.00.00', 'REDUÇÃO A VALOR RECUPERÁVEL DE PEÇAS E CONJUNTOS DE REPOSIÇÃO', 'Registra a variação patrimonial diminutiva relativa à redução a valor recuperável de peças e conjuntos de reposição destinados a substituição em máquinas e equipamentos, aeronaves e embarcações, bens de segurança e socorro, entre outros.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (6092, 1, '3.6.1.5.1.01.07.00.00.00', 'REDUÇÃO A VALOR RECUPERÁVEL DE BENS MÓVEIS EM ANDAMENTO', 'Registra a variação patrimonial diminutiva relativa à redução a valor recuperável de bens móveis em andamento.', 1, true, 2, 'N');
