insert into contabilidade.planocontadetalhe values (6093, 1, '3.6.1.5.1.01.08.00.00.00', 'REDUÇÃO A VALOR RECUPERÁVEL DE BENS MÓVEIS EM ALMOXARIFADO', 'Registra a variação patrimonial diminutiva relativa à redução a valor recuperável de bens permanentes a serem estocados em almoxarifado.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (6094, 1, '3.6.1.5.1.01.09.00.00.00', 'REDUÇÃO A VALOR RECUPERÁVEL DE ARMAMENTOS', 'Registra a variação patrimonial diminutiva relativa à redução a valor recuperável de armas que constituem objetos de defesa ou preparativos de guerra.', 1, true, 2, 'N');
