insert into contabilidade.planocontadetalhe values (6097, 1, '3.6.1.5.1.02.01.00.00.00', 'REDUÇÃO A VALOR RECUPERÁVEL DE BENS DE USO ESPECIAL', 'Registra a variação patrimonial diminutiva relativa à redução a valor recuperável de bens como edifícios ou terrenos destinados a serviço ou estabelecimento da administração estadual ou municipal, inclusive os de suas autarquias e fundações públicas.', 1, true, 2, 'N');
