insert into contabilidade.planocontadetalhe values (6105, 1, '3.6.1.6.1.01.00.00.00.00', 'REDUÇÃO A VALOR RECUPERÁVEL DE SOFTWARES', 'Registra a variação patrimonial diminutiva com a redução nos benefícios econômicos futuros ou no potencial de serviços de softwares, que reflete um declínio na sua utilidade além do reconhecimento sistemático por meio da depreciação.', 1, true, 2, 'N');
