insert into contabilidade.planocontadetalhe values (6227, 1, '3.7.1.1.1.01.00.00.00.00', 'IMPOSTO SOBRE A RENDA E PROVENTOS DE QUALQUER NATUREZA', 'Registra as variações patrimoniais diminutivas com Imposto sobre a Renda e Proventos de Qualquer Natureza retidos na fonte.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (6228, 1, '3.7.1.1.1.02.00.00.00.00', 'IPVA', 'Registra as variações patrimoniais diminutivas com Imposto sobre a Propriedade de Veículos Automotores.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (6229, 1, '3.7.1.1.1.03.00.00.00.00', 'ITCMD', 'Registra as variações patrimoniais diminutivas com Imposto sobre Transmissão "Causa Mortis" e Doação de Bens e Direitos.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (6230, 1, '3.7.1.1.1.04.00.00.00.00', 'ICMS', 'Registra as variações patrimoniais diminutivas com Imposto sobre Operações Relativas a circulação de Mercadorias e sobre Prestação de Serviços de Transporte Interestadual e Intermunicipal e de Comunicação.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (6231, 1, '3.7.1.1.1.05.00.00.00.00', 'IPTU', 'Registra as variações patrimoniais diminutivas com Imposto sobre a Propriedade Predial e Territorial Urbana.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (6232, 1, '3.7.1.1.1.06.00.00.00.00', 'ITBI', 'Registra as variações patrimoniais diminutivas com Imposto sobre Transmissão "Inter Vivos" de Bens Imóveis e de Direitos Reais sobre Imóveis', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (6233, 1, '3.7.1.1.1.07.00.00.00.00', 'ISS', 'Registra as variações patrimoniais diminutivas com Imposto Sobre Serviços de Qualquer Natureza.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (6234, 1, '3.7.1.1.1.08.00.00.00.00', 'ITR', 'Registra as variações patrimoniais diminutivas com Imposto Sobre a Propriedade Territorial Rural, devidos aos municípios ou ao Distrito Federal devido a convênios firmados com a União, conforme inciso III, parágrafo 4º do artigo 153 da Constituição Federal.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (6235, 1, '3.7.1.1.1.09.00.00.00.00', 'IMPOSTO S/ PRODUTOS INDUSTRIALIZADOS - IPI', 'Registra as variações patrimoniais diminutivas, decorrentes do imposto, de competência da União, sobre produtos industrializados tem como fato gerador: i o seu desembaraço aduaneiro, quando de procedência estrangeira; ii a sua saída dos estabelecimentos a que se refere o parágrafo único do artigo 51 do CTN; iii a sua arrematação, quando apreendido ou abandonado e levado a leilão.para os efeitos deste imposto, considera se industrializado o produto que tenha sido submetido a qualquer operacao que lhe modifique a natureza ou a finalidade, ou o aperfeicoe para o consumo.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (6236, 1, '3.7.1.1.1.10.00.00.00.00', 'IMPOSTO S/ OPERAÇÕES FINANCEIRAS - IOF', 'Registra as variações patrimoniais diminutivas com o imposto, de competência da união, sobre operações de crédito, câmbio e seguro, e sobre operações relativas a titulos e valores mobiliários que tem como fato gerador: i - quanto as operações de crédito, a sua efetivação pela entrega total ou parcial do montante ou do valor que constitua o objeto da obrigação, ou sua colocação a disposição do interessado; ii - quanto as operações de câmbio, a sua efetivação pela entrega de moeda nacional ou estrangeira, ou de documento que a represente, ou sua colocação a disposição do interessado em montante equivalente a moeda estrangeira ou nacional entregue ou posta a disposição por este; iii - quanto as operações de seguro, a sua efetivaçãopela emissão da apólice ou do documento equivalente, ou recebimento do prêmio, na forma da lei aplicável; iv - quanto as operações relativas a títulos e valores mobiliários, a emissão, transmissão, pagamento ou resgate destes, na forma da lei aplicável.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (6324, 1, '4.3.3.9.1.09.00.00.00.00', '(-) COFINS', 'Registra o valor das deduções de impostos incidentes sobre as vendas de serviços referentes ao PASEP.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (6237, 1, '3.7.1.1.1.11.00.00.00.00', 'IMPOSTO S/ IMPORTAÇÃO - II', 'Registra as variações patrimoniais diminutivas, de competência da união, sobre a importação de produtos estrangeiros que tem como fato gerador a entrada destes no territorio nacional.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (6238, 1, '3.7.1.2.1.01.00.00.00.00', 'TAXAS PELO EXERCÍCIO DO PODER DE POLÍCIA', 'Registra as variações patrimoniais diminutivas com taxas pelo exercício do poder de polícia.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (6239, 1, '3.7.1.2.1.02.00.00.00.00', 'TAXAS PELA PRESTAÇÃO DE SERVIÇOS', 'Registra as variações patrimoniais diminutivas com taxas pela prestação de serviço.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (6240, 1, '3.7.2.1.1.01.00.00.00.00', 'CONTRIBUIÇÃO PARA FINANCIAMENTO DA SEGURIDADE SOCIAL - COFINS - ', 'Registra o valor da VPD com contribuição para financiamento da seguridade social', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (6241, 1, '3.7.2.1.1.02.00.00.00.00', 'PIS/PASEP ', 'Registra o valor da VPD com contribuição para o programa de integração social (PIS) ou para o programa de formação do patrimônio do servidor público (PASEP)', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (6242, 1, '3.7.2.1.1.03.00.00.00.00', 'CONTRIBUIÇÃO SOCIAL S/ LUCRO LIQUIDO - CSLL - ', 'Registra o valor da VPD com contribuição social incidente sobre o lucro da pessoa jurídica.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (6243, 1, '3.7.2.1.1.04.00.00.00.00', 'OBRIGAÇÕES PATRONAIS S/ SERVIÇOS DE PESSOA FISICA', 'Registra o valor da VPD com contribuições previdenciárias sobre serviços de terceiros pessoas físicas contratadas para a execução de serviços, sem vínculo com a administração, conforme parecer SOF/DESOC 101 de 17/12/1997.', 1, true, 2, 'N');
