insert into contabilidade.planocontadetalhe values (6315, 1, '4.3.2.9.1.97.06.00.00.00', '(-) PIS/PASEP', 'Registra as deduções das vendas de mercadorias, como devoluções, abatimentos e descontos comerciais concedidos. Dedução de Vendas - PIS/PASEP.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (6316, 1, '4.3.2.9.1.97.07.00.00.00', '(-) COFINS', 'Registra as deduções das vendas de mercadorias, como devoluções, abatimentos e descontos comerciais concedidos. Dedução de Vendas - COFINS.', 1, true, 2, 'N');
