insert into contabilidade.planocontadetalhe values (6318, 1, '4.3.2.9.1.99.00.00.00.00', '(-) OUTRAS DEDUÇÕES DE VENDAS', 'Registra as deduções das vendas de mercadorias, como devoluções, abatimentos e descontos comerciais concedidos. Outras Dedução de Vendas.', 1, true, 2, 'N');
