insert into contabilidade.planocontadetalhe values (6320, 1, '4.3.3.9.1.07.00.00.00.00', '(-) PIS', 'Registra o valor das deduções de impostos incidentes sobre as vendas de serviços referentes ao ICMS.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (6321, 1, '4.3.3.9.1.01.00.00.00.00', '(-) VENDAS CANCELADAS E DEVOLUÇÕES', 'Registra o valor da dedução de VPA de vendas de serviços referentes a cancelamento de vendas.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (6322, 1, '4.3.3.9.1.02.00.00.00.00', '(-) ABATIMENTOS', 'Registra o valor dos abatimentos decorrentes de defeitos de qualidade apresentados nos serviços entregues.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (6323, 1, '4.3.3.9.1.03.00.00.00.00', '(-) DESCONTOS INCONDICIONAIS', 'Registra os descontos incondicionais decorrentes de reduções de preço dadas no momento', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (6325, 1, '4.3.3.9.1.10.00.00.00.00', '(-) CONTRIBUIÇÕES PREVIDENCIARIAS - INSS PATRONAL', 'Registra o valor da contribuição patronal devida pelas empresas que prestam exclusivamente serviços de tecnologia da informação (TI) e de tecnologia da informação e comunicação (TIC), incidentes sobre o valor da receita bruta, excluidas as vendas canceladas e os descontos incondicionais concedidos, conforme dispoe o artigo 7º da lei 12.546/2011. A presente metodologia de calculo do INSS patronal terá vigencia ate 31/12/2014.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (6326, 1, '4.3.3.9.1.99.00.00.00.00', '(-) OUTRAS DEDUÇÕES DE VENDAS', 'Registra o valor de outras deduções de vendas de serviços.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (6327, 1, '4.4.2.4.1.97.00.00.00.00', '(-) DEDUÇÕES', 'Registra as deduções de juros e encargos de mora sobre créditos tributários.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (6328, 1, '4.6.2.2.1.97.01.00.00.00', '(-) DEDUÇÃO ALIENAÇÃO DE BENS MÓVEIS', 'Registra as deduções dos ganho com alienação de ativo imobilizado - Dedução Alienação de Bens Móveis.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (6329, 1, '4.6.2.2.1.97.02.00.00.00', '(-) DEDUÇÃO ALIENAÇÃO DE BENS IMÓVEIS', 'Registra as deduções dos ganho com alienação de ativo imobilizado - Dedução Alienação de Bens Imóveis.', 1, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (6330, 1, '5.2.1.2.1.01.00.00.00.00', 'REESTIMATIVA', 'Registra o valor adicional da receita para abertura de créditos adicionais por motivo de reestimativa da receita.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (6331, 1, '4.9.1.0.1.99.00.00.00.00', '(-) DEDUÇÕES DA VARIAÇÃO PATRIMONIAL AUMENTATIVA BRUTA A CLASSIFICAR', 'Registra os valores referentes às deduções das variações patrimoniais aumentativas de diversas fontes ou origens, que não tenham sido devidamente classificados.', 1, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (6332, 1, '5.1.1.1.0.00.00.00.00.00', 'APROVAÇÃO INICIAL DO PPA', 'Compreende os valores monetários previstos inicialmente para a execução dos programas e ações (projetos, atividades e operações especiais) estabelecidos no plano plurianual.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (6333, 1, '5.1.1.2.0.00.00.00.00.00', 'REVISAO DO PPA', 'Compreende o somatório dos valores monetários das revisões anuais autorizadas durante o período de vigência do plano plurianual.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (6334, 1, '5.1.2.1.1.00.00.00.00.00', 'PLOA INICIAL DA RECEITA', 'Registra o somatório dos valores monetários da previsão de receita constante do PLOA inicial.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (6335, 1, '5.1.2.1.2.00.00.00.00.00', 'ALTERAÇÕES  DO PROJETO INICIAL DA LOA - RECEITA', 'Registra o somatório das alterações no projeto inicial da LOA em relação a receita.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (6336, 1, '5.1.2.2.1.00.00.00.00.00', 'PLOA INICIAL DA DESPESA', 'Registra o somatório dos valores monetários da fixação da despesa constante do PLOA inicial.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (6337, 1, '5.1.2.2.2.00.00.00.00.00', 'ALTERAÇÕES DO PROJETO INICIAL DA LOA - DESPESA', 'Registra o somatório das alterações no projeto inicial da LOA em relação a despesa.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (6338, 1, '5.2.1.1.1.00.00.00.00.00', 'PREVISAO INICIAL DA RECEITA  BRUTA', 'Registra a previsão inicial da receita bruta aprovada na LOA.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (6339, 1, '5.2.1.2.1.02.00.00.00.00', 'CORREÇÃO', 'Registra o valor adicional da receita para abertura de créditos adicionais por motivo de correção de erros ou omissões na estimativa da receita.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (6340, 1, '5.2.2.1.1.01.00.00.00.00', 'CREDITO INICIAL', 'Compreende os valores pertinentes aos créditos inicialmente aprovados para dar suporte a execução orçamentária.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (6341, 1, '5.2.2.1.1.02.01.00.00.00', 'ANTECIPAÇÃO - LDO', 'Registra os valores pertinentes aos créditos antecipados pela lei de diretrizes orçamentarias até que o orçamento seja aprovado.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (6342, 1, '5.2.2.1.2.01.00.00.00.00', 'CREDITO ADICIONAL - SUPLEMENTAR', 'Registra o somatório dos valores relativos aos créditos adicionais suplementares com vista ao reforço da dotação orçamentária constante da lei orçamentária.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (6343, 1, '5.2.2.1.2.02.01.00.00.00', 'CRÉDITOS ESPECIAIS ABERTOS', 'Registra os valores referentes à abertura de créditos especiais autorizados em lei especifica.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (6344, 1, '5.2.2.1.2.02.02.00.00.00', 'CRÉDITOS ESPECIAIS REABERTOS', 'Registra os valores referentes à reabertura de créditos especiais cujo ato de autorização foi promulgado nos últimos quatro meses do exercício anterior.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (6345, 1, '5.2.2.1.2.02.03.00.00.00', 'CRÉDITOS ESPECIAIS REABERTOS - SUPLEMENTAÇÃO', 'Registra os valores referentes à suplementação de créditos especiais reabertos nos termos do § 2º do art. 167 da C.F./88.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (6346, 1, '5.2.2.1.2.03.01.00.00.00', 'CRÉDITOS EXTRAORDINÁRIOS ABERTOS', 'Registra os valores referentes aos créditos extraordinários abertos por decreto do poder executivo.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (6347, 1, '5.2.2.1.2.03.02.00.00.00', 'CRÉDITOS EXTRAORDINÁRIOS REABERTOS', 'Registra os valores referentes à reabertura de créditos extraordinários cujo ato de autorização foi promulgado nos últimos quatro meses do exercício anterior.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (6348, 1, '5.2.2.1.2.03.03.00.00.00', 'CRÉDITOS EXTRAORDINÁRIOS REABERTOS - SUPLEMENTAÇÃO', 'Registra os valores referentes à suplementação de créditos extraordinários reabertos nos termos do § 2º do art. 168 da C.F./88.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (6349, 1, '5.2.2.1.3.01.00.00.00.00', 'SUPERAVIT FINANCEIRO DE EXERCÍCIO ANTERIOR ', 'Registra os valores pertinentes aos créditos adicionais abertos cuja origem de recursos seja superavit financeiro apurado no Balanço patrimonial do exercício anterior.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (6350, 1, '5.2.2.1.3.02.00.00.00.00', ' EXCESSO DE ARRECADAÇÃO          ', 'Registra os valores pertinentes aos créditos adicionais abertos cuja origem de recursos seja excesso de arrecadação.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (6351, 1, '5.2.2.1.3.03.00.00.00.00', 'ANULAÇÃO DE DOTAÇÃO', 'Registra os valores pertinentes aos créditos adicionais abertos cuja origem de recursos seja a anulação parcial ou total de dotações orçamentarias ou créditos adicionais, autorizados em lei.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (6352, 1, '5.2.2.1.3.04.00.00.00.00', 'OPERAÇÕES DE CREDITO', 'Registra os valores pertinentes aos créditos adicionais abertos cuja origem de recursos seja operações de credito autorizadas.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (6353, 1, '5.2.2.1.3.05.00.00.00.00', 'RESERVA DE CONTINGENCIA', 'Registra os valores pertinentes aos créditos adicionais abertos cuja origem de recursos seja a reserva de contingência.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (6354, 1, '5.2.2.1.3.06.00.00.00.00', 'DOTAÇÃO TRANSFERIDA', 'Registra os valores de alterações da lei orçamentária com controle por origem de crédito.', 1, true, 4, 'N');
