insert into contabilidade.planocontadetalhe values (6358, 1, '5.2.2.2.1.01.00.00.00.00', 'PROVISAO RECEBIDA            ', 'Registra a parcela de credito recebida por uma unidade administrativa ou orçamentária, decorrente da descentralização do credito orçamentário ou adicional, dentro do próprio ministério ou órgão.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (6359, 1, '5.2.2.2.1.02.00.00.00.00', 'PROVISAO RECEBIDA - BLOQUEADA', 'Registra a parcela de créditos orçamentários recebidos mediante provisão e posteriormente bloqueados, em hipóteses especiais, pela unidade concedente.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (6360, 1, '5.2.2.2.1.09.01.00.00.00', 'ACRESCIMO ', 'Registra o valor da movimentação de créditos orçamentários por acréscimo decorrente de alteração do quadro de detalhamento de despesa - QDD.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (6361, 1, '5.2.2.2.2.01.01.00.00.00', 'CREDITOS RECEBIDOS ', 'Registra o valor dos créditos recebidos pela administração direta de outros órgãos e entidades.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (6362, 1, '5.2.2.2.2.02.01.00.00.00', 'CREDITOS RECEBIDOS', 'Registra o valor dos créditos recebidos pela administração indireta de mesma ou de diferente unidade orçamentária do órgão emitente.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (6363, 1, '5.2.2.2.2.09.01.00.00.00', 'ACRESCIMO', 'Registra o valor do acréscimo de credito disponível por alteração do quadro de detalhamento de despesa-QDD, por UG não pertencente ao órgão ou entidade da unidade orçamentária.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (6364, 1, '5.2.2.2.9.01.00.00.00.00', 'CREDITOS EXT. RECEB. POR FUSAO/CISAO/EXTINÇÃO ', 'Registra o valor dos créditos recebidos por descentralização externa decorrentes de fusão, cisão ou extinção de órgãos, entidades ou UG''s durante o exercício.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (6365, 1, '5.2.2.2.9.02.00.00.00.00', 'CREDITOS INT. RECEB. POR FUSAO/CISAO/EXTINÇÃO ', 'Registra o valor dos créditos recebidos por descentralização interna decorrentes de fusão, cisão ou extinção de órgãos, entidades ou UG''s durante o exercício.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (6366, 1, '5.2.2.9.1.01.00.00.00.00', 'PRÉ-EMPENHOS EMITIDOS', 'Registra os valores dos pré-empenhos emitidos pela própria unidade gestora detentora pelo credito disponível.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (6367, 1, '5.2.2.9.1.02.00.00.00.00', 'REFORÇO DE PRÉ-EMPENHO', 'Registra os valores de reforço de pré-empenho emitido pela própria unidade detentora do crédito disponível.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (6368, 1, '5.2.2.9.1.03.00.00.00.00', 'ANULAÇÃO DE PRÉ-EMPENHO', 'Registra a anulação de pré-empenho emitido pela própria unidade detentora do crédito disponível.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (6369, 1, '5.2.2.9.2.01.01.00.00.00', 'EMISSAO DE EMPENHOS       ', 'Registra o valor da emissão de empenho da despesa, inclusive referente àquela despesa que já se encontra pré-empenhada.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (6370, 1, '5.2.2.9.2.01.02.00.00.00', 'REFORCO DE EMPENHOS       ', 'Registra o valor da emissão de nota de empenho de despesa visando suplementar o anterior cujo valor seja insuficiente.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (6371, 1, '5.3.1.1.0.00.00.00.00.00', 'RP NÃO PROCESSADOS INSCRITOS', 'Compreende os valores inscritos em restos a pagar não-processados relativos às despesas empenhadas e não liquidadas até o ultimo dia do exercício financeiro imediatamente anterior.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (6372, 1, '5.3.1.2.0.00.00.00.00.00', 'RP NÃO PROCESSADOS - EXERCÍCIOS ANTERIORES', 'Compreende o valor de restos a pagar não processados relativo a exercícios anteriores que não foram cancelados porque tiveram seu prazo de validade prorrogado.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (6373, 1, '5.3.1.3.0.00.00.00.00.00', 'RP NÃO PROCESSADOS RESTABELECIDOS', 'Compreende o valor por restabelecimento de empenho de restos a pagar já cancelados em exercícios anteriores com base em ato normativo específico.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (6374, 1, '5.3.1.6.0.00.00.00.00.00', 'RP NÃO PROCESSADOS RECEBIDOS POR TRANSFERÊNCIA', 'Compreende o valor da transferência de restos a pagar não processados decorrente de transformação, cisão, fusão e extinção de órgãos ou UG.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (6375, 1, '7.1.2.1.1.04.02.00.00.00', 'FIANÇAS', 'Registra o valor das contragarantias decorrentes das concessões de fianças por obrigações contraídas no exterior.', 1, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (6376, 1, '5.3.1.7.0.00.00.00.00.00', 'RP NÃO PROCESSADOS - INSCRIÇÃO NO EXERCÍCIO', 'Compreende o valor das despesas empenhadas inscritas no exercício como restos a pagar não processados, a ser transferido no exercício seguinte para a conta 531100000.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (6377, 1, '5.3.2.1.0.00.00.00.00.00', 'RP PROCESSADOS - INSCRITOS', 'Compreende o somatório dos valores inscritos em restos a pagar processados relativos às despesas empenhadas, liquidadas e não pagas no exercício financeiro em que foi empenhado.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (6378, 1, '5.3.2.2.0.00.00.00.00.00', 'RP PROCESSADOS - EXERCÍCIOS ANTERIORES', 'Compreende os valores de restos a pagar processados relativos às despesas empenhadas, liquidadas e não pagas no exercício financeiro subseqüente.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (6379, 1, '5.3.2.6.0.00.00.00.00.00', 'RP PROCESSADOS RECEBIDOS POR TRANSFERÊNCIA', 'Compreende o valor da transferência de restos a pagar processados decorrente de transformação, cisão, fusão e extinção de órgãos ou UG.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (6380, 1, '5.3.2.7.0.00.00.00.00.00', 'RP PROCESSADOS - INSCRIÇÃO NO EXERCÍCIO', 'Compreende o valor das despesas empenhadas inscritas no exercício como restos a pagar processados, a ser transferido no exercício seguinte para a conta 532100000.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (6381, 1, '7.1.2.1.1.01.05.00.00.00', 'CAUÇÕES', 'Registra a responsabilidade da unidade por títulos, valores e bens concedidos em cauções no país.', 1, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (6382, 1, '6.2.1.3.1.01.00.00.00.00', '(-) FUNDEB', 'Registra o somatório dos valores relativos as deduções de receitas realizadas por transferências ao FUNDEB.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (6383, 1, '6.2.1.3.1.02.00.00.00.00', '(-) TRANSFERÊNCIAS CONSTITUCIONAIS E LEGAIS A MUNICÍPIOS', 'Registra o somatório dos valores relativos as deduções de receitas realizadas por transferências constitucionais e legais aos municípios, as quais representem repartição de receita orçamentária.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (6384, 1, '6.2.1.3.2.00.00.00.00.00', '(-) RENÚNCIA', 'Registra o somatório dos valores relativos as deduções de receitas realizadas por renúncia, detalhada por natureza de receita.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (6385, 1, '6.2.1.3.9.00.00.00.00.00', '(-) OUTRAS DEDUÇÕES DA RECEITA REALIZADA', 'Registra o somatório dos valores relativos as outras deduções de receitas realizadas, detalhada por natureza de receita.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (6386, 1, '6.2.2.1.3.99.00.00.00.00', '(-) OUTROS CRÉDITOS UTILIZADOS', 'Registra a contrapartida de despesas realizadas pelas entidades ou órgão da administração direta/indireta que utilizam o SIAFI no modulo parcial.   Registra a contrapartida de despesas liquidadas na rotina de suprimento de fundos para evitar a emissão de lista de item (li) para reclassificação da despesa.', 1, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (8637, 1, '8.1.2.1.1.04.03.00.00.00', 'AVAIS EXECUTADOS', 'Registra o valor recebido das contragarantias recebidas por aval no país.', 2, true, 1, 'N');
