insert into contabilidade.planocontadetalhe values (6463, 1, '7.2.1.1.3.00.00.00.00.00', 'RECURSOS EXTRAORÇAMENTÁRIOS', 'Registra as disponibilidades por destinação de recursos extraorçamentários.', 1, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (6464, 1, '7.3.1.1.1.01.00.00.00.00', 'ENCAMINHAMENTO DE CRÉDITOS PARA INSCRIÇÃO EM DÍVIDA ATIVA TRIBUTÁRIA - IMPOSTOS', 'Registra o montante dos créditos passíveis de serem encaminhados para inscrição em Dívida Ativa, referentes a impostos.', 1, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (6465, 1, '7.3.1.1.1.02.00.00.00.00', 'ENCAMINHAMENTO DE CRÉDITOS PARA INSCRIÇÃO EM DÍVIDA ATIVA TRIBUTÁRIA - TAXAS', 'Registra o montante dos créditos passíveis de serem encaminhados para inscrição em Dívida Ativa, referentes a taxas', 1, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (6466, 1, '7.3.1.1.1.03.00.00.00.00', 'ENCAMINHAMENTO DE CRÉDITOS PARA INSCRIÇÃO EM DÍVIDA ATIVA TRIBUTÁRIA - CONTRIBUIÇÃO DE MELHORIA', 'Registra o montante dos créditos passíveis de serem encaminhados para inscrição em Dívida Ativa, referentes a contribuições de melhoria.', 1, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (6467, 1, '7.3.1.1.2.01.00.00.00.00', 'ENCAMINHAMENTO DE CRÉDITOS PARA INSCRIÇÃO EM DÍVIDA ATIVA  NÃO-TRIBUTÁRIA', 'Registra o montante dos créditos a encaminhar e encaminhados para inscrição em Dívida Ativa Não-Tributária..', 1, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (6468, 1, '7.3.2.1.1.00.00.00.00.00', 'INSCRIÇÃO DE CRÉDITOS EM DÍVIDA ATIVA TRIBUTÁRIA', 'Compreende o valor dos créditos de origem tributária passíveis de serem inscritos em dívida ativa pelo órgão competente.', 1, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (6469, 1, '7.3.2.1.2.00.00.00.00.00', 'INSCRIÇÃO DE CRÉDITOS EM DÍVIDA ATIVA NÃO-TRIBUTÁRIA', 'Compreende o valor dos créditos de natureza não-tributára passíveis de serem inscritos em dívida ativa pelo órgão competente.', 1, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (6470, 1, '7.4.1.1.1.00.00.00.00.00', 'DEMANDAS JUDICIAIS', 'Registra a estimativa do montante relativo a ações judiciais em andamento contra o ente federativo nas quais haja a probabilidade de que o ganho de causa venha a ser da outra parte. Ao fazer a estimativa, considerar os principais tipos de ação judicial, tais como:a) Demandas judiciais contra a atividade reguladora do Estado: Indexação e controles de preços; De ordem tributária e previdenciária; Outras demandas judiciais;b) Demandas judiciais contra empresas estatais dependentes;c) Demandas judiciais contra a administração direta e indireta: Privatizações, liquidação ou extinção de órgãos ou empresas; Reajustes salariais;d) Demandas trabalhistas contra o ente federativo;e) Outras demandas judiciais.', 1, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (6471, 1, '7.4.1.1.2.00.00.00.00.00', 'DÍVIDAS EM PROCESSO DE RECONHECIMENTO', 'Registra as Dívidas ainda não assumidas formalmente que apresentam probabilidade de serem incorporadas ao passivo devido, por exemplo, a decisões judiciais.', 1, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (6472, 1, '8.9.1.2.2.02.00.00.00.00', '(-) DEPRECIAÇÃO DOS ATIVOS CONTABILIZADOS NO ENTE', 'Registra o valor da depreciação dos ativos oriundos de contratos de Parcerias Público Privadas. Tal depreciação deve estar reconhecida no ativo imobilizado do ente (Poder Concedente), mas deve ser registrada em conta de controle a fim de obter a informação segregada dos ativos produzidos por meio de PPP.', 1, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (6473, 1, '7.4.1.1.3.00.00.00.00.00', 'AVAIS E GARANTIAS CONCEDIDAS', 'Registra a estimativa do montante que apresenta probabilidade de vir a ser gasto pelo ente federativo para honrar fianças e avais concedidos em operações de crédito direta ou indiretamente pelo ente federativo a favor de outros entes federativos e entidades dos setores público e privado, inclusive com recursos de fundos de aval, a assunção de risco creditício em linhas de crédito, o seguro de crédito à exportação e outras garantias de natureza semelhante que representem compromisso de adimplência de obrigação financeira ou contratual.', 1, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (6474, 1, '7.4.1.1.4.00.00.00.00.00', 'ASSUNÇÃO DE PASSIVOS', 'Registra a estimativa do montante que apresenta probabilidade de vir a ser gasto pelo ente federativo com o objetivo de proteger o cidadão ou sistemas importantes do Mercado contra inadimplências, falências, altos prejuízos, ou garantir a credibilidade desses sistemas frente a fatores agudos adversos. Ao fazer a estimativa, considerar os principais tipos de situações que podem advir:a) de órgãos da administração direta ou indireta;b) de entidades privadas;c) de Regime Próprio de Previdência Social dos Servidores Públicos;d) de Entes da Federação;e) do Regime Geral de Previdência Social;f) do Banco Central; eg) da assunção de outros passivos.', 1, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (6475, 1, '7.4.1.1.5.00.00.00.00.00', 'ASSISTÊNCIAS DIVERSAS', 'Registra a estimativa do montante que apresenta probabilidade de vir a ser empregado pelo ente federativo com o objetivo de fazer frente a calamidades públicas e que, por não serem recorrentes, não foram planejados. Recomenda-se que o ente federativo explicite o tipo de assistência emergencial que ele está prevendo, por exemplo, se é assistência contra seca, enchentes, catástrofes, epidemias etc.', 1, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (6476, 1, '7.4.1.1.9.00.00.00.00.00', 'OUTROS PASSIVOS CONTINGENTES', 'Registra a estimativa do montante que apresenta probabilidade de vir a ser empregado pelo ente federativo para fazer frente a outros tipos de passivos contingentes.', 1, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (6477, 1, '7.4.2.1.1.00.00.00.00.00', 'FRUSTRAÇÃO DE ARRECADAÇÃO', 'Registra a estimativa do montante de redução de arrecadação que apresenta probabilidade de vir a ocorrer no exercício, decorrente de, por exemplo, cenários macroeconômicos desfavoráveis não previstos na época da elaboração do Orçamento.', 1, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (6478, 1, '7.4.2.1.2.00.00.00.00.00', 'RESTITUIÇÃO DE TRIBUTOS A MAIOR', 'Registra a estimativa do montante de devolução de tributos a maior que apresenta probabilidade de vir a ocorrer no exercício.', 1, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (6479, 1, '7.4.2.1.3.00.00.00.00.00', 'DISCREPÂNCIA DE PROJEÇÕES:', 'Registra a estimativa do montante de redução no valor dos ingressos ou de aumento no valor dos desembolsos que apresentam probabilidade de vir a ocorrer no exercício, decorrentes de evolução desfavorável de indicadores econômicos empregados na época da elaboração do Orçamento, tais como:a) Taxa de crescimento econômico;b) Taxa de inflação;c) Taxa de câmbio;d) Taxa de juros;e) Salário mínimo;f) Outros indicadores.', 1, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (6480, 1, '7.4.2.1.4.00.00.00.00.00', 'OUTROS RISCOS FISCAIS', 'Registra a estimativa do montante que apresenta probabilidade de vir a ser empregado pelo ente federativo para fazer frente a outros tipos de riscos fiscais.', 1, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (6481, 1, '7.5.2.0.0.00.00.00.00.00', 'PRESTAÇÃO DE CONTAS DE CONSÓRCIOS PÚBLICOS', 'Compreende contas relacionadas ao registro do controle da prestação de contas dos Consórcios Públicos.', 1, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (6482, 1, '7.5.3.1.0.00.00.00.00.00', 'VALORES TRANSFERIDOS POR CONTRATO DE RATEIO', 'Compreende os valores repassados pelo ente para execução das despesas nos Consórcios Públicos, com base no Contrato de Rateio.', 1, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (6483, 1, '7.5.3.2.0.00.00.00.00.00', 'DESPESAS EXECUTADAS EM CONSÓRCIOS PÚBLICOS', 'Compreende as despesas executadas em consórcios públicos atribuídas ao ente consorciado com base no contrato de rateio.', 1, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (6484, 1, '7.5.3.3.0.00.00.00.00.00', 'EXECUÇÃO DE RP NÃO PROCESSADOS EM CONSÓRCIOS PÚBLICOS', 'Compreende o somatório dos valores relativos à transferência, liquidação e pagamento das despesas empenhadas, não liquidadas no exercício financeiro de sua inscrição e não pagas, em consórcios públicos atribuídos ao ente consorciado com base no contrato de rateio.', 1, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (6485, 1, '7.5.3.4.0.00.00.00.00.00', 'EXECUÇÃO DE RP PROCESSADOS EM CONSÓRCIOS PÚBLICOS', 'Compreende o somatório dos valores relativos à transferência, liquidação e pagamento das despesas empenhadas, liquidadas no exercício financeiro de sua inscrição e não pagas, em consórcios públicos atribuídos ao ente consorciado com base no contrato de rateio.', 1, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (6486, 1, '7.5.3.5.0.00.00.00.00.00', 'INSUFICIÊNCIA DE CAIXA DO CONSÓRCIO PÚBLICO', 'Compreende a parcela total da insuficiência de caixa gerada no consórcio público atribuída ao ente consorciado com base no contrato de rateio.', 1, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (6487, 1, '7.9.1.1.1.00.00.00.00.00', 'DEPÓSITOS JUDICIAIS', 'Registra os depósitos judiciais efetuados por terceiros em títulos, em conta vinculada etc, sob a responsabilidade da unidade, ou depositados por esta para terceiros.', 1, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (6488, 1, '7.9.1.1.2.00.00.00.00.00', 'DEPÓSITOS COMPULSÓRIOS', 'Registra o somatório dos valores dos depósitos compulsórios realizados.', 1, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (6489, 1, '7.9.1.1.3.00.00.00.00.00', 'OUTRAS RESPONSABILIDADES COM TERCEIROS', 'Registra responsabilidades com terceiros, não individualizadas nas outras contas desse grupo.', 1, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (6490, 1, '7.9.1.2.1.00.00.00.00.00', 'CONTROLE DE ADIANTAMENTOS/SUPRIMENTOS DE FUNDOS CONCEDIDOS', 'Registra os valores concedidos a servidor responsável para atender despesas que não possam subordinar-se ao processo normal de aplicação, até a sua prestação de contas.', 1, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (6491, 1, '7.9.1.2.2.00.00.00.00.00', 'ATIVOS DE PPP CONTABILIZADOS NO ENTE', 'Registra o valor contábil líquido dos ativos produzidos por meio de Parcerias Público Privadas e contabilizados no Ente (Poder Concedente). Deverá ser debitada para fins de incorporação do ativo e deverá ser creditada para fins de registro da depreciação.', 1, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (6492, 1, '7.9.1.2.9.00.00.00.00.00', 'OUTRAS RESPONSABILIDADES DE TERCEIROS', 'Registra o valor de outras responsabilidades de terceiros, de natureza eventual, por títulos, valores e bens, para as quais não há contas especificas.', 1, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (6493, 1, '7.9.2.0.0.00.00.00.00.00', 'DIVERSOS RESPONSÁVEIS EM APURAÇÃO', 'Compreende as responsabilidades em fase de apuração decorrentes de atos praticados por gestores, servidores ou terceiros que possam resultarem prejuízos para a fazenda nacional.', 1, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (6494, 1, '1.1.3.6.4.99.00.00.00.00', 'OUTROS CRÉDITOS PREVIDENCIÁRIOS ', 'Registra os valores relativos a outros créditos previdenciários devidos ao RPPS pelo ente, sujeitos a pagamento em parcela única ou parcelados.', 1, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (6495, 1, '7.9.3.0.0.00.00.00.00.00', 'CONTROLE DE OPERAÇÕES DE CRÉDITO PARA FINS DA LRF', 'Compreende as contas relacionadas ao fluxo de operações de crédito no exercício financeiro para fins de preenchimento do Demonstrativo previsto no artigo 55, I, d da LRF. ', 1, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (6496, 1, '7.9.4.0.0.00.00.00.00.00', 'CONTROLE DE OBRIGAÇÕES SEM AUTORIZAÇÃO ORÇAMENTÁRIA PARA FINS DA LRF', 'Compreende as contas relacionadas ao reconhecimento de obrigações patrimoniais realizadas sem autorização orçamentária, para fins de preenchimento do Relatório de Gestão Fiscal, previsto no art. 54 da LRF. ', 1, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (6497, 1, '1.2.4.0.0.00.00.00.00.00', 'INTANGÍVEL', 'Compreende os direitos que tenham por objeto bens incorpóreos destinados a manutenção da entidade ou exercidos com essa finalidade.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6498, 1, '1.0.0.0.0.00.00.00.00.00', 'ATIVO', 'Compreende os recursos controlados por uma entidade como consequência de eventos passados e dos quais se espera que fluam benefícios econômicos ou potencial de serviços futuros a unidade.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6499, 1, '1.0.0.0.0.00.00.00.00.00', 'ATIVO', 'Compreende os recursos controlados por uma entidade como consequência de eventos passados e dos quais se espera que fluam benefícios econômicos ou potencial de serviços futuros a unidade.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6500, 1, '1.1.1.0.0.00.00.00.00.00', 'CAIXA E EQUIVALENTES DE CAIXA', 'Compreende o somatório dos valores em caixa e em bancos, bem como equivalentes, que representam recursos com livre movimentação para aplicação nas operações da entidade e para os quais não haja restrições para uso imediato.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6564, 1, '1.1.2.4.1.07.00.00.00.00', 'EMPRÉSTIMOS E FINANCIAMENTOS CONCEDIDOS COM RECURSOS PREVIDENCIÁRIOS', 'Compreende o somatório dos valores de empréstimos e financiamentos concedidos por autorizações legais ou vinculações a contratos e acordos.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6501, 1, '1.1.1.1.0.00.00.00.00.00', 'CAIXA E EQUIVALENTES DE CAIXA EM MOEDA NACIONAL', 'Compreende o somatório dos valores em caixa e em bancos, bem como equivalentes, que representam recursos com livre movimentação para aplicação nas operações da entidade e para os quais não haja restrições para uso imediato.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6502, 1, '1.1.1.1.1.00.00.00.00.00', 'CAIXA E EQUIVALENTES DE CAIXA EM MOEDA NACIONAL - CONSOLIDAÇÃO', 'Compreende o somatório dos valores de caixa e equivalentes de caixa em moeda nacional. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6503, 1, '1.1.1.1.1.06.00.00.00.00', 'CONTA ÚNICA RPPS', 'Compreende os valores disponíveis na Conta Única do RPPS.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6504, 1, '1.1.1.1.1.50.00.00.00.00', 'APLICAÇÕES FINANCEIRAS DE LIQUIDEZ IMEDIATA', 'Compreende as aplicações financeiras de alta liquidez em moeda nacional, que são prontamente conversíveis em valores conhecidos de caixa e que estão sujeitas a um insignificante risco de mudança de valor.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6505, 1, '1.1.1.1.2.00.00.00.00.00', 'CAIXA E EQUIVALENTES DE CAIXA EM MOEDA NACIONAL - INTRA OFSS', 'Compreende o somatório dos valores de caixa e equivalentes de caixa em moeda nacional. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do ente.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6506, 1, '1.1.1.2.0.00.00.00.00.00', 'CAIXA E EQUIVALENTES DE CAIXA EM MOEDA ESTRANGEIRA', 'Compreende o somatório dos valores de caixa e equivalentes de caixa em moeda estrangeira.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6507, 1, '1.1.1.2.1.00.00.00.00.00', 'CAIXA E EQUIVALENTES DE CAIXA EM MOEDA ESTRANGEIRA - CONSOLIDAÇÃO', 'Compreende o somatório dos valores de caixa e equivalentes de caixa em moeda estrangeira. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6508, 1, '1.1.2.0.0.00.00.00.00.00', 'CRÉDITOS A CURTO PRAZO', 'Compreende os valores a receber por fornecimento de bens, serviços, créditos tributários, dívida ativa, transferências e empréstimos e financiamentos concedidos realizáveis em até 12 meses da data das demonstrações.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6509, 1, '1.1.2.1.0.00.00.00.00.00', 'CRÉDITOS TRIBUTÁRIOS A RECEBER', 'Compreende os valores relativos a créditos a receber oriundos das variações patrimoniais aumentativas tributárias, realizáveis em até 12 meses da data das demonstrações. Os tributos são: impostos, taxas, contribuições de melhoria, contribuições e empréstimos compulsórios.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6510, 1, '1.1.2.1.1.00.00.00.00.00', 'CRÉDITOS TRIBUTÁRIOS A RECEBER - CONSOLIDAÇÃO', 'Compreende os valores relativos a créditos a receber oriundos das variações patrimoniais aumentativas tributárias, realizáveis em até 12 meses da data das demonstrações.. Os tributos são: impostos, taxas, contribuições de melhoria, contribuições e empréstimos compulsórios. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6511, 1, '1.1.2.1.1.01.00.00.00.00', 'IMPOSTOS', 'Compreende os valores relativos aos créditos a receber, decorrentes da cobrança da modalidade de tributo cuja obrigação tem por fato gerador uma situação independente de qualquer atividade estatal específica relativa ao contribuinte.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6512, 1, '1.1.2.1.1.02.00.00.00.00', 'TAXAS', 'Compreende os valores relativos aos créditos a receber, decorrentes da cobrança da modalidade de tributo que tem como fato gerador o exercício regular do poder de polícia ou a utilização efetiva ou potencial de serviço público específico e divisível, prestado ao contribuinte ou posto a sua disposição.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6513, 1, '1.1.2.1.1.03.00.00.00.00', 'CONTRIBUIÇÕES DE MELHORIA', 'Compreende os valores relativos aos créditos a receber, decorrentes da cobrança dos valores decorrentes da contribuição instituída para fazer face ao custo de obras públicas de que decorra valorização imobiliária.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6514, 1, '1.1.2.1.1.04.00.00.00.00', 'DEMAIS CONTRIBUIÇÕES', 'Compreende os valores relativos aos créditos a receber, decorrentes da cobrança das demais contribuições.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6515, 1, '1.1.2.1.1.05.00.00.00.00', 'CONTRIBUIÇÕES PREVIDENCIÁRIAS A RECEBER', 'Compreende os valores relativos aos créditos a receber, decorrentes das contribuições para o financiamento da previdência social.', 1, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (6516, 1, '1.1.2.1.2.00.00.00.00.00', 'CRÉDITOS TRIBUTÁRIOS A RECEBER - INTRA OFSS', 'Compreende os valores relativos a créditos a receber oriundos das variações patrimoniais aumentativas tributárias, realizáveis em até 12 meses da data das demonstrações. Os tributos são: impostos, taxas, contribuições de melhoria, contribuições e empréstimos compulsórios. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do ente.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6517, 1, '1.1.2.1.2.01.00.00.00.00', 'IMPOSTOS', 'Compreende os valores relativos aos créditos a receber, decorrentes da cobrança da modalidade de tributo cuja obrigação tem por fato gerador uma situação independente de qualquer atividade estatal específica relativa ao contribuinte.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6518, 1, '1.1.2.1.2.02.00.00.00.00', 'TAXAS', 'Compreende os valores relativos aos créditos a receber, decorrentes da cobrança da modalidade de tributo que tem como fato gerador o exercício regular do poder de polícia ou a utilização efetiva ou potencial de serviço público específico e divisível, prestado ao contribuinte ou posto a sua disposição.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6519, 1, '1.1.2.1.2.03.00.00.00.00', 'CONTRIBUIÇÕES DE MELHORIA', 'Compreende os valores relativos aos créditos a receber, decorrentes da cobrança dos valores decorrentes da contribuição instituída para fazer face ao custo de obras públicas de que decorra valorização imobiliária.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6520, 1, '1.1.2.1.2.04.00.00.00.00', 'DEMAIS CONTRIBUIÇÕES', 'Compreende os valores relativos aos créditos aos créditos a receber, decorrentes da cobrança das demais contribuições.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6521, 1, '1.1.2.1.2.05.00.00.00.00', 'CONTRIBUIÇÕES PREVIDENCIÁRIAS A RECEBER', 'Compreende os valores relativos aos créditos a receber, decorrentes das contribuições para o financiamento da previdência social.', 1, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (6522, 1, '1.1.2.4.2.02.00.00.00.00', 'FINANCIAMENTOS CONCEDIDOS', 'Compreende o somatório dos valores dos financiamentos concedidos por autorizações legais ou vinculações a contratos e acordos, exceto os concedidos com recursos do RPPS.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6565, 1, '1.1.2.4.2.00.00.00.00.00', 'EMPRÉSTIMOS E FINANCIAMENTOS CONCEDIDOS-INTRA OFSS', 'Compreende o somatório dos valores de empréstimos e financiamentos concedidos por autorizações legais ou vinculações a contratos e acordos. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do ente.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6523, 1, '1.1.2.1.3.00.00.00.00.00', 'CRÉDITOS TRIBUTÁRIOS A RECEBER - INTER OFSS - UNIÃO', 'Compreende os valores relativos a créditos a receber oriundos das variações patrimoniais aumentativas tributárias realizáveis em até 12 meses da data das demonstrações. Os tributos são: impostos, taxas, contribuições de melhoria, contribuições e empréstimos compulsórios. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União. .', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6524, 1, '1.1.2.1.3.01.00.00.00.00', 'IMPOSTOS', 'Compreende os valores relativos aos créditos a receber, decorrentes da cobrança da modalidade de tributo cuja obrigação tem por fato gerador uma situação independente de qualquer atividade estatal específica relativa ao contribuinte.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6525, 1, '1.1.2.1.3.02.00.00.00.00', 'TAXAS', 'Compreende os valores relativos aos créditos a receber, decorrentes da cobrança da modalidade de tributo que tem como fato gerador o exercício regular do poder de polícia ou a utilização efetiva ou potencial de serviço público específico e divisível, prestado ao contribuinte ou posto à sua disposição.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6526, 1, '1.1.2.1.3.03.00.00.00.00', 'CONTRIBUIÇÕES DE MELHORIA', 'Compreende os valores relativos aos créditos a receber, decorrentes da cobrança dos valores decorrentes da contribuição instituída para fazer face ao custo de obras públicas de que decorra valorização imobiliária.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6527, 1, '1.1.2.1.3.04.00.00.00.00', 'DEMAIS CONTRIBUIÇÕES', 'Compreende os valores relativos aos créditos aos créditos a receber, decorrentes da cobrança das demais contribuições.', 1, false, 0, 'N');
