insert into contabilidade.planocontadetalhe values (6579, 1, '1.1.2.4.4.08.00.00.00.00', 'PROGRAMA DE REESTRUTURAÇÃO FISCAL', 'Compreende o somatório dos valores a receber em decorrência da assunção e refinanciamento, pela União, de dívidas de responsabilidade dos Estados e Distrito Federal, nos termos da Lei nº 9.496, de 11 de setembro de 1997.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6580, 1, '1.1.2.4.5.00.00.00.00.00', 'EMPRÉSTIMOS E FINANCIAMENTOS CONCEDIDOS-INTER OFSS - MUNICÍPIO', 'Compreende o somatório dos valores de empréstimos e financiamentos concedidos por autorizações legais ou vinculações a contratos e acordos. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6581, 1, '1.1.2.4.5.01.00.00.00.00', 'EMPRÉSTIMOS CONCEDIDOS', 'Compreende o somatório dos valores dos empréstimos concedidos por autorizações legais ou vinculações a contratos e acordos, exceto os concedidos com recursos do RPPS.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6582, 1, '1.1.2.4.5.03.00.00.00.00', 'JUROS E ENCARGOS SOBRE EMPRÉSTIMOS E FINANCIAMENTOS CONCEDIDOS A RECEBER', 'Compreende o somatório dos valores dos Juros e Encargos sobre Empréstimos e Financiamentos Concedidos a Receber.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6583, 1, '1.1.2.4.5.07.00.00.00.00', 'EMPRÉSTIMOS E FINANCIAMENTOS CONCEDIDOS COM RECURSOS PREVIDENCIÁRIOS', 'Compreende o somatório dos valores de empréstimos e financiamentos concedidos por autorizações legais ou vinculações a contratos e acordos.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6584, 1, '1.1.2.4.5.08.00.00.00.00', 'PROGRAMA DE REESTRUTURAÇÃO FISCAL', 'Compreende o somatório dos valores a receber em decorrência da assunção e refinanciamento, pela União, de dívidas de responsabilidade dos Municípios, nos termos da MP nº 2.185-35, de 24 de agosto de 2001.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6585, 1, '1.1.2.5.0.00.00.00.00.00', 'DÍVIDA ATIVA TRIBUTÁRIA', 'Compreende os valores dos créditos de dívida ativa tributária inscritos, realizáveis em até 12 meses da data das demonstrações.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6586, 1, '1.1.2.5.1.00.00.00.00.00', 'DÍVIDA ATIVA TRIBUTÁRIA - CONSOLIDAÇÃO', 'Compreende os valores dos créditos de dívida ativa tributária inscritos, realizáveis em até 12 meses da data das demonstrações. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6587, 1, '1.1.2.5.1.01.00.00.00.00', 'DÍVIDA ATIVA TRIBUTÁRIA DOS IMPOSTOS', 'Compreende os valores relativos aos créditos a receber, inscritos em dívida ativa, decorrentes da cobrança da modalidade de tributo cuja obrigação tem por fato gerador uma situação independente de qualquer atividade estatal específica relativa ao contribuinte.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6588, 1, '1.1.2.5.1.02.00.00.00.00', 'DÍVIDA ATIVA TRIBUTÁRIA DAS TAXAS', 'Compreende os valores relativos aos créditos a receber, inscritos em dívida ativa, decorrentes da cobrança da modalidade de tributo que tem como fato gerador o exercício regular do poder de polícia ou a utilização efetiva ou potencial de serviço público específico e divisível, prestado ao contribuinte ou posto a sua disposição.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6630, 1, '1.2.2.1.5.02.00.00.00.00', 'PARTICIPAÇÕES AVALIADAS PELO MÉTODO DE CUSTO', 'Compreende as participações permanentes da unidade em outras sociedades em forma de ações ou cotas, avaliadas pelo método de custo.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6589, 1, '1.1.2.5.1.03.00.00.00.00', 'DÍVIDA ATIVA DAS CONTRIBUIÇÕES DE MELHORIA', 'Compreende os valores relativos aos créditos a receber, inscritos em dívida ativa, decorrentes da cobrança dos valores decorrentes da contribuição instituída para fazer face ao custo de obras públicas de que decorra valorização imobiliária.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6590, 1, '1.1.2.5.1.04.00.00.00.00', 'DÍVIDA ATIVA DAS DEMAIS CONTRIBUIÇÕES', 'Compreende os valores relativos aos créditos a receber, inscritos em dívida ativa, decorrentes da cobrança dos valores decorrentes das demais contribuições.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6591, 1, '1.1.2.6.0.00.00.00.00.00', 'DÍVIDA ATIVA NÃO TRIBUTÁRIA ', 'Compreende os valores dos créditos de dívida ativa não tributária inscritos, derivados de clientes, realizáveis no curto prazo.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6592, 1, '1.1.2.5.2.00.00.00.00.00', 'DÍVIDA ATIVA TRIBUTÁRIA - INTRA OFSS ', 'Compreende os valores dos créditos de dívida ativa tributária inscritos, realizáveisem até 12 meses da data das demonstrações. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do ente.', 1, false, 0, 'N');
