insert into contabilidade.planocontadetalhe values (6619, 1, '1.1.3.0.0.00.00.00.00.00', 'DEMAIS CRÉDITOS E VALORES A CURTO PRAZO', 'Compreende os valores a receber por demais transações realizáveis no curto prazo.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6620, 1, '1.1.3.1.0.00.00.00.00.00', 'ADIANTAMENTOS CONCEDIDOS', 'Compreende as antecipações concedidas a pessoal (tais como antecipações de salários e ordenados, adiantamentos de 13º salário, adiantamentos de férias e outros) e a terceiros, incluídos os adiantamentos a fornecedores.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6621, 1, '1.1.3.1.1.00.00.00.00.00', 'ADIANTAMENTOS CONCEDIDOS - CONSOLIDAÇÃO', 'Compreende as antecipações concedidas à pessoal (tais como antecipações de salários e ordenados, adiantamentos de 13º salário, adiantamentos de ferias e outros) e a terceiros, incluídos os adiantamentos a fornecedores. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6622, 1, '1.1.3.1.1.01.00.00.00.00', 'ADIANTAMENTOS CONCEDIDOS A PESSOAL', 'Compreende os valores das antecipações concedidas a servidores e a dirigentes da unidade, tais como antecipações de salários e ordenados, adiantamentos de 13º salário, adiantamentos de férias e de gratificações natalinas,entre outras.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6623, 1, '1.1.3.2.0.00.00.00.00.00', 'TRIBUTOS A RECUPERAR/COMPENSAR', 'Compreende o somatório dos valores dos tributos a recuperar/compensar.', 1, false, 0, 'N');
