insert into contabilidade.planocontadetalhe values (7638, 1, '2.1.2.1.1.03.00.00.00.00', 'OUTROS EMPRÉSTIMOS A CURTO PRAZO - INTERNO', 'Compreende os empréstimos a curto prazo - interno - não enquadrados nas classificações anteriores.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (6631, 1, '1.1.3.3.0.00.00.00.00.00', 'CRÉDITOS A RECEBER POR DESCENTRALIZAÇÃO DA PRESTAÇÃO DE SERVIÇOS PÚBLICOS', 'Compreende os créditos a receber decorrentes da descentralização de serviços públicos, tanto por meio de outorga a entidades da administração indireta como por meio de delegação, nas formas de concessão, inclusive parcerias público-privada - PPP, permissão ou autorização ao particular do direito de exploração de serviços públicos.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6632, 1, '1.1.3.3.1.00.00.00.00.00', 'CRÉDITOS A RECEBER POR DESCENTRALIZAÇÃO DA PRESTAÇÃO DE SERVIÇOS PÚBLICOS - CONSOLIDAÇÃO', 'Compreende os créditos a receber decorrentes da descentralização de serviços públicos, tanto por meio de outorga a entidades da administração indireta, como por meio de delegação, nas formas de concessão, inclusive parcerias público-privada - PPP, permissão ou autorização ao particular do direito de exploração de serviços públicos. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6633, 1, '1.1.3.4.0.00.00.00.00.00', 'CRÉDITOS POR DANOS AO PATRIMÔNIO', 'Compreende os valores realizáveis no curto prazo, provenientes de direitos oriundos de danos ao patrimônio, apurados em sindicância, prestação de contas, tomada de contas, processos judiciais e outros.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6634, 1, '1.1.9.2.0.00.00.00.00.00', 'VPD FINANCEIRAS A APROPRIAR', 'Compreende os valores pagos, a título de VPD financeiras a apropriar.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6635, 1, '1.1.3.4.1.00.00.00.00.00', 'CRÉDITOS POR DANOS AO PATRIMONIO- CONSOLIDAÇÃO', 'Compreende os valores realizáveis no curto prazo, provenientes de direitos oriundos de danos ao patrimônio, apurados em sindicância, prestação de contas, tomada de contas, processos judiciais e outros. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6636, 1, '1.1.3.5.0.00.00.00.00.00', 'DEPÓSITOS RESTITUÍVEIS E VALORES VINCULADOS', 'Compreende os valores de depósitos e cauções efetuados e recebidos pela entidade para garantia de contratos, bem como para direito de uso, exploração temporária de bens ou de natureza judicial, depósitos compulsórios e demais recursos vinculados, realizáveis no curto prazo.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6637, 1, '1.1.3.5.1.00.00.00.00.00', 'DEPÓSITOS RESTITUÍVEIS E VALORES VINCULADOS - CONSOLIDAÇÃO', 'Compreende os valores de depósitos e cauções efetuados e recebidos pela entidade para garantia de contratos, bem como para direito de uso, exploração temporária de bens ou de natureza judicial, depósitos compulsórios e demais recursos vinculados, realizáveis no curto prazo. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6638, 1, '1.1.3.6.0.00.00.00.00.00', 'CRÉDITOS PREVIDENCIÁRIOS A RECEBER A CURTO PRAZO', 'Compreende os valores relativos aos créditos previdenciários a receber, realizáveis no curto prazo.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6639, 1, '1.1.3.6.1.00.00.00.00.00', 'CRÉDITOS PREVIDENCIÁRIOS A RECEBER A CURTO PRAZO - CONSOLIDAÇÃO', 'Compreende os valores relativos aos créditos previdenciários a receber, realizáveis no curto prazo. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6640, 1, '1.1.3.6.1.01.00.00.00.00', 'CONTRIBUIÇÕES PREVIDENCIÁRIAS A RECEBER - ', 'Registra os valores relativos aos créditos a receber, decorrentes das contribuições para o financiamento da previdência social.', 1, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (6641, 1, '1.1.3.6.1.02.00.00.00.00', 'CRÉDITOS PREVIDENCIÁRIOS PARCELADOS', 'Registra os valores relativos aos créditos a receber, decorrentes de créditos previdenciários parcelados.', 1, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (6642, 1, '1.1.3.6.2.00.00.00.00.00', 'CRÉDITOS PREVIDENCIÁRIOS A RECEBER A CURTO PRAZO - INTRA OFSS', 'Compreende os valores relativos aos créditos previdenciários a receber, realizáveis no curto prazo. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do ente.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6643, 1, '1.1.3.6.2.01.00.00.00.00', 'CONTRIBUIÇÕES PREVIDENCIÁRIAS A RECEBER - ', 'Registra os valores relativos aos créditos a receber, decorrentes das contribuições para o financiamento da previdência social.', 1, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (6644, 1, '1.1.3.6.2.02.00.00.00.00', 'CRÉDITOS PREVIDENCIÁRIOS PARCELADOS', 'Registra os valores relativos aos créditos a receber, decorrentes de créditos previdenciários parcelados.', 1, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (6645, 1, '1.1.3.6.2.03.00.00.00.00', 'COMPENSAÇÃO FINANCEIRA ENTRE REGIMES PREVIDENCIÁRIOS', 'Registra os valores relativos aos créditos a receber decorrentes de compensação financeira entre regimes de previdência, por contagem recíproca de tempo de contribuição.', 1, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (6646, 1, '1.1.9.3.0.00.00.00.00.00', 'ASSINATURAS E ANUIDADES A APROPRIAR', 'Compreende os valores pagos a titulo de assinaturas e anuidades a apropriar.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6647, 1, '1.1.3.6.2.99.00.00.00.00', 'OUTROS CRÉDITOS PREVIDENCIÁRIOS ', 'Registra os valores relativos a outros créditos previdenciários devidos ao RPPS pelo ente, sujeitos a pagamento em parcela única ou parcelados.', 1, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (6648, 1, '1.1.3.6.3.00.00.00.00.00', 'CRÉDITOS PREVIDENCIÁRIOS A RECEBER A CURTO PRAZO -  INTER OFSS - UNIÃO', 'Compreende os valores relativos aos créditos previdenciários a receber, realizáveis no curto prazo. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6649, 1, '1.1.3.6.3.03.00.00.00.00', 'COMPENSAÇÃO FINANCEIRA ENTRE REGIMES PREVIDENCIÁRIOS', 'Registra os valores relativos aos créditos a receber decorrentes de compensação financeira entre regimes de previdência, por contagem recíproca de tempo de contribuição.', 1, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (6650, 1, '1.1.3.6.3.99.00.00.00.00', 'OUTROS CRÉDITOS PREVIDENCIÁRIOS ', 'Registra os valores relativos a outros créditos previdenciários devidos ao RPPS pelo ente, sujeitos a pagamento em parcela única ou parcelados.', 1, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (6651, 1, '1.1.3.6.4.00.00.00.00.00', 'CRÉDITOS PREVIDENCIÁRIOS A RECEBER A CURTO PRAZO - INTER OFSS - ESTADO', 'Compreende os valores relativos aos créditos previdenciários a receber, realizáveis no curto prazo. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6652, 1, '1.1.3.6.4.03.00.00.00.00', 'COMPENSAÇÃO FINANCEIRA ENTRE REGIMES PREVIDENCIÁRIOS', 'Registra os valores relativos aos créditos a receber decorrentes de compensação financeira entre regimes de previdência, por contagem recíproca de tempo de contribuição.', 1, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (6653, 1, '5.2.1.1.2.99.00.00.00.00', '(-) OUTRAS DEDUÇÕES', 'Registra a previsão de outras deduções da receita aprovada na LOA.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (6654, 1, '1.1.3.6.5.00.00.00.00.00', 'CRÉDITOS PREVIDENCIÁRIOS A RECEBER A CURTO PRAZO - INTER OFSS - MUNICÍPIO', 'Compreende os valores relativos aos créditos previdenciários a receber, realizáveis no curto prazo. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6655, 1, '1.1.3.6.5.03.00.00.00.00', 'COMPENSAÇÃO FINANCEIRA ENTRE REGIMES PREVIDENCIÁRIOS', 'Registra os valores relativos aos créditos a receber decorrentes de compensação financeira entre regimes de previdência, por contagem recíproca de tempo de contribuição.', 1, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (6656, 1, '1.1.3.6.5.99.00.00.00.00', 'OUTROS CRÉDITOS PREVIDENCIÁRIOS ', 'Registra os valores relativos a outros créditos previdenciários devidos ao RPPS pelo ente, sujeitos a pagamento em parcela única ou parcelados.', 1, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (6657, 1, '1.1.3.8.0.00.00.00.00.00', 'OUTROS CRÉDITOS A RECEBER E VALORES A CURTO PRAZO', 'Compreende os outros créditos e valores realizáveis no curto prazo, provenientes de direitos obtidos junto a diversos devedores.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6658, 1, '1.1.3.8.1.00.00.00.00.00', 'OUTROS CRÉDITOS A RECEBER E VALORES A CURTO PRAZO - CONSOLIDAÇÃO', 'Compreende os outros créditos e valores realizáveis no curto prazo, provenientes de direitos obtidos junto a diversos devedores. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6659, 1, '1.1.4.0.0.00.00.00.00.00', 'INVESTIMENTOS E APLICAÇÕES TEMPORÁRIAS A CURTO PRAZO', 'Compreendem as aplicações de recursos em títulos e valores mobiliários, não destinadas à negociação e que não façam parte das atividades operacionais da entidade, resgatáveis no curto prazo, alem das aplicações temporárias em metais preciosos.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6660, 1, '1.1.4.1.0.00.00.00.00.00', 'TÍTULOS E VALORES MOBILIÁRIOS', 'Compreendem as aplicações de recursos em títulos e valores mobiliários, não destinadas à negociação e que não façam parte das atividades operacionais da entidade, resgatáveis no curto prazo.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6661, 1, '1.1.4.1.1.00.00.00.00.00', 'TÍTULOS E VALORES MOBILIARIOS- CONSOLIDAÇÃO', 'Compreendem as aplicações de recursos em títulos e valores mobiliários, não destinadas à negociação e que não façam parte das atividades operacionais da entidade, resgatáveis em até 12 (doze) meses da data das demonstrações. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6662, 1, '1.1.4.1.1.09.00.00.00.00', 'APLICAÇÕES EM SEGMENTO DE RENDA FIXA - RPPS', 'Compreende o somatório dos investimentos realizados pelo RPPS com recursos previdenciários, efetuados em conformidade com a legislação específica.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6663, 1, '1.1.4.1.1.10.00.00.00.00', 'APLICAÇÕES EM SEGMENTO DE RENDA VARIAVEL - RPPS', 'Compreende o somatório dos investimentos realizados pelo RPPS com recursos previdenciários, efetuados em conformidade com a legislação específica.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6664, 1, '1.1.4.1.1.11.00.00.00.00', 'APLICAÇÕES EM SEGMENTO IMOBILIARIO - RPPS', 'Compreende o somatório dos investimentos realizados pelo RPPS com recursos previdenciários não financeiros em segmento imobiliário.', 1, false, 0, 'F');
insert into contabilidade.planocontadetalhe values (6665, 1, '1.1.4.1.1.12.00.00.00.00', 'APLICAÇÕES EM ENQUADRAMENTO - RPPS', 'Compreende os investimentos realizados pelo rpps, em desacordo com as regras estabelecidas pelas Resoluções CMN nº 3.992/2010 e 4.392/2014.', 1, false, 0, 'F');
insert into contabilidade.planocontadetalhe values (6666, 1, '1.1.4.1.1.13.00.00.00.00', 'TITULOS E VALORES NAO SUJEITOS AO ENQUADRAMENTO - RPPS', 'Compreende os investimentos realizados pelo rpps, em ativos nao sujeitos as regras das Resoluções CMN nº 3.992/2010 e 4.392/2014.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6667, 1, '1.1.4.1.1.14.00.00.00.00', 'APLICAÇÕES COM A TAXA DE ADMINISTRAÇÃO DO RPPS', 'Compreende os investimentos realizados pelo rpps, com recursos da taxa de administracao, sujeitos  às regras das Resoluções CMN nº 3.992/2010 e 4.392/2014.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6668, 1, '1.1.4.2.0.00.00.00.00.00', 'APLICAÇÃO TEMPORÁRIA EM METAIS PRECIOSOS', 'Compreende as aplicações de recursos em metais preciosos, não destinados a negociação e que não façam parte das atividades operacionais da entidade, resgatáveis no curto prazo.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6669, 1, '1.1.4.2.1.00.00.00.00.00', 'APLICAÇÃO TEMPORÁRIA EM METAIS PRECIOSOS- CONSOLIDAÇÃO', 'Compreende as aplicações de recursos em metais preciosos, não destinados a negociação e que não façam parte das atividades operacionais da entidade, resgatáveis no curto prazo. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (6670, 1, '1.1.4.3.0.00.00.00.00.00', 'APLICAÇÕES EM SEGMENTO DE IMÓVEIS', 'Compreende os investimentos de longo prazo realizados em segmento de imóveis, realizáveis no curto prazo.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6671, 1, '1.1.4.3.1.00.00.00.00.00', 'APLICAÇÕES EM SEGMENTO DE IMÓVEIS - CONSOLIDAÇÃO', 'Compreende os investimentos de longo prazo realizados em segmento de imóveis, realizáveis no curto prazo. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (6672, 1, '1.1.5.0.0.00.00.00.00.00', 'ESTOQUES', 'Compreende o valor dos bens adquiridos, produzidos ou em processo de elaboração pela entidade com o objetivo de venda ou utilização própria no curso normal das atividades.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6673, 1, '1.1.5.1.0.00.00.00.00.00', 'MERCADORIAS PARA REVENDA', 'Compreende todos os produtos adquiridos de terceiros para revenda, que não sofrem nenhum processo de transformação na entidade.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6674, 1, '1.1.5.1.1.00.00.00.00.00', 'MERCADORIAS PARA REVENDA - CONSOLIDAÇÃO', 'Compreende todos os produtos adquiridos de terceiros para revenda, que não sofrem nenhum processo de transformação na entidade. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6675, 1, '1.1.5.2.0.00.00.00.00.00', 'PRODUTOS E SERVIÇOS ACABADOS', 'Compreende os produtos já terminados e oriundos da própria produção da entidade e disponíveis para venda, estocados na fabrica, ou em depósitos, ou em filiais, ou ainda com terceiros em consignação e os serviços acabados.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6676, 1, '1.1.9.2.1.00.00.00.00.00', 'VPD FINANCEIRAS A APROPRIAR - CONSOLIDAÇÃO', 'Compreende os valores pagos, a título de VPD financeiras a apropriar. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (6701, 1, '1.1.9.3.1.00.00.00.00.00', 'ASSINATURAS E ANUIDADES A APROPRIAR - CONSOLIDAÇÃO', 'Compreende os valores pagos a titulo de assinaturas e anuidades a apropriar. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (6677, 1, '1.1.5.2.1.00.00.00.00.00', 'PRODUTOS E SERVIÇOS ACABADOS - CONSOLIDAÇÃO', 'Compreende os produtos já terminados oriundos da própria produção da entidade e disponíveis para venda, estocados na fabrica, ou em depósitos, ou em filiais, ou ainda com terceiros em consignação e os serviços acabados. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6678, 1, '1.1.5.3.1.00.00.00.00.00', 'PRODUTOS E SERVIÇOS EM ELABORAÇÃO - CONSOLIDAÇÃO', 'Compreende os produtos e serviços em andamento não concluídos na data do balanço. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6679, 1, '1.1.5.4.0.00.00.00.00.00', 'MATÉRIAS-PRIMAS', 'Compreende o estoque de matérias-primas, que será utilizado no processo produtivo.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6680, 1, '1.1.5.4.1.00.00.00.00.00', 'MATÉRIAS-PRIMAS - CONSOLIDAÇÃO', 'Compreende o estoque de matérias-primas, que será utilizado no processo produtivo.. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6681, 1, '1.1.5.5.0.00.00.00.00.00', 'MATERIAIS EM TRANSITO', 'Compreende o valor dos materiais em processo de transferência para outras unidades da entidade.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6682, 1, '1.1.5.5.1.00.00.00.00.00', 'MATERIAIS EM TRANSITO - CONSOLIDAÇÃO', 'Compreende o valor dos materiais em processo de transferência para outras unidades da entidade. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6683, 1, '1.1.5.6.0.00.00.00.00.00', 'ALMOXARIFADO', 'Compreende o valor dos materiais destinados ao consumo interno da unidade.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6684, 1, '1.1.5.6.1.00.00.00.00.00', 'ALMOXARIFADO - CONSOLIDAÇÃO', 'Compreende o valor dos materiais destinados ao consumo interno da unidade. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6685, 1, '1.1.5.8.0.00.00.00.00.00', 'OUTROS ESTOQUES', 'Compreende o valor dos outros bens adquiridos, produzidos ou em processo de elaboração pela entidade com o objetivo de venda ou utilização própria no curso normal das atividades.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6686, 1, '1.1.5.8.1.00.00.00.00.00', 'OUTROS ESTOQUES - CONSOLIDAÇÃO', 'Compreende o valor dos outros bens adquiridos, produzidos ou em processo de elaboração pela entidade com o objetivo de venda ou utilização própria no curso normal das atividades. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (6687, 1, '1.1.6.0.0.00.00.00.00.00', 'ATIVO NÃO CIRCULANTE MANTIDO PARA VENDA', 'Compreende os ativos não circulantes cuja recuperação esperada do seu valor contábil venha a ocorrer por meio de uma transação de venda em vez do uso contínuo, dentro de um prazo inferior a 12 meses.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6688, 1, '1.1.6.1.0.00.00.00.00.00', 'INVESTIMENTO MANTIDO PARA VENDA', 'Compreende os ativos de investimentos mantidos para venda, segundo um plano de venda com prazo inferior a doze meses.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6689, 1, '1.1.6.1.1.00.00.00.00.00', 'INVESTIMENTO MANTIDO PARA VENDA - CONSOLIDAÇÃO', 'Compreende os ativos de investimentos mantidos para venda, segundo um plano de venda com prazo inferior a doze meses. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (6690, 1, '1.1.6.1.2.00.00.00.00.00', 'INVESTIMENTO MANTIDO PARA VENDA - INTRA OFSS', 'Compreende os ativos de investimentos mantidos para venda, segundo um plano de venda com prazo inferior a doze meses. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do ente.', 1, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (6691, 1, '1.1.6.1.3.00.00.00.00.00', 'INVESTIMENTO MANTIDO PARA VENDA - INTER OFSS - UNIÃO', 'Compreende os ativos de investimentos mantidos para venda, segundo um plano de venda com prazo inferior a doze meses. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 1, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (6692, 1, '1.1.6.1.4.00.00.00.00.00', 'INVESTIMENTO MANTIDO PARA VENDA - INTER OFSS - ESTADO', 'Compreende os ativos de investimentos mantidos para venda, segundo um plano de venda com prazo inferior a doze meses. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 1, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (6693, 1, '1.1.6.1.5.00.00.00.00.00', 'INVESTIMENTO MANTIDO PARA VENDA - INTER OFSS - MUNICÍPIO', 'Compreende os ativos de investimentos mantidos para venda, segundo um plano de venda com prazo inferior a doze meses. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município. ', 1, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (6694, 1, '1.1.6.2.0.00.00.00.00.00', 'IMOBILIZADO MANTIDO PARA VENDA', 'Compreende os ativos imobilizados mantidos para venda, segundo um plano de venda com prazo inferior a doze meses.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6695, 1, '1.1.6.2.1.00.00.00.00.00', 'IMOBILIZADO MANTIDO PARA VENDA - CONSOLIDAÇÃO', 'Compreende os ativos imobilizados mantidos para venda, segundo um plano de venda com prazo inferior a doze meses. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (6696, 1, '1.1.6.3.0.00.00.00.00.00', 'INTANGÍVEL MANTIDO PARA VENDA', 'Compreende os ativos intangíveis mantidos para venda, segundo um plano de venda com prazo inferior a doze meses.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6697, 1, '1.1.6.3.1.00.00.00.00.00', 'INTANGÍVEL MANTIDO PARA VENDA - CONSOLIDAÇÃO', 'Compreende os ativos intangíveis mantidos para venda, segundo um plano de venda com prazo inferior a doze meses. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (6698, 1, '1.1.9.0.0.00.00.00.00.00', 'VARIAÇÕES PATRIMONIAIS DIMINUTIVAS PAGAS ANTECIPADAMENTE', 'Compreende pagamentos de variações patrimoniais diminutivas (VPD) antecipadas, cujos benefícios ou prestação de serviço a entidade ocorrerão no curto prazo.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6699, 1, '1.1.9.1.0.00.00.00.00.00', 'PRÊMIOS DE SEGUROS A APROPRIAR', 'Compreende os valores pagos a titulo de prêmios de seguro a apropriar.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6700, 1, '1.1.9.1.1.00.00.00.00.00', 'PRÊMIOS DE SEGUROS A APROPRIAR - CONSOLIDAÇÃO', 'Compreende os valores pagos a titulo de prêmios de seguro a apropriar. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (6725, 1, '1.2.1.1.5.00.00.00.00.00', 'CRÉDITOS A LONGO PRAZO - INTER OFSS - MUNICÍPIO', 'Compreende os valores a receber por fornecimento de bens, serviços, créditos tributários, dívida ativa, transferências e empréstimos e financiamentos concedidos com vencimento no longo prazo. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) de entes públicos distintos, para permitir a consolidação nacional realizada pelo Poder Executivo da União. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6726, 1, '1.2.1.2.0.00.00.00.00.00', 'DEMAIS CRÉDITOS E VALORES A LONGO PRAZO', 'Compreende os valores a receber por demais transações, com vencimento no longo prazo.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6727, 1, '1.2.1.2.1.00.00.00.00.00', 'DEMAIS CRÉDITOS E VALORES A LONGO PRAZO - CONSOLIDAÇÃO', 'Compreende os valores a receber por demais transações, com vencimento no longo prazo. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6728, 1, '1.2.1.2.1.01.00.00.00.00', 'ADIANTAMENTOS CONCEDIDOS A PESSOAL E A TERCEIROS', 'Compreende as antecipações concedidas à pessoal, tais como antecipações de salários e ordenados, adiantamentos de 13º salário, adiantamentos de ferias e outros, alem da entrega de numerário a terceiros sem vinculação especifica ao fornecimento de bens ou serviços.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6729, 1, '1.2.1.2.1.02.00.00.00.00', 'TRIBUTOS A RECUPERAR/COMPENSAR', 'Compreende o somatório dos valores dos tributos a recuperar/compensar.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6730, 1, '1.2.1.2.1.04.00.00.00.00', 'CRÉDITOS POR DANOS AO PATRIMÔNIO PROVENIENTES DE CRÉDITOS ADMINISTRATIVOS', 'Compreende os valores realizáveis após os doze meses seguintes a data de publicação das demonstrações contábeis, provenientes de direitos oriundos de danos ao patrimônio, apurados em processos administrativos.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6731, 1, '1.2.1.2.1.05.00.00.00.00', 'CRÉDITOS POR DANOS AO PATRIMÔNIO APURADOS EM TOMADA DE CONTAS ESPECIAL', 'Compreende os valores realizáveis após os doze meses seguintes a data de publicação das demonstrações contábeis, provenientes de direitos oriundos de danos ao patrimônio, apurados em tomada de contas especial.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6732, 1, '1.2.1.2.1.06.00.00.00.00', 'DEPÓSITOS RESTITUÍVEIS E VALORES VINCULADOS', 'Compreende os valores de depósitos e cauções efetuados e recebidos pela entidade para garantia de contratos, bem como para direito de uso, exploração temporária de bens ou de natureza judicial, depósitos compulsórios e demais recursos vinculados, realizáveis após os doze meses seguintes a data de publicação das demonstrações contábeis.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6733, 1, '1.2.1.2.1.98.00.00.00.00', 'OUTROS CRÉDITOS A RECEBER E VALORES A LONGO PRAZO', 'Compreende os outros créditos e valores realizáveis após os doze meses seguintes a data da publicação das demonstrações contábeis, provenientes de direitos obtidos junto a diversos devedores.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6734, 1, '1.2.1.3.0.00.00.00.00.00', 'INVESTIMENTOS E APLICAÇÕES TEMPORÁRIAS A LONGO PRAZO', 'Compreende as aplicações de recursos em títulos, valores mobiliários e imobiliários, não destinadas à negociação e que não façam parte das atividades operacionais da entidade, resgatáveis no longo prazo.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6735, 1, '1.2.1.3.1.00.00.00.00.00', 'INVESTIMENTOS E APLICAÇÕES TEMPORÁRIAS A LONGO PRAZO - CONSOLIDAÇÃO', 'Compreende as aplicações de recursos em títulos, valores mobiliários e imobiliários, não destinadas à negociação e que não façam parte das atividades operacionais da entidade, resgatáveis no longo prazo. Não inclui as aplicações dos recursos do RPPS. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6736, 1, '1.2.1.3.1.01.00.00.00.00', 'TÍTULOS E VALORES MOBILIÁRIOS', 'Compreendem as aplicações de recursos em títulos e valores mobiliários, não destinadas à negociação e que não façam parte das atividades operacionais da entidade, resgatáveis após os doze meses seguintes a data da publicação das demonstrações contábeis.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6737, 1, '1.2.1.3.1.02.00.00.00.00', 'APLICAÇÃO TEMPORÁRIA EM METAIS PRECIOSOS', 'Compreendem as aplicações de recursos em metais preciosos, não destinados a negociação e que não façam parte das atividades operacionais da entidade, resgatáveis após os doze meses seguintes a data da publicação das demonstrações contábeis.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6738, 1, '1.2.1.4.0.00.00.00.00.00', 'ESTOQUES', 'Compreende o valor dos bens adquiridos, produzidos ou em processo de elaboração pela entidade para utilização própria ou para venda, previstos para período posterior os 12 (doze) meses seguintes a data da publicação das demonstrações contábeis.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6739, 1, '1.2.1.4.1.00.00.00.00.00', 'ESTOQUES - CONSOLIDAÇÃO', 'Compreende o valor dos bens adquiridos, produzidos ou em processo de elaboração pela entidade com o objetivo de venda ou utilização própria no curso normal das atividades. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6740, 1, '1.2.1.9.0.00.00.00.00.00', 'VARIAÇÕES PATRIMONIAIS DIMINUTIVAS PAGAS ANTECIPADAMENTE', 'Compreende pagamentos de variações patrimoniais diminutivas (VPD) antecipadas, cujos benefícios ou prestação de serviço à entidade ocorrerão no longo prazo.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6741, 1, '1.2.1.9.1.00.00.00.00.00', 'VARIAÇÕES PATRIMONIAIS DIMINUTIVAS PAGAS ANTECIPADAMENTE- CONSOLIDAÇÃO', 'Compreende pagamentos de variações patrimoniais diminutivas (VPD) antecipadas, cujos benefícios ou prestação de serviço a entidade ocorrerão no longo prazo. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6742, 1, '1.2.2.0.0.00.00.00.00.00', 'INVESTIMENTOS', 'Compreende as participações permanentes em outras sociedades, bem como os bens e direitos não classificáveis no ativo circulante nem no ativo realizável a longo prazo e que não se destinem a manutenção da atividade da entidade.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6743, 1, '1.2.2.1.0.00.00.00.00.00', 'PARTICIPAÇÕES PERMANENTES', 'Compreende as participações permanentes da unidade em outras entidades em forma de ações ou cotas.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6744, 1, '1.2.2.1.1.00.00.00.00.00', 'PARTICIPAÇÕES PERMANENTES - CONSOLIDAÇÃO', 'Compreende as participações permanentes da unidade em outras entidades em forma de ações ou cotas. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6745, 1, '1.2.2.1.1.01.00.00.00.00', 'PARTICIPAÇÕES AVALIADAS PELO MÉTODO DE EQUIVALÊNCIA PATRIMONIAL', 'Compreende as participações permanentes da unidade em outras entidades em forma de ações ou cotas, avaliadas pelo método de equivalência patrimonial.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6746, 1, '1.2.2.1.1.02.00.00.00.00', 'PARTICIPAÇÕES AVALIADAS PELO MÉTODO DE CUSTO', 'Compreende as participações permanentes da unidade em outras sociedades em forma de ações ou cotas, avaliadas pelo método de custo.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6747, 1, '1.2.2.1.2.00.00.00.00.00', 'PARTICIPAÇÕES PERMANENTES - INTRA OFSS', 'Compreende as participações permanentes da entidade em outras sociedades em forma de ações ou cotas. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do ente.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6748, 1, '1.2.2.1.2.01.00.00.00.00', 'PARTICIPAÇÕES AVALIADAS PELO MÉTODO DE EQUIVALÊNCIA PATRIMONIAL', 'Compreende as participações permanentes da unidade em outras entidades em forma de ações ou cotas, avaliadas pelo método de equivalência patrimonial.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6749, 1, '1.2.2.1.2.02.00.00.00.00', 'PARTICIPAÇÕES AVALIADAS PELO MÉTODO DE CUSTO', 'Compreende as participações permanentes da unidade em outras sociedades em forma de ações ou cotas, avaliadas pelo método de custo.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6750, 1, '1.2.2.1.3.00.00.00.00.00', 'PARTICIPAÇÕES PERMANENTES - INTER OFSS - UNIÃO', 'Compreende as participações permanentes da entidade em outras sociedades em forma de ações ou cotas. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6751, 1, '1.2.2.1.3.01.00.00.00.00', 'PARTICIPAÇÕES AVALIADAS PELO MÉTODO DE EQUIVALÊNCIA PATRIMONIAL', 'Compreende as participações permanentes da unidade em outras entidades em forma de ações ou cotas, avaliadas pelo método de equivalência patrimonial.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6752, 1, '1.2.2.1.3.02.00.00.00.00', 'PARTICIPAÇÕES AVALIADAS PELO MÉTODO DE CUSTO', 'Compreende as participações permanentes da unidade em outras sociedades em forma de ações ou cotas, avaliadas pelo método de custo.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6753, 1, '1.2.2.1.4.00.00.00.00.00', 'PARTICIPAÇÕES PERMANENTES - INTER OFSS - ESTADO', 'Compreende as participações permanentes da entidade em outras sociedades em forma de ações ou cotas. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6754, 1, '1.2.2.1.4.01.00.00.00.00', 'PARTICIPAÇÕES AVALIADAS PELO MÉTODO DE EQUIVALÊNCIA PATRIMONIAL', 'Compreende as participações permanentes da unidade em outras entidades em forma de ações ou cotas, avaliadas pelo método de equivalência patrimonial.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6755, 1, '1.2.2.1.4.02.00.00.00.00', 'PARTICIPAÇÕES AVALIADAS PELO MÉTODO DE CUSTO', 'Compreende as participações permanentes da unidade em outras sociedades em forma de ações ou cotas, avaliadas pelo método de custo.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6756, 1, '1.2.2.1.5.00.00.00.00.00', 'PARTICIPAÇÕES PERMANENTES - INTER OFSS - MUNICÍPIO', 'Compreende as participações permanentes da entidade em outras sociedades em forma de ações ou cotas. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6757, 1, '1.2.2.1.5.01.00.00.00.00', 'PARTICIPAÇÕES AVALIADAS PELO MÉTODO DE EQUIVALÊNCIA PATRIMONIAL', 'Compreende as participações permanentes da unidade em outras entidades em forma de ações ou cotas, avaliadas pelo método de equivalência patrimonial.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6758, 1, '1.2.3.2.1.99.00.00.00.00', 'DEMAIS BENS IMÓVEIS', 'Compreende os demais bens imóveis não classificados anteriormente nesse plano de contas.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6759, 1, '1.2.2.2.0.00.00.00.00.00', 'PROPRIEDADES PARA INVESTIMENTO', 'Compreende a propriedade (terreno ou edifício - ou parte de edifício - ou ambos) mantida (pelo proprietário ou pelo arrendatário em arrendamento financeiro) para auferir aluguel ou para valorização do capital ou para ambas, e não para: uso na produção ou fornecimento de bens ou serviços ou para finalidades administrativas; ou venda no curso ordinário do negócio.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6760, 1, '1.2.2.2.1.00.00.00.00.00', 'PROPRIEDADES PARA INVESTIMENTO - CONSOLIDAÇÃO', 'Compreende a propriedade (terreno ou edifício - ou parte de edifício - ou ambos) mantida (pelo proprietário ou pelo arrendatário em arrendamento financeiro) para auferir aluguel ou para valorização do capital ou para ambas, e não para: uso na produção ou fornecimento de bens ou serviços ou para finalidades administrativas; ou venda no curso ordinário do negócio. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6761, 1, '1.2.2.2.1.01.00.00.00.00', 'BENS IMÓVEIS PARA FUTURA UTILIZAÇÃO', 'Compreende os valores de imóveis da unidade mantidos para futura utilização.', 1, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (6762, 1, '1.2.2.2.1.02.00.00.00.00', 'BENS IMOVEIS NÃO DESTINADOS A USO', 'Compreende os valores de imóveis da unidade mantidos para geração de renda.', 1, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (6763, 1, '1.2.2.3.0.00.00.00.00.00', 'INVESTIMENTOS DO RPPS DE LONGO PRAZO', 'Compreende os investimentos realizados pelo Regime Próprio da Previdência Social, em conformidade com a legislação que trata das aplicações e investimentos dos RPPS.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6764, 1, '1.2.2.3.1.00.00.00.00.00', 'INVESTIMENTOS DO RPPS DE LONGO PRAZO - CONSOLIDAÇÃO', 'Compreende os investimentos realizados pelo Regime Próprio da Previdência Social, em conformidade com a legislação que trata das aplicações e investimentos dos RPPS. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6765, 1, '1.2.2.3.1.01.00.00.00.00', 'TITULOS E VALORES MOBILIÁRIOS - RPPS', 'Compreende os investimentos realizados pelo Regime Próprio da Previdência Social em títulos e valores mobiliários .', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6766, 1, '1.2.2.3.1.02.00.00.00.00', 'APLICAÇÕES EM SEGMENTO DE IMÓVEIS - RPPS', 'Compreende os investimentos realizados pelo Regime Próprio da Previdência Social em aplicações em segmentos de imóveis.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6767, 1, '1.2.2.7.0.00.00.00.00.00', 'DEMAIS INVESTIMENTOS PERMANENTES', 'Compreende os demais direitos de qualquer natureza não classificáveis no ativo circulante nem no ativo realizável a longo prazo e que não se destinem a manutenção das atividades da entidade.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6768, 1, '1.2.2.7.1.00.00.00.00.00', 'DEMAIS INVESTIMENTOS PERMANENTES - CONSOLIDAÇÃO', 'Compreende os demais direitos de qualquer natureza não classificáveis no ativo circulante nem no ativo realizável a longo prazo e que não se destinem a manutenção das atividades da entidade. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6769, 1, '1.2.3.0.0.00.00.00.00.00', 'IMOBILIZADO', 'Compreende os direitos que tenham por objeto bens corpóreos destinados a manutenção das atividades da entidade ou exercidos com essa finalidade, inclusive os decorrentes de operações que transfiram a ela os benefícios, os riscos e o controle desses bens.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6770, 1, '1.2.3.1.0.00.00.00.00.00', 'BENS MOVEIS', 'Compreende o valor da aquisição ou incorporação de bens corpóreos, que tem existência material e que podem ser transportados por movimento próprio ou removidos por forca alheia sem alteração da substancia ou da destinação economico-social, que constituam meio para a produção de outros bens ou serviços.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6771, 1, '1.2.3.1.1.00.00.00.00.00', 'BENS MOVEIS- CONSOLIDAÇÃO', 'Compreende o valor da aquisição ou incorporação de bens corpóreos, que tem existência material e que podem ser transportados por movimento próprio ou removidos por forca alheia sem alteração da substancia ou da destinação economico-social, que constituam meio para a produção de outros bens ou serviços. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6772, 1, '1.2.3.1.1.01.00.00.00.00', 'MÁQUINAS, APARELHOS, EQUIPAMENTOS E FERRAMENTAS', 'Compreende o valor da aquisição ou incorporação de máquinas, ferramentas, aparelhos, equipamentos, acessórios etc.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6773, 1, '1.2.3.1.1.02.00.00.00.00', 'BENS DE INFORMÁTICA', 'Compreende o valor da aquisição ou incorporação de equipamentos de processamento de dados e sistemas aplicativos, entre outros.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6774, 1, '1.2.3.1.1.03.00.00.00.00', 'MÓVEIS E UTENSÍLIOS', 'Compreende o valor da aquisição ou incorporação de mobiliário em geral e utensílios, entre outros.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6775, 1, '1.2.3.1.1.04.00.00.00.00', 'MATERIAIS CULTURAIS, EDUCACIONAIS E DE COMUNICAÇÃO', 'Compreende o valor da aquisição ou incorporação de materiais bibliográficos, discotecas, filmotecas, de comunicação, entre outros.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6776, 1, '1.2.3.1.1.05.00.00.00.00', 'VEÍCULOS', 'Compreende o valor da aquisição ou incorporação de meios de transportes aéreos, aquáticos e terrestres, entre outros.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6777, 1, '1.2.3.1.1.07.00.00.00.00', 'BENS MÓVEIS EM ANDAMENTO', 'Compreende os valores de bens móveis em andamento.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6778, 1, '1.2.3.1.1.08.00.00.00.00', 'BENS MÓVEIS EM ALMOXARIFADO', 'Compreende os valores de bens permanentes a serem estocados em almoxarifado.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6779, 1, '1.2.3.1.1.99.00.00.00.00', 'DEMAIS BENS MÓVEIS', 'Compreende o valor da aquisição ou incorporação dos demais bens móveis não classificados em grupos específicos.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6780, 1, '1.2.3.2.0.00.00.00.00.00', 'BENS IMÓVEIS', 'Compreende o valor dos bens imóveis, os quais são bens vinculados ao solo e que não podem ser retirados sem destruição ou dano, destinados ao uso e que a entidade não esteja explorando comercialmente.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6781, 1, '1.2.3.2.1.00.00.00.00.00', 'BENS IMOVEIS- CONSOLIDAÇÃO', 'Compreende o valor dos bens imóveis, os quais são bens vinculados ao solo e que não podem ser retirados sem destruição ou dano, destinados ao uso e que a entidade não esteja explorando comercialmente. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6782, 1, '1.2.3.2.1.01.00.00.00.00', 'BENS DE USO ESPECIAL', 'Compreende os bens, tais como edifícios ou terrenos destinados a serviço ou estabelecimento da administração estadual ou municipal, inclusive os de suas autarquias e fundações públicas.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6783, 1, '1.2.3.2.1.04.00.00.00.00', 'BENS DOMINICAIS', 'Compreende os bens que constituem o patrimônio das pessoas jurídicas de direito público, como objeto de direito pessoal, ou real, de cada uma dessas entidades. Compreende ainda, não dispondo a lei em contrário, os bens pertencentes as pessoas jurídicas de direito público a que se tenha dado estrutura de direito privado.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6784, 1, '1.2.3.2.1.05.00.00.00.00', 'BENS DE USO COMUM DO POVO', 'Compreende os bens de uso comum do povo construídos ou adquiridos por pessoas jurídicas de direito público.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6785, 1, '1.2.4.1.0.00.00.00.00.00', 'SOFTWARES', 'Compreende os valores dos softwares pertencentes à entidade e não integrantes a um hardware, englobando os valores referentes à sua construção, implementação e instalação.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6786, 1, '1.2.4.1.1.00.00.00.00.00', 'SOFTWARES- CONSOLIDAÇÃO', 'Compreende os valores dos softwares pertencentes à entidade e não integrantes a um hardware, englobando os valores referentes à sua construção, implementação e instalação. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6787, 1, '1.2.4.2.0.00.00.00.00.00', 'MARCAS, DIREITOS E PATENTES INDUSTRIAIS', 'Compreende os valores pertinentes a bens intangíveis, englobando os gastos com registro de marca, nome, invenções próprias, direitos de uso de comunicação e direitos autorais, alem de desembolsos a terceiros por contratos de uso de marcas, patentes ou processos de fabricação (tecnologia).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6788, 1, '1.2.4.2.1.00.00.00.00.00', 'MARCAS, DIREITOS E PATENTES INDUSTRIAIS- CONSOLIDAÇÃO', 'Compreende os valores pertinentes a bens intangíveis, englobando os gastos com registro de marca, nome, invenções próprias, direitos de uso de comunicação, direitos autorais e direitos sobre recursos naturais, alem de desembolsos a terceiros por contratos de uso de marcas, patentes ou processos de fabricação (tecnologia). Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6789, 1, '1.2.4.3.0.00.00.00.00.00', 'DIREITO DE USO DE IMÓVEIS', 'Compreende os valores pertinentes a bens intangíveis representados pela aquisição do direito de uso de imóveis.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6790, 1, '1.2.4.3.1.00.00.00.00.00', 'DIREITO DE USO DE IMOVEIS- CONSOLIDAÇÃO', 'Compreende os valores pertinentes a bens intangíveis representados pela aquisição de direito de uso de imóveis. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (6791, 1, '1.2.5.0.0.00.00.00.00.00', 'DIFERIDO', 'Compreende as despesas pré-operacionais e os gastos de reestruturação que contribuirão, efetivamente, para o aumento do resultado de mais de um exercício social e que não configurem tão somente uma redução de custos ou acréscimo na eficiência operacional. Compreende os saldos compreendedos até 2008 e que deverão ser integralmente amortizados até 2017.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6792, 1, '1.2.5.1.0.00.00.00.00.00', 'GASTOS DE IMPLANTAÇÃO E PRÉ-OPERACIONAIS', 'Compreende os gastos com novos empreendimentos, incorridos antes do início de suas operações. Compreende os saldos Compreendedos até 2008 e que deverão ser integralmente amortizados até 2017.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6793, 1, '1.2.5.1.1.00.00.00.00.00', 'GASTOS DE IMPLANTAÇÃO E PRÉ-OPERACIONAIS - CONSOLIDAÇÃO', 'Registra os gastos com novos empreendimentos, incorridos antes do início de suas operações. Compreende os saldos registrados até 2008 e que deverão ser integralmente amortizados até 2017. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (6794, 1, '1.2.5.2.0.00.00.00.00.00', 'GASTOS DE REORGANIZAÇÃO', 'Compreende os gastos com a reorganização, que contribuirão, efetivamente, para o aumento do resultado de mais de um exercício social, registrados até 2008 e que deverão ser integralmente amortizados até 2017.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6795, 1, '1.2.5.2.1.00.00.00.00.00', 'GASTOS DE REORGANIZAÇÃO - CONSOLIDAÇÃO', 'Compreende os gastos com a reorganização, que contribuirão, efetivamente, para o aumento do resultado de mais de um exercício social, registrados até 2008 e que deverão ser integralmente amortizados até 2017. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (6796, 1, '3.9.9.6.0.00.00.00.00.00', 'INDENIZAÇÕES E RESTITUIÇÕES', ' Compreende as variações patrimoniais diminutivas provenientes de indenizações e/ou restituições diversas, não especificadas no plano de contas.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6797, 1, '2.3.9.0.0.00.00.00.00.00', '(-) AÇÕES/COTAS EM TESOURARIA', 'Compreende o valor das ações ou cotas da entidade que foram adquiridas pela própria entidade.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6798, 1, '2.1.2.8.0.00.00.00.00.00', '(-) ENCARGOS FINANCEIROS A APROPRIAR - INTERNO', 'Compreende os encargos financeiros estabelecidos em valores prefixados, inclusos como contrapartida nas contas de empréstimo e de financiamento a curto prazo - interno, mas que ainda não transcorreram por não ter ocorrido ainda o fato gerador.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6799, 1, '2.1.2.8.1.00.00.00.00.00', '(-) ENCARGOS FINANCEIROS A APRORIAR - INTERNO - CONSOLIDAÇÃO', 'Compreende os encargos financeiros estabelecidos em valores prefixados, inclusos como contrapartida nas contas de empréstimo e de financiamento a curto prazo - interno, mas que ainda não transcorreram por não ter ocorrido ainda o fato gerador. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6800, 1, '2.1.2.8.3.00.00.00.00.00', '(-) ENCARGOS FINANCEIROS A APRORIAR - INTERNO - INTER OFSS - UNIÃO', 'Compreende os encargos financeiros estabelecidos em valores prefixados, inclusos como contrapartida nas contas de empréstimo e de financiamento a curto prazo - interno, mas que ainda não transcorreram por não ter ocorrido ainda o fato gerador. ompreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6801, 1, '2.1.2.8.4.00.00.00.00.00', '(-) ENCARGOS FINANCEIROS A APROPRIAR - INTERNO - INTER OFSS - ESTADO', 'Compreende os encargos financeiros estabelecidos em valores prefixados, inclusos como contrapartida nas contas de empréstimo e de financiamento a curto prazo - interno, mas que ainda não transcorreram por não ter ocorrido ainda o fato gerador. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6802, 1, '2.1.2.8.5.00.00.00.00.00', '(-) ENCARGOS FINANCEIROS A APRORIAR - INTERNO - INTER OFSS - MUNICÍPIO', 'Compreende os encargos financeiros estabelecidos em valores prefixados, inclusos como contrapartida nas contas de empréstimo e de financiamento a curto prazo - interno, mas que ainda não transcorreram por não ter ocorrido ainda o fato gerador. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 1, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (6803, 1, '2.1.2.9.0.00.00.00.00.00', '(-) ENCARGOS FINANCEIROS A APROPRIAR - EXTERNO', 'Compreende os encargos financeiros estabelecidos em valores prefixados, inclusos como contrapartida nas contas de empréstimo e de financiamento a curto prazo - externo, mas que ainda não transcorreram por não ter ocorrido ainda o fato gerador.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6804, 1, '2.1.2.9.1.00.00.00.00.00', '(-) ENCARGOS FINANCEIROS A APROPRIAR- CONSOLIDAÇÃO', 'Compreende os encargos financeiros estabelecidos em valores prefixados, inclusos como contrapartida nas contas de empréstimo e de financiamento a curto prazo - externo, mas que ainda não transcorreram por não ter ocorrido ainda o fato gerador. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6805, 1, '2.2.2.8.0.00.00.00.00.00', '(-) ENCARGOS FINANCEIROS A APROPRIAR - INTERNO', 'Compreende os encargos financeiros estabelecidos em valores prefixados, inclusos como contrapartida nas contas de empréstimo e de financiamento a longo prazo - interno, mas que ainda não transcorreram por não ter ocorrido ainda o fato gerador.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6806, 1, '2.2.2.8.1.00.00.00.00.00', '(-) ENCARGOS FINANCEIROS A APROPRIAR - INTERNO - CONSOLIDAÇÃO', 'Compreende os encargos financeiros estabelecidos em valores prefixados, inclusos como contrapartida nas contas de empréstimo e de financiamento a longo prazo - interno, mas que ainda não transcorreram por não ter ocorrido ainda o fato gerador. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6807, 1, '2.2.2.8.3.00.00.00.00.00', '(-) ENCARGOS FINANCEIROS A APROPRIAR - INTERNO - INTER OFSS - UNIÃO', 'Compreende os encargos financeiros estabelecidos em valores prefixados, inclusos como contrapartida nas contas de empréstimo e de financiamento a longo prazo - interno, mas que ainda não transcorreram por não ter ocorrido ainda o fato gerador. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 1, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (6808, 1, '2.2.2.8.4.00.00.00.00.00', '(-) ENCARGOS FINANCEIROS A APROPRIAR - INTERNO - INTER OFSS - ESTADO', 'Compreende os encargos financeiros estabelecidos em valores prefixados, inclusos como contrapartida nas contas de empréstimo e de financiamento a longo prazo - interno, mas que ainda não transcorreram por não ter ocorrido ainda o fato gerador. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 1, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (6870, 1, '3.1.9.0.0.00.00.00.00.00', 'OUTRAS VARIAÇÕES PATRIMONIAIS DIMINUTIVAS - PESSOAL E ENCARGOS', 'Compreende outras variações patrimoniais diminutivas, relacionadas com pessoal e encargos, não abrangidas nos grupos anteriores, tais como as indenizações e restituições trabalhistas.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6809, 1, '2.2.2.8.5.00.00.00.00.00', '(-) ENCARGOS FINANCEIROS A APROPRIAR - INTERNO - INTER OFSS - MUNICÍPIO', 'Compreende os encargos financeiros estabelecidos em valores prefixados, inclusos como contrapartida nas contas de empréstimo e de financiamento a longo prazo - interno, mas que ainda não transcorreram por não ter ocorrido ainda o fato gerador. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 1, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (6810, 1, '2.2.2.9.0.00.00.00.00.00', '(-) ENCARGOS FINANCEIROS A APROPRIAR - EXTERNO', 'Compreende os encargos financeiros estabelecidos em valores prefixados, inclusos como contrapartida nas contas de empréstimo e de financiamento a longo prazo - externo, mas que ainda não transcorreram por não ter ocorrido ainda o fato gerador.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6811, 1, '2.2.2.9.1.00.00.00.00.00', '(-) ENCARGOS FINANCEIROS A APROPRIAR - EXTERNO - CONSOLIDAÇÃO', 'Compreende os encargos financeiros estabelecidos em valores prefixados, inclusos como contrapartida nas contas de empréstimo e de financiamento a longo prazo - externo, mas que ainda não transcorreram por não ter ocorrido ainda o fato gerador. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6812, 1, '2.2.9.2.0.00.00.00.00.00', '(-) CUSTO DIFERIDO', 'Compreende o custo relacionado às variações patrimoniais aumentativas (VPA) diferidas.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6813, 1, '2.2.9.2.1.00.00.00.00.00', '(-) CUSTO DIFERIDO - CONSOLIDAÇÃO', 'Compreende o custo relacionado às variações patrimoniais aumentativas (VPA) diferidas. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (6814, 1, '3.2.1.1.1.01.00.00.00.00', 'PROVENTOS - PESSOAL CIVIL', 'Compreende as Variações Patrimoniais Diminutivas com a concessão de aposentadoria a Pessoal Civil. ', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6815, 1, '3.2.9.3.1.10.00.00.00.00', 'SALARIO-FAMILIA', 'Registra as variações patrimoniais diminutivas com salário-família.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6816, 1, '2.3.9.1.1.00.00.00.00.00', '(-) AÇÕES EM TESOURARIA - CONSOLIDAÇÃO', 'Registra o valor das ações da entidade que foram adquiridas pela própria entidade. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6817, 1, '2.3.9.1.2.00.00.00.00.00', '(-) AÇÕES EM TESOURARIA - INTRA OFSS', 'Registra o valor das ações da entidade que foram adquiridas pela própria entidade. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do mesmo ente.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6818, 1, '2.3.9.1.3.00.00.00.00.00', '(-) AÇÕES EM TESOURARIA - INTER OFSS - UNIÃO', 'Registra o valor das ações da entidade que foram adquiridas pela própria entidade. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6819, 1, '2.3.9.1.4.00.00.00.00.00', '(-) AÇÕES EM TESOURARIA - INTER OFSS - ESTADO', 'Registra o valor das ações da entidade que foram adquiridas pela própria entidade. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6820, 1, '2.3.9.1.5.00.00.00.00.00', '(-) AÇÕES EM TESOURARIA - INTER OFSS - MUNICÍPIO', 'Registra o valor das ações da entidade que foram adquiridas pela própria entidade. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6821, 1, '2.3.9.2.0.00.00.00.00.00', '(-) COTAS EM TESOURARIA', 'Compreende o valor das cotas da entidade que foram adquiridas pela própria entidade.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6822, 1, '2.3.9.2.1.00.00.00.00.00', '(-) COTAS EM TESOURARIA - CONSOLIDAÇÃO', 'Registra o valor das cotas da entidade que foram adquiridas pela própria entidade. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6823, 1, '2.3.9.2.2.00.00.00.00.00', '(-) COTAS EM TESOURARIA - INTRA OFSS', 'Registra o valor das cotas da entidade que foram adquiridas pela própria entidade. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do mesmo ente.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6824, 1, '2.3.9.2.3.00.00.00.00.00', '(-) COTAS EM TESOURARIA - INTER OFSS - UNIÃO', 'Registra o valor das cotas da entidade que foram adquiridas pela própria entidade. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6825, 1, '2.3.9.2.4.00.00.00.00.00', '(-) COTAS EM TESOURARIA - INTER OFSS - ESTADO', 'Registra o valor das cotas da entidade que foram adquiridas pela própria entidade. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6826, 1, '2.3.9.2.5.00.00.00.00.00', '(-) COTAS EM TESOURARIA - INTER OFSS - MUNICÍPIO', 'Registra o valor das cotas da entidade que foram adquiridas pela própria entidade. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6827, 1, '3.0.0.0.0.00.00.00.00.00', 'VARIAÇÃO PATRIMONIAL DIMINUTIVA', 'Compreende o decréscimo no beneficio econômico durante o período contábil sob a forma de saída de recurso ou redução de ativo ou incremento em passivo, que resulte em decréscimo do patrimônio liquido e que não seja proveniente de distribuição aos proprietários da entidade.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6828, 1, '3.1.0.0.0.00.00.00.00.00', 'PESSOAL E ENCARGOS', 'Compreende a remuneração do pessoal ativo civil ou militar, correspondente ao somatório das variações patrimoniais diminutivas com subsídios, vencimentos, soldos e vantagens pecuniárias fixas ou variáveis estabelecidas em lei decorrentes do pagamento pelo efetivo exercício do cargo, emprego ou função de confiança no setor público. Compreende ainda, obrigações trabalhistas de responsabilidade do empregador, incidentes sobre a folha de pagamento dos órgãos e demais entidades do setor público, contribuições a entidades fechadas de previdência e benefícios eventuais a pessoal civil e militar, destacados os custos de pessoal e encargos inerentes as mercadorias e produtos vendidos e serviços prestados.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6829, 1, '3.1.1.0.0.00.00.00.00.00', 'REMUNERAÇÃO A PESSOAL', 'Compreende a remuneração do pessoal ativo civil ou militar, correspondente ao somatório das variações patrimoniais diminutivas com subsídios, vencimentos, soldos e vantagens pecuniárias fixas e variáveis estabelecidas em lei decorrentes do pagamento pelo efetivo exercício do cargo, emprego ou função de confiança no setor público, bem como as com contratos de terceirização de mão de obra que se refiram à substituição de servidores e empregados públicos.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6830, 1, '3.1.1.1.0.00.00.00.00.00', 'REMUNERAÇÃO A PESSOAL ATIVO CIVIL - ABRANGIDOS PELO RPPS', 'Compreende a remuneração do pessoal ativo civil abrangidos pelo RPPS, correspondente ao somatório das variações patrimoniais diminutivas com subsídios, vencimentos e vantagens pecuniárias fixas e variáveis estabelecidas em lei decorrentes do pagamento pelo efetivo exercício do cargo ou função de confiança no setor público.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6831, 1, '3.1.1.1.1.00.00.00.00.00', 'REMUNERAÇÃO A PESSOAL ATIVO CIVIL - ABRANGIDOS PELO RPPS - CONSOLIDAÇÃO', 'Compreende a remuneração do pessoal ativo civil abrangidos pelo RPPS, correspondente ao somatório das variações patrimoniais diminutivas com subsídios, vencimentos e vantagens pecuniárias fixas e variáveis estabelecidas em lei decorrentes do pagamento pelo efetivo exercício do cargo ou função de confiança no setor público. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6832, 1, '3.1.1.1.1.01.00.00.00.00', 'VENCIMENTOS E VANTAGENS FIXAS - PESSOAL CIVIL - RPPS', 'Compreende o somatorio dos valores com vencimentos e vantagens fixas do pessoal civil do tipo: gratificacao, representacao, adicional insalubridade, férias, 13 salário, licenca-premio, abono pecuniario, adicional noturno, etc.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6833, 1, '3.1.1.1.1.02.00.00.00.00', 'OUTRAS DESPESAS VARIAVEIS - PESSOAL CIVIL - RPPS', 'Compreende o valor de outras despesas variáveis - Pessoal Civil - RPPS.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6834, 1, '3.1.1.2.0.00.00.00.00.00', 'REMUNERAÇÃO A PESSOAL ATIVO CIVIL - ABRANGIDOS PELO RGPS', 'Compreende a remuneração do pessoal ativo civil abrangidos pelo RGPS, correspondente ao somatório das variações patrimoniais diminutivas com vencimentos e vantagens pecuniárias fixas e variáveis estabelecidas em lei decorrentes do pagamento pelo efetivo exercício do emprego, inclusive os ocupantes de cargos em comissão não investidos em cargo efetivo, no setor público.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6835, 1, '3.1.1.2.1.00.00.00.00.00', 'REMUNERAÇÃO A PESSOAL ATIVO CIVIL - ABRANGIDOS PELO RGPS - CONSOLIDAÇÃO', 'Compreende a remuneração do pessoal ativo civil abrangidos pelo RGPS, correspondente ao somatório das variações patrimoniais diminutivas com vencimentos e vantagens pecuniárias fixas e variáveis estabelecidas em lei decorrentes do pagamento pelo efetivo exercício do emprego, inclusive os ocupantes de cargos em comissão não investidos em cargo efetivo, no setor público. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6836, 1, '3.1.1.2.1.01.00.00.00.00', 'VENCIMENTOS E VANTAGENS FIXAS - PESSOAL CIVIL - RGPS', 'Compreende o somatório dos valores com vencimentos e vantagens fixas do pessoal civil do tipo: gratificação, representação, adicional insalubridade, ferias, 13º salário, licença-prêmio, abono pecuniário, adicional noturno, etc.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6837, 1, '3.1.2.9.0.00.00.00.00.00', 'OUTROS ENCARGOS PATRONAIS', 'Compreende outras variações patrimoniais diminutivas, relacionadas aos encargos patronais, não abrangidas nos grupos anteriores.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6838, 1, '3.1.1.2.1.02.00.00.00.00', 'OUTRAS VPD VARIAVEIS - PESSOAL CIVIL - RGPS  ', 'Compreende o valor de outras VPD variáveis - pessoal civil RGPS.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6839, 1, '3.1.1.2.1.04.00.00.00.00', 'CONTRATAÇÃO POR TEMPO DETERMINADO     ', 'Compreende as variações patrimoniais diminutivas com contratação por tempo determinado.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6840, 1, '3.1.1.3.0.00.00.00.00.00', 'REMUNERAÇÃO A PESSOAL ATIVO MILITAR - ABRANGIDOS PELO  RPPS', 'Compreende a remuneração do pessoal ativo militar, abrangidos por regime próprio dos militares ou não, correspondente ao somatório das variações patrimoniais diminutivas com soldos e vantagens pecuniárias fixas e variáveis estabelecidas em lei decorrentes do pagamento pelo efetivo exercício do cargo ou função de confiança no setor público.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6841, 1, '3.1.1.3.1.00.00.00.00.00', 'REMUNERAÇÃO A PESSOAL  ATIVO MILITAR - ABRANGIDOS PELO RPPS - CONSOLIDAÇÃO', 'Compreende a remuneração do pessoal ativo militar, abrangidos por regime próprio dos militares ou não, correspondente ao somatório das variações patrimoniais diminutivas com soldos e vantagens pecuniárias fixas e variáveis estabelecidas em lei decorrentes do pagamento pelo efetivo exercício do cargo ou função de confiança no setor público. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6842, 1, '3.1.1.3.1.01.00.00.00.00', 'VENCIMENTOS E VANTAGENS FIXAS - PES. MILITAR', 'Compreende a remuneração do pessoal ativo militar, correspondente ao somatório das variações patrimoniais diminutivas com vencimentos e vantagens.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6843, 1, '3.1.1.3.1.02.00.00.00.00', 'OUTRAS DESPESAS VARIAVEIS - PESSOAL MILITAR', 'Compreende a remuneração do pessoal ativo militar, correspondente ao somatório de outras variações patrimoniais diminutivas variáveis.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6844, 1, '3.1.2.0.0.00.00.00.00.00', 'ENCARGOS PATRONAIS', 'Compreende os encargos trabalhistas de responsabilidade do empregador, incidentes sobre a folha de pagamento dos servidores e empregados ativos, pertencentes aos órgãos e demais entidades do setor público, bem como contribuições a entidades fechadas de previdência e ainda outras contribuições patronais.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6845, 1, '3.1.2.1.0.00.00.00.00.00', 'ENCARGOS PATRONAIS - RPPS', 'Compreende os encargos trabalhistas de responsabilidade do empregador, incidentes sobre a folha de pagamento dos servidores públicos ativos, pertencentes aos órgãos e demais entidades do setor público.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6846, 1, '3.1.2.1.1.00.00.00.00.00', 'ENCARGOS PATRONAIS - RPPS - CONSOLIDAÇÃO', 'Compreende os encargos trabalhistas de responsabilidade do empregador, incidentes sobre a folha de pagamento dos servidores públicos ativos, pertencentes aos órgãos e demais entidades do setor público.  Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6847, 1, '3.1.2.1.2.00.00.00.00.00', 'ENCARGOS PATRONAIS - RPPS - INTRA OFSS', 'Compreende os encargos trabalhistas de responsabilidade do empregador, incidentes sobre a folha de pagamento dos servidores públicos ativos, pertencentes aos órgãos e demais entidades do setor público. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do ente.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6848, 1, '3.1.2.1.3.00.00.00.00.00', 'ENCARGOS PATRONAIS - RPPS - INTER OFSS - UNIÃO', 'Compreende os encargos trabalhistas de responsabilidade do empregador, incidentes sobre a folha de pagamento dos servidores públicos ativos, pertencentes aos órgãos e demais entidades do setor público.  Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6849, 1, '3.1.2.1.4.00.00.00.00.00', 'ENCARGOS PATRONAIS - RPPS - INTER OFSS - ESTADO', 'Compreende os encargos trabalhistas de responsabilidade do empregador, incidentes sobre a folha de pagamento dos servidores públicos ativos, pertencentes aos órgãos e demais entidades do setor público.  Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6850, 1, '3.1.2.1.5.00.00.00.00.00', 'ENCARGOS PATRONAIS - RPPS - INTER OFSS - MUNICÍPIO', 'Compreende os encargos trabalhistas de responsabilidade do empregador, incidentes sobre a folha de pagamento dos servidores públicos ativos, pertencentes aos órgãos e demais entidades do setor público.  Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6851, 1, '3.1.2.2.0.00.00.00.00.00', 'ENCARGOS PATRONAIS - RGPS', 'Compreende os encargos trabalhistas de responsabilidade do empregador, incidentes sobre a folha de pagamento dos empregados ativos, pertencentes aos órgãos e demais entidades do setor público, bem como ocupantes de cargo em comissão não investidos, em cargo efetivo.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6852, 1, '3.1.2.2.1.00.00.00.00.00', 'ENCARGOS PATRONAIS - RGPS - CONSOLIDAÇÃO', 'Compreende os encargos trabalhistas de responsabilidade do empregador, incidentes sobre a folha de pagamento dos empregados ativos, pertencentes aos órgãos e demais entidades do setor público, bem como ocupantes de cargo em comissão não investido em cargo efetivo. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6853, 1, '3.1.2.2.2.00.00.00.00.00', 'ENCARGOS PATRONAIS - RGPS - INTRA OFSS', 'Compreende os encargos trabalhistas de responsabilidade do empregador, incidentes sobre a folha de pagamento dos empregados ativos, pertencentes aos órgãos e demais entidades do setor público, bem como ocupantes de cargo em comissão não investido em cargo efetivo. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do ente.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6854, 1, '3.1.2.2.3.00.00.00.00.00', 'ENCARGOS PATRONAIS - RGPS - INTER OFSS - UNIÃO', 'Compreende os encargos trabalhistas de responsabilidade do empregador, incidentes sobre a folha de pagamento dos empregados ativos, pertencentes aos órgãos e demais entidades do setor público, bem como ocupantes de cargo em comissão não investido em cargo efetivo. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6855, 1, '3.1.2.3.0.00.00.00.00.00', 'ENCARGOS PATRONAIS - FGTS', 'Compreende os valores recolhidos mensalmente pelos empregadores, em conta bancaria vinculada do trabalhador no FGTS, correspondente a percentual definido em lei sobre a remuneração paga ou devida, no mês anterior, a cada trabalhador, incluídas na remuneração as parcelas de que tratam os artigos. 457 e 458 da CLT e a gratificação de natal a que se refere à lei nº 4.090, de 13 de julho de 1962, com as modificações da lei nº 4.749, de 12 de agosto de 1965. Entende-se por empregador a pessoa física ou a pessoa jurídica de direito privado ou de direito público, da administração pública direta, indireta ou fundacional de qualquer dos poderes, da União, dos estados, do distrito federal e dos municípios, que admitir trabalhadores a seu serviço, bem assim aquele que, regido por legislação especial, encontrar-se nessa condição ou figurar como fornecedor ou tomador de mão de obra, independente da responsabilidade solidaria e/ou subsidiaria a que eventualmente venha obrigar-se. Considera-se trabalhador toda pessoa física que prestar serviços a empregador, a locador ou tomador de mão de obra, excluídos os eventuais, os autônomos e os servidores públicos civis e militares sujeitos a regime jurídico próprio. O recolhimento do FGTS e obrigatório também nos casos de afastamento para prestação do serviço militar obrigatório e licença por acidente do trabalho. Não se incluem na remuneração, para os fins desta lei, as parcelas elencadas no § 9º do art. 28 da lei nº 8.212, de 24 de julho de 1991.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6856, 1, '3.1.3.3.1.00.00.00.00.00', 'BENEFÍCIOS A PESSOAL - MILITAR - CONSOLIDAÇÃO', 'Compreende o valor total das variações patrimoniais diminutivas com benefícios devidos a pessoal militar, tais como: adicional de compensação orgânica não incorporada, gratificação de localidade especial, gratificação de representação, transporte, ajuda-de-custo, auxílio-fardamento, auxílio-alimentação e outros benefícios eventuais relativos ao local ou a natureza do trabalho. Estão excluídos deste grupo os soldos e quaisquer outras vantagens pecuniárias permanentes, bem como as os benefícios previdenciários ou assistenciais, tais como: aposentadoria, auxílio-natalidade, salário-família, licença para tratamento de saúde, licença a gestante, a adotante e licença-maternidade, licença por acidente em serviço, assistência a saúde, garantia de condições individuais e ambientais de trabalho satisfatórias, pensão vitalícia e temporária, auxílio-funeral, auxílio-reclusão, auxílio-invalidez, assistência a saúde. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6871, 1, '3.1.9.1.0.00.00.00.00.00', 'INDENIZAÇÕES E RESTITUIÇÕES TRABALHISTAS', 'Compreende o valor total com variações patrimoniais diminutivas resultante do pagamento efetuado a servidores públicos civis e empregados de entidades integrantes da administração pública, inclusive ferias e aviso prévio indenizados, multas e contribuições incidentes sobre os depósitos do fundo de garantia por tempo de serviço, etc., em função da perda da condição de servidor ou empregado, podendo ser em decorrência da participação em programa de desligamento voluntario.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6872, 1, '3.2.2.9.1.00.00.00.00.00', 'OUTRAS PENSÕES - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais diminutivas provenientes de outras pensões. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6904, 1, '3.2.2.3.1.00.00.00.00.00', 'PENSÕES - PESSOAL MILITAR - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais diminutivas com pagamento de pensões aos dependentes dos militares, após seu óbito, regidos pelo regime próprio. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6857, 1, '3.1.2.3.1.00.00.00.00.00', 'ENCARGOS PATRONAIS - FGTS - CONSOLIDAÇÃO', 'Compreende os valores recolhidos mensalmente pelos empregadores, em conta bancaria vinculada do trabalhador no FGTS, correspondente a percentual definido em lei sobre a remuneração paga ou devida, no mês anterior, a cada trabalhador, incluídas na remuneração as parcelas de que tratam os artigos. 457 e 458 da CLT e a gratificação de natal a que se refere à lei nº 4.090, de 13 de julho de 1962, com as modificações da lei nº 4.749, de 12 de agosto de 1965. Entende-se por empregador a pessoa física ou a pessoa jurídica de direito privado ou de direito público, da administração pública direta, indireta ou fundacional de qualquer dos poderes, da União, dos estados, do distrito federal e dos municípios, que admitir trabalhadores a seu serviço, bem assim aquele que, regido por legislação especial, encontrar-se nessa condição ou figurar como fornecedor ou tomador de mão de obra, independente da responsabilidade solidaria e/ou subsidiaria a que eventualmente venha obrigar-se. Considera-se trabalhador toda pessoa física que prestar serviços a empregador, a locador ou tomador de mão de obra, excluídos os eventuais, os autônomos e os servidores públicos civis e militares sujeitos a regime jurídico próprio. O recolhimento do FGTS e obrigatório também nos casos de afastamento para prestação do serviço militar obrigatório e licença por acidente do trabalho. Não se incluem na remuneração, para os fins desta lei, as parcelas elencadas no § 9º do art. 28 da lei nº 8.212, de 24 de julho de 1991. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6858, 1, '3.1.2.4.0.00.00.00.00.00', 'CONTRIBUIÇÕES SOCIAIS GERAIS', 'Compreende os encargos patronais relativos ao salário educação e as contribuições compulsórias dos empregadores sobre a folha de salários, destinados as entidades privadas de serviço social e de formação profissional, vinculadas ao sistema sindical, tais como SESI, SENAI, SESC e SENAC.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6859, 1, '3.1.2.4.1.00.00.00.00.00', 'CONTRIBUIÇÕES SOCIAIS GERAIS - CONSOLIDAÇÃO', 'Compreende os encargos patronais relativos ao salário educação e as contribuições compulsórias dos empregadores sobre a folha de salários, destinados as entidades privadas de serviço social e de formação profissional, vinculadas ao sistema sindical, tais como SESI, SENAI, SESC e SENAC. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6860, 1, '3.1.2.5.0.00.00.00.00.00', 'CONTRIBUIÇÕES A ENTIDADES FECHADAS DE PREVIDÊNCIA', 'Compreende o valor total das variações patrimoniais diminutivas relacionadas ao regime de previdência privada, de caráter complementar, organizado de forma autônoma em relação ao regime geral de previdência social, de caráter facultativo, baseado na constituição de reservas que garantam o benefício, nos termos do caput do art. 202 da constituição federal. Entende-se por entidades fechadas aquelas acessíveis, na forma regulamentada pelo órgão regulador e fiscalizador, exclusivamente aos empregados de uma empresa ou grupo de empresas e aos servidores da União, dos estados, do distrito federal e dos municípios, entes denominados patrocinadores.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6861, 1, '3.2.9.9.0.00.00.00.00.00', 'OUTROS BENEFÍCIOS PREVIDENCIÁRIOS E ASSISTENCIAIS', 'Compreende as variações patrimoniais diminutivas provenientes de outros benefícios previdenciários e assistenciais', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6862, 1, '3.2.1.1.1.00.00.00.00.00', 'APOSENTADORIAS - RPPS - CONSOLIDAÇÃO', 'Compreendem os benefícios de prestação continuada assegurados pela previdência social com o objetivo de garantir meios indispensáveis de manutenção, por motivo de incapacidade, idade avançada e tempo de serviço, abrangidas pelo RPPS. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6863, 1, '4.3.1.9.0.00.00.00.00.00', '(-) DEDUÇÕES DA VENDA BRUTA DE MERCADORIAS', 'Compreende as deduções das vendas de mercadorias, como devoluções, abatimentos e descontos comerciais concedidos.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6864, 1, '3.1.2.5.1.00.00.00.00.00', 'CONTRIBUIÇÕES A ENTIDADES FECHADAS DE PREVIDÊNCIA - CONSOLIDAÇÃO', 'Compreende o valor total das variações patrimoniais diminutivas relacionadas ao regime de previdência privada, de caráter complementar, organizado de forma autônoma em relação ao regime geral de previdência social, de caráter facultativo, baseado na constituição de reservas que garantam o benefício, nos termos do caput do art. 202 da constituição federal. Entende-se por entidades fechadas aquelas acessíveis, na forma regulamentada pelo órgão regulador e fiscalizador, exclusivamente aos empregados de uma empresa ou grupo de empresas e aos servidores da União, dos estados, do distrito federal e dos municípios, entes denominados patrocinadores. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6865, 1, '3.1.2.9.1.00.00.00.00.00', 'OUTROS ENCARGOS PATRONAIS - CONSOLIDAÇÃO', 'Compreende outras variações patrimoniais diminutivas, relacionadas aos encargos patronais, não abrangidas nos grupos anteriores. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6866, 1, '3.1.2.9.2.00.00.00.00.00', 'OUTROS ENCARGOS PATRONAIS - INTRA OFSS', 'Compreende outras variações patrimoniais diminutivas, relacionadas aos encargos patronais, não abrangidas nos grupos anteriores. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do ente.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6867, 1, '3.1.2.9.3.00.00.00.00.00', 'OUTROS ENCARGOS PATRONAIS - INTER OFSS - UNIÃO', 'Compreende outras variações patrimoniais diminutivas, relacionadas aos encargos patronais, não abrangidas nos grupos anteriores. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6868, 1, '3.1.2.9.4.00.00.00.00.00', 'OUTROS ENCARGOS PATRONAIS - INTER OFSS - ESTADO', 'Compreende outras variações patrimoniais diminutivas, relacionadas aos encargos patronais, não abrangidas nos grupos anteriores. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6869, 1, '3.1.2.9.5.00.00.00.00.00', 'OUTROS ENCARGOS PATRONAIS - INTER OFSS - MUNICÍPIO', 'Compreende outras variações patrimoniais diminutivas, relacionadas aos encargos patronais, não abrangidas nos grupos anteriores. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6905, 1, '3.2.2.9.0.00.00.00.00.00', 'OUTRAS PENSÕES', 'Compreende as variações patrimoniais diminutivas provenientes de outras pensões.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6873, 1, '3.1.3.0.0.00.00.00.00.00', 'BENEFÍCIOS A PESSOAL', 'Compreende o valor total das variações patrimoniais diminutivas com benefícios devidos a pessoal civil e militar , tais como para o pessoal civil: ajuda-de-custo, indenização de transporte, auxílio-moradia, auxilia-alimentação, auxilia-transporte bem como outros decorrentes de acordo ou convenção coletiva no que se refere aos empregados públicos. Para os militares: adicional de compensação orgânica não incorporada, gratificação de localidade especial, gratificação de representação, transporte, ajuda-de-custo, auxílio-fardamento, auxílio-alimentação e outros benefícios eventuais relativos ao local ou a natureza do trabalho. Estão excluídas deste grupo as despesas com vencimentos, soldos e quaisquer outras vantagens pecuniárias, bem como as despesas relacionadas aos benefícios previdenciários ou assistenciais, tais como: aposentadoria, auxílio-natalidade, salário-família, licença para tratamento de saúde, licença a gestante, a adotante e licença-maternidade, licença por acidente em serviço, assistência a saúde, garantia de condições individuais e ambientais de trabalho satisfatórias, pensão vitalícia e temporária, auxílio-funeral, auxílio-reclusão, auxílio-invalidez, assistência a saúde. Estão excluídas ainda as indenizações e restituições trabalhistas decorrentes da perda da condição de servidor ou empregado, tais como ferias, aviso prévio indenizado e outras.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6874, 1, '3.1.3.1.0.00.00.00.00.00', 'BENEFÍCIOS A PESSOAL - RPPS', 'Compreende o valor total das variações patrimoniais diminutivas com benefícios a servidor público, tais como: ajuda-de-custo, indenização de transporte, auxílio-moradia, auxílio-transporte,auxílio-alimentação e outros benefícios relativos ao local ou a natureza do trabalho. Estão excluídas deste grupo os vencimentos e quaisquer outras vantagens pecuniárias permanentes, bem como os benefícios previdenciários ou assistenciais, tais como: aposentadoria, auxílio-natalidade, salário-família, licença para tratamento de saúde, licença a gestante, a adotante e licença-maternidade, licença por acidente em serviço, assistência a saúde, pensão vitalícia e temporária, auxílio-funeral, auxílio-reclusão, auxílio-invalidez, assistência a saúde. Estão excluídas ainda as indenizações e restituições trabalhistas decorrentes da perda da condição de servidor ou empregado, tais como ferias, aviso prévio indenizados e outras.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6875, 1, '3.2.1.2.0.00.00.00.00.00', 'APOSENTADORIAS - RGPS', 'Compreendem os benefícios de prestação continuada assegurados pela previdência social com o objetivo de garantir meios indispensáveis de manutenção, por motivo de incapacidade, idade avançada e tempo de serviço, abrangidas pelo RGPS.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6876, 1, '3.2.1.2.1.00.00.00.00.00', 'APOSENTADORIAS - RGPS - CONSOLIDAÇÃO', 'Compreendem os benefícios de prestação continuada assegurados pela previdência social com o objetivo de garantir meios indispensáveis de manutenção, por motivo de incapacidade, idade avançada e tempo de serviço, abrangidos pelo RGPS. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6877, 1, '3.2.1.3.0.00.00.00.00.00', 'RESERVA REMUNERADA - PESSOAL MILITAR', 'Compreende as variações patrimoniais diminutivas com reserva remunerada dos militares', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6878, 1, '3.1.3.1.1.00.00.00.00.00', 'BENEFÍCIOS A PESSOAL - RPPS - CONSOLIDAÇÃO', 'Compreende o valor total das variações patrimoniais diminutivas com benefícios a servidor público, tais como: ajuda-de-custo, indenização de transporte, auxílio-moradia, auxílio-transporte,auxílio-alimentação e outros benefícios relativos ao local ou a natureza do trabalho. Estão excluídas deste grupo os vencimentos e quaisquer outras vantagens pecuniárias permanentes, bem como os benefícios previdenciários ou assistenciais, tais como: aposentadoria, auxílio-natalidade, salário-família, licença para tratamento de saúde, licença a gestante, a adotante e licença-maternidade, licença por acidente em serviço, assistência a saúde, pensão vitalícia e temporária, auxílio-funeral, auxílio-reclusão, auxílio-invalidez, assistência a saúde. Estão excluídas ainda as indenizações e restituições trabalhistas decorrentes da perda da condição de servidor ou empregado, tais como ferias, aviso prévio indenizado e outras. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6879, 1, '3.1.3.2.0.00.00.00.00.00', 'BENEFÍCIOS A PESSOAL - RGPS', 'Compreende o valor total das variações patrimoniais diminutivas com benefícios devidos aos empregados públicos, e ainda outros relativos a acordo ou convenção coletiva. Estão excluídos deste grupo os vencimentos e quaisquer outras vantagens pecuniárias, bem como os benefícios previdenciários ou assistenciais, tais como: aposentadoria, auxílio-natalidade, salário-família, licença para tratamento de saúde, licença a gestante, a adotante e licença-maternidade, licença por acidente em serviço, assistência a saúde, garantia de condições individuais e ambientais de trabalho satisfatórias, pensão vitalícia e temporária, auxílio-funeral, auxílio-reclusão, auxílio-invalidez, assistência a saúde. Estão excluídas ainda as indenizações e restituições trabalhistas decorrentes da perda da condição de servidor ou empregado, tais como ferias, aviso prévio indenizado e outras.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6880, 1, '3.1.3.2.1.00.00.00.00.00', 'BENEFÍCIOS A PESSOAL - RGPS - CONSOLIDAÇÃO', 'Compreende o valor total das variações patrimoniais diminutivas com benefícios devidos aos empregados públicos, e ainda outros relativos a acordo ou convenção coletiva. Estão excluídas deste grupo os vencimentos e quaisquer outras vantagens pecuniárias, bem como os benefícios previdenciários ou assistenciais, tais como: aposentadoria, auxílio-natalidade, salário-família, licença para tratamento de saúde, licença a gestante, a adotante e licença-maternidade, licença por acidente em serviço, assistência a saúde, garantia de condições individuais e ambientais de trabalho satisfatórias, pensão vitalícia e temporária, auxílio-funeral, auxílio-reclusão, auxílio-invalidez, assistência a saúde. Estão excluídos ainda as indenizações e restituições trabalhistas decorrentes da perda da condição de servidor ou empregado, tais como ferias, aviso prévio indenizados e outras. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6902, 1, '3.2.2.2.1.00.00.00.00.00', 'PENSÕES - RGPS - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais diminutivas com pagamento de pensões aos dependentes dos segurados, após seu óbito, regidos pelo regime geral da previdência social - RGPS. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6903, 1, '3.2.2.3.0.00.00.00.00.00', 'PENSÕES - PESSOAL MILITAR', 'Compreende as variações patrimoniais diminutivas com pagamento de pensões aos dependentes dos militares, após seu óbito, regidos pelo regime próprio.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6906, 1, '3.2.3.1.0.00.00.00.00.00', 'BENEFÍCIOS DE PRESTAÇÃO CONTINUADA AO IDOSO', 'Compreendem os benefícios de prestação continuada ao idoso e renda mensal vitalícia por idade.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6881, 1, '3.1.3.3.0.00.00.00.00.00', 'BENEFÍCIOS A PESSOAL - MILITAR', 'Compreende o valor total das variações patrimoniais diminutivas com benefícios devidos a pessoal militar, tais como: adicional de compensação orgânica não incorporada, gratificação de localidade especial, gratificação de representação, transporte, ajuda-de-custo, auxílio-fardamento, auxílio-alimentação e outros benefícios eventuais relativos ao local ou a natureza do trabalho. Estão excluídos deste grupo os soldos e quaisquer outras vantagens pecuniárias permanentes, bem como as os benefícios previdenciários ou assistenciais, tais como: aposentadoria, auxílio-natalidade, salário-família, licença para tratamento de saúde, licença a gestante, a adotante e licença-maternidade, licença por acidente em serviço, assistência a saúde, garantia de condições individuais e ambientais de trabalho satisfatórias, pensão vitalícia e temporária, auxílio-funeral, auxílio-reclusão, auxílio-invalidez, assistência a saúde.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6882, 1, '3.1.9.1.1.00.00.00.00.00', 'INDENIZAÇÕES E RESTITUIÇÕES TRABALHISTAS - CONSOLIDAÇÃO', 'Compreende o valor total com variações patrimoniais diminutivas resultante do pagamento efetuado a servidores públicos civis e empregados de entidades integrantes da administração pública, inclusive ferias e aviso prévio indenizados, multas e contribuições incidentes sobre os depósitos do fundo de garantia por tempo de serviço, etc., em função da perda da condição de servidor ou empregado, podendo ser em decorrência da participação em programa de desligamento voluntario. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6883, 1, '3.1.9.2.0.00.00.00.00.00', 'PESSOAL REQUISITADO DE OUTROS ORGAOS E ENTES - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais diminutivas  com pessoal requisitado de outros órgãos e entes.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6884, 1, '3.1.9.2.1.00.00.00.00.00', 'PESSOAL REQUISITADO DE OUTROS ORGAOS E ENTES - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais diminutivas  com pessoal requisitado de outros órgãos e entes.  Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6885, 1, '3.1.9.9.0.00.00.00.00.00', 'OUTRAS VPD DE PESSOAL E ENCARGOS', 'Compreende outras variações patrimoniais diminutivas, relacionadas com pessoal e encargos, não abrangidas nos grupos anteriores.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6886, 1, '3.1.9.9.1.00.00.00.00.00', 'OUTRAS VPD DE PESSOAL E ENCARGOS - CONSOLIDAÇÃO', 'Compreende outras variações patrimoniais diminutivas, relacionadas com pessoal e encargos, não abrangidas nos grupos anteriores. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6887, 1, '3.2.0.0.0.00.00.00.00.00', 'BENEFÍCIOS PREVIDENCIÁRIOS E ASSISTENCIAIS', 'Compreendem as variações patrimoniais diminutivas relativas às aposentadorias, pensões, reformas, reserva remunerada e outros benefícios previdenciários de caráter contributivo, do regime próprio da previdência social - RPPS e do regime geral da previdência social - RGPS, bem como as ações de assistência social, que são políticas de seguridade social não contributiva, visando ao enfrentamento da pobreza, a garantia dos mínimos sociais, ao provimento de condições para atender contingencias sociais e a universalização dos direitos sociais.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6888, 1, '3.2.1.0.0.00.00.00.00.00', 'APOSENTADORIAS E REFORMAS', 'Compreendem os benefícios de prestação continuada assegurados pela previdência social com o objetivo de garantir meios indispensáveis de manutenção, por motivo de incapacidade, idade avançada e tempo de serviço.', 1, false, 0, 'N');
