insert into contabilidade.planocontadetalhe values (6890, 1, '1.1.2.9.5.01.04.00.00.00', '(-) PERDAS ESTIMADAS EM DEMAIS CONTRIBUIÇÕES', 'Registra o ajuste para perdas estimadas com o não recebimento de demais contribuições.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (6891, 1, '3.2.1.3.1.00.00.00.00.00', 'RESERVA REMUNERADA - PESSOAL MILITAR - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais diminutivas com reserva remunerada dos militares. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
