insert into contabilidade.planocontadetalhe values (6907, 1, '3.2.3.1.1.00.00.00.00.00', 'BENEFÍCIOS DE PRESTAÇÃO CONTINUADA AO IDOSO - CONSOLIDAÇÃO', 'Compreendem os benefícios de prestação continuada e renda mensal vitalícia por idade. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6908, 1, '3.2.3.2.0.00.00.00.00.00', 'BENEFÍCIOS DE PRESTAÇÃO CONTINUADA AO PORTADOR DE DEFICIÊNCIA', 'Compreendem os benefícios de prestação continuada ao portador de deficiência e renda mensal vitalícia - invalidez', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6909, 1, '3.2.3.2.1.00.00.00.00.00', 'BENEFÍCIOS DE PRESTAÇÃO CONTINUADA AO PORTADOR DE DEFICIÊNCIA - CONSOLIDAÇÃO', 'Compreendem os benefícios de prestação continuada ao portador de deficiência e renda mensal vitalícia - invalidez. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6910, 1, '3.2.3.9.0.00.00.00.00.00', 'OUTROS BENEFÍCIOS DE PRESTAÇÃO CONTINUADA', 'Compreendem outros benefícios de prestação continuada.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6911, 1, '3.2.3.9.1.00.00.00.00.00', 'OUTROS BENEFÍCIOS DE PRESTAÇÃO CONTINUADA - CONSOLIDAÇÃO', 'Registra outros benefícios de prestação continuada. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6912, 1, '3.2.4.0.0.00.00.00.00.00', 'BENEFÍCIOS EVENTUAIS', 'Compreendem as provisões suplementares e provisórias, prestadas aos cidadãos e as famílias em virtude de nascimento, morte, situações de vulnerabilidade temporária e de calamidade pública. As provisões relativas a programas, projetos, serviços e benefícios diretamente vinculados ao campo da saúde, educação, integração nacional e das demais políticas setoriais não se incluem na modalidade de benefícios eventuais da assistência social.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6913, 1, '3.2.4.1.0.00.00.00.00.00', 'AUXÍLIO POR NATALIDADE', 'Compreende o beneficio eventual que visa o pagamento de auxílio por natalidade as famílias cuja renda mensal per capita seja inferior a 1/4 (um quarto) do salário mínimo.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6914, 1, '3.2.4.1.1.00.00.00.00.00', 'AUXÍLIO POR NATALIDADE - CONSOLIDAÇÃO', 'Compreende o beneficio eventual que visa o pagamento de auxílio por natalidade as famílias cuja renda mensal per capita seja inferior a 1/4 (um quarto) do salário mínimo. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6915, 1, '3.2.4.2.0.00.00.00.00.00', 'AUXÍLIO POR MORTE', 'Compreende o beneficio eventual que visa o pagamento de auxílio por morte as famílias cuja renda mensal per capita seja inferior a 1/4 (um quarto) do salário mínimo.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6916, 1, '3.2.4.2.1.00.00.00.00.00', 'AUXÍLIO POR MORTE - CONSOLIDAÇÃO', 'Compreende o beneficio eventual que visa o pagamento de auxílio por morte as famílias cuja renda mensal per capita seja inferior a 1/4 (um quarto) do salário mínimo. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6917, 1, '3.2.4.3.0.00.00.00.00.00', 'BENEFÍCIOS EVENTUAIS POR SITUAÇÕES DE VULNERABILIDADE TEMPORÁRIA', 'Compreende as provisões suplementares e provisórias, prestadas aos cidadãos e as famílias em virtude de situações de vulnerabilidade temporária, com prioridade para a criança, a família, o idoso, a pessoa portadora de deficiência, a gestante e a nutriz.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6918, 1, '3.2.4.3.1.00.00.00.00.00', 'BENEFÍCIOS EVENTUAIS POR SITUAÇÕES DE VULNERABILIDADE TEMPORÁRIA - CONSOLIDAÇÃO', 'Compreende as provisões suplementares e provisórias, prestadas aos cidadãos e as famílias em virtude de situações de vulnerabilidade temporária, com prioridade para a criança, a família, o idoso, a pessoa portadora de deficiência, a gestante e a nutriz. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6919, 1, '3.2.4.4.0.00.00.00.00.00', 'BENEFÍCIOS EVENTUAIS EM CASO DE CALAMIDADE PÚBLICA', 'Compreendem os benefícios para atendimento de vitimas de calamidade pública, de modo a assegurar lhes a sobrevivência e a reconstrução de sua autonomia. Entende-se se por estado de calamidade pública o reconhecimento pelo poder público de situação anormal, advinda de baixas ou altas temperaturas, tempestades, enchentes, inversão térmica, desabamentos, incêndios, epidemias, causando sérios danos à comunidade afetada, inclusive a incolumidade ou a vida de seus integrantes.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6920, 1, '3.2.4.4.1.00.00.00.00.00', 'BENEFÍCIOS EVENTUAIS EM CASO DE CALAMIDADE PÚBLICA - CONSOLIDAÇÃO', 'Compreendem os benefícios para atendimento de vitimas de calamidade pública, de modo a assegurar - lhes a sobrevivência e a reconstrução de sua autonomia. Entende-se por estado de calamidade pública o reconhecimento pelo poder público de situação anormal, advinda de baixas ou altas temperaturas, tempestades, enchentes, inversão térmica, desabamentos, incêndios, epidemias, causando sérios danos à comunidade afetada, inclusive a incolumidade ou a vida de seus integrantes. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6921, 1, '3.2.4.9.0.00.00.00.00.00', 'OUTROS BENEFÍCIOS EVENTUAIS', 'Compreende a variação patrimonial diminutiva proveniente de outros benefícios eventuais', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6922, 1, '3.2.4.9.1.00.00.00.00.00', 'OUTROS BENEFÍCIOS EVENTUAIS - CONSOLIDAÇÃO', 'Compreende a variação patrimonial diminutiva proveniente de outros benefícios eventuais.Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6923, 1, '3.2.5.0.0.00.00.00.00.00', 'POLÍTICAS PÚBLICAS DE TRANSFERÊNCIA DE RENDA', 'Compreende as políticas públicas que visem contribuir para a redução da fome, da pobreza, da desigualdade e de outras formas de privação vividas pelas famílias mais excluídas, considerando três dimensões: o alivio imediato da pobreza, por meio da transferência de renda diretamente as famílias pobres e extremamente pobres; a contribuição para a redução da pobreza da geração seguinte, por meio do reforço do direito de acesso aos serviços de saúde e de educação, com o cumprimento das condicionalidades nestas áreas; e a articulação de ações complementares, de forma a desenvolver as capacidades das famílias beneficiárias.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6924, 1, '3.3.2.3.0.00.00.00.00.00', 'SERVIÇOS TERCEIROS - PJ', 'Compreende as variações patrimoniais diminutivas provenientes da prestação de serviços por pessoa jurídica fornecida a entidade governamental. Na classificação da despesa de material por encomenda, a variação patrimonial diminutiva só devera ser classificada com serviços de terceiros se o próprio órgão ou entidade fornecer a matéria-prima.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7669, 1, '2.1.2.3.1.01.03.00.00.00', 'FINANCIAMENTO DE CAPITAL DE GIRO', 'Registra os valores exigíveis, decorrentes de financiamentos internos a curto prazo contraídos para o capital de giro.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (6925, 1, '3.5.1.1.0.00.00.00.00.00', 'TRANSFERÊNCIAS CONCEDIDAS PARA A EXECUÇÃO ORCAMENTARIA', 'Compreende o valor das transferências financeiras concedidas e correspondência de créditos em virtude da execução orçamentária (cota, repassse e sub-repasse). Não Inclui o valor repassado para aportes no RPPS ou RGPS.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6926, 1, '3.2.5.0.1.00.00.00.00.00', 'POLÍTICAS PÚBLICAS DE TRANSFERÊNCIA DE RENDA - CONSOLIDAÇÃO', 'Compreende as políticas públicas que visem contribuir para a redução da fome, da pobreza, da desigualdade e de outras formas de privação vividas pelas famílias mais excluídas, considerando três dimensões: o alivio imediato da pobreza, por meio da transferência de renda diretamente as famílias pobres e extremamente pobres; a contribuição para a redução da pobreza da geração seguinte, por meio do reforço do direito de acesso aos serviços de saúde e de educação, com o cumprimento das condicionalidades nestas áreas; e a articulação de ações complementares, de forma a desenvolver as capacidades das famílias beneficiarias. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6927, 1, '3.2.9.0.0.00.00.00.00.00', 'OUTROS BENEFÍCIOS PREVIDENCIÁRIOS E ASSISTENCIAIS', 'Compreende outras variações patrimoniais diminutivas, relacionadas com benefícios previdenciários ou assistenciais, não abrangidas nos grupos anteriores.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6928, 1, '3.2.9.1.0.00.00.00.00.00', 'OUTROS BENEFÍCIOS PREVIDENCIÁRIOS - RPPS', 'Compreende outras variações patrimoniais diminutivas, relacionadas com benefícios previdenciários do RPPS, não abrangidas nos grupos anteriores.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6929, 1, '3.2.9.1.1.00.00.00.00.00', 'OUTROS BENEFÍCIOS PREVIDENCIÁRIOS - RPPS - CONSOLIDAÇÃO', 'Compreende outras variações patrimoniais diminutivas, relacionadas com benefícios previdenciários do RPPS, não abrangidas nos grupos anteriores. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6930, 1, '3.2.9.1.1.12.00.00.00.00', 'SALARIO-FAMILIA', 'Registra as variações patrimoniais diminutivas com salário-família', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6931, 1, '3.2.9.2.0.00.00.00.00.00', 'OUTROS BENEFÍCIOS PREVIDENCIÁRIOS - RGPS', 'Compreende outras variações patrimoniais diminutivas, relacionadas com benefícios previdenciários do RGPS, não abrangidas nos grupos anteriores.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6932, 1, '3.2.9.2.1.00.00.00.00.00', 'OUTROS BENEFÍCIOS PREVIDENCIÁRIOS - RGPS - CONSOLIDAÇÃO', 'Compreende outras variações patrimoniais diminutivas, relacionadas com benefícios previdenciários do RGPS, não abrangidas nos grupos anteriores. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6933, 1, '3.2.9.3.0.00.00.00.00.00', 'OUTROS BENEFÍCIOS PREVIDENCIÁRIOS - MILITAR', 'Compreende outras variações patrimoniais diminutivas, relacionadas com benefícios previdenciários do regime próprio dos militares, não abrangidas nos grupos anteriores.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6934, 1, '3.2.9.3.1.00.00.00.00.00', 'OUTROS BENEFÍCIOS PREVIDENCIÁRIOS - MILITAR - CONSOLIDAÇÃO', 'Compreende outras variações patrimoniais diminutivas, relacionadas com benefícios previdenciários do regime próprio dos militares, não abrangidas nos grupos anteriores. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6935, 1, '3.2.9.9.1.00.00.00.00.00', 'OUTROS BENEFÍCIOS PREVIDENCIÁRIOS E ASSISTENCIAIS - CONSOLIDAÇÃO', 'Registra as variações patrimoniais diminutivas provenientes de outros benefícios previdenciários e assistenciais. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6936, 1, '3.3.0.0.0.00.00.00.00.00', 'USO DE BENS, SERVIÇOS E CONSUMO DE CAPITAL FIXO', 'Compreende o somatório das variações patrimoniais diminutivas com manutenção e operação da maquina pública, exceto despesas com pessoal e encargos que serão registradas em grupo específico (despesas de pessoal e encargos). Compreende: diárias, material de consumo, material de distribuição gratuita, passagens e despesas com locomoção, serviços de terceiros, arrendamento mercantil operacional, aluguel, depreciação, amortização, exaustão, entre outras.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6937, 1, '3.3.1.0.0.00.00.00.00.00', 'USO DE MATERIAL DE CONSUMO', 'Compreende as variações patrimoniais diminutivas provenientes da distribuição do material de consumo. Um material é considerado de consumo quando for de duração inferior a dois anos, frágil, perecível, incorporável, transformável ou cuja finalidade seja para consumo imediato ou para reposição.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6938, 1, '3.3.1.1.0.00.00.00.00.00', 'CONSUMO DE MATERIAL', 'Compreende as variações patrimoniais diminutivas provenientes de requisição de material de consumo para uso interno.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6939, 1, '3.3.1.1.1.00.00.00.00.00', 'CONSUMO DE MATERIAL - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais diminutivas provenientes de requisição de material de consumo para uso interno.Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6940, 1, '3.3.1.2.0.00.00.00.00.00', 'DISTRIBUIÇÃO DE MATERIAL GRATUITO', 'Compreende as variações patrimoniais diminutivas provenientes da distribuição de material gratuito.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6941, 1, '3.3.1.2.1.00.00.00.00.00', 'DISTRIBUIÇÃO DE MATERIAL GRATUITO - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais diminutivas provenientes da distribuição de material gratuito. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6942, 1, '3.3.2.0.0.00.00.00.00.00', 'SERVIÇOS', 'Compreende as variações patrimoniais diminutivas provenientes da prestação de serviços fornecidas à entidade governamental.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6943, 1, '3.3.2.1.0.00.00.00.00.00', 'DIÁRIAS', 'Compreende as variações patrimoniais diminutivas provenientes da utilização de diárias pagas aos servidores, empregados públicos e colaboradores eventuais, para fazer face a despesas com pousada, alimentação e locomoção urbana.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6944, 1, '3.3.2.1.1.00.00.00.00.00', 'DIÁRIAS - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais diminutivas provenientes da utilização de diárias pagas aos servidores, empregados públicos e colaboradores eventuais, para fazer face a despesas com pousada, alimentação e locomoção urbana.Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7082, 1, '7.3.1.1.2.00.00.00.00.00', 'ENCAMINHAMENTO DE CRÉDITOS PARA INSCRIÇÃO EM DÍVIDA ATIVA  NÃO-TRIBUTÁRIA', 'Compreende o montante dos créditos a encaminhar e encaminhados para inscrição em Dívida Ativa Não-Tributária..', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6945, 1, '3.3.2.2.0.00.00.00.00.00', 'SERVIÇOS TERCEIROS - PF', 'Compreende as variações patrimoniais diminutivas provenientes da prestação de serviços por pessoa física fornecida a entidade governamental. Na classificação da despesa de material por encomenda, a variação patrimonial diminutiva só devera ser classificada com serviços de terceiros se o próprio órgão ou entidade fornecer a matéria-prima.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6946, 1, '3.3.2.2.1.00.00.00.00.00', 'SERVIÇOS TERCEIROS - PF - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais diminutivas provenientes da prestação de serviços por pessoa física fornecida a entidade governamental. Na classificação da despesa de material por encomenda, a variação patrimonial diminutiva só devera ser classificada com serviços de terceiros se o próprio órgão ou entidade fornecer a matéria-prima. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6947, 1, '3.3.2.3.1.00.00.00.00.00', 'SERVIÇOS TERCEIROS - PJ - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais diminutivas provenientes da prestação de serviços por pessoa jurídica fornecida a entidade governamental. Na classificação da despesa de material por encomenda, a variação patrimonial diminutiva só devera ser classificada com serviços de terceiros se o próprio órgão ou entidade fornecer a matéria-prima. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6948, 1, '3.3.2.4.0.00.00.00.00.00', 'CONTRATO DE TERCEIRIZAÇÃO POR SUBSTITUIÇÃO DE MÃO DE OBRA - ART. 18 § 1, LC 101/00', 'Compreende a apropriação das despesas relativas à mão de obra, constantes dos contratos de terceirização, classificáveis no grupo de despesa com pessoal e encargos em obediência ao disposto no artigo 18, § 1º, da lei complementar nº 101, de 2000.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6949, 1, '3.3.2.4.1.00.00.00.00.00', 'CONTRATO DE TERCEIRIZAÇÃO POR SUBSTITUIÇÃO DE MÃO DE OBRA - ART. 18 § 1, LC 101/00 - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais diminutivas relativas à mão de obra, constantes dos contratos de terceirização, classificáveis no grupo de despesa com pessoal e encargos em obediência ao disposto no artigo 18, § 1º, da lei complementar nº 101, de 2000. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6950, 1, '3.3.3.0.0.00.00.00.00.00', 'DEPRECIAÇÃO, AMORTIZAÇÃO E EXAUSTÃO', 'Compreende o decréscimo no beneficio de um bem durante o período contábil decorrente de depreciação, amortização e exaustão.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6951, 1, '3.3.3.1.0.00.00.00.00.00', 'DEPRECIAÇÃO', 'Compreende a redução do valor dos bens tangíveis pelo desgaste ou perda de utilidade por uso, ação da natureza ou obsolescência.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6952, 1, '3.3.3.1.1.00.00.00.00.00', 'DEPRECIAÇÃO - CONSOLIDAÇÃO', 'Compreende a redução do valor dos bens tangíveis pelo desgaste ou perda de utilidade por uso, ação da natureza ou obsolescência. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6953, 1, '3.3.3.1.1.01.00.00.00.00', 'DEPRECIAÇÃO DE IMOBILIZADO', 'Registra a redução do valor dos bens tangíveis, do ativo imobilizado, pelo desgaste ou perda de utilidade por uso, ação da natureza ou obsolescência.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6954, 1, '3.3.3.2.0.00.00.00.00.00', 'AMORTIZAÇÃO', 'Compreende a redução do valor aplicado na aquisição de direitos de propriedade e quaisquer outros, inclusive ativos intangíveis, com existência ou exercício de duração limitada, ou cujo objeto sejam bens de utilização por prazo legal ou contratualmente limitado.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6955, 1, '3.5.1.2.2.02.00.00.00.00', 'TRANSFERÊNCIAS  NÃO FINANCEIRAS CONCEDIDAS - INDEPENDENTES DE EXECUÇÃO ORÇAMENTÁRIA', 'Compreende o valor das transferências concedidas de bens ou valores independentes da execução orçamentária.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6956, 1, '3.3.3.2.1.00.00.00.00.00', 'AMORTIZAÇÃO - CONSOLIDAÇÃO', 'Compreende a redução do valor aplicado na aquisição de direitos de propriedade e quaisquer outros, inclusive ativos intangíveis, com existência ou exercício de duração limitada, ou cujo objeto sejam bens de utilização por prazo legal ou contratualmente limitado. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6957, 1, '3.3.3.3.0.00.00.00.00.00', 'EXAUSTÃO', 'Compreende a redução do valor decorrente da exploração dos recursos minerais, florestais e outros recursos naturais esgotáveis.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6958, 1, '3.3.3.3.1.00.00.00.00.00', 'EXAUSTÃO - CONSOLIDAÇÃO', 'Compreende a redução do valor decorrente da exploração dos recursos minerais, florestais e outros recursos naturais esgotáveis. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6959, 1, '3.4.0.0.0.00.00.00.00.00', 'VARIAÇÕES PATRIMONIAIS DIMINUTIVAS FINANCEIRAS', 'Compreende as variações patrimoniais diminutivas com operações financeiras, tais como: juros incorridos, descontos concedidos, comissões, despesas bancarias e correções monetárias.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6960, 1, '3.4.1.0.0.00.00.00.00.00', 'JUROS E ENCARGOS DE EMPRÉSTIMOS E FINANCIAMENTOS OBTIDOS', 'Compreende a variação patrimonial diminutiva com juros e encargos de empréstimos e financiamentos contraídos com pessoas jurídicas de direito público ou privado.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6961, 1, '3.4.1.1.0.00.00.00.00.00', 'JUROS E ENCARGOS DA DÍVIDA CONTRATUAL INTERNA', 'Compreende a variação patrimonial diminutiva com juros e encargos da dívida pública interna derivada de obrigações assumidas com pessoas jurídicas de direito público ou privado com vistas à execução de obras, fornecimento de bens ou prestação de serviços, ou da celebração de contratos de financiamento.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6962, 1, '3.4.1.1.1.00.00.00.00.00', 'JUROS E ENCARGOS DA DÍVIDA CONTRATUAL INTERNA - CONSOLIDAÇÃO', 'Compreende a variação patrimonial diminutiva com juros e encargos da dívida pública interna derivada de obrigações assumidas com pessoas jurídicas de direito público ou privado com vistas à execução de obras, fornecimento de bens ou prestação de serviços, ou da celebração de contratos de financiamento. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6978, 1, '3.4.1.8.5.00.00.00.00.00', 'OUTROS JUROS E ENCARGOS DE EMPRÉSTIMOS E FINANCIAMENTOS INTERNOS - INTER OFSS - MUNICÍPIO', 'Compreende a variação patrimonial diminutiva com juros e encargos de empréstimos e financiamentos internos que não sejam referentes a dívida contratual, a dívida mobiliaria e a por antecipação de receita orçamentária. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6963, 1, '3.4.1.1.3.00.00.00.00.00', 'JUROS E ENCARGOS DA DÍVIDA CONTRATUAL INTERNA - INTER OFSS - UNIÃO', 'Compreende a variação patrimonial diminutiva com juros e encargos da dívida pública interna derivada de obrigações assumidas com pessoas jurídicas de direito público ou privado com vistas à execução de obras, fornecimento de bens ou prestação de serviços, ou da celebração de contratos de financiamento. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) de. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6964, 1, '3.4.1.1.4.00.00.00.00.00', 'JUROS E ENCARGOS DA DÍVIDA CONTRATUAL INTERNA - INTER OFSS - ESTADO', 'Compreende a variação patrimonial diminutiva com juros e encargos da dívida pública interna derivada de obrigações assumidas com pessoas jurídicas de direito público ou privado com vistas à execução de obras, fornecimento de bens ou prestação de serviços, ou da celebração de contratos de financiamento. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6965, 1, '3.4.1.1.5.00.00.00.00.00', 'JUROS E ENCARGOS DA DÍVIDA CONTRATUAL INTERNA - INTER OFSS - MUNICÍPIO', 'Compreende a variação patrimonial diminutiva com juros e encargos da dívida pública interna derivada de obrigações assumidas com pessoas jurídicas de direito público ou privado com vistas à execução de obras, fornecimento de bens ou prestação de serviços, ou da celebração de contratos de financiamento. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6966, 1, '2.1.4.3.5.03.00.00.00.00', 'TRIBUTOS MUNICIPAIS RENEGOCIADOS', 'Registra os valores devidos pela unidade relativos a Tributos que foram renegociados.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (6967, 1, '3.4.1.2.0.00.00.00.00.00', 'JUROS E ENCARGOS DA DÍVIDA CONTRATUAL EXTERNA', 'Compreende a variação patrimonial diminutiva com juros e encargos da dívida pública externa derivada de obrigações assumidas com pessoas jurídicas de direito público ou privado com vistas à execução de obras, fornecimento de bens ou prestação de serviços, ou da celebração de contratos de financiamento.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6968, 1, '3.4.1.2.1.00.00.00.00.00', 'JUROS E ENCARGOS DA DÍVIDA CONTRATUAL EXTERNA - CONSOLIDAÇÃO', 'Compreende a variação patrimonial diminutiva com juros e encargos da dívida pública externa derivada de obrigações assumidas com pessoas jurídicas de direito público ou privado com vistas à execução de obras, fornecimento de bens ou prestação de serviços, ou da celebração de contratos de financiamento.Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6969, 1, '3.4.1.3.0.00.00.00.00.00', 'JUROS E ENCARGOS DA DÍVIDA MOBILIARIA', 'Compreende a variação patrimonial diminutiva com juros e encargos da dívida pública representada por títulos emitidos pelo governo. São considerados encargos da dívida mobiliaria: comissões, corretagens, seguros, deságio e outros.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6970, 1, '3.4.1.3.1.00.00.00.00.00', 'JUROS E ENCARGOS DA DÍVIDA MOBILIARIA - CONSOLIDAÇÃO', 'Compreende a variação patrimonial diminutiva com juros e encargos da dívida pública representada por títulos emitidos pelo governo. São considerados encargos da dívida mobiliaria: comissões, corretagens, seguros, deságio e outros. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6971, 1, '3.4.1.4.0.00.00.00.00.00', 'JUROS E ENCARGOS DE EMPRÉSTIMOS POR ANTECIPAÇÃO DE RECEITA ORÇAMENTÁRIA', 'Compreende a variação patrimonial diminutiva com juros e encargos sobre empréstimos contraídos por antecipação de receita orçamentária para atender insuficiência de caixa durante o exercício financeiro.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6972, 1, '3.4.1.4.1.00.00.00.00.00', 'JUROS E ENCARGOS DE EMPRÉSTIMOS POR ANTECIPAÇÃO DE RECEITA ORÇAMENTÁRIA - CONSOLIDAÇÃO', 'Compreende a variação patrimonial diminutiva com juros e encargos sobre empréstimos contraídos por antecipação de receita orçamentária para atender insuficiência de caixa durante o exercício financeiro. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6973, 1, '8.1.1.1.1.01.03.00.00.00', 'FIANÇAS A EXECUTAR', 'Registra o valor das garantias recebidas por fianças, pendentes de execução, no país.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (6974, 1, '3.4.1.8.0.00.00.00.00.00', 'OUTROS JUROS E ENCARGOS DE EMPRÉSTIMOS E FINANCIAMENTOS INTERNOS', 'Compreende a variação patrimonial diminutiva com juros e encargos de empréstimos e financiamentos internos que não sejam referentes a dívida contratual, a dívida mobiliaria e a por antecipação de receita orçamentária.', 1, false, 0, 'N');
