insert into contabilidade.planocontadetalhe values (6976, 1, '3.4.1.8.3.00.00.00.00.00', 'OUTROS JUROS E ENCARGOS DE EMPRÉSTIMOS E FINANCIAMENTOS INTERNOS - INTER OFSS - UNIÃO', 'Compreende a variação patrimonial diminutiva com juros e encargos de empréstimos e financiamentos internos que não sejam referentes a dívida contratual, a dívida mobiliaria e a por antecipação de receita orçamentária. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6977, 1, '3.4.1.8.4.00.00.00.00.00', 'OUTROS JUROS E ENCARGOS DE EMPRÉSTIMOS E FINANCIAMENTOS INTERNOS - INTER OFSS - ESTADO', 'Compreende a variação patrimonial diminutiva com juros e encargos de empréstimos e financiamentos internos que não sejam referentes a dívida contratual, a dívida mobiliaria e a por antecipação de receita orçamentária. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6979, 1, '3.4.1.9.0.00.00.00.00.00', 'OUTROS JUROS E ENCARGOS DE EMPRÉSTIMOS E FINANCIAMENTOS EXTERNOS', 'Compreende a variação patrimonial diminutiva com juros e encargos de empréstimos e financiamentos externos que não sejam referentes a dívida contratual, a dívida mobiliaria e a por antecipação de receita orçamentária.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6980, 1, '3.4.1.9.1.00.00.00.00.00', 'OUTROS JUROS E ENCARGOS DE EMPRÉSTIMOS E FINANCIAMENTOS EXTERNOS - CONSOLIDAÇÃO', 'Compreende a variação patrimonial diminutiva com juros e encargos de empréstimos e financiamentos externos que não sejam referentes a dívida contratual, a dívida mobiliaria e a por antecipação de receita orçamentária. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6981, 1, '3.4.2.0.0.00.00.00.00.00', 'JUROS E ENCARGOS DE MORA', 'Compreende o montante de variação patrimonial diminutiva com juros e encargos a titulo de penalidade em virtude de atrasos e não cumprimento dos prazos contratuais.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6982, 1, '3.4.2.1.0.00.00.00.00.00', 'JUROS E ENCARGOS DE MORA DE EMPRÉSTIMOS E FINANCIAMENTOS INTERNOS OBTIDOS', 'Compreende a variação patrimonial diminutiva com juros e encargos a titulo de penalidade em virtude de atrasos e/ou não cumprimento dos prazos contratuais dos empréstimos e financiamentos internos contraídos com pessoas jurídicas de direito público ou privado.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6983, 1, '3.4.2.1.1.00.00.00.00.00', 'JUROS E ENCARGOS DE MORA DE EMPRÉSTIMOS E FINANCIAMENTOS INTERNOS OBTIDOS - CONSOLIDAÇÃO', 'Compreende a variação patrimonial diminutiva com juros e encargos a titulo de penalidade em virtude de atrasos e/ou não cumprimento dos prazos contratuais dos empréstimos e financiamentos internos contraídos com pessoas jurídicas de direito público ou privado. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6984, 1, '3.4.3.9.1.01.00.00.00.00', 'OUTRAS VARIAÇÕES MONETARIAS', 'Registra a Variação Patrimonial Diminutiva proveniente de variações da nossa própria moeda em relação aos índices ou coeficientes aplicáveis por dispositivo legal ou contratual, com exceção a dívida contratual e mobiliaria. Ressalte-se será tratada como Variação Monetária apenas a Correção Monetária Pós - Fixada.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6985, 1, '3.4.2.1.3.00.00.00.00.00', 'JUROS E ENCARGOS DE MORA DE EMPRÉSTIMOS E FINANCIAMENTOS INTERNOS OBTIDOS - INTER OFSS - UNIÃO', 'Compreende a variação patrimonial diminutiva com juros e encargos a titulo de penalidade em virtude de atrasos e/ou não cumprimento dos prazos contratuais dos empréstimos e financiamentos internos contraídos com pessoas jurídicas de direito público ou privado. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6986, 1, '3.4.2.3.1.03.00.00.00.00', 'MULTAS INDEDUTÍVEIS', 'Registra a variação patrimonial diminutiva com multas, que sejam indedutíveis na determinação do lucro real pela legislação, referentes a penalidade em virtude de atrasos e não cumprimento dos prazos dos contratos de prestação de serviços e aquisição de bens.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6987, 1, '3.4.2.1.4.00.00.00.00.00', 'JUROS E ENCARGOS DE MORA DE EMPRÉSTIMOS E FINANCIAMENTOS INTERNOS OBTIDOS - INTER OFSS - ESTADO', 'Compreende a variação patrimonial diminutiva com juros e encargos a titulo de penalidade em virtude de atrasos e/ou não cumprimento dos prazos contratuais dos empréstimos e financiamentos internos contraídos com pessoas jurídicas de direito público ou privado. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6988, 1, '3.4.2.1.5.00.00.00.00.00', 'JUROS E ENCARGOS DE MORA DE EMPRÉSTIMOS E FINANCIAMENTOS INTERNOS OBTIDOS - INTER OFSS - MUNICÍPIO', 'Compreende a variação patrimonial diminutiva com juros e encargos a titulo de penalidade em virtude de atrasos e/ou não cumprimento dos prazos contratuais dos empréstimos e financiamentos internos contraídos com pessoas jurídicas de direito público ou privado. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6989, 1, '3.4.2.2.0.00.00.00.00.00', 'JUROS E ENCARGOS DE MORA DE EMPRÉSTIMOS E FINANCIAMENTOS EXTERNOS OBTIDOS', 'Compreende a variação patrimonial diminutiva com juros e encargos a titulo de penalidade em virtude de atrasos e/ou não cumprimento dos prazos contratuais dos empréstimos e financiamentos externos contraídos com pessoas jurídicas de direito público ou privado.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6990, 1, '3.4.2.2.1.00.00.00.00.00', 'JUROS E ENCARGOS DE MORA DE EMPRÉSTIMOS E FINANCIAMENTOS EXTERNOS OBTIDOS - CONSOLIDAÇÃO', 'Compreende a variação patrimonial diminutiva com juros e encargos a titulo de penalidade em virtude de atrasos e/ou não cumprimento dos prazos contratuais dos empréstimos e financiamentos externos contraídos com pessoas jurídicas de direito público ou privado. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6991, 1, '3.4.2.3.0.00.00.00.00.00', 'JUROS E ENCARGOS DE MORA DE AQUISIÇÃO DE BENS E SERVIÇOS', 'Compreende a variação patrimonial diminutiva com juros e encargos a titulo de penalidade em virtude de atrasos e não cumprimento dos prazos dos contratos de prestação de serviços e aquisição de bens.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6992, 1, '3.4.2.3.1.00.00.00.00.00', 'JUROS E ENCARGOS DE MORA DE AQUISIÇÃO DE BENS E SERVIÇOS - CONSOLIDAÇÃO', 'Compreende a variação patrimonial diminutiva com juros e encargos a titulo de penalidade em virtude de atrasos e não cumprimento dos prazos dos contratos de prestação de serviços e aquisição de bens. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6993, 1, '3.4.2.3.1.01.00.00.00.00', 'JUROS DE MORA', 'Registra a variação patrimonial diminutiva com juros referentes a penalidade em virtude de atrasos e não cumprimento dos prazos dos contratos de prestação de serviços e aquisição de bens.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6994, 1, '3.4.2.3.1.02.00.00.00.00', 'MULTAS DEDUTÍVEIS', 'Registra a variação patrimonial diminutiva com multas, que sejam dedutíveis na determinação do lucro real pela legislação, referentes a penalidade em virtude de atrasos e não cumprimento dos prazos dos contratos de prestação de serviços e aquisição de bens.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6995, 1, '3.4.2.3.1.99.00.00.00.00', 'OUTROS ENCARGOS DE MORA', 'Registra a variação patrimonial diminutiva com outros encargos referentes a penalidade em virtude de atrasos e não cumprimento dos prazos dos contratos de prestação de serviços e aquisição de bens, que não se enquadrem nos itens anteriores.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6996, 1, '3.4.2.4.0.00.00.00.00.00', 'JUROS E ENCARGOS DE MORA DE OBRIGAÇÕES TRIBUTÁRIAS', 'Compreende a variação patrimonial diminutiva com juros e encargos a titulo de penalidade em virtude de atrasos e não cumprimento dos prazos de obrigações tributárias devidas.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6997, 1, '3.4.2.4.1.00.00.00.00.00', 'JUROS E ENCARGOS DE MORA DE OBRIGAÇÕES TRIBUTÁRIAS - CONSOLIDAÇÃO', 'Compreende a variação patrimonial diminutiva com juros e encargos a titulo de penalidade em virtude de atrasos e não cumprimento dos prazos de obrigações tributárias devidas. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6998, 1, '3.4.2.9.0.00.00.00.00.00', 'OUTROS JUROS E ENCARGOS DE MORA', 'Compreende a variação patrimonial diminutiva com juros e encargos a titulo de penalidade em virtude de atrasos e não cumprimento dos prazos em situações não compreendidas nas classificações anteriores.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (6999, 1, '3.4.2.9.1.00.00.00.00.00', 'OUTROS JUROS E ENCARGOS DE MORA - CONSOLIDAÇÃO', 'Compreende a variação patrimonial diminutiva com juros e encargos a titulo de penalidade em virtude de atrasos e não cumprimento dos prazos em situações não compreendidas nas classificações anteriores. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7000, 1, '3.4.3.0.0.00.00.00.00.00', 'VARIAÇÕES MONETÁRIAS E CAMBIAIS', 'Compreende a variação patrimonial diminutiva proveniente de variações da nossa própria moeda em relação aos índices ou coeficientes aplicáveis por dispositivo legal ou contratual e a variação do valor da nossa moeda em relação às moedas estrangeiras. Ressalte-se que será tratada como variação monetária apenas a correção monetária pós-fixada.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7001, 1, '3.4.3.1.0.00.00.00.00.00', 'VARIAÇÕES MONETÁRIAS E CAMBIAIS DE DÍVIDA CONTRATUAL INTERNA', 'Compreende a variação patrimonial diminutiva proveniente de variações da nossa própria moeda em relação aos índices ou coeficientes aplicáveis por dispositivo legal ou contratual e a variação do valor da nossa moeda em relação às moedas estrangeiras referentes a dívida contratual interna. Ressalte-se que será tratada como variação monetária apenas a correção monetária pós-fixada.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7002, 1, '3.5.1.0.0.00.00.00.00.00', 'TRANSFERÊNCIAS INTRAGOVERNAMENTAIS', 'Compreende as variações patrimoniais diminutivas decorrentes das transferências financeiras relativas à execução orçamentária, e de bens e valores, referentes às transações intragovernamentais.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7003, 1, '3.4.3.1.1.00.00.00.00.00', 'VARIAÇÕES MONETÁRIAS E CAMBIAIS DE DÍVIDA CONTRATUAL INTERNA - CONSOLIDAÇÃO', 'Compreende a variação patrimonial diminutiva proveniente de variações da nossa própria moeda em relação aos índices ou coeficientes aplicáveis por dispositivo legal ou contratual e a variação do valor da nossa moeda em relação às moedas estrangeiras referentes a dívida contratual interna. Ressalte-se que será tratada como variação monetária apenas a correção monetária pós-fixada. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7004, 1, '3.4.3.1.3.00.00.00.00.00', 'VARIAÇÕES MONETÁRIAS E CAMBIAIS DE DÍVIDA CONTRATUAL INTERNA - INTER OFSS - UNIÃO', 'Compreende a variação patrimonial diminutiva proveniente de variações da nossa própria moeda em relação aos índices ou coeficientes aplicáveis por dispositivo legal ou contratual e a variação do valor da nossa moeda em relação às moedas estrangeiras referentes a dívida contratual interna. Ressalte-se que será tratada como variação monetária apenas a correção monetária pós-fixada. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7005, 1, '3.4.3.1.4.00.00.00.00.00', 'VARIAÇÕES MONETÁRIAS E CAMBIAIS DE DÍVIDA CONTRATUAL INTERNA - INTER OFSS - ESTADO', 'Compreende a variação patrimonial diminutiva proveniente de variações da nossa própria moeda em relação aos índices ou coeficientes aplicáveis por dispositivo legal ou contratual e a variação do valor da nossa moeda em relação às moedas estrangeiras referentes a dívida contratual interna. Ressalte-se que será tratada como variação monetária apenas a correção monetária pós-fixada. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7006, 1, '3.5.1.3.0.00.00.00.00.00', 'TRANSFERENCIAS CONCEDIDAS PARA APORTES DE RECURSOS PARA O RPPS', 'Compreende o valor das transferências para aportes financeiros do ente para cobertura de insuficiências financeiras, formação de reserva, e cobertura de déficits financeiros ou atuariais do RPPS e outros aportes., exceto os decorrentes de alíquota de contribuição suplementar.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7007, 1, '3.4.3.1.5.00.00.00.00.00', 'VARIAÇÕES MONETÁRIAS E CAMBIAIS DE DÍVIDA CONTRATUAL INTERNA - INTER OFSS - MUNICÍPIO', 'Compreende a variação patrimonial diminutiva proveniente de variações da nossa própria moeda em relação aos índices ou coeficientes aplicáveis por dispositivo legal ou contratual e a variação do valor da nossa moeda em relação às moedas estrangeiras referentes a dívida contratual interna. Ressalte-se que será tratada como variação monetária apenas a correção monetária pós-fixada. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7008, 1, '3.4.3.2.0.00.00.00.00.00', 'VARIAÇÕES MONETÁRIAS E CAMBIAIS DE DÍVIDA CONTRATUAL EXTERNA', 'Compreende a variação patrimonial diminutiva proveniente de variações da nossa própria moeda em relação aos índices ou coeficientes aplicáveis por dispositivo legal ou contratual e a variação do valor da nossa moeda em relação às moedas estrangeiras referentes a dívida contratual externa. Ressalte-se que será tratada como variação monetária apenas a correção monetária pós-fixada', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7009, 1, '3.4.3.2.1.00.00.00.00.00', 'VARIAÇÕES MONETÁRIAS E CAMBIAIS DE DÍVIDA CONTRATUAL EXTERNA - CONSOLIDAÇÃO', 'Compreende a variação patrimonial diminutiva proveniente de variações da nossa própria moeda em relação aos índices ou coeficientes aplicáveis por dispositivo legal ou contratual e a variação do valor da nossa moeda em relação às moedas estrangeiras referentes a dívida contratual externa. Ressalte-se que será tratada como variação monetária apenas a correção monetária pós-fixada. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7010, 1, '3.4.3.3.0.00.00.00.00.00', 'VARIAÇÕES MONETÁRIAS E CAMBIAIS DE DÍVIDA MOBILIARIA INTERNA', 'Compreende a variação patrimonial diminutiva proveniente de variações da nossa própria moeda em relação aos índices ou coeficientes aplicáveis por dispositivo legal ou contratual e a variação do valor da nossa moeda em relação às moedas estrangeiras referentes a dívida mobiliaria interna. Ressalte-se que será tratada como variação monetária apenas a correção monetária pós-fixada', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7011, 1, '3.4.3.3.1.00.00.00.00.00', 'VARIAÇÕES MONETÁRIAS E CAMBIAIS DE DÍVIDA MOBILIARIA INTERNA - CONSOLIDAÇÃO', 'Compreende a variação patrimonial diminutiva proveniente de variações da nossa própria moeda em relação aos índices ou coeficientes aplicáveis por dispositivo legal ou contratual e a variação do valor da nossa moeda em relação às moedas estrangeiras referentes a dívida mobiliaria interna. Ressalte-se que será tratada como variação monetária apenas a correção monetária pós-fixada. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7012, 1, '3.4.3.4.0.00.00.00.00.00', 'VARIAÇÕES MONETÁRIAS E CAMBIAIS DE DÍVIDA MOBILIARIA EXTERNA', 'Compreende a variação patrimonial diminutiva proveniente de variações da nossa própria moeda em relação aos índices ou coeficientes aplicáveis por dispositivo legal ou contratual e a variação do valor da nossa moeda em relação às moedas estrangeiras referentes a dívida mobiliaria externa. Ressalte-se que será tratada como variação monetária apenas a correção monetária pós-fixada.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7013, 1, '3.4.3.4.1.00.00.00.00.00', 'VARIAÇÕES MONETÁRIAS E CAMBIAIS DE DÍVIDA MOBILIARIA EXTERNA - CONSOLIDAÇÃO', 'Compreende a variação patrimonial diminutiva proveniente de variações da nossa própria moeda em relação aos índices ou coeficientes aplicáveis por dispositivo legal ou contratual e a variação do valor da nossa moeda em relação às moedas estrangeiras referentes a dívida mobiliaria externa. Ressalte-se que será tratada como variação monetária apenas a correção monetária pós-fixada. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7014, 1, '3.4.3.9.0.00.00.00.00.00', 'OUTRAS VARIAÇÕES MONETÁRIAS E CAMBIAIS', 'Compreende a variação patrimonial diminutiva proveniente de variações da nossa própria moeda em relação aos índices ou coeficientes aplicáveis por dispositivo legal ou contratual e a variação do valor da nossa moeda em relação às moedas estrangeiras, com exceção a dívida contratual e mobiliaria. Ressalte-se que será tratada como variação monetária apenas a correção monetária pós-fixada.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7015, 1, '3.4.3.9.1.00.00.00.00.00', 'OUTRAS VARIAÇÕES MONETÁRIAS E CAMBIAIS - CONSOLIDAÇÃO', 'Compreende a variação patrimonial diminutiva proveniente de variações da nossa própria moeda em relação aos índices ou coeficientes aplicáveis por dispositivo legal ou contratual e a variação do valor da nossa moeda em relação às moedas estrangeiras, com exceção a dívida contratual e mobiliaria. Ressalte-se que será tratada como variação monetária apenas a correção monetária pós-fixada. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7016, 1, '2.2.7.9.1.99.00.00.00.00', 'OUTRAS PROVISÕES A LONGO PRAZO', 'Registra os valores das provisões não classificáveis nas demais contas deste plano de contas.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7017, 1, '3.4.3.9.3.00.00.00.00.00', 'OUTRAS VARIAÇÕES MONETÁRIAS E CAMBIAIS - INTER OFSS - UNIÃO', 'Compreende a variação patrimonial diminutiva proveniente de variações da nossa própria moeda em relação aos índices ou coeficientes aplicáveis por dispositivo legal ou contratual e a variação do valor da nossa moeda em relação às moedas estrangeiras, com exceção a dívida contratual e mobiliaria. Ressalte-se que será tratada como variação monetária apenas a correção monetária pós-fixada. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7018, 1, '3.4.3.9.3.01.00.00.00.00', 'OUTRAS VARIAÇÕES MONETARIAS', 'Registra a Variação Patrimonial Diminutiva proveniente de variações da nossa própria moeda em relação aos índices ou coeficientes aplicáveis por dispositivo legal ou contratual, com exceção a dívida contratual e mobiliaria. Ressalte-se será tratada como Variação Monetária apenas a Correção Monetária Pós - Fixada.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7019, 1, '3.4.3.9.4.00.00.00.00.00', 'OUTRAS VARIAÇÕES MONETÁRIAS E CAMBIAIS - INTER OFSS - ESTADO', 'Compreende a variação patrimonial diminutiva proveniente de variações da nossa própria moeda em relação aos índices ou coeficientes aplicáveis por dispositivo legal ou contratual e a variação do valor da nossa moeda em relação às moedas estrangeiras, com exceção a dívida contratual e mobiliaria. Ressalte-se que será tratada como variação monetária apenas a correção monetária pós-fixada. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7020, 1, '8.1.1.1.1.01.04.00.00.00', 'FIANÇAS EXECUTADAS', 'Registra o valor recebido das garantias por fianças, no país.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (7021, 1, '3.4.3.9.5.00.00.00.00.00', 'OUTRAS VARIAÇÕES MONETÁRIAS E CAMBIAIS - INTER OFSS - MUNICÍPIO', 'Compreende a variação patrimonial diminutiva proveniente de variações da nossa própria moeda em relação aos índices ou coeficientes aplicáveis por dispositivo legal ou contratual e a variação do valor da nossa moeda em relação às moedas estrangeiras, com exceção a dívida contratual e mobiliaria. Ressalte-se que será tratada como variação monetária apenas a correção monetária pós-fixada. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7022, 1, '3.4.4.0.0.00.00.00.00.00', 'DESCONTOS FINANCEIROS CONCEDIDOS', 'Compreende o valor da variação patrimonial diminutiva com descontos financeiros concedidos a clientes por pagamentos antecipados de duplicatas e outros títulos. Não se confundem com descontos nos preços de venda concedidos incondicionalmente, ou abatimentos de preços, que são deduções da receita.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7023, 1, '3.4.4.0.1.00.00.00.00.00', 'DESCONTOS FINANCEIROS CONCEDIDOS  - CONSOLIDAÇÃO', 'Compreende o valor da variação patrimonial diminutiva com descontos financeiros concedidos a clientes por pagamentos antecipados de duplicatas e outros títulos. Não se confundem com descontos nos preços de venda concedidos incondicionalmente, ou abatimentos de preços, que são deduções da receita. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7024, 1, '3.4.8.0.0.00.00.00.00.00', 'APORTES AO BANCO CENTRAL', 'Compreende os aportes de recursos do Tesouro Nacional ao Banco Central do Brasil. Conta de uso exclusivo da União.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7025, 1, '3.4.8.1.0.00.00.00.00.00', 'RESULTADO NEGATIVO DO BANCO CENTRAL', 'Compreende os aportes de títulos públicos para cobertura de resultado negativo do Banco Central do Brasil, conforme art. 7º da Lei Complementar 101, de 4/5/2000. ', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7026, 1, '3.4.8.1.1.00.00.00.00.00', 'RESULTADO NEGATIVO DO BANCO CENTRAL - CONSOLIDAÇÃO', 'Compreende os aportes de títulos públicos para cobertura de resultado negativo do Banco Central do Brasil, conforme art. 7º da Lei Complementar 101, de 4/5/2000. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7027, 1, '3.4.8.2.0.00.00.00.00.00', 'MANUTENÇÃO DA CARTEIRA DE TÍTULOS', 'Compreende os aportes de títulos públicos ao Banco Central do Brasil, para complementação de carteira, conforme disposto na Lei nº 10.179, de 6/2/2011.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7028, 1, '3.4.8.2.1.00.00.00.00.00', 'MANUTENÇÃO DA CARTEIRA DE TÍTULOS - CONSOLIDAÇÃO', 'Compreende os aportes de títulos públicos ao Banco Central do Brasil, para complementação de carteira, conforme disposto na Lei nº 10.179, de 6/2/2011. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7029, 1, '3.4.9.0.0.00.00.00.00.00', 'OUTRAS VARIAÇÕES PATRIMONIAIS DIMINUTIVAS - FINANCEIRAS', 'Compreende outras variações patrimoniais diminutivas financeiras, não abrangidas nos grupos anteriores.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7030, 1, '3.4.9.1.0.00.00.00.00.00', 'JUROS E ENCARGOS EM SENTENÇAS JUDICIAIS', 'Compreende os juros e encargos resultantes de pagamento de precatórios e de sentenças judiciais transitadas em julgado.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7031, 1, '3.4.9.1.1.00.00.00.00.00', 'JUROS E ENCARGOS EM SENTENÇAS JUDICIAIS - CONSOLIDAÇÃO', 'Compreende os juros e encargos resultantes de pagamento de precatórios e de sentenças judiciais transitadas em julgado. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7032, 1, '3.4.9.2.0.00.00.00.00.00', 'JUROS E ENCARGOS EM INDENIZAÇÕES E RESTITUIÇÕES', 'Compreende as variações patrimoniais diminutivas com indenizações e restituições referentes a juros e encargos.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7033, 1, '3.4.9.2.1.00.00.00.00.00', 'JUROS E ENCARGOS EM INDENIZAÇÕES E RESTITUIÇÕES - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais diminutivas com indenizações e restituições referentes a juros e encargos. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7034, 1, '3.4.9.9.0.00.00.00.00.00', 'OUTRAS VARIAÇÕES PATRIMONIAIS DIMINUTIVAS FINANCEIRAS', 'Compreende as variações patrimoniais diminutivas provenientes de operações financeiras não compreendidas nas contas anteriores.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7035, 1, '3.4.9.9.1.00.00.00.00.00', 'OUTRAS VARIAÇÕES PATRIMONIAIS DIMINUTIVAS FINANCEIRAS - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais diminutivas provenientes de operações financeiras não compreendidas nas contas anteriores. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7036, 1, '3.5.0.0.0.00.00.00.00.00', 'TRANSFERÊNCIAS E DELEGAÇÕES CONCEDIDAS', 'Compreende o somatório das variações patrimoniais diminutivas com transferências inter governamentais, transferências intragovernamentais, transferências a instituições multigovernamentais, transferências a instituições privadas com ou sem fins lucrativos, transferências a convênios, transferências ao exterior e execuções orçamentárias delegadas.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7037, 1, '8.1.1.1.1.02.05.00.00.00', 'HIPOTECAS A EXECUTAR', 'Registra o valor das garantias por hipoteca pendentes de execução, no exterior.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (7038, 1, '3.5.1.1.2.00.00.00.00.00', 'TRANSFERÊNCIAS CONCEDIDAS PARA A EXECUÇÃO ORÇAMENTÁRIA -  INTRA OFSS', 'Compreende o valor das transferências financeiras concedidas e correspondência de créditos em virtude da execução orçamentária (cota, repassse e sub-repasse). Não Inclui o valor repassado para aportes no RPPS ou RGPS.Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7039, 1, '3.5.1.2.0.00.00.00.00.00', 'TRANSFERÊNCIAS CONCEDIDAS - INDEPENDENTES DE EXECUÇÃO ORÇAMENTÁRIA', 'Compreende o valor das transferências financeiras, de bens ou valores, concedidas para restos a pagar e outras finalidades independentes da execução orçamentária.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7040, 1, '3.5.1.2.2.00.00.00.00.00', 'TRANSFERÊNCIAS CONCEDIDAS - INDEPENDENTES DE EXECUÇÃO ORÇAMENTÁRIA - INTRA OFSS', 'Compreende o valor das transferências financeiras, de bens ou valores, concedidas para restos a pagar e outras finalidades independentes da execução orçamentária. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do ente.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7041, 1, '3.5.1.2.2.01.00.00.00.00', 'TRANSFERÊNCIAS FINANCEIRAS CONCEDIDAS - INDEPENDENTES DE EXECUÇÃO ORÇAMENTÁRIA', 'Compreende o valor das transferências financeiras concedidas para restos a pagar e outras finalidades independentes da execução orçamentária.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7042, 1, '2.1.8.9.1.09.01.00.00.00', 'TERMOS DE PARCERIA A PAGAR DO EXERCÍCIO', 'Registra os valores a pagar referentes a termos de parceria firmados no exercício.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (7043, 1, '3.5.6.0.1.00.00.00.00.00', 'TRANSFERÊNCIAS AO EXTERIOR - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais diminutivas decorrentes de transferências a organismos e fundos internacionais, de governos estrangeiros e instituições privadas com ou sem fins lucrativos no exterior. Compreende os valores de operações efetuadas entre uma unidade pertencente ao orçamento fiscal e da seguridade social (OFSS) com unidade que não pertença ao OFSS de ente público.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7044, 1, '3.5.1.3.2.00.00.00.00.00', 'TRANSFERENCIAS CONCEDIDAS PARA APORTES DE RECURSOS PARA O RPPS - INTRA OFSS', 'Compreende o valor das transferências para aportes financeiros do ente para cobertura de insuficiências financeiras, formação de reserva, e cobertura de déficits financeiros ou atuariais do RPPS e outros aportes exceto os decorrentes de alíquota de contribuição suplementar. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do ente.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7045, 1, '3.5.1.3.2.01.00.00.00.00', 'PLANO FINANCEIRO', 'Compreende o valor total dos valores concedidos pelo RPPS para cobertura de insuficiências financeiras, formação de reserva e outras necessidades financeiras, no âmbito do plano financeiro.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7046, 1, '3.5.1.3.2.02.00.00.00.00', 'PLANO PREVIDENCIÁRIO', 'Compreende o valor total concedido ao RPPS para cobertura de déficit financeiro ou atuarial e outros aportes, no âmbito do plano previdenciário.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7047, 1, '3.5.1.4.0.00.00.00.00.00', 'TRANSFERÊNCIAS CONCEDIDAS PARA APORTES DE RECURSOS PARA O RGPS', 'Compreende o valor das transferências para os aportes financeiros da União para a cobertura de déficits financeiros ou atuariais do RGPS.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7048, 1, '3.5.1.4.2.00.00.00.00.00', 'TRANSFERÊNCIAS CONCEDIDAS PARA APORTES DE RECURSOS PARA O RGPS  - INTRA OFSS', 'Compreende o valor das transferências para os aportes financeiros da União para a cobertura de déficits financeiros ou atuariais do RGPS. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do ente.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7049, 1, '3.5.1.4.2.01.00.00.00.00', 'RECURSOS PARA COBERTURA DE INSUFICIÊNCIAS FINANCEIRAS', 'Compreende os recursos orçamentários efetivamente utilizados para a cobertura de insuficiências financeiras entre as receitas e despesas previdenciáriasno exercício de referência.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7050, 1, '3.5.1.5.0.00.00.00.00.00', 'TRANSFERÊNCIAS CONCEDIDAS PARA APORTES DE RECURSOS PARA O SISTEMA DE PAGAMENTO DE PENSÕES MILITARES', 'Compreende o valor das transferências para os aportes financeiros do ente para cobertura de insuficiências financeiras, formação de reserva e cobertura de déficits financeiros ou atuariais do regime dos militares e outros aportes, exceto os decorrentes de alíquota de contribuição suplementar.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7051, 1, '3.5.1.5.2.00.00.00.00.00', 'TRANSFERÊNCIAS CONCEDIDAS PARA APORTES DE RECURSOS PARA O SISTEMA DE PAGAMENTO DE PENSÕES MILITARES  - INTRA OFSS', 'Compreende o valor das transferências para os aportes financeiros do ente para cobertura de insuficiências financeiras, formação de reserva e cobertura de déficits financeiros ou atuariais do regime dos militares e outros aportes, exceto os decorrentes de alíquota de contribuição suplementar. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do ente.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7052, 1, '3.5.2.0.0.00.00.00.00.00', 'TRANSFERÊNCIAS INTER GOVERNAMENTAIS', 'Compreende as variações patrimoniais diminutivas decorrentes de transferências a União, estados, distrito federal, municípios, inclusive as entidades vinculadas, de bens e/ou valores.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7053, 1, '3.5.2.1.0.00.00.00.00.00', 'DISTRIBUIÇÃO CONSTITUCIONAL OU LEGAL DE RECEITAS', 'Compreende as variações patrimoniais diminutivas decorrentes da transferência a outras esferas de governo de receitas tributárias, de contribuições e de outras receitas vinculadas, prevista na constituição ou em leis específicas, cuja competência de arrecadação é do órgão transferidor.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7054, 1, '3.5.2.1.1.00.00.00.00.00', 'DISTRIBUIÇÃO CONSTITUCIONAL OU LEGAL DE RECEITAS - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais diminutivas decorrentes da transferência a outras esferas de governo de receitas tributárias, de contribuições e de outras receitas vinculadas, prevista na constituição ou em leis específicas, cuja competência de arrecadação é do órgão transferidor. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS). Por exemplo, empresa independente de um ente recebendo transferência de outro ente. (a empresa independente não pertence ao OFSS mas pertence ao conceito de governamental).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7055, 1, '3.5.2.1.3.00.00.00.00.00', 'DISTRIBUIÇÃO CONSTITUCIONAL OU LEGAL DE RECEITAS - INTER OFSS - UNIÃO', 'Compreende as variações patrimoniais diminutivas decorrentes da transferência a outras esferas de governo de receitas tributárias, de contribuições e de outras receitas vinculadas, prevista na constituição ou em leis específicas, cuja competência de arrecadação é do órgão transferidor.Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) de entes públicos distintos, para permitir a consolidação nacional realizada pelo Poder Executivo da União.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7056, 1, '3.5.2.1.4.00.00.00.00.00', 'DISTRIBUIÇÃO CONSTITUCIONAL OU LEGAL DE RECEITAS - INTER OFSS - ESTADO', 'Compreende as variações patrimoniais diminutivas decorrentes da transferência a outras esferas de governo de receitas tributárias, de contribuições e de outras receitas vinculadas, prevista na Constituição ou em leis específicas, cuja competência de arrecadação é do órgão transferidor. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7057, 1, '3.5.2.1.5.00.00.00.00.00', 'DISTRIBUIÇÃO CONSTITUCIONAL OU LEGAL DE RECEITAS - INTER OFSS - MUNICÍPIO', 'Compreende as variações patrimoniais diminutivas decorrentes da transferência a outras esferas de governo de receitas tributárias, de contribuições e de outras receitas vinculadas, prevista na constituição ou em leis específicas, cuja competência de arrecadação é do órgão transferidor. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7058, 1, '3.5.2.2.0.00.00.00.00.00', 'TRANSFERÊNCIAS AO FUNDEB', 'Compreende as variações patrimoniais diminutivas decorrentes da transferência de recursos dos entes, incluindo a complementação da União, para a composição do Fundo de Manutenção e Desenvolvimento da Educação Básica e de Valorização dos Profissionais da Educação, instituído pela E.C. n.º 53/2006 e regulamentado pela lei 11.494/2007.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7059, 1, '3.9.3.0.0.00.00.00.00.00', 'OPERAÇÕES DA AUTORIDADE MONETÁRIA', 'Compreende as variações patrimoniais diminutivas do Banco Central do Brasil, na qualidade de autoridade monetária. Conta de uso exclusivo da União. ', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7060, 1, '3.5.2.2.4.00.00.00.00.00', 'TRANSFERÊNCIAS AO FUNDEB - INTER-OFSS - ESTADO ', 'Compreende as variações patrimoniais diminutivas decorrentes da transferência de recursos dos entes,incluindo a complementação da União, para a composição do Fundo de Manutenção e Desenvolvimento da Educação Básica e de Valorização dos Profissionais da Educação, instituído pela E.C. n.º 53/2006 e regulamentado pela lei 11.494/2007. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7061, 1, '3.5.2.3.0.00.00.00.00.00', 'TRANSFERÊNCIAS VOLUNTÁRIAS', 'Compreende as variações patrimoniais diminutivas decorrentes de transferências voluntárias a União, estados, distrito federal, municípios, inclusive as entidades vinculadas, bem como a demais entidades, de bens e/ou valores.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7062, 1, '3.5.2.3.1.00.00.00.00.00', 'TRANSFERÊNCIAS VOLUNTÁRIAS - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais diminutivas decorrentes de transferências voluntárias a União, estados, distrito federal, municípios, inclusive as entidades vinculadas, de bens e/ou valores. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS). Por exemplo, empresa independente de um ente recebendo transferência de outro ente. (A empresa independente não pertence ao OFSS, mas pertence ao conceito de governamental).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7063, 1, '3.5.2.3.3.00.00.00.00.00', 'TRANSFERÊNCIAS VOLUNTÁRIAS - INTER OFSS - UNIÃO', 'Compreende as variações patrimoniais diminutivas decorrentes de transferências voluntárias de bens e/ou valores. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7064, 1, '3.5.2.3.4.00.00.00.00.00', 'TRANSFERÊNCIAS VOLUNTÁRIAS - INTER-OFSS - ESTADO ', 'Compreende as variações patrimoniais diminutivas decorrentes de transferências voluntárias de bens e/ou valores. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7065, 1, '3.5.2.3.5.00.00.00.00.00', 'TRANSFERÊNCIAS VOLUNTÁRIAS - INTER-OFSS - MUNICÍPIO ', 'Compreende as variações patrimoniais diminutivas decorrentes de transferências voluntárias de bens e/ou valores. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7066, 1, '3.5.2.4.0.00.00.00.00.00', 'OUTRAS TRANSFERÊNCIAS', 'Compreende as variações patrimoniais diminutivas decorrentes demais transferências a União, estados, distrito federal, municípios, inclusive as entidades vinculadas, de bens e/ou valores.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7067, 1, '3.5.2.4.1.00.00.00.00.00', 'OUTRAS TRANSFERÊNCIAS - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais diminutivas decorrentes demais transferências a União, estados, distrito federal, municípios, inclusive as entidades vinculadas, de bens e/ou valores. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7068, 1, '3.5.2.4.3.00.00.00.00.00', 'OUTRAS TRANSFERÊNCIAS - INTER OFSS - UNIÃO', 'Compreende as variações patrimoniais diminutivas decorrentes demais transferências a União, estados, distrito federal, municípios, inclusive as entidades vinculadas, de bens e/ou valores. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7069, 1, '3.5.2.4.4.00.00.00.00.00', 'OUTRAS TRANSFERÊNCIAS - INTER OFSS - ESTADO', 'Compreende as variações patrimoniais diminutivas decorrentes demais transferências a União, estados, distrito federal, municípios, inclusive as entidades vinculadas, de bens e/ou valores. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7070, 1, '3.5.2.4.5.00.00.00.00.00', 'OUTRAS TRANSFERÊNCIAS - INTER OFSS - MUNICÍPIO', 'Compreende as variações patrimoniais diminutivas decorrentes demais transferências a União, estados, distrito federal, municípios, inclusive as entidades vinculadas, de bens e/ou valores. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7071, 1, '3.5.3.0.0.00.00.00.00.00', 'TRANSFERÊNCIAS A INSTITUIÇÕES PRIVADAS', 'Compreende as variações patrimoniais diminutivas decorrentes das transferências financeiras a instituições privadas, inclusive de bens e valores.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7072, 1, '3.5.3.1.0.00.00.00.00.00', 'TRANSFERÊNCIAS A INSTITUIÇÕES PRIVADAS SEM FINS LUCRATIVOS', 'Compreende as variações patrimoniais diminutivas decorrentes das transferências de bens e valores a instituições privadas sem fins lucrativos que não tenham vinculo com a administração pública, exemplo: ONGs, OSCIPS e OS.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7073, 1, '3.6.1.5.1.01.00.00.00.00', 'REDUÇÃO A VALOR RECUPERÁVEL DE BENS MÓVEIS', 'Compreende a variação patrimonial diminutiva com a redução nos benefícios econômicos futuros ou no potencial de serviços de bens móveis, que reflete um declínio na sua utilidade além do reconhecimento sistemático por meio da depreciação.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7074, 1, '3.5.3.1.1.00.00.00.00.00', 'TRANSFERÊNCIAS A INSTITUIÇÕES PRIVADAS SEM FINS LUCRATIVOS - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais diminutivas decorrentes das transferências de bens e valores a instituições privadas sem fins lucrativos que não tenham vinculo com a administração pública, exemplo: ONGs,OSCIPS E OS. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7075, 1, '3.5.3.2.0.00.00.00.00.00', 'TRANSFERÊNCIAS A INSTITUIÇÕES PRIVADAS COM FINS LUCRATIVOS', 'Compreende as variações patrimoniais diminutivas decorrentes das transferências de bens e valores a instituições privadas com fins lucrativos que não tenham vínculos com administração pública.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7076, 1, '3.5.3.2.1.00.00.00.00.00', 'TRANSFERÊNCIAS A INSTITUIÇÕES PRIVADAS COM FINS LUCRATIVOS - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais diminutivas decorrentes das transferências de bens e valores a instituições privadas com fins lucrativos, que não tenham vínculos com a administração pública. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7077, 1, '3.5.4.0.0.00.00.00.00.00', 'TRANSFERÊNCIAS A INSTITUIÇÕES MULTIGOVERNAMENTAIS', 'Compreende as variações patrimoniais diminutivas decorrentes das transferências a instituições multigovernamentais, da quais o ente transferidor não participe.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7078, 1, '3.5.4.0.1.00.00.00.00.00', 'TRANSFERÊNCIAS A INSTITUIÇÕES MULTIGOVERNAMENTAIS - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais diminutivas decorrentes das transferências a instituições multigovernamentais, das quais o ente transferidor não participe. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7079, 1, '3.5.5.0.0.00.00.00.00.00', 'TRANSFERÊNCIAS A CONSÓRCIOS PÚBLICOS', 'Compreende as variações patrimoniais diminutivas decorrentes das transferências a consórcios públicos, dos quais o ente transferidor participe.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7080, 1, '3.5.5.0.1.00.00.00.00.00', 'TRANSFERÊNCIAS A CONSÓRCIOS PÚBLICOS - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais diminutivas decorrentes das transferências a consórcios públicos, dos quais o ente transferidor participe. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7081, 1, '3.5.6.0.0.00.00.00.00.00', 'TRANSFERÊNCIAS AO EXTERIOR', 'Compreende as variações patrimoniais diminutivas decorrentes de transferências a organismos e fundos internacionais, de governos estrangeiros e instituições privadas com ou sem fins lucrativos no exterior.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7083, 1, '3.5.7.0.0.00.00.00.00.00', 'EXECUÇÃO ORÇAMENTÁRIA DELEGADA', 'Compreende as variações patrimoniais diminutivas decorrentes de transferência de recursos financeiros, decorrentes de delegação ou descentralização aos Entes (União, Estados, Distrito Federal ou Municípios) ou Consórcios Públicos para execução de ações de responsabilidade exclusiva do delegante.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7084, 1, '3.5.7.1.0.00.00.00.00.00', 'EXECUÇÃO ORÇAMENTÁRIA DELEGADA A ENTES', 'Compreende as variações patrimoniais diminutivas decorrentes de transferência de recursos financeiros, decorrentes de delegação ou descentralização aos Entes (União, Estados, Distrito Federal, Municípios ou consórcios públicos) para execução de ações de responsabilidade exclusiva do delegante.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7085, 1, '3.5.7.1.3.00.00.00.00.00', 'EXECUÇÃO ORÇAMENTÁRIA DELEGADA A ENTES - INTER OFSS - UNIÃO', 'Compreende as variações patrimoniais diminutivas decorrentes de transferência de recursos financeiros, decorrentes de delegação ou descentralização aos Entes (União, Estados, Distrito Federal ou Municípios) para execução de ações de responsabilidade exclusiva do delegante. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7086, 1, '3.5.7.1.4.00.00.00.00.00', 'EXECUÇÃO ORÇAMENTÁRIA DELEGADA A ENTES - INTER OFSS - ESTADO', 'Compreende as variações patrimoniais diminutivas decorrentes de transferência de recursos financeiros, decorrentes de delegação ou descentralização aos Entes (União, Estados, Distrito Federal ou Municípios) para execução de ações de responsabilidade exclusiva do delegante. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7087, 1, '3.5.7.1.5.00.00.00.00.00', 'EXECUÇÃO ORÇAMENTÁRIA DELEGADA A ENTES - INTER OFSS - MUNICÍPIO', 'Compreende as variações patrimoniais diminutivas decorrentes de transferência de recursos financeiros, decorrentes de delegação ou descentralização aos Entes (União, Estados, Distrito Federal ou Municípios) para execução de ações de responsabilidade exclusiva do delegante. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7088, 1, '3.5.7.2.0.00.00.00.00.00', 'EXECUÇÃO ORÇAMENTÁRIA DELEGADA A CONSÓRCIOS', 'Compreende as variações patrimoniais diminutivas decorrentes de transferência de recursos financeiros, decorrentes de delegação ou descentralização aos Consórcios Públicos para execução de ações de responsabilidade exclusiva do delegante.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7089, 1, '3.5.7.2.1.00.00.00.00.00', 'EXECUÇÃO ORÇAMENTÁRIA DELEGADA A CONSÓRCIOS - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais diminutivas decorrentes de transferência de recursos financeiros, decorrentes de delegação ou descentralização aos Consórcios Públicos para execução de ações de responsabilidade exclusiva do delegante. Compreende os valores de operações efetuadas entre uma unidade pertencente ao orçamento fiscal e da seguridade social (OFSS) com unidade que não pertença ao OFSS de ente público.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7090, 1, '3.5.9.0.0.00.00.00.00.00', 'OUTRAS TRANSFERÊNCIAS E DELEGAÇÕES CONCEDIDAS', 'Compreende as variações patrimoniais diminutivas decorrentes de demais transferências e delegações concedidas não compreendidas nas contas anteriores. ', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7091, 1, '3.5.9.0.1.00.00.00.00.00', 'OUTRAS TRANSFERÊNCIAS CONCEDIDAS - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais diminutivas decorrentes de demais transferências concedidas não compreendidas nas contas anteriores. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7092, 1, '3.6.1.5.1.02.00.00.00.00', 'REDUÇÃO A VALOR RECUPERÁVEL DE BENS IMÓVEIS', 'Compreende a variação patrimonial diminutiva com a redução nos benefícios econômicos futuros ou no potencial de serviços de bens imóveis, que reflete um declínio na sua utilidade além do reconhecimento sistemático por meio da depreciação.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7093, 1, '3.6.0.0.0.00.00.00.00.00', 'DESVALORIZAÇÃO E PERDA DE ATIVOS E INCORPORAÇÃO DE PASSIVOS', 'Compreende a variação patrimonial diminutiva com desvalorização e perdas de ativos, nos casos de reavaliação, redução a valor recuperável, provisões para perdas, perdas com alienação e perdas involuntárias. Compreende também a variação patrimonial diminutiva com incorporação de passivo.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7094, 1, '3.6.1.0.0.00.00.00.00.00', 'REAVALIAÇÃO, REDUÇÃO A VALOR RECUPERÁVEL E AJUSTE PARA PERDAS', 'Compreende as variações patrimoniais diminutivas relativas a reavaliação, redução a valor recuperável e ajuste para perdas.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7095, 1, '3.9.7.1.0.00.00.00.00.00', 'VPD DE PROVISÃO PARA RISCOS TRABALHISTAS', 'Compreende os passivos de prazo ou de valor incertos, relacionados a pagamento de reclamações trabalhistas.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7096, 1, '3.6.1.1.0.00.00.00.00.00', 'REAVALIAÇÃO DE IMOBILIZADO', 'Compreende a variação patrimonial diminutiva relativa à adoção do valor de mercado ou de consenso entre as partes para bens do ativo imobilizado, quando esse for inferior ao valor liquido contábil.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7097, 1, '3.9.3.1.0.00.00.00.00.00', 'JUROS', 'Compreende as variações patrimoniais diminutivas com juros do Banco Central do Brasil, na qualidade de autoridade monetária. Conta de uso exclusivo da União.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7098, 1, '3.6.1.1.1.00.00.00.00.00', 'REAVALIAÇÃO DE IMOBILIZADO - CONSOLIDAÇÃO', 'Compreende a variação patrimonial diminutiva relativa à adoção do valor de mercado ou de consenso entre as partes para bens do ativo imobilizado, quando esse for inferior ao valor liquido contábil. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
