insert into contabilidade.planocontadetalhe values (7101, 1, '3.6.1.2.0.00.00.00.00.00', 'REAVALIAÇÃO DE INTANGÍVEIS', 'Compreende a variação patrimonial diminutiva relativa à adoção do valor de mercado ou de consenso entre as partes para ativos intangíveis, quando esse for inferior ao valor liquido contábil.', 1, false, 0, 'N');
