insert into contabilidade.planocontadetalhe values (7103, 1, '3.6.1.3.0.00.00.00.00.00', 'REAVALIAÇÃO DE OUTROS ATIVOS', 'Compreende a variação patrimonial diminutiva relativa à adoção do valor de mercado ou de consenso entre as partes para outros ativos, quando esse for inferior ao valor liquido contábil.', 1, false, 0, 'N');
