insert into contabilidade.planocontadetalhe values (7105, 1, '3.6.1.4.0.00.00.00.00.00', 'REDUÇÃO A VALOR RECUPERÁVEL DE INVESTIMENTOS', 'Compreende a variação patrimonial diminutiva com a redução nos benefícios econômicos futuros ou no potencial de serviços de um investimento, que reflete um declínio na sua utilidade além do reconhecimento sistemático por meio da depreciação.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7106, 1, '3.6.1.4.1.00.00.00.00.00', 'REDUÇÃO A VALOR RECUPERÁVEL DE INVESTIMENTOS - CONSOLIDAÇÃO', 'Compreende a variação patrimonial diminutiva com a redução nos benefícios econômicos futuros ou no potencial de serviços de um investimento, que reflete um declínio na sua utilidade além do reconhecimento sistemático por meio da depreciação.Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7107, 1, '3.6.1.4.2.00.00.00.00.00', 'REDUÇÃO A VALOR RECUPERÁVEL DE INVESTIMENTOS - INTRA OFSS', 'Compreende a variação patrimonial diminutiva com a redução nos benefícios econômicos futuros ou no potencial de serviços de um investimento, que reflete um declínio na sua utilidade além do reconhecimento sistemático por meio da depreciação. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do ente.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7108, 1, '3.6.1.4.3.00.00.00.00.00', 'REDUÇÃO A VALOR RECUPERÁVEL DE INVESTIMENTOS - INTER OFSS - UNIÃO', 'Compreende a variação patrimonial diminutiva com a redução nos benefícios econômicos futuros ou no potencial de serviços de um investimento, que reflete um declínio na sua utilidade além do reconhecimento sistemático por meio da depreciação. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7109, 1, '3.6.1.4.4.00.00.00.00.00', 'REDUÇÃO A VALOR RECUPERÁVEL DE INVESTIMENTOS - INTER OFSS - ESTADO', 'Compreende a variação patrimonial diminutiva com a redução nos benefícios econômicos futuros ou no potencial de serviços de um investimento, que reflete um declínio na sua utilidade além do reconhecimento sistemático por meio da depreciação.Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7110, 1, '3.6.1.4.5.00.00.00.00.00', 'REDUÇÃO A VALOR RECUPERÁVEL DE INVESTIMENTOS - INTER OFSS - MUNICÍPIO', 'Compreende a variação patrimonial diminutiva com a redução nos benefícios econômicos futuros ou no potencial de serviços de um investimento, que reflete um declínio na sua utilidade além do reconhecimento sistemático por meio da depreciação.Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7111, 1, '3.6.1.5.0.00.00.00.00.00', 'REDUÇÃO A VALOR RECUPERÁVEL DE IMOBILIZADO', 'Compreende a variação patrimonial diminutiva com a redução nos benefícios econômicos futuros ou no potencial de serviços de um ativo imobilizado, que reflete um declínio na sua utilidade além do reconhecimento sistemático por meio da depreciação.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7112, 1, '3.6.1.5.1.00.00.00.00.00', 'REDUÇÃO A VALOR RECUPERÁVEL DE IMOBILIZADO - CONSOLIDAÇÃO', 'Compreende a variação patrimonial diminutiva com a redução nos benefícios econômicos futuros ou no potencial de serviços de um ativo imobilizado, que reflete um declínio na sua utilidade além do reconhecimento sistemático por meio da depreciação. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7113, 1, '4.3.1.9.1.97.00.00.00.00', '(-) DEDUÇÕES DE VENDAS', 'Compreende as deduções das vendas de mercadorias, como devoluções, abatimentos e descontos comerciais concedidos. Dedução de Vendas.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7114, 1, '3.6.1.6.0.00.00.00.00.00', 'REDUÇÃO A VALOR RECUPERÁVEL DE INTANGÍVEIS', 'Compreende a variação patrimonial diminutiva com a redução nos benefícios econômicos futuros ou no potencial de serviços de um ativo intangível, que reflete um declínio na sua utilidade além do reconhecimento sistemático por meio da depreciação.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7115, 1, '3.6.1.6.1.00.00.00.00.00', 'REDUÇÃO A VALOR RECUPERÁVEL DE INTANGÍVEIS - CONSOLIDAÇÃO', 'Compreende a variação patrimonial diminutiva com a redução nos benefícios econômicos futuros ou no potencial de serviços de um ativo intangível, que reflete um declínio na sua utilidade além do reconhecimento sistemático por meio da depreciação. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7116, 1, '2.1.1.3.1.01.00.00.00.00', 'BENEFICIOS ASSISTENCIAIS A PAGAR', 'Registra as obrigações relativas aos benefícios assistenciais a pagar.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (7117, 1, '3.6.1.7.0.00.00.00.00.00', 'VARIAÇÃO PATRIMONIAL DIMINUTIVA COM AJUSTE DE PERDAS DE CRÉDITOS E DE INVESTIMENTOS E APLICAÇÕES TEMPORÁRIOS', 'Compreende a variação patrimonial diminutiva com ajuste de perdas de créditos por inadimplência ou outros fatores que impossibilitam o recebimento de créditos. Por exemplo, a variação patrimonial diminutiva com ajuste para créditos de liquidação duvidosa e ajuste para créditos da dívida ativa. Compreende também a variação patrimonial diminutiva com ajuste de perdas em investimentos e aplicações temporários, não destinados à negociação e que não façam parte das atividades operacionais da entidade, resgatáveis no curto e no longo prazo.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7136, 1, '3.6.2.2.0.00.00.00.00.00', 'PERDAS COM ALIENAÇÃO DE IMOBILIZADO', 'Compreende a perda com alienação de ativos imobilizados, ou seja, quando o valor alienado do ativo e menor que o seu valor contábil, de maneira que a diferença compreende a perda.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7118, 1, '3.6.1.7.1.00.00.00.00.00', 'VARIAÇÃO PATRIMONIAL DIMINUTIVA COM AJUSTE DE PERDAS DE CRÉDITOS  E DE INVESTIMENTOS E APLICAÇÕES TEMPORÁRIOS- CONSOLIDAÇÃO', 'Compreende a variação patrimonial diminutiva com ajuste de perdas de créditos por inadimplência ou outros fatores que impossibilitam o recebimento de créditos. Compreende também a variação patrimonial diminutiva com ajuste de perdas em investimentos e aplicações temporários, não destinados à negociação e que não façam parte das atividades operacionais da entidade, resgatáveis no curto e no longo prazo. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7119, 1, '3.6.1.7.1.05.00.00.00.00', 'AJUSTE PARA PERDAS EM DÍVIDA ATIVA TRIBUTÁRIA', 'Compreende a variação patrimonial diminutiva com ajuste para perdas em créditos da dívida ativa tributária.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7120, 1, '3.6.1.7.1.07.00.00.00.00', 'AJUSTE PARA PERDAS EM INVESTIMENTOS E APLICAÇÕES TEMPORÁRIOS', 'Compreende a variação patrimonial diminutiva com ajuste de perdas em investimentos e aplicações temporários, não destinados à negociação e que não façam parte das atividades operacionais da entidade, resgatáveis no curto e no longo prazo.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7121, 1, '6.2.1.3.0.00.00.00.00.00', '(-) DEDUÇÕES DA RECEITA ORÇAMENTÁRIA', 'Compreende o somatório dos valores relativos às deduções de receitas realizadas (devoluções, restituições, e outras), detalhada por natureza de receita.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7122, 1, '3.6.1.7.2.00.00.00.00.00', 'VARIAÇÃO PATRIMONIAL DIMINUTIVA COM AJUSTE DE PERDAS DE CRÉDITOS E DE INVESTIMENTOS E APLICAÇÕES TEMPORÁRIOS- INTRA OFSS', 'Compreende a variação patrimonial diminutiva com ajuste de perdas de créditos por inadimplência ou outros fatores que impossibilitam o recebimento de créditos.  Compreende também a variação patrimonial diminutiva com ajuste de perdas em investimentos e aplicações temporários, não destinados à negociação e que não façam parte das atividades operacionais da entidade, resgatáveis no curto e no longo prazo. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do ente.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7123, 1, '3.6.1.7.2.05.00.00.00.00', 'AJUSTE PARA PERDAS EM DÍVIDA ATIVA TRIBUTÁRIA', 'Compreende a variação patrimonial diminutiva com ajuste para perdas em créditos da dívida ativa tributária.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7124, 1, '3.6.1.7.3.00.00.00.00.00', 'VARIAÇÃO PATRIMONIAL DIMINUTIVA COM AJUSTE DE PERDAS DE CRÉDITOS E DE INVESTIMENTOS E APLICAÇÕES TEMPORÁRIOS - INTER OFSS - UNIÃO', 'Compreende a variação patrimonial diminutiva com ajuste de perdas de créditos por inadimplência ou outros fatores que impossibilitam o recebimento de créditos.  Compreende também a variação patrimonial diminutiva com ajuste de perdas em investimentos e aplicações temporários, não destinados à negociação e que não façam parte das atividades operacionais da entidade, resgatáveis no curto e no longo prazo. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7125, 1, '3.6.1.7.3.05.00.00.00.00', 'AJUSTE PARA PERDAS EM DÍVIDA ATIVA TRIBUTÁRIA', 'Compreende a variação patrimonial diminutiva com ajuste para perdas em créditos da dívida ativa tributária.', 1, false, 0, 'N');
