insert into contabilidade.planocontadetalhe values (7127, 1, '3.6.1.7.4.05.00.00.00.00', 'AJUSTE PARA PERDAS EM DÍVIDA ATIVA TRIBUTÁRIA', 'Compreende a variação patrimonial diminutiva com ajuste para perdas em créditos da dívida ativa tributária.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7128, 1, '3.6.1.7.5.00.00.00.00.00', 'VARIAÇÃO PATRIMONIAL DIMINUTIVA COM AJUSTE DE PERDAS DE CRÉDITOS E DE INVESTIMENTOS E APLICAÇÕES TEMPORÁRIOS- INTER OFSS - MUNICÍPIO', 'Compreende a variação patrimonial diminutiva com ajuste de perdas de créditos por inadimplência ou outros fatores que impossibilitam o recebimento de créditos.  Compreende também a variação patrimonial diminutiva com ajuste de perdas em investimentos e aplicações temporários, não destinados à negociação e que não façam parte das atividades operacionais da entidade, resgatáveis no curto e no longo prazo. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7129, 1, '3.6.1.7.5.05.00.00.00.00', 'AJUSTE PARA PERDAS EM DÍVIDA ATIVA TRIBUTÁRIA', 'Compreende a variação patrimonial diminutiva com ajuste para perdas em créditos da dívida ativa tributária.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7130, 1, '3.6.1.8.0.00.00.00.00.00', 'VARIAÇÃO PATRIMONIAL DIMINUTIVA COM AJUSTE DE PERDAS DE ESTOQUES', 'Compreende a variação patrimonial diminutiva com ajuste para redução a valor de mercado de estoques.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7131, 1, '3.6.1.8.1.00.00.00.00.00', 'VARIAÇÃO PATRIMONIAL DIMINUTIVA COM AJUSTE DE PERDAS DE ESTOQUES - CONSOLIDAÇÃO', 'Compreende a variação patrimonial diminutiva com ajuste para perdas de estoques. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7132, 1, '3.6.2.0.0.00.00.00.00.00', 'PERDAS COM ALIENAÇÃO ', 'Compreende a perda com alienação de ativos, ou seja, quando o valor alienado do ativo e menor que o seu valor contábil, de maneira que a diferença compreende a perda.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7133, 1, '3.6.2.1.0.00.00.00.00.00', 'PERDAS COM ALIENAÇÃO DE INVESTIMENTOS', 'Compreende a perda com alienação de investimentos, ou seja, quando o valor alienado do ativo e menor que o seu valor contábil, de maneira que a diferença compreende a perda.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7134, 1, '8.1.1.1.1.01.05.00.00.00', 'HIPOTECAS A EXECUTAR', 'Registra o valor das garantias por hipoteca pendentes de execução, no país.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (7135, 1, '3.6.2.1.1.00.00.00.00.00', 'PERDAS COM ALIENAÇÃO DE INVESTIMENTOS - CONSOLIDAÇÃO', 'Compreende a perda com alienação de investimentos, ou seja, quando o valor alienado do ativo e menor que o seu valor contábil, de maneira que a diferença compreende a perda. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
