insert into contabilidade.planocontadetalhe values (7138, 1, '3.6.2.2.1.01.00.00.00.00', 'PERDAS COM ALIENAÇÃO DE BENS MOVEIS', 'Registra a variação patrimonial diminutiva de perdas com alienação de bens móveis.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7139, 1, '3.6.2.3.0.00.00.00.00.00', 'PERDAS COM ALIENAÇÃO DE INTANGÍVEIS', 'Compreende a perda com alienação de ativos intangíveis, ou seja, quando o valor alienado do ativo e menor que o seu valor contábil, de maneira que a diferença compreende a perda.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7140, 1, '3.6.2.3.1.00.00.00.00.00', 'PERDAS COM ALIENAÇÃO DE INTANGÍVEIS - CONSOLIDAÇÃO', 'Registra a perda com alienação de ativos intangíveis, ou seja, quando o valor alienado do ativo e menor que o seu valor contábil, de maneira que a diferença compreende a perda. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7141, 1, '3.6.2.9.0.00.00.00.00.00', 'PERDAS COM ALIENAÇÃO DE DEMAIS ATIVOS', 'Compreende a perda com alienação de demais ativos, não discriminados nas categorias anteriores, incluindo os investimentos do RPPS, quando o valor alienado do ativo e menor que o seu valor contábil, de maneira que a diferença compreende a perda.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7142, 1, '3.9.1.4.1.00.00.00.00.00', 'PREMIAÇÕES DESPORTIVAS - CONSOLIDAÇÃO', 'Registra o valor gasto com prêmios, condecorações, medalhas, troféus, etc., de caráter desportivo. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7143, 1, '3.6.2.9.1.00.00.00.00.00', 'PERDAS COM ALIENAÇÃO DE DEMAIS ATIVOS - CONSOLIDAÇÃO', 'Registra a perda com alienação de demais ativos, não discriminados nas categorias anteriores, incluindo os investimentos do RPPS, quando o valor alienado do ativo e menor que o seu valor contábil, de maneira que a diferença compreende a perda. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7144, 1, '3.6.3.0.0.00.00.00.00.00', 'PERDAS INVOLUNTÁRIAS', 'Compreendem o desfazimento físico involuntário do bem, como o que resulta de sinistros como incêndio e inundações.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7145, 1, '3.6.3.1.0.00.00.00.00.00', 'PERDAS INVOLUNTÁRIAS COM IMOBILIZADO', 'Compreendem o desfazimento físico involuntário de bem do ativo imobilizado, como o que resulta de sinistros como incêndio e inundações.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7146, 1, '3.6.3.1.1.00.00.00.00.00', 'PERDAS INVOLUNTÁRIAS COM IMOBILIZADO - CONSOLIDAÇÃO', 'Compreende o desfazimento físico involuntário de bem do ativo imobilizado, como o que resulta de sinistros como incêndio e inundações. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7147, 1, '3.6.3.1.1.01.00.00.00.00', 'PERDAS INVOLUNTÁRIAS DE BENS MOVEIS', 'Registra a variação patrimonial diminutiva com perdas involuntárias de bens móveis.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7148, 1, '3.6.3.2.0.00.00.00.00.00', 'PERDAS INVOLUNTÁRIAS COM INTANGÍVEIS', 'Compreendem o desfazimento físico involuntário de bem do ativo intangível, como o que resulta de sinistros como incêndio e inundações.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7149, 1, '3.6.3.2.1.00.00.00.00.00', 'PERDAS INVOLUNTÁRIAS COM INTANGÍVEIS - CONSOLIDAÇÃO', 'Registra o desfazimento físico involuntário de bem do ativo intangível, como o que resulta de sinistros como incêndio e inundações. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7150, 1, '3.6.3.3.0.00.00.00.00.00', 'PERDAS INVOLUNTÁRIAS COM ESTOQUES', 'Compreendem o desfazimento físico involuntário de bem do estoque, como o que resulta de sinistros como incêndio e inundações.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7151, 1, '3.6.3.3.1.00.00.00.00.00', 'PERDAS INVOLUNTÁRIAS COM ESTOQUES - CONSOLIDAÇÃO', 'Registra o desfazimento físico involuntário de bem do estoque, como o que resulta de sinistros como incêndio e inundações. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7152, 1, '3.6.3.9.0.00.00.00.00.00', 'OUTRAS PERDAS INVOLUNTÁRIAS', 'Compreendem o desfazimento físico involuntário de outros bens, como as que resultam de sinistros como incêndio e inundações.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7153, 1, '3.6.3.9.1.00.00.00.00.00', 'OUTRAS PERDAS INVOLUNTÁRIAS - CONSOLIDAÇÃO', 'Compreende o desfazimento físico involuntário de outros bens, como as que resultam de sinistros como incêndio e inundações. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7154, 1, '3.6.4.0.0.00.00.00.00.00', 'INCORPORAÇÃO DE PASSIVOS', 'Compreende a contrapartida de incorporação de passivo, como nos casos de extinção e fusão de entidades ou de restos a pagar com prescrição interrompida.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7155, 1, '3.6.4.0.1.00.00.00.00.00', 'INCORPORAÇÃO DE PASSIVOS - CONSOLIDAÇÃO', 'Compreende a variação patrimonial diminutiva com incorporação de passivo, como nos casos de extinção e fusão de entidades ou de restos a pagar com prescrição interrompida. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7156, 1, '3.6.5.0.0.00.00.00.00.00', 'DESINCORPORAÇÃO DE ATIVOS', 'Compreende a contrapartida de desincorporação de ativo,  como nos casos de baixa de ativos inservíveis ou outros eventos sob controle da entidade.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7157, 1, '3.7.2.3.0.00.00.00.00.00', 'CONTRIBUIÇÃO PARA O CUSTEIO DO SERVIÇO DE ILUMINAÇÃO PÚBLICA - COSIP', 'Compreende o valor da variação patrimonial diminutiva com a contribuição para custeio do serviço de iluminação pública (art.149-a da C.F.)', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7158, 1, '3.6.5.0.1.00.00.00.00.00', 'DESINCORPORAÇÃO DE ATIVOS - CONSOLIDAÇÃO', 'Compreende a contrapartida de desincorporação de ativo,  como nos casos de baixa de ativos inservíveis ou de desfalque de bens públicos ou outros eventos sob controle da entidade. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7159, 1, '3.6.5.0.1.01.00.00.00.00', 'DESINCORPORAÇÃO DE DÍVIDA ATIVA TRIBUTÁRIA', 'Compreende a contrapartida de desincorporação da dívida ativa tributária em virtude de cancelamento, anistia, remissão, adjudicação, anulação, prescrição, extinção, desconto ou abatimento.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7160, 1, '3.7.0.0.0.00.00.00.00.00', 'TRIBUTÁRIAS', 'Compreendem as variações patrimoniais diminutivas relativas aos impostos, taxas, contribuições de melhoria, contribuições sociais, contribuições econômicas e contribuições especiais.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7161, 1, '3.7.1.0.0.00.00.00.00.00', 'IMPOSTOS, TAXAS E CONTRIBUIÇÕES DE MELHORIA', 'Compreendem as variações patrimoniais diminutivas relativas às obrigações relativas às prestações pecuniárias compulsórias, em moeda ou cujo valor nela possa se exprimir, que não constitua sanção de ato ilícito, instituída em lei e cobrada mediante atividade vinculada. Como: impostos, taxas e contribuições de melhoria.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7162, 1, '3.7.1.1.0.00.00.00.00.00', 'IMPOSTOS', 'Compreende as variações patrimoniais diminutivas com impostos, apurados no período de competência, e vinculados à atividade administrativa do contribuinte, definidos no CTN.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7163, 1, '3.7.1.1.1.00.00.00.00.00', 'IMPOSTOS- CONSOLIDAÇÃO', 'Compreende as variações patrimoniais diminutivas com impostos, apurados no período de competência e vinculados atividade administrativa do contribuinte, definidos no CTN. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7164, 1, '3.7.1.2.0.00.00.00.00.00', 'TAXAS', 'Compreende as variações patrimoniais diminutivas com taxas cobradas pela União, Estados, Distrito Federal ou Municípios, no âmbito de suas respectivas contribuições, decorrentes da contraprestação de serviços públicos ao contribuinte postos a sua disposição, inclusive o exercício de poder de policia.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7165, 1, '3.7.1.2.1.00.00.00.00.00', 'TAXAS - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais diminutivas com taxas cobradas pela União, Estados, Distrito Federal ou Municípios, no âmbito de suas respectivas contribuições, decorrentes da contraprestação de serviços públicos ao contribuinte postos a sua disposição, inclusive o exercício de poder de policia. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7166, 1, '3.7.1.3.0.00.00.00.00.00', 'CONTRIBUIÇÕES DE MELHORIA', 'Compreende as variações patrimoniais diminutivas com tributo cuja obrigação tem por fato gerador um beneficio especial auferido pelo contribuinte que por consequência promove uma valorização imobiliária e patrimonial decorrente de obra pública de competência da União, Estados, Distrito Federal ou Municípios , amparadas em lei e limitadas ao total da despesa pública realizada.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7167, 1, '3.7.1.3.1.00.00.00.00.00', 'CONTRIBUIÇÕES DE MELHORIA - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais diminutivas com titulo cuja obrigação tem por fato gerador um beneficio especial auferido pelo contribuinte que por consequência promove uma valorização imobiliária e patrimonial decorrente de obra pública de competência da União, Estados, Distrito Federal ou municípios, amparadas em lei e limitadas ao total da despesa pública realizada. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7168, 1, '3.7.2.0.0.00.00.00.00.00', 'CONTRIBUIÇÕES', 'Compreende as variações patrimoniais diminutivas com contribuições sociais, econômicas e outras, decorrentes da intervenção do estado (União, estados, distrito federal e municípios) no domínio econômico e de interesse da categoria de profissionais.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7169, 1, '3.7.2.1.0.00.00.00.00.00', 'CONTRIBUIÇÕES SOCIAIS', 'Compreende a variação patrimonial diminutiva com contribuições sociais constituídas por ordem social e profissional, instituídas pelo estado, entre elas o PIS/PASEP, CSLL e COFINS, etc.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7170, 1, '3.7.2.1.1.00.00.00.00.00', 'CONTRIBUIÇÕES SOCIAIS - CONSOLIDAÇÃO', 'Compreende a variação patrimonial diminutiva com contribuições sociais constituídas por ordem social e profissional, instituídas pelo Estado, entre elas o PIS/PASEP, CSLL e COFINS, etc. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7171, 1, '3.7.2.1.2.00.00.00.00.00', 'CONTRIBUIÇÕES SOCIAIS - INTRA OFSS', 'Compreende a variação patrimonial diminutiva com contribuições sociais constituídas por ordem social e profissional, instituídas pelo Estado, entre elas o PIS/PASEP, CSLL e COFINS, etc. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do ente.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7172, 1, '3.7.2.1.3.00.00.00.00.00', 'CONTRIBUIÇÕES SOCIAIS - INTER OFSS - UNIÃO', 'Compreende a variação patrimonial diminutiva com contribuições sociais constituídas por ordem social e profissional, instituídas pelo Estado, entre elas o PIS/PASEP, CSLL e COFINS, etc. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7173, 1, '3.7.2.1.4.00.00.00.00.00', 'CONTRIBUIÇÕES SOCIAIS - INTER OFSS - ESTADO', 'Registra a variação patrimonial diminutiva com contribuições sociais constituídas por ordem social e profissional, instituídas pelo Estado, entre elas o PIS/PASEP, CSLL e COFINS, etc. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7174, 1, '3.7.2.1.5.00.00.00.00.00', 'CONTRIBUIÇÕES SOCIAIS - INTER OFSS - MUNICÍPIO', 'Registra a variação patrimonial diminutiva com contribuições sociais constituídas por ordem social e profissional, instituídas pelo Estado, entre elas o PIS/PASEP,CSLL e COFINS, etc. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7175, 1, '3.7.2.2.0.00.00.00.00.00', 'CONTRIBUIÇÕES DE INTERVENÇÃO NO DOMÍNIO ECONÔMICO', 'Compreende a variação patrimonial diminutiva com contribuições de intervenção no domínio econômico.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7176, 1, '3.7.2.2.1.00.00.00.00.00', 'CONTRIBUIÇÕES DE INTERVENÇÃO NO DOMÍNIO ECONÔMICO - CONSOLIDAÇÃO', 'Registra a variação patrimonial diminutiva com contribuições de intervenção no domínio econômico. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7177, 1, '4.3.2.9.0.00.00.00.00.00', '(-) DEDUÇÕES DE VENDA BRUTA DE PRODUTOS', 'Compreende as deduções das vendas de produtos, como devoluções, abatimentos e descontos comerciais concedidos.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7670, 1, '2.1.2.3.1.01.98.00.00.00', 'OUTROS FINANCIAMENTOS INTERNOS', 'Registra os valores exigíveis, decorrentes de financiamentos internos a curto prazo para os quais não haja contas específicas.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (7178, 1, '3.7.2.3.1.00.00.00.00.00', 'CONTRIBUIÇÃO PARA O CUSTEIO DO SERVIÇO DE ILUMINAÇÃO PÚBLICA - COSIP - CONSOLIDAÇÃO', 'Registra o valor da variação patrimonial diminutiva com a contribuição para custeio da iluminação pública (art.149-a da C.F.). Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7179, 1, '3.7.2.9.0.00.00.00.00.00', 'OUTRAS CONTRIBUIÇÕES', 'Compreende a variação patrimonial diminutiva com contribuições que não se enquadram na condição de sociais e econômicas.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7180, 1, '3.7.2.9.1.00.00.00.00.00', 'OUTRAS CONTRIBUIÇÕES - CONSOLIDAÇÃO', 'Compreende a variação patrimonial diminutiva com contribuições que não se enquadram na condição de sociais e econômicas. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7181, 1, '3.8.0.0.0.00.00.00.00.00', 'CUSTO DAS MERCADORIAS VENDIDAS, DOS PRODUTOS VENDIDOS E DOS SERVIÇOS PRESTADOS', 'Compreende as variações patrimoniais diminutivas relativas aos custos das mercadorias vendidas, dos produtos vendidos e dos serviços prestados.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7182, 1, '3.8.1.0.0.00.00.00.00.00', 'CUSTO DE MERCADORIAS VENDIDAS ', 'Compreende as variações patrimoniais diminutivas relativas aos custos apropriados às mercadorias, sendo registradas apenas no momento da venda destas.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7183, 1, '3.8.1.0.1.00.00.00.00.00', 'CUSTO DE MERCADORIAS VENDIDAS - CONSOLIDAÇÃO', 'Registra as variações patrimoniais diminutivas relativas aos custos apropriados às mercadorias, sendo registradas apenas no momento da venda destas. Compreende os saldos que não serão excluídos dos Demonstrativos Consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) ', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7184, 1, '3.8.1.0.2.00.00.00.00.00', 'CUSTO DE MERCADORIAS VENDIDAS - INTRA OFSS', 'Registra as variações patrimoniais diminutivas relativas aos custos apropriados às mercadorias, sendo registradas apenas no momento da venda destas. Compreende os saldos que não serão excluídos dos Demonstrativos Consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) ', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7185, 1, '3.8.1.0.3.00.00.00.00.00', 'CUSTO DE MERCADORIAS VENDIDAS -  INTER OFSS - UNIÃO', 'Registra as variações patrimoniais diminutivas relativas aos custos apropriados às mercadorias, sendo registradas apenas no momento da venda destas. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.      ', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7186, 1, '3.8.1.0.4.00.00.00.00.00', 'CUSTO DE MERCADORIAS VENDIDAS -  INTER OFSS - ESTADO', 'Registra as variações patrimoniais diminutivas relativas aos custos apropriados às mercadorias, sendo registradas apenas no momento da venda destas. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7187, 1, '3.9.1.5.0.00.00.00.00.00', 'ORDENS HONORIFICAS', 'Compreende o valor gasto com prêmios, condecorações, medalhas, troféus, insígnias etc., relativo a ordens honorificas.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7188, 1, '3.8.1.0.5.00.00.00.00.00', 'CUSTO DE MERCADORIAS VENDIDAS - INTER OFSS - MUNICÍPIO', 'Registra as variações patrimoniais diminutivas relativas aos custos apropriados às mercadorias, sendo registradas apenas no momento da venda destas. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7189, 1, '3.8.2.0.0.00.00.00.00.00', 'CUSTO DE PRODUTOS VENDIDOS', 'Compreende as variações patrimoniais diminutivas relativas aos custos apropriados aos produtos, sendo registradas apenas no momento da venda destes.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7190, 1, '3.8.2.0.1.00.00.00.00.00', 'CUSTO DOS PRODUTOS VENDIDOS-CONSOLIDAÇÃO', 'Registra as variações patrimoniais diminutivas relativas aos custos apropriados aos produtos, sendo registradas apenas no momento da venda destes. Compreende os saldos que não serão excluídos dos Demonstrativos Consolidados do Orçamento Fiscal e da Seguridade Social (OFSS)', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7191, 1, '3.8.2.0.2.00.00.00.00.00', 'CUSTO DOS PRODUTOS VENDIDOS-INTRA OFSS', 'Registra as variações patrimoniais diminutivas relativas aos custos apropriados aos produtos, sendo registradas apenas no momento da venda destes. Compreende os saldos que serão excluídos nos Demonstrativos Consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) do ente.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7192, 1, '3.8.2.0.3.00.00.00.00.00', 'CUSTO DOS PRODUTOS VENDIDOS-INTER OFSS UNIÃO', 'Registra as variações patrimoniais diminutivas relativas aos custos apropriados aos produtos, sendo registradas apenas no momento da venda destes. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.    ', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7193, 1, '3.8.2.0.4.00.00.00.00.00', 'CUSTO DOS PRODUTOS VENDIDOS-INTER OFSS ESTADO', 'Registra as variações patrimoniais diminutivas relativas aos custos apropriados aos produtos, sendo registradas apenas no momento da venda destes. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7194, 1, '3.8.2.0.5.00.00.00.00.00', 'CUSTO DOS PRODUTOS VENDIDOS-INTER OFSS MUNICÍPIO', 'Registra as variações patrimoniais diminutivas relativas aos custos apropriados aos produtos, sendo registradas apenas no momento da venda destes. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7195, 1, '3.8.3.0.0.00.00.00.00.00', 'CUSTO DE SERVIÇOS PRESTADOS', 'Compreende as variações patrimoniais diminutivas relativas a tributos utilizados na produção de serviços, sendo registrado apenas no momento da venda destes.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7196, 1, '3.8.3.0.1.00.00.00.00.00', 'CUSTO DE SERVIÇOS PRESTADOS-CONSOLIDAÇÃO', 'Registra as variações patrimoniais diminutivas relativas aos custos apropriados aos serviços, sendo registradas apenas no momento da prestação destes. Compreende os saldos que não serão excluídos dos Demonstrativos Consolidados do Orçamento Fiscal e da Seguridade Social (OFSS)', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7197, 1, '3.8.3.0.2.00.00.00.00.00', 'CUSTO DE SERVIÇOS PRESTADOS- INTRA OFSS', 'Registra as variações patrimoniais diminutivas relativas aos custos apropriados aos serviços, sendo registradas apenas no momento da prestação destes. Compreende os saldos que serão excluídos nos Demonstrativos Consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) do ente.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7198, 1, '1.1.2.9.4.05.00.00.00.00', '(-) PERDAS ESTIMADAS EM CRÉDITOS DE DÍVIDA ATIVA NÃO TRIBUTÁRIA ', 'Registra o ajuste para perdas estimadas com o não recebimento dos créditos inscritos em dívida ativa não tributária.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7199, 1, '3.8.3.0.3.00.00.00.00.00', 'CUSTO DE SERVIÇOS PRESTADOS- INTER OFSS UNIÃO', 'Registra as variações patrimoniais diminutivas relativas aos custos apropriados aos serviços, sendo registradas apenas no momento da prestação destes. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7200, 1, '3.8.3.0.4.00.00.00.00.00', 'CUSTO DE SERVIÇOS PRESTADOS- INTER OFSS ESTADO', 'Registra as variações patrimoniais diminutivas relativas aos custos apropriados aos serviços, sendo registradas apenas no momento da prestação destes. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7201, 1, '3.8.3.0.5.00.00.00.00.00', 'CUSTO DE SERVIÇOS PRESTADOS- INTER OFSS MUNICÍPIO', 'Registra as variações patrimoniais diminutivas relativas aos custos apropriados aos serviços, sendo registradas apenas no momento da prestação destes. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7202, 1, '3.9.0.0.0.00.00.00.00.00', 'OUTRAS VARIAÇÕES PATRIMONIAIS DIMINUTIVAS', 'Compreende o somatório das variações patrimoniais diminutivas não incluídas nos grupos anteriores. Compreende: premiações, incentivos, equalizações de preços e taxas, participações e contribuições, resultado negativo com participações, dentre outros.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7203, 1, '3.9.1.0.0.00.00.00.00.00', 'PREMIAÇÕES', 'Compreende as aquisições de prêmios, condecorações, medalhas, troféus, etc., bem como com o pagamento de prêmios em pecúnia, inclusive decorrentes de sorteios lotéricos.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7204, 1, '3.9.1.1.0.00.00.00.00.00', 'PREMIAÇÕES CULTURAIS', 'Compreende o valor gasto com prêmios, condecorações, medalhas, troféus, etc., de caráter cultural.', 1, false, 0, 'N');
