insert into contabilidade.planocontadetalhe values (7208, 1, '3.9.1.3.0.00.00.00.00.00', 'PREMIAÇÕES CIENTIFICAS', 'Compreende o valor gasto com prêmios, condecorações, medalhas, troféus, etc., de caráter cientifico.', 1, false, 0, 'N');
