insert into contabilidade.planocontadetalhe values (7227, 1, '3.9.3.4.1.00.00.00.00.00', 'CORREÇÃO CAMBIAL - CONSOLIDAÇÃO', 'Registra as variações patrimoniais diminutivas com correção cambial do Banco Central do Brasil, na qualidade de autoridade monetária. Conta de uso exclusivo da União. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).              ', 1, false, 0, 'N');
