insert into contabilidade.planocontadetalhe values (7230, 1, '3.9.4.0.0.00.00.00.00.00', 'INCENTIVOS', 'Compreende os incentivos financeiros concedidos relativos à educação, a ciência e a cultura', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7231, 1, '3.9.4.1.0.00.00.00.00.00', 'INCENTIVOS A EDUCAÇÃO', 'Compreende a ajuda financeira concedida pelo estado a estudantes comprovadamente carentes, e concessão de auxílio para o desenvolvimento de estudos e pesquisas de natureza cientifica realizadas por pessoas físicas na condição de estudante.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7232, 1, '3.9.4.1.1.00.00.00.00.00', 'INCENTIVOS A EDUCAÇÃO - CONSOLIDAÇÃO', 'Compreende a ajuda financeira concedida pelo estado a estudantes comprovadamente carentes, e concessão de auxílio para o desenvolvimento de estudos e pesquisas de natureza cientifica realizadas por pessoas físicas na condição de estudante. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7233, 1, '3.9.4.2.0.00.00.00.00.00', 'INCENTIVOS A CIÊNCIA', 'Compreende o apoio financeiro concedido a pesquisadores, individual ou coletivamente, exceto na condição de estudante, no desenvolvimento de pesquisas cientificas e tecnológicas, nas suas mais diversas modalidades.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7234, 1, '3.9.4.2.1.00.00.00.00.00', 'INCENTIVOS A CIÊNCIA - CONSOLIDAÇÃO', 'Compreende o apoio financeiro concedido a pesquisadores, individual ou coletivamente, exceto na condição de estudante, no desenvolvimento de pesquisas cientificas e tecnológicas, nas suas mais diversas modalidades. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7235, 1, '3.9.4.3.0.00.00.00.00.00', 'INCENTIVOS A CULTURA', 'Compreende os incentivos financeiros concedidos, visando à promoção da cultura.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7236, 1, '3.9.4.3.1.00.00.00.00.00', 'INCENTIVOS A CULTURA - CONSOLIDAÇÃO', 'Compreende os incentivos financeiros concedidos, visando à promoção da cultura. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7237, 1, '3.9.4.4.0.00.00.00.00.00', 'INCENTIVOS AO ESPORTE', 'Compreende os incentivos financeiros concedidos, visando à promoção do esporte.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7238, 1, '3.9.4.4.1.00.00.00.00.00', 'INCENTIVOS AO ESPORTE - CONSOLIDAÇÃO', 'Compreende os incentivos financeiros concedidos, visando à promoção do esporte. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7239, 1, '3.9.4.9.0.00.00.00.00.00', 'OUTROS INCENTIVOS', 'Compreende outros incentivos financeiros concedidos.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7240, 1, '3.9.4.9.1.00.00.00.00.00', 'OUTROS INCENTIVOS - CONSOLIDAÇÃO', 'Compreende os incentivos financeiros concedidos. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7241, 1, '3.9.5.0.0.00.00.00.00.00', 'SUBVENÇÕES ECONÔMICAS', 'Compreende a variação patrimonial diminutiva com o pagamento de subvenções econômicas, a qualquer título, autorizadas em leis específicas, tais como: ajuda financeira a entidades privadas com fins lucrativos; concessão de bonificações a produtores, distribuidores e vendedores; cobertura, direta ou indireta, de parcela de encargos de empréstimos e financiamentos e dos custos de aquisição, de produção, de escoamento, de distribuição, de venda e de manutenção de bens, produtos e serviços em geral; e, ainda, outras operações com características semelhantes.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7242, 1, '3.9.7.5.0.00.00.00.00.00', 'VPD DE PROVISÃO PARA REPARTIÇÃO DE CRÉDITOS', 'Compreende a constituição de provisões de passivos de prazo ou de valores incertos relacionados aos créditos tributários e não tributários reconhecidos no lançamento por parte do agente arrecadador, a serem repartidos com outros entes da federação.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7243, 1, '5.2.2.2.1.09.00.00.00.00', 'ALTERAÇÃO DE CREDITOS MOVIMENTADOS     ', 'Compreende o valor da movimentação de créditos orçamentários por acréscimo ou redução decorrente de alteração do quadro de detalhamento de despesa - QDD, por UG pertencente ao órgão ou entidade da unidade.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7244, 1, '3.9.5.0.1.00.00.00.00.00', 'SUBVENÇÕES ECONÔMICAS - CONSOLIDAÇÃO', 'Compreende a variação patrimonial diminutiva com o pagamento de subvenções econômicas, a qualquer título, autorizadas em leis específicas, tais como: ajuda financeira a entidades privadas com fins lucrativos; concessão de bonificações a produtores, distribuidores e vendedores; cobertura, direta ou indireta, de parcela de encargos de empréstimos e financiamentos e dos custos de aquisição, de produção, de escoamento, de distribuição, de venda e de manutenção de bens, produtos e serviços em geral; e, ainda, outras operações com características semelhantes. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7245, 1, '3.9.6.0.0.00.00.00.00.00', 'PARTICIPAÇÕES E CONTRIBUIÇÕES', 'Compreende as participações de terceiros nos lucros, não relativas ao investimento dos acionistas, tais como: participações de debêntures, empregados, administradores e partes beneficiárias, mesmo na forma de instrumentos financeiros, além da contribuição a instituições ou fundos de assistência ou previdência de empregados.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7246, 1, '3.9.6.1.0.00.00.00.00.00', 'PARTICIPAÇÕES DE DEBÊNTURES', 'Compreende as participações de debêntures incidentes sobre o lucro após imposto de renda e contribuição social sobre o lucro liquido.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7247, 1, '3.9.6.1.1.00.00.00.00.00', 'PARTICIPAÇÕES DE DEBÊNTURES - CONSOLIDAÇÃO', 'Registra as participações de debêntures incidentes sobre o lucro após imposto de renda e contribuição social sobre o lucro liquido. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7248, 1, '3.9.6.2.0.00.00.00.00.00', 'PARTICIPAÇÕES DE EMPREGADOS', 'Compreende as participações de empregados incidentes sobre o lucro após imposto de renda e contribuição social sobre o lucro liquido.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7249, 1, '3.9.6.2.1.00.00.00.00.00', 'PARTICIPAÇÕES DE EMPREGADOS - CONSOLIDAÇÃO', 'Registra as participações de empregados incidentes sobre o lucro após imposto de renda e contribuição social sobre o lucro liquido. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7250, 1, '3.9.6.3.0.00.00.00.00.00', 'PARTICIPAÇÕES DE ADMINISTRADORES', 'Compreende as participações de administradores incidentes sobre o lucro após imposto de renda e contribuição social sobre o lucro liquido.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7251, 1, '3.9.6.3.1.00.00.00.00.00', 'PARTICIPAÇÕES DE ADMINISTRADORES - CONSOLIDAÇÃO', 'Registra as participações de administradores incidentes sobre o lucro após imposto de renda e contribuição social sobre o lucro liquido. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7252, 1, '3.9.6.4.0.00.00.00.00.00', 'PARTICIPAÇÕES DE PARTES BENEFICIARIAS', 'Compreende as participações de partes beneficiarias incidentes sobre o lucro após imposto de renda e contribuição social sobre o lucro liquido.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7253, 1, '3.9.6.4.1.00.00.00.00.00', 'PARTICIPAÇÕES DE PARTES BENEFICIARIAS - CONSOLIDAÇÃO', 'Registra as participações de partes beneficiarias incidentes sobre o lucro após imposto de renda e contribuição social sobre o lucro liquido. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7254, 1, '3.9.6.5.0.00.00.00.00.00', 'PARTICIPAÇÕES DE INSTITUIÇÕES OU FUNDOS DE ASSISTÊNCIA OU PREVIDÊNCIA DE EMPREGADOS', 'Compreende as contribuições da empresa, incidentes sobre o lucro após imposto de renda e contribuição social sobre o lucro liquido, para instituições ou fundos de assistência ou previdência de empregados.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7255, 1, '7.3.2.1.0.00.00.00.00.00', 'INSCRIÇÃO DE CRÉDITOS EM DÍVIDA ATIVA ', 'Compreende os valores dos créditos passíveis de serem inscritos em dívida ativa pelo órgão responsável pela inscrição em dívida ativa.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7256, 1, '3.9.6.5.1.00.00.00.00.00', 'PARTICIPAÇÕES DE INSTITUIÇÕES OU FUNDOS DE ASSISTÊNCIA OU PREVIDÊNCIA DE EMPREGADOS - CONSOLIDAÇÃO', 'Registra as contribuições da empresa, incidentes sobre o lucro após imposto de renda e contribuição social sobre o lucro líquido, para instituições ou fundos de assistência ou previdência de empregados. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7257, 1, '3.9.7.0.0.00.00.00.00.00', 'VPD DE CONSTITUIÇÃO DE PROVISÕES', 'Compreende a constituição de provisões, entendidas como os passivos de vencimento ou montante incertos. Não se confundem com os passivos derivados de apropriação por competência, como férias e décimo - terceiro salário.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7258, 1, '3.9.7.1.1.00.00.00.00.00', 'VPD DE PROVISÃO PARA RISCOS TRABALHISTAS - CONSOLIDAÇÃO', 'Registra os passivos de prazo ou de valor incertos, relacionados a pagamento de reclamações trabalhistas. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7259, 1, '3.9.7.2.0.00.00.00.00.00', ' VPD DE PROVISÕES MATEMÁTICAS PREVIDÊNCIÁRIAS A LONGO PRAZO', 'Compreende a constituição de provisões de passivos de prazo ou de valor incertos, relacionados a futuros benefícios previdenciários a serem pagos aos contribuintes.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7260, 1, '3.9.7.2.1.00.00.00.00.00', ' VPD DE PROVISÕES MATEMÁTICAS PREVIDÊNCIÁRIAS A LONGO PRAZO - CONSOLIDAÇÃO', 'Registra a constituição de provisões de passivos de prazo ou de valor incertos, relacionados a futuros benefícios previdenciários a serem pagos aos contribuintes. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7261, 1, '3.9.7.3.0.00.00.00.00.00', 'VPD DE PROVISÕES PARA RISCOS FISCAIS', 'Compreende a constituição de provisões de passivos de prazo ou de valor incertos, relacionados ao pagamento de autuações fiscais.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7325, 1, '5.2.2.1.2.02.00.00.00.00', 'CREDITO ADICIONAL - ESPECIAL', 'Compreende o somatório dos valores dos créditos adicionais especiais destinados a atender programas não contemplados na lei orçamentária anual.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7262, 1, '3.9.7.3.1.00.00.00.00.00', 'VPD DE PROVISÕES PARA RISCOS FISCAIS - CONSOLIDAÇÃO', 'Registra a constituição de provisões de passivos de prazo ou de valor incertos, relacionados ao pagamento de autuações fiscais. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7263, 1, '3.9.7.4.0.00.00.00.00.00', 'VPD DE PROVISÃO PARA RISCOS CÍVEIS', 'Compreende a constituição de provisões de passivos de prazo ou de valor incertos, relacionados a pagamento de indenizações a fornecedores e clientes.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7264, 1, '3.9.7.4.1.00.00.00.00.00', 'VPD DE PROVISÃO PARA RISCOS CÍVEIS - CONSOLIDAÇÃO', 'Registra a constituição de provisões de passivos de prazo ou de valor incertos, relacionados a pagamentos de indenizações a fornecedores e clientes. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7265, 1, '4.1.2.2.1.97.00.00.00.00', '(-) DEDUÇÕES', 'Compreende as deduções diversas.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7266, 1, '3.9.7.5.3.00.00.00.00.00', 'VPD DE PROVISÃO PARA REPARTIÇÃO DE CRÉDITOS - INTER OFSS - UNIÃO', 'Compreende/Registra a constituição de provisões de passivos de prazo ou de valores incertos relacionados aos créditos tributários e não tributários reconhecidos no lançamento por parte do agente arrecadador, a serem repartidos com outros entes da federação. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7267, 1, '8.1.1.1.1.02.06.00.00.00', 'HIPOTECAS EXECUTADAS', 'Registra o valor recebido das garantias por hipoteca no exterior.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (7268, 1, '3.9.7.5.4.00.00.00.00.00', 'VPD DE PROVISÃO PARA REPARTIÇÃO DE CRÉDITOS - INTER OFSS - ESTADO', 'Compreende/Registra a constituição de provisões de passivos de prazo ou de valores incertos relacionados aos créditos tributários e não tributários reconhecidos no lançamento por parte do agente arrecadador, a serem repartidos com outros entes da federação. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7269, 1, '3.9.7.5.5.00.00.00.00.00', 'VPD DE PROVISÃO PARA REPARTIÇÃO DE CRÉDITOS - INTER OFSS - MUNICÍPIO', 'Registra a constituição de provisões de passivos de prazo ou de valores incertos relacionados aos créditos tributários e não tributários reconhecidos no lançamento por parte do agente arrecadador, a serem repartidos com outros entes da federação. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7270, 1, '3.9.7.6.0.00.00.00.00.00', 'VPD DE PROVISÃO PARA RISCOS DECORRENTES DE CONTRATOS DE PPP ', 'Compreende a constituição de provisões de passivos de prazo ou de valores incertos relacionados aos riscos de demanda, construção, disponibilidade ou outros riscos decorrentes de contratos de PPP, de acordo com a Lei n.11.079/2004.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7271, 1, '3.9.7.6.1.00.00.00.00.00', 'VPD DE PROVISÃO PARA RISCOS DECORRENTES DE CONTRATOS DE PPP - CONSOLIDAÇÃO', 'Registra a constituição de provisões de passivos de prazo ou de valores incertos relacionados aos riscos de demanda, construção, disponibilidade ou outros riscos decorrentes de contratos de PPP, de acordo com a Lei n.11.079/2004. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7272, 1, '3.9.7.9.0.00.00.00.00.00', 'VPD DE OUTRAS PROVISÕES ', 'Compreende a constituição de provisões de passivos de prazo ou de valor incertos não classificadas anteriormente neste plano de contas.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7273, 1, '3.9.7.9.1.00.00.00.00.00', 'VPD DE OUTRAS PROVISÕES - CONSOLIDAÇÃO ', 'Registra a constituição de provisões de passivos de prazo ou de valor incertos não classificadas anteriormente neste plano de contas. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7274, 1, '3.9.9.0.0.00.00.00.00.00', 'DIVERSAS VARIAÇÕES PATRIMONIAIS DIMINUTIVAS', 'Compreende outras variações patrimoniais diminutivas não classificadas em itens específicos.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7275, 1, '3.9.9.1.0.00.00.00.00.00', 'COMPENSAÇÃO FINANCEIRA ENTRE RGPS/RPPS', 'Compreende as variações patrimoniais diminutivas provenientes da compensação financeira entre o regime geral de previdência social e os regimes próprios de previdência social dos servidores da União, dos estados, do distrito federal e dos municípios na hipótese de contagem recíproca de tempo de contribuição (não concomitante).', 1, false, 0, 'N');
