insert into contabilidade.planocontadetalhe values (7296, 1, '3.9.9.6.1.00.00.00.00.00', 'INDENIZAÇÕES E RESTITUIÇÕES - CONSOLIDAÇÃO', 'Registra as variações patrimoniais diminutivas provenientes de indenizações e/ou restituições diversas, não especificadas no plano de contas. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7297, 1, '3.9.9.7.0.00.00.00.00.00', 'COMPENSAÇÕES AO RGPS', ' Compreende as compensações diversas ao Fundo do Regime Geral de Previdência Social, tais como recomposição do fundo em virtude de isenções, reduções de alíquota ou base de cálculo e outros benefícios concedidos.', 1, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (7298, 1, '3.9.9.7.1.00.00.00.00.00', 'COMPENSAÇÕES AO RGPS - CONSOLIDAÇÃO', ' Registra as compensações diversas ao Fundo do Regime Geral de Previdência Social, tais como recomposição do fundo em virtude de isenções, reduções de alíquota ou base de cálculo e outros benefícios concedidos. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 1, false, 0, 'N');
