insert into contabilidade.planocontadetalhe values (7403, 1, '1.1.2.9.2.01.04.00.00.00', '(-) PERDAS ESTIMADAS EM DEMAIS CONTRIBUIÇÕES', 'Registra o ajuste para perdas estimadas com o não recebimento de demais contribuições.', 2, true, 2, 'P');
