insert into contabilidade.planocontadetalhe values (7469, 1, '1.1.5.9.1.01.00.00.00.00', '(-) AJUSTE DE PERDAS DE ESTOQUES', 'Registra as perdas conhecidas em estoques e calculadas por estimativa, relativas a estoques deteriorados ou obsoletos e para dar cobertura a diferenças físicas, quando tais perdas não puderem ser baixadas das próprias contas, pelo fato de não estarem identificados os itens específicos e por constituírem estimativas.', 2, true, 2, 'P');
