insert into contabilidade.planocontadetalhe values (7471, 1, '2.2.3.2.1.01.99.00.00.00', 'DEMAIS FORNECEDORES A PAGAR', 'Registra os valores de demais fornecedores a pagar.', 2, true, 2, 'X');
