insert into contabilidade.planocontadetalhe values (7479, 1, '1.2.1.1.4.99.00.00.00.00', '(-) AJUSTE DE PERDAS DE CRÉDITOS A LONGO PRAZO', 'Compreende os ajustes de perdas estimadas s com o não recebimento de valores referentes a créditos a longo prazo, por inadimplência de terceiros e outras.', 2, true, 2, 'P');
