insert into contabilidade.planocontadetalhe values (7482, 1, '1.2.1.2.1.99.02.00.00.00', '(-) AJUSTE DE PERDAS DE CRÉDITOS ADMINISTRATIVOS', 'Registra os valores, realizáveis após  os 12 (doze) meses seguintes a data da publicação das demonstrações contábeis, dos ajustes para perdas estimadas de créditos por danos ao patrimônio, verificados em processos administrativos.', 2, true, 2, 'P');
