insert into contabilidade.planocontadetalhe values (7489, 1, '1.2.1.3.1.99.04.00.00.00', '(-) AJUSTE DE PERDAS DE FUNDOS AVALIADOS A VALOR DE MERCADO', 'Registra os valores de ajustes para perdas de fundos, quando avaliados a valor de mercado.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7490, 1, '1.2.1.4.1.99.00.00.00.00', '(-) AJUSTE DE PERDAS DE ESTOQUES', 'Compreende o registro das perdas conhecidas em estoques e calculadas por estimativa, relativas a estoques deteriorados ou obsoletos e para dar cobertura a diferenças físicas, quando tais perdas não puderem ser baixadas das próprias contas, pelo fato de não estarem identificados os itens específicos e por constituírem estimativas, bem como o registro de perdas estimadas para os estoque que tiverem o valor de mercado inferior ao seu custo. Conta a ser utilizada apenas para os estoques classificados no ativo realizável a longo prazo.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7491, 1, '1.2.2.1.1.01.97.00.00.00', '(-) AMORTIZAÇÃO DE ÁGIO NA AQUISIÇÃO DE PARTICIPAÇÕES AVALIADAS PELO MEP', 'Registra as participações permanentes da unidade em outras entidades em forma de ações ou cotas, avaliadas pelo método de equivalência patrimonial - Amortização de Ágio na Aquisição de Participações.', 2, true, 2, 'P');
