insert into contabilidade.planocontadetalhe values (7500, 1, '1.2.2.1.5.01.98.00.00.00', '(-) DESAGIO NA AQUISIÇÃO DE PARTICIPAÇÕES AVALIADAS PELO MEP', 'Registra as participações permanentes da unidade em outras entidades em forma de ações ou cotas, avaliadas pelo método de equivalência patrimonial - Deságio na aquisição de Participações.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7501, 1, '1.2.2.8.1.01.01.00.00.00', '(-) DEPRECIAÇÃO ACUMULADA DE BENS IMÓVEIS PARA FUTURA UTILIZAÇÃO', 'Registra a diminuição do valor dos elementos do ativo investimento devido a desgaste pelo uso, ação da natureza ou obsolescência, quando couber, dos valores de imóveis da unidade mantidos para futura utilização.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7502, 1, '1.2.2.8.1.01.02.00.00.00', '(-) DEPRECIAÇÃO ACUMULADA DE BENS IMOVEIS NÃO DESTINADOS A USO', 'Registra a diminuição do valor dos elementos do ativo investimento devido a desgaste pelo uso, ação da natureza ou obsolescência, quando couber, dos valores de imóveis da unidade mantidos para geração de renda.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7503, 1, '2.1.2.5.1.02.00.00.00.00', 'ENCARGOS - EMPRÉSTIMOS INTERNOS', 'Compreende os valores exigíveis decorrentes dos encargos de contratos de empréstimos internos.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (7504, 1, '1.2.2.8.1.01.99.00.00.00', '(-) DEPRECIAÇÃO ACUMULADA OUTRAS PROPRIEDADES PARA INVESTIMENTOS', 'Registra a diminuição do valor dos elementos do ativo investimento devido a desgaste pelo uso, ação da natureza ou obsolescência, quando couber, das outras propriedades mantidas para investimento.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7505, 1, '1.2.2.9.1.01.01.00.00.00', '(-) REDUÇÃO AO VALOR RECUPERÁVEL DE PARTICIPAÇÕES AVALIADAS PELO MÉTODO DE EQUIVALÊNCIA PATRIMONIAL', 'Registra o valor da redução ao valor recuperável das participações permanentes da unidade em outras entidades em forma de ações ou cotas, avaliadas pelo método de equivalência patrimonial.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7506, 1, '1.2.2.9.1.01.02.00.00.00', '(-) REDUÇÃO AO VALOR RECUPERÁVEL DE PARTICIPAÇÕES AVALIADAS PELO MÉTODO DE CUSTO', 'Registra o valor da redução ao valor recuperável das participações permanentes da unidade em outras sociedades em forma de ações ou cotas, avaliadas pelo método de custo.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7507, 1, '1.2.2.9.1.02.01.00.00.00', '(-) REDUÇÃO AO VALOR RECUPERÁVEL DE BENS IMÓVEIS PARA FUTURA UTILIZAÇÃO', 'Registra o valor da redução ao valor recuperável de imóveis da unidade mantidos para futura utilização.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7508, 1, '1.2.2.9.1.02.02.00.00.00', '(-) REDUÇÃO AO VALOR RECUPERÁVEL DE BENS IMOVEIS NÃO DESTINADOS A USO', 'Registra o valor da redução ao valor recuperável de imóveis da unidade mantidos para geração de renda.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7509, 1, '1.2.2.9.1.03.00.00.00.00', '(-) REDUÇÃO AO VALOR RECUPERÁVEL DE INVESTIMENTOS DO RPPS', 'Compreende os valores de ajuste ao valor recuperável de investimentos do RPPS, quando esse for inferior ao valor liquido contábil.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7510, 1, '1.2.2.9.1.04.00.00.00.00', '(-) REDUÇÃO AO VALOR RECUPERÁVEL DE INVESTIMENTOS - DEMAIS INVESTIMENTOS PERMANENTES', 'Compreende os valores de ajuste ao valor recuperável de demais investimentos permanentes, quando esse for inferior ao valor liquido contábil.', 2, true, 2, 'P');
