insert into contabilidade.planocontadetalhe values (7512, 1, '1.2.2.9.2.04.00.00.00.00', '(-) REDUÇÃO AO VALOR RECUPERÁVEL DE INVESTIMENTOS - DEMAIS INVESTIMENTOS PERMANENTES', 'Compreende os valores de ajuste ao valor recuperável de demais investimentos permanentes, quando esse for inferior ao valor liquido contábil.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7513, 1, '1.2.2.9.3.01.00.00.00.00', '(-) REDUÇÃO AO VALOR RECUPERÁVEL DE INVESTIMENTOS - PARTICIPAÇÕES PERMANENTES', 'Compreende os valores de ajuste ao valor recuperável de participações permanentes, quando esse for inferior ao valor liquido contábil.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7514, 1, '1.2.2.9.3.04.00.00.00.00', '(-) REDUÇÃO AO VALOR RECUPERÁVEL DE INVESTIMENTOS - DEMAIS INVESTIMENTOS PERMANENTES', 'Compreende os valores de ajuste ao valor recuperável de demais investimentos permanentes, quando esse for inferior ao valor liquido contábil.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7515, 1, '1.2.2.9.4.01.00.00.00.00', '(-) REDUÇÃO AO VALOR RECUPERÁVEL DE INVESTIMENTOS - PARTICIPAÇÕES PERMANENTES', 'Compreende os valores de ajuste ao valor recuperável de participações permanentes, quando esse for inferior ao valor liquido contábil.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7516, 1, '1.2.2.9.4.04.00.00.00.00', '(-) REDUÇÃO AO VALOR RECUPERÁVEL DE INVESTIMENTOS - DEMAIS INVESTIMENTOS PERMANENTES', 'Registra os valores de ajuste ao valor recuperável de demais investimentos permanentes, quando esse for inferior ao valor liquido contábil.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7517, 1, '1.2.2.9.5.01.00.00.00.00', '(-) REDUÇÃO AO VALOR RECUPERÁVEL DE INVESTIMENTOS - PARTICIPAÇÕES PERMANENTES', 'Compreende os valores de ajuste ao valor recuperável de participações permanentes, quando esse for inferior ao valor liquido contábil.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7518, 1, '1.2.2.9.5.04.00.00.00.00', '(-) REDUÇÃO AO VALOR RECUPERÁVEL DE INVESTIMENTOS - DEMAIS INVESTIMENTOS PERMANENTES', 'Compreende os valores de ajuste ao valor recuperável de demais investimentos permanentes, quando esse for inferior ao valor liquido contábil.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7519, 1, '1.2.3.8.1.01.01.00.00.00', '(-) DEPRECIAÇÃO ACUMULADA DE MÁQUINAS, APARELHOS, EQUIPAMENTOS E FERRAMENTAS', 'Registra a depreciação acumulada de máquinas, ferramentas, aparelhos, equipamentos, acessórios etc.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7520, 1, '1.2.3.8.1.01.02.00.00.00', '(-) DEPRECIAÇÃO ACUMULADA DE BENS DE INFORMÁTICA', 'Registra a depreciação acumulada de equipamentos de processamento de dados e sistemas aplicativos, entre outros.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7521, 1, '1.2.3.8.1.01.03.00.00.00', '(-) DEPRECIAÇÃO ACUMULADA DE MÓVEIS E UTENSÍLIOS', 'Registra a depreciação acumulada de mobiliário em geral e utensílios, entre outros.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7522, 1, '1.2.3.8.1.01.04.00.00.00', '(-) DEPRECIAÇÃO ACUMULADA DE MATERIAIS CULTURAIS, EDUCACIONAIS E DE COMUNICAÇÃO', 'Registra a depreciação acumulada de materiais bibliográficos, discotecas, filmotecas, de comunicação, entre outros.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7523, 1, '1.2.3.8.1.01.05.00.00.00', '(-) DEPRECIAÇÃO ACUMULADA DE VEÍCULOS', 'Registra a depreciação acumulada de transportes aéreos, aquáticos e terrestres, entre outros.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7524, 1, '1.2.3.8.1.01.06.00.00.00', '(-) DEPRECIAÇÃO ACUMULADA DE PEÇAS E CONJUNTOS DE REPOSIÇÃO', 'Registra a depreciação acumulada de peças e conjuntos de reposição destinados a substituição em máquinas e equipamentos, aeronaves e embarcações, bens de segurança e socorro, entre outros.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7525, 1, '1.2.3.8.1.01.07.00.00.00', '(-) DEPRECIAÇÃO ACUMULADA DE BENS MÓVEIS EM ANDAMENTO', 'Registra a depreciação acumulada de bens móveis em andamento.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7526, 1, '1.2.3.8.1.01.08.00.00.00', '(-) DEPRECIAÇÃO ACUMULADA DE BENS MÓVEIS EM ALMOXARIFADO', 'Registra a depreciação acumulada de bens permanentes a serem estocados em almoxarifado.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7527, 1, '1.2.3.8.1.01.09.00.00.00', '(-) DEPRECIAÇÃO ACUMULADA DE ARMAMENTOS', 'Registra a depreciação acumulada de armas que constituem objetos de defesa ou preparativos de guerra.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7528, 1, '1.2.3.8.1.01.10.00.00.00', '(-) DEPRECIAÇÃO ACUMULADA DE SEMOVENTES', 'Registra a depreciação acumulada de animais destinados a produção, reprodução, engorda e aos serviços utilitários em geral.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7529, 1, '1.2.3.8.1.01.99.00.00.00', '(-) DEPRECIAÇÃO ACUMULADA DE DEMAIS BENS MÓVEIS', 'Registra a depreciação acumulada de demais bens móveis não classificados em grupos específicos.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7530, 1, '1.2.3.8.1.02.01.00.00.00', '(-) DEPRECIAÇÃO ACUMULADA DE BENS DE USO ESPECIAL', 'Registra a depreciação acumulada de bens como edifícios ou terrenos destinados a serviço ou estabelecimento da administração estadual ou municipal, inclusive os de suas autarquias e fundações públicas.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7531, 1, '2.1.1.3.1.03.01.00.00.00', 'PRECATÓRIOS DE BENEFÍCIOS ASSISTENCIAIS - REGIME ESPECIAL - ANTES DE 05/05/2000 ', 'Registra as obrigações referentes a precatórios de benefícios assistenciais,  sujeitos ao regime especial instituído pela emenda constitucional 62/2009, anteriores a 05/05/2000 (Lei de Responsabilidade Fiscal).', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (7532, 1, '1.2.3.8.1.02.02.00.00.00', '(-) DEPRECIAÇÃO ACUMULADA DE BENS DOMINICAIS', 'Registra a depreciação acumulada de bens que constituem o patrimônio das pessoas jurídicas de direito público, como objeto de direito pessoal, ou real, de cada uma dessas entidades. Compreende ainda, não dispondo a lei em contrário, os bens pertencentes as pessoas jurídicas de direito público a que se tenha dado estrutura de direito privado.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7533, 1, '1.2.3.8.1.02.03.00.00.00', '(-) DEPRECIAÇÃO ACUMULADA DE BENS DE USO COMUM DO POVO', 'Registra a depreciação acumulada de bens de uso comum do povo construídos ou adquiridos por pessoas jurídicas de direito público.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7534, 1, '1.2.3.8.1.02.04.00.00.00', '(-) DEPRECIAÇÃO ACUMULADA DE BENS IMÓVEIS EM ANDAMENTO', 'Registra a depreciação acumulada de valores de bens imóveis em andamento.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7535, 1, '2.1.1.4.5.06.00.00.00.00', 'CONTRIBUIÇÕES PREVIDÊNCIÁRIAS  - DÉBITO PARCELADO', 'Registra a apropriação e movimentação do valor referente a débitos parcelados junto ao INSS ou entidade de previdência, referente ao não recolhimento de obrigações de folha de pagamento e outros afins.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (7536, 1, '1.2.3.8.1.02.05.00.00.00', '(-) DEPRECIAÇÃO ACUMULADA DE INSTALAÇÕES', 'Registra a depreciação acumulada de equipamentos, materiais e custo de implantação de instalações que, não obstante integradas aos edifícios, devem ser segregadas das obras civis, como, por exemplo, as instalações elétricas, hidráulicas, sanitárias, de vapor, de ar comprimido, frigoríficas, contra incêndio, de comunicações, de climatização, para combustíveis, gases, de antipoluição, para cozinha, dentre outros. E também aplicável a construção de trechos ferroviários.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7537, 1, '1.2.3.8.1.02.06.00.00.00', '(-) DEPRECIAÇÃO ACUMULADA DE BENFEITORIAS EM PROPRIEDADE DE TERCEIROS', 'Registra a depreciação acumulada de construções em terrenos arrendados de terceiros e instalações e outras benfeitorias em prédios alugados. São considerados somente os gastos com construção e instalação que se incorporam ao imóvel e revertem ao proprietário do imóvel ao final da locação.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7538, 1, '1.2.3.8.1.02.99.00.00.00', '(-) DEPRECIAÇÃO ACUMULADA DE DEMAIS BENS IMÓVEIS', 'Registra a depreciação acumulada de os demais bens imóveis não classificados anteriormente nesse plano de contas.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7539, 1, '1.2.3.8.1.03.00.00.00.00', '(-) EXAUSTÃO ACUMULADA - BENS MÓVEIS', 'Registra a diminuição do valor dos elementos do ativo imobilizado, bens móveis, devido à perda do valor, decorrente de sua exploração, de direitos cujo objeto sejam recursos minerais ou florestais ou bens aplicados nessa exploração.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7540, 1, '1.2.3.8.1.04.00.00.00.00', '(-) EXAUSTÃO ACUMULADA - BENS IMÓVEIS', 'Registra a diminuição do valor dos elementos do ativo imobilizado, bens imóveis, devido à perda do valor, decorrente de sua exploração, de direitos cujo objeto sejam recursos minerais ou florestais ou bens aplicados nessa exploração.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7565, 1, '1.2.3.9.1.02.99.00.00.00', '(-) REDUÇÃO A VALOR RECUPERÁVEL DE DEMAIS BENS IMÓVEIS', 'Registra os valores de ajuste ao valor recuperável de os demais bens imóveis não classificados anteriormente nesse plano de contas.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7541, 1, '1.2.3.8.1.05.00.00.00.00', '(-) AMORTIZAÇÃO ACUMULADA - BENS MÓVEIS', 'Registra a diminuição do valor dos elementos do ativo imobilizado, bens móveis, devido à perda do valor do capital aplicado na aquisição de direitos de propriedade industrial ou comercial e quaisquer outros com existência ou exercício de duração limitada ou cujo objeto sejam bens de utilização por prazo legal ou contratualmente limitado.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7542, 1, '1.2.3.8.1.06.00.00.00.00', '(-) AMORTIZAÇÃO ACUMULADA - BENS IMÓVEIS', 'Registra a diminuição do valor dos elementos do ativo imobilizado, bens Imóveis, devido à perda do valor do capital aplicado na aquisição de direitos de propriedade industrial ou comercial e quaisquer outros com existência ou exercício de duração limitada ou cujo objeto sejam bens de utilização por prazo legal ou contratualmente limitado.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7543, 1, '1.2.3.9.1.01.01.00.00.00', '(-) REDUÇÃO A VALOR RECUPERÁVEL DE MÁQUINAS, APARELHOS, EQUIPAMENTOS E FERRAMENTAS', 'Registra os valores de ajuste ao valor recuperável de máquinas, ferramentas, aparelhos, equipamentos, acessórios etc.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7544, 1, '1.2.3.9.1.01.02.00.00.00', '(-) REDUÇÃO A VALOR RECUPERÁVEL DE BENS DE INFORMÁTICA', 'Registra os valores de ajuste ao valor recuperável de equipamentos de processamento de dados e sistemas aplicativos, entre outros.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7545, 1, '1.2.3.9.1.01.03.00.00.00', '(-) REDUÇÃO A VALOR RECUPERÁVEL DE MÓVEIS E UTENSÍLIOS', 'Registra os valores de ajuste ao valor recuperável de mobiliário em geral e utensílios, entre outros.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7546, 1, '1.2.3.9.1.01.04.00.00.00', '(-) REDUÇÃO A VALOR RECUPERÁVEL DE MATERIAIS CULTURAIS, EDUCACIONAIS E DE COMUNICAÇÃO', 'Registra os valores de ajuste ao valor recuperável de materiais bibliográficos, discotecas, filmotecas, de comunicação, entre outros.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7547, 1, '1.2.3.9.1.01.05.00.00.00', '(-) REDUÇÃO A VALOR RECUPERÁVEL DE VEÍCULOS', 'Registra os valores de ajuste ao valor recuperável de transportes aéreos, aquáticos e terrestres, entre outros.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7548, 1, '1.2.3.9.1.01.06.00.00.00', '(-) REDUÇÃO A VALOR RECUPERÁVEL DE PEÇAS E CONJUNTOS DE REPOSIÇÃO', 'Registra os valores de ajuste ao valor recuperável de peças e conjuntos de reposição destinados a substituição em máquinas e equipamentos, aeronaves e embarcações, bens de segurança e socorro, entre outros.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7549, 1, '1.2.3.9.1.01.07.00.00.00', '(-) REDUÇÃO A VALOR RECUPERÁVEL DE BENS MÓVEIS EM ANDAMENTO', 'Registra os valores de ajuste ao valor recuperável de bens móveis em andamento.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7550, 1, '1.2.3.9.1.01.08.00.00.00', '(-) REDUÇÃO A VALOR RECUPERÁVEL DE BENS MÓVEIS EM ALMOXARIFADO', 'Registra os valores de ajuste ao valor recuperável de bens permanentes a serem estocados em almoxarifado.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7551, 1, '1.2.3.9.1.01.09.00.00.00', '(-) REDUÇÃO A VALOR RECUPERÁVEL DE ARMAMENTOS', 'Registra os valores de ajuste ao valor recuperável de armas que constituem objetos de defesa ou preparativos de guerra.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7552, 1, '1.2.3.9.1.01.10.00.00.00', '(-) REDUÇÃO A VALOR RECUPERÁVEL DE SEMOVENTES', 'Registra os valores de ajuste ao valor recuperável de animais destinados a produção, reprodução, engorda e aos serviços utilitários em geral.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7553, 1, '1.2.3.9.1.01.99.00.00.00', '(-) REDUÇÃO A VALOR RECUPERÁVEL DE DEMAIS BENS MÓVEIS', 'Registra os valores de ajuste ao valor recuperável de demais bens móveis não classificados em grupos específicos.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7554, 1, '1.2.3.9.1.02.01.00.00.00', '(-) REDUÇÃO A VALOR RECUPERÁVEL DE BENS DE USO ESPECIAL', 'Registra os valores de ajuste ao valor recuperável de bens como edifícios ou terrenos destinados a serviço ou estabelecimento da administração estadual ou municipal, inclusive os de suas autarquias e fundações públicas.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7555, 1, '2.1.1.4.3.07.00.00.00.00', 'CONTRIBUICÕES SOCIAIS  - DÉBITOS PARCELADOS', 'Registra a apropriação e movimentação do valor dos débitos parcelados, referente ao não recolhimento de contribuições sociais', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (7556, 1, '2.1.2.1.5.02.01.00.00.00', 'CONTRATOS DE EMPRÉSTIMOS INTERNOS ', 'Registra os valores em liquidação, decorrentes de contratos de empréstimos internos.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (7557, 1, '1.2.3.9.1.02.02.00.00.00', '(-) REDUÇÃO A VALOR RECUPERÁVEL DE BENS DOMINICAIS', 'Registra os valores de ajuste ao valor recuperável de bens que constituem o patrimônio das pessoas jurídicas de direito público, como objeto de direito pessoal, ou real, de cada uma dessas entidades. Compreende ainda, não dispondo a lei em contrário, os bens pertencentes as pessoas jurídicas de direito público a que se tenha dado estrutura de direito privado.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7558, 1, '1.2.3.9.1.02.03.00.00.00', '(-) REDUÇÃO A VALOR RECUPERÁVEL DE BENS DE USO COMUM DO POVO', 'Registra os valores de ajuste ao valor recuperável de bens de uso comum do povo construídos ou adquiridos por pessoas jurídicas de direito público.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7559, 1, '1.2.3.9.1.02.04.00.00.00', '(-) REDUÇÃO A VALOR RECUPERÁVEL DE BENS IMÓVEIS EM ANDAMENTO', 'Registra os valores de ajuste ao valor recuperável de valores de bens imóveis em andamento.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7560, 1, '2.1.1.1.1.05.01.00.00.00', 'PRECATÓRIOS DE PESSOAL - REGIME ORDINÁRIO - ANTES DE 05/05/2000 ', 'Registra as obrigações referentes a precatórios de salários ou remunerações, bem como a benefícios aos quais o empregado ou servidor tenha direito,  não sujeitos ao regime especial instituído pela emenda constitucional 62/2009, anteriores a 05/05/2000 (Lei de Responsabilidade Fiscal).', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (7561, 1, '2.1.1.4.5.98.00.00.00.00', 'OUTROS ENCARGOS SOCIAIS', 'Registra os valores relativos aos encargos sociais de ocorrência permanente ou eventual que tenham gerado obrigações para a entidade, cuja classificação não esteja prevista em contas especificas.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (7562, 1, '2.1.2.1.1.01.01.00.00.00', 'DÍVIDA MOBILIÁRIA', 'Registra os valores exigíveis, decorrentes da emissão de títulos da dívida mobiliária.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (7563, 1, '1.2.3.9.1.02.05.00.00.00', '(-) REDUÇÃO A VALOR RECUPERÁVEL DE INSTALAÇÕES', 'Registra os valores de ajuste ao valor recuperável de equipamentos, materiais e custo de implantação de instalações que, não obstante integradas aos edifícios, devem ser segregadas das obras civis, como, por exemplo, as instalações elétricas, hidráulicas, sanitárias, de vapor, de ar comprimido, frigoríficas, contra incêndio, de comunicações, de climatização, para combustíveis, gases, de antipoluição, para cozinha, dentre outros. E também aplicável a construção de trechos ferroviários.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7564, 1, '1.2.3.9.1.02.06.00.00.00', '(-) REDUÇÃO A VALOR RECUPERÁVEL DE BENFEITORIAS EM PROPRIEDADE DE TERCEIROS', 'Registra os valores de ajuste ao valor recuperável de construções em terrenos arrendados de terceiros e instalações e outras benfeitorias em prédios alugados. São considerados somente os gastos com construção e instalação que se incorporam ao imóvel e revertem ao proprietário do imóvel ao final da locação.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7567, 1, '1.2.4.8.1.02.00.00.00.00', '(-) AMORTIZAÇÃO ACUMULADA - MARCAS, DIREITOS E PATENTES', 'Registra a diminuição do valor do capital aplicado em marcas, direitos e patentes, pertencentes ao ativo intangível.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7568, 1, '1.2.4.8.1.03.00.00.00.00', '(-) AMORTIZAÇÃO ACUMULADA - DIREITO DE USO DE IMÓVEIS', 'Registra a diminuição do valor do capital aplicado em direito de uso de imóveis, pertencentes ao ativo intangível.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7569, 1, '1.2.4.9.1.01.00.00.00.00', '(-) REDUÇÃO AO VALOR RECUPERÁVEL DE INTANGÍVEL - SOFTWARES', 'Registra os valores de ajuste ao valor recuperável do software pertencente ao ativo intangível, quando esse for inferior ao valor liquido contábil.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7570, 1, '1.2.4.9.1.02.00.00.00.00', '(-) REDUÇÃO AO VALOR RECUPERÁVEL DE INTANGÍVEL - MARCAS, DIREITOS E PATENTES', 'Registra os valores de ajuste ao valor recuperável das marcas, direitos e patentes, quando esse for inferior ao valor liquido contábil.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7571, 1, '1.2.4.9.1.03.00.00.00.00', '(-) REDUÇÃO AO VALOR RECUPERÁVEL DE INTANGÍVEL-DIREITO DE USO', 'Registra os valores de ajuste ao valor recuperável de direito de uso, quando esse for inferior ao valor liquido contábil.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7572, 1, '1.2.5.9.1.01.00.00.00.00', '(-) AMORTIZAÇÃO ACUMULADA - GASTOS DE IMPLANTAÇÃO E PRÉ-OPERACIONAIS', 'Registra a perda do valor do capital aplicado em despesas pré-operacionais.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7573, 1, '1.2.5.9.1.02.00.00.00.00', '(-) AMORTIZAÇÃO ACUMULADA - GASTOS DE REORGANIZAÇÃO', 'Registra a perda do valor do capital aplicado em gastos de reestruturação.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7574, 1, '2.1.1.1.1.01.01.00.00.00', 'SALÁRIOS, REMUNERAÇÕES E BENEFÍCIOS', 'Registra as obrigações referentes a salários ou remunerações, bem como benefícios aos quais o empregado ou servidor tenha direito.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (7575, 1, '2.1.1.1.1.01.02.00.00.00', 'DÉCIMO TERCEIRO SALÁRIO', 'Registra as obrigações referentes ao décimo terceiro salário, geralmente apropriadas na base de 1/12 do valor bruto da folha de pagamento da unidade.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (7576, 1, '2.1.1.1.1.01.03.00.00.00', 'FÉRIAS', 'Registra as obrigações referentes a férias, geralmente apropriadas como percentuais da folha de pagamento da unidade.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (7577, 1, '2.1.1.1.1.01.04.00.00.00', 'LICENÇA- PRÊMIO', 'Registra os valores das obrigações constituídas com base em percentuais de salários, destinados ao pagamento de licença-prêmio.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (7578, 1, '2.1.1.1.1.01.05.00.00.00', 'PARTICIPAÇÕES A EMPREGADOS', 'Registra os valores das obrigações constituídas para pagamento de participações a empregados.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (7579, 1, '2.1.1.1.1.04.01.00.00.00', 'PRECATÓRIOS DE PESSOAL - REGIME ESPECIAL - ANTES DE 05/05/2000 ', 'Registra as obrigações referentes a precatórios de proventos de aposentadoria, reformas ou pensões,  sujeitos ao regime especial instituído pela emenda constitucional 62/2009, anteriores a 05/05/2000 (Lei de Responsabilidade Fiscal).', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (7580, 1, '2.1.1.1.1.04.02.00.00.00', 'PRECATÓRIOS DE PESSOAL - REGIME ESPECIAL - A PARTIR DE 05/05/2000 - VENCIDOS E NÃO PAGOS', 'Registra as obrigações referentes a precatórios de salários ou remunerações, bem como a benefícios aos quais o empregado ou servidor tenha direito,  sujeitos ao regime especial instituído pela emenda constitucional 62/2009, a partir de 05/05/2000 (Lei de Responsabilidade Fiscal), não pagos durante a execução do orçamento em que deveriam ter sido incluídos, caso fosse observada à regra geral, prevista no §5º do artigo 100 da CF/88.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (7581, 1, '2.1.1.1.1.04.03.00.00.00', 'PRECATÓRIOS DE PESSOAL - REGIME ESPECIAL - A PARTIR DE 05/05/2000 - NÃO VENCIDOS', 'Registra as obrigações referentes a precatórios de salários ou remunerações, bem como a benefícios aos quais o empregado ou servidor tenha direito,  sujeitos ao regime especial instituído pela emenda constitucional 62/2009, a partir de 05/05/2000 (Lei de Responsabilidade Fiscal), dentro do prazo de pagamento caso fosse observada a regra geral, estabelicida no § 5º do artigo 100 da CF/88.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (7582, 1, '2.1.1.1.1.05.02.00.00.00', 'PRECATÓRIOS DE PESSOAL - REGIME ORDINÁRIO - A PARTIR DE 05/05/2000 - VENCIDOS E NÃO PAGOS', 'Registra as obrigações referentes a precatórios de salários ou remunerações, bem como a benefícios aos quais o empregado ou servidor tenha direito,  não sujeitos ao regime especial instituído pela emenda constitucional 62/2009, a partir de 05/05/2000 (Lei de Responsabilidade Fiscal), não pagos durante a execução do orçamento em que deveriam ter sido incluídos em observância ao disposto no § 5º do artigo 100 da CF/88.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (7583, 1, '2.1.1.1.1.05.03.00.00.00', 'PRECATÓRIOS DE PESSOAL - REGIME ORDINÁRIO - A PARTIR DE 05/05/2000 - NÃO VENCIDOS', 'Registra as obrigações referentes a precatórios de salários ou remunerações, bem como a benefícios aos quais o empregado ou servidor tenha direito,  não sujeitos ao regime especial instituído pela emenda constitucional 62/2009, a partir de 05/05/2000 (Lei de Responsabilidade Fiscal), dentro do prazo de pagamento previsto no § 5º do artigo 100 da CF/88.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (7584, 1, '2.1.1.1.1.06.00.00.00.00', 'PESSOAL A PAGAR - SENTENÇAS JUDICIAIS - EXCETO PRECATÓRIOS', 'Registra as obrigações decorrentes de sentenças judiciais referentes a salários ou remunerações, bem como a benefícios aos quais o empregado ou servidor tenha direito,  exceto precatórios.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (7585, 1, '2.1.1.2.1.01.00.00.00.00', 'BENEFICIOS PREVIDENCIARIOS A PAGAR', 'Registra as obrigações referentes a proventos de aposentadoria, reformas ou pensões.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (7586, 1, '2.1.1.2.1.04.01.00.00.00', 'PRECATÓRIOS DE BENEFÍCIOS PREVIDENCIÁRIOS - REGIME ESPECIAL - ANTES DE 05/05/2000 ', 'Registra as obrigações referentes a precatórios de proventos de aposentadoria, reformas ou pensões,  sujeitos ao regime especial instituído pela emenda constitucional 62/2009, anteriores a 05/05/2000 (Lei de Responsabilidade Fiscal).', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (7587, 1, '2.1.1.2.1.04.02.00.00.00', 'PRECATÓRIOS DE BENEFÍCIOS PREVIDENCIÁRIOS - REGIME ESPECIAL - A PARTIR DE 05/05/2000 - VENCIDOS E NÃO PAGOS', 'Registra as obrigações referentes a precatórios de proventos de aposentadoria, reformas ou pensões,  sujeitos ao regime especial instituído pela emenda constitucional 62/2009, a partir de 05/05/2000 (Lei de Responsabilidade Fiscal), não pagos durante a execução do orçamento em que deveriam ter sido incluídos, caso fosse observada à regra geral, prevista no §5º do artigo 100 da CF/88.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (7588, 1, '2.1.1.2.1.04.03.00.00.00', 'PRECATÓRIOS DE BENEFÍCIOS PREVIDENCIÁRIOS - REGIME ESPECIAL - A PARTIR DE 05/05/2000 - NÃO VENCIDOS', 'Registra as obrigações referentes a precatórios de proventos de aposentadoria, reformas ou pensões,  sujeitos ao regime especial instituído pela emenda constitucional 62/2009, a partir de 05/05/2000 (Lei de Responsabilidade Fiscal), dentro do prazo de pagamento caso fosse observada a regra geral, estabelicida no § 5º do artigo 100 da CF/88.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (7589, 1, '2.1.1.2.1.05.01.00.00.00', 'PRECATÓRIOS DE BENEFÍCIOS PREVIDENCIÁRIOS - REGIME ORDINÁRIO - ANTES DE 05/05/2000 ', 'Registra as obrigações referentes a precatórios de proventos de aposentadoria, reformas ou pensões,  não sujeitos ao regime especial instituído pela emenda constitucional 62/2009, anteriores a 05/05/2000 (Lei de Responsabilidade Fiscal).', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (7590, 1, '2.1.1.2.1.05.02.00.00.00', 'PRECATÓRIOS DE BENEFÍCIOS PREVIDENCIÁRIOS - REGIME ORDINÁRIO - A PARTIR DE 05/05/2000 - VENCIDOS E NÃO PAGOS', 'Registra as obrigações referentes a precatórios de proventos de aposentadoria, reformas ou pensões,  não sujeitos ao regime especial instituído pela emenda constitucional 62/2009, a partir de 05/05/2000 (Lei de Responsabilidade Fiscal), não pagos durante a execução do orçamento em que deveriam ter sido incluídos em observância ao disposto no § 5º do artigo 100 da CF/88.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (7591, 1, '2.1.1.2.1.05.03.00.00.00', 'PRECATÓRIOS DE BENEFÍCIOS PREVIDENCIÁRIOS - REGIME ORDINÁRIO - A PARTIR DE 05/05/2000 - NÃO VENCIDOS', 'Registra as obrigações referentes a precatórios de proventos de aposentadoria, reformas ou pensões,  não sujeitos ao regime especial instituído pela emenda constitucional 62/2009, a partir de 05/05/2000 (Lei de Responsabilidade Fiscal), dentro do prazo de pagamento previsto no § 5º do artigo 100 da CF/88.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (7592, 1, '2.1.1.2.1.06.00.00.00.00', 'BENEFÍCIOS PREVIDENCIÁRIOS A PAGAR - DECISÕES JUDICIAIS - EXCETO PRECATÓRIOS', 'Registra as obrigações decorrentes de sentenças judiciais referentes a proventos de aposentadoria, reformas ou pensões,  exceto precatórios', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (7593, 1, '2.1.1.2.2.05.01.00.00.00', 'OBRIGAÇÕES DO RPPS DA UNIÃO JUNTO AO RGPS', 'Registra os valores relativos às obrigações do RPPS da União a pagar ao RGPS decorrentes de compensação financeira entre regimes, por contagem recíproca de tempo de contribuição.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7594, 1, '2.1.1.2.2.05.02.00.00.00', 'OBRIGAÇÕES DO RGPS JUNTO AO RPPS DA UNIÃO  ', 'Registra os valores relativos às obrigações do RGPS a pagar ao RPPS da União decorrentes de compensação financeira entre regimes, por contagem recíproca de tempo de contribuição.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7595, 1, '2.1.1.2.2.06.00.00.00.00', 'APORTE PARA COBERTURA DE DÉFICIT FINANCEIRO A PAGAR ', 'Registra os valores devidos ao RPPS pelo ente a título de aporte para cobertura de déficit financeiro.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7596, 1, '2.1.1.2.2.07.00.00.00.00', 'APORTE PARA COBERTURA DE DÉFICIT ATUARIAL A PAGAR  ', 'Registra os valores devidos ao RPPS pelo ente a título de aporte para cobertura de déficit atuarial.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7597, 1, '2.1.1.2.3.05.01.00.00.00', 'OBRIGAÇÕES DO RPPS JUNTO AO RGPS', 'Registra os valores relativos às obrigações do RPPS a pagar ao RGPS decorrentes de compensação financeira entre regimes, por contagem recíproca de tempo de contribuição.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7598, 1, '2.1.1.2.3.05.02.00.00.00', 'OBRIGAÇÕES DO RPPS JUNTO AO RPPS DA UNIÃO', 'Registra os valores relativos às obrigações do RPPS a pagar ao RPPS da União decorrentes de compensação financeira entre regimes, por contagem recíproca de tempo de contribuição.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7599, 1, '2.1.1.2.4.05.01.00.00.00', 'OBRIGAÇÕES DO RPPS JUNTO AO RPPS DE ESTADO', 'Registra os valores relativos às obrigações do RPPS a pagar ao RPPS de um estado decorrentes de compensação financeira entre regimes, por contagem recíproca de tempo de contribuição.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7600, 1, '2.1.1.2.4.05.02.00.00.00', 'OBRIGAÇÕES DO RGPS JUNTO AO RPPS DE ESTADO', 'Registra os valores relativos às obrigações do RGPS a pagar ao RPPS de um estado decorrentes de compensação financeira entre regimes, por contagem recíproca de tempo de contribuição.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7601, 1, '2.1.1.2.5.05.01.00.00.00', 'CRÉDITOS DO RPPS JUNTO AO RPPS DE MUNICÍPIO', 'Registra os valores relativos às obrigações do RPPS a pagar ao RPPS de um município decorrentes de compensação financeira entre regimes, por contagem recíproca de tempo de contribuição.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7602, 1, '2.1.1.2.5.05.02.00.00.00', 'CRÉDITOS DO RGPS JUNTO AO RPPS DE MUNICÍPIO', 'Registra os valores relativos às obrigações do RGPS a pagar ao RPPS de um município decorrentes de compensação financeira entre regimes, por contagem recíproca de tempo de contribuição.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (7603, 1, '2.1.1.3.1.03.02.00.00.00', 'PRECATÓRIOS DE BENEFÍCIOS ASSISTENCIAIS - REGIME ESPECIAL - A PARTIR DE 05/05/2000 - VENCIDOS E NÃO PAGOS', 'Registra as obrigações referentes a precatórios de benefícios assistenciais,  sujeitos ao regime especial instituído pela emenda constitucional 62/2009, a partir de 05/05/2000 (Lei de Responsabilidade Fiscal), não pagos durante a execução do orçamento em que deveriam ter sido incluídos, caso fosse observada à regra geral, prevista no §5º do artigo 100 da CF/88.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (7604, 1, '2.1.1.3.1.03.03.00.00.00', 'PRECATÓRIOS DE BENEFÍCIOS ASSISTENCIAIS - REGIME ESPECIAL - A PARTIR DE 05/05/2000 - NÃO VENCIDOS', 'Registra as obrigações referentes a precatórios de benefícios assistenciais,  sujeitos ao regime especial instituído pela emenda constitucional 62/2009, a partir de 05/05/2000 (Lei de Responsabilidade Fiscal), dentro do prazo de pagamento caso fosse observada a regra geral, estabelicida no § 5º do artigo 100 da CF/88.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (7605, 1, '2.1.1.3.1.04.01.00.00.00', 'PRECATÓRIOS DE BENEFÍCIOS ASSISTENCIAIS - REGIME ORDINÁRIO - ANTES DE 05/05/2000 ', 'Registra as obrigações referentes a precatórios de benefícios assistenciais,  não sujeitos ao regime especial instituído pela emenda constitucional 62/2009, anteriores a 05/05/2000 (Lei de Responsabilidade Fiscal).', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (7606, 1, '8.1.1.1.1.02.08.00.00.00', 'SEGUROS-GARANTIA EXECUTADAS', 'Registra o valor recebido dos seguros-garantia, no exterior.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (7607, 1, '2.1.1.3.1.04.02.00.00.00', 'PRECATÓRIOS DE BENEFÍCIOS ASSISTENCIAIS - REGIME ORDINÁRIO - A PARTIR DE 05/05/2000 - VENCIDOS E NÃO PAGOS', 'Registra as obrigações referentes a precatórios de benefícios assistenciais,  não sujeitos ao regime especial instituído pela emenda constitucional 62/2009, a partir de 05/05/2000 (Lei de Responsabilidade Fiscal), não pagos durante a execução do orçamento em que deveriam ter sido incluídos em observância ao disposto no § 5º do artigo 100 da CF/88.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (7608, 1, '2.1.1.3.1.04.03.00.00.00', 'PRECATÓRIOS DE BENEFÍCIOS ASSISTENCIAIS - REGIME ORDINÁRIO - A PARTIR DE 05/05/2000 - NÃO VENCIDOS', 'Registra as obrigações referentes a precatórios de benefícios assistenciais,  não sujeitos ao regime especial instituído pela emenda constitucional 62/2009, a partir de 05/05/2000 (Lei de Responsabilidade Fiscal), dentro do prazo de pagamento previsto no § 5º do artigo 100 da CF/88.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (7609, 1, '2.1.1.3.1.05.00.00.00.00', 'BENEFÍCIOS ASSISTENCIAIS A PAGAR - DECISÕES JUDICIAIS - EXCETO PRECATÓRIOS', 'Registra as obrigações decorrentes de decisões judiciais referentes a benefícios assistenciais, exceto precatórios.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (7610, 1, '2.1.1.4.1.01.01.00.00.00', 'CONTRIBUIÇÕES AO RGPS SOBRE SALÁRIOS E REMUNERAÇÕES', 'Registra os valores relativos as contribuições a previdência social, incidentes sobre salários e remunerações pagos.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (7611, 1, '2.1.1.4.1.01.02.00.00.00', 'CONTRIBUIÇÕES AO RGPS  - DEBITO PARCELADO', 'Registra os valores de debito parcelado que se referem ao não recolhimento de obrigações da folha de pagamento junto à previdência.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (7612, 1, '2.1.1.4.1.01.03.00.00.00', 'CONTRIBUIÇÕES AO RGPS  -  SERVIÇOS DE TERCEIROS OU CONTRIBUINTES AVULSOS', 'Registra os valores relativos as contribuições incidentes sobre serviços prestados por terceiros ou contribuintes avulsos.', 2, true, 2, 'F');
