insert into contabilidade.planocontadetalhe values (7700, 1, '2.1.3.1.1.01.01.00.00.00', 'FORNECEDORES NÃO FINANCIADOS A PAGAR', 'Registra os valores a pagar não financiados, ou seja, em uma única parcela, aos fornecedores nacionais de bens, materiais e serviços envolvidos com as atividades operacionais da entidade.', 2, true, 2, 'X');
