insert into contabilidade.planocontadetalhe values (7704, 1, '2.1.3.1.1.03.01.00.00.00', 'CONTAS NÃO FINANCIADAS A PAGAR', 'Registra os valores não financiados, ou seja, em uma única parcela, de contas a pagar', 2, true, 2, 'X');
