insert into contabilidade.planocontadetalhe values (7979, 1, '2.2.3.1.1.01.01.00.00.00', 'FORNECEDORES NÃO FINANCIADOS A PAGAR', 'Registra os valores a pagar não financiados, ou seja, em uma única parcela, aos fornecedores nacionais de bens, materiais e serviços envolvidos com as atividades operacionais da entidade.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (7980, 1, '2.2.3.1.1.01.02.00.00.00', 'FORNECEDORES FINANCIADOS A PAGAR', 'Registra os valores a pagar financiados diretamente com fornecedores nacionais de bens, materiais e serviços envolvidos com as atividades operacionais da entidade.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (7981, 1, '2.2.3.1.1.01.03.00.00.00', 'PARCELAMENTO DE FORNECEDORES A PAGAR', 'Registra o parcelamento de dívidas com fornecedores a pagar.', 2, true, 2, 'X');
