insert into contabilidade.planocontadetalhe values (7983, 1, '2.2.3.1.1.04.01.00.00.00', 'PRECATÓRIOS DE FORNECEDORES NACIONAIS - REGIME ESPECIAL - ANTES DE 05/05/2000 ', 'Registra as obrigações referentes a precatórios de fornecedores nacionais,  sujeitos ao regime especial instituído pela emenda constitucional 62/2009, anteriores a 05/05/2000 (Lei de Responsabilidade Fiscal).', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (7984, 1, '2.2.3.2.1.01.02.00.00.00', 'FORNECEDORES FINANCIADOS A PAGAR', 'Registra os valores a pagar financiados diretamente com fornecedores nacionais de bens, materiais e serviços envolvidos com as atividades operacionais da entidade.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (7985, 1, '2.2.3.1.1.04.02.00.00.00', 'PRECATÓRIOS DE FORNECEDORES NACIONAIS - REGIME ESPECIAL - A PARTIR DE 05/05/2000 - VENCIDOS E NÃO PAGOS', 'Registra as obrigações referentes a precatórios de fornecedores nacionais,  sujeitos ao regime especial instituído pela emenda constitucional 62/2009, a partir de 05/05/2000 (Lei de Responsabilidade Fiscal), não pagos durante a execução do orçamento em que deveriam ter sido incluídos, caso fosse observada à regra geral, prevista no §5º do artigo 100 da CF/88.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (7986, 1, '2.2.3.1.1.04.03.00.00.00', 'PRECATÓRIOS DE FORNECEDORES NACIONAIS - REGIME ESPECIAL - A PARTIR DE 05/05/2000 - NÃO VENCIDOS', 'Registra as obrigações referentes a precatórios de fornecedores nacionais,  sujeitos ao regime especial instituído pela emenda constitucional 62/2009, a partir de 05/05/2000 (Lei de Responsabilidade Fiscal), dentro do prazo de pagamento caso fosse observada a regra geral, estabelicida no § 5º do artigo 100 da CF/88.', 2, true, 2, 'X');
insert into contabilidade.planocontadetalhe values (7987, 1, '2.2.4.2.4.99.00.00.00.00', 'OUTROS TRIBUTOS E CONTRIBUIÇÕES ESTADUAIS A RECOLHER', 'Registra os compromissos exigíveis a longo prazo, decorrentes da incidência de tributos para os quais não haja contas específicas.', 2, true, 2, 'X');
