insert into contabilidade.planocontadetalhe values (7993, 1, '2.2.3.1.1.06.03.00.00.00', 'PRECATÓRIOS DE CONTAS A PAGAR - REGIME ESPECIAL - A PARTIR DE 05/05/2000 - NÃO VENCIDOS', 'Registra as obrigações referentes a precatórios de contas a pagar de credores nacionais,  sujeitos ao regime especial instituído pela emenda constitucional 62/2009, a partir de 05/05/2000 (Lei de Responsabilidade Fiscal), dentro do prazo de pagamento caso fosse observada a regra geral, estabelicida no § 5º do artigo 100 da CF/88.', 2, true, 2, 'X');
