insert into contabilidade.planocontadetalhe values (7997, 1, '2.2.3.1.1.08.00.00.00.00', 'FORNECEDORES NACIONAIS A PAGAR - DECISÕES JUDICIAIS - EXCETO PRECATÓRIOS', 'Compreende as obrigações decorrentes de decisões judiciais referentes a fornecedores nacionais, exceto precatórios.', 2, true, 2, 'X');
