insert into contabilidade.planocontadetalhe values (8175, 1, '4.3.3.1.1.08.00.00.00.00', 'PRESTAÇÃO DE SERVICOS RELACIONADOS A T.I', 'Registra as variações patrimoniais aumentativas provenientes da prestação de serviços relacionados a tecnologia da informação', 2, true, 2, 'N');
