insert into contabilidade.planocontadetalhe values (8178, 1, '4.3.3.1.1.11.00.00.00.00', 'SERVICO DE INFORMAÇÕES CIENTIFICAS E TECNOLOGICAS', 'Registra as variações patrimoniais aumentativas provenientes de serviços de informações cientificas e tecnológicas.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8179, 1, '4.9.9.6.1.99.00.00.00.00', 'OUTRAS INDENIZAÇÕES', 'Registra a variação patrimonial aumentativa proveniente de outras indenizações.', 2, true, 2, 'N');
