insert into contabilidade.planocontadetalhe values (8181, 1, '4.3.3.1.1.36.00.00.00.00', 'SERVICOS DE INSPEÇÃO E FISCALIZAÇÃO', 'Registra as variações patrimoniais aumentativas provenientes de serviços de inspeção e fiscalização prestados. VPA proporcionada pela constatação das condições higiênico-sanitárias e técnicas de produtos ou estabelecimentos, ou resultantes de ação externa e direta dos órgãos do poder público destinada a verificação do cumprimento da legislação.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8182, 1, '4.3.3.1.1.35.00.00.00.00', 'SERVICOS DE METROLOGIA E CERTIFICAÇÃO', 'Registra as variações patrimoniais aumentativas provenientes de serviços de metrologia e certificação prestados. VPA de serviços metrológicos em geral, tais como aferição de medidas e instrumentos de medir, serviços de arqueação de tanques para armazenagem, etc.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8183, 1, '4.3.3.1.1.13.00.00.00.00', 'SERVICOS DE TECNOLOGIA', 'Registra as variações patrimoniais aumentativas provenientes de serviços tecnológicos prestados. VPA proporcionada por:  a) analises químicas, ensaios físicos e mecânicos, controle e experimentação qualitativa de matérias-primas, insumos e produtos fabricados; padronização e especificação de produtos; ajustes dos processos e técnicas de produção industrial (sistema de tecnologia) b) especificação e controle de qualidade de medicamentos, insumos farmacêuticos, drogas, cosméticos, produtos químicos, alimentos, e outros, por meio de provas especificas de identificação, de pureza e detestes de contaminação microbiológica.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8184, 1, '4.3.3.1.1.14.00.00.00.00', 'SERVICOS DE COMUNICAÇÃO', 'Compreende as variações patrimoniais aumentativas provenientes de atividades de comunicação, conforme descrição abaixo: a) serviço postal, de entrega e transporte de volumes e correspondências; b) serviço de comunicação telefônica local, interurbana e internacional e de transmissão de dados; c) serviço de radiodifusão e de agenciamento de publicidade.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8185, 1, '4.3.3.1.1.15.00.00.00.00', 'PRESTAÇÃO DE SERVICOS RELACIONADOS A ARMAZENAGEM', 'Registra as variações patrimoniais aumentativas provenientes da prestação de serviços de armazenagem.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8186, 1, '4.3.3.1.1.16.00.00.00.00', 'PRESTAÇÃO DE SERVICOS COMPLEMENTARES', 'Registra as variações patrimoniais aumentativas provenientes da prestação de serviços complementares quando da estocagem em armazenagem.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8187, 1, '4.3.3.1.1.17.00.00.00.00', 'PRESTAÇÃO DE SERVICOS RELACIONADOS AO BENEFICIAMENTO DE GRAOS', 'Registra as variações patrimoniais aumentativas provenientes da prestação de serviços de beneficiamento de grãos.', 2, true, 2, 'N');
