insert into contabilidade.planocontadetalhe values (8194, 1, '4.3.3.1.1.24.00.00.00.00', 'OUTORGA SERV. EXPL. PROD PETR. GAS NATURAL', 'Registra as variações patrimoniais aumentativas provenientes de atividades de exploração, desenvolvimento e produção de petróleo e gás natural, exercidas mediante contratos de concessão.', 2, true, 2, 'N');
