insert into contabilidade.planocontadetalhe values (8196, 1, '4.3.3.1.1.26.00.00.00.00', 'OUTORGA DIREITOS DE EXPL. E PESQ. MINER', 'Registra as variações patrimoniais aumentativas provenientes da compensação financeira pela exploração de recursos minerais devido por todas as empresas que realizam o aproveitamento de uma jazida mineral garantida a essas a propriedade do produto da lavra.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8236, 1, '4.4.2.4.1.03.00.00.00.00', 'MULTAS E JUROS SOBRE ITCMD', 'Registra os valores relativos a créditos a receber, decorrentes da cobrança do Imposto sobre Transmissão "Causa Mortis" e Doação de Bens e Direitos.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (8197, 1, '4.3.3.1.1.27.00.00.00.00', ' CONCESSAO FLORESTAL', 'Registra as variações patrimoniais aumentativas provenientes de atividades de exploração e gestão de direitos de uso de florestas públicas, recursos florestais, produtos e serviços delas decorrentes, para produção sustentável, exercidas mediante contratos de concessão, a particulares que estejam em condições de atender as exigências do respectivo edital de licitação e que demonstrem capacidade para seu desempenho, por sua conta e risco e prazo determinado.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8198, 1, '4.3.3.1.1.28.00.00.00.00', 'CONCESSAO E PERMISSAO. - DIR. USO DE BENS PUB', 'Registra as variações patrimoniais aumentativas provenientes da utilização e exploração de bens públicos por terceiros', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8199, 1, '4.3.3.1.1.29.00.00.00.00', 'COMPENSAÇÕES FINANCEIRAS', 'Registra as variações patrimoniais aumentativas provenientes dos recursos decorrentes do artigo 20, parágrafo 1º da constituição federal, o qual dispõe: "e assegurada, nos termos da lei, aos estados, ao distrito federal e aos municípios, bem como aos órgãos da administração direta da União, participação no resultado da exploração de petróleo ou gás natural, de recursos hídricos para fins de geração de energia elétrica e de outros recursos minerais no respectivo território, plataforma continental, mar territorial ou zona economia exclusiva, ou compensação financeira por essa exploração".', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8200, 1, '4.3.3.1.1.30.00.00.00.00', 'SERVICOS DE TRANSPORTE', 'Registra as variações patrimoniais aumentativas provenientes de serviços de transporte rodoviário, ferroviário, hidroviário, aéreo, especiais e tarifa de pedágio.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8201, 1, '4.3.3.1.1.31.00.00.00.00', 'SERVICOS PORTUARIOS', 'Registra as variações patrimoniais aumentativas provenientes de serviços portuários. Abrangem os recursos oriundos da exploração dos portos, terminais marítimos, atracadouros e ancoradouros, referentes a estiva, desestiva, dragagem, atracação, sinalização, comunicação náutica, docagem, etc....', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8202, 1, '4.3.3.1.1.32.00.00.00.00', 'SERVICOS DE SOCORRO MARITIMO', 'Registra as variações patrimoniais aumentativas provenientes de serviço de socorro marítimo prestado. VPA de serviços de salvamento, por navio de socorro ou equipe de salvamento da marinha, de embarcação e cargas perigo (desencalhe, mergulho, outros socorros), bem como serviços de reboque marítimo, dentre outros.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8203, 1, '4.3.3.1.1.33.00.00.00.00', 'SERVICOS DE SAUDE', 'Registra as variações patrimoniais aumentativas provenientes da prestação de serviços de saúde: hospitalares gerais ou especializados, maternidade, centro de reabilitação, assistência médico-odontológica (inclusive ambulatorial), saúde pública, etc.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8204, 1, '4.4.2.4.1.99.00.00.00.00', 'JUROS E ENCARGOS DE MORA SOBRE OUTROS CRÉDITOS TRIBUTÁRIOS', 'Registra os juros e encargos de mora sobre outros créditos tributários.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8205, 1, '4.3.3.1.1.37.00.00.00.00', 'SERVICOS ADMINISTRATIVOS', 'Registra as variações patrimoniais aumentativas provenientes de serviços administrativos prestados, das atividades de apoio administrativo executadas em organizações de qualquer natureza, tais como: a) taxas de expedição de certificados; b) taxas de registro, renovação, vistoria, licença, cadastramento, etc. C) datilografia, microfilmagem, copias xerográficas, heliográficas, fotostáticas, etc. d) taxas de inscrição em concursos. e) taxa de administração de serviços. F) venda de editais.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8206, 1, '4.3.3.1.1.38.00.00.00.00', 'SERVICOS DE METEOROLOGIA', 'Registra as variações patrimoniais aumentativas provenientes de serviços de meteorologia prestados. VPA proporcionada pelo fornecimento de dados meteorológicos e de pareceres técnicos, bem como conserto, comparação e aferição de equipamentos de meteorologia.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8207, 1, '4.3.3.1.1.39.00.00.00.00', 'SERVICOS EDUCACIONAIS', 'Registra as variações patrimoniais aumentativas provenientes das atividades do sistema educacional, cuja natureza esteja diretamente relacionada a formação do educando (matriculas, anuidades, etc.). As VPA de atividades auxiliares, de apoio ou derivadas dos serviços educacionais propriamente ditos, devem ser classificadas nos títulos apropriados. Exemplos: matriculas e anuidades, serviços educacionais, taxas de expedição de documentos, copias xerográficas, heliográficas, etc, serviço de credenciamento, autorização e reconhecimento de cursos.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8208, 1, '4.3.3.1.1.40.00.00.00.00', 'SERVICOS AGROPECUARIOS', 'Registra as variações patrimoniais aumentativas provenientes de serviços agropecuário: a) preparo e correção de solos (destocamento, aração, gradeação, calagem, adubação, drenagem, irrigação, capina, desmatamento, etc.); b) semeadura e plantio; c) combate a pragas (pulverização, dedetização); d)colheita e preparação de produtos agrícolas; e)inseminação artificial; f)incubação de ovos; g)vacinação de animais; h) outros serviços auxiliares de agricultura e pecuária.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8209, 1, '4.3.3.1.1.41.00.00.00.00', 'SERVICOS DE REPARAÇÃO,MANUTENÇÃO E INSTALAÇÃO', 'Registra as variações patrimoniais aumentativas provenientes de serviços de reparação, manutenção e instalação prestados. VPA de serviços de reparação de artefatos de metal; reparação e manutenção de maquinas e aparelhos de uso doméstico; reparação, manutenção e instalação de maquinas e aparelhos elétricos e eletrônicos e de comunicação; reparação e manutenção de instalações elétricas, de gás, de agua, etc. incluem-se também, nesse título, os serviços de confecção sob medida. Não são considerados nesse título, classificando-se em VPA industrial: reparação e manutenção de veículos ferroviários, embarcações e aeronaves (indústria de material de transporte).', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8210, 1, '4.3.3.1.1.42.00.00.00.00', 'SERVICOS RECREATIVOS E CULTURAIS', 'Registra as variações patrimoniais aumentativas provenientes de serviços recreativos e culturais prestados. VPA proporcionada pela exploração de instalações para recreação, pratica desportiva e cultural (cinemas, teatros, salões para recitais, concertos, conferencias, planetários, estádios desportivos, autódromos, museus, bibliotecas, promoção e/ou produção de espetáculos artísticos culturais e esportivos).', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8211, 1, '4.3.3.1.1.43.00.00.00.00', 'SERVICOS REG. MARCAS,PAT.TRANSF.DE TECNOLOGIA', 'Registra as variações patrimoniais aumentativas provenientes de serviços de registro de marcas, patentes e transferência de tecnologias. VPA correspondente aos serviços previstos no código da propriedade industrial, petições gerais, pedidos e petições relativas a privilégios, pedidos e petições relativas a marcas e patentes, pedidos e petições relativos a contratos de transferência de tecnologia e correlatos.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8234, 1, '4.4.2.4.1.01.00.00.00.00', 'MULTAS E JUROS SOBRE IMPOSTO SOBRE A RENDA E PROVENTOS DE QUALQUER NATUREZA', 'Registra os valores relativos a créditos a receber, decorrentes da cobrança do Imposto sobre a Renda e Proventos de Qualquer Natureza retidos na fonte.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (8212, 1, '4.3.3.1.1.44.00.00.00.00', 'SERVICOS DE REGISTRO DO COMERCIO', 'Registra as variações patrimoniais aumentativas provenientes de serviços de registro do comercio prestados. VPA advinda da prestação de serviços de registro do comercio e atividades afins, tratando-se de: a) serviços prestados pela junta comercial do distrito federal; b) serviços constantes do cadastro nacional de empresa, devidos no âmbito das juntas comerciais dos estados e do distrito federal; c) remuneração de serviços prestados pelo departamento nacional de registro do comercio.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8213, 1, '4.3.3.1.1.45.00.00.00.00', 'SERVICOS DE FORNECIMENTO DE AGUA', 'Registra as variações patrimoniais aumentativas provenientes de serviços prestados de fornecimento de agua aos irrigantes aa amortização dos investimentos da infraestrutura de irrigação dos projetos públicos, conforme dec.89.496, de 29.03de 84, relativos a tarifas k-1 e k-2.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8214, 1, '4.3.3.1.1.46.00.00.00.00', 'SERVICOS DE PERFURAÇÃO E INSTALAÇÃO DE POCOS', 'Registra as variações patrimoniais aumentativas provenientes de serviços prestados de perfuração e instalação de poços tubulares profundos, poços artesianos ou similares.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8215, 1, '4.3.3.1.1.47.00.00.00.00', 'SERVICOS DE GEOPROCESSAMENTO', 'Registra as variações patrimoniais aumentativas provenientes de serviços prestados a terceiros de interpretação de imagem aerofotogrametrica, execução de mapas digitalizados diversos, venda de cartas e imagens de satélites, videográficas e similares.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8216, 1, '4.3.3.1.1.48.00.00.00.00', 'SERVICOS DE CADASTRAMENTO DE FORNECEDORES', 'Registra as variações patrimoniais aumentativas provenientes de prestação de serviços de cadastramento de empresas fornecedoras de bens e serviços ao governo federal.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8217, 1, '4.3.3.1.1.49.00.00.00.00', 'TARIFA DE UTILIZAÇÃO DE FAROIS', 'Registra as variações patrimoniais aumentativas provenientes de tarifa de utilização de faróis. VPA proveniente da efetiva utilização, por embarcações estrangeiras, dos serviços de sinalização náutica de proteção a navegação. O produto da arrecadação e destinado integralmente ao fundo naval para aplicação nos serviços que envolvam a manutenção e ampliação da rede de balizamento marítimo, fluvial e lacustre, a cargo da diretoria de hidrografia e navegação do Ministério da Marinha.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8218, 1, '4.3.3.1.1.50.00.00.00.00', 'TARIFA E ADICIONAL SOBRE TARIFA AEROPORTUARIA', 'Registra as variações patrimoniais aumentativas provenientes de tarifa e adicional sobre tarifa aeroportuária. VPA provenientes de tarifa e adicional cobrados por embarque de passageiros, pouso e permanência de aeronaves nos aeroportos, armazenagem de mercadorias em armazéns de carga aérea e utilização de serviços relativos a manutenção e manuseio de mercadorias em armazéns de carga (tarifa de capatazia). VPA vinculada ao Ministério da Aeronáutica.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8219, 1, '4.3.3.1.1.51.00.00.00.00', 'SERVICOS DE CADASTRO DA ATIVIDADE MINERAL', 'Registra as variações patrimoniais aumentativas provenientes da taxa de serviços cadastrais quando do requerimento de autorização de pesquisa mineral.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8220, 1, '4.3.3.1.1.52.00.00.00.00', 'TAR.INSCR.CONCURSOS E PROCESSOS SELETIVOS', 'Registra as variações patrimoniais aumentativas provenientes de tarifas de inscrição em concursos e processos seletivos.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8221, 1, '4.4.2.4.1.16.00.00.00.00', 'MULTAS E JUROS DE DÍVIDA ATIVA TRIBUTÁRIA', 'Registra os valores de multas e juros de dívida ativa tributária.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8222, 1, '4.3.3.1.1.53.00.00.00.00', 'SERVICO DE COMPENSAÇÃO DE VARIAÇÕES SALARIAIS', 'Registra as variações patrimoniais aumentativas provenientes da cobrança de contribuições sobre o valor das prestações pagas pelos mutuários do sistema financeiro de habitação-SFH e sobre o saldo dos financiamentos imobiliários concedidos pelos agentes financeiros do SFH, com cobertura do FCVS.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8223, 1, '4.3.3.1.1.54.00.00.00.00', 'GARANTIAS E AVAIS', 'Registra as variações patrimoniais aumentativas provenientes da prestação de garantias e avais nas operações de credito. Fato gerador: concessão de garantias e avais, de natureza não-financeiras.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8224, 1, '4.3.3.1.1.55.00.00.00.00', 'CREDENCIAMENTO EMP.PREST.SERVICOS DE VISTORIA', 'Registra as variações patrimoniais aumentativas provenientes do valor a ser pago por empresas na obtenção de credenciamento para prestação de serviços de vistoria. - Destinação legal: órgão arrecadador; - amparo legal: resolução CONTRAN 282, de 26 de junho de 2008.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8225, 1, '4.3.3.1.1.56.00.00.00.00', 'SERVICOS VETERINARIOS', 'Registra as variações patrimoniais aumentativas provenientes de serviços veterinários.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8226, 1, '4.3.3.1.1.57.00.00.00.00', 'CERTIFICAÇÃO E HOMOLOGAÇÃO ATIVIDADE MINERAL', 'Registra as variações patrimoniais aumentativas provenientes de taxa de serviços cadastrais quando do requerimento de registro de licença e do registro de permissão de lavra garimpeira.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8227, 1, '4.3.3.1.1.58.00.00.00.00', 'SERV.INOV.A.PESQ.AMBIENT.PROD.-INST.CIEN.TEC.', 'Registra as variações patrimoniais aumentativas provenientes da prestação de serviços voltados a inovação e a pesquisa cientifica e tecnológica no ambiente produtivo.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8228, 1, '4.3.3.1.1.59.00.00.00.00', 'SERVICOS FINANCEIROS', 'Registra as variações patrimoniais aumentativas com serviços financeiros', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8229, 1, '4.3.3.1.1.60.00.00.00.00', 'SERV.COMERCIAIS DE PROD.DADOS E MAT.INFORMATI', 'Registra as variações patrimoniais aumentativas provenientes da comercialização de produtos, dados e materiais de informática, tais como disquetes, softwares, programas, CD-Rom, fitas magnéticas e assemelhados, bem como informações em redes e sistemas de dados disponíveis em meio de hardware.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8230, 1, '4.3.3.1.1.61.00.00.00.00', 'SERVIÇOS DE TURISMO', 'Registra as variações patrimoniais aumentativas com serviços de turismo.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8231, 1, '4.3.3.1.1.98.00.00.00.00', 'SERVIÇOS ADMINISTRATIVOS - RPPS', 'Registra as variações patrimoniais aumentativas provenientes de serviços administrativos prestados pelo RPPS, geralmente remunerados por meio de taxa de administração de serviços. ', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8232, 1, '4.3.3.1.1.99.00.00.00.00', 'OUTRAS VARIAÇÕES PATRIMONIAIS AUMENTATIVAS PROVENIENTES DE PRESTAÇÃO DE SERVICOS', 'Registra as variações patrimoniais aumentativas provenientes da prestação de outros serviços não enquadrados nos itens anteriores.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8233, 1, '4.5.1.1.2.04.00.00.00.00', 'RECURSOS ARRECADADOS - RECEBIDOS ', 'Registra o valor recebido de outro órgão ou entidade referente aos recursos que foram arrecadados (classificados como receita) para pagamento de despesas na unidade recebedora.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8235, 1, '4.4.2.4.1.02.00.00.00.00', 'MULTAS E JUROS SOBRE IPVA', 'Registra os valores relativos a créditos a receber, decorrentes da cobrança do Imposto sobre a Propriedade de Veículos Automotores.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (8237, 1, '4.4.2.4.1.04.00.00.00.00', ' MULTAS E JUROS SOBRE ICMS', 'Registra os valores relativos a créditos a receber, decorrentes da cobrança do Imposto sobre Operações Relativas a circulação de Mercadorias e sobre Prestação de Serviços de Transporte Interestadual e Intermunicipal e de Comunicação.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (8238, 1, '4.4.2.4.1.05.00.00.00.00', 'MULTAS E JUROS SOBRE IPTU', 'Registra os valores relativos a créditos a receber, decorrentes da cobrança do Imposto sobre a Propriedade Predial e Territorial Urbana.', 2, true, 2, 'p');
insert into contabilidade.planocontadetalhe values (8239, 1, '4.4.2.4.1.06.00.00.00.00', 'MULTAS E JUROS SOBRE ITBI', 'Registra os valores relativos a créditos a receber, decorrentes da cobrança do Imposto sobre Transmissão "Inter Vivos" de Bens Imóveis e de Direitos Reais sobre Imóveis', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (8240, 1, '4.4.2.4.1.07.00.00.00.00', 'MULTAS E JUROS SOBRE ISS', 'Registra os valores relativos aos créditos a receber, decorrentes do Imposto Sobre Serviços de Qualquer Natureza.', 2, true, 2, 'p');
insert into contabilidade.planocontadetalhe values (8241, 1, '4.5.2.3.3.03.00.00.00.00', 'SUBVENÇÕES SOCIAIS', 'Registra a variação patrimonial aumentativa decorrente de transferências às entidades privadas sem fins lucrativos para os serviços essenciais de assistência social, médica e educacional;', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8242, 1, '4.4.2.4.1.08.00.00.00.00', 'MULTAS E JUROS SOBRE ITR', 'Registra os valores relativos aos créditos a receber, decorrentes do Imposto Sobre a Propriedade Territorial Rural, devidos aos municípios ou ao Distrito Federal devido a convênios firmados com a União, conforme inciso III, parágrafo 4º do artigo 153 da Constituição Federal.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (8243, 1, '4.4.2.4.1.09.00.00.00.00', 'MULTAS E JUROS SOBRE TAXAS PELO EXERCÍCIO DO PODER DE POLÍCIA', 'Registra os valores relativos aos créditos a receber, decorrentes da cobrança das taxas pelo exercício do poder de polícia.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (8244, 1, '4.4.2.4.1.10.00.00.00.00', 'MULTAS E JUROS TAXAS PELA PRESTAÇÃO DE SERVIÇOS', 'Registra os valores relativos aos créditos a receber, decorrentes da cobrança das taxas pela prestação de serviços.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (8245, 1, '4.4.2.4.1.11.00.00.00.00', 'MULTAS E JUROS CONTRIBUIÇÕES DE MELHORIA', 'Compreende os valores relativos aos créditos a receber, decorrentes da cobrança dos valores decorrentes da contribuição instituída para fazer face ao custo de obras públicas de que decorra valorização imobiliária.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (8246, 1, '4.4.2.4.1.13.00.00.00.00', 'MULTAS E JUROS DEMAIS CONTRIBUIÇÕES', 'Registra os valores relativos aos créditos aos créditos a receber, decorrentes da cobrança das demais contribuições.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (8247, 1, '4.4.2.4.1.14.00.00.00.00', 'MULTAS E JUROS CONTRIBUIÇÃO PARA O CUSTEIO DO SERVIÇO DE ILUMINAÇÃO PÚBLICA', 'Registra os valores relativos aos crédtios a receber dos Municípios e o Distrito Federal que instituirem contribuição, na forma das respectivas leis, para o custeio do serviço de iluminação pública, conforme artigo 149-A da Constituição Federal de 1988. ', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (8248, 1, '4.4.2.4.1.15.00.00.00.00', 'MULTAS E JUROS CRÉDITOS TRIBUTARIOS PARCELADOS', 'Registra os valores relativos aos créditos aos créditos a receber, decorrentes de Créditos Tributários Parcelados.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (8249, 1, '4.5.1.1.2.08.00.00.00.00', 'VALORES DIFERIDOS - INSCRIÇÃO', 'Registra os valores no processo de inscrição dos recursos diferidos, subdividindo-se em: cota e repasse diferidos.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8250, 1, '4.5.1.1.2.09.00.00.00.00', 'DEVOLUÇÃO DE TRANSFERÊNCIAS CONCEDIDAS', 'Registra os valores de devoluções de transferências anteriormente concedidas', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8251, 1, '4.5.1.1.2.01.00.00.00.00', 'COTA RECEBIDA ', 'Registra o valor dos recursos recebidos pela administração direta decorrentes da programação financeira correspondente ao orçamento anual.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8252, 1, '4.5.1.1.2.02.00.00.00.00', 'REPASSE RECEBIDO  ', 'Registra o valor dos recursos recebidos decorrentes de transferências financeiras entre órgãos da administração direta e indireta, correspondentes ao orçamento anual.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8253, 1, '4.5.1.1.2.03.00.00.00.00', 'SUB-REPASSE RECEBIDO  ', 'Registra o valor dos recursos recebidos decorrentes de transferências financeiras entre órgãos da administração direta e indireta, correspondentes ao orçamento anual.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8254, 1, '4.5.1.2.2.01.01.00.00.00', 'ORDEM DE TRANSFERÊNCIAS RECEBIDAS   ', 'Registra o valor da ordem de transferência recebida (OTR) a título de recursos vinculados que deverão permanecer na própria unidade beneficiada.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8255, 1, '4.5.1.2.2.01.02.00.00.00', 'MOVIMENTO DE FUNDOS A DÉBITO - CORRESPONDÊNCIA DE DÉBITO - SALDOS NAO FINANCEIROS', 'Registra a apropriação da transferência de créditos internos entre órgãos correspondentes a saldos não financeiros.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8256, 1, '4.5.1.2.2.01.03.00.00.00', 'MOVIMENTO DE FUNDOS A DÉBITO - CORRESPONDÊNCIA DE DÉBITOS - SALDOS FINANCEIROS', 'Registra a apropriação da transferência de créditos internos entre órgãos correspondentes a saldos financeiros.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8257, 1, '4.5.1.2.2.01.99.00.00.00', 'OUTRAS TRANSFERÊNCIAS FINANCEIRAS RECEBIDAS - INDEPENDENTES DE EXECUÇÃO ORÇAMENTÁRIA', 'Registra o valor das demais transferências financeiras recebidas independentes da execução orçamentária.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8258, 1, '4.5.1.2.2.02.01.00.00.00', 'TRANSFERÊNCIAS RECEBIDAS DE BENS IMÓVEIS', 'Registra o valor das transferências de bens imóveis entre unidades do mesmo órgão.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8259, 1, '4.5.1.2.2.02.02.00.00.00', 'DOAÇÕES RECEBIDAS DE BENS IMÓVEIS', 'Registra o valor das doações de bens imóveis entre unidades de órgãos diferentes', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8260, 1, '4.5.1.2.2.02.03.00.00.00', 'TRANFERÊNCIAS RECEBIDAS DE BENS MÓVEIS ', 'Registra o valor dos bens moveis recebidos em decorrência de transferência entre unidades do mesmo órgão, independente de execução orçamentária.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8261, 1, '4.5.1.2.2.02.04.00.00.00', 'DOAÇÕES RECEBIDAS DE BENS MÓVEIS ', 'Registra o valor dos bens moveis recebidos em decorrência de transferência de outro órgão.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8262, 1, '4.5.1.2.2.02.05.00.00.00', 'TRANSFERÊNCIAS CONCEDIDAS DE TÍTULOS E VALORES ', 'Registra o total dos títulos e valores em circulação recebidos por unidade decorrente de transferência de outra unidade de mesma gestão.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8263, 1, '4.5.1.2.2.02.06.00.00.00', 'TRANSFERÊNCIAS CONCEDIDAS DE TÍTULOS DA DÍVIDA ATIVA', 'Registra o recebimento de títulos da dívida ativa de uma UG para a PGFN ou órgão equivalente.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8264, 1, '4.5.1.2.2.02.99.00.00.00', 'OUTRAS TRANSFERÊNCIAS  NÃO FINANCEIRAS RECEBIDAS - INDEPENDENTES DE EXECUÇÃO ORÇAMENTÁRIA', 'Registra o valor das demais transferências recebidas de bens ou valores independentes da execução orçamentária.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8265, 1, '4.5.1.2.2.09.00.00.00.00', 'DEVOLUÇÃO DE TRANSFERÊNCIAS', 'Registra o valor de devoluções de transferências anteriormente concedidas.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8266, 1, '4.5.1.3.2.01.01.00.00.00', 'RECURSOS PARA COBERTURA DE INSUFICIÊNCIAS FINANCEIRAS', 'Registra os recursos orçamentários efetivamente utilizados para a cobertura de insuficiências financeiras entre as receitas e despesas previdenciárias no exercício de referência.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8267, 1, '4.5.1.3.2.01.02.00.00.00', 'RECURSOS PARA FORMAÇÃO DE RESERVA', 'Registra os recursos transferidos pelo ente federativo ao RPPS para formação de reserva espontânea, para futuros pagamentos de benefícios do plano financeiro.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8268, 1, '4.5.1.3.2.01.99.00.00.00', 'OUTROS APORTES PARA O RPPS', 'Registra o somatório do recebimento de eventuais aportes de recursos no RPPS para outras necessidades financeiras que não a cobertura de insuficiências financeiras e formação de reservas.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8269, 1, '4.5.1.3.2.02.01.00.00.00', 'RECURSOS PARA COBERTURA DE DÉFICIT FINANCEIRO', 'Registra o somatório dos recebimentos de recursos necessários ao equilíbrio financeiro do plano previdenciário, ou seja, à cobertura de déficit entre as receitas e despesas previdenciárias, referentes ao exercício atual.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8270, 1, '4.5.1.3.2.02.02.00.00.00', 'RECURSOS PARA COBERTURA DE DÉFICIT ATUARIAL', 'Registra os recursos orçamentários alocados para cobertura de déficit atuarial no exercício de referência, desde que não definidos por lei como contribuições suplementares.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8271, 1, '4.5.1.3.2.02.03.00.00.00', 'TRANSFERÊNCIA DE BENS IMÓVEIS', 'Registra o valor dos bens imóveis recebido pelos RPPS para cobertura de déficit financeiro ou atuarial.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8272, 1, '4.5.1.3.2.02.04.00.00.00', 'TRANFERÊNCIAS DE BENS MÓVEIS ', 'Registra o valor dos bens móveis recebidos pelo RPPS para cobertura de déficit financeiro ou atuarial.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8273, 1, '4.5.1.3.2.02.99.00.00.00', 'OUTROS APORTES PARA O RPPS', 'Registra outros aportes financeiros para o RPPS com outras finalidades previdenciárias.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8274, 1, '8.1.1.1.1.01.08.00.00.00', 'SEGUROS-GARANTIA EXECUTADAS', 'Registra o valor recebido dos seguros-garantia, no país.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8275, 1, '4.5.1.4.2.01.01.00.00.00', 'PROVENIENTES DO ORÇAMENTO DA SEGURIDADE SOCIAL', 'Registra o montante do orçamento da Seguridade Social realocado da Saúde ou da Assistência Social para a Previdência.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8276, 1, '4.5.1.4.2.01.02.00.00.00', 'PROVENIENTES DO ORÇAMENTO FISCAL', 'Registra os valores das receitas do orçamento fiscal destinados para cobrir os déficits financeiros da Previdência', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8277, 1, '4.5.1.4.2.02.00.00.00.00', 'RECURSOS PARA FORMAÇÃO DE RESERVA', 'Registra os recursos transferidos pela União ao RGPS para formação de reserva espontânea, para futuros pagamentos de benefícios do plano financeiro.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8278, 1, '4.5.1.4.2.99.00.00.00.00', 'OUTROS APORTES PARA O RGPS', 'Registra o somatório do recebimento de eventuais aportes de  recursos para o RGPS para outras necessidades financeiras.', 2, true, 2, 'N');
