insert into contabilidade.planocontadetalhe values (8350, 1, '4.5.9.0.1.01.00.00.00.00', 'DOAÇÕES RECEBIDAS', 'Registra as variações patrimoniais aumentativas decorrentes de doações recebidas não compreendidos nas contas anteriores.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8351, 1, '4.6.1.1.1.01.01.00.00.00', 'REAVALIAÇÃO DE MÁQUINAS, APARELHOS, EQUIPAMENTOS E FERRAMENTAS', 'Registra a variação patrimonial aumentativa relativa à adoção do valor de mercado ou de consenso entre as partes para máquinas, ferramentas, aparelhos, equipamentos, acessórios etc, quando esse for inferior ao valor liquido contábil.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8352, 1, '4.6.1.1.1.01.02.00.00.00', 'REAVALIAÇÃO DE BENS DE INFORMÁTICA', 'Registra a variação patrimonial aumentativa relativa à adoção do valor de mercado ou de consenso entre as partes paraequipamentos de processamento de dados e sistemas aplicativos, entre outros, quando esse for inferior ao valor liquido contábil.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8353, 1, '4.6.1.1.1.01.03.00.00.00', 'REAVALIAÇÃO DE MÓVEIS E UTENSÍLIOS', 'Registra a variação patrimonial aumentativa relativa à adoção do valor de mercado ou de consenso entre as partes para mobiliário em geral e utensílios, entre outros, quando esse for inferior ao valor liquido contábil.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8354, 1, '4.6.5.1.2.99.00.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL DE DEMAIS INVESTIMENTOS PERMANENTES', 'Registra a variação patrimonial aumentativa com a reversão de redução a valor recuperável de demais investimentos permanentes.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8355, 1, '4.6.1.1.1.01.04.00.00.00', 'REAVALIAÇÃO DE MATERIAIS CULTURAIS, EDUCACIONAIS E DE COMUNICAÇÃO', 'Registra a variação patrimonial aumentativa relativa à adoção do valor de mercado ou de consenso entre as partes para materiais bibliográficos, discotecas, filmotecas, de comunicação, entre outros, quando esse for inferior ao valor liquido contábil.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8356, 1, '4.6.1.1.1.01.05.00.00.00', 'REAVALIAÇÃO DE VEÍCULOS', 'Registra a variação patrimonial aumentativa relativa à adoção do valor de mercado ou de consenso entre as partes para transportes aéreos, aquáticos e terrestres, entre outros, quando esse for inferior ao valor liquido contábil.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8357, 1, '4.6.1.1.1.01.06.00.00.00', 'REAVALIAÇÃO DE PEÇAS E CONJUNTOS DE REPOSIÇÃO', 'Registra a variação patrimonial aumentativa relativa à adoção do valor de mercado ou de consenso entre as partes para peças e conjuntos de reposição destinados a substituição em máquinas e equipamentos, aeronaves e embarcações, bens de segurança e socorro, entre outros, quando esse for inferior ao valor liquido contábil.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8358, 1, '8.1.1.1.1.01.11.00.00.00', 'GARANTIAS INSTITUÍDAS POR LEI ESPECÍFICA A EXECUTAR', 'Registra o valor das garantias instituídas por lei específica pendentes de execução, no país.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8359, 1, '4.6.1.1.1.01.07.00.00.00', 'REAVALIAÇÃO DE BENS MÓVEIS EM ANDAMENTO', 'Registra a variação patrimonial aumentativa relativa à adoção do valor de mercado ou de consenso entre as partes para bens móveis em andamento, quando esse for inferior ao valor liquido contábil.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8360, 1, '4.6.1.1.1.01.08.00.00.00', 'REAVALIAÇÃO DE BENS MÓVEIS EM ALMOXARIFADO', 'Registra a variação patrimonial aumentativa relativa à adoção do valor de mercado ou de consenso entre as partes para bens permanentes a serem estocados em almoxarifado, quando esse for inferior ao valor liquido contábil.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8361, 1, '4.6.1.1.1.01.09.00.00.00', 'REAVALIAÇÃO DE ARMAMENTOS', 'Registra a variação patrimonial aumentativa relativa à adoção do valor de mercado ou de consenso entre as partes para armas que constituem objetos de defesa ou preparativos de guerra, quando esse for inferior ao valor liquido contábil.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8362, 1, '5.2.2.1.9.02.09.00.00.00', '(-) REDUÇÃO', 'Registra o valor da redução da dotação devido a alteração da lei orçamentária em virtude de remanejamento.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (8363, 1, '4.6.1.1.1.01.10.00.00.00', 'REAVALIAÇÃO DE SEMOVENTES', 'Registra a variação patrimonial aumentativa relativa à adoção do valor de mercado ou de consenso entre as partes para animais destinados a produção, reprodução, engorda e aos serviços utilitários em geral, quando esse for inferior ao valor liquido contábil.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8364, 1, '4.6.1.1.1.01.99.00.00.00', 'REAVALIAÇÃO DE DEMAIS BENS MÓVEIS', 'Registra a variação patrimonial aumentativa relativa à adoção do valor de mercado ou de consenso entre as partes para demais bens móveis não classificados em grupos específicos, quando esse for inferior ao valor liquido contábil.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8365, 1, '4.6.1.1.1.02.01.00.00.00', 'REAVALIAÇÃO DE BENS DE USO ESPECIAL', 'Registra a variação patrimonial aumentativa relativa à adoção do valor de mercado ou de consenso entre as partes para os bens, tais como edifícios ou terrenos destinados a serviço ou estabelecimento da administração estadual ou municipal, inclusive os de suas autarquias e fundações públicas, quando esse for inferior ao valor liquido contábil.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8412, 1, '4.6.5.1.4.05.00.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL DE INVESTIMENTOS MANTIDOS PARA VENDA', 'Registra a variação patrimonial aumentativa com a reversão de redução a valor recuperável de investimentos permanentes mantidos para venda.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8366, 1, '4.6.1.1.1.02.02.00.00.00', 'REAVALIAÇÃO DE BENS DOMINICAIS', 'Registra a variação patrimonial aumentativa relativa à adoção do valor de mercado ou de consenso entre as partes para os bens que constituem o patrimônio das pessoas jurídicas de direito público, como objeto de direito pessoal, ou real, de cada uma dessas entidades. Compreende ainda, não dispondo a lei em contrário, os bens pertencentes as pessoas jurídicas de direito público a que se tenha dado estrutura de direito privado, quando esse for inferior ao valor liquido contábil.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8367, 1, '4.6.1.1.1.02.03.00.00.00', 'REAVALIAÇÃO DE BENS DE USO COMUM DO POVO', 'Registra a variação patrimonial aumentativa relativa à adoção do valor de mercado ou de consenso entre as partes para os bens de uso comum do povo construídos ou adquiridos por pessoas jurídicas de direito público, quando esse for inferior ao valor liquido contábil.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8368, 1, '4.6.1.1.1.02.04.00.00.00', 'REAVALIAÇÃO DE BENS IMÓVEIS EM ANDAMENTO', 'Registra a variação patrimonial aumentativa relativa à adoção do valor de mercado ou de consenso entre as partes para os valores de bens imóveis em andamento, quando esse for inferior ao valor liquido contábil.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8369, 1, '4.6.1.1.1.02.05.00.00.00', 'REAVALIAÇÃO DE INSTALAÇÕES', 'Registra a variação patrimonial aumentativa relativa à adoção do valor de mercado ou de consenso entre as partes para equipamentos, materiais e custo de implantação de instalações que, não obstante integradas aos edifícios, devem ser segregadas das obras civis, como, por exemplo, as instalações elétricas, hidráulicas, sanitárias, de vapor, de ar comprimido, frigoríficas, contra incêndio, de comunicações, de climatização, para combustíveis, gases, de antipoluição, para cozinha, dentre outros. E também aplicável a construção de trechos ferroviários, quando esse for inferior ao valor liquido contábil.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8370, 1, '4.6.1.1.1.02.06.00.00.00', 'REAVALIAÇÃO DE BENFEITORIAS EM PROPRIEDADE DE TERCEIROS', 'Registra a variação patrimonial aumentativa relativa à adoção do valor de mercado ou de consenso entre as partes para construções em terrenos arrendados de terceiros e instalações e outras benfeitorias em prédios alugados. São considerados somente os gastos com construção e instalação que se incorporam ao imóvel e revertem ao proprietário do imóvel ao final da locação, quando esse for inferior ao valor liquido contábil.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8371, 1, '4.6.1.1.1.02.99.00.00.00', 'REAVALIAÇÃO DE DEMAIS BENS IMÓVEIS', 'Registra a variação patrimonial aumentativa relativa à adoção do valor de mercado ou de consenso entre as partes para os demais bens imóveis não classificados anteriormente nesse plano de contas, quando esse for inferior ao valor liquido contábil.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8372, 1, '4.6.2.1.1.01.00.00.00.00', 'GANHOS COM ALIENAÇÃO DE PARTICIPAÇÕES PERMANENTES', 'Registra a variação patrimonial aumentativa de ganhos com alienação de participações permanentes.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8373, 1, '4.6.2.1.1.02.00.00.00.00', 'GANHOS COM ALIENAÇÃO DE PROPRIEDADES PARA INVESTIMENTO', 'Registra a variação patrimonial aumentativa de ganhos com alienação de propriedades para investimento.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8374, 1, '4.6.2.1.1.03.00.00.00.00', 'GANHOS COM ALIENAÇÃO DE INVESTIMENTOS DO RPPS DE LONGO PRAZO', 'Registra a variação patrimonial aumentativa de ganhos com alienação de investimentos do RPPS de longo prazo.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8375, 1, '4.6.2.1.1.99.00.00.00.00', 'GANHOS COM ALIENAÇÃO DE DEMAIS INVESTIMENTOS PERMANENTES', 'Registra a variação patrimonial aumentativa de ganhos com alienação de demais investimentos permanentes.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8376, 1, '4.6.2.2.1.01.01.00.00.00', 'GANHO LÍQUIDO COM A ALIENAÇÃO DE  MÁQUINAS, APARELHOS, EQUIPAMENTOS E FERRAMENTAS', 'Registra o ganho com alienação de ativo imobilizado, ou seja, quando o valor alienado do referido ativo e maior que o seu valor contábil, de maneira que a diferença compreende o ganho - Ganho Líquido com a Alienação de Máquinas, Equipamentos e Ferramentas.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8377, 1, '4.6.2.2.1.01.02.00.00.00', 'GANHO LÍQUIDO COM A ALIENAÇÃO DE BENS DE INFORMÁTICA', 'Registra o ganho com alienação de ativo imobilizado, ou seja, quando o valor alienado do referido ativo e maior que o seu valor contábil, de maneira que a diferença compreende o ganho - Ganho Líquido com a Alienação de Bens de Informática.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8378, 1, '4.6.2.2.1.01.03.00.00.00', 'GANHO LÍQUIDO COM A ALIENAÇÃO DE  MÓVEIS E UTENSÍLIOS', 'Registra o ganho com alienação de ativo imobilizado, ou seja, quando o valor alienado do referido ativo e maior que o seu valor contábil, de maneira que a diferença compreende o ganho - Ganho Líquido com a Alienação de Móveis e Utensílios.', 2, true, 2, 'N');
