insert into contabilidade.planocontadetalhe values (8419, 1, '4.6.5.2.1.01.01.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL DE MÁQUINAS, APARELHOS, EQUIPAMENTOS E FERRAMENTAS', 'Registra a variação patrimonial aumentativa com a reversão de redução a valor recuperável de máquinas, ferramentas, aparelhos, equipamentos, acessórios etc.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8420, 1, '4.6.5.2.1.01.02.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL DE BENS DE INFORMÁTICA', 'Registra a variação patrimonial aumentativa com a reversão de redução a valor recuperável de equipamentos de processamento de dados e sistemas aplicativos, entre outros.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8421, 1, '4.6.5.2.1.01.03.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL DE MÓVEIS E UTENSÍLIOS', 'Registra a variação patrimonial aumentativa com a reversão de redução a valor recuperável de mobiliário em geral e utensílios, entre outros.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8422, 1, '4.6.5.2.1.01.04.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL DE MATERIAIS CULTURAIS, EDUCACIONAIS E DE COMUNICAÇÃO', 'Registra a variação patrimonial aumentativa com a reversão de redução a valor recuperável de materiais bibliográficos, discotecas, filmotecas, de comunicação, entre outros.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8423, 1, '4.6.5.2.1.01.05.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL DE VEÍCULOS', 'Registra a variação patrimonial aumentativa com a reversão de redução a valor recuperável de transportes aéreos, aquáticos e terrestres, entre outros.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8424, 1, '4.6.5.2.1.01.06.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL DE PEÇAS E CONJUNTOS DE REPOSIÇÃO', 'Registra a variação patrimonial aumentativa com a reversão de redução a valor recuperável de peças e conjuntos de reposição destinados a substituição em máquinas e equipamentos, aeronaves e embarcações, bens de segurança e socorro, entre outros.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8425, 1, '4.6.5.2.1.01.07.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL DE BENS MÓVEIS EM ANDAMENTO', 'Registra a variação patrimonial aumentativa com a reversão de redução a valor recuperável de bens móveis em andamento.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8426, 1, '4.6.5.2.1.01.08.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL DE BENS MÓVEIS EM ALMOXARIFADO', 'Registra a variação patrimonial aumentativa com a reversão de redução a valor recuperável de bens permanentes a serem estocados em almoxarifado.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8427, 1, '4.6.5.2.1.01.09.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL DE ARMAMENTOS', 'Registra a variação patrimonial aumentativa com a reversão de redução a valor recuperável de armas que constituem objetos de defesa ou preparativos de guerra.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8428, 1, '4.6.5.2.1.01.10.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL DE SEMOVENTES', 'Registra a variação patrimonial aumentativa com a reversão de redução a valor recuperável de animais destinados a produção, reprodução, engorda e aos serviços utilitários em geral.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8429, 1, '4.6.5.2.1.01.99.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL DE DEMAIS BENS MÓVEIS', 'Registra a variação patrimonial aumentativa com a reversão de redução a valor recuperável de demais bens móveis não classificados em grupos específicos.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8430, 1, '4.9.9.6.1.04.00.00.00.00', 'REPOSIÇÃO/INDENIZAÇÃO DE SERVIDORES/AGENTES PÚBLICOS', 'Registra a variação patrimonial aumentativa proveniente de reposição ou indenização por parte de servidores ou agentes públicos.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8431, 1, '5.2.1.1.2.01.02.00.00.00', '(-) TRANSFERÊNCIAS CONSTITUCIONAIS E LEGAIS A MUNICÍPIOS', 'Registra a previsão de dedução da receita aprovada na LOA por transferências constitucionais e legais aos municípios, as quais representem repartição de receita orçamentária.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (8432, 1, '4.6.5.2.1.02.01.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL DE BENS DE USO ESPECIAL', 'Registra a variação patrimonial aumentativa com a reversão de redução a valor recuperável de bens como edifícios ou terrenos destinados a serviço ou estabelecimento da administração estadual ou municipal, inclusive os de suas autarquias e fundações públicas.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8433, 1, '4.6.5.2.1.02.02.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL DE BENS DOMINICAIS', 'Registra a variação patrimonial aumentativa com a reversão de redução a valor recuperável de bens que constituem o patrimônio das pessoas jurídicas de direito público, como objeto de direito pessoal, ou real, de cada uma dessas entidades. Compreende ainda, não dispondo a lei em contrário, os bens pertencentes as pessoas jurídicas de direito público a que se tenha dado estrutura de direito privado.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8434, 1, '4.6.5.2.1.02.03.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL DE BENS DE USO COMUM DO POVO', 'Registra a variação patrimonial aumentativa com a reversão de redução a valor recuperável de bens de uso comum do povo construídos ou adquiridos por pessoas jurídicas de direito público.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8435, 1, '4.6.5.2.1.02.04.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL DE BENS IMÓVEIS EM ANDAMENTO', 'Registra a variação patrimonial aumentativa com a reversão de redução a valor recuperável de valores de bens imóveis em andamento.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8463, 1, '5.2.1.2.9.00.00.00.00.00', '(-) ANULAÇÃO DA PREVISÃO DA RECEITA', 'Registra o valor da anulação da receita prevista no orçamento, na gestão fundos e nas administrações direta e indireta.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (8436, 1, '4.6.5.2.1.02.05.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL DE INSTALAÇÕES', 'Registra a variação patrimonial aumentativa com a reversão de redução a valor recuperável de equipamentos, materiais e custo de implantação de instalações que, não obstante integradas aos edifícios, devem ser segregadas das obras civis, como, por exemplo, as instalações elétricas, hidráulicas, sanitárias, de vapor, de ar comprimido, frigoríficas, contra incêndio, de comunicações, de climatização, para combustíveis, gases, de antipoluição, para cozinha, dentre outros. E também aplicável a construção de trechos ferroviários.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8437, 1, '4.6.5.2.1.02.06.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL DE BENFEITORIAS EM PROPRIEDADE DE TERCEIROS', 'Registra a variação patrimonial aumentativa com a reversão de redução a valor recuperável de construções em terrenos arrendados de terceiros e instalações e outras benfeitorias em prédios alugados. São considerados somente os gastos com construção e instalação que se incorporam ao imóvel e revertem ao proprietário do imóvel ao final da locação.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8438, 1, '4.6.5.2.1.02.99.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL DE DEMAIS BENS IMÓVEIS', 'Registra a variação patrimonial aumentativa com a reversão de redução a valor recuperável de os demais bens imóveis não classificados anteriormente nesse plano de contas.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8439, 1, '4.6.5.2.1.03.00.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL DE IMOBILIZADO MANTIDO PARA VENDA', 'Registra a variação patrimonial aumentativa com a reversão de redução a valor recuperável de imobilizados mantidos para venda', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8440, 1, '4.6.5.3.1.01.00.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL DE SOFTWARES', 'Registra a variação patrimonial aumentativa com a reversão de redução a valor recuperável de serviços de softwares.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8441, 1, '4.6.5.3.1.02.00.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL DE MARCAS, DIREITOS E PATENTES ', 'Registra a variação patrimonial aumentativa com a reversão de redução a valor recuperável de serviços de marcas, direitos e patentes.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8442, 1, '4.6.5.3.1.03.00.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL DE DIREITO DE USO DE IMÓVEIS', 'Registra a variação patrimonial aumentativa com a reversão de redução a valor recuperável de direito de uso de imóveis.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8443, 1, '4.6.5.3.1.04.00.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL DE INTANGÍVEL MANTIDO PARA VENDA', 'Registra a variação patrimonial aumentativa com a reversão de redução a valor recuperável de intangíveis mantidos para venda.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8444, 1, '4.9.1.0.1.01.00.00.00.00', 'VARIAÇÃO PATRIMONIAL AUMENTATIVA BRUTA A CLASSIFICAR', 'Registra os valores referentes a variação patrimonial aumentativas de diversas fontes ou origens, que não tenham sido devidamente classificados.', 2, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (8445, 1, '4.9.7.1.1.01.00.00.00.00', 'REVERSÃO DE PROVISÃO PARA RISCOS TRABALHISTAS', 'Registra a variação patrimonial aumentativa proveniente de reversão de provisão para riscos trabalhistas.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8446, 1, '4.9.7.1.1.02.00.00.00.00', 'REVERSÃO DE PROVISÕES MATEMÁTICAS PREVIDENCIÁRIAS A LONGO PRAZO', 'Registra a variação patrimonial aumentativa proveniente de reversão de provisões matemáticas previdenciárias a longo prazo.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8447, 1, '4.9.7.1.1.03.00.00.00.00', 'REVERSÃO DE PROVISÕES PARA RISCOS FISCAIS', 'Registra a variação patrimonial aumentativa proveniente de reversão de provisões para riscos fiscais.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8448, 1, '4.9.7.1.1.04.00.00.00.00', 'REVERSÃO DE PROVISÕES PARA RISCOS CÍVEIS', 'Registra a variação patrimonial aumentativa proveniente de reversão de provisão riscos cíveis.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8449, 1, '4.9.7.1.1.05.00.00.00.00', 'REVERSÃO DE PROVISÕES REPARTIÇÃO DE CRÉDITO', 'Registra a variação patrimonial aumentativa proveniente de reversão de provisões por repartição de crédito.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8450, 1, '4.9.7.1.1.06.00.00.00.00', 'REVERSÃO DE PROVISÕES DECORRENTES DE CONTRATOS DE PPP', 'Registra a variação patrimonial aumentativa proveniente de reversão de provisões decorrentes de contratos de PPP.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8451, 1, '4.9.7.1.1.99.00.00.00.00', 'REVERSÃO DE OUTRAS PROVISÕES', 'Registra a variação patrimonial aumentativa proveniente de reversão de outras provisões.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8452, 1, '4.9.7.2.1.01.00.00.00.00', 'REVERSÃO DE AJUSTES DE PERDAS DE CRÉDITOS', 'Registra a variação patrimonial aumentativa proveniente de reversão de ajustes de perdas de créditos.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8453, 1, '4.9.7.2.1.02.00.00.00.00', 'REVERSÃO DE AJUSTES DE PERDAS DE ESTOQUES', 'Registra a variação patrimonial aumentativa proveniente de reversão de ajustes de perdas de estoques.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8454, 1, '4.9.7.2.1.03.00.00.00.00', 'REVERSÃO DE AJUSTES DE INVESTIMENTOS E APLICAÇÕES', 'Registra a variação patrimonial aumentativa proveniente de reversão de ajustes de investimentos e aplicações.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8455, 1, '4.9.9.6.1.01.00.00.00.00', 'INDENIZ. POR DANOS CAUSADOS AO PATR. PUBLICO', 'Registra a variação patrimonial aumentativa proveniente de indenizações por danos causados ao patrimônio público.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8456, 1, '4.9.9.6.1.02.00.00.00.00', 'INDENIZAÇÃO POR PERDA/QUEBRA DE MERCADORIAS', 'Registra a variação patrimonial aumentativa proveniente de indenização por perda/quebra de mercadorias.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8457, 1, '4.9.9.6.1.03.00.00.00.00', 'INDENIZ. POSSE OU OCUPAÇÃO ILIC. BENS ', 'Registra a variação patrimonial aumentativa proveniente de indenização por posse ou ocupação ilícita de bens.', 2, true, 2, 'N');
insert into contabilidade.planocontadetalhe values (8458, 1, '5.2.1.1.2.01.01.00.00.00', '(-) FUNDEB', 'Registra a previsão de dedução da receita aprovada na LOA por transferências ao FUNDEB.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (8459, 1, '5.2.1.2.1.03.01.00.00.00', '(-) FUNDEB', 'Registra a previsão de dedução da receita para abertura de créditos adicionais por motivo de reestimativa ou correção da receita por transferências ao FUNDEB.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (8460, 1, '5.2.1.2.1.03.02.00.00.00', '(-) TRANSFERÊNCIAS CONSTITUCIONAIS E LEGAIS A MUNICÍPIOS', 'Registra a previsão de dedução da receita para abertura de créditos adicionais por motivo de reestimativa ou correção da receita por transferências constitucionais e legais aos municípios, as quais representem repartição de receita orçamentária.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (8461, 1, '5.2.1.2.1.04.00.00.00.00', '(-) PREVISÃO DE DEDUÇÕES DA RECEITA  POR RENÚNCIA', 'Registra a previsão de renúncia da receita para abertura de créditos adicionais por motivo de reestimativa ou correção da receita.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (8462, 1, '5.2.1.2.1.99.00.00.00.00', '(-) PREVISÃO DE OUTRAS DEDUÇÕES DA RECEITA', 'Registra a previsão de outras deduções da receita para abertura de créditos adicionais por motivo de reestimativa ou correção da receita.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (8464, 1, '5.2.2.1.1.02.09.00.00.00', '(-) ANULAÇÃO DA ANTECIPAÇÃO - LDO ', 'Registra o valor referente ao cancelamento de dotação antecipada prevista na lei de diretrizes orçamentarias - LDO, após aprovação do orçamento.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (8465, 1, '5.2.2.1.3.09.00.00.00.00', '(-) CANCELAMENTO DE DOTAÇÕES', 'Registra o cancelamento / remanejamento de dotações para abertura de créditos adicionais.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (8466, 1, '8.1.2.1.1.02.07.00.00.00', 'HIPOTECAS A EXECUTAR', 'Registra o valor das garantias por hipoteca pendentes de execução, no exterior.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8467, 1, '5.2.2.2.1.09.09.00.00.00', '(-) REDUÇÃO                                     ', 'Registra o valor da movimentação de créditos orçamentários por redução decorrente de alteração do quadro de detalhamento de despesa - QDD.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (8468, 1, '5.2.2.2.2.01.09.00.00.00', '(-) CREDITOS TRANSFERIDOS              ', 'Registra a movimentação de créditos de entidades da administração indireta ou entre órgãos da administração direta de unidade orçamentária diferente.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (8469, 1, '5.2.2.2.2.02.09.00.00.00', '(-) CREDITOS TRANSFERIDOS              ', 'Registra a movimentação de créditos de órgãos da administração direta ou entre entidades da administração indireta de mesma ou de diferente unidade orçamentária, não formalizada a termo de contrato.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (8470, 1, '5.2.2.2.2.09.09.00.00.00', '(-) REDUÇÃO                            ', 'Registra o valor da redução do credito disponível por alteração do quadro de detalhamento de despesa-QDD, por UG não pertencente ao órgão ou entidade da unidade orçamentária.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (8471, 1, '5.2.2.9.2.01.03.00.00.00', '(-) ANULAÇÃO DE EMPENHOS', 'Registra o valor referente a reversão total ou parcial de despesa à dotação inicial correspondente, através da "nota de anulação" da NE.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (8472, 1, '5.2.2.9.2.01.04.00.00.00', '(-) CANCEL. DE EMPENHO POR FALTA DE DISPON. CAIXA', 'Registra o cancelamento de empenhos por falta de disponibilidade de caixa.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (8473, 1, '6.1.1.1.0.00.00.00.00.00', 'PPA A ALOCAR EM LEIS ORÇAMENTÁRIAS ANUAIS', 'Compreende o somatório dos valores monetários do plano plurianual durante o seu período de vigência, detalhado por programas de trabalho a serem selecionados na elaboracao das leis orçamentárias anuais, nos quatro anos do PPA.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (8474, 1, '6.1.1.2.0.00.00.00.00.00', 'PPA ALOCADO  EM LEIS ORÇAMENTÁRIAS ANUAIS', 'Compreende o somatório dos valores monetários do plano plurianual aprovado, detalhado por programa de trabalho, alocado nas leis orçamentárias anuais ou relativos aos valores dos créditos antecipados pela LDO, dentro do período de vigência do PPA.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (8475, 1, '6.1.1.3.0.00.00.00.00.00', 'PPA EXECUTADO ', 'Compreende o somatório dos valores monetários empenhados do plano plurianual no seu período de vigência, detalhado por programa de trabalho, autorizado nas leis orçamentárias anuais.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (8476, 1, '6.1.2.1.0.00.00.00.00.00', 'PROCESSAMENTO DO PLOA -RECEITA', 'Compreende o somatório dos valores monetários das receitas previstas no projeto de lei orçamentária durante as suas fases de tramitação.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (8477, 1, '6.1.2.2.0.00.00.00.00.00', 'PROCESSAMENTO DO PLOA -DESPESA', 'Compreende o somatório dos valores monetários fixados para as despesas no projeto de lei orçamentária durante as suas fases de tramitação.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (8478, 1, '6.2.1.2.0.00.00.00.00.00', 'RECEITA REALIZADA', 'Compreende o somatório dos valores relativos às receitas realizadas, detalhada por natureza de receita.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (8479, 1, '6.2.2.1.1.00.00.00.00.00', 'CREDITO DISPONÍVEL', 'Registra o valor da disponibilidade de credito referente à dotação inicial e adicional aprovada no orçamento geral da União na loa ou lei especifica ou antecipada pela lei de diretrizes orçamentárias - LDO.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (8480, 1, '6.2.2.1.2.01.00.00.00.00', 'BLOQUEIO DE CREDITO                             ', 'Registra o valor da disponibilidade de créditos orçamentários por contenção ou contingenciamento pela setorial orçamentária, SOF e outros.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (8481, 1, '6.2.2.1.2.02.00.00.00.00', 'CREDITO PRE-EMPENHADO ', 'Registra os valores dos pré-empenhos emitidos pela unidade ou por outra unidade gestora.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (8482, 1, '6.2.2.1.2.99.00.00.00.00', 'OUTRAS INDISPONIBILIDADES', 'Registra o valor das indisponibilidades de créditos orçamentários de natureza eventual, para as quais não há contas específicas.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (8483, 1, '6.2.2.1.3.01.00.00.00.00', 'CREDITO EMPENHADO A LIQUIDAR', 'Registra o valor da despesa empenhada a ser liquidada', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (8484, 1, '6.2.2.1.3.02.00.00.00.00', 'CREDITO EMPENHADO EM LIQUIDAÇÃO', 'Registra o valor da despesa cujo fato gerador já ocorreu, mas que ainda não foram conferidos o objeto, e o valor, ou seja, não houve a liquidação.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (8485, 1, '6.2.2.1.3.03.00.00.00.00', 'CREDITO EMPENHADO LIQUIDADO A PAGAR', 'Registra o valor da apropriação das despesas empenhadas com posterior verificação de sua regularidade por constituição do direto do credor.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (8486, 1, '6.2.2.1.3.04.00.00.00.00', 'CREDITO EMPENHADO LIQUIDADO PAGO', 'Registra o valor da despesa empenhada liquidada paga.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (8487, 1, '6.2.2.1.3.05.00.00.00.00', 'EMPENHOS A LIQUIDAR INSCRITOS EM RESTOS A PAGAR NAO PROCESSADOS', 'Registra o montante dos valores a liquidar inscritos em restos a pagar nao processados.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (8488, 1, '6.2.2.1.3.06.00.00.00.00', 'EMPENHOS EM LIQUIDAÇÃO INSCRITOS EM RESTOS A PAGAR NAO PROCESSADOS', 'Registra o montante dos valores em liquidação inscritos em restos a pagar nao processados.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (8489, 1, '6.2.2.1.3.07.00.00.00.00', 'EMPENHOS LIQUIDADOS INSCRITOS EM RESTOS A PAGAR PROCESSADOS', 'Registra o montante dos valores liquidados inscritos em restos a pagar processados.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (8490, 1, '6.2.2.2.1.01.00.00.00.00', 'PROVISAO CONCEDIDA             ', 'Registra o credito concedido pela unidade orçamentária a partir de sua própria dotação ou de um destaque a seu favor, para unidade administrativa ou orçamentária, no âmbito do próprio ministério ou órgão.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (8491, 1, '6.2.2.2.1.02.00.00.00.00', 'PROVISAO CONCEDIDA - BLOQUEADA ', 'Registra o bloqueio dos créditos orçamentários concedidos mediante provisão.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (8492, 1, '6.2.2.2.1.09.01.00.00.00', 'ACRESCIMO', 'Registra o valor do acréscimo de credito disponível decorrente de alteração do quadro de detalhamento de despesa - QDD, por UG pertencente ao órgão ou entidade da unidade orçamentária.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (8493, 1, '6.2.2.2.2.01.01.00.00.00', 'CREDITOS CONCEDIDOS', 'Registra o valor referente a movimentação de créditos decorrentes de concessão pela unidade orçamentária do órgão da administração direta transferidora.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (8494, 1, '6.2.2.2.2.02.01.00.00.00', 'CREDITOS CONCEDIDOS', 'Registra o valor referente a movimentação de créditos decorrentes de sua concessão pela unidade orçamentária do órgão da administração indireta transferidora.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (8495, 1, '6.2.2.2.2.09.01.00.00.00', 'ACRESCIMO', 'Registra o valor do acréscimo de credito disponível decorrente de alteração do quadro de detalhamento de despesa - QDD, por UG não pertencente ao órgão ou entidade da unidade orçamentária.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (8496, 1, '6.2.2.3.1.00.00.00.00.00', 'CREDITOS DETALHADOS', 'Registra o valor dos créditos detalhados por fonte de recursos, UG responsável e natureza de despesa (elemento de despesa e / ou modalidade de aplicação).', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (8497, 1, '6.2.2.9.1.01.00.00.00.00', 'PRE-EMPENHOS A EMPENHAR ', 'Registra os valores dos pré-empenhos emitidos e/ou seus respectivos reforços.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (8498, 1, '6.2.2.9.1.02.00.00.00.00', 'PRE-EMPENHOS EMPENHADOS ', 'Registra os valores dos pré-empenhos e/ou seus respectivos reforços, emitidos e empenhados.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (8499, 1, '6.2.2.9.2.01.01.00.00.00', 'EMPENHOS A LIQUIDAR ', 'Registra o valor dos empenhos de despesas pendentes de liquidação.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (8500, 1, '6.2.2.9.2.01.02.00.00.00', 'EMPENHOS EM LIQUIDAÇÃO', 'Registra o somatório das despesas cujo fato gerador tenha ocorrido, tendo iniciado e não concluído o processo de liquidação da despesa orçamentária.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (8501, 1, '6.2.2.9.2.01.03.00.00.00', 'EMPENHOS LIQUIDADOS A PAGAR ', 'Registra o valor dos empenhos após verificação do direito adquirido pelo credor ou entidade beneficiária.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (8502, 1, '6.2.2.9.2.01.04.00.00.00', 'EMPENHOS LIQUIDADOS PAGOS', 'Registra o montante dos valores pagos, controlados por nota de empenho e subitem.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (8503, 1, '6.3.1.1.0.00.00.00.00.00', 'RP NÃO PROCESSADOS A LIQUIDAR', 'Compreende o valor dos RP não processados ainda não liquidados.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (8504, 1, '6.3.1.2.0.00.00.00.00.00', 'RP NÃO PROCESSADOS EM LIQUIDAÇÃO', 'Compreende o valor dos RP não processados ainda não liquidados cujo fato gerador já ocorreu.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (8505, 1, '6.3.1.3.0.00.00.00.00.00', 'RP NÃO PROCESSADOS LIQUIDADOS A PAGAR', 'Compreende o valor dos RP não processados, liquidados após sua inscrição e ainda não pagos.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (8506, 1, '6.3.1.4.0.00.00.00.00.00', 'RP NÃO PROCESSADOS PAGOS', 'Compreende o valor dos RP não processados, liquidados após sua inscrição e pagos.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (8507, 1, '6.3.1.5.0.00.00.00.00.00', 'RP NÃO PROCESSADOS A LIQUIDAR BLOQUEADOS', 'Compreende o valor de restos a pagar não processados a liquidar, bloqueado por decreto.', 2, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (8508, 1, '6.3.1.6.0.00.00.00.00.00', 'RP NÃO PROCESSADOS TRANSFERIDOS', 'Compreende o valor da transferência de restos a pagar não processados pela desincorporação de saldos decorrentes de transformação, cisão, fusão e extinção de órgãos ou UG.', 2, true, 4, 'N');
