insert into contabilidade.planocontadetalhe values (8721, 1, '8.2.1.1.3.01.00.00.00.00', 'COMPROMETIDA POR LIQUIDAÇÃO', 'Registra o valor das disponibilidades de recursos comprometidas por ocasião da liquidação. O saldo desta conta representa o valor líquido dos empenhos a pagar.', 2, true, 1, 'N');
