insert into contabilidade.planocontadetalhe values (8759, 1, '8.3.2.5.2.01.00.00.00.00', 'BAIXAS DE CRÉDITOS INSCRITOS EM DÍVIDA ATIVA NÃO-TRIBUTÁRIA EM COBRANÇA ADMNISTRATIVA', 'Registra as baixas de créditos inscritos em dívida ativa não-tributária, em cobrança administrativa.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8760, 1, '8.3.2.5.2.02.00.00.00.00', 'BAIXAS DE CRÉDITOS INSCRITOS EM DÍVIDA ATIVA NÃO-TRIBUTÁRIA EM COBRANÇA JUDICIAL', 'Registra as baixas de créditos inscritos em dívida ativa não-tributária, em cobrança judicial.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8761, 1, '8.4.1.1.1.00.00.00.00.00', 'DEMANDAS JUDICIAIS', 'Registra a estimativa do montante relativo a ações judiciais em andamento contra o ente federativo nas quais haja a probabilidade de que o ganho de causa venha a ser da outra parte. Ao fazer a estimativa, considerar os principais tipos de ação judicial, tais como:a) Demandas judiciais contra a atividade reguladora do Estado: Indexação e controles de preços; De ordem tributária e previdenciária; Outras demandas judiciais;b) Demandas judiciais contra empresas estatais dependentes;c) Demandas judiciais contra a administração direta e indireta: Privatizações, liquidação ou extinção de órgãos ou empresas; Reajustes salariais;d) Demandas trabalhistas contra o ente federativo;e) Outras demandas judiciais.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8762, 1, '8.4.1.1.2.00.00.00.00.00', 'DÍVIDAS EM PROCESSO DE RECONHECIMENTO', 'Registra as Dívidas ainda não assumidas formalmente que apresentam probabilidade de serem incorporadas ao passivo devido, por exemplo, a decisões judiciais.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8763, 1, '8.4.1.1.3.00.00.00.00.00', 'AVAIS E GARANTIAS CONCEDIDAS', 'Registra a estimativa do montante que apresenta probabilidade de vir a ser gasto pelo ente federativo para honrar fianças e avais concedidos em operações de crédito direta ou indiretamente pelo ente federativo a favor de outros entes federativos e entidades dos setores público e privado, inclusive com recursos de fundos de aval, a assunção de risco creditício em linhas de crédito, o seguro de crédito à exportação e outras garantias de natureza semelhante que representem compromisso de adimplência de obrigação financeira ou contratual.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8764, 1, '8.4.1.1.4.00.00.00.00.00', 'ASSUNÇÃO DE PASSIVOS', 'Registra a estimativa do montante que apresenta probabilidade de vir a ser gasto pelo ente federativo com o objetivo de proteger o cidadão ou sistemas importantes do Mercado contra inadimplências, falências, altos prejuízos, ou garantir a credibilidade desses sistemas frente a fatores agudos adversos. Ao fazer a estimativa, considerar os principais tipos de situações que podem advir:a) de órgãos da administração direta ou indireta;b) de entidades privadas;c) de Regime Próprio de Previdência Social dos Servidores Públicos;d) de Entes da Federação;e) do Regime Geral de Previdência Social;f) do Banco Central; eg) da assunção de outros passivos.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8765, 1, '8.4.1.1.5.00.00.00.00.00', 'ASSISTÊNCIAS DIVERSAS', 'Registra a estimativa do montante que apresenta probabilidade de vir a ser empregado pelo ente federativo com o objetivo de fazer frente a calamidades públicas e que, por não serem recorrentes, não foram planejados. Recomenda-se que o ente federativo explicite o tipo de assistência emergencial que ele está prevendo, por exemplo, se é assistência contra seca, enchentes, catástrofes, epidemias etc.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8766, 1, '8.4.1.1.9.00.00.00.00.00', 'OUTROS PASSIVOS CONTINGENTES', 'Registra a estimativa do montante que apresenta probabilidade de vir a ser empregado pelo ente federativo para fazer frente a outros tipos de passivos contingentes.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8767, 1, '8.4.1.2.1.00.00.00.00.00', 'DEMANDAS JUDICIAIS', 'Registra a estimativa do montante relativo a ações judiciais em andamento contra o ente federativo nas quais haja a probabilidade de que o ganho de causa venha a ser da outra parte. Ao fazer a estimativa, considerar os principais tipos de ação judicial, tais como:a) Demandas judiciais contra a atividade reguladora do Estado: Indexação e controles de preços; De ordem tributária e previdenciária; Outras demandas judiciais;b) Demandas judiciais contra empresas estatais dependentes;c) Demandas judiciais contra a administração direta e indireta: Privatizações, liquidação ou extinção de órgãos ou empresas; Reajustes salariais;d) Demandas trabalhistas contra o ente federativo;e) Outras demandas judiciais.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8768, 1, '8.4.1.2.2.00.00.00.00.00', 'DÍVIDAS EM PROCESSO DE RECONHECIMENTO', 'Registra as Dívidas ainda não assumidas formalmente que apresentam probabilidade de serem incorporadas ao passivo devido, por exemplo, a decisões judiciais.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8769, 1, '8.4.1.2.3.00.00.00.00.00', 'AVAIS E GARANTIAS CONCEDIDAS', 'Registra a estimativa do montante que apresenta probabilidade de vir a ser gasto pelo ente federativo para honrar fianças e avais concedidos em operações de crédito direta ou indiretamente pelo ente federativo a favor de outros entes federativos e entidades dos setores público e privado, inclusive com recursos de fundos de aval, a assunção de risco creditício em linhas de crédito, o seguro de crédito à exportação e outras garantias de natureza semelhante que representem compromisso de adimplência de obrigação financeira ou contratual.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8770, 1, '8.5.3.3.8.00.00.00.00.00', 'RP NÃO PROCESSADOS CANCELADOS', 'Compreende o cancelamento de restos a pagar não processados por insuficiência de recursos, pela inscrição indevida ou para atender dispositivo legal, em consórcios públicos atribuídos ao ente consorciado com base no contrato de rateio.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8771, 1, '8.5.3.4.1.00.00.00.00.00', 'RP PROCESSADOS A PAGAR', 'Registra o valor dos RP processados e não pagos em consórcios públicos atribuídos ao ente consorciado com base no contrato de rateio.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8772, 1, '8.4.1.2.4.00.00.00.00.00', 'ASSUNÇÃO DE PASSIVOS', 'Registra a estimativa do montante que apresenta probabilidade de vir a ser gasto pelo ente federativo com o objetivo de proteger o cidadão ou sistemas importantes do Mercado contra inadimplências, falências, altos prejuízos, ou garantir a credibilidade desses sistemas frente a fatores agudos adversos. Ao fazer a estimativa, considerar os principais tipos de situações que podem advir:a) de órgãos da administração direta ou indireta;b) de entidades privadas;c) de Regime Próprio de Previdência Social dos Servidores Públicos;d) de Entes da Federação;e) do Regime Geral de Previdência Social;f) do Banco Central; eg) da assunção de outros passivos.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8773, 1, '8.4.1.2.5.00.00.00.00.00', 'ASSISTÊNCIAS DIVERSAS', 'Registra a estimativa do montante que apresenta probabilidade de vir a ser empregado pelo ente federativo com o objetivo de fazer frente a calamidades públicas e que, por não serem recorrentes, não foram planejados. Recomenda-se que o ente federativo explicite o tipo de assistência emergencial que ele está prevendo, por exemplo, se é assistência contra seca, enchentes, catástrofes, epidemias etc.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8774, 1, '8.4.1.2.9.00.00.00.00.00', 'OUTROS PASSIVOS CONTINGENTES', 'Registra a estimativa do montante que apresenta probabilidade de vir a ser empregado pelo ente federativo para fazer frente a outros tipos de passivos contingentes.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8775, 1, '8.4.2.1.1.00.00.00.00.00', 'FRUSTRAÇÃO DE ARRECADAÇÃO', 'Registra a estimativa do montante de redução de arrecadação que apresenta probabilidade de vir a ocorrer no exercício, decorrente de, por exemplo, cenários macroeconômicos desfavoráveis não previstos na época da elaboração do Orçamento.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8776, 1, '8.4.2.1.3.00.00.00.00.00', 'DISCREPÂNCIA DE PROJEÇÕES:', 'Registra a estimativa do montante de redução no valor dos ingressos ou de aumento no valor dos desembolsos que apresentam probabilidade de vir a ocorrer no exercício, decorrentes de evolução desfavorável de indicadores econômicos empregados na época da elaboração do Orçamento, tais como:a) Taxa de crescimento econômico;b) Taxa de inflação;c) Taxa de câmbio;d) Taxa de juros;e) Salário mínimo;f) Outros indicadores.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8777, 1, '8.4.2.1.4.00.00.00.00.00', 'OUTROS RISCOS FISCAIS', 'Registra a estimativa do montante que apresenta probabilidade de vir a ser empregado pelo ente federativo para fazer frente a outros tipos de riscos fiscais.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8778, 1, '8.5.2.2.0.00.00.00.00.00', 'EM INADIMPLENCIA', 'Compreende os valores transferidos dos Consórcios Públicos em que não houve prestação de contas dentro do prazo estipulado.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8779, 1, '8.5.2.3.0.00.00.00.00.00', 'A APROVAR', 'Compreende os valores transferidos dos Consórcios Públicos a aprovar.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8780, 1, '8.5.2.4.0.00.00.00.00.00', 'APROVADOS', 'Compreende os valores transferidos dos Consórcios Públicos aprovados.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8781, 1, '8.5.2.5.0.00.00.00.00.00', 'IMPUGNADOS', 'Compreende os valores transferidos dos Consórcios Públicos impugnados.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8782, 1, '8.5.2.6.0.00.00.00.00.00', 'CONCLUÍDOS', 'Compreende os valores transferidos dos Consórcios Públicos concluídos.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8783, 1, '8.5.3.1.0.00.00.00.00.00', 'VALORES TRANSFERIDOS POR CONTRATO DE RATEIO', 'Compreende os valores repassados pelo ente para execução das despesas nos Consórcios Públicos, com base no Contrato de Rateio.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8784, 1, '8.5.3.2.1.00.00.00.00.00', 'CREDITO EMPENHADO A LIQUIDAR', 'Registra o valor da despesa empenhada a ser liquidada executadas em consórcios públicos atribuídas ao ente consorciado com base no contrato de rateio.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8785, 1, '8.5.3.2.2.00.00.00.00.00', 'CREDITO EMPENHADO EM LIQUIDAÇÃO', 'Registra o valor da despesa cujo fato gerador já ocorreu, mas que ainda não foram conferidos o objeto, e o valor, ou seja, não houve a liquidação, executadas em consórcios públicos atribuídas ao ente consorciado com base no contrato de rateio.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8786, 1, '8.5.3.2.3.00.00.00.00.00', 'CREDITO EMPENHADO LIQUIDADO A PAGAR', 'Registra o valor da apropriação das despesas empenhadas com posterior verificação de sua regularidade por constituição do direto do credor, executadas em consórcios públicos atribuídas ao ente consorciado com base no contrato de rateio.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8787, 1, '8.5.3.2.5.00.00.00.00.00', 'EMPENHOS A LIQUIDAR INSCRITOS EM RESTOS A PAGAR NAO PROCESSADOS', 'Demonstra o montante dos valores a liquidar inscritos em restos a pagar nao processados, executadas em consórcios públicos atribuídas ao ente consorciado com base no contrato de rateio', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8788, 1, '8.5.3.2.6.00.00.00.00.00', 'EMPENHOS EM LIQUIDAÇÃO INSCRITOS EM RESTOS A PAGAR NAO PROCESSADOS', 'Demonstra o montante dos valores em liquidação inscritos em restos a pagar nao processados, executadas em consórcios públicos atribuídas ao ente consorciado com base no contrato de rateio', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8789, 1, '8.5.3.2.7.00.00.00.00.00', 'EMPENHOS LIQUIDADOS INSCRITOS EM RESTOS A PAGAR PROCESSADOS', 'Demonstra o montante dos valores liquidados inscritos em restos a pagar processados, executadas em consórcios públicos atribuídas ao ente consorciado com base no contrato de rateio', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8790, 1, '8.5.3.3.1.00.00.00.00.00', 'RP NÃO PROCESSADOS A LIQUIDAR', 'Registra o valor dos RP não processados ainda não liquidados, em consórcios públicos atribuídos ao ente consorciado com base no contrato de rateio.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8791, 1, '8.5.3.3.2.00.00.00.00.00', 'RP NÃO PROCESSADOS EM LIQUIDAÇÃO', 'Registra o valor dos RP não processados ainda não liquidados cujo fato gerador já ocorreu em consórcios públicos atribuídos ao ente consorciado com base no contrato de rateio.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8792, 1, '8.5.3.3.3.00.00.00.00.00', 'RP NÃO PROCESSADOS LIQUIDADOS A PAGAR', 'Registra o valor dos RP não processados, liquidados após sua inscrição e ainda não pagos em consórcios públicos atribuídos ao ente consorciado com base no contrato de rateio.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8793, 1, '8.5.3.3.4.00.00.00.00.00', 'RP NÃO PROCESSADOS PAGOS', 'Registra o valor dos RP não processados, liquidados após sua inscrição e pagos em consórcios públicos atribuídos ao ente consorciado com base no contrato de rateio.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (9326, 1, '6.2.2.1.2.00.00.00.00.00', 'CREDITO INDISPONÍVEL', 'Compreende o valor da indisponibilidade de credito orçamentário pelo seu contingenciamento ou liberação pendentes de autorização legislativa.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8794, 1, '8.5.3.3.5.00.00.00.00.00', 'RP NÃO PROCESSADOS A LIQUIDAR BLOQUEADOS', 'Registra o valor de restos a pagar não processados a liquidar, bloqueado por decreto em consórcios públicos atribuídas ao ente consorciado com base no contrato de rateio.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8795, 1, '8.5.3.3.6.00.00.00.00.00', 'RP NÃO PROCESSADOS TRANSFERIDOS', 'Registra o valor da transferência de restos a pagar não processados pela desincorporação de saldos decorrentes de transformação, cisão, fusão e extinção de órgãos ou UG.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8796, 1, '8.5.3.3.7.00.00.00.00.00', 'RP NÃO PROCESSADOS - INSCRIÇÃO NO EXERCÍCIO', 'Registra o valor das despesas empenhadas inscritas no exercício como restos a pagar não processados, a ser transferido no exercício seguinte para a conta 631100000 e 631200000, em consórcios públicos atribuídos ao ente consorciado com base no contrato de rateio.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8797, 1, '8.5.3.4.2.00.00.00.00.00', 'RP PROCESSADOS PAGOS', 'Registra o valor dos RP processados pagos em consórcios públicos atribuídos ao ente consorciado com base no contrato de rateio.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8798, 1, '8.5.3.4.3.00.00.00.00.00', 'RP PROCESSADOS TRANSFERIDOS', 'Registra o valor da transferência de restos a pagar pela desincorporação de saldos decorrente de transformação, cisão, fusão e extinção de órgãos ou UG em consórcios públicos atribuídos ao ente consorciado com base no contrato de rateio.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8799, 1, '8.5.3.4.4.00.00.00.00.00', 'RP PROCESSADOS - INSCRIÇÃO NO EXERCÍCIO', 'Registra o valor das despesas empenhadas inscritas no exercício como restos a pagar processados, a ser transferido no exercício seguinte para a conta 632100000, em consórcios públicos atribuídos ao ente consorciado com base no contrato de rateio.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8800, 1, '8.5.3.4.5.00.00.00.00.00', 'RP PROCESSADOS CANCELADOS', 'Compreende o cancelamento de restos a pagar processados por insuficiência de recursos, pela inscrição indevida ou para atender dispositivo legal, em consórcios públicos atribuídos ao ente consorciado com base no contrato de rateio.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8801, 1, '8.5.3.5.0.00.00.00.00.00', 'INSUFICIÊNCIA DE CAIXA DO CONSÓRCIO PÚBLICO', 'Compreende a parcela total da insuficiência de caixa gerada no consórcio público atribuída ao ente consorciado com base no contrato de rateio.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8802, 1, '8.5.3.6.0.00.00.00.00.00', 'OPERAÇÃO DE CRÉDITO CONTRATADA PELO CONSÓRCIO PÚBLICO', 'Compreende a parcela da operação de crédito contratada pelo consórcio público atribuída ao ente consorciado com base no contrato de rateio.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8803, 1, '8.5.3.7.0.00.00.00.00.00', 'DÍVIDA CONSOLIDADA REFERENTE AO CONSÓRCIO PÚBLICO', 'Compreende o valor da dívida consolidada do consórcio público.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8804, 1, '8.9.1.1.1.00.00.00.00.00', 'DEPÓSITOS JUDICIAIS', 'Registra os depósitos judiciais efetuados por terceiros em títulos, em conta vinculada etc, sob a responsabilidade da unidade, ou depositados por esta para terceiros.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8805, 1, '8.9.1.1.2.00.00.00.00.00', 'DEPÓSITOS COMPULSÓRIOS', 'Registra o somatório dos valores dos depósitos compulsórios realizados.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8806, 1, '8.9.1.1.3.00.00.00.00.00', 'OUTRAS RESPONSABILIDADES COM TERCEIROS', 'Registra responsabilidades com terceiros, não individualizadas nas outras contas desse grupo.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8807, 1, '8.9.1.2.1.01.00.00.00.00', 'ADIANTAMENTOS CONCEDIDOS A COMPROVAR', 'Registra os valores dos adiantamentos concedidos pendentes de comprovação', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8808, 1, '8.9.1.2.1.02.00.00.00.00', 'ADIANTAMENTOS A APROVAR', 'Registra os valores dos adiantamentos concedidos comprovados pendentes de aprovação.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8809, 1, '8.9.1.2.1.03.00.00.00.00', 'ADIANTAMENTOS APROVADOS', 'Registra os valores dos adiantamentos concedidos aprovados.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8810, 1, '8.9.1.2.1.04.00.00.00.00', 'ADIANTAMENTOS IMPUGNADOS', 'Registra os valores dos adiantamentos concedidos impugnados.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8811, 1, '8.9.1.2.1.05.00.00.00.00', 'ADIANTAMENTOS EM INDADIMPLENCIA', 'Registra os valores dos adiantamentos concedidos em inadimplência.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8812, 1, '8.9.1.2.1.06.00.00.00.00', 'ADIANTAMENTOS CANCELADOS', 'Registra os valores dos adiantamentos concedidos cancelados.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8813, 1, '8.9.1.2.2.01.00.00.00.00', 'ATIVOS DE PPP CONTABILIZADOS NO ENTE', 'Registra o valor dos ativos oriundos de contratos de Parcerias Público Privadas-PPP. Tais bens devem estar reconhecidos no ativo imobilizado do ente (Poder Concedente), mas devem ser registrados em conta de controle a fim de obter a informação segregada dos ativos produzidos por meio de PPP.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8814, 1, '8.9.1.2.9.00.00.00.00.00', 'EXECUÇÃO DE OUTRAS RESPONSABILIDADES DE TERCEIROS', 'Registra responsabilidades com terceiros, não individualizadas nas outras contas desse grupo.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8815, 1, '8.9.2.1.0.00.00.00.00.00', 'PAGAMENTOS INDEVIDOS', 'Compreende as responsabilidades em apuração de gestores e outros responsáveis e corresponsáveis por pagamentos efetuados indevidamente, inclusive em casos de superfaturamento.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8816, 1, '8.9.2.2.0.00.00.00.00.00', 'SALDOS NÃO RECOLHIDOS', 'Compreende os saldos dos valores entregues a funcionários ou servidores, não recolhidos dentro dos prazos estabelecidos em normas legais ou administrativas cujos processos estejam em fase de apuração.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8817, 1, '8.9.2.3.0.00.00.00.00.00', 'DESFALQUES OU DESVIOS', 'Compreende os desfalques ou desvios de bens e valores da União ou de entidades públicas, em apuração, decorrentes de processos por ações administrativas, policiais ou judiciais.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8818, 1, '8.9.2.4.0.00.00.00.00.00', 'DÉBITOS DE TERCEIROS EM PRESTAÇÃO DE SERVIÇOS', 'Compreende os valores relativos as responsabilidades por irregularidades em prestação de serviços por terceiros, cujos processos estejam em fase de apuração.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8819, 1, '8.9.2.5.0.00.00.00.00.00', 'RESPONSÁVEIS POR DANOS OU PERDAS', 'Compreende o registro das responsabilidades em inquéritos administrativos ou policiais contra servidores ou terceiros, por danos e perdas causados a fazenda nacional, e que estejam em fase de apuração.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8820, 1, '8.9.2.6.0.00.00.00.00.00', 'PAGAMENTOS SEM RESPALDO ORÇAMENTÁRIO', 'Compreende as despesas realizadas sem existência de credito que as comporte, resultando em pagamento sem prévio empenho ou ainda com classificação imprópria (diferente daquela prevista no orçamento), em fase de apuração.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8821, 1, '8.9.2.7.0.00.00.00.00.00', 'CRÉDITOS ANTECIPADOS', 'Compreende os valores pagos sobre dotações decorrentes de créditos antecipados não realizados até o fechamento do exercício, em fase de apuração.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8847, 1, '1.1.2.9.2.02.00.00.00.00', '(-) PERDAS ESTIMADAS EM CLIENTE', 'Compreende o ajuste para perdas estimadas com o não recebimento das faturas/duplicatas a receber decorrentes de vendas de mercadorias ou da prestação de serviços.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8822, 1, '8.9.2.8.0.00.00.00.00.00', 'FALTA OU IRREGULARIDADE DE COMPROVAÇÃO', 'Compreende os valores correspondentes à falta de documentação comprobatória da execução da despesa, inclusive as apresentações fora do prazo legal, bem como a inadimplência na comprovação de instrumentos de transferência ou ainda irregularidade na documentação, em fase de apuração.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8823, 1, '8.9.2.9.1.01.00.00.00.00', 'FALTA DE LICITAÇÃO', 'Registra os valores relativos a bens e serviços adquiridos sem a necessária licitação, infringindo a legislação especifica, em processos motivados, por determinações administrativas e ou inquéritos, em fase de apuração.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8824, 1, '8.9.2.9.1.02.00.00.00.00', 'FALTA DE RECOLHIMENTO DE OBRIGAÇÕES PECUNIÁRIAS', 'Registra os valores correspondentes a falta de recolhimento ou pagamento de obrigações pecuniárias, tais como: parte do empregador de obrigações patronais, valores descontados de terceiros e não recolhidos, não pagamento de obrigações para com a União.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8825, 1, '8.9.2.9.1.04.00.00.00.00', 'DÉBITOS ORIUNDOS DE USO OU ALUGUEL DE IMOVEL', 'Registra os débitos oriundos de uso ou aluguel de imóveis.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8826, 1, '8.9.2.9.1.05.00.00.00.00', 'ADIANTAMENTOS CONCEDIDOS IRREGULARMENTE', 'Registra os adiantamentos concedidos irregularmente.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8827, 1, '8.9.3.1.1.00.00.00.00.00', 'AQUISIÇÃO FINANCIADA DE BENS E ARRENDAMENTO MERCANTIL FINANCEIRO', 'Registra os compromissos financeiros assumidos em razão de financiamentos, como  a aquisição financiada de bens, o arrendamento mercantil financeiro e outras operações assemelhadas nas quais a Administração Pública seja a contratante. Caso o ente tenha optado pelo registro de receita de capital no momento da aquisição, a operação não deve ser contabilizada nesta conta de controle, uma vez que integrará a linha de "Empréstimos" no demonstrativo.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8828, 1, '8.9.3.1.2.00.00.00.00.00', 'ANTECIPAÇÃO DE RECEITA PELA VENDA A TERMO DE BENS E SERVIÇOS', 'Registra as antecipações recebidas por operações de fornecimento de bens ou prestação de serviços e que ensejem a devolução da quantia recebida, caso a operação não ocorra, nos termos do art. 29, inciso III da LC 101/2000.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8829, 1, '8.9.3.1.3.00.00.00.00.00', 'ASSUNÇÃO, RECONHECIMENTO E CONFISSÃO DE DÍVIDAS (LRF, ART. 29, § 1º)', 'Registra as operações equiparadas a operações de crédito pelo art. 29 §1º da LC nº 101/2000', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8830, 1, '8.9.3.2.1.00.00.00.00.00', 'AQUISIÇÃO FINANCIADA DE BENS E ARRENDAMENTO MERCANTIL FINANCEIRO', 'Registra os compromissos financeiros assumidos em razão de financiamentos, como  a aquisição financiada de bens, o arrendamento mercantil financeiro e outras operações assemelhadas nas quais a Administração Pública seja a contratante. Caso o ente tenha optado pelo registro de receita de capital no momento da aquisição, a operação não deve ser contabilizada nesta conta de controle, uma vez que integrará a linha de "Empréstimos" no demonstrativo.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8831, 1, '8.9.3.2.2.00.00.00.00.00', 'ANTECIPAÇÃO DE RECEITA PELA VENDA A TERMO DE BENS E SERVIÇOS', 'Registra as antecipações recebidas por operações de fornecimento de bens ou prestação de serviços e que ensejem a devolução da quantia recebida, caso a operação não ocorra, nos termos do art. 29, inciso III da LC 101/2000.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8832, 1, '8.9.3.2.3.00.00.00.00.00', 'ASSUNÇÃO, RECONHECIMENTO E CONFISSÃO DE DÍVIDAS (LRF, ART. 29, § 1º)', 'Registra as operações equiparadas a operações de crédito pelo art. 29 §1º da LC nº 101/2000', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8833, 1, '8.9.3.3.1.01.00.00.00.00', 'TRIBUTOS', 'Registra os valores dos parcelamentos de tributos do ente no âmbito da SRF e PGFN.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8834, 1, '8.9.3.3.1.02.00.00.00.00', 'CONTRIBUIÇÕES  PREVIDENCIÁRIAS', 'Registra os valores dos parcelamentos de contribuições previdenciárias do ente no âmbito da SRF e do RPPS.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8835, 1, '8.9.3.3.1.03.00.00.00.00', 'FGTS', 'Registra os valores dos parcelamentos de dívidas do ente com o FGTS.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8836, 1, '8.9.4.0.0.00.00.00.00.00', 'CONTROLE DE OBRIGAÇÕES SEM AUTORIZAÇÃO ORÇAMENTÁRIA PARA FINS DA LRF', 'Compreende as contas relacionadas  ao reconhecimento de obrigações patrimoniais realizadas sem autorização orçamentária, para fins de preenchimento do Relatório de Gestão Fiscal, previsto no art. 54 da LRF.', 2, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (8837, 1, '5.2.1.1.2.00.00.00.00.00', '(-) PREVISÃO DE DEDUÇÕES DA RECEITA', 'Registra a previsão de deduções da receita bruta aprovada na LOA.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8838, 1, '1.1.2.9.2.01.00.00.00.00', '(-) PERDAS ESTIMADAS EM CRÉDITOS TRIBUTÁRIOS A RECEBER', 'Compreende o ajuste para perdas estimadas com o não recebimento dos créditos tributários', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8839, 1, '1.1.2.9.2.04.00.00.00.00', '(-) PERDAS ESTIMADAS EM CRÉDITOS DE DÍVIDA ATIVA TRIBUTÁRIA', 'Compreende o ajuste para perdas estimadas com o não recebimento dos créditos inscritos em dívida ativa tributária.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8840, 1, '1.1.2.9.0.00.00.00.00.00', '(-) AJUSTE DE PERDAS DE CRÉDITOS A CURTO PRAZO', 'Compreende o ajuste para perdas estimadas com o não recebimento de valores referentes a créditos a curto prazo, por inadimplência de terceiros e outras.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8841, 1, '1.1.2.9.1.00.00.00.00.00', '(-) AJUSTE DE PERDAS DE CRÉDITOS A CURTO PRAZO - CONSOLIDAÇÃO', 'Compreende o ajuste para perdas estimadas com o não recebimento de valores referentes a créditos a curto prazo, por inadimplência de terceiros e outras. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8842, 1, '1.1.2.9.1.01.00.00.00.00', '(-) PERDAS ESTIMADAS EM CRÉDITOS TRIBUTÁRIOS A RECEBER', 'Compreende o ajuste para perdas estimadas com o não recebimento dos créditos tributários', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8843, 1, '1.1.2.9.1.02.00.00.00.00', '(-) PERDAS ESTIMADAS EM CLIENTE', 'Compreende o ajuste para perdas estimadas com o não recebimento das faturas/duplicatas a receber decorrentes de vendas de mercadorias ou da prestação de serviços.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8844, 1, '1.1.2.9.1.03.00.00.00.00', '(-) PERDAS ESTIMADAS EM CRÉDITOS DE EMPRÉSTIMOS E FINANCIAMENTOS CONCEDIDOS', 'Compreende o ajuste para perdas estimadas com o não recebimento de créditos de empréstimos e financiamentos concedidos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8845, 1, '1.1.2.9.1.04.00.00.00.00', '(-) PERDAS ESTIMADAS EM CRÉDITOS DE DÍVIDA ATIVA TRIBUTÁRIA', 'Compreende o ajuste para perdas estimadas com o não recebimento dos créditos inscritos em dívida ativa tributária.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8846, 1, '1.1.2.9.2.00.00.00.00.00', '(-) AJUSTE DE PERDAS DE CRÉDITOS A CURTO PRAZO - INTRA OFSS', 'Compreende o ajuste para perdas estimadas com o não recebimento de valores referentes a créditos a curto prazo, por inadimplência de terceiros e outras. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do ente.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8848, 1, '1.1.2.9.2.03.00.00.00.00', '(-) PERDAS ESTIMADAS EM CRÉDITOS DE EMPRÉSTIMOS E FINANCIAMENTOS CONCEDIDOS', 'Compreende o ajuste para perdas estimadas com o não recebimento de créditos de empréstimos e financiamentos concedidos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8849, 1, '1.1.2.9.3.00.00.00.00.00', '(-) AJUSTE DE PERDAS DE CRÉDITOS A CURTO PRAZO - INTER OFSS - UNIÃO', 'Compreende o ajuste para perdas estimadas com o não recebimento de valores referentes a créditos a curto prazo, por inadimplência de terceiros e outras. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8850, 1, '1.1.2.9.3.01.00.00.00.00', '(-) PERDAS ESTIMADAS EM CRÉDITOS TRIBUTÁRIOS A RECEBER', 'Compreende o ajuste para perdas estimadas com o não recebimento dos créditos tributários', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8851, 1, '1.1.2.9.3.02.00.00.00.00', '(-) PERDAS ESTIMADAS EM CLIENTE', 'Compreende o ajuste para perdas estimadas com o não recebimento das faturas/duplicatas a receber decorrentes de vendas de mercadorias ou da prestação de serviços.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8852, 1, '1.1.2.9.3.03.00.00.00.00', '(-) PERDAS ESTIMADAS EM CRÉDITOS DE EMPRÉSTIMOS E FINANCIAMENTOS CONCEDIDOS', 'Compreende o ajuste para perdas estimadas com o não recebimento de créditos de empréstimos e financiamentos concedidos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8853, 1, '1.1.2.9.3.04.00.00.00.00', '(-) PERDAS ESTIMADAS EM CRÉDITOS DE DÍVIDA ATIVA TRIBUTÁRIA', 'Compreende o ajuste para perdas estimadas com o não recebimento dos créditos inscritos em dívida ativa tributária.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8854, 1, '1.1.2.9.4.00.00.00.00.00', '(-) AJUSTE DE PERDAS DE CRÉDITOS A CURTO PRAZO - INTER OFSS - ESTADO', 'Compreende o ajuste para perdas estimadas com o não recebimento de valores referentes a créditos a curto prazo, por inadimplência de terceiros e outras. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8855, 1, '1.1.2.9.4.01.00.00.00.00', '(-) PERDAS ESTIMADAS EM CRÉDITOS TRIBUTÁRIOS A RECEBER', 'Compreende o ajuste para perdas estimadas com o não recebimento dos créditos tributários', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8856, 1, '4.2.1.9.0.00.00.00.00.00', 'OUTRAS CONTRIBUIÇÕES SOCIAIS', 'Compreende o valor de outras contribuições sociais, não classificadas em itens específicos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8857, 1, '1.1.2.9.4.02.00.00.00.00', '(-) PERDAS ESTIMADAS EM CLIENTE', 'Compreende o ajuste para perdas estimadas com o não recebimento das faturas/duplicatas a receber decorrentes de vendas de mercadorias ou da prestação de serviços.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8858, 1, '1.1.2.9.4.03.00.00.00.00', '(-) PERDAS ESTIMADAS EM CRÉDITOS DE EMPRÉSTIMOS E FINANCIAMENTOS CONCEDIDOS', 'Compreende o ajuste para perdas estimadas com o não recebimento de créditos de empréstimos e financiamentos concedidos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8859, 1, '1.1.2.9.4.04.00.00.00.00', '(-) PERDAS ESTIMADAS EM CRÉDITOS DE DÍVIDA ATIVA TRIBUTÁRIA', 'Compreende o ajuste para perdas estimadas com o não recebimento dos créditos inscritos em dívida ativa tributária.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8860, 1, '1.1.2.9.5.00.00.00.00.00', '(-) AJUSTE DE PERDAS DE CRÉDITOS A CURTO PRAZO - INTER OFSS - MUNICÍPIO', 'Compreende o ajuste para perdas estimadas com o não recebimento de valores referentes a créditos a curto prazo, por inadimplência de terceiros e outras. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8861, 1, '1.1.2.9.5.01.00.00.00.00', '(-) PERDAS ESTIMADAS EM CRÉDITOS TRIBUTÁRIOS A RECEBER', 'Compreende o ajuste para perdas estimadas com o não recebimento dos créditos tributários', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8862, 1, '1.1.2.9.5.02.00.00.00.00', '(-) PERDAS ESTIMADAS EM CLIENTE', 'Compreende o ajuste para perdas estimadas com o não recebimento das faturas/duplicatas a receber decorrentes de vendas de mercadorias ou da prestação de serviços.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8863, 1, '1.1.2.9.5.03.00.00.00.00', '(-) PERDAS ESTIMADAS EM CRÉDITOS DE EMPRÉSTIMOS E FINANCIAMENTOS CONCEDIDOS', 'Compreende o ajuste para perdas estimadas com o não recebimento de créditos de empréstimos e financiamentos concedidos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8864, 1, '1.1.2.9.5.04.00.00.00.00', '(-) PERDAS ESTIMADAS EM CRÉDITOS DE DÍVIDA ATIVA TRIBUTÁRIA', 'Compreende o ajuste para perdas estimadas com o não recebimento dos créditos inscritos em dívida ativa tributária.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8865, 1, '1.1.3.9.0.00.00.00.00.00', '(-) AJUSTE DE PERDAS DE DEMAIS CRÉDITOS E VALORES A CURTO PRAZO', 'Compreende o ajuste de perdas estimadas com o não recebimento de valores referentes a demais créditos e valores a curto prazo, por inadimplência de terceiros e outras.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8866, 1, '1.1.3.9.1.00.00.00.00.00', '(-) AJUSTE DE PERDAS DE DEMAIS CRÉDITOS E VALORES A CURTO PRAZO - CONSOLIDAÇÃO', 'Compreende o ajuste de perdas estimadas com o não recebimento de valores referentes a demais créditos e valores a curto prazo, por inadimplência de terceiros e outras. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8867, 1, '1.1.3.9.1.04.00.00.00.00', '(-) AJUSTE  PARA PERDAS EM CRÉDITOS POR DANOS AO PATRIMÔNIO', 'Compreende os valores das provisões para perdas de créditos por danos ao patrimônio, verificados em processos administrativos ou apurados em Tomada de Contas Especial.', 2, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (8868, 1, '1.1.4.9.0.00.00.00.00.00', '(-) AJUSTE DE PERDAS DE INVESTIMENTOS E APLICAÇÕES TEMPORÁRIAS', 'Compreende a diferença entre o valor recuperável do ativo e seu valor contábil, quando o primeiro for menor.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8869, 1, '1.1.4.9.1.00.00.00.00.00', '(-) AJUSTE DE PERDAS DE INVESTIMENTOS E APLICAÇÕES TEMPORÁRIAS - CONSOLIDAÇÃO', 'Compreende os ajustes de perdas estimadas e redução a valor recuperável de investimentos e aplicações temporárias. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8870, 1, '2.1.2.1.3.05.00.00.00.00', 'PROGRAMA DE APOIO À REESTRUTURAÇÃO E AO AJUSTE FISCAL DOS MUNICÍPIOS', 'Compreende a obrigação decorrente da assunção e do refinanciamento, pela União, da dívida pública de Municípios, nos termos da MP nº 2.185-35, de 24 de agosto de 2001.', 2, false, 0, 'X');
insert into contabilidade.planocontadetalhe values (8871, 1, '1.1.5.9.0.00.00.00.00.00', '(-) AJUSTE DE PERDAS DE ESTOQUES', 'Compreende o registro das perdas conhecidas em estoques e calculadas por estimativa, relativas a estoques deteriorados ou obsoletos e para dar cobertura a diferenças físicas, quando tais perdas não puderem ser baixadas das próprias contas, pelo fato de não estarem identificados os itens específicos e por constituírem estimativas, bem como o registro do ajuste  de perdas para os estoque que tiverem o valor de mercado inferior ao seu custo.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8872, 1, '1.1.5.9.1.00.00.00.00.00', '(-) AJUSTE DE PERDAS DE ESTOQUES - CONSOLIDAÇÃO', 'Compreende o registro das perdas conhecidas em estoques e calculadas por estimativa, relativas a estoques deteriorados ou obsoletos e para dar cobertura a diferenças físicas, quando tais perdas não puderem ser baixadas das próprias contas, pelo fato de não estarem identificados os itens específicos e por constituírem estimativas, bem como o registro do ajuste  de perdas para os estoque que tiverem o valor de mercado inferior ao seu custo. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8873, 1, '1.1.6.9.0.00.00.00.00.00', '(-) REDUÇÃO A VALOR RECUPERÁVEL DE ATIVOS MANTIDOS PARA VENDA', 'Compreende os valores lançados a título de redução a valor recuperável de ativos mantidos para venda, segundo um plano de venda com prazo inferior a doze meses.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8874, 1, '1.1.6.9.1.00.00.00.00.00', '(-) REDUÇÃO A VALOR RECUPERÁVEL DE ATIVOS MANTIDOS PARA VENDA - CONSOLIDAÇÃO', 'Compreende os valores lançados a título de redução a valor recuperável de ativos mantidos para venda, segundo um plano de venda com prazo inferior a doze meses. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (8875, 1, '1.1.6.9.2.00.00.00.00.00', '(-) REDUÇÃO A VALOR RECUPERÁVEL DE ATIVOS MANTIDOS PARA VENDA - INTRA OFSS', 'Compreende os valores lançados a título de redução a valor recuperável de ativos mantidos para venda, segundo um plano de venda com prazo inferior a doze meses. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do ente.', 2, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (8876, 1, '1.1.6.9.3.00.00.00.00.00', '(-) REDUÇÃO A VALOR RECUPERÁVEL DE ATIVOS MANTIDOS PARA VENDA - INTER OFSS - UNIÃO', 'Compreende os valores lançados a título de redução a valor recuperável de ativos mantidos para venda, segundo um plano de venda com prazo inferior a doze meses. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 2, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (8877, 1, '1.1.6.9.4.00.00.00.00.00', '(-) REDUÇÃO A VALOR RECUPERÁVEL DE ATIVOS MANTIDOS PARA VENDA - INTER OFSS - ESTADO', 'Compreende os valores lançados a título de redução a valor recuperável de ativos mantidos para venda, segundo um plano de venda com prazo inferior a doze meses. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 2, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (8878, 1, '1.1.6.9.5.00.00.00.00.00', '(-) REDUÇÃO A VALOR RECUPERÁVEL DE ATIVOS MANTIDOS PARA VENDA - INTER OFSS - MUNICÍPIO', 'Compreende os valores lançados a título de redução a valor recuperável de ativos mantidos para venda, segundo um plano de venda com prazo inferior a doze meses. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 2, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (8879, 1, '2.1.1.1.1.01.00.00.00.00', 'PESSOAL A PAGAR', 'Compreende as obrigações referentes a salários ou remunerações, bem como benefícios aos quais o empregado ou servidor tenha direito.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8880, 1, '1.2.1.1.1.99.00.00.00.00', '(-) AJUSTE DE PERDAS DE CRÉDITOS A LONGO PRAZO', 'Compreende o ajuste de perdas estimadas com o não recebimento de valores referentes a créditos a longo prazo, por inadimplência de terceiros e outras.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8881, 1, '1.2.1.2.1.99.00.00.00.00', '(-) AJUSTE DE PERDAS DE DEMAIS CRÉDITOS E VALORES A LONGO PRAZO', 'Compreende o ajuste de perdas estimadas com o não recebimento de valores referentes a demais créditos a longo prazo, por inadimplência de terceiros e outras.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8882, 1, '1.2.1.3.1.99.00.00.00.00', '(-) AJUSTE DE PERDAS DE INVESTIMENTOS E APLICAÇÕES TEMPORÁRIAS A LONGO PRAZO', 'Compreende a diferença entre o valor recuperável do ativo e seu valor contábil, quando o primeiro for menor.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8883, 1, '1.2.2.8.0.00.00.00.00.00', '(-) DEPRECIAÇÃO ACUMULADA DE INVESTIMENTOS', 'Compreende a diminuição do valor dos elementos do ativo investimento devido a desgaste pelo uso, ação da natureza ou obsolescência, quando couber, como a depreciação das propriedades mantidas para investimento.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8884, 1, '1.2.2.8.1.00.00.00.00.00', '(-) DEPRECIAÇÃO ACUMULADA DE INVESTIMENTOS - CONSOLIDAÇÃO', 'Compreende a diminuição do valor dos elementos do ativo investimento devido a desgaste pelo uso, ação da natureza ou obsolescência, quando couber, como a depreciação das propriedades mantidas para investimento. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8885, 1, '1.2.2.8.1.01.00.00.00.00', '(-) DEPRECIAÇÃO ACUMULADA DE INVESTIMENTOS - CONSOLIDAÇÃO - PROPRIEDADES PARA INVESTIMENTO', 'Compreende a diminuição do valor dos elementos do ativo investimento devido a desgaste pelo uso, ação da natureza ou obsolescência, quando couber, das propriedades mantidas para investimento.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8886, 1, '1.2.2.9.0.00.00.00.00.00', '(-) REDUÇÃO AO VALOR RECUPERÁVEL DE INVESTIMENTOS', 'Compreende os valores de ajuste ao valor recuperável de investimentos, quando esse for inferior ao valor liquido contábil.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8887, 1, '1.2.2.9.1.00.00.00.00.00', '(-) REDUÇÃO AO VALOR RECUPERÁVEL DE INVESTIMENTOS - CONSOLIDAÇÃO', 'Compreende os valores de ajuste ao valor recuperável de investimentos, quando esse for inferior ao valor liquido contábil. . Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8888, 1, '1.2.2.9.1.01.00.00.00.00', '(-) REDUÇÃO AO VALOR RECUPERÁVEL DE INVESTIMENTOS - PARTICIPAÇÕES PERMANENTES', 'Compreende os valores de ajuste ao valor recuperável de participações permanentes, quando esse for inferior ao valor liquido contábil.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8889, 1, '1.2.2.9.1.02.00.00.00.00', '(-) REDUÇÃO AO VALOR RECUPERÁVEL DE PROPRIEDADES PARA INVESTIMENTO', 'Compreende os valores de ajuste ao valor recuperável de propriedades para investimento, quando esse for inferior ao valor liquido contábil.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8890, 1, '1.2.2.9.2.00.00.00.00.00', '(-) REDUÇÃO AO VALOR RECUPERÁVEL DE INVESTIMENTOS-INTRA OFSS', 'Compreende os valores de ajuste ao valor recuperável de investimentos, quando esse for inferior ao valor liquido contábil. . Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do ente.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8910, 1, '2.1.4.1.0.00.00.00.00.00', 'OBRIGAÇÕES FISCAIS A CURTO PRAZO COM A UNIÃO', 'Compreende as obrigações das entidades com o governo federal relativas a impostos, taxas e contribuições, com vencimento no curto prazo.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8891, 1, '1.2.2.9.3.00.00.00.00.00', '(-) REDUÇÃO AO VALOR RECUPERÁVEL DE INVESTIMENTOS-INTER OFSS - UNIÃO', 'Compreende os valores de ajuste ao valor recuperável de investimentos, quando esse for inferior ao valor liquido contábil. . Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8892, 1, '1.2.2.9.4.00.00.00.00.00', '(-) REDUÇÃO AO VALOR RECUPERÁVEL DE INVESTIMENTOS-INTER OFSS - ESTADO', 'Compreende os valores de ajuste ao valor recuperável de investimentos, quando esse for inferior ao valor liquido contábil. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8893, 1, '1.2.2.9.5.00.00.00.00.00', '(-) REDUÇÃO AO VALOR RECUPERÁVEL DE INVESTIMENTOS-INTER OFSS - MUNICÍPIO', 'Compreende os valores de ajuste ao valor recuperável de investimentos, quando esse for inferior ao valor liquido contábil. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8894, 1, '1.2.3.8.0.00.00.00.00.00', '(-) DEPRECIAÇÃO, EXAUSTÃO E AMORTIZAÇÃO ACUMULADAS', 'Compreende a diminuição do valor dos elementos do ativo imobilizado devido a desgaste pelo uso, ação da natureza ou obsolescência, bem como a perda do valor, decorrente de sua exploração, de direitos cujo objeto sejam recursos minerais ou florestais ou bens aplicados nessa exploração e a perda do valor do capital aplicado na aquisição de direitos de propriedade industrial ou comercial e quaisquer outros com existência ou exercício de duração limitada ou cujo objeto sejam bens de utilização por prazo legal ou contratualmente limitado.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8895, 1, '1.2.3.8.1.00.00.00.00.00', '(-) DEPRECIAÇÃO, EXAUSTÃO E AMORTIZAÇÃO ACUMULADAS - CONSOLIDAÇÃO', 'Compreende a diminuição do valor dos elementos do ativo imobilizado devido a desgaste pelo uso, ação da natureza ou obsolescência, bem como a perda do valor, decorrente de sua exploração, de direitos cujo objeto sejam recursos minerais ou florestais ou bens aplicados nessa exploração e a perda do valor do capital aplicado na aquisição de direitos de propriedade industrial ou comercial e quaisquer outros com existência ou exercício de duração limitada ou cujo objeto sejam bens de utilização por prazo legal ou contratualmente limitado. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8896, 1, '1.2.3.8.1.01.00.00.00.00', '(-) DEPRECIAÇÃO ACUMULADA - BENS MÓVEIS', 'Compreende a diminuição do valor dos elementos do ativo imobilizado, bens móveis, devido a desgaste pelo uso, ação da natureza ou obsolescência.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8897, 1, '1.2.3.8.1.02.00.00.00.00', '(-) DEPRECIAÇÃO ACUMULADA - BENS IMÓVEIS', 'Compreende a diminuição do valor dos elementos do ativo imobilizado, bens imóveis, devido a desgaste pelo uso, ação da natureza ou obsolescência.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8898, 1, '1.2.3.9.0.00.00.00.00.00', '(-) REDUÇÃO AO VALOR RECUPERÁVEL DE IMOBILIZADO', 'Compreende os valores de ajuste ao valor recuperável do imobilizado, quando esse for inferior ao valor liquido contábil.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8899, 1, '1.2.3.9.1.00.00.00.00.00', '(-) REDUÇÃO AO VALOR RECUPERÁVEL DE IMOBILIZADO - CONSOLIDAÇÃO', 'Compreende os valores de ajuste ao valor recuperável do imobilizado, quando esse for inferior ao valor liquido contábil. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8900, 1, '1.2.3.9.1.01.00.00.00.00', '(-) REDUÇÃO AO VALOR RECUPERÁVEL DE IMOBILIZADO - BENS MOVEIS', 'Compreende os valores de ajuste ao valor recuperável de bens moveis, quando esse for inferior ao valor liquido contábil.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8901, 1, '1.2.3.9.1.02.00.00.00.00', '(-) REDUÇÃO AO VALOR RECUPERÁVEL DE IMOBILIZADO - BENS IMÓVEIS', 'Compreende os valores de ajuste ao valor recuperável de bens imóveis, quando esse for inferior ao valor liquido contábil.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8902, 1, '1.2.4.8.0.00.00.00.00.00', '(-) AMORTIZAÇÃO ACUMULADA', 'Compreende a diminuição do valor do capital aplicado na aquisição de direitos da propriedade industrial ou comercial e quaisquer outros com existência ou exercício de duração limitada, ou cujo objeto sejam bens de utilização por prazo legal ou contratualmente limitado.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8903, 1, '1.2.4.8.1.00.00.00.00.00', '(-) AMORTIZAÇÃO ACUMULADA- CONSOLIDAÇÃO', 'Compreende a diminuição do valor do capital aplicado na aquisição de direitos da propriedade industrial ou comercial e quaisquer outros com existência ou exercício de duração limitada, ou cujo objeto sejam bens de utilização por prazo legal ou contratualmente limitado. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8904, 1, '1.2.4.9.0.00.00.00.00.00', '(-) REDUÇÃO AO VALOR RECUPERÁVEL DE INTANGÍVEL', 'Compreende os valores de ajuste ao valor recuperável do ativo intangível, quando esse for inferior ao valor liquido contábil.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8905, 1, '1.2.4.9.1.00.00.00.00.00', '(-) REDUÇÃO AO VALOR RECUPERÁVEL DE INTANGÍVEL - CONSOLIDAÇÃO', 'Compreende os valores de ajuste ao valor recuperável do ativo intangível, quando esse for inferior ao valor liquido contábil. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8906, 1, '1.2.5.9.0.00.00.00.00.00', '(-) AMORTIZAÇÃO ACUMULADA', 'Compreende a perda do valor do capital aplicado em despesas pré-operacionais e gastos de reestruturação. ', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8907, 1, '1.2.5.9.1.00.00.00.00.00', '(-) AMORTIZAÇÃO ACUMULADA - CONSOLIDAÇÃO', 'Compreende a perda do valor do capital aplicado em despesas pré-operacionais e gastos de reestruturação. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8908, 1, '2.0.0.0.0.00.00.00.00.00', 'PASSIVO E PATRIMÔNIO LIQUIDO', 'Passivo compreende as obrigações existentes da entidade oriundas de eventos passados de cuja liquidação se espera que resulte em fluxo de saída de recursos que incorporem benefícios econômicos ou serviços em potencial. Patrimônio liquido compreende a diferença entre o ativo e o passivo.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8909, 1, '2.1.0.0.0.00.00.00.00.00', 'PASSIVO CIRCULANTE', 'Compreende as obrigações conhecidas e estimadas que atendam a qualquer um dos seguintes critérios: tenham prazos estabelecidos ou esperados dentro do ciclo operacional da entidade; sejam mantidos primariamente para negociação; tenham prazos estabelecidos ou esperados no curto prazo; sejam valores de terceiros ou retenções em nome deles, quando a entidade do setor público for fiel depositaria, independentemente do prazo de exigibilidade.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8911, 1, '2.1.1.0.0.00.00.00.00.00', 'OBRIGAÇÕES TRABALHISTAS, PREVIDENCIÁRIAS E ASSISTENCIAIS A PAGAR A CURTO PRAZO', 'Compreende as obrigações referentes a salários ou remunerações, bem como benefícios aos quais o empregado ou servidor tenha direito, aposentadorias, reformas, pensões e encargos a pagar, benefícios assistenciais, inclusive os precatórios decorrentes dessas obrigações , com vencimento no curto prazo.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8912, 1, '2.1.1.1.0.00.00.00.00.00', 'PESSOAL A PAGAR', 'Compreende as obrigações a curto prazo referentes a salários ou remunerações, bem como benefícios aos quais o empregado ou servidor tenha direito, quando pagos em data posterior a qual forem incorridos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8913, 1, '2.1.1.1.1.00.00.00.00.00', 'PESSOAL A PAGAR - CONSOLIDAÇÃO', 'Compreende as obrigações referentes a salários ou remunerações, bem como benefícios aos quais o empregado ou servidor tenha direito, quando pagos em data posterior a qual forem incorridos. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8914, 1, '2.1.1.1.1.04.00.00.00.00', 'PRECATÓRIOS DE PESSOAL - REGIME ESPECIAL', 'Compreende as obrigações referentes a precatórios de salários ou remunerações, bem como a benefícios aos quais o empregado ou servidor tenha direito, sujeitos ao regime especial instituído pela emenda constitucional 62/ 2009.', 2, false, 0, 'X');
insert into contabilidade.planocontadetalhe values (8915, 1, '2.1.1.1.1.05.00.00.00.00', 'PRECATÓRIOS DE PESSOAL - REGIME ORDINÁRIO', 'Compreende as obrigações referentes a precatórios de proventos de aposentadoria, reformas ou pensões,  não sujeitos ao regime especial instituído pela emenda constitucional 62/ 2009.', 2, false, 0, 'X');
insert into contabilidade.planocontadetalhe values (8916, 1, '2.1.1.2.0.00.00.00.00.00', 'BENEFÍCIOS PREVIDENCIÁRIOS A PAGAR', 'Compreende as obrigações a curto prazo referentes a proventos de aposentadoria, reformas ou pensões aos quais o aposentado, reformado ou pensionista tenha direito, quando pagos em data posterior a qual forem incorridos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8917, 1, '2.1.1.2.1.00.00.00.00.00', 'BENEFÍCIOS PREVIDENCIÁRIOS A PAGAR- CONSOLIDAÇÃO', 'Compreende as obrigações referentes a proventos de aposentadoria, reformas ou pensões aos quais o aposentado, reformado ou pensionista tenha direito, quando pagos em data posterior a qual forem incorridos. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8918, 1, '2.1.1.2.1.04.00.00.00.00', 'PRECATÓRIOS DE BENEFÍCIOS PREVIDENCIÁRIOS - REGIME ESPECIAL', 'Compreende as obrigações referentes a precatórios de proventos de aposentadoria, reformas ou pensões, sujeitos ao regime especial instituído pela emenda constitucional 62/ 2009.', 2, false, 0, 'X');
insert into contabilidade.planocontadetalhe values (8919, 1, '2.1.1.2.1.05.00.00.00.00', 'PRECATÓRIOS DE BENEFÍCIOS PREVIDENCIÁRIOS - REGIME ORDINÁRIO', 'Compreende as obrigações referentes a precatórios de proventos de aposentadoria, reformas ou pensões,  não sujeitos ao regime especial instituído pela emenda constitucional 62/ 2009.', 2, false, 0, 'X');
insert into contabilidade.planocontadetalhe values (8920, 1, '2.1.1.2.2.00.00.00.00.00', 'BENEFÍCIOS PREVIDENCIÁRIOS A PAGAR- INTRA OFSS', 'Compreende as obrigações referentes a proventos de aposentadoria, reformas ou pensões aos quais o aposentado, reformado ou pensionista tenha direito, quando pagos em data posterior a qual forem incorridos.Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) do mesmo ente.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8921, 1, '2.1.1.2.2.05.00.00.00.00', 'COMPENSAÇÃO FINANCEIRA ENTRE REGIMES PREVIDENCIÁRIOS', 'Compreende os valores relativos a obrigações a pagar decorrentes de compensação financeira entre RGPS e RPPS, por contagem recíproca de tempo de contribuição.', 2, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (8922, 1, '2.1.1.2.3.00.00.00.00.00', 'BENEFÍCIOS PREVIDENCIÁRIOS A PAGAR-INTER OFSS - UNIÃO', 'Compreende as obrigações referentes a proventos de aposentadoria, reformas ou pensões aos quais o aposentado, reformado ou pensionista tenha direito, quando pagos em data posterior a qual forem incorridos.Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8923, 1, '2.1.1.2.3.05.00.00.00.00', 'COMPENSAÇÃO FINANCEIRA ENTRE REGIMES PREVIDENCIÁRIOS', 'Compreende os valores relativos a obrigações a pagar decorrentes de compensação financeira entre RGPS e RPPS, por contagem recíproca de tempo de contribuição.', 2, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (8924, 1, '2.1.1.2.4.00.00.00.00.00', 'BENEFÍCIOS PREVIDENCIÁRIOS A PAGAR- INTER OFSS - ESTADO', 'Compreende as obrigações referentes a proventos de aposentadoria, reformas ou pensões aos quais o aposentado, reformado ou pensionista tenha direito, quando pagos em data posterior a qual forem incorridos. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um Estado.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8925, 1, '2.1.1.2.4.05.00.00.00.00', 'COMPENSAÇÃO FINANCEIRA ENTRE REGIMES PREVIDENCIÁRIOS', 'Compreende os valores relativos às obrigações a pagar decorrentes de compensação financeira entre RGPS e RPPS, por contagem recíproca de tempo de contribuição.', 2, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (8926, 1, '2.1.1.2.5.00.00.00.00.00', 'BENEFÍCIOS PREVIDENCIÁRIOS A PAGAR- INTER OFSS - MUNICÍPIO', 'Compreende as obrigações referentes a proventos de aposentadoria, reformas ou pensões aos quais o aposentado, reformado ou pensionista tenha direito, quando pagos em data posterior a qual forem incorridos.Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um Município.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8927, 1, '2.1.1.2.5.05.00.00.00.00', 'COMPENSAÇÃO FINANCEIRA ENTRE REGIMES PREVIDENCIÁRIOS', 'Compreende os valores relativos às obrigações a pagar decorrentes de compensação financeira entre RGPS e RPPS, por contagem recíproca de tempo de contribuição.', 2, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (8928, 1, '2.1.1.3.0.00.00.00.00.00', 'BENEFÍCIOS ASSISTENCIAIS A PAGAR', 'Compreende as obrigações a curto prazo relativas aos benefícios assistenciais administrados pela previdência social, quando pagos em data posterior a qual forem incorridos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8929, 1, '2.1.1.3.1.00.00.00.00.00', 'BENEFÍCIOS ASSISTENCIAIS A PAGAR - CONSOLIDAÇÃO', 'Compreende as obrigações relativas aos benefícios assistenciais, quando pagos em data posterior a qual forem incorridos. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8930, 1, '2.1.1.3.1.03.00.00.00.00', 'PRECATÓRIOS DE BENEFÍCIOS ASSISTENCIAIS - REGIME ESPECIAL', 'Compreende as obrigações referentes a precatórios de benefícios assistenciais, sujeitos ao regime especial instituído pela emenda constitucional 62/ 2009.', 2, false, 0, 'X');
insert into contabilidade.planocontadetalhe values (9327, 1, '6.2.2.1.3.00.00.00.00.00', 'CREDITO UTILIZADO', 'Compreende o somatório dos valores referentes aos créditos orçamentários empenhados.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8931, 1, '2.1.1.3.1.04.00.00.00.00', 'PRECATÓRIOS DE BENEFÍCIOS ASSISTENCIAIS - REGIME ORDINÁRIO', 'Compreende as obrigações referentes a precatórios de benefícios assistenciais,  não sujeitos ao regime especial instituído pela emenda constitucional 62/ 2009.', 2, false, 0, 'X');
insert into contabilidade.planocontadetalhe values (8932, 1, '2.1.7.9.0.00.00.00.00.00', 'OUTRAS PROVISÕES A CURTO PRAZO', 'Compreende os demais passivos de prazo ou de valor incertos, com probabilidade de ocorrerem no curto prazo, não classificadas anteriormente neste plano de contas.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8933, 1, '2.1.1.4.0.00.00.00.00.00', 'ENCARGOS SOCIAIS A PAGAR', 'Compreende as obrigações a curto prazo das unidades relativas a despesas incorridas e não pagas, em beneficio de seus servidores, empregados e familiares, compulsoriamente ou não, incluindo aquelas que se destinam ao financiamento da seguridade social de responsabilidade do poder público e as demais contribuições sociais.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8934, 1, '2.1.1.4.1.00.00.00.00.00', 'ENCARGOS SOCIAIS A PAGAR-CONSOLIDAÇÃO', 'Compreende as obrigações das unidades relativas a despesas incorridas e não pagas, em beneficio de seus servidores, empregados e familiares, compulsoriamente ou não, incluindo aquelas que se destinam ao financiamento da seguridade social de responsabilidade do poder público e as demais contribuições sociais. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8935, 1, '2.1.1.4.1.01.00.00.00.00', 'CONTRIBUIÇÕES AO RGPS A PAGAR', 'Registra os valores relativos as contribuições a previdência social, incidentes sobre salários e remunerações pagos e sobre serviços de terceiros.', 2, false, 0, 'X');
