insert into contabilidade.planocontadetalhe values (8937, 1, '2.1.1.4.3.00.00.00.00.00', 'ENCARGOS SOCIAIS A PAGAR-INTER OFSS - UNIÃO', 'Compreende as obrigações das unidades relativas a despesas incorridas e não pagas, em beneficio de seus servidores, empregados e familiares, compulsoriamente ou não, incluindo aquelas que se destinam ao financiamento da seguridade social de responsabilidade do poder público e as demais contribuições sociais. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 2, false, 0, 'N');
