insert into contabilidade.planocontadetalhe values (8944, 1, '2.1.2.0.0.00.00.00.00.00', 'EMPRÉSTIMOS E FINANCIAMENTOS A CURTO PRAZO', 'Compreende as obrigações financeiras externas e internas da entidade a titulo de empréstimos, bem como as aquisições efetuadas diretamente com o fornecedor, com vencimentos no curto prazo.', 2, false, 0, 'N');
