insert into contabilidade.planocontadetalhe values (8947, 1, '2.1.2.1.1.01.00.00.00.00', 'EMPRÉSTIMOS INTERNOS - EM TÍTULOS', 'Compreende os valores das operações de créditos internas decorrentes da emissão de titulos.', 2, false, 0, 'N');
