insert into contabilidade.planocontadetalhe values (8978, 1, '4.4.1.2.0.00.00.00.00.00', 'JUROS E ENCARGOS DE EMPRÉSTIMOS EXTERNOS CONCEDIDOS', 'Compreende as variações patrimoniais aumentativas relativas à aplicação das taxas de juros aplicadas a empréstimos externos concedidos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8979, 1, '2.1.2.5.5.00.00.00.00.00', 'JUROS E ENCARGOS A PAGAR DE EMPRÉSTIMOS E FINANCIAMENTOS A CURTO PRAZO - INTERNO -INTER OFSS - MUNICÍPIO', 'Compreende os juros e encargos financeiros referentes a empréstimos e financiamentos, reconhecidos pelo regime de competência e pagáveis a curto prazo, assumidos dentro do país e transacionados, em regra, em moeda nacional, com vencimento no curto prazo. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 2, false, 0, 'X');
insert into contabilidade.planocontadetalhe values (8980, 1, '2.1.2.6.0.00.00.00.00.00', 'JUROS E ENCARGOS A PAGAR DE EMPRÉSTIMOS E FINANCIAMENTOS A CURTO PRAZO - EXTERNO', 'Compreende os juros e encargos financeiros referentes a empréstimos e financiamentos, reconhecidos pelo regime de competência e pagáveis a curto prazo, assumidos no exterior e transacionados, em regra, em moeda estrangeira, com vencimento no curto prazo.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8981, 1, '2.1.2.6.1.00.00.00.00.00', 'JUROS E ENCARGOS A PAGAR DE EMPRÉSTIMOS E FINANCIAMENTOS A CURTO PRAZO - EXTERNO - CONSOLIDAÇÃO', 'Compreende os juros e encargos financeiros referentes a empréstimos e financiamentos, reconhecidos pelo regime de competência e pagáveis a curto prazo, assumidos no exterior e transacionados, em regra, em moeda estrangeira, com vencimento no curto prazo. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8982, 1, '2.1.3.0.0.00.00.00.00.00', 'FORNECEDORES E CONTAS A PAGAR A CURTO PRAZO', 'Compreende as obrigações junto a fornecedores de matérias-primas, mercadorias e outros materiais utilizados nas atividades operacionais da entidade, bem como as obrigações decorrentes do fornecimento de utilidades e da prestação de serviços, tais como de energia elétrica, água, telefone, propaganda, alugueis e todas as outras contas a pagar, inclusive os precatórios decorrentes dessas obrigações, com vencimento no curto prazo.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8983, 1, '2.1.3.1.0.00.00.00.00.00', 'FORNECEDORES E CONTAS A PAGAR NACIONAIS A CURTO PRAZO', 'Compreende as obrigações junto a fornecedores nacionais de matérias-primas, mercadorias e outros materiais utilizados nas atividades operacionais da entidade, bem como as obrigações decorrentes do fornecimento de utilidades e da prestação de serviços, tais como de energia elétrica, água, telefone, propaganda, alugueis e todas as outras contas a pagar com vencimento no curto prazo.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8984, 1, '2.1.3.1.1.00.00.00.00.00', 'FORNECEDORES E CONTAS A PAGAR NACIONAIS A CURTO PRAZO - CONSOLIDAÇÃO', 'Compreende as obrigações junto a fornecedores nacionais de matérias-primas, mercadorias e outros materiais utilizados nas atividades operacionais da entidade, bem como as obrigações decorrentes do fornecimento de utilidades e da prestação de serviços, tais como de energia elétrica, água, telefone, propaganda, alugueis e todas as outras contas a pagar com vencimento no curto prazo. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8985, 1, '2.1.3.1.1.01.00.00.00.00', 'FORNECEDORES NACIONAIS', 'Compreende os valores a pagar aos fornecedores nacionais de bens, materiais e serviços envolvidos com as atividades operacionais da entidade.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8986, 1, '2.1.3.1.1.03.00.00.00.00', 'CONTAS A PAGAR CREDORES NACIONAIS', 'Compreende os valores a pagar aos credores nacionais decorrentes do fornecimento de bens/materiais e da prestação de contas.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8987, 1, '2.1.3.1.1.05.00.00.00.00', 'PRECATÓRIOS DE FORNECEDORES NACIONAIS - REGIME ESPECIAL', 'Compreende as obrigações referentes a precatórios de fornecedores nacionais, sujeitos ao regime especial instituído pela emenda constitucional 62/ 2009.', 2, false, 0, 'X');
insert into contabilidade.planocontadetalhe values (8988, 1, '2.1.3.1.1.06.00.00.00.00', 'PRECATÓRIOS DE FORNECEDORES NACIONAIS - REGIME ORDINÁRIO', 'Compreende as obrigações referentes a precatórios de fornecedores nacionais,  não sujeitos ao regime especial instituído pela emenda constitucional 62/ 2009.', 2, false, 0, 'X');
insert into contabilidade.planocontadetalhe values (8989, 1, '6.2.2.0.0.00.00.00.00.00', 'EXECUÇÃO DA DESPESA', 'Compreende o somatório da disponibilidade de credito orçamentário e da execução da despesa em suas diversas etapas.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8990, 1, '2.1.3.1.1.07.00.00.00.00', 'PRECATÓRIOS DE CONTAS A PAGAR - CREDORES NACIONAIS- REGIME ESPECIAL', 'Compreende as obrigações referentes a precatórios de contas a pagar de credores nacionais, sujeitos ao regime especial instituído pela emenda constitucional 62/ 2009.', 2, false, 0, 'X');
insert into contabilidade.planocontadetalhe values (9046, 1, '2.1.8.5.0.00.00.00.00.00', 'DIVIDENDOS E JUROS SOBRE CAPITAL PRÓPRIO A PAGAR', 'Compreende os dividendos aprovados pela assembleia geral a serem pagos aos acionistas e os valores a serem pagos a título de remuneração do capital próprio.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8991, 1, '2.1.3.1.1.08.00.00.00.00', 'PRECATÓRIOS DE CONTAS A PAGAR - CREDORES NACIONAIS - REGIME ORDINÁRIO', 'Compreende as obrigações referentes a precatórios de contas a pagar de credores nacionais,  não sujeitos ao regime especial instituído pela emenda constitucional 62/ 2009.', 2, false, 0, 'X');
insert into contabilidade.planocontadetalhe values (8992, 1, '2.1.3.2.0.00.00.00.00.00', 'FORNECEDORES E CONTAS A PAGAR ESTRANGEIROS A CURTO PRAZO', 'Compreende as obrigações junto a fornecedores estrangeiros de matérias-primas, mercadorias e outros materiais utilizados nas atividades operacionais da entidade, bem como as obrigações decorrentes do fornecimento de utilidades e da prestação de serviços, tais como de energia elétrica, água, telefone, propaganda, alugueis e todas as outras contas a pagar com vencimento no curto prazo.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8993, 1, '2.1.3.2.1.00.00.00.00.00', 'FORNECEDORES E CONTAS A PAGAR ESTRANGEIROS A CURTO PRAZO - CONSOLIDAÇÃO', 'Compreende as obrigações junto a fornecedores estrangeiros de matérias-primas, mercadorias e outros materiais utilizados nas atividades operacionais da entidade, bem como as obrigações decorrentes do fornecimento de utilidades e da prestação de serviços, tais como de energia elétrica, água, telefone, propaganda, alugueis e todas as outras contas a pagar com vencimento no curto prazo. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8994, 1, '2.1.3.2.1.01.00.00.00.00', 'FORNECEDORES ESTRANGEIROS A CURTO PRAZO', 'Compreende os valores a pagar aos fornecedores estrangeiros de bens, materiais e serviços envolvidos com as atividades operacionais da entidade.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8995, 1, '2.1.3.2.1.02.00.00.00.00', 'CONTAS A PAGAR - CREDORES ESTRANGEIROS A CURTO PRAZO', 'Compreende os valores a pagar aos credores estrangeiros decorrentes do fornecimento de bens/materiais e da prestação de contas.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8996, 1, '2.1.4.0.0.00.00.00.00.00', 'OBRIGAÇÕES FISCAIS A CURTO PRAZO', 'Compreende as obrigações das entidades com o governo relativas a impostos, taxas e contribuições com vencimento no curto prazo.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8997, 1, '2.1.4.1.1.00.00.00.00.00', 'OBRIGAÇÕES FISCAIS A CURTO PRAZO COM A UNIÃO - CONSOLIDAÇÃO', 'Compreende as obrigações das entidades com o governo federal relativas a impostos, taxas e contribuições, com vencimento no curto prazo.Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8998, 1, '2.1.4.1.2.00.00.00.00.00', 'OBRIGAÇÕES FISCAIS A CURTO PRAZO COM A UNIÃO - INTRA OFSS', 'Compreende as obrigações das entidades com o governo federal relativas a impostos, taxas e contribuições, com vencimento no curto prazo.Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do ente.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (8999, 1, '2.1.4.1.3.00.00.00.00.00', 'OBRIGAÇÕES FISCAIS A CURTO PRAZO COM A UNIÃO - INTER OFSS - UNIÃO', 'Compreende as obrigações das entidades com o governo federal relativas a impostos, taxas e contribuições, com vencimento no curto prazo.Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9000, 1, '2.1.4.2.0.00.00.00.00.00', 'OBRIGAÇÕES FISCAIS A CURTO PRAZO COM OS ESTADOS', 'Compreende as obrigações das entidades com os tributos de competência estadual com vencimento no curto prazo.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9001, 1, '2.1.4.2.1.00.00.00.00.00', 'OBRIGAÇÕES FISCAIS A CURTO PRAZO COM OS ESTADOS - CONSOLIDAÇÃO', 'Compreende as obrigações das entidades com os tributos de competência estadual com vencimento no curto prazo. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9002, 1, '2.1.7.4.0.00.00.00.00.00', 'PROVISÃO PARA RISCOS CÍVEIS A CURTO PRAZO', 'Compreende os passivos de prazo ou de valor incertos, relacionados a pagamento de indenizações a fornecedores e clientes, com probabilidade de ocorrerem no curto prazo.', 2, false, 0, 'N');
