insert into contabilidade.planocontadetalhe values (9127, 1, '2.2.3.0.0.00.00.00.00.00', 'FORNECEDORES E CONTAS A PAGAR A LONGO PRAZO', 'Compreende as obrigações junto a fornecedores de matérias-primas, mercadorias e outros materiais utilizados nas atividades operacionais da entidade,  inclusive os precatórios decorrentes dessas obrigações, com vencimento no longo prazo. Compreende também os precatórios com vencimento no longo prazo das obrigações decorrentes do fornecimento de utilidades e da prestação de serviços, tais como de energia elétrica, água, telefone, propaganda, aluguéis e todas as outras contas a pagar.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9128, 1, '5.2.1.1.2.01.00.00.00.00', '(-) DEDUÇÕES  POR TRANSFERÊNCIAS CONSTITUCIONAIS E LEGAIS', 'Registra a previsão de dedução da receita aprovada na LOA por transferências constitucionais e legais.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9129, 1, '2.2.3.1.0.00.00.00.00.00', 'FORNECEDORES NACIONAIS E CONTAS A PAGAR A LONGO PRAZO', 'Compreende as obrigações junto a fornecedores nacionais de matérias-primas, mercadorias e outros materiais utilizados nas atividades operacionais da entidade, com vencimento no longo prazo.  Compreende também os precatórios com vencimento no longo prazo das obrigações decorrentes do fornecimento de utilidades e da prestação de serviços, tais como de energia elétrica, água, telefone, propaganda, aluguéis e todas as outras contas a pagar referentes a credores nacionais.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9130, 1, '2.2.3.1.1.00.00.00.00.00', 'FORNECEDORES NACIONAIS E CONTAS A PAGAR A LONGO PRAZO - CONSOLIDAÇÃO', 'Compreende as obrigações junto a fornecedores nacionais de matérias-primas, mercadorias e outros materiais utilizados nas atividades operacionais da entidade, com vencimento no longo prazo.  Compreende também os precatórios com vencimento no longo prazo das obrigações decorrentes do fornecimento de utilidades e da prestação de serviços, tais como de energia elétrica, água, telefone, propaganda, aluguéis e todas as outras contas a pagar referentes a credores nacionais. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9131, 1, '2.2.3.1.1.01.00.00.00.00', 'FORNECEDORES NACIONAIS', 'Compreende os valores a pagar aos fornecedores nacionais de bens, materiais e serviços envolvidos com as atividades operacionais da entidade.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9132, 1, '2.2.3.1.1.04.00.00.00.00', 'PRECATÓRIOS DE FORNECEDORES NACIONAIS - REGIME ESPECIAL', 'Compreende as obrigações referentes a precatórios de fornecedores nacionais, sujeitos ao regime especial instituído pela emenda constitucional 62/ 2009.', 2, false, 0, 'X');
insert into contabilidade.planocontadetalhe values (9133, 1, '2.2.3.1.1.05.00.00.00.00', 'PRECATÓRIOS DE FORNECEDORES NACIONAIS - REGIME ORDINÁRIO', 'Compreende as obrigações referentes a precatórios de fornecedores nacionais,  não sujeitos ao regime especial instituído pela emenda constitucional 62/ 2009.', 2, false, 0, 'X');
insert into contabilidade.planocontadetalhe values (9134, 1, '2.2.3.1.1.06.00.00.00.00', 'PRECATÓRIOS DE CONTAS A PAGAR - CREDORES NACIONAIS- REGIME ESPECIAL', 'Compreende as obrigações referentes a precatórios de contas a pagar de credores nacionais, sujeitos ao regime especial instituído pela emenda constitucional 62/ 2009.', 2, false, 0, 'X');
insert into contabilidade.planocontadetalhe values (9135, 1, '2.2.3.1.1.07.00.00.00.00', 'PRECATÓRIOS DE CONTAS A PAGAR - CREDORES NACIONAIS - REGIME ORDINÁRIO', 'Compreende as obrigações referentes a precatórios de contas a pagar de credores nacionais,  não sujeitos ao regime especial instituído pela emenda constitucional 62/ 2009.', 2, false, 0, 'X');
insert into contabilidade.planocontadetalhe values (9136, 1, '2.2.3.2.0.00.00.00.00.00', 'FORNECEDORES ESTRANGEIROS A LONGO PRAZO', 'Compreende as obrigações junto a fornecedores estrangeiros de matérias primas, mercadorias e outros materiais utilizados nas atividades operacionais da entidade, com vencimento no longo prazo.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9137, 1, '2.2.3.2.1.00.00.00.00.00', 'FORNECEDORES ESTRANGEIROS A LONGO PRAZO - CONSOLIDAÇÃO', 'Compreende as obrigações junto a fornecedores estrangeiros de matérias primas, mercadorias e outros materiais utilizados nas atividades operacionais da entidade, com vencimento no longo prazo. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9138, 1, '2.2.3.2.1.01.00.00.00.00', 'FORNECEDORES ESTRANGEIROS A LONGO PRAZO', 'Compreende os valores a pagar aos fornecedores estrangeiros de bens, materiais e serviços envolvidos com as atividades operacionais da entidade.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9139, 1, '2.2.4.0.0.00.00.00.00.00', 'OBRIGAÇÕES FISCAIS A LONGO PRAZO', 'Compreende as obrigações das entidades com o governo relativas a impostos, taxas e contribuições com vencimento no longo prazo.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9140, 1, '2.2.4.1.0.00.00.00.00.00', 'OBRIGAÇÕES FISCAIS A LONGO PRAZO COM A UNIÃO', 'Compreende as obrigações das entidades com o governo federal relativas a impostos, taxas e contribuições, com vencimento no longo prazo.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9141, 1, '2.2.4.1.1.00.00.00.00.00', 'OBRIGAÇÕES FISCAIS A LONGO PRAZO COM A UNIÃO - CONSOLIDAÇÃO', 'Compreende as obrigações das entidades com o governo federal relativas a impostos, taxas e contribuições, com vencimento no longo prazo. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9142, 1, '2.2.4.1.2.00.00.00.00.00', 'OBRIGAÇÕES FISCAIS A LONGO PRAZO COM A UNIÃO - INTRA OFSS', 'Compreende as obrigações das entidades com o governo federal relativas a impostos, taxas e contribuições com vencimento no longo prazo. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do mesmo ente.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9143, 1, '2.2.4.1.3.00.00.00.00.00', 'OBRIGAÇÕES FISCAIS A LONGO PRAZO COM A UNIÃO - INTER OFSS - UNIÃO', 'Compreende as obrigações das entidades com o governo federal relativas a impostos, taxas e contribuições, com vencimento no longo prazo. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9144, 1, '2.2.4.2.0.00.00.00.00.00', 'OBRIGAÇÕES FISCAIS A LONGO PRAZO COM OS ESTADOS', 'Compreende as obrigações das entidades com o governo estadual relativas a impostos, taxas e contribuições, com vencimento no longo prazo.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9145, 1, '2.2.4.2.1.00.00.00.00.00', 'OBRIGAÇÕES FISCAIS A LONGO PRAZO COM OS ESTADOS - CONSOLIDAÇÃO', 'Compreende as obrigações das entidades com o governo estadual relativas a impostos, taxas e contribuições, com vencimento no longo prazo. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9146, 1, '2.2.4.2.2.00.00.00.00.00', 'OBRIGAÇÕES FISCAIS A LONGO PRAZO COM OS ESTADOS - INTRA OFSS', 'Compreende as obrigações das entidades com o governo estadual relativas a impostos, taxas e contribuições, com vencimento no longo prazo. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do mesmo ente.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9147, 1, '2.2.7.4.0.00.00.00.00.00', 'PROVISÃO PARA RISCOS CÍVEIS A LONGO PRAZO', 'Compreende os passivos de prazo ou de valor incertos, relacionados a pagamento de indenizações a fornecedores e clientes, com probabilidade de ocorrerem no longo prazo.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9148, 1, '2.2.4.2.4.00.00.00.00.00', 'OBRIGAÇÕES FISCAIS A LONGO PRAZO COM OS ESTADOS - INTER OFSS - ESTADO', 'Compreende as obrigações das entidades com o governo estadual relativas a impostos, taxas e contribuições, com vencimento no longo prazo. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9149, 1, '2.2.4.3.0.00.00.00.00.00', 'OBRIGAÇÕES FISCAIS A LONGO PRAZO COM OS MUNICÍPIOS', 'Compreende as obrigações das entidades com o governo municipal relativas a impostos, taxas e contribuições, com vencimento no longo prazo.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9150, 1, '2.2.4.3.1.00.00.00.00.00', 'OBRIGAÇÕES FISCAIS A LONGO PRAZO COM OS MUNICÍPIOS - CONSOLIDAÇÃO', 'Compreende as obrigações das entidades com o governo municipal relativas a impostos, taxas e contribuições, com vencimento no longo prazo. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9152, 1, '2.2.4.3.2.00.00.00.00.00', 'OBRIGAÇÕES FISCAIS A LONGO PRAZO COM OS MUNICÍPIOS-INTRA OFSS', 'Compreende as obrigações das entidades com o governo municipal relativas a impostos, taxas e contribuições, com vencimento no longo prazo. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do mesmo ente.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9153, 1, '2.2.4.3.5.00.00.00.00.00', 'OBRIGAÇÕES FISCAIS A LONGO PRAZO COM OS MUNICÍPIOS-INTER OFSS - MUNICÍPIO', 'Compreende as obrigações das entidades com o governo municipal relativas a impostos, taxas e contribuições, com vencimento no longo prazo.  Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9154, 1, '2.2.7.0.0.00.00.00.00.00', 'PROVISÕES A LONGO PRAZO', 'Compreende os passivos de prazo ou de valor incertos, com probabilidade de ocorrerem no longo prazo.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9155, 1, '2.2.7.1.0.00.00.00.00.00', 'PROVISÃO PARA RISCOS TRABALHISTAS A LONGO PRAZO', 'Compreende os passivos de prazo ou de valor incertos, relacionados a pagamento de reclamações trabalhistas, com probabilidade de ocorrerem no longo prazo.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9156, 1, '2.2.7.1.1.00.00.00.00.00', 'PROVISÃO PARA RISCOS TRABALHISTAS A LONGO PRAZO - CONSOLIDAÇÃO', 'Compreende os passivos de prazo ou de valor incertos, relacionados a pagamento de reclamações trabalhistas, com probabilidade de ocorrerem no longo prazo. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9157, 1, '2.2.7.2.0.00.00.00.00.00', 'PROVISÕES MATEMÁTICAS PREVIDÊNCIÁRIAS A LONGO PRAZO', 'Compreende os passivos de prazo ou de valor incertos, relacionados a futuros benefícios previdenciários a serem pagos aos contribuintes, com probabilidade de ocorrerem no longo prazo.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9158, 1, '2.2.7.2.1.00.00.00.00.00', 'PROVISÕES MATEMÁTICAS PREVIDÊNCIÁRIAS A LONGO PRAZO - CONSOLIDAÇÃO', 'Compreende os passivos de prazo ou de valor incertos, relacionados a futuros benefícios previdenciários a serem pagos aos contribuintes, comprobabilidade de ocorrerem no longo prazo. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9159, 1, '2.2.7.2.1.01.00.00.00.00', 'PLANO FINANCEIRO - PROVISOES DE BENEFICIOS CONCEDIDOS   ', 'Compreende, de acordo com o resultado da avaliação atuarial, a provisão matemática correspondente ao valor presente liquido das prestações futuras dos benefícios já concedidos aos assistidos e beneficiários em gozo de beneficio de prestação continuada.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9160, 1, '2.2.7.2.1.02.00.00.00.00', 'PLANO FINANCEIRO - PROVISOES DE BENEFICIOS A CONCEDER            ', 'Compreende, de acordo com o resultado da avaliação atuarial, a provisão matemática correspondente ao valor presente liquido das prestações futuras dos benefícios a conceder para a geração atual (servidores ativos).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9161, 1, '2.2.7.2.1.03.00.00.00.00', 'PLANO PREVIDENCIARIO - PROVISOES DE BENEFICIOS CONCEDIDOS            ', 'Compreende, de acordo com o resultado da avaliação atuarial, a provisão matemática correspondente ao valor presente liquido das prestações futuras dos benefícios já concedidos aos assistidos e beneficiários em gozo de beneficio de prestação continuada.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9162, 1, '2.2.7.2.1.04.00.00.00.00', 'PLANO PREVIDENCIARIO - PROVISOES DE BENEFICIOS A CONCEDER              ', 'Compreende, de acordo com o resultado da avaliação atuarial, a provisão matemática correspondente ao valor presente liquido das prestações futuras dos benefícios a conceder para a geração atual (servidores ativos).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9163, 1, '2.2.7.2.1.05.00.00.00.00', ' PLANO PREVIDENCIARIO - PLANO DE AMORTIZAÇÃO                            ', 'Compreende, de acordo com resultado da avaliação atuarial, o valor presente liquido dos direitos incorporados ao patrimônio do RPPS com base em legislação especifica, bem como registro tempestivo do plano de amortização implementado em lei do ente federativo, considerando que o ajuste contábil das reservas matemáticas somente ocorrera na apresentação de uma nova reavaliação atuarial.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9164, 1, '2.2.7.2.1.06.00.00.00.00', ' PROVISOES ATUARIAIS PARA AJUSTES DO PLANO FINANCEIRO      ', 'Compreende o somatório das provisões atuariais constituídas para ajustes do plano financeiro, conforme o resultado da avaliação atuarial.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9165, 1, '2.2.7.2.1.07.00.00.00.00', ' PROVISOES ATUARIAIS PARA AJUSTES DO PLANO PREVIDENCIARIO      ', 'Compreende o somatório das provisões atuariais constituídas para ajustes do plano previdenciário, conforme o resultado da avaliação atuarial.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9166, 1, '2.2.7.3.0.00.00.00.00.00', 'PROVISÃO PARA RISCOS FISCAIS A LONGO PRAZO', 'Compreende os passivos de prazo ou de valor incertos, relacionados ao pagamento de autuações fiscais, com probabilidade de ocorrerem no longo prazo.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9167, 1, '2.2.7.3.1.00.00.00.00.00', 'PROVISÃO PARA RISCOS FISCAIS A LONGO PRAZO - CONSOLIDAÇÃO', 'Compreende os passivos de prazo ou de valor incertos, relacionados ao pagamento de autuações fiscais, com probabilidade de ocorrerem no longo prazo. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9168, 1, '2.2.7.3.1.01.00.00.00.00', 'PROVISÃO PARA PAGAMENTOS REFERENTES A AUTOS DE INFRAÇÃO', 'Compreende os valores das provisões para pagamento de autos de infração já lavrados e que se encontram na esfera administrativa.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9169, 1, '2.2.7.3.1.02.00.00.00.00', 'PROVISÃO PARA PAGAMENTOS DE AUTUAÇÕES FISCAIS - ESFERA JUDICIAL', 'Compreende os valores das provisões para pagamento de autuações fiscais que já se encontram na esfera judicial.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9170, 1, '2.2.7.4.1.00.00.00.00.00', 'PROVISÃO PARA RISCOS CÍVEIS A LONGO PRAZO - CONSOLIDAÇÃO', 'Compreende os passivos de prazo ou de valor incertos, relacionados a pagamento de indenizações a fornecedores e clientes, com probabilidade de ocorrerem no longo prazo. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9171, 1, '2.2.7.5.0.00.00.00.00.00', 'PROVISÃO PARA REPARTIÇÃO DE CRÉDITOS A LONGO PRAZO', 'Compreende os passivos de prazo ou de valores incertos relacionados aos créditos tributários e não tributários reconhecidos no lançamento por parte do agente arrecadador, a serem repartidos com outros entes da federação, com probabilidade de ocorrerem no longo prazo. Na arrecadação, esta provisão será revertida em conta especifica de passivo.', 2, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (9330, 1, '4.5.1.2.2.01.00.00.00.00', 'TRANSFERÊNCIAS FINANCEIRAS RECEBIDAS - INDEPENDENTES DE EXECUÇÃO ORÇAMENTÁRIA', 'Compreende o valor das transferências financeiras recebidas para restos a pagar e outras finalidades independentes da execução orçamentária.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9172, 1, '2.2.7.5.3.00.00.00.00.00', 'PROVISÃO PARA REPARTIÇÃO DE CRÉDITOS A LONGO PRAZO - INTER OFSS - UNIÃO', 'Compreende os passivos de prazo ou de valores incertos relacionados aos créditos tributários e não tributários reconhecidos no lançamento por parte do agente arrecadador, a serem repartidos a outras entidades, conforme previsão legal. Na arrecadação, esta provisão será revertida em conta específica de passivo. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (9173, 1, '2.2.7.5.4.00.00.00.00.00', 'PROVISÃO PARA REPARTIÇÃO DE CRÉDITOS A LONGO PRAZO - INTER OFSS - ESTADO', 'Compreende os passivos de prazo ou de valores incertos relacionados aos créditos tributários e não tributários reconhecidos no lançamento por parte do agente arrecadador, a serem repartidos com outros entes da federação, com probabilidade de ocorrerem no longo prazo. Na arrecadação, esta provisão será revertida em conta especifica de passivo. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 2, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (9174, 1, '2.2.7.5.5.00.00.00.00.00', 'PROVISÃO PARA REPARTIÇÃO DE CRÉDITOS A LONGO PRAZO - INTER OFSS - MUNICÍPIO', 'Compreende os passivos de prazo ou de valores incertos relacionados aos créditos tributários e não tributários reconhecidos no lançamento por parte do agente arrecadador, a serem repartidos com outros entes da federação, com probabilidade de ocorrerem no longo prazo. Na arrecadação, esta provisão será revertida em conta especifica de passivo. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 2, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (9175, 1, '2.2.7.6.0.00.00.00.00.00', 'PROVISÃO PARA RISCOS DECORRENTES DE CONTRATOS DE PPP A LONGO PRAZO', 'Compreende os passivos de prazo ou de valores incertos relacionados aos riscos de demanda, construção, disponibilidade ou outros riscos decorrentes de contratos de PPP, de acordo com a Lei n.11.079/2004.', 2, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (9176, 1, '2.2.7.6.1.00.00.00.00.00', 'PROVISÃO PARA RISCOS DECORRENTES DE CONTRATOS DE PPP A LONGO PRAZO - CONSOLIDAÇÃO', 'Compreende os passivos de prazo ou de valores incertos relacionados aos riscos de demanda, construção, disponibilidade ou outros riscos decorrentes de contratos de PPP, de acordo com a Lei n.11.079/2004. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (9177, 1, '2.2.7.7.0.00.00.00.00.00', 'PROVISÃO PARA OBRIGAÇÕES DECORRENTES DA ATUAÇÃO GOVERNAMENTAL A LONGO PRAZO', 'Compreende os passivos de prazo ou de valores incertos relacionados a programas governamentais, como subsídios, auxílios, desonerações, assunção de obrigações ou outros.', 2, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (9178, 1, '2.2.7.7.1.00.00.00.00.00', 'PROVISÃO PARA OBRIGAÇÕES DECORRENTES DA ATUAÇÃO GOVERNAMENTAL A LONGO PRAZO - CONSOLIDAÇÃO', 'Compreende os passivos de prazo ou de valores incertos relacionados a programas governamentais, como subsídios, auxílios, desonerações, assunção de obrigações ou outros. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (9179, 1, '2.2.7.9.0.00.00.00.00.00', 'OUTRAS PROVISÕES A LONGO PRAZO', 'Compreende os demais passivos de prazo ou de valor incertos, com probabilidade de ocorrerem no longo prazo, não classificadas anteriormente neste plano de contas.', 2, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (9180, 1, '2.2.7.9.1.00.00.00.00.00', 'OUTRAS PROVISÕES A LONGO PRAZO - CONSOLIDAÇÃO', 'Compreende os demais passivos de prazo ou de valor incertos, com probabilidade de ocorrerem no longo prazo, não classificadas anteriormente neste plano de contas. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (9181, 1, '2.2.7.9.1.03.00.00.00.00', 'PROVISÕES DO FCVS', 'Compreende, de acordo com a nota técnica atuarial, os valores atuariais dos passivos do fundo de compensação e variações salariais.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9182, 1, '2.2.8.0.0.00.00.00.00.00', 'DEMAIS OBRIGAÇÕES A LONGO PRAZO', 'Compreende as obrigações da entidade junto a terceiros não inclusas nos subgrupos anteriores, inclusive os precatórios decorrentes dessas obrigações, com vencimento no longo prazo.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9183, 1, '2.2.8.1.0.00.00.00.00.00', 'ADIANTAMENTOS DE CLIENTES A LONGO PRAZO', 'Compreende as antecipações recebidas por operações de fornecimento de bens ou prestação de serviços e que ensejem a devolução da quantia recebida, caso a operação não ocorra.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9184, 1, '2.2.8.1.1.00.00.00.00.00', 'ADIANTAMENTOS DE CLIENTES A LONGO PRAZO- CONSOLIDAÇÃO', 'Compreende as antecipações recebidas por operações de fornecimento de bens ou prestação de serviços e que ensejem a devolução da quantia recebida, caso a operação não ocorra. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (9185, 1, '2.2.8.2.0.00.00.00.00.00', 'OBRIGAÇÕES POR DANOS A TERCEIROS A LONGO PRAZO', 'Compreende os valores exigíveis no longo prazo, provenientes de danos a terceiros.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9186, 1, '2.2.8.2.1.00.00.00.00.00', 'OBRIGAÇÕES POR DANOS A TERCEIROS A LONGO PRAZO - CONSOLIDAÇÃO', 'Compreende os valores exigíveis no longo prazo, provenientes de danos a terceiros. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'X');
insert into contabilidade.planocontadetalhe values (9187, 1, '2.2.8.3.0.00.00.00.00.00', 'DEBÊNTURES E OUTROS TÍTULOS DE DÍVIDA A LONGO PRAZO', 'Compreende os títulos emitidos pela entidade que conferirão aos seus titulares direito de credito contra ela, nas condições constantes da escritura de emissão do titulo, com vencimento no longo prazo.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9188, 1, '2.2.8.3.1.00.00.00.00.00', 'DEBÊNTURES E OUTROS TÍTULOS DE DÍVIDA A LONGO PRAZO- CONSOLIDAÇÃO', 'Compreende os títulos emitidos pela entidade que conferirão aos seus titulares direito de credito contra ela, nas condições constantes da escritura de emissão do titulo, com vencimento no longo prazo. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'X');
insert into contabilidade.planocontadetalhe values (9189, 1, '2.2.8.4.0.00.00.00.00.00', 'ADIANTAMENTO PARA FUTURO AUMENTO DE CAPITAL', 'Compreende os recursos recebidos pela entidade de seus acionistas ou quotistas destinados a serem utilizados para aumento de capital, quando haja a possibilidade de devolução destes recursos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9252, 1, '2.3.3.9.1.00.00.00.00.00', 'OUTRAS RESERVAS DE CAPITAL - CONSOLIDAÇÃO', 'Compreende os valores das demais reservas de capital, inclusive aquelas que terão seus saldos realizados por haverem sido extintas pela legislação. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9190, 1, '2.2.8.4.1.00.00.00.00.00', 'ADIANTAMENTO PARA FUTURO AUMENTO DE CAPITAL - CONSOLIDAÇÃO', 'Compreende os recursos recebidos pela entidade de seus acionistas ou quotistas destinados a serem utilizados para aumento de capital, quando haja a possibilidade de devolução destes recursos. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (9191, 1, '2.2.8.6.0.00.00.00.00.00', 'OBRIGAÇÕES DECORRENTES DE CONTRATOS DE PPP- LONGO PRAZO', 'Compreende os passivos decorrentes dos contratos de Parceria Público Privada - PPP. Deve abranger tanto a contraprestação referente à incorporação dos ativos quanto à referente à prestação dos serviços objeto do contrato, incluindo a parcela variável condicionada à qualidade do serviço.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9192, 1, '2.3.2.0.2.00.00.00.00.00', 'ADIANTAMENTO PARA FUTURO AUMENTO DE CAPITAL - INTRA OFSS', 'Compreende os recursos recebidos pela entidade de seus acionistas ou quotistas destinados a serem utilizados para aumento de capital, quando não haja a possibilidade de devolução destes recursos. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do mesmo ente.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9193, 1, '2.2.8.6.1.00.00.00.00.00', 'OBRIGAÇÕES DECORRENTES DE CONTRATOS DE PPP- CONSOLIDAÇÃO', 'Compreende os passivos decorrentes dos contratos de Parceria Público Privada - PPP. Deve abranger tanto a contraprestação referente à incorporação dos ativos quanto à referente à prestação dos serviços objeto do contrato, incluindo a parcela variável condicionada à qualidade do serviço. Compreende os valores de operações efetuadas entre uma unidade pertencente ao orçamento fiscal e da seguridade social (OFSS) com pessoa ou unidade que não pertença ao OFSS de ente público, alem dos demais fatos que não compreendem transações entre partes.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9194, 1, '2.2.8.8.0.00.00.00.00.00', 'VALORES RESTITUÍVEIS', 'Compreende os valores de terceiros ou retenções em nome deles, quando a entidade do setor público for fiel depositaria, exigíveis no longo prazo.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9195, 1, '2.2.8.8.1.00.00.00.00.00', 'VALORES RESTITUÍVEIS - CONSOLIDAÇÃO', 'Compreende os valores de terceiros ou retenções em nome deles, quando a entidade do setor público for fiel depositaria, exigíveis no longo prazo. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9196, 1, '2.2.8.8.1.01.00.00.00.00', 'CONSIGNAÇÕES ', 'Compreende os valores entregues em confiança ou em consignações, geralmente retidos em folha de pagamento de empregados ou servidores ou nos pagamentos referentes a compras de bens e serviços.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9197, 1, '2.2.8.8.1.03.00.00.00.00', 'DEPOSITOS JUDICIAIS', 'Compreende os valores de obrigações, decorrentes de depósitos recebidos por determinação judicial e depósitos para recursos judiciais.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9198, 1, '2.2.8.8.1.04.00.00.00.00', 'DEPOSITOS NAO JUDICIAIS', 'Compreende os valores de obrigações, decorrentes de depósitos recebidos, exceto depósitos judiciais.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9199, 1, '2.2.8.9.0.00.00.00.00.00', 'OUTRAS OBRIGAÇÕES A LONGO PRAZO', 'Compreende outras obrigações não classificáveis em grupos específicos deste plano de contas, com vencimento no longo prazo.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9200, 1, '2.2.8.9.1.00.00.00.00.00', 'OUTRAS OBRIGAÇÕES A LONGO PRAZO- CONSOLIDAÇÃO', 'Compreende outras obrigações não classificáveis em grupos específicos deste plano de contas, com vencimento no longo prazo. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'X');
insert into contabilidade.planocontadetalhe values (9201, 1, '2.2.9.0.0.00.00.00.00.00', 'RESULTADO DIFERIDO', 'Compreende o valor das variações patrimoniais aumentativas já recebidas que efetivamente devem ser reconhecidas em resultados em anos futuros e que não haja qualquer tipo de obrigação de devolução por parte da entidade.  Compreende também o saldo existente na antiga conta resultado de exercícios futuros em 31 de dezembro de 2008.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9202, 1, '2.2.9.1.0.00.00.00.00.00', 'VARIAÇÃO PATRIMONIAL AUMENTATIVA (VPA) DIFERIDA', 'Compreende o valor das variações patrimoniais aumentativas já recebidas que efetivamente devem ser reconhecidas em resultados em anos futuros e que não haja qualquer tipo de obrigação de devolução por parte da entidade.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9203, 1, '2.2.9.1.1.00.00.00.00.00', 'VARIAÇÃO PATRIMONIAL AUMENTATIVA DIFERIDA - CONSOLIDAÇÃO', 'Compreende o valor das variações patrimoniais aumentativas já recebidas que efetivamente devem ser reconhecidas em resultados em anos futuros e que não haja qualquer tipo de obrigação de devolução por parte da entidade. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'P');
insert into contabilidade.planocontadetalhe values (9204, 1, '2.3.0.0.0.00.00.00.00.00', 'PATRIMÔNIO LIQUIDO', 'Compreende o valor residual dos ativos depois de deduzidos todos os passivos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9205, 1, '2.3.1.0.0.00.00.00.00.00', 'PATRIMÔNIO SOCIAL E CAPITAL SOCIAL', 'Compreende o patrimônio social das autarquias, fundações e fundos e o capital social das demais entidades da administração indireta.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9206, 1, '2.3.1.1.0.00.00.00.00.00', 'PATRIMÔNIO SOCIAL', 'Compreende o patrimônio das autarquias, fundações e fundos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9207, 1, '2.3.1.1.1.00.00.00.00.00', 'PATRIMÔNIO SOCIAL - CONSOLIDAÇÃO', 'Compreende o patrimônio das autarquias, fundações e fundos, pertencentes ao orçamento fiscal e da seguridade social.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9208, 1, '2.3.1.2.0.00.00.00.00.00', 'CAPITAL SOCIAL REALIZADO', 'Compreende o capital social subscrito das empresas públicas e sociedades de economia mista, deduzido da parcela ainda não realizada.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9209, 1, '4.5.3.2.0.00.00.00.00.00', 'TRANSFERÊNCIAS DAS INSTITUIÇÕES PRIVADAS COM FINS LUCRATIVOS', 'Compreende as variações patrimoniais aumentativas decorrentes das transferências financeiras das instituições privadas com fins lucrativos, inclusive de bens e valores.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9210, 1, '2.3.1.2.1.00.00.00.00.00', 'CAPITAL SOCIAL REALIZADO - CONSOLIDAÇÃO', 'Compreende o capital social subscrito das empresas públicas e sociedades de economia mista, deduzido da parcela ainda não realizada. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9211, 1, '2.3.1.2.2.00.00.00.00.00', 'CAPITAL SOCIAL REALIZADO - INTRA OFSS', 'Compreende o capital social subscrito, deduzido da parcela ainda não realizada. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do mesmo ente.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9212, 1, '6.3.2.9.0.00.00.00.00.00', 'RP PROCESSADOS CANCELADOS', 'Compreende o cancelamento de restos a pagar processados por insuficiência de recursos, pela inscrição indevida ou para atender dispositivo legal.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9213, 1, '2.3.1.2.3.00.00.00.00.00', 'CAPITAL SOCIAL REALIZADO - INTER OFSS - UNIÃO', 'Compreende o capital social subscrito, deduzido da parcela ainda não realizada. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9214, 1, '2.3.1.2.4.00.00.00.00.00', 'CAPITAL SOCIAL REALIZADO - INTER OFSS - ESTADO', 'Compreende o capital social subscrito, deduzido da parcela ainda não realizada. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9215, 1, '2.3.1.2.5.00.00.00.00.00', 'CAPITAL SOCIAL REALIZADO - INTER OFSS - MUNICÍPIO', 'Compreende o capital social subscrito, deduzido da parcela ainda não realizada. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9216, 1, '2.3.2.0.0.00.00.00.00.00', 'ADIANTAMENTO PARA FUTURO AUMENTO DE CAPITAL', 'Compreende os recursos recebidos pela entidade de seus acionistas ou quotistas destinados a serem utilizados para aumento de capital, quando não haja a possibilidade de devolução destes recursos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9217, 1, '2.3.2.0.1.00.00.00.00.00', 'ADIANTAMENTO PARA FUTURO AUMENTO DE CAPITAL - CONSOLIDAÇÃO', 'Compreende os recursos recebidos pela entidade de seus acionistas ou quotistas destinados a serem utilizados para aumento de capital, quando não haja a possibilidade de devolução destes recursos. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9218, 1, '2.3.2.0.3.00.00.00.00.00', 'ADIANTAMENTO PARA FUTURO AUMENTO DE CAPITAL - INTER OFSS - UNIÃO', 'Compreende os recursos recebidos pela entidade de seus acionistas ou quotistas destinados a serem utilizados para aumento de capital, quando não haja a possibilidade de devolução destes recursos. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9219, 1, '2.3.5.6.2.00.00.00.00.00', 'RESERVA DE LUCROS A REALIZAR- INTRA OFSS', 'Compreende a reserva constituída com o excesso entre o montante do dividendo obrigatório e a parcela realizada do lucro liquido do exercício. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do ente.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9220, 1, '2.3.2.0.4.00.00.00.00.00', 'ADIANTAMENTO PARA FUTURO AUMENTO DE CAPITAL - INTER OFSS - ESTADO', 'Compreende os recursos recebidos pela entidade de seus acionistas ou quotistas destinados a serem utilizados para aumento de capital, quando não haja a possibilidade de devolução destes recursos. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9221, 1, '2.3.2.0.5.00.00.00.00.00', 'ADIANTAMENTO PARA FUTURO AUMENTO DE CAPITAL - INTER OFSS - MUNICÍPIO.', 'Compreende os recursos recebidos pela entidade de seus acionistas ou quotistas destinados a serem utilizados para aumento de capital, quando não haja a possibilidade de devolução destes recursos. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9222, 1, '2.3.3.0.0.00.00.00.00.00', 'RESERVAS DE CAPITAL', 'Compreende os valores acrescidos ao patrimônio que não transitaram pelo resultado como variações patrimoniais aumentativas (VPA).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9223, 1, '2.3.3.1.0.00.00.00.00.00', 'ÁGIO NA EMISSÃO DE AÇÕES', 'Compreende a contribuição do subscritor de ações que ultrapassar o valor nominal e a parte do preço de emissão das ações sem valor nominal que ultrapassar a importância destinada à formação do capital social, inclusive nos casos de conversão em ações de debêntures ou partes beneficiárias.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9224, 1, '2.3.3.1.1.00.00.00.00.00', 'ÁGIO NA EMISSÃO DE AÇÕES - CONSOLIDAÇÃO', 'Compreende a contribuição do subscritor de ações que ultrapassar o valor nominal e a parte do preço de emissão das ações sem valor nominal que ultrapassar a importância destinada à formação do capital social, inclusive nos casos de conversão em ações de debêntures ou partes beneficiarias. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9225, 1, '2.3.3.1.2.00.00.00.00.00', 'ÁGIO NA EMISSÃO DE AÇÕES - INTRA OFSS', 'Compreende a contribuição do subscritor de ações que ultrapassar o valor nominal e a parte do preço de emissão das ações sem valor nominal que ultrapassar a importância destinada à formação do capital social, inclusive nos casos de conversão em ações de debêntures ou partes beneficiarias. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do mesmo ente.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9226, 1, '2.3.3.1.3.00.00.00.00.00', 'ÁGIO NA EMISSÃO DE AÇÕES - INTER OFSS - UNIÃO', 'Compreende a contribuição do subscritor de ações que ultrapassar o valor nominal e a parte do preço de emissão das ações sem valor nominal que ultrapassar a importância destinada à formação do capital social, inclusive nos casos de conversão em ações de debêntures ou partes beneficiarias. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9227, 1, '2.3.3.1.4.00.00.00.00.00', 'ÁGIO NA EMISSÃO DE AÇÕES - INTER OFSS - ESTADO', 'Compreende a contribuição do subscritor de ações que ultrapassar o valor nominal e a parte do preço de emissão das ações sem valor nominal que ultrapassar a importância destinada à formação do capital social, inclusive nos casos de conversão em ações de debêntures ou partes beneficiarias. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9228, 1, '4.6.1.0.0.00.00.00.00.00', 'REAVALIAÇÃO DE ATIVOS', 'Compreende a variação patrimonial aumentativa relativa à adoção do valor de mercado ou de consenso entre as partes para bens do ativo, quando esse for superior ao valor liquido contábil.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9229, 1, '2.3.3.9.2.00.00.00.00.00', 'OUTRAS RESERVAS DE CAPITAL - INTRA OFSS', 'Compreende os valores das demais reservas de capital, inclusive aquelas que terão seus saldos realizados por haverem sido extintas pela legislação. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do mesmo ente.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9231, 1, '2.3.3.1.5.00.00.00.00.00', 'ÁGIO NA EMISSÃO DE AÇÕES - INTER OFSS - MUNICÍPIO', 'Compreende a contribuição do subscritor de ações que ultrapassar o valor nominal e a parte do preço de emissão das ações sem valor nominal que ultrapassar a importância destinada à formação do capital social, inclusive nos casos de conversão em ações de debêntures ou partes beneficiarias. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a um município.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9232, 1, '2.3.3.2.0.00.00.00.00.00', 'ALIENAÇÃO DE PARTES BENEFICIARIAS', 'Compreende o produto da alienação de partes beneficiárias.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9233, 1, '2.3.3.2.1.00.00.00.00.00', 'ALIENAÇÃO DE PARTES BENEFICIARIAS - CONSOLIDAÇÃO', 'Compreende o produto da alienação de partes beneficiárias. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
