insert into contabilidade.planocontadetalhe values (9289, 1, '2.3.5.6.0.00.00.00.00.00', 'RESERVA DE LUCROS A REALIZAR', 'Compreende a reserva constituída com o excesso entre o montante do dividendo obrigatório e a parcela realizada do lucro liquido do exercício.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9369, 1, '4.2.1.1.2.01.00.00.00.00', 'CONTRIBUIÇÕES PATRONAIS AO RPPS', 'Compreende a contribuicao patronal destinada ao custeio do regime proprio de previdencia social.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9290, 1, '2.3.5.6.1.00.00.00.00.00', 'RESERVA DE LUCROS A REALIZAR- CONSOLIDAÇÃO', 'Compreende a reserva constituída com o excesso entre o montante do dividendo obrigatório e a parcela realizada do lucro liquido do exercício. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9291, 1, '6.1.1.0.0.00.00.00.00.00', 'EXECUÇÃO DO PPA', 'Compreende o somatório dos valores monetários relativos à execução dos programas e ações (projetos, atividades e operações especiais) estabelecidos no plano plurianual.', 2, false, 0, 'N');
