insert into contabilidade.planocontadetalhe values (9295, 1, '2.3.5.7.0.00.00.00.00.00', 'RESERVA DE RETENÇÃO DE PREMIO NA EMISSÃO DE DEBÊNTURES', 'Compreende a parcela do lucro líquido do exercício decorrente do prêmio na emissão de debêntures.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9296, 1, '2.3.5.7.1.00.00.00.00.00', 'RESERVA DE RETENÇÃO DE PREMIO NA EMISSÃO DE DEBÊNTURES- CONSOLIDAÇÃO', 'Compreende a parcela do lucro líquido do exercício decorrente do premio na emissão de debêntures. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
