insert into contabilidade.planocontadetalhe values (9298, 1, '2.3.5.7.3.00.00.00.00.00', 'RESERVA DE RETENÇÃO DE PREMIO NA EMISSÃO DE DEBÊNTURES- INTER OFSS - UNIÃO', 'Compreende a parcela do lucro líquido do exercício decorrente do premio na emissão de debêntures. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9299, 1, '2.3.5.7.4.00.00.00.00.00', 'RESERVA DE RETENÇÃO DE PREMIO NA EMISSÃO DE DEBÊNTURES- INTER OFSS - ESTADO', 'Compreende a parcela do lucro líquido do exercício decorrente do premio na emissão de debêntures. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9300, 1, '2.3.5.7.5.00.00.00.00.00', 'RESERVA DE RETENÇÃO DE PREMIO NA EMISSÃO DE DEBÊNTURES- INTER OFSS - MUNICÍPIO', 'Compreende a parcela do lucro líquido do exercício decorrente do premio na emissão de debêntures. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9301, 1, '2.3.5.8.0.00.00.00.00.00', 'RESERVA ESPECIAL PARA DIVIDENDO OBRIGATÓRIO NÃO DISTRIBUÍDO', 'Compreende os valores referentes ao dividendo obrigatório que deixar de ser distribuído no exercício por ser incompatível com a situação financeira da entidade.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9302, 1, '2.3.5.8.1.00.00.00.00.00', 'RESERVA ESPECIAL PARA DIVIDENDO OBRIGATÓRIO NÃO DISTRIBUÍDO - CONSOLIDAÇÃO', 'Compreende os valores referentes ao dividendo obrigatório que deixar de ser distribuído no exercício por ser incompatível com a situação financeira da entidade. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9303, 1, '2.3.5.8.2.00.00.00.00.00', 'RESERVA ESPECIAL PARA DIVIDENDO OBRIGATÓRIO NÃO DISTRIBUÍDO - INTRA OFSS', 'Compreende os valores referentes ao dividendo obrigatório que deixar de ser distribuído no exercício por ser incompatível com a situação financeira da entidade. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do ente.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9304, 1, '2.3.5.8.3.00.00.00.00.00', 'RESERVA ESPECIAL PARA DIVIDENDO OBRIGATÓRIO NÃO DISTRIBUÍDO - INTER OFSS - UNIÃO', 'Compreende os valores referentes ao dividendo obrigatório que deixar de ser distribuído no exercício por ser incompatível com a situação financeira da entidade. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 2, false, 0, 'N');
