insert into contabilidade.planocontadetalhe values (9306, 1, '2.3.5.8.5.00.00.00.00.00', 'RESERVA ESPECIAL PARA DIVIDENDO OBRIGATÓRIO NÃO DISTRIBUÍDO - INTER OFSS - MUNICÍPIO', 'Compreende os valores referentes ao dividendo obrigatório que deixar de ser distribuído no exercício por ser incompatível com a situação financeira da entidade. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9307, 1, '2.3.5.9.0.00.00.00.00.00', 'OUTRAS RESERVAS DE LUCRO', 'Compreende os valores das demais reservas de lucro, inclusive aquelas que terão seus saldos realizados por haverem sido extintas pela legislação.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9308, 1, '2.3.5.9.1.00.00.00.00.00', 'OUTRAS RESERVAS DE LUCRO - CONSOLIDAÇÃO', 'Compreende os valores das demais reservas de lucro, inclusive aquelas que terão seus saldos realizados por haverem sido extintas pela legislação Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9309, 1, '2.3.5.9.2.00.00.00.00.00', 'OUTRAS RESERVAS DE LUCRO - INTRA OFSS', 'Compreende os valores das demais reservas de lucro, inclusive aquelas que terão seus saldos realizados por haverem sido extintas pela legislação. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do mesmo ente.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9310, 1, '4.0.0.0.0.00.00.00.00.00', 'VARIAÇÃO PATRIMONIAL AUMENTATIVA', 'Compreende o aumento no beneficio econômico durante o período contábil sob a forma de entrada de recurso ou aumento de ativo ou diminuição de passivo, que resulte em aumento do patrimônio liquido e que não sejam provenientes de aporte dos proprietários.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9311, 1, '2.3.5.9.3.00.00.00.00.00', 'OUTRAS RESERVAS DE LUCRO - INTER OFSS - UNIÃO', 'Compreende os valores das demais reservas de lucro, inclusive aquelas que terão seus saldos realizados por haverem sido extintas pela legislação. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9312, 1, '2.3.5.9.4.00.00.00.00.00', 'OUTRAS RESERVAS DE LUCRO - INTER OFSS - ESTADO', 'Compreende os valores das demais reservas de lucro, inclusive aquelas que terão seus saldos realizados por haverem sido extintas pela legislação. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9313, 1, '2.3.5.9.5.00.00.00.00.00', 'OUTRAS RESERVAS DE LUCRO - INTER OFSS - MUNICÍPIO', 'Compreende os valores das demais reservas de lucro, inclusive aquelas que terão seus saldos realizados por haverem sido extintas pela legislação. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9314, 1, '2.3.6.1.1.00.00.00.00.00', 'RESERVA DE REAVALIAÇÃO - CONSOLIDAÇÃO', 'Compreende a contrapartida dos acréscimos de valor atribuídos a elementos do ativo, apurados pela diferença entre o valor do laudo e o valor anterior (custo original mais eventuais reavaliações anteriores), nos casos permitidos pela legislação vigente. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9315, 1, '2.3.6.1.2.00.00.00.00.00', 'RESERVA DE REAVALIAÇÃO - INTRA OFSS', 'Compreende a contrapartida dos acréscimos de valor atribuídos a elementos do ativo, apurados pela diferença entre o valor do laudo e o valor anterior (custo original mais eventuais reavaliações anteriores), nos casos permitidos pela legislação vigente. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do mesmo ente.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9316, 1, '2.3.6.1.3.00.00.00.00.00', 'RESERVA DE REAVALIAÇÃO - INTER OFSS - UNIÃO', 'Compreende a contrapartida dos acréscimos de valor atribuídos a elementos do ativo, apurados pela diferença entre o valor do laudo e o valor anterior (custo original mais eventuais reavaliações anteriores), nos casos permitidos pela legislação vigente. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9317, 1, '2.3.6.1.4.00.00.00.00.00', 'RESERVA DE REAVALIAÇÃO - INTER OFSS - ESTADO', 'Compreende a contrapartida dos acréscimos de valor atribuídos a elementos do ativo, apurados pela diferença entre o valor do laudo e o valor anterior (custo original mais eventuais reavaliações anteriores), nos casos permitidos pela legislação vigente. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9318, 1, '2.3.6.1.5.00.00.00.00.00', 'RESERVA DE REAVALIAÇÃO - INTER OFSS - MUNICÍPIO', 'Compreende a contrapartida dos acréscimos de valor atribuídos a elementos do ativo, apurados pela diferença entre o valor do laudo e o valor anterior (custo original mais eventuais reavaliações anteriores), nos casos permitidos pela legislação vigente. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9319, 1, '2.3.6.9.0.00.00.00.00.00', 'OUTRAS RESERVAS', 'Compreende outras reservas que não forem classificadas como reservas de capital ou de lucro.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9320, 1, '2.3.6.9.1.00.00.00.00.00', 'OUTRAS RESERVAS - CONSOLIDAÇÃO', 'Compreende outras reservas que não forem classificadas como reservas de capital ou de lucro. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9321, 1, '2.3.6.9.2.00.00.00.00.00', 'OUTRAS RESERVAS - INTRA OFSS', 'Compreende outras reservas que não forem classificadas como reservas de capital ou de lucro. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do mesmo ente.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9322, 1, '2.3.6.9.3.00.00.00.00.00', 'OUTRAS RESERVAS - INTER OFSS - UNIÃO', 'Compreende outras reservas que não forem classificadas como reservas de capital ou de lucro. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9323, 1, '2.3.6.9.4.00.00.00.00.00', 'OUTRAS RESERVAS - INTER OFSS - ESTADO', 'Compreende outras reservas que não forem classificadas como reservas de capital ou de lucro. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9324, 1, '2.3.6.9.5.00.00.00.00.00', 'OUTRAS RESERVAS - INTER OFSS - MUNICÍPIO', 'Compreende outras reservas que não forem classificadas como reservas de capital ou de lucro. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9325, 1, '4.2.1.1.1.01.00.00.00.00', 'CONTRIBUIÇÕES PATRONAIS AO RPPS', 'Compreende a contribuição patronal destinada ao custeio do Regime Próprio de Previdência Social.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9331, 1, '4.1.0.0.0.00.00.00.00.00', 'IMPOSTOS, TAXAS E CONTRIBUIÇÕES DE MELHORIA', 'Compreende toda prestação pecuniária compulsória, em moeda ou cujo valor nela se possa exprimir, que não constitua sanção de ato ilícito, instituída em lei e cobrada mediante atividade administrativa plenamente vinculada. Como: impostos, taxas e contribuições de melhoria.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9332, 1, '4.1.1.0.0.00.00.00.00.00', 'IMPOSTOS', 'Compreende como imposto o tributo cuja obrigação tem por fato gerador uma situação independente de qualquer atividade estatal especifica, relativa ao contribuinte.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9333, 1, '4.1.1.1.0.00.00.00.00.00', 'IMPOSTOS SOBRE COMERCIO EXTERIOR', 'Compreende os impostos sobre operações de comercio exterior, como por exemplo: impostos sobre a importação e imposto sobre a exportação.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9334, 1, '4.1.1.1.1.00.00.00.00.00', 'IMPOSTOS SOBRE COMERCIO EXTERIOR - CONSOLIDAÇÃO', 'Compreende os impostos sobre operações de comercio exterior, como exemplo: impostos sobre a importação e imposto sobre a exportação. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9335, 1, '4.1.1.2.0.00.00.00.00.00', 'IMPOSTOS SOBRE PATRIMÔNIO E A RENDA', 'Compreende os impostos sobre patrimônio e a renda, como por exemplo: imposto sobre a propriedade territorial rural, imposto sobre a propriedade predial e territorial urbana, imposto sobre a transmissão de bens imóveis e de direitos a eles relativos e impostos sobre a renda e proventos de qualquer natureza.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9336, 1, '4.1.1.2.1.00.00.00.00.00', 'IMPOSTOS SOBRE PATRIMÔNIO E A RENDA - CONSOLIDAÇÃO', 'Compreende os impostos sobre patrimônio e a renda, como exemplo: imposto sobre a propriedade territorial rural,imposto sobre a propriedade predial e territorial urbana,imposto sobre a transmissão de bens imóveis e de direitos a eles relativos e imposto sobre a renda e proventos de qualquer natureza. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9337, 1, '4.1.1.2.1.03.00.00.00.00', 'IMPOSTO SOBRE A RENDA E PROVENTOS DE QUALQUER NATUREZA', 'Registra a variação patrimonial aumentativa decorrente de imposto sobre a renda e proventos de qualquer natureza, retidos na fonte.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9338, 1, '4.1.1.3.0.00.00.00.00.00', 'IMPOSTOS SOBRE A PRODUÇÃO E A CIRCULAÇÃO', 'Compreende os impostos sobre a produção e a circulação, como por exemplo: imposto sobre produtos industrializados; imposto sobre operações de credito, câmbio e seguro, e sobre operações relativas a títulos e valores mobiliários; imposto sobre serviços de qualquer natureza.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9339, 1, '4.1.1.3.1.00.00.00.00.00', 'IMPOSTOS SOBRE A PRODUÇÃO E A CIRCULAÇÃO - CONSOLIDAÇÃO', 'Compreende os impostos sobre a produção e a circulação como, por exemplo, imposto sobre produtos industrializados;imposto sobre operações de crédito, cambio e seguro, e sobre operações relativas a títulos e valores mobiliários, imposto sobre serviços de qualquer natureza.Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9340, 1, '4.1.1.4.0.00.00.00.00.00', 'IMPOSTOS EXTRAORDINÁRIOS', 'Compreende os impostos instituídos pela União, temporariamente, na iminência ou no caso de guerra externa, suprimidos, gradativamente, no prazo Maximo de cinco anos, contados da celebração da paz.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9341, 1, '4.1.1.4.1.00.00.00.00.00', 'IMPOSTOS EXTRAORDINÁRIOS - CONSOLIDAÇÃO', 'Compreende os impostos instituídos pela União, temporariamente, na iminência ou no caso de guerra externa, suprimidos,gradativamente, no prazo Maximo de cinco anos, contados da celebração da paz.Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9342, 1, '4.1.1.9.0.00.00.00.00.00', 'OUTROS IMPOSTOS', 'Compreende os demais impostos não classificados nos grupos anteriores.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9343, 1, '4.1.1.9.1.00.00.00.00.00', 'OUTROS IMPOSTOS - CONSOLIDAÇÃO', 'Compreende os demais impostos não classificados nos grupos anteriores. Compreende os valores de operações efetuadas entre uma unidade pertinente ao orçamento fiscal e da seguridade social (OFSS) com pessoa ou unidade que não pertença ao OFSS de ente público, alem dos demais fatos que não compreendem transações entre partes.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9344, 1, '4.1.2.0.0.00.00.00.00.00', 'TAXAS', 'Compreende as taxas cobradas pela União, pelos estados, pelo distrito federal ou pelos municípios, no âmbito de suas respectivas atribuições, tem como fato gerador o exercício regular do poder de policia, ou a utilização, efetiva ou potencial, de serviço público específico e divisível, prestado ao contribuinte ou posto a sua disposição.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9345, 1, '4.1.2.1.0.00.00.00.00.00', 'TAXAS PELO EXERCÍCIO DO PODER DE POLICIA', 'Compreende as taxas pelo poder de policia aquelas decorrentes das atividades da administração pública que, limitando ou disciplinando direito, interesse ou liberdade, regula a prática de ato ou abstenção de fato, em razão de interesse público.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9346, 1, '4.1.2.1.1.00.00.00.00.00', 'TAXAS PELO EXERCÍCIO DO PODER DE POLICIA - CONSOLIDAÇÃO', 'Compreende as taxas pelo poder de policia aquelas decorrentes das atividades da administração pública que, limitando ou disciplinando direito, interesse ou liberdade, regula a pratica de ato ou abstenção de fato em razão de interesse público. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9347, 1, '4.1.2.1.1.11.00.00.00.00', 'TAXA DE FISCALIZAÇÃO DE VIGILÂNCIA SANITÁRIA', 'Compreende as taxas pelo poder de policia aquelas decorrentes das atividades da administração pública que, limitando ou disciplinando direito, interesse ou liberdade, regula a pratica de ato ou abstenção de fato em razão de interesse público. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) - Taxa de Fiscalização de Vigilância Sanitária.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9348, 1, '4.1.2.1.1.15.00.00.00.00', 'TAXA DE SERVIÇOS ADMINISTRATIVO', 'Compreende as taxas pelo poder de policia aquelas decorrentes das atividades da administração pública que, limitando ou disciplinando direito, interesse ou liberdade, regula a pratica de ato ou abstenção de fato em razão de interesse público. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) - Taxas de Serviços Administrativos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9349, 1, '4.1.2.2.0.00.00.00.00.00', 'TAXAS PELA PRESTAÇÃO DE SERVIÇOS', 'Compreende as taxas cobradas pela União, pelos estados, pelo distrito federal ou pelos municípios, no âmbito de suas respectivas atribuições, tem como fato gerador a utilização, efetiva ou potencial, de serviço público específico e divisível, prestado ao contribuinte ou posto a sua disposição.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9350, 1, '4.2.1.1.4.00.00.00.00.00', 'CONTRIBUIÇÕES SOCIAIS - RPPS - INTER OFSS - ESTADO', 'Compreende a contribuição patronal e a contribuição do segurado destinada ao custeio do regime próprio de previdência social. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9351, 1, '4.1.2.2.1.00.00.00.00.00', 'TAXAS PELA PRESTAÇÃO DE SERVIÇOS - CONSOLIDAÇÃO', 'Compreende as taxas cobradas pela União, pelos estados, pelo distrito federal ou pelos municípios, no âmbito de suas respectivas atribuições tem como fato gerador a utilização, efetiva ou potencial, de serviço público específico e divisível prestado ao contribuinte ou posto a sua disposição. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9352, 1, '4.1.3.0.0.00.00.00.00.00', 'CONTRIBUIÇÕES DE MELHORIA', 'Compreende como contribuição de melhoria o tributo cobrado pela União, pelos estados, pelo distrito federal ou pelos municípios, no âmbito de suas respectivas atribuições, sendo instituída para fazer face ao custo de obras públicas de que decorra valorização imobiliária, tendo como limite total a despesa realizada e como limite individual o acréscimo de valor que da obra resultar para cada imóvel beneficiado.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9353, 1, '4.1.3.1.0.00.00.00.00.00', 'CONTRIBUIÇÃO DE MELHORIA PELA EXPANSÃO DA REDE DE ÁGUA POTÁVEL E ESGOTO SANITÁRIO', 'Compreende o valor da arrecadação de receita de contribuição de melhoria decorrente de valorização de propriedades em função da expansão da rede de água potável e esgoto sanitário.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9354, 1, '4.1.3.1.1.00.00.00.00.00', 'CONTRIBUIÇÃO DE MELHORIA PELA EXPANSÃO DA REDE DE ÁGUA POTÁVEL E ESGOTO SANITÁRIO - CONSOLIDAÇÃO', 'Compreende o valor da arrecadação de receita de contribuição de melhoria decorrente de valorização de propriedade em função da pavimentação asiática, bem como pela colocação de guias, sarjetas e calcamento. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9355, 1, '4.1.3.2.0.00.00.00.00.00', 'CONTRIBUIÇÃO DE MELHORIA PELA EXPANSÃO DA REDE DE ILUMINAÇÃO PÚBLICA NA CIDADE', 'Compreende o valor da arrecadação de receita de contribuição de melhoria decorrente de valorização de propriedades em função da expansão da rede de iluminação pública na cidade.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9356, 1, '4.1.3.2.1.00.00.00.00.00', 'CONTRIBUIÇÃO DE MELHORIA PELA EXPANSÃO DA REDE DE ILUMINAÇÃO PÚBLICA NA CIDADE - CONSOLIDAÇÃO', 'Compreende o valor da arrecadação de receita de contribuição de melhoria decorrente de valorização de propriedades em função da expansão da rede iluminação pública na cidade. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS). Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9357, 1, '4.1.3.3.0.00.00.00.00.00', 'CONTRIBUIÇÃO DE MELHORIA PELA EXPANSÃO DE REDE DE ILUMINAÇÃO PÚBLICA RURAL', 'Compreende o valor da arrecadação de receita sobre a cobrança decorrente de valorização de propriedades em função da expansão da rede de iluminação pública rural.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9358, 1, '4.1.3.3.1.00.00.00.00.00', 'CONTRIBUIÇÃO DE MELHORIA PELA EXPANSÃO DE REDE DE ILUMINAÇÃO PÚBLICA RURAL - CONSOLIDAÇÃO', 'Compreende o valor da arrecadação de receita de contribuição de melhoria decorrente de valorização de propriedades em função da expansão da rede iluminação pública rural. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9359, 1, '4.1.3.4.0.00.00.00.00.00', 'CONTRIBUIÇÃO DE MELHORIA PELA PAVIMENTAÇÃO E OBRAS COMPLEMENTARES', 'Compreende o valor da arrecadação de receita de contribuição de melhoria decorrente de valorização de propriedades em função da pavimentação asfáltica, bem como pela colocação de guias, sarjetas e calçamento.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9360, 1, '4.1.3.4.1.00.00.00.00.00', 'CONTRIBUIÇÃO DE MELHORIA PELA PAVIMENTAÇÃO E OBRAS COMPLEMENTARES - CONSOLIDAÇÃO', 'Compreende o valor da arrecadação de receita de contribuição de melhoria decorrente de valorização de propriedades em função da pavimentação asfáltica, bem como pela colocação de guias, sarjetas e calçamento. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9361, 1, '4.1.3.9.0.00.00.00.00.00', 'OUTRAS CONTRIBUIÇÕES DE MELHORIA', 'Compreende o valor de outras contribuições de melhorias, não classificadas em itens específicos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9362, 1, '4.1.3.9.1.00.00.00.00.00', 'OUTRAS CONTRIBUIÇÕES DE MELHORIA - CONSOLIDAÇÃO', 'Compreende o valor de outras contribuições de melhorias, não classificadas em itens específicos. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9363, 1, '4.2.0.0.0.00.00.00.00.00', 'CONTRIBUIÇÕES', 'Compreende toda prestação pecuniária compulsória, em moeda ou cujo valor nela se possa exprimir, que não constitua sanção de ato ilícito, instituída em lei e cobrada mediante atividade administrativa plenamente vinculada. Como: contribuições.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9364, 1, '4.2.1.0.0.00.00.00.00.00', 'CONTRIBUIÇÕES SOCIAIS', 'Compreendem como contribuições sociais: a) as das empresas, incidentes sobre a remuneração paga ou creditada aos segurados a seu serviço; b) as dos empregadores domésticos; c) as dos trabalhadores, incidentes sobre o seu salário-de-contribuição; d) as sobre a receita e faturamento; e) as sobre o lucro; f) do importador de bens ou serviços do exterior; g) e outros', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9365, 1, '4.2.1.1.0.00.00.00.00.00', 'CONTRIBUIÇÕES SOCIAIS - RPPS', 'Compreende a contribuição patronal e a contribuição do segurado destinada ao custeio do regime próprio de previdência social.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9366, 1, '4.2.1.1.1.00.00.00.00.00', 'CONTRIBUIÇÕES SOCIAIS - RPPS - CONSOLIDAÇÃO', 'Compreende a contribuição patronal e a contribuição do segurado destinada ao custeio do regime próprio de previdência social. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9367, 1, '4.2.1.1.1.02.00.00.00.00', 'CONTRIBUIÇÃO DO SEGURADO AO RPPS', 'Compreende a contribuição ao RPPS dos segurados, servidor ativo, servidor inativo e pensionista sobre a sua remuneração.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9368, 1, '4.2.1.1.2.00.00.00.00.00', 'CONTRIBUIÇÕES SOCIAIS - RPPS - INTRA OFSS', 'Compreende a contribuição patronal e a contribuição do segurado destinada ao custeio do regime próprio de previdência social. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do ente.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9370, 1, '4.2.1.1.3.00.00.00.00.00', 'CONTRIBUIÇÕES SOCIAIS - RPPS - INTER OFSS - UNIÃO', 'Compreende a contribuição patronal e a contribuição do segurado destinada ao custeio do regime próprio de previdência social. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9371, 1, '4.2.1.1.3.01.00.00.00.00', 'CONTRIBUIÇÕES PATRONAIS AO RPPS', 'Compreende a contribuição patronal destinada ao custeio do regime proprio de previdencia social.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9372, 1, '4.2.1.1.5.00.00.00.00.00', 'CONTRIBUIÇÕES SOCIAIS - RPPS - INTER OFSS - MUNICÍPIO', 'Compreende a contribuição patronal e a contribuição do segurado destinada ao custeio do regime próprio de previdência social. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9373, 1, '4.2.1.1.5.01.00.00.00.00', 'CONTRIBUIÇÕES PATRONAIS AO RPPS', 'Compreende a contribuicao patronal destinada ao custeio do regime proprio de previdencia social.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9374, 1, '4.2.1.2.0.00.00.00.00.00', 'CONTRIBUIÇÕES SOCIAIS - RGPS', 'Compreende a contribuição patronal e a contribuição do segurado destinada ao custeio do regime geral de previdência social.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9375, 1, '4.2.1.2.1.00.00.00.00.00', 'CONTRIBUIÇÕES SOCIAIS - RGPS - CONSOLIDAÇÃO', 'Compreende a contribuição patronal e a contribuição do segurado destinada ao custeio do regime geral de previdência social. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9376, 1, '4.2.1.2.2.00.00.00.00.00', 'CONTRIBUIÇÕES SOCIAIS - RGPS - INTRA OFSS', 'Compreende a contribuição patronal e a contribuição do segurado destinada ao custeio do regime geral de previdência social. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do ente.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9377, 1, '4.2.1.2.3.00.00.00.00.00', 'CONTRIBUIÇÕES SOCIAIS - RGPS - INTER OFSS - UNIÃO', 'Compreende a contribuição patronal e a contribuição do segurado destinada ao custeio do regime geral de previdência social. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9378, 1, '4.2.1.2.4.00.00.00.00.00', 'CONTRIBUIÇÕES SOCIAIS - RGPS - INTER OFSS - ESTADO', 'Compreende a contribuição patronal e a contribuição do segurado destinada ao custeio do regime geral de previdência social. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9379, 1, '4.2.1.2.5.00.00.00.00.00', 'CONTRIBUIÇÕES SOCIAIS - RGPS - INTER OFSS - MUNICÍPIO', 'Compreende a contribuição patronal e a contribuição do segurado destinada ao custeio do regime geral de previdência social. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9380, 1, '4.2.1.3.0.00.00.00.00.00', 'CONTRIBUIÇÃO SOBRE A RECEITA OU O FATURAMENTO', 'Compreende a contribuição do empregador, da empresa e da entidade a ela equiparada na forma da lei, incidentes sobre a receita ou o faturamento, como por exemplo: COFINS, PIS/PASEP.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9381, 1, '4.2.1.3.1.00.00.00.00.00', 'CONTRIBUIÇÃO SOBRE A RECEITA OU O FATURAMENTO - CONSOLIDAÇÃO', 'Compreende a contribuição do empregador, da empresa e da entidade a ela equiparada na forma da lei, incidentes sobre a receita ou o faturamento, como por exemplo: COFINS, PIS/PASEP. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9382, 1, '4.2.1.4.0.00.00.00.00.00', 'CONTRIBUIÇÃO SOBRE O LUCRO', 'Compreende a contribuição do empregador, da empresa e da entidade a ela equiparada na forma da lei, incidentes sobre o lucro, como por exemplo: CSLL.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9383, 1, '4.2.1.4.1.00.00.00.00.00', 'CONTRIBUIÇÃO SOBRE O LUCRO - CONSOLIDAÇÃO', 'Registra a contribuição do empregador,da empresa e da entidade a ela equiparada na forma da lei, incidentes sobre o lucro, como por exemplo: CSLL. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9384, 1, '4.2.1.5.0.00.00.00.00.00', 'CONTRIBUIÇÃO SOBRE RECEITA DE CONCURSO DE PROGNOSTICO', 'Compreende a contribuição sobre a receita de concursos de prognósticos, que são todos e quaisquer concursos de sorteios de números, loterias, apostas, inclusive as realizadas em reuniões hípicas, nos âmbitos federal, estadual, do Distrito Federal e municipais.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9385, 1, '4.2.1.5.1.00.00.00.00.00', 'CONTRIBUIÇÃO SOBRE RECEITA DE CONCURSO DE PROGNOSTICO - CONSOLIDAÇÃO', 'Compreende a contribuição sobre a receita de concursos de prognósticos, que são todos e quaisquer concursos de sorteios de números, loterias, apostas, inclusive as realizadas em reuniões hípicas, nos âmbitos federal, estadual, do Distrito Federal e municipais. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS). Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9386, 1, '4.2.1.6.0.00.00.00.00.00', 'CONTRIBUIÇÃO DO IMPORTADOR DE BENS OU SERVIÇOS DO EXTERIOR', 'Compreende a contribuição social paga pelo importador de bens ou serviços do exterior, ou de quem a lei a ele equiparar.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9387, 1, '4.2.1.6.1.00.00.00.00.00', 'CONTRIBUIÇÃO DO IMPORTADOR DE BENS OU SERVIÇOS DO EXTERIOR - CONSOLIDAÇÃO', 'Compreende a contribuição social paga pelo importador de bens ou serviços do exterior, ou de quem a lei a ele equiparar. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9388, 1, '4.2.1.7.0.00.00.00.00.00', 'CONTRIBUIÇÃO SOCIAL PARA O SISTEMA DE PAGAMENTO DE PENSÕES MILITARES', 'Compreende a contribuição social para custeio de pensões militares, efetivas por todos os militares, com valor correspondente a seu posto ou graduação, observando as exceções previstas na lei específica, de competência da União e dos estados.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9427, 1, '4.4.2.0.0.00.00.00.00.00', 'JUROS E ENCARGOS DE MORA', 'Compreende as variações patrimoniais aumentativas com penalidades pecuniárias decorrentes da inobservância de normas e com rendimentos destinados a indenização pelo atraso no cumprimento da obrigação representando o resultado das aplicações impostas ao contribuinte.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9389, 1, '4.2.1.7.2.00.00.00.00.00', 'CONTRIBUIÇÃO SOCIAL PARA O SISTEMA DE PAGAMENTO DE PENSÕES MILITARES - INTRA OFSS', 'Compreende a contribuição social para custeio de pensões militares, efetivas por todos os militares, com valor correspondente a seu posto ou graduação, observando as exceções previstas na lei específica, de competência da União e dos estados. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do ente.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9390, 1, '4.2.1.9.1.00.00.00.00.00', 'OUTRAS CONTRIBUIÇÕES SOCIAIS - CONSOLIDAÇÃO', 'Compreende o valor de outras contribuições sociais, não classificadas em itens específicos. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9391, 1, '4.2.2.0.0.00.00.00.00.00', 'CONTRIBUIÇÕES DE INTERVENÇÃO NO DOMÍNIO ECONÔMICO', 'Compreendem as contribuições de intervenção no domínio econômico, como por exemplo, a CIDE-combustível.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9392, 1, '4.2.2.0.1.00.00.00.00.00', 'CONTRIBUIÇÕES DE INTERVENÇÃO NO DOMÍNIO ECONÔMICO - CONSOLIDAÇÃO', 'Compreendem as contribuições de intervenção no domínio econômico, como por exemplo, a CIDE combustível. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9393, 1, '4.2.3.0.0.00.00.00.00.00', 'CONTRIBUIÇÃO DE ILUMINAÇÃO PÚBLICA', 'Compreende as contribuições de iluminação pública, nos termos do artigo 149-a da constituição federal, acrescentado pela emenda constitucional n.ºª 39/02, sendo facultada a cobrança da contribuição na fatura de consumo de energia elétrica.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9394, 1, '4.2.3.0.1.00.00.00.00.00', 'CONTRIBUIÇÃO DE ILUMINAÇÃO PÚBLICA - CONSOLIDAÇÃO', 'Compreende as contribuições de iluminação pública, nos termos do artigo 149-a da constituição federal, acrescentado pela emenda constitucional n.ºª 39/02, sendo facultada a cobrança da contribuição na fatura de consumo de energia elétrica. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
