insert into contabilidade.planocontadetalhe values (9396, 1, '4.2.4.0.1.00.00.00.00.00', 'CONTRIBUIÇÕES DE INTERESSE DAS CATEGORIAS PROFISSIONAIS - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais aumentativas provenientes de contribuições de interesse das categorias profissionais. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9397, 1, '4.3.0.0.0.00.00.00.00.00', 'EXPLORAÇÃO E VENDA DE BENS, SERVIÇOS E DIREITOS', 'Compreende as variações patrimoniais aumentativas auferidas com a exploração e venda de bens, serviços e direitos, que resultem em aumento do patrimônio liquido, independentemente de ingresso, segregando-se a venda bruta das deduções como devoluções, abatimentos e descontos comerciais concedidos.', 2, false, 0, 'N');
