insert into contabilidade.planocontadetalhe values (9411, 1, '4.4.0.0.0.00.00.00.00.00', 'VARIAÇÕES PATRIMONIAIS AUMENTATIVAS FINANCEIRAS', 'Compreende o somatório das variações patrimoniais aumentativas com operações financeiras. Compreende: descontos obtidos, juros auferidos, prêmio de resgate de títulos e debêntures, entre outros.', 2, false, 0, 'N');
