insert into contabilidade.planocontadetalhe values (9441, 1, '4.4.2.9.0.00.00.00.00.00', 'OUTROS JUROS E ENCARGOS DE MORA', 'Compreende as outras variações patrimoniais aumentativas decorrentes de juros e multas com penalidades pecuniárias decorrentes da inobservância de normas e com rendimentos destinados a indenização pelo atraso no cumprimento da obrigação.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9442, 1, '4.4.2.9.1.00.00.00.00.00', 'OUTROS JUROS E ENCARGOS DE MORA - CONSOLIDAÇÃO', 'Compreende as outras variações patrimoniais aumentativas decorrentes de juros e multas com penalidades pecuniárias decorrentes da inobservância de normas e com rendimentos destinados a indenização pelo atraso no cumprimento da obrigação. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9606, 1, '4.9.7.2.1.00.00.00.00.00', 'REVERSÃO DE AJUSTES DE PERDAS - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais aumentativas provenientes de reversões de ajustes de perdas. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9443, 1, '4.4.3.0.0.00.00.00.00.00', 'VARIAÇÕES MONETÁRIAS E CAMBIAIS', 'Compreende a variação patrimonial aumentativa proveniente de variações da nossa própria moeda em relação aos índices ou coeficientes aplicáveis por dispositivo legal ou contratual e a variação do valor da nossa moeda em relação às moedas estrangeiras. Ressalte-se que será tratada como variação monetária apenas a correção monetária pós-fixada.', 2, false, 0, 'N');
