insert into contabilidade.planocontadetalhe values (9445, 1, '6.3.2.0.0.00.00.00.00.00', 'EXECUÇÃO DE RP PROCESSADOS', 'Compreende o somatório dos valores relativos à transferência, liquidação e pagamento das despesas empenhadas, liquidadas no exercício financeiro de sua inscrição e não pagas.', 2, false, 0, 'N');
