insert into contabilidade.planocontadetalhe values (9456, 1, '4.4.3.3.4.00.00.00.00.00', 'VARIAÇÕES MONETÁRIAS E CAMBIAIS DE FINANCIAMENTOS INTERNOS CONCEDIDOS - INTER OFSS - ESTADO', 'Compreende a variação patrimonial aumentativa proveniente de variações da nossa própria moeda em relação aos índices ou coeficientes aplicáveis por dispositivo legal ou contratual e a variação do valor da nossa moeda em relação às moedas estrangeiras referentes aos financiamentos internos concedidos. Ressalte-se que será tratada como variação monetária apenas a correção monetária pós-fixada. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9457, 1, '4.4.5.2.0.00.00.00.00.00', 'REMUNERAÇÃO DE APLICAÇÕES FINANCEIRAS', 'Compreende a variação patrimonial aumentativa proveniente da remuneração de depósitos bancários, recursos oriundos de aplicações de entidades da administração pública no mercado financeiro, autorizadas por lei, em caderneta de poupança, fundo de investimento, contas remuneradas e outros.', 2, false, 0, 'N');
