insert into contabilidade.planocontadetalhe values (9460, 1, '4.4.3.4.1.00.00.00.00.00', 'VARIAÇÕES MONETÁRIAS E CAMBIAIS DE FINANCIAMENTOS EXTERNOS CONCEDIDOS - CONSOLIDAÇÃO', 'Compreende a variação patrimonial aumentativa proveniente de variações da nossa própria moeda em relação aos índices ou coeficientes aplicáveis por dispositivo legal ou contratual e a variação do valor da nossa moeda em relação às moedas estrangeiras referentes aos financiamentos externos concedidos. Ressalte-se que será tratada como variação monetária apenas a correção monetária pós-fixada. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9461, 1, '4.9.0.0.0.00.00.00.00.00', 'OUTRAS VARIAÇÕES PATRIMONIAIS AUMENTATIVAS', 'Compreende o somatório das demais variações patrimoniais aumentativas não incluídas nos grupos anteriores, tais como: resultado positivo da equivalência patrimonial, dividendos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9462, 1, '4.4.3.9.0.00.00.00.00.00', 'OUTRAS VARIAÇÕES MONETÁRIAS E CAMBIAIS', 'Compreende a variação patrimonial aumentativa proveniente de variações da nossa própria moeda em relação aos índices ou coeficientes aplicáveis por dispositivo legal ou contratual e a variação do valor da nos moeda em relação às moedas estrangeiras, com exceção de empréstimos e financiamentos concedidos. Ressalte-se que será tratada como variação monetária apenas a correção monetária pós-fixada.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9463, 1, '4.4.3.9.1.00.00.00.00.00', 'OUTRAS VARIAÇÕES MONETÁRIAS E CAMBIAIS - CONSOLIDAÇÃO', 'Compreende a variação patrimonial aumentativa proveniente de variações da nossa própria moeda em relação aos índices ou coeficientes aplicáveis por dispositivo legal ou contratual e a variação do valor da nossa moeda em relação às moedas estrangeiras, com exceção de empréstimos e financiamentos concedidos. Ressalte-se que será tratada como variação monetária apenas a correção monetária pós-fixada. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
