insert into contabilidade.planocontadetalhe values (9468, 1, '4.4.4.0.0.00.00.00.00.00', 'DESCONTOS FINANCEIROS OBTIDOS', 'Compreende a variação patrimonial aumentativa decorrente de descontos financeiros obtidos em virtude de liquidação antecipada de obrigações.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9469, 1, '4.4.4.0.1.00.00.00.00.00', 'DESCONTOS FINANCEIROS OBTIDOS - CONSOLIDAÇÃO', 'Registra a variação patrimonial aumentativa decorrente de descontos financeiros obtidos em virtude de liquidação antecipada de obrigações. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9470, 1, '4.4.5.0.0.00.00.00.00.00', 'REMUNERAÇÃO DE DEPÓSITOS BANCÁRIOS E APLICAÇÕES FINANCEIRAS', 'Compreende o valor total das variações patrimoniais aumentativas decorrentes da remuneração do saldo diário dos depósitos da União existentes no banco central, bem como aplicação de recursos da conta única de acordo com a rentabilidade media intrínseca dos títulos do Tesouro.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9471, 1, '4.4.5.1.0.00.00.00.00.00', 'REMUNERAÇÃO DE DEPÓSITOS BANCÁRIOS', 'Compreende a variação patrimonial aumentativa decorrente da remuneração dos depósitos bancários do ente existentes no agente financeiro.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9472, 1, '4.6.3.0.0.00.00.00.00.00', 'GANHOS COM INCORPORAÇÃO DE ATIVOS', 'Compreende a contrapartida da incorporação de novos ativos descobertos, a contrapartida da incorporação de ativos semoventes nascidos, por exemplo.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9473, 1, '4.4.5.2.1.00.00.00.00.00', 'REMUNERAÇÃO DE APLICAÇÕES FINANCEIRAS - CONSOLIDAÇÃO', 'Registra a variação patrimonial aumentativa proveniente da remuneração de depósitos bancários, recursos oriundos de aplicações de entidades da administração pública no mercado financeiro, autorizadas por lei, em caderneta de poupança, fundo de investimento, contas remuneradas e outros. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9474, 1, '4.4.8.0.0.00.00.00.00.00', 'APORTES DO BANCO CENTRAL', 'Compreende os aportes de recursos do Banco Central do Brasil ao Tesouro Nacional. Conta de uso exclusivo da União.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9475, 1, '4.4.8.1.0.00.00.00.00.00', 'RESULTADO POSITIVO DO BANCO CENTRAL', 'Compreende a incorporação do resultado positivo do Banco Central do Brasil, conforme art. 7º da Lei Complementar 101, de 4/5/2000. ', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9476, 1, '4.4.8.1.1.00.00.00.00.00', 'RESULTADO POSITIVO DO BANCO CENTRAL - CONSOLIDAÇÃO', 'Registra a incorporação do resultado positivo do Banco Central do Brasil, conforme art. 7º da Lei Complementar 101, de 4/5/2000. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9477, 1, '4.4.9.0.0.00.00.00.00.00', 'OUTRAS VARIAÇÕES PATRIMONIAIS AUMENTATIVAS - FINANCEIRAS', 'Compreende as variações patrimoniais aumentativas provenientes de operações financeiras não compreendidas nos subgrupos anteriores.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9478, 1, '4.5.3.1.0.00.00.00.00.00', 'TRANSFERÊNCIAS DAS INSTITUIÇÕES PRIVADAS SEM FINS LUCRATIVOS', 'Compreende as variações patrimoniais aumentativas decorrentes das transferências financeiras das instituições privadas sem fins lucrativos, inclusive de bens e valores. Exemplo: ONGs, OSCIPS e OS.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9479, 1, '4.4.9.0.1.00.00.00.00.00', 'OUTRAS VARIAÇÕES PATRIMONIAIS AUMENTATIVAS - FINANCEIRAS - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais aumentativas provenientes de operações financeiras não compreendidas nos subgrupos anteriores. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9480, 1, '4.5.0.0.0.00.00.00.00.00', 'TRANSFERÊNCIAS E DELEGAÇÕES RECEBIDAS', 'Compreende o somatório das variações patrimoniais aumentativas com transferências inter governamentais, transferências intragovernamentais, transferências de instituições multigovernamentais, transferências de instituições privadas com ou sem fins lucrativos, transferências de convênios, transferências do exterior e execuções orçamentárias delegadas.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9481, 1, '4.5.1.0.0.00.00.00.00.00', 'TRANSFERÊNCIAS INTRAGOVERNAMENTAIS', 'Compreende as variações patrimoniais aumentativas decorrentes das transferências financeiras relativas à execução orçamentária, e de bens e valores, referentes às transações intragovernamentais.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9482, 1, '4.5.1.1.0.00.00.00.00.00', 'TRANSFERÊNCIAS RECEBIDAS PARA A EXECUÇÃO ORÇAMENTÁRIA', 'Compreende o valor das transferências financeiras recebidas e correspondência de créditos em virtude da execução orçamentária (cota, repasse e sub-repasse). Não Inclui o valor repassado para aportes no RPPS ou RGPS.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9483, 1, '4.5.1.1.2.00.00.00.00.00', 'TRANSFERÊNCIAS RECEBIDAS PARA A EXECUÇÃO ORÇAMENTÁRIA - INTRA OFSS', 'Compreende o valor das transferências financeiras recebidas e correspondência de créditos em virtude da execução orçamentária (cota, repassse e sub-repasse).Não Inclui o valor repassado para aportes no RPPS ou RGPS.Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do ente.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9484, 1, '4.5.1.2.0.00.00.00.00.00', 'TRANSFERÊNCIAS RECEBIDAS INDEPENDENTES DE EXECUÇÃO ORÇAMENTÁRIA', 'Compreende o valor das transferências, de bens ou valores, financeiras recebidas para restos a pagar e outras finalidades independentes da execução orçamentária.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9485, 1, '4.5.1.2.2.00.00.00.00.00', 'TRANSFERÊNCIAS RECEBIDAS INDEPENDENTES DE EXECUÇÃO ORÇAMENTÁRIA - INTRA OFSS', 'Compreende o valor das transferências financeiras, de bens ou valores, recebidas para restos a pagar e outras finalidades independentes da execução orçamentária. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do ente.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9488, 1, '4.5.1.3.2.02.00.00.00.00', 'PLANO PREVIDENCIÁRIO', 'Compreende o valor total recebido pelo RPPS para cobertura de déficit financeiro ou atuarial e outros aportes, no âmbito do plano previdenciário.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9642, 1, '6.2.2.2.2.01.00.00.00.00', 'ADMINISTRAÇÃO DIRETA         ', 'Compreende o valor referente ao movimento de créditos decorrentes de concessão pela unidade orçamentária do órgão da administração direta transferidora.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9490, 1, '4.5.1.4.2.00.00.00.00.00', 'TRANSFERÊNCIAS RECEBIDAS PARA APORTES DE RECURSOS PARA O RGPS  - INTRA OFSS', 'Compreende o valor das transferências recebidas para os aportes financeiros da União para a cobertura de déficits financeiros ou atuariais do RGPS. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do ente.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9491, 1, '4.5.1.4.2.01.00.00.00.00', 'RECURSOS PARA COBERTURA DE INSUFICIÊNCIAS FINANCEIRAS', 'Compreende os recursos orçamentários efetivamente utilizados para a cobertura de insuficiências financeiras entre as receitas e despesas previdenciárias no exercício de referência.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9492, 1, '4.5.1.5.0.00.00.00.00.00', 'TRANSFERÊNCIAS RECEBIDAS PARA APORTES DE RECURSOS PARA O SISTEMA DE PAGAMENTO DE PENSÕES MILITARES', 'Compreende o valor das transferências recebidas para os aportes financeiros do ente para cobertura de insuficiências financeiras, formação de reserva e cobertura de déficits financeiros ou atuariais do regime dos militares e outros aportes, exceto os decorrentes de alíquota de contribuição suplementar.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9493, 1, '4.6.2.2.1.02.00.00.00.00', 'GANHO LÍQUIDO COM A ALIENAÇÃO DE BENS IMÓVEIS', 'Compreende o ganho com alienação de ativo imobilizado, ou seja, quando o valor alienado do referido ativo e maior que o seu valor contábil, de maneira que a diferença compreende o ganho - Ganho Líquido com a Alienação de Bens Imóveis.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9494, 1, '4.5.1.5.2.00.00.00.00.00', 'TRANSFERÊNCIAS RECEBIDAS PARA APORTES DE RECURSOS PARA O SISTEMA DE PAGAMENTO DE PENSÕES MILITARES  - INTRA OFSS', 'Compreende o valor das transferências recebidas para os aportes financeiros do ente para cobertura de insuficiências financeiras, formação de reserva e cobertura de déficits financeiros ou atuariais do regime dos militares e outros aportes, exceto os decorrentes de alíquota de contribuição suplementar.Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do ente.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9495, 1, '4.5.2.0.0.00.00.00.00.00', 'TRANSFERÊNCIAS INTER GOVERNAMENTAIS', 'Compreende as variações patrimoniais aumentativas decorrentes de transferências da União, estados, distrito federal, municípios, inclusive as entidades vinculadas, de bens e/ou valores.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9496, 1, '4.5.2.1.0.00.00.00.00.00', 'TRANSFERÊNCIAS CONSTITUCIONAIS E LEGAIS DE RECEITAS', 'Compreende as variações patrimoniais aumentativas decorrentes da transferência de outras esferas de governo de receitas tributárias, de contribuições e de outras receitas vinculadas, prevista na Constituição ou em leis específicas, cuja competência de arrecadação é do órgão transferidor.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9497, 1, '4.5.2.1.1.00.00.00.00.00', 'TRANSFERÊNCIAS CONSTITUCIONAIS E LEGAIS  DE RECEITAS- CONSOLIDAÇÃO', 'Registra as variações patrimoniais aumentativas decorrentes da transferência de outras esferas de governo de receitas tributárias, de contribuições e de outras receitas vinculadas, prevista na Constituição ou em leis específicas, cuja competência de arrecadação é do órgão transferidor. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS). Por exemplo, empresa independente de um ente recebendo transferência de outro ente (a empresa independente não pertence ao OFSS mas pertence ao conceito de governamental).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9498, 1, '4.5.3.1.1.00.00.00.00.00', 'TRANSFERÊNCIAS DAS INSTITUIÇÕES PRIVADAS SEM FINS LUCRATIVOS - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais aumentativas decorrentes das transferências financeiras das instituições privadas sem fins lucrativos, inclusive de bens e valores. Exemplo: ONGs, OSCIPS e OS. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9499, 1, '4.5.2.1.3.00.00.00.00.00', 'TRANSFERÊNCIAS CONSTITUCIONAIS E LEGAIS DE RECEITAS - INTER OFSS - UNIÃO', 'Compreende as variações patrimoniais aumentativas decorrentes da transferência de outras esferas de governo de receitas tributárias, de contribuições e de outras receitas vinculadas, prevista na Constituição ou em leis específicas, cuja competência de arrecadação é do órgão transferidor. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9500, 1, '4.5.2.1.4.00.00.00.00.00', 'TRANSFERÊNCIAS CONSTITUCIONAIS E LEGAIS DE RECEITAS - INTER OFSS - ESTADO', 'Compreendem as variações patrimoniais aumentativas decorrentes da transferência de outras esferas de governo de receitas tributárias, de contribuições e de outras receitas vinculadas, prevista na Constituição ou em leis específicas, cuja competência de arrecadação é do órgão transferidor. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9501, 1, '4.5.2.2.0.00.00.00.00.00', 'TRANSFERÊNCIAS DO FUNDEB', 'Compreende as variações patrimoniais aumentativas decorrentes da recursos recebidos do Fundo de Manutenção e Desenvolvimento da Educação Básica e de Valorização dos Profissionais da Educação, instituído pela E.C. n.º 53/2006 e regulamentado pela lei 11.494/2007.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9502, 1, '4.5.2.2.3.00.00.00.00.00', 'TRANSFERÊNCIAS DO FUNDEB -INTER OFSS - UNIÃO', 'Registra as variações patrimoniais aumentativas decorrentes de recursos recebidos do Fundo de Manutenção e Desenvolvimento da Educação Básica e de Valorização dos Profissionais da Educação, instituído pela E.C. n.º 53/2006 e regulamentado pela lei 11.494/2007, decorrentes de complementação da União. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9503, 1, '4.5.2.2.4.00.00.00.00.00', 'TRANSFERÊNCIAS DO FUNDEB  - INTER OFSS - ESTADO', 'Registra as variações patrimoniais aumentativas decorrentes da recursos recebidos do Fundo de Manutenção e Desenvolvimento da Educação Básica e de Valorização dos Profissionais da Educação, instituído pela E.C. n.º 53/2006 e regulamentado pela lei 11.494/2007. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9504, 1, '4.5.2.3.0.00.00.00.00.00', 'TRANSFERÊNCIAS VOLUNTÁRIAS', 'Compreendem as variações patrimoniais aumentativas decorrentes de transferências voluntárias da União, estados, Distrito Federal, municípios, inclusive das entidades vinculadas, bem como as demais entidades, de bens e/ou valores.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9643, 1, '6.2.2.2.2.02.00.00.00.00', 'ADMINISTRAÇÃO INDIRETA                    ', 'Compreende o valor referente ao movimento de créditos decorrentes de concessão pela unidade orçamentária da entidade da administração indireta transferidora.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9505, 1, '4.5.2.3.1.00.00.00.00.00', 'TRANSFERÊNCIAS VOLUNTÁRIAS - CONSOLIDAÇÃO', 'Registra as variações patrimoniais aumentativas decorrentes de transferências voluntárias da União, estados, Distrito Federal, municípios, inclusive das entidades vinculadas, bem como as demais entidades, de bens e/ou valores. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9506, 1, '4.5.2.3.3.00.00.00.00.00', 'TRANSFERÊNCIAS VOLUNTÁRIAS - INTER OFSS - UNIÃO', 'Compreendem as variações patrimoniais aumentativas decorrentes de transferências voluntárias da União, estados, Distrito Federal, municípios, inclusive das entidades vinculadas, bem como as demais entidades, de bens e/ou valores. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9507, 1, '4.5.2.3.4.00.00.00.00.00', 'TRANSFERÊNCIAS VOLUNTÁRIAS - INTER OFSS - ESTADO', 'Compreendem as variações patrimoniais aumentativas decorrentes de transferências voluntárias da União, estados, Distrito Federal, municípios, inclusive das entidades vinculadas, bem como as demais entidades, de bens e/ou valores. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9508, 1, '4.6.2.3.0.00.00.00.00.00', 'GANHOS COM ALIENAÇÃO DE INTANGÍVEIS', 'Compreende o ganho com alienação de ativos intangíveis, ou seja, quando o valor alienado do referido ativo e maior que o seu valor contábil, de maneira que a diferença compreende o ganho.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9509, 1, '4.5.2.3.5.00.00.00.00.00', 'TRANSFERÊNCIAS VOLUNTÁRIAS - INTER OFSS - MUNICÍPIO', 'Compreendem as variações patrimoniais aumentativas decorrentes de transferências voluntárias da União, estados, Distrito Federal, municípios, inclusive das entidades vinculadas, bem como as demais entidades, de bens e/ou valores. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9510, 1, '4.5.2.4.0.00.00.00.00.00', 'OUTRAS TRANSFERÊNCIAS', 'Compreendem as variações patrimoniais aumentativas decorrentes de demais transferências da união, estados, Distrito Federal, municípios, inclusive as entidades vinculadas, de bens e/ou valores.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9511, 1, '4.5.2.4.1.00.00.00.00.00', 'OUTRAS TRANSFERÊNCIAS - CONSOLIDAÇÃO', 'Registra as variações patrimoniais aumentativas decorrentes de demais transferências da união, estados, Distrito Federal, municípios, inclusive das entidades vinculadas, de bens e/ou valores. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9512, 1, '4.5.2.4.3.00.00.00.00.00', 'OUTRAS TRANSFERÊNCIAS - INTER OFSS - UNIÃO', 'Registra as variações patrimoniais aumentativas decorrentes de demais transferências da união, estados, Distrito Federal, municípios, inclusive das entidades vinculadas, de bens e/ou valores. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9513, 1, '4.5.2.4.4.00.00.00.00.00', 'OUTRAS TRANSFERÊNCIAS - INTER OFSS - ESTADO', 'Registra as variações patrimoniais aumentativas decorrentes de demais transferências da união, estados, Distrito Federal, municípios, inclusive das entidades vinculadas, de bens e/ou valores. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9514, 1, '4.5.2.4.5.00.00.00.00.00', 'OUTRAS TRANSFERÊNCIAS - INTER OFSS - MUNICÍPIO', 'Registra as variações patrimoniais aumentativas decorrentes de demais transferências da união, estados, Distrito Federal, municípios, inclusive das entidades vinculadas, de bens e/ou valores. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9515, 1, '4.5.3.0.0.00.00.00.00.00', 'TRANSFERÊNCIAS DAS INSTITUIÇÕES PRIVADAS', 'Compreende as variações patrimoniais aumentativas decorrentes das transferências financeiras das instituições privadas, inclusive de bens e valores.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9516, 1, '4.5.3.2.1.00.00.00.00.00', 'TRANSFERÊNCIAS DAS INSTITUIÇÕES PRIVADAS COM FINS LUCRATIVOS - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais aumentativas decorrentes das transferências financeiras das instituições privadas com fins lucrativos, inclusive de bens e valores. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9517, 1, '4.5.4.0.0.00.00.00.00.00', 'TRANSFERÊNCIAS DAS INSTITUIÇÕES MULTIGOVERNAMENTAIS', 'Compreende as variações patrimoniais aumentativas decorrentes das transferências das instituições multigovernamentais, das quais o ente recebedor não participe.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9518, 1, '4.5.4.0.1.00.00.00.00.00', 'TRANSFERÊNCIAS DAS INSTITUIÇÕES MULTIGOVERNAMENTAIS - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais aumentativas decorrentes das transferências das instituições multigovernamentais, das quais o ente recebedor não participe. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9519, 1, '4.5.5.0.0.00.00.00.00.00', 'TRANSFERÊNCIAS DE CONSÓRCIOS PÚBLICOS', 'Compreende as variações patrimoniais aumentativas decorrentes das transferências de consórcios públicos, dos quais o ente recebedor participe.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9520, 1, '4.5.5.0.1.00.00.00.00.00', 'TRANSFERÊNCIAS DE CONSÓRCIOS PÚBLICOS - CONSOLIDAÇÃO', 'Registra as variações patrimoniais aumentativas decorrentes das transferências de consórcios públicos, dos quais o ente recebedor participe. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9521, 1, '4.5.6.0.0.00.00.00.00.00', 'TRANSFERÊNCIAS DO EXTERIOR', 'Compreende as variações patrimoniais aumentativas decorrentes de transferências de organismos e fundos internacionais, de governos estrangeiros e instituições privadas com ou sem fins lucrativos no exterior.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9522, 1, '4.5.6.0.1.00.00.00.00.00', 'TRANSFERÊNCIAS DO EXTERIOR - CONSOLIDAÇÃO', 'Registra as variações patrimoniais aumentativas decorrentes de transferências de organismos e fundos internacionais, de governos estrangeiros e instituições privadas com ou sem fins lucrativos no exterior. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9523, 1, '4.5.7.0.0.00.00.00.00.00', 'EXECUÇÃO ORÇAMENTÁRIA DELEGADA', 'Compreende as variações patrimoniais aumentativas decorrentes de transferência de recursos financeiros, decorrentes de delegação ou descentralização dos Entes (União, Estados, Distrito Federal ou Municípios) ou Consórcios Públicos para execução de ações de responsabilidade exclusiva do delegante.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9524, 1, '4.5.7.1.0.00.00.00.00.00', 'EXECUÇÃO ORÇAMENTÁRIA DELEGADA DE ENTES', 'Compreende as variações patrimoniais aumentativas decorrentes de transferência de recursos financeiros, decorrentes de delegação ou descentralização dos Entes (União, Estados, Distrito Federal ou Municípios) para execução de ações de responsabilidade exclusiva do delegante.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9525, 1, '4.5.7.1.3.00.00.00.00.00', 'EXECUÇÃO ORÇAMENTÁRIA DELEGADA DE ENTES - INTER OFSS - UNIÃO', 'Compreende as variações patrimoniais aumentativas decorrentes de transferência de recursos financeiros, decorrentes de delegação ou descentralização dos Entes (União, Estados, Distrito Federal ou Municípios) para execução de ações de responsabilidade exclusiva do delegante. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9526, 1, '4.5.7.1.4.00.00.00.00.00', 'EXECUÇÃO ORÇAMENTÁRIA DELEGADA DE ENTES - INTER OFSS - ESTADO', 'Compreende as variações patrimoniais aumentativas decorrentes de transferência de recursos financeiros, decorrentes de delegação ou descentralização dos Entes (União, Estados, Distrito Federal ou Municípios) para execução de ações de responsabilidade exclusiva do delegante. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9527, 1, '4.5.7.1.5.00.00.00.00.00', 'EXECUÇÃO ORÇAMENTÁRIA DELEGADA DE ENTES - INTER OFSS - MUNICÍPIO', 'Compreende as variações patrimoniais aumentativas decorrentes de transferência de recursos financeiros, decorrentes de delegação ou descentralização dos Entes (União, Estados, Distrito Federal ou Municípios) para execução de ações de responsabilidade exclusiva do delegante. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9528, 1, '4.5.7.2.0.00.00.00.00.00', 'EXECUÇÃO ORÇAMENTÁRIA DELEGADA DE CONSÓRCIOS', 'Compreende as variações patrimoniais aumentativas decorrentes de transferência de recursos financeiros, decorrentes de delegação ou descentralização de Consórcios Públicos para execução de ações de responsabilidade exclusiva do delegante.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9529, 1, '4.5.7.2.1.00.00.00.00.00', 'EXECUÇÃO ORÇAMENTÁRIA DELEGADA DE CONSÓRCIOS - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais aumentativas decorrentes de transferência de recursos financeiros, decorrentes de delegação ou descentralização de Consórcios Públicos para execução de ações de responsabilidade exclusiva do delegante. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9530, 1, '4.5.8.0.0.00.00.00.00.00', 'TRANSFERÊNCIAS DE PESSOAS FÍSICAS', 'Compreende as variações patrimoniais aumentativas decorrentes de contribuições e doações a governos e entidades da administração descentralizada realizadas por pessoas físicas.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9531, 1, '4.5.8.0.1.00.00.00.00.00', 'TRANSFERÊNCIAS DE PESSOAS FÍSICAS - CONSOLIDAÇÃO', 'Registra as variações patrimoniais aumentativas decorrentes de contribuições e doações a governos e entidades da administração descentralizada realizadas por pessoas físicas. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9532, 1, '4.5.9.0.0.00.00.00.00.00', 'OUTRAS TRANSFERÊNCIAS E DELEGAÇÕES RECEBIDAS', 'Compreende as variações patrimoniais aumentativas decorrentes de demais transferências e delegações recebidas não compreendidas nas contas anteriores. ', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9533, 1, '4.5.9.0.1.00.00.00.00.00', 'OUTRAS TRANSFERÊNCIAS E DELEGAÇÕES RECEBIDAS - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais aumentativas decorrentes de demais transferências e delegações recebidas não compreendidas nas contas anteriores. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9534, 1, '4.6.0.0.0.00.00.00.00.00', 'VALORIZAÇÃO E GANHOS COM ATIVOS E DESINCORPORAÇÃO DE PASSIVOS', 'Compreende a variação patrimonial aumentativa com reavaliação e ganhos de ativos, bem como com a desincorporação de passivos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9535, 1, '4.6.1.1.1.00.00.00.00.00', 'REAVALIAÇÃO DE IMOBILIZADO - CONSOLIDAÇÃO', 'Compreende a variação patrimonial aumentativa relativa à adoção do valor de mercado ou de consenso entre as partes para bens do ativo imobilizado, quando esse for superior ao valor liquido contábil.Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9536, 1, '4.6.1.1.1.01.00.00.00.00', 'REAVALIAÇÃO DE BENS MÓVEIS', 'Compreende a variação patrimonial aumentativa relativa à adoção do valor de mercado ou de consenso entre as partes para bens móveis, quando esse for inferior ao valor liquido contábil.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9537, 1, '4.6.1.1.1.02.00.00.00.00', 'REAVALIAÇÃO DE BENS IMÓVEIS', 'Compreende a variação patrimonial aumentativa relativa à adoção do valor de mercado ou de consenso entre as partes para bens imóveis, quando esse for inferior ao valor liquido contábil.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9538, 1, '4.6.1.2.0.00.00.00.00.00', 'REAVALIAÇÃO DE INTANGÍVEIS', 'Compreende a variação patrimonial aumentativa relativa à adoção do valor de mercado ou de consenso entre as partes para ativos intangíveis, quando esse for superior ao valor liquido contábil.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9539, 1, '4.6.1.2.1.00.00.00.00.00', 'REAVALIAÇÃO DE INTANGÍVEIS - CONSOLIDAÇÃO', 'Compreende a variação patrimonial aumentativa relativa à adoção do valor de mercado ou de consenso entre as partes para ativos intangíveis, quando esse for superior ao valor liquido contábil. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9540, 1, '4.6.1.9.0.00.00.00.00.00', 'REAVALIAÇÃO DE OUTROS ATIVOS', 'Compreende a variação patrimonial aumentativa relativa à adoção do valor de mercado ou de consenso entre as partes para outros ativos, quando esse for superior ao valor liquido contábil.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9694, 1, '8.1.2.3.1.03.00.00.00.00', 'CONTRATOS DE ALUGUÉIS', 'Compreende contas relacionadas ao registro da execução dos valores do contrato de alugueis em que o poder público seja o locatário do bem.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9541, 1, '4.6.1.9.1.00.00.00.00.00', 'REAVALIAÇÃO DE OUTROS ATIVOS - CONSOLIDAÇÃO', 'Compreende a variação patrimonial aumentativa relativa à adoção do valor de mercado ou de consenso entre as partes para outros ativos, quando esse for superior ao valor liquido contábil. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9542, 1, '4.6.2.0.0.00.00.00.00.00', 'GANHOS COM ALIENAÇÃO', 'Compreende o ganho com alienação de ativos, ou seja, quando o valor alienado do ativo e maior que o seu valor contábil, de maneira que a diferença compreende o ganho.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9543, 1, '4.6.2.1.0.00.00.00.00.00', 'GANHOS COM ALIENAÇÃO DE INVESTIMENTOS', 'Compreende o ganho com alienação de investimentos, ou seja, quando o valor alienado do referido ativo e maior que o seu valor contábil, de maneira que a diferença compreende o ganho.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9544, 1, '4.6.2.1.1.00.00.00.00.00', 'GANHOS COM ALIENAÇÃO DE INVESTIMENTOS - CONSOLIDAÇÃO', 'Compreende o ganho com alienação de investimentos, ou seja, quando o valor alienado do referido ativo e maior que o seu valor contábil, de maneira que a diferença compreende o ganho. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9545, 1, '4.6.2.2.0.00.00.00.00.00', 'GANHOS COM ALIENAÇÃO DE IMOBILIZADO', 'Compreende o ganho com alienação de ativo imobilizado, ou seja, quando o valor alienado do referido ativo e maior que o seu valor contábil, de maneira que a diferença compreende o ganho.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9546, 1, '4.6.2.2.1.00.00.00.00.00', 'GANHOS COM ALIENAÇÃO DE IMOBILIZADO - CONSOLIDAÇÃO', 'Compreende o ganho com alienação de ativo imobilizado, ou seja, quando o valor alienado do referido ativo e maior que o seu valor contábil, de maneira que a diferença compreende o ganho. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9547, 1, '4.6.2.2.1.01.00.00.00.00', 'GANHO LÍQUIDO COM A ALIENAÇÃO DE BENS MÓVEIS', 'Compreende o ganho com alienação de ativo imobilizado, ou seja, quando o valor alienado do referido ativo e maior que o seu valor contábil, de maneira que a diferença compreende o ganho - Ganho Líquido com a Alienação de Bens Móveis.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9548, 1, '4.6.2.3.1.00.00.00.00.00', 'GANHOS COM ALIENAÇÃO DE INTANGÍVEIS - CONSOLIDAÇÃO', 'Compreende o ganho com alienação de ativos intangíveis, ou seja, quando o valor alienado do referido ativo e maior que o seu valor contábil, de maneira que a diferença compreende o ganho. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9549, 1, '4.6.2.9.0.00.00.00.00.00', 'GANHOS COM ALIENAÇÃO DE DEMAIS ATIVOS', 'Compreende o ganho com alienação de demais ativos, não discriminados nas categorias anteriores, incluindo os investimentos do RPPS, quando o valor alienado do referido ativo seja maior que o seu valor contábil, de maneira que a diferença compreenda o ganho.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9550, 1, '4.6.2.9.1.00.00.00.00.00', 'GANHOS COM ALIENAÇÃO DE DEMAIS ATIVOS - CONSOLIDAÇÃO', 'Registra o ganho com alienação de demais ativos, não discriminados nas categorias anteriores, incluindo os investimentos do RPPS, quando o valor alienado do referido ativo seja maior que o seu valor contábil, de maneira que a diferença compreenda o ganho. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9551, 1, '4.6.3.1.0.00.00.00.00.00', 'GANHOS COM INCORPORAÇÃO DE ATIVOS POR DESCOBERTAS', 'Compreende os ganhos com a incorporação de novos ativos descobertos, como por exemplo, descoberta de jazidas de recursos naturais.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9552, 1, '4.6.3.1.1.00.00.00.00.00', 'GANHOS COM INCORPORAÇÃO DE ATIVOS POR DESCOBERTAS - CONSOLIDAÇÃO', 'Registra os ganhos com a incorporação de novos ativos descobertos, como por exemplo, descoberta de jazidas de recursos naturais. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9553, 1, '4.6.3.2.0.00.00.00.00.00', 'GANHOS COM INCORPORAÇÃO DE ATIVOS POR NASCIMENTOS', 'Compreende os ganhos com a incorporação de semoventes nascidos, como por exemplo, nascimento de bovinos e aves.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9554, 1, '6.0.0.0.0.00.00.00.00.00', 'CONTROLES DA EXECUÇÃO DO PLANEJAMENTO E ORÇAMENTO', 'Compreende as contas com função de registra os atos e fatos ligados a execução orçamentária.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9555, 1, '4.6.3.2.1.00.00.00.00.00', 'GANHOS COM INCORPORAÇÃO DE ATIVOS POR NASCIMENTOS - CONSOLIDAÇÃO', 'Registra os ganhos com a incorporação de semoventes nascidos, como por exemplo, nascimento de bovinos e aves. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9556, 1, '4.6.3.3.0.00.00.00.00.00', 'GANHOS COM INCORPORAÇÃO DE ATIVOS APREENDIDOS', 'Compreende os ganhos  com a incorporação de ativos apreendidos, como por exemplo, os valores apreendidos associados ao trafico ilícito de entorpecentes e drogas afins.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9557, 1, '4.6.3.3.1.00.00.00.00.00', 'GANHOS COM INCORPORAÇÃO DE ATIVOS APREENDIDOS - CONSOLIDAÇÃO', 'Registra os ganhos  com a incorporação de ativos apreendidos, como por exemplo, os valores apreendidos associados ao trafico ilícito de entorpecentes e drogas afins. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9558, 1, '4.6.3.4.0.00.00.00.00.00', ' GANHOS COM INCORPORAÇÃO DE ATIVOS POR PRODUÇÃO', 'Compreende a contrapartida da incorporação de novos ativos por produção como, por exemplo, produção agrícola e laticínia.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9559, 1, '4.6.3.4.1.00.00.00.00.00', ' GANHOS COM INCORPORAÇÃO DE ATIVOS POR PRODUÇÃO - CONSOLIDAÇÃO', 'Registra a contrapartida da incorporação de novos ativos por produção como, por exemplo, produção agrícola e laticínia. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9560, 1, '4.6.3.9.0.00.00.00.00.00', 'OUTROS GANHOS COM INCORPORAÇÃO DE ATIVOS', 'Compreende a contrapartida da incorporação de outros novos ativos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9561, 1, '4.6.3.9.1.00.00.00.00.00', 'OUTROS GANHOS COM INCORPORAÇÃO DE ATIVOS - CONSOLIDAÇÃO', 'Registra a contrapartida da incorporação de outros novos ativos. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9562, 1, '4.6.4.0.0.00.00.00.00.00', 'GANHOS COM DESINCORPORAÇÃO DE PASSIVOS', 'Compreende a contrapartida da desincorporação de passivos, inclusive as baixas de passivo decorrentes do cancelamento de restos a pagar.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9563, 1, '4.6.4.0.1.00.00.00.00.00', 'GANHOS COM DESINCORPORAÇÃO DE PASSIVOS - CONSOLIDAÇÃO', 'Registra a contrapartida da desincorporação de passivos, inclusive as baixas de passivo decorrentes do cancelamento de restos a pagar. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9564, 1, '4.6.5.0.0.00.00.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL', 'Compreende a reversão de redução a valor recuperável previamente reconhecida como redutora do valor de ativos. ', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9565, 1, '4.6.5.1.0.00.00.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL DE INVESTIMENTOS', 'Compreende a variação patrimonial aumentativa com a reversão de redução a valor recuperável de um investimento.', 2, false, 0, 'N');
