insert into contabilidade.planocontadetalhe values (9567, 1, '4.6.5.1.2.00.00.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL DE INVESTIMENTOS - INTRA OFSS', 'Compreende a variação patrimonial aumentativa com a reversão de redução a valor recuperável de um investimento. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do ente.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9568, 1, '4.9.1.0.0.00.00.00.00.00', 'VARIAÇÃO PATRIMONIAL AUMENTATIVA A CLASSIFICAR', 'Compreende os recursos referentes à variação patrimonial aumentativa recebidas e não classificadas.', 2, false, 0, 'N');
