insert into contabilidade.planocontadetalhe values (9571, 1, '4.6.5.1.5.00.00.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL DE INVESTIMENTOS - INTER OFSS - MUNICÍPIO', 'Compreende a variação patrimonial aumentativa com a reversão de redução a valor recuperável de um investimento. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9572, 1, '4.6.5.2.0.00.00.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL DE IMOBILIZADO', 'Compreende a variação patrimonial aumentativa com a reversão de redução a valor recuperável de um ativo imobilizado.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9573, 1, '4.6.5.2.1.00.00.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL DE IMOBILIZADO - CONSOLIDAÇÃO', 'Compreende a variação patrimonial aumentativa com a reversão de redução a valor recuperável de um ativo imobilizado. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9574, 1, '4.6.5.2.1.01.00.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL DE BENS MÓVEIS', 'Compreende a variação patrimonial aumentativa com a reversão de redução nos benefícios econômicos futuros ou no potencial de serviços de bens móveis, que reflete um declínio na sua utilidade além do reconhecimento sistemático por meio da depreciação.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9575, 1, '4.6.5.2.1.02.00.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL DE BENS IMÓVEIS', 'Compreende a variação patrimonial aumentativa com a reversão de redução nos benefícios econômicos futuros ou no potencial de serviços de bens imóveis, que reflete um declínio na sua utilidade além do reconhecimento sistemático por meio da depreciação.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9576, 1, '4.6.5.3.0.00.00.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL DE INTANGÍVEIS', 'Compreende a variação patrimonial aumentativa com a reversão de redução a valor recuperável de um ativo intangível.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9577, 1, '4.6.5.3.1.00.00.00.00.00', 'REVERSÃO DE REDUÇÃO A VALOR RECUPERÁVEL DE INTANGÍVEIS - CONSOLIDAÇÃO', 'Compreende a variação patrimonial aumentativa com a reversão de redução a valor recuperável de um ativo intangível. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
