insert into contabilidade.planocontadetalhe values (9631, 1, '4.9.9.5.0.00.00.00.00.00', 'MULTAS ADMINISTRATIVAS', 'Compreende as variações patrimoniais aumentativas provenientes de penalidades pecuniárias decorrentes da inobservância de normas, e com rendimentos destinados a indenização pelo atraso no cumprimento da obrigação. Representa o resultado das aplicações impostas ao contribuinte faltoso, como sanção legal no campo tributário (impostos, taxas e contribuição de melhoria) e não-tributário (contribuições sociais e econômicas, patrimoniais, industriais, serviços e diversas) e de natureza administrativa, por infrações a regulamentos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9632, 1, '4.9.9.5.1.00.00.00.00.00', 'MULTAS ADMINISTRATIVAS - CONSOLIDAÇÃO', 'Registra as variações patrimoniais aumentativas provenientes de penalidades pecuniárias decorrentes da inobservância de normas, e com rendimentos destinados a indenização pelo atraso no cumprimento da obrigação. Representa o resultado das aplicações impostas ao contribuinte faltoso, como sanção legal no campo tributário (impostos, taxas e contribuição de melhoria) e não-tributário (contribuições sociais e econômicas, patrimoniais, industriais, serviços e diversas) e de natureza administrativa, por infrações a regulamentos. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9633, 1, '4.9.9.6.0.00.00.00.00.00', 'INDENIZAÇÕES E RESTITUIÇÕES', 'Compreende as variações patrimoniais aumentativas provenientes de indenizações e/ou restituições diversas.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9634, 1, '4.9.9.6.1.00.00.00.00.00', 'INDENIZAÇÕES E RESTITUIÇÕES - CONSOLIDAÇÃO', 'Compreende as variações patrimoniais aumentativas provenientes de indenizações e/ou restituições diversas. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9635, 1, '4.9.9.9.0.00.00.00.00.00', 'VARIAÇÕES PATRIMONIAIS AUMENTATIVAS DECORRENTES DE FATOS GERADORES DIVERSOS', 'Compreende as variações patrimoniais aumentativas decorrentes de fatos geradores diversos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9636, 1, '4.9.9.9.1.00.00.00.00.00', 'VARIAÇÕES PATRIMONIAIS AUMENTATIVAS DECORRENTES DE FATOS GERADORES DIVERSOS - CONSOLIDAÇÃO', 'Registra as variações patrimoniais aumentativas decorrentes de fatos geradores diversos.Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9637, 1, '5.2.1.2.1.03.00.00.00.00', '(-) PREVISÃO DE DEDUÇÕES DA RECEITA  POR TRANSFERÊNCIAS CONSTITUCIONAIS E LEGAIS', 'Registra a previsão de dedução da receita para abertura de créditos adicionais por motivo de reestimativa ou correção da receita por transferências constitucionais e legais.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9638, 1, '6.2.2.2.0.00.00.00.00.00', 'MOVIMENTAÇÃO DE CRÉDITOS CONCEDIDOS', 'Compreende o somatório dos valores dos créditos orçamentários concedidos através de destaque, provisão ou por fusão, cisão ou extinção de unidades.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9639, 1, '6.2.2.2.1.00.00.00.00.00', 'DESCENTRALIZAÇÃO INTERNA DE CRÉDITOS - PROVISÃO', 'Compreende os valores dos créditos descentralizados das unidades orçamentárias para as unidades administrativas sob sua jurisdição ou entre estas, no âmbito do próprio ministério, secretaria ou órgão equivalente, concedidos ao longo do exercício.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9640, 1, '6.2.2.2.1.09.00.00.00.00', 'ALTERAÇÃO DE CREDITOS MOVIMENTADOS        ', 'Registra o valor da variação de créditos orçamentários disponíveis por acréscimo ou redução do quadro de detalhamento de despesa, por UG pertencente ao órgão ou entidade da unidade orçamentária.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9644, 1, '6.2.2.2.2.09.00.00.00.00', 'ALTERAÇÃO DE CREDITOS MOVIMENTADOS        ', 'Compreende o valor da variação de créditos orçamentários disponíveis por acréscimo ou redução do quadro de detalhamento de despesa, por UG não pertencente ao órgão ou entidade da unidade orçamentária.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9645, 1, '6.2.2.2.9.00.00.00.00.00', 'OUTRAS DESCENTRALIZAÇÕES DE CRÉDITOS', 'Compreende as movimentações de créditos concedidos por cisão, fusão, extinção, compensação e outras transações.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9646, 1, '6.2.2.3.0.00.00.00.00.00', 'DETALHAMENTO DE CREDITO', 'Compreende o detalhamento das dotações orçamentárias relativas a cada programa de trabalho.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9647, 1, '6.2.2.9.0.00.00.00.00.00', 'OUTROS CONTROLES DA DESPESA ORÇAMENTÁRIA', 'Compreende o somatório dos valores executados das despesas pré-empenhadas e empenhadas por detalhamento específico.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9648, 1, '6.2.2.9.1.00.00.00.00.00', 'DESPESA PRE-EMPENHADA                          ', 'Compreende o somatório dos valores executados das despesas pré-empenhadas pela própria unidade gestora, transferidos ou recebidos por transferência, por detalhamento especifico e suas respectivas anulações.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9649, 1, '6.2.2.9.2.00.00.00.00.00', 'EMISSAO DE EMPENHO', 'Compreende o somatório dos valores executados das despesas empenhadas por detalhamento específico.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9650, 1, '6.2.2.9.2.01.00.00.00.00', 'EMPENHOS POR NOTA DE EMPENHO', 'Compreende o valor da emissão de documentos através dos quais são registrados os estágios das despesas orçamentárias realizadas pela administração pública.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9651, 1, '6.3.0.0.0.00.00.00.00.00', 'EXECUÇÃO DE RESTOS A PAGAR', 'Compreende o somatório dos valores relativos à transferência, liquidação e pagamento das despesas empenhadas e não pagas.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9652, 1, '6.3.1.0.0.00.00.00.00.00', 'EXECUÇÃO DE RP NÃO PROCESSADOS', 'Compreende o somatório dos valores relativos à transferência, liquidação e pagamento das despesas empenhadas, não liquidadas no exercício financeiro de sua inscrição e não pagas.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9653, 1, '6.3.1.7.0.00.00.00.00.00', 'RP NÃO PROCESSADOS - INSCRIÇÃO NO EXERCÍCIO', 'Compreende o valor das despesas empenhadas inscritas no exercício como restos a pagar não processados, a ser transferido no exercício seguinte para a conta 631100000 e 631200000.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9654, 1, '8.1.0.0.0.00.00.00.00.00', 'EXECUÇÃO DOS ATOS POTENCIAIS', 'Compreende contas relacionadas à execução de situações não compreendidas no patrimônio, mas que, direta ou indiretamente, possam vir à afeta-lo, exclusive as que dizem respeito a atos e fatos ligados a execução orçamentária e financeira e as contas com função precípua de controle.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9655, 1, '8.1.1.0.0.00.00.00.00.00', 'EXECUÇÃO DOS ATOS POTENCIAIS ATIVOS', 'Compreende a execução dos atos e fatos que possa vir a afetar o ativo da entidade governamental.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9656, 1, '8.1.1.1.0.00.00.00.00.00', 'EXECUÇÃO DE GARANTIAS E CONTRAGARANTIAS RECEBIDAS', 'Compreende as contas relacionadas ao registro da execução de avais, fianças e hipotecas recebidos no país e no exterior, bem como emolumentos consulares e outras garantias e contragarantias.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9657, 1, '8.1.1.1.1.00.00.00.00.00', 'EXECUÇÃO DE GARANTIAS E CONTRAGARANTIAS RECEBIDAS - CONSOLIDAÇÃO', 'Compreende as contas relacionadas ao registro da execução de avais, fianças e hipotecas recebidos no país e no exterior, bem como emolumentos consulares e outras garantias e contragarantias. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9658, 1, '8.1.1.1.1.01.00.00.00.00', 'EXECUÇÃO DE GARANTIAS RECEBIDAS NO PAÍS', 'Compreende as contas relacionadas ao registro da execução de avais, fianças e hipotecas recebidos no país, bem como emolumentos consulares e outras garantias e contragarantias.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9659, 1, '8.1.1.1.1.02.00.00.00.00', 'EXECUÇÃO DE GARANTIAS   RECEBIDAS NO EXTERIOR', 'Compreende contas relacionadas ao registro da execução de avais, fianças e hipotecas recebidas no exterior, bem como emolumentos consulares e outras garantias e contragarantias.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9660, 1, '8.1.1.1.1.03.00.00.00.00', 'EXECUÇÃO DE CONTRAGARANTIAS RECEBIDAS NO PAÍS', 'Compreende contas relacionadas ao registro da execução de avais, fianças e hipotecas recebidas no país bem como outras contragarantias.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9661, 1, '8.1.1.1.1.04.00.00.00.00', 'EXECUÇÃO DE CONTRAGARANTIAS RECEBIDAS NO EXTERIOR', 'Compreende contas relacionadas ao registro da execução de avais, fianças e hipotecas recebidas no exterior, bem como outras contragarantias.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9662, 1, '8.1.1.2.0.00.00.00.00.00', 'EXECUÇÃO DE DIREITOS CONVENIADOS E OUTROS INSTRUMENTOS CONGÊNERES', 'Compreende contas relacionadas ao registro, no convenente, da execução dos convênios firmados entre entidades, objetivando o cumprimento de finalidades comuns.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9663, 1, '8.1.1.2.1.00.00.00.00.00', 'EXECUÇÃO DE DIREITOS CONVENIADOS E OUTROS INSTRUMENTOS CONGÊNERES - CONSOLIDAÇÃO', 'Compreende contas relacionadas ao registro, no convenente, da execução dos convênios e outros instrumentos congêneres firmados entre entidades, objetivando o cumprimento de finalidades comuns. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9664, 1, '8.1.1.2.1.01.00.00.00.00', 'EXECUÇÃO DE CONVÊNIOS ', 'Compreende a execução dos valores de convênios para entrada de recursos firmado com outras entidades com a finalidade de atingir objetivos comuns.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9665, 1, '8.1.1.2.1.02.00.00.00.00', 'TERMO DE COOPERAÇÃO ', 'Compreende a execução dos valores de termo de cooperação para entrada de recursos firmados com outras entidades com a finalidade de atingir objetivos comuns.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9666, 1, '8.1.1.2.1.99.00.00.00.00', 'OUTROS INSTRUMENTOS CONGÊNERES ', 'Compreende a execução dos valores de outros instrumentos congêneres para entrada de recursos firmados com outras entidades com a finalidade de atingir objetivos comuns.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9667, 1, '8.1.1.3.0.00.00.00.00.00', 'EXECUÇÃO DE DIREITOS CONTRATUAIS', 'Compreende contas relacionadas ao registro da execução dos valores de direitos contratuais, quando a administração pública participa como contratada.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9668, 1, '8.1.2.3.1.05.00.00.00.00', 'CONTRATOS DE EMPRÉSTIMOS E FINANCIAMENTOS', 'Compreende valores relacionados a execução de contratos de obrigações da entidade pública com terceiros referente a empréstimos e financiamentos concedidos no exercício.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9695, 1, '8.1.2.3.1.04.00.00.00.00', 'CONTRATOS DE FORNECIMENTO DE BENS', 'Compreende contas relacionadas ao registro da execução dos valores do contrato de fornecimento de bens pela administração pública a terceiros.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9669, 1, '8.1.1.3.1.00.00.00.00.00', 'EXECUÇÃO DE DIREITOS CONTRATUAIS - CONSOLIDAÇÃO', 'Compreende contas relacionadas ao registro da execução dos valores de direitos contratuais, quando a administração pública participa como contratada. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9670, 1, '8.1.1.3.1.01.00.00.00.00', 'CONTRATOS DE SEGUROS', 'Compreende contas relacionas ao registro da execução dos valores do contrato de seguros em que a administração pública participa como contratada no instrumento contratual com terceiros.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9671, 1, '8.1.1.3.1.02.00.00.00.00', 'CONTRATOS DE SERVIÇOS', 'Compreende contas relacionadas ao registo da execução dos valores do contrato de serviços em que a administração pública seja a contratada no instrumento contratual com terceiros.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9672, 1, '8.1.1.3.1.03.00.00.00.00', 'CONTRATOS DE ALUGUÉIS', 'Compreende contas relacionadas ao registro da execução dos valores do contrato de aluguéis em que o poder público seja o locador do bem.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9673, 1, '8.1.1.3.1.04.00.00.00.00', 'CONTRATOS DE FORNECIMENTO DE BENS', 'Compreende contas relacionadas ao registro da execução dos valores do contrato de fornecimento de bens pela administração pública a terceiros.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9674, 1, '8.1.1.3.1.05.00.00.00.00', 'CONTRATOS DE EMPRÉSTIMOS E FINANCIAMENTOS', 'Compreende valores relacionados a execução de contratos de obrigações da entidade pública com terceiros referente a empréstimos e financiamentos contraídos no exercício.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9675, 1, '8.1.1.3.1.08.00.00.00.00', 'EXECUÇÃO DE CONTRATOS DE RATEIO DE CONSÓRCIOS PÚBLICOS', 'Compreende contas relacionadas ao registro dos valores de direitos contratuais decorrentes de Consórcios Públicos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9676, 1, '8.1.1.3.1.99.00.00.00.00', 'OUTROS DIREITOS CONTRATUAIS', 'Compreende a execução dos valores relativos a outros direitos contratuais.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9677, 1, '8.1.1.9.0.00.00.00.00.00', 'EXECUÇÃO DE OUTROS ATOS POTENCIAIS ATIVOS', 'Compreende a execução dos atos potenciais ativos não contemplados em contas especificas.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9678, 1, '8.1.1.9.1.00.00.00.00.00', 'EXECUÇÃO DE OUTROS ATOS POTENCIAIS ATIVOS - CONSOLIDAÇÃO', 'Registra a execução dos atos potenciais ativos não contemplados em contas especificas. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9679, 1, '8.1.2.0.0.00.00.00.00.00', 'EXECUÇÃO DOS ATOS POTENCIAIS PASSIVOS', 'Compreende a execução dos atos e fatos que possa vir a afetar o passivo da entidade governamental.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9680, 1, '8.1.2.1.0.00.00.00.00.00', 'EXECUÇÃO DE GARANTIAS E CONTRAGARANTIAS CONCEDIDAS', 'Compreende contas relacionadas ao registro da execução de avais, fianças e hipotecas concedidas no país e no exterior, bem como emolumentos consulares e outras garantias e contragarantias.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9681, 1, '8.1.2.1.1.00.00.00.00.00', 'EXECUÇÃO DE GARANTIAS E CONTRAGARANTIAS CONCEDIDAS - CONSOLIDAÇÃO', 'Compreende as contas relacionadas ao registro da execução de avais, fianças e hipotecas concedidos no país e no exterior, bem como emolumentos consulares e outras garantias e contragarantias. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9682, 1, '8.1.2.1.1.01.00.00.00.00', 'EXECUÇÃO DE GARANTIAS CONCEDIDAS NO PAÍS', 'Compreende as contas relacionadas ao registro da execução de avais, fianças e hipotecas concedidos no país, bem como emolumentos consulares e outras garantias e contragarantias.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9683, 1, '8.1.2.1.1.02.00.00.00.00', 'EXECUÇÃO DE GARANTIAS E  CONCEDIDAS NO EXTERIOR', 'Compreende contas relacionadas ao registro da execução de avais, fianças e hipotecas concedidos no exterior, bem como emolumentos consulares e outras garantias e contragarantias.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9684, 1, '8.1.2.1.1.03.00.00.00.00', 'EXECUÇÃO DE CONTRAGARANTIAS CONCEDIDAS NO PAÍS', 'Compreende as contas relacionadas ao registro da execução de avais, fianças e hipotecas concedidos no país, bem como outras contragarantias.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9685, 1, '8.1.2.1.1.04.00.00.00.00', 'EXECUÇÃO DE CONTRAGARANTIAS CONCEDIDAS NO EXTERIOR', 'Compreende as contas relacionadas ao registro da execução de avais, fianças e hipotecas concedidos no país, bem como outras contragarantias.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9686, 1, '8.1.2.2.0.00.00.00.00.00', 'EXECUÇÃO DE OBRIGAÇÕES CONVENIADAS E OUTROS INSTRUMENTOS CONGÊNERES', 'Compreende contas relacionadas ao registro, no concedente, da execução do valor dos convênios e outros instrumentos congêneres firmados entre entidades, objetivando o cumprimento de finalidades comuns.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9687, 1, '8.1.2.2.1.00.00.00.00.00', 'EXECUÇÃO DE OBRIGAÇÕES CONVENIADAS E OUTROS INSTRUMENTOS CONGÊNERES - CONSOLIDAÇÃO', 'Compreende contas relacionadas ao registro, no concedente, da execução dos convênios e outros instrumentos congêneres firmados entre entidades, objetivando o cumprimento de finalidades comuns. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9688, 1, '8.1.2.2.1.01.00.00.00.00', 'EXECUÇÃO DE CONVÊNIOS ', 'Compreende a execução dos valores de convênios para saída de recursos firmado com outras entidades com a finalidade de atingir objetivos comuns.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9689, 1, '8.1.2.2.1.99.00.00.00.00', 'OUTROS INSTRUMENTOS CONGÊNERES ', 'Registra a execução dos valores de outros instrumentos congêneres para saída de recursos firmados com outras entidades com a finalidade de atingir objetivos comuns.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9690, 1, '8.1.2.3.0.00.00.00.00.00', 'EXECUÇÃO DE OBRIGAÇÕES CONTRATUAIS', 'Compreende contas relacionadas ao registro da execução dos valores de obrigações contratuais, quando a administração pública participa como contratante.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9691, 1, '8.1.2.3.1.00.00.00.00.00', 'EXECUÇÃO DE OBRIGAÇÕES -CONSOLIDAÇÃO', 'Compreende contas relacionadas ao registro da execução dos valores de obrigações contratuais, quando a administração pública participa como contratante. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9692, 1, '8.1.2.3.1.01.00.00.00.00', 'CONTRATOS DE SEGUROS', 'Compreende contas relacionadas ao registro da execução dos valores do contrato de seguros em que a administração pública seja a contratante do instrumento contratual com terceiros.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9693, 1, '8.1.2.3.1.02.00.00.00.00', 'CONTRATOS DE SERVIÇOS', 'Compreende contas relacionadas ao registo da execução dos valores do contrato de serviços em que a administração pública seja a contratante.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9696, 1, '8.1.2.3.1.08.00.00.00.00', 'CONTRATOS DE PPP', 'Compreende o valor dos passivos decorrentes de contrato de PPP, incluindo o valor das obrigações contratuais com as contraprestações futuras, assim como os riscos não provisionados e outros passivos contingentes.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9697, 1, '8.1.2.3.1.09.00.00.00.00', 'EXECUÇÃO DE CONTRATOS DE RATEIO DE CONSÓRCIOS PÚBLICOS', 'Compreende contas relacionadas ao registro dos valores de obrigações contratuais decorrentes de Consórcios Públicos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9698, 1, '8.1.2.3.1.10.00.00.00.00', 'CONTRATOS DE PPP - DO ENTE FEDERADO, EXCETO ESTATAIS NÃO DEPENDENTES', 'Compreende a previsão de valor, por contrato, das despesas derivadas de PPP contratadas pelo ente da Federação excluídas as empresas estatais não dependentes. Deve abranger todas as despesas, correntes e de capital, devidadas do conjunto das parcerias contratadas, bem como as previsões de despesas de PPP para os próximos 9 anos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9699, 1, '8.1.2.3.1.11.00.00.00.00', 'CONTRATOS DE PPP - DAS ESTATAIS NÃO DEPENDENTES', 'Compreende o valor por contrato das despesas derivadas de PPP contratadas pelas empresas estatais não dependentes. Deve abranger todas as despesas, correntes e de capital, derivadas do conhunto das parcerias contratadas, bem como as previsões de despesas de PPP para os próximos 9 anos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9700, 1, '8.1.2.3.1.99.00.00.00.00', 'OUTRAS OBRIGAÇÕES CONTRATUAIS', 'Compreende a execução dos valores relativos a outras obrigações contratuais.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9701, 1, '8.1.2.9.0.00.00.00.00.00', 'EXECUÇÃO DE OUTROS ATOS POTENCIAIS PASSIVOS', 'Compreende a execução dos atos potenciais passivos não contemplados em contas especificas.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9702, 1, '8.1.2.9.1.00.00.00.00.00', 'EXECUÇÃO DE OUTROS ATOS POTENCIAIS PASSIVOS - CONSOLIDAÇÃO', 'Registra a execução dos atos potenciais passivos não contemplados em contas especificas. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9703, 1, '8.2.0.0.0.00.00.00.00.00', 'EXECUÇÃO DA ADMINISTRAÇÃO FINANCEIRA', 'Compreende as contas de registro da execução da programação financeira e de controle das disponibilidades.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9704, 1, '8.2.1.1.2.00.00.00.00.00', 'DISPONIBILIDADE POR DESTINAÇÃO DE RECURSOS COMPROMETIDA POR EMPENHO', 'Compreende o valor das disponibilidades de recursos comprometidas por ocasião do empenho e não liquidadas.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9705, 1, '8.2.1.1.3.00.00.00.00.00', 'DISPONIBILIDADE POR DESTINAÇÃO DE RECURSOS COMPROMETIDA POR LIQUIDAÇÃO E ENTRADAS COMPENSATÓRIAS', 'Compreende o valor das disponibilidades de recursos comprometidas por ocasião da liquidação e de entradas compensatórias e não pagas/devolvidas.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9706, 1, '8.2.1.2.0.00.00.00.00.00', 'EXECUÇÃO FINANCEIRA DO LIMITE DE RESTOS A PAGAR', 'Compreende as contas que registram a execução financeira do limite de restos a pagar.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9707, 1, '8.2.1.3.0.00.00.00.00.00', 'EXECUÇÃO DO RECURSO DIFERIDO POR DESTINAÇÃO', 'Compreende as contas que controlam a execução dos recursos diferidos. Recursos diferidos são as sobras de recursos financeiros ao final do exercício (recurso diferido), que deveriam ser devolvidas a conta única, porem, ao invés disso, essas sobras são liberadas para uso (apenas no exercício seguinte) através de descontos das transferências financeiras (cota, repasse e sub-repasse) do exercício seguinte.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9708, 1, '8.2.2.0.0.00.00.00.00.00', 'EXECUÇÃO DA PROGRAMAÇÃO FINANCEIRA', 'Compreende as contas que registram a execução das cotas, repasses e sub-repasses para atender a despesas orçamentárias, restos a pagar autorizados e demais dispêndios extra orçamentários.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9709, 1, '8.2.3.0.0.00.00.00.00.00', 'EXECUÇÃO DO LIMITE ORÇAMENTÁRIO', 'Compreende as contas que controlam a execução do limite de empenho e movimentação de créditos orçamentários, conforme estabelecidos em ato próprio dos poderes e ministério público.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9710, 1, '8.2.4.0.0.00.00.00.00.00', 'CONTROLES DA ARRECADAÇÃO', 'Compreende as contas que registram os valores discriminados da arrecadação da receita orçamentária, por meio de documentos de arrecadação como DARF, GRU, DAR, entre outros.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9711, 1, '8.3.0.0.0.00.00.00.00.00', 'EXECUÇÃO DA DÍVIDA ATIVA', 'Compreende as contas que controlam a execução dos créditos passiveis de serem encaminhados e inscritos em dívida ativa.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9712, 1, '8.3.1.0.0.00.00.00.00.00', 'EXECUÇÃO DO ENCAMINHAMENTO DE CRÉDITOS PARA INSCRIÇÃO EM DÍVIDA ATIVA', 'Compreende as contas que registram os valores a serem encaminhados e os já encaminhados para o órgão competente em inscrever em dívida ativa.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9713, 1, '8.3.1.1.0.00.00.00.00.00', 'CRÉDITOS A ENCAMINHAR PARA A DÍVIDA ATIVA', 'Compreende os valores a serem encaminhados para o órgão competente em inscrever em dívida ativa.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9714, 1, '8.3.1.1.1.00.00.00.00.00', 'CRÉDITOS A ENCAMINHAR PARA A DÍVIDA ATIVA TRIBUTÁRIA', 'Compreende os créditos a serem encaminhados para o órgão competente em inscrever em dívida ativa tributária.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9715, 1, '8.3.1.1.2.00.00.00.00.00', 'CRÉDITOS A ENCAMINHAR PARA A DÍVIDA ATIVA NÃO-TRIBUTÁRIA', 'Compreende os créditos a serem encaminhados para o órgão competente em inscrever em dívida ativa, referentes a créditos não-tributários.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9716, 1, '8.3.1.2.0.00.00.00.00.00', 'CRÉDITOS ENCAMINHADOS PARA A DÍVIDA ATIVA', 'Compreende os valores encaminhados para o órgão competente em inscrever em dívida ativa.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9717, 1, '8.3.1.2.1.00.00.00.00.00', 'CRÉDITOS ENCAMINHADOS PARA A DÍVIDA ATIVA TRIBUTÁRIA', 'Compreende os créditos referentes a tributos encaminhados para o órgão competente em inscrever em dívida ativa.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9718, 1, '8.3.1.2.2.00.00.00.00.00', 'CRÉDITOS ENCAMINHADOS PARA A DÍVIDA ATIVA NÃO TRIBUTÁRIA', 'Compreende os créditos de natureza não-tributária encaminhados para o órgão competente em inscrever em dívida ativa.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9719, 1, '8.3.1.3.0.00.00.00.00.00', 'CANCELAMENTO DE CRÉDITOS ENCAMINHADOS PARA A DÍVIDA ATIVA', 'Compreende o cancelamento dos valores indevidamente encaminhados para o órgão competente em inscrever em dívida ativa.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9720, 1, '8.3.1.3.1.00.00.00.00.00', 'CANCELAMENTO DE CRÉDITOS ENCAMINHADOS PARA A DÍVIDA ATIVA TRIBUTÁRIA', 'Compreende o cancelamento dos créditos de natureza tributária encaminhados para o órgão competente em inscrever em dívida ativa.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9721, 1, '8.3.1.3.2.00.00.00.00.00', 'CANCELAMENTO DE CRÉDITOS ENCAMINHADOS PARA A DÍVIDA ATIVA NÃO-TRIBUTÁRIA', 'Compreende o cancelamento dos créditos de natureza não-tributária encaminhados para o órgão competente em inscrever em dívida ativa.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9722, 1, '8.3.1.4.0.00.00.00.00.00', 'CRÉDITOS INSCRITOS EM DÍVIDA ATIVA', 'Compreende os valores encaminhados para o órgão competente em inscrever em dívida ativa que foram efetivamente inscritos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9723, 1, '8.3.1.4.1.00.00.00.00.00', 'CANCELAMENTO DE CRÉDITOS ENCAMINHADOS PARA A DÍVIDA ATIVA TRIBUTÁRIA', 'Compreende os valores dos créditos de natureza tributária encaminhados para o órgão competente em inscrever em dívida ativa que foram efetivamente inscritos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9724, 1, '8.3.1.4.2.00.00.00.00.00', 'CANCELAMENTO DE CRÉDITOS ENCAMINHADOS PARA A DÍVIDA ATIVA NÃO-TRIBUTÁRIA', 'Compreende os valores  dos créditos de natureza não-tributária encaminhados para o órgão competente em inscrever em dívida ativa que foram efetivamente inscritos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9725, 1, '8.3.2.0.0.00.00.00.00.00', 'EXECUÇÃO DA INSCRIÇÃO DE CRÉDITOS EM DÍVIDA ATIVA', 'Compreende as contas que registram os valores a serem inscritos em dívida ativa pelo o órgão competente em inscrever em dívida ativa.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9726, 1, '8.3.2.1.0.00.00.00.00.00', 'CRÉDITOS A INSCREVER EM DÍVIDA ATIVA', 'Compreende os valores a serem inscritos em dívida ativa pelo o órgão competente em inscrever em dívida ativa.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9727, 1, '8.3.2.2.0.00.00.00.00.00', 'CRÉDITOS A INSCREVER EM DÍVIDA ATIVA DEVOLVIDOS', 'Compreende os valores a serem inscritos em dívida ativa que foram devolvidos pelo órgão competente, por incorreções na formalização do processo de encaminhamento.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9728, 1, '8.3.2.3.0.00.00.00.00.00', 'CRÉDITOS INSCRITOS EM DÍVIDA ATIVA A RECEBER', 'Compreende os valores inscritos em dívida ativa pelo o órgão competente em inscrever em dívida ativa.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9729, 1, '8.3.2.3.1.00.00.00.00.00', 'CRÉDITOS INSCRITOS EM DÍVIDA ATIVA TRIBUTÁRIA A RECEBER', 'Registra os créditos inscritos em dívida ativa tributária pelo órgão competente em inscrever em dívida ativa.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9730, 1, '8.3.2.3.2.00.00.00.00.00', 'CRÉDITOS INSCRITOS EM DÍVIDA ATIVA NÃO-TRIBUTÁRIA A RECEBER', 'Compreende os créditos a receber, inscritos em dívida ativa não-tributária pelo órgão competente em inscrever em dívida ativa, em fase administrativa de cobrança.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9731, 1, '8.3.2.4.0.00.00.00.00.00', 'CRÉDITOS INSCRITOS EM DÍVIDA ATIVA RECEBIDOS', 'Compreende os valores recebidos relativos aos créditos anteriormente inscritos em dívida ativa.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9732, 1, '8.3.2.4.1.00.00.00.00.00', 'RECEBIMENTO DE CRÉDITOS INSCRITOS EM DÍVIDA ATIVA TRIBUTÁRIA ', 'Compreende o recebimento dos valores referentes aos créditos inscritos em dívida ativa tributária.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9733, 1, '8.3.2.4.2.00.00.00.00.00', 'RECEBIMENTOS DE CRÉDITOS INSCRITOS EM DÍVIDA ATIVA NÃO-TRIBUTÁRIA ', 'Compreende o recebimento dos valores referentes aos créditos inscritos em dívida ativa não-tributária.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9734, 1, '8.3.2.5.0.00.00.00.00.00', 'BAIXA DE CRÉDITOS INSCRITOS EM DÍVIDA ATIVA', 'Compreende os valores relativos às baixas de créditos inscritos em dívida ativa.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9735, 1, '8.3.2.5.1.00.00.00.00.00', 'BAIXAS DE CRÉDITOS INSCRITOS EM DÍVIDA ATIVA TRIBUTÁRIA', 'Compreende as baixas de créditos inscritos em dívida ativa tributária.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9736, 1, '8.3.2.5.2.00.00.00.00.00', 'BAIXAS DE CRÉDITOS INSCRITOS EM DÍVIDA ATIVA NÃO-TRIBUTÁRIA', 'Compreende as baixas de créditos inscritos em dívida ativa não-tributária.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9737, 1, '8.4.0.0.0.00.00.00.00.00', 'EXECUÇÃO DOS RISCOS FISCAIS', 'Compreende as contas que controlam a execução dos riscos fiscais que não preencham os requisitos para reconhecimento como passivo, conforme identificados no anexo de riscos fiscais da lei de diretrizes orçamentárias.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9738, 1, '8.4.1.0.0.00.00.00.00.00', 'EXECUÇÃO DE PASSIVOS CONTINGENTES', 'Compreende as contas que controlam a execução dos riscos fiscais que não preencham os requisitos para reconhecimento como passivo, classificados como passivos contingentes, conforme identificados no anexo de riscos fiscais da lei de diretrizes orçamentárias.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9739, 1, '8.4.1.1.0.00.00.00.00.00', 'PASSIVOS CONTINGENTES PREVISTOS', 'Compreende a previsão dos riscos fiscais classificados como Passivos Contingentes.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9740, 1, '8.4.1.2.0.00.00.00.00.00', 'PASSIVOS CONTINGENTES CONFIRMADOS', 'Compreende a confirmação da previsão dos riscos fiscais classificados como Passivos Contingentes.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9741, 1, '8.4.2.0.0.00.00.00.00.00', 'EXECUÇÃO DOS DEMAIS RISCOS FISCAIS', 'Compreende as contas que controlam a execução dos riscos fiscais que não preencham os requisitos para reconhecimento como passivo, não classificados como passivos contingentes, conforme identificados no anexo de riscos fiscais da lei de diretrizes orçamentárias.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9742, 1, '8.4.2.1.0.00.00.00.00.00', 'DEMAIS RISCOS FISCAIS PREVISTOS ', 'Compreende a previsão dos riscos fiscais não classificados como passivos contingentes.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9743, 1, '8.4.2.2.0.00.00.00.00.00', 'DEMAIS RISCOS FISCAIS CONFIRMADOS', 'Compreende a confirmação da previsão dos riscos fiscais não classificados como passivos contingentes.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9744, 1, '8.5.0.0.0.00.00.00.00.00', 'EXECUÇÃO DOS CONSÓRCIOS PÚBLICOS', 'Compreende as contas que controlam a execução dos consórcios públicos (do ente consorciado e/ou do próprio consórcio), incluindo os controles do contrato de rateio, controle da prestação de contas, bem como as informações que serão consolidadas no ente consorciado para fins de elaboração dos demonstrativos dos consórcios, conforme Portaria STN 72/2012.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9745, 1, '8.5.2.0.0.00.00.00.00.00', 'EXECUÇÃO DA PRESTAÇÃO DE CONTAS DE CONSÓRCIO PÚBLICO', 'Compreende contas relacionadas ao registro da execução do controle da prestação de contas referentes aos valores transferidos dos Consórcios Públicos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9746, 1, '2.3.7.1.2.04.00.00.00.00', 'SUPERÁVITS OU DÉFICITS RESULTANTES DE EXTINÇÃO, FUSÃO E CISÃO', 'Registra o resultado apurado por extinção, cisão ou fusão de unidade da administração direta, autarquias, fundações e fundos, ocorrida durante o exercício.', 3, true, 2, 'P');
insert into contabilidade.planocontadetalhe values (9747, 1, '8.5.3.0.0.00.00.00.00.00', 'CONSOLIDAÇÃO DA EXECUÇÃO DO CONSÓRCIO', 'Compreende as informações referentes aos Consórcios Públicos, atribuídas ao ente consorciado com base no contrato de rateio,que serão enviadas pelo consórcio para os entes consorciados para fins de elaboração dos demonstrativos fiscais ( Saúde, pessoal, educação e disponibilidade de caixa), em atendimento a Portaria STN n.º 72/2012. Conta para uso do ente consorciado.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9748, 1, '8.5.3.2.0.00.00.00.00.00', 'DESPESAS EXECUTADAS EM CONSÓRCIOS PÚBLICOS', 'Compreende as despesas executadas em consórcios públicos atribuídas ao ente consorciado com base no contrato de rateio.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9749, 1, '8.5.3.3.0.00.00.00.00.00', 'EXECUÇÃO DE RP NÃO PROCESSADOS EM CONSÓRCIOS PÚBLICOS', 'Compreende o somatório dos valores relativos à transferência, liquidação e pagamento das despesas empenhadas, não liquidadas no exercício financeiro de sua inscrição e não pagas, em consórcios públicos atribuídos ao ente consorciado com base no contrato de rateio.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9750, 1, '8.5.3.4.0.00.00.00.00.00', 'EXECUÇÃO DE RP PROCESSADOS EM CONSÓRCIOS PÚBLICOS', 'Compreende o somatório dos valores relativos à transferência, liquidação e pagamento das despesas empenhadas, liquidadas no exercício financeiro de sua inscrição e não pagas, em consórcios públicos atribuídos ao ente consorciado com base no contrato de rateio.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9751, 1, '8.8.0.0.0.00.00.00.00.00', 'APURAÇÃO DE CUSTOS', 'Compreende as contas que controlam a execução dos custos dos bens e serviços produzidos.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9752, 1, '8.9.0.0.0.00.00.00.00.00', 'OUTROS CONTROLES', 'Compreende as contas de controles da execução não especificados anteriormente nos grupos dessa classe.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9753, 1, '8.9.1.0.0.00.00.00.00.00', 'EXECUÇÃO DE RESPONSABILIDADE POR VALORES, TÍTULOS E BENS', 'Compreende as contas relacionadas ao registro das responsabilidades por valores, títulos e bens.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9754, 1, '8.9.1.1.0.00.00.00.00.00', 'EXECUÇÃO DE RESPONSABILIDADE COM TERCEIROS POR VALORES, TÍTULOS E BENS', 'Compreende as contas relacionadas ao registro da responsabilidade da administração pública com terceiros por títulos, valores e bens.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9755, 1, '8.9.1.2.0.00.00.00.00.00', 'EXECUÇÃO DE RESPONSABILIDADE DE TERCEIROS POR VALORES, TÍTULOS E BENS', 'Compreende contas relacionadas ao registro da responsabilidade de terceiros com a administração pública por títulos, valores e bens.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9756, 1, '8.9.1.2.1.00.00.00.00.00', 'EXECUÇÃO DE ADIANTAMENTOS/SUPRIMENTOS DE FUNDOS CONCEDIDOS', 'Compreende os valores concedidos a servidor responsável para atender despesas que não possam subordinar-se ao processo normal de aplicação, até a sua prestação de contas.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9757, 1, '8.9.1.2.2.00.00.00.00.00', 'ATIVOS DE PPP CONTABILIZADOS NO ENTE', 'Compreende o valor dos ativos produzidos por meio de Parcerias Público Privadas contabilizados no ente.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9758, 1, '8.9.2.0.0.00.00.00.00.00', 'DIVERSOS RESPONSÁVEIS EM APURAÇÃO', 'Compreende as responsabilidades em fase de apuração decorrentes de atos praticados por gestores, servidores ou terceiros que possam resultarem prejuízos para a fazenda nacional.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9759, 1, '8.9.2.9.0.00.00.00.00.00', 'OUTRAS RESPONSABILIDADES EM APURAÇÃO', 'Compreende outras responsabilidades em apuração.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9760, 1, '8.9.2.9.1.00.00.00.00.00', 'MULTAS E JUROS', 'Compreende os valores referentes a multas e juros pagos pelo órgão, porém de responsabilidade de servidores e que estejam em fase de apuração.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9761, 1, '8.9.3.0.0.00.00.00.00.00', 'CONTROLE DE OPERAÇÕES DE CRÉDITO PARA FINS DA LRF', 'Compreende as contas relacionadas ao fluxo de operações de crédito no exercício financeiro para fins de preenchimento do Demonstrativo previsto no artigo 55, I, d da LRF.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9762, 1, '8.9.3.1.0.00.00.00.00.00', 'OPERAÇÕES CONTRATUAIS INTERNAS SUJEITAS AO LIMITE', 'Compreende o valor das operações de crédito contratuais internas.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9763, 1, '8.9.3.2.0.00.00.00.00.00', 'OPERAÇÕES CONTRATUAIS EXTERNAS SUJEITAS AO LIMITE', 'Compreende o valor das operações de crédito contratuais externas.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9764, 1, '8.9.3.3.0.00.00.00.00.00', 'OUTRAS OPERAÇÕES QUE INTEGRAM A DÍVIDA CONSOLIDADA', 'Compreende o valor de outras operações que  integram o conceito de dívida consolidada.', 2, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9765, 1, '8.9.3.3.1.00.00.00.00.00', 'PARCELAMENTO DE DÍVIDAS', 'Compreende os montantes referentes ao parcelamento de dívidas.', 2, false, 0, 'N');
