insert into contabilidade.planocontadetalhe values (9818, 1, '6.2.1.8.0.00.00.00.00.00', 'CORREÇÃO DE DIFERENÇAS RESULTANTES DE VARIAÇÃO CAMBIAL', 'Compreende valor para equilíbrio dos saldos das contas, quando estes apresentarem desequilíbrio decorrente de variação cambial. Conta de uso exclusivo pela União.', 3, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (9819, 1, '6.2.2.8.0.00.00.00.00.00', 'CORREÇÃO DE DIFERENÇAS RESULTANTES DE VARIAÇÃO CAMBIAL', 'Compreende valor para equilíbrio dos saldos das contas, quando estes apresentarem desequilíbrio decorrente de variação cambial. Conta de uso exclusivo pela União.', 3, true, 4, 'N');
insert into contabilidade.planocontadetalhe values (9820, 1, '8.2.1.1.1.01.00.00.00.00', 'RECURSOS DISPONÍVEIS PARA O EXERCÍCIO', 'Registra o valor das disponibilidades de recursos a utilizar, incluindo os recursos provenientes de exercícios anteriores  e legalmente autorizados para utilização no exercício financeiro.', 3, true, 1, 'N');
insert into contabilidade.planocontadetalhe values (9821, 1, '2.3.4.0.0.00.00.00.00.00', 'AJUSTES DE AVALIAÇÃO PATRIMONIAL', 'Compreende as contrapartidas de aumentos ou diminuições de valor atribuídos a elementos do ativo e do passivo em decorrência da sua avaliação a valor justo, nos casos previstos pela lei 6.404/76 ou em normas expedidas pela comissão de valores mobiliários, enquanto não computadas no resultado do exercício em obediência ao regime de competência.', 3, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9822, 1, '2.3.4.1.0.00.00.00.00.00', 'AJUSTES DE AVALIAÇÃO PATRIMONIAL DE ATIVOS', 'Compreende as contrapartidas de aumentos ou diminuições de valor atribuídos a elementos do ativo em decorrência da sua avaliação a valor justo, nos casos previstos pela lei 6.404/76 ou em normas expedidas pela comissão de valores mobiliários, enquanto não computadas no resultado do exercício.', 3, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9823, 1, '2.3.4.1.1.00.00.00.00.00', 'AJUSTES DE AVALIAÇÃO PATRIMONIAL DE ATIVOS - CONSOLIDAÇÃO', 'Compreende as contrapartidas de aumentos ou diminuições de valor atribuídos a elementos do ativo em decorrência da sua avaliação a valor justo, nos casos previstos pela lei 6.404/76 ou em normas expedidas pela comissão de valores mobiliários, enquanto não computadas no resultado do exercício. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 3, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9824, 1, '2.3.4.2.0.00.00.00.00.00', 'AJUSTES DE AVALIAÇÃO PATRIMONIAL DE PASSIVOS', 'Compreende as contrapartidas de aumentos ou diminuições de valor atribuídos a elementos do passivo em decorrência da sua avaliação a valor justo, nos casos previstos pela lei 6.404/76 ou em normas expedidas pela comissão de valores mobiliários, enquanto não computadas no resultado do exercício.', 3, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9825, 1, '2.3.4.2.1.00.00.00.00.00', 'AJUSTES DE AVALIAÇÃO PATRIMONIAL DE PASSIVOS - CONSOLIDAÇÃO', 'Compreende as contrapartidas de aumentos ou diminuições de valor atribuídos a elementos do passivo em decorrência da sua avaliação a valor justo, nos casos previstos pela lei 6.404/76 ou em normas expedidas pela comissão de valores mobiliários, enquanto não computadas no resultado do exercício. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 3, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9826, 1, '2.3.7.0.0.00.00.00.00.00', 'RESULTADOS ACUMULADOS', 'Compreende o saldo remanescente dos lucros ou prejuízos líquidos das empresas e os superávits ou déficits acumulados da administração direta, autarquias, fundações e fundos.', 3, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9827, 1, '2.3.7.1.0.00.00.00.00.00', 'SUPERÁVITS OU DÉFICITS ACUMULADOS', 'Compreendem os superávits ou déficits acumulados da administração direta, autarquias, fundações e fundos.', 3, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9828, 1, '2.3.7.1.1.00.00.00.00.00', 'SUPERÁVITS OU DÉFICITS ACUMULADOS - CONSOLIDAÇÃO', 'Compreendem os superávits ou déficits acumulados da administração direta, autarquias, fundações e fundos. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 3, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9829, 1, '2.3.7.1.2.00.00.00.00.00', 'SUPERÁVITS OU DÉFICITS ACUMULADOS - INTRA OFSS', 'Compreendem os superávits ou déficits acumulados da administração direta, autarquias, fundações e fundos. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do ente.', 3, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9830, 1, '2.3.7.1.3.00.00.00.00.00', 'SUPERÁVITS OU DÉFICITS ACUMULADOS - INTER OFSS - UNIÃO', 'Compreendem os superávits ou déficits acumulados da administração direta, autarquias, fundações e fundos. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 3, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9831, 1, '2.3.7.1.4.00.00.00.00.00', 'SUPERÁVITS OU DÉFICITS ACUMULADOS - INTER OFSS - ESTADO', 'Compreendem os superávits ou déficits acumulados da administração direta, autarquias, fundações e fundos. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) de entes públicos distintos, para permitir a consolidação nacional realizada pelo Poder Executivo da União. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 3, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9832, 1, '2.3.7.1.5.00.00.00.00.00', 'SUPERÁVITS OU DÉFICITS ACUMULADOS - INTER OFSS - MUNICÍPIO', 'Compreendem os superávits ou déficits acumulados da administração direta, autarquias, fundações e fundos. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 3, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9833, 1, '2.3.7.2.0.00.00.00.00.00', 'LUCROS E PREJUÍZOS ACUMULADOS', 'Compreende o saldo remanescente dos lucros ou prejuízos líquidos das empresas.', 3, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9834, 1, '2.3.7.2.1.00.00.00.00.00', 'LUCROS E PREJUÍZOS ACUMULADOS - CONSOLIDAÇÃO', 'Compreende o saldo remanescente dos lucros ou prejuízos líquidos das empresas. Compreende os saldos que não serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS).', 3, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9835, 1, '2.3.7.2.2.00.00.00.00.00', 'LUCROS E PREJUÍZOS ACUMULADOS - INTRA OFSS', 'Compreende o saldo remanescente dos lucros ou prejuízos líquidos das empresas. Compreende os saldos que serão excluídos nos demonstrativos consolidados do orçamento fiscal e da seguridade social (OFSS) do ente.', 3, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9836, 1, '2.3.7.2.3.00.00.00.00.00', 'LUCROS E PREJUÍZOS ACUMULADOS - INTER OFSS - UNIÃO', 'Compreende o saldo remanescente dos lucros ou prejuízos líquidos das empresas. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e a União.', 3, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9837, 1, '2.3.7.2.4.00.00.00.00.00', 'LUCROS E PREJUÍZOS ACUMULADOS - INTER OFSS - ESTADO', 'Compreende o saldo remanescente dos lucros ou prejuízos líquidos das empresas. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um estado.', 3, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9838, 1, '2.3.7.2.5.00.00.00.00.00', 'LUCROS E PREJUÍZOS ACUMULADOS - INTER OFSS - MUNICÍPIO', 'Compreende o saldo remanescente dos lucros ou prejuízos líquidos das empresas. Compreende os saldos que serão excluídos nos demonstrativos consolidados do Orçamento Fiscal e da Seguridade Social (OFSS) de entes públicos distintos, resultantes das transações entre o ente e um município.', 3, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9839, 1, '5.2.1.2.0.00.00.00.00.00', 'ALTERAÇÃO DA PREVISÃO DA RECEITA', 'Compreende o valor dos créditos previstos após a aprovação do orçamento independente da autorização já concedida na lei orçamentária para abertura de credito suplementar.', 3, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9840, 1, '5.2.2.1.9.00.00.00.00.00', 'CANCELAMENTO/REMANEJAMENTO DE DOTAÇÃO', 'Compreende o somatório dos valores relativos aos créditos inicial, suplementar, especial e extraordinário cancelados ou remanejados, em casos regularmente previstos.', 3, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9841, 1, '8.2.1.0.0.00.00.00.00.00', 'EXECUÇÃO DAS DISPONIBILIDADES POR DESTINAÇÃO', 'Compreende as contas que registram a execução dos controles das disponibilidades por destinação de recursos.', 3, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9842, 1, '8.2.1.1.0.00.00.00.00.00', 'EXECUÇÃO DA DISPONIBILIDADE DE RECURSOS', 'Compreende as contas que registram a execução das disponibilidades de recursos a utilizar, comprometidas e utilizadas.', 3, false, 0, 'N');
insert into contabilidade.planocontadetalhe values (9843, 1, '8.2.1.1.1.00.00.00.00.00', 'DISPONIBILIDADE POR DESTINAÇÃO DE RECURSOS', 'Compreende o valor das disponibilidades de recursos a utilizar.', 3, false, 0, 'N');
