    if v_juronaultima is true then
     v_comando = v_comando || '                                     and juro is false                                                                                     \n';
    end if;
    v_comando = v_comando || '                                    group by arrecad_parc_rec.numpre,                                                                       \n';
    v_comando = v_comando || '                                             arrecad_parc_rec.numpar,                                                                       \n';
